_soviez_log_level_num() {
  case "$(printf '%s' "${1:-info}" | tr '[:upper:]' '[:lower:]')" in
    debug) echo 10 ;;
    info) echo 20 ;;
    warn|warning) echo 30 ;;
    error) echo 40 ;;
    *) echo 20 ;;
  esac
}

_soviez_log_should() {
  local want="$1"
  local cur
  cur="$(_soviez_log_level_num "$SOVIEZ_LOG_LEVEL")"
  [[ "$want" -ge "$cur" ]]
}

_soviez_log_emit() {
