  else
    printf '[%s] %s\n' "$level" "$redacted" >&2
  fi
}

soviez_log_debug() {
  if _soviez_log_should 10; then
    _soviez_log_emit debug "$*"
  fi
}

soviez_log_info() {
  if _soviez_log_should 20; then
    _soviez_log_emit info "$*"
  fi
}

soviez_log_warn() {
