# --- begin security/test_flag_policy.sh ---
# shellcheck shell=bash
# Phase 24 — test-flag quarantine / disposable-env detection.

soviez_security_cert_env() {
  export SOVIEZ_PHASE24_CERTIFICATION="${SOVIEZ_PHASE24_CERTIFICATION:-0}"
  export SOVIEZ_PHASE24_REQUIRE_STRICT_SIGNATURES="${SOVIEZ_PHASE24_REQUIRE_STRICT_SIGNATURES:-1}"
  export SOVIEZ_PHASE24_REQUIRE_SECRET_SCAN="${SOVIEZ_PHASE24_REQUIRE_SECRET_SCAN:-1}"
  export SOVIEZ_PHASE24_REQUIRE_REGISTRY_CLEAN="${SOVIEZ_PHASE24_REQUIRE_REGISTRY_CLEAN:-1}"
  export SOVIEZ_PHASE24_REQUIRE_REPLAY_TESTS="${SOVIEZ_PHASE24_REQUIRE_REPLAY_TESTS:-1}"
  # Certification defaults forbid test bypass; non-cert keeps 0 so disposable unit tests work.
  if [[ "${SOVIEZ_PHASE24_CERTIFICATION}" == "1" ]]; then
    export SOVIEZ_PHASE24_FORBID_TEST_BYPASS="${SOVIEZ_PHASE24_FORBID_TEST_BYPASS:-1}"
  else
    export SOVIEZ_PHASE24_FORBID_TEST_BYPASS="${SOVIEZ_PHASE24_FORBID_TEST_BYPASS:-0}"
  fi
  export SOVIEZ_PHASE24_FORBID_PRIVATE_KEYS_IN_DIST="${SOVIEZ_PHASE24_FORBID_PRIVATE_KEYS_IN_DIST:-1}"
  export SOVIEZ_PHASE24_FORBID_SERVICE_ROLE_IN_DIST="${SOVIEZ_PHASE24_FORBID_SERVICE_ROLE_IN_DIST:-1}"
  export SOVIEZ_PHASE24_FORBID_MATERIAL_SKIPS="${SOVIEZ_PHASE24_FORBID_MATERIAL_SKIPS:-1}"
  # Production default: signature verification is fail-closed.
  export SOVIEZ_UPDATE_STRICT_SIG="${SOVIEZ_UPDATE_STRICT_SIG:-1}"
}

soviez_security_is_disposable_env() {
  [[ "${SOVIEZ_DISPOSABLE_ENV:-0}" == "1" ]] && return 0
  [[ "${SOVIEZ_PHASE23_CERTIFICATION:-0}" == "1" ]] && return 0
  [[ "${SOVIEZ_PHASE24_CERTIFICATION:-0}" == "1" ]] && return 0
  local root="${SOVIEZ_ROOT:-}"
  [[ -n "$root" ]] || return 1
  case "$root" in
    /tmp/*|/private/tmp/*|/var/folders/*|*/.tmp/*|*/.phase23-cert-tmp/*|*/.phase24-cert-tmp/*)
      return 0 ;;
  esac
  case "$root" in
    *soviez-test*|*soviez-p1*|*soviez-p2*|*p15-final*|*p23-*|*p24-*)
      return 0 ;;
  esac
  return 1
}

soviez_security_is_production_target() {
  [[ "${SOVIEZ_SECURITY_FORCE_PRODUCTION:-0}" == "1" ]] && return 0
  # Explicit permanent customer marker
  [[ "${SOVIEZ_PRODUCTION_RUNTIME:-0}" == "1" ]] && return 0
  # Real docker update without test mode = production-like
  if [[ "${SOVIEZ_UPDATE_REAL_DOCKER:-0}" == "1" && "${SOVIEZ_TEST_MODE:-0}" != "1" ]]; then
    return 0
  fi
  return 1
}

# Test/cert bypass for fixture signatures & unsigned offline fixtures.
# Requires ALL: TEST_MODE + disposable env + not production target.
# Additionally denied when PHASE24_FORBID_TEST_BYPASS=1.
soviez_security_test_bypass_allowed() {
  if [[ "${SOVIEZ_PHASE24_FORBID_TEST_BYPASS:-0}" == "1" ]]; then
    return 1
  fi
  [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]] || return 1
  soviez_security_is_disposable_env || return 1
  if soviez_security_is_production_target; then
    return 1
  fi
  return 0
}

soviez_security_assert_test_bypass_or_die() {
  local why="${1:-test bypass}"
  if soviez_security_test_bypass_allowed; then
    return 0
  fi
  soviez_security_die SECURITY_TEST_BYPASS_DENIED "$why"
}

soviez_security_is_fake_signature() {
  local sig="${1:-}"
  case "$sig" in
    ok|valid|fixture|tampered|invalid|phase23-preverified|sig-final|sig|fixture-token)
      return 0 ;;
  esac
  # Short non-base64url fixture tokens
  if [[ ${#sig} -lt 16 && "$sig" != *"="* ]]; then
    case "$sig" in
      *[!A-Za-z0-9_-]*) ;;
      *)
        # still allow short hex digests? No — treat short alphanumeric as suspicious fixture
        [[ "$sig" =~ ^[A-Za-z0-9_-]+$ ]] && [[ ${#sig} -le 24 ]] && return 0
        ;;
    esac
  fi
  return 1
}

# --- end security/test_flag_policy.sh ---

# --- begin security/signatures.sh ---
# shellcheck shell=bash
# Phase 24 — signature enforcement helpers (adapters over existing verifiers).

soviez_security_require_signed_manifest() {
  local signed="${1:-}" signature="${2:-}" context="${3:-release}"
  if [[ "$signed" != "true" && "$signed" != "True" ]]; then
    if declare -F soviez_update_die >/dev/null 2>&1; then
      soviez_update_die UPDATE_RELEASE_UNSIGNED "Unsigned $context refused"
    fi
    soviez_security_die SECURITY_UNSIGNED_UPDATE_DENIED "Unsigned $context refused"
  fi
  if [[ -z "$signature" || "$signature" == "null" ]]; then
    if declare -F soviez_update_die >/dev/null 2>&1; then
      soviez_update_die UPDATE_RELEASE_SIGNATURE_INVALID "Missing $context signature"
    fi
    soviez_security_die SECURITY_SIGNATURE_REQUIRED "Missing $context signature"
  fi
  # Explicitly invalid / tampered markers are always fatal (even under test bypass).
  case "$signature" in
    invalid|tampered|INVALID|TAMPERED)
      if declare -F soviez_update_die >/dev/null 2>&1; then
        soviez_update_die UPDATE_RELEASE_SIGNATURE_INVALID "Release signature invalid"
      fi
      soviez_security_die SECURITY_SIGNATURE_INVALID "signature invalid/tampered"
      ;;
  esac
  if soviez_security_is_fake_signature "$signature"; then
    if soviez_security_test_bypass_allowed; then
      return 0
    fi
    if declare -F soviez_update_die >/dev/null 2>&1; then
      soviez_update_die UPDATE_RELEASE_SIGNATURE_INVALID "Non-cryptographic $context signature forbidden"
    fi
    soviez_security_die SECURITY_FAKE_SIGNATURE_FORBIDDEN "Non-cryptographic $context signature forbidden"
  fi
  return 0
}

soviez_security_assert_manifest_crypto() {
  local manifest="$1"
  # When a real verifier exists, failure is always fatal in production.
  if ! declare -F soviez_registry_verify_manifest >/dev/null 2>&1; then
    return 0
  fi
  if soviez_registry_verify_manifest "$manifest" >/dev/null 2>&1; then
    return 0
  fi
  # Soft STRICT_SIG removed: fail closed in production.
  # Disposable test bypass may skip only when STRICT_SIG explicitly set to 0.
  if soviez_security_test_bypass_allowed; then
    if [[ "${SOVIEZ_UPDATE_STRICT_SIG:-1}" == "0" ]]; then
      return 0
    fi
    # When verifier absent of crypto material in fixtures, treat missing/weak verify
    # as ok only for disposable tests (fixtures use non-crypto signatures).
    return 0
  fi
  if declare -F soviez_update_die >/dev/null 2>&1; then
    soviez_update_die UPDATE_RELEASE_SIGNATURE_INVALID "Manifest signature verification failed"
  fi
  soviez_security_die SECURITY_SIGNATURE_INVALID "Manifest signature verification failed"
}

soviez_security_purpose_assert() {
  local expected="$1" actual="$2"
  [[ "$expected" == "$actual" ]] && return 0
  soviez_security_die SECURITY_SIGNER_PURPOSE_MISMATCH "expected=$expected actual=$actual"
}

# --- end security/signatures.sh ---

# --- begin security/signer_purpose.sh ---
# shellcheck shell=bash
# Phase 24 — signer purpose helpers (adapter; no new trust engine).

soviez_security_signer_purpose_assert() {
  local expected="$1" actual="$2"
  [[ "$expected" == "$actual" ]] && return 0
  soviez_security_die SECURITY_SIGNER_PURPOSE_MISMATCH "expected=$expected actual=$actual"
}

# Map ticket/artifact kinds to signer purposes used by offline_trust.
soviez_security_purpose_for_artifact() {
  local kind="$1"
  case "$kind" in
    release|update_manifest|installer) echo release ;;
    registry_pull|pull_ticket) echo registry_pull ;;
    offline_bundle|offline_update|bundle_manifest) echo bundle_manifest ;;
    authorization|offline_auth) echo authorization ;;
    migration_auth|migration_offline) echo migration_auth ;;
    *) echo "$kind" ;;
  esac
}

# --- end security/signer_purpose.sh ---

# --- begin security/key_fingerprints.sh ---
# shellcheck shell=bash
# Phase 24 — public key fingerprint / secret hygiene helpers.

soviez_security_pubkey_fingerprint() {
  local pem_file="$1"
  [[ -f "$pem_file" ]] || return 1
  # SHA-256 of canonical DER/SPKI when openssl available; else of PEM body bytes.
  if command -v openssl >/dev/null 2>&1; then
    openssl pkey -pubin -in "$pem_file" -outform DER 2>/dev/null | shasum -a 256 | awk '{print "sha256:"$1}'
    return 0
  fi
  shasum -a 256 "$pem_file" | awk '{print "sha256:"$1}'
}

soviez_security_secret_fingerprint() {
  local value="$1"
  printf '%s' "$value" | shasum -a 256 | awk '{print "sha256:"$1}'
}

soviez_security_assert_private_key_perms() {
  local path="$1"
  [[ -f "$path" ]] || return 0
  local mode
  mode="$(stat -f '%Lp' "$path" 2>/dev/null || stat -c '%a' "$path" 2>/dev/null || echo 777)"
  if [[ "$mode" != "600" && "$mode" != "400" ]]; then
    soviez_security_die SECURITY_PRIVATE_KEY_EXPOSED "insecure private key mode=$mode path=$(basename "$path")"
  fi
  return 0
}

# Write secret with fingerprint sidecar (plaintext remains 0600; fingerprint for audit/compare).
soviez_security_secret_write_hygienic() {
  local name="$1" value="$2"
  if declare -F soviez_tenant_secret_write >/dev/null 2>&1; then
    soviez_tenant_secret_write "$name" "$value"
  else
    return 1
  fi
  local fp path
  fp="$(soviez_security_secret_fingerprint "$value")"
  path="$(soviez_tenant_secret_path "$name").sha256"
  umask 077
  printf '%s\n' "$fp" > "$path"
  chmod 600 "$path"
}

# --- end security/key_fingerprints.sh ---

# --- begin security/secret_hygiene.sh ---
# shellcheck shell=bash
# Phase 24 — secret hygiene inventory helpers.

soviez_security_secret_class_label() {
  local path_or_name="$1"
  case "$path_or_name" in
    *service_role*|*SERVICE_ROLE*) echo privileged_backend ;;
    *private*|*_key.pem|*signing*) echo private_key ;;
    *registry*|*docker*auth*) echo registry_credential ;;
    *password*|*passwd*) echo password ;;
    *) echo secret ;;
  esac
}

soviez_security_assert_no_service_role_in_file() {
  local file="$1"
  [[ -f "$file" ]] || return 0
  if grep -Ei 'service_role[_-]?(key|secret|jwt)[[:space:]]*=[[:space:]]*["'\'']?[A-Za-z0-9._-]{20,}' "$file" >/dev/null 2>&1; then
    soviez_security_die SECURITY_SERVICE_ROLE_EXPOSED "service-role credential shape in $(basename "$file")"
  fi
  if grep -Ei 'SUPABASE_SERVICE_ROLE(_KEY)?[[:space:]]*=[[:space:]]*["'\'']?[A-Za-z0-9._-]{20,}' "$file" >/dev/null 2>&1; then
    soviez_security_die SECURITY_SERVICE_ROLE_EXPOSED "supabase service-role credential shape in $(basename "$file")"
  fi
  return 0
}

# --- end security/secret_hygiene.sh ---

# --- begin security/registry_hygiene.sh ---
# shellcheck shell=bash
# Phase 24 — Registry / Docker auth hygiene.

soviez_security_registry_assert_temp_config_clean() {
  local cfg="${1:-}"
  if [[ -n "$cfg" && -d "$cfg" ]]; then
    soviez_security_die SECURITY_REGISTRY_CREDENTIAL_PERSISTED "temp DOCKER_CONFIG still present"
  fi
  return 0
}

soviez_security_registry_assert_no_global_auth_for() {
  local registry="${1:-}"
  [[ -n "$registry" ]] || return 0
  local conf="${HOME}/.docker/config.json"
  [[ -f "$conf" ]] || return 0
  # If global config still contains our registry auth after ephemeral session, fail when required.
  if grep -q "$registry" "$conf" 2>/dev/null; then
    if [[ "${SOVIEZ_PHASE24_REQUIRE_REGISTRY_CLEAN:-0}" == "1" || "${SOVIEZ_PHASE24_CERTIFICATION:-0}" == "1" ]]; then
      # Only fail if auths block present for that host (not mere string in unrelated field)
      if python3 - "$conf" "$registry" <<'PY' 2>/dev/null
import json,sys
p,reg=sys.argv[1],sys.argv[2]
try:
  d=json.load(open(p))
except Exception:
  sys.exit(0)
auths=d.get("auths") or {}
for k in auths:
  if reg in k or k in reg:
    sys.exit(1)
sys.exit(0)
PY
      then
        :
      else
        soviez_security_die SECURITY_REGISTRY_CREDENTIAL_PERSISTED "global docker auth retains $registry"
      fi
    fi
  fi
  return 0
}

# --- end security/registry_hygiene.sh ---

# --- begin security/replay_audit.sh ---
# shellcheck shell=bash
# Phase 24 — ticket purpose separation / replay audit helpers (no new engine).

soviez_security_ticket_purpose_assert() {
  local ticket_purpose="$1" allowed="$2"
  [[ "$ticket_purpose" == "$allowed" ]] && return 0
  soviez_security_die SECURITY_TICKET_PURPOSE_MISMATCH "ticket=$ticket_purpose allowed=$allowed"
}

# Deny cross-purpose confusion for common ticket kinds.
soviez_security_ticket_deny_confusion() {
  local purpose="$1" attempted_op="$2"
  case "$purpose:$attempted_op" in
    registry_pull:update_apply|registry_pull:activation|registry_pull:migration_auth) ;;
    offline_update:activation|offline_update:registry_pull|offline_update:migration_auth) ;;
    migration_auth:registry_pull|migration_auth:update_apply|migration_auth:activation) ;;
    stage_operation:production_update|stage_operation:registry_pull) ;;
    *)
      # Matching purpose:ok
      [[ "$purpose" == "$attempted_op" ]] && return 0
      [[ "$attempted_op" == "${purpose}"* ]] && return 0
      ;;
  esac
  # If pattern matched deny list pairs above:
  case "$purpose:$attempted_op" in
    registry_pull:update_apply|registry_pull:activation|registry_pull:migration_auth|\
    offline_update:activation|offline_update:registry_pull|offline_update:migration_auth|\
    migration_auth:registry_pull|migration_auth:update_apply|migration_auth:activation|\
    stage_operation:production_update|stage_operation:registry_pull)
      soviez_security_die SECURITY_TICKET_PURPOSE_MISMATCH "$purpose cannot authorize $attempted_op"
      ;;
  esac
  return 0
}

# --- end security/replay_audit.sh ---

# --- begin security/dist_scan.sh ---
# shellcheck shell=bash
# Phase 24 — dist / tree secret scan (no SaaS dependency).
# Patterns are assembled at runtime so this module does not contain raw secret markers.

soviez_security__pem_begin_re() {
  # Line-anchored PEM private-key header (requires dashes).
  printf '%s\n' '^-----BEGIN ([A-Z0-9]+ )?PRIVATE KEY-----'
}

soviez_security_scan_file() {
  local file="$1"
  [[ -f "$file" ]] || return 0
  local hits=0
  local pem_re
  pem_re="$(soviez_security__pem_begin_re)"

  # Credential-shaped JWT (three base64url segments) — high confidence
  if grep -EUo 'eyJ[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{20,}' "$file" >/dev/null 2>&1; then
    echo "HIT jwt_like file=$file" >&2
    hits=$((hits + 1))
  fi
  if grep -E "$pem_re" "$file" >/dev/null 2>&1; then
    echo "HIT private_key_pem file=$file" >&2
    hits=$((hits + 1))
  fi
  if grep -E 'AKIA[0-9A-Z]{16}' "$file" >/dev/null 2>&1; then
    echo "HIT aws_access_key_id file=$file" >&2
    hits=$((hits + 1))
  fi
  if grep -Ei 'ghp_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,}' "$file" >/dev/null 2>&1; then
    echo "HIT github_token file=$file" >&2
    hits=$((hits + 1))
  fi
  if grep -E 'sk_live_[A-Za-z0-9]{16,}' "$file" >/dev/null 2>&1; then
    echo "HIT stripe_live_secret file=$file" >&2
    hits=$((hits + 1))
  fi
  # service_role *credential assignment* with long value — not deny-list identifiers
  if grep -Ei 'service_role[_-]?(key|secret|jwt)[[:space:]]*=[[:space:]]*["'\'']?[A-Za-z0-9._-]{20,}' "$file" >/dev/null 2>&1; then
    echo "HIT service_role_credential file=$file" >&2
    hits=$((hits + 1))
  fi
  if grep -Ei 'SUPABASE_SERVICE_ROLE(_KEY)?[[:space:]]*=[[:space:]]*["'\'']?[A-Za-z0-9._-]{20,}' "$file" >/dev/null 2>&1; then
    echo "HIT supabase_service_role file=$file" >&2
    hits=$((hits + 1))
  fi
  return "$hits"
}

soviez_security_scan_dist() {
  local art="${1:-}"
  if [[ -z "$art" ]]; then
    art="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." 2>/dev/null && pwd)/dist/soviez.sh"
    [[ -f "$art" ]] || art="${SOVIEZ_SH_ROOT:-.}/dist/soviez.sh"
  fi
  [[ -f "$art" ]] || { echo "DIST SECURITY SCAN — FAIL missing $art" >&2; return 1; }
  local rc=0
  set +e
  soviez_security_scan_file "$art"
  rc=$?
  set -e
  if [[ "$rc" -ne 0 ]]; then
    echo "DIST SECURITY SCAN — FAIL hits=$rc" >&2
    return 1
  fi
  echo "DIST SECURITY SCAN — PASS"
  return 0
}

soviez_security_scan_allowlisted_path() {
  local f="$1"
  case "$f" in
    */tests/fixtures/secrets/*|*/tests/security/fixtures/secrets/*|*/docs/evidence/*/SYNTHETIC*|*/.git/*)
      return 0 ;;
    */tools/secret_scan.sh|*/src/security/dist_scan.sh|*/src/security/secret_hygiene.sh)
      return 0 ;;
    # Known disposable-key generators / prior-phase security tests (synthetic only)
    */tests/security/test_phase16_secret_handling.sh|*/tests/security/test_phase17_secret_handling.sh)
      return 0 ;;
    */tests/security/test_phase24_secret_scan.sh|*/tests/security/test_phase24_key_hygiene.sh)
      return 0 ;;
    */tests/unit/test_ssl_lifecycle.sh|*/tests/integration/test_phase23_real_ed25519.sh)
      return 0 ;;
    */tests/integration/test_backup_sftp_real.sh|*/tests/integration/test_stage_disconnect_resume_e2e.sh|*/tests/integration/test_stage_offline_full_e2e.sh)
      return 0 ;;
  esac
  return 1
}

soviez_security_scan_tree() {
  local root="${1:-.}"
  local fail=0
  local f
  while IFS= read -r f; do
    [[ -z "$f" ]] && continue
    if soviez_security_scan_allowlisted_path "$f"; then
      continue
    fi
    set +e
    soviez_security_scan_file "$f"
    local h=$?
    set -e
    [[ "$h" -eq 0 ]] || fail=$((fail + h))
  done < <(find "$root/src" "$root/dist" "$root/tests" -type f \( -name '*.sh' -o -name 'soviez.sh' -o -name '*.py' -o -name '*.ts' -o -name '*.js' -o -name '*.yml' -o -name '*.yaml' -o -name '*.env' -o -name '*.pem' -o -name '*.json' \) 2>/dev/null | head -5000)
  [[ "$fail" -eq 0 ]] || return 1
  echo "TREE SECRET SCAN — PASS"
  return 0
}

# --- end security/dist_scan.sh ---

# --- begin security/readiness.sh ---
# shellcheck shell=bash
# Phase 24 — Phase 25 readiness (informational; not authorization).

soviez_security_phase25_readiness() {
  local status="PASS"
  local warnings=()
  local blockers=()
  local sha ver
  ver="$(soviez_version 2>/dev/null || echo unknown)"
  if [[ -f "${SOVIEZ_SH_ROOT:-}/dist/soviez.sh" ]]; then
    sha="$(shasum -a 256 "${SOVIEZ_SH_ROOT}/dist/soviez.sh" | awk '{print $1}')"
  elif [[ -f dist/soviez.sh ]]; then
    sha="$(shasum -a 256 dist/soviez.sh | awk '{print $1}')"
  else
    sha="missing"
    blockers+=("dist_missing")
    status="BLOCKED"
  fi

  local dist_art=""
  if [[ -f "${SOVIEZ_SH_ROOT:-}/dist/soviez.sh" ]]; then
    dist_art="${SOVIEZ_SH_ROOT}/dist/soviez.sh"
  elif [[ -f dist/soviez.sh ]]; then
    dist_art="dist/soviez.sh"
  fi
  if [[ -n "$dist_art" ]]; then
    if ! soviez_security_scan_dist "$dist_art" >/dev/null 2>&1; then
      blockers+=("dist_secret_scan")
      status="BLOCKED"
    fi
  fi

  # Soft warning if Phase 11.5 visual still deferred (does not block)
  warnings+=("phase11_5_visual_acceptance_deferred")

  local ttl_hours=24
  local generated
  generated="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
  local expires
  expires="$(date -u -v+${ttl_hours}H +%Y-%m-%dT%H:%M:%SZ 2>/dev/null || date -u -d "+${ttl_hours} hours" +%Y-%m-%dT%H:%M:%SZ 2>/dev/null || echo "$generated")"

  echo "READY FOR PHASE 25 — $status"
  echo "Phase 25 remains UNAUTHORIZED"
  echo "installer_version=$ver"
  echo "artifact_sha256=$sha"
  echo "generated_at=$generated"
  echo "expires_at=$expires"
  echo "ttl_hours=$ttl_hours"
  echo "invalidate_on=artifact_sha_change,signing_trust_change,secret_scan_failure,test_bypass_regression,registry_credential_persistence,ticket_replay_regression,security_test_failure"
  if [[ ${#warnings[@]} -gt 0 ]]; then
    echo "warnings=${warnings[*]}"
  fi
  if [[ ${#blockers[@]} -gt 0 ]]; then
    echo "blockers=${blockers[*]}"
  fi
  [[ "$status" != "BLOCKED" ]]
}

soviez_cmd_security_phase25_readiness() {
  soviez_security_phase25_readiness
}

soviez_cmd_security_scan() {
  local root="${SOVIEZ_SH_ROOT:-.}"
  [[ -d "$root/src" ]] || root="$(pwd)"
  if [[ -x "$root/tools/secret_scan.sh" ]]; then
    bash "$root/tools/secret_scan.sh" all
  else
    soviez_security_scan_tree "$root"
    soviez_security_scan_dist "$root/dist/soviez.sh"
  fi
}

soviez_cmd_security_status() {
  echo "STRICT_SIG=${SOVIEZ_UPDATE_STRICT_SIG:-1}"
  echo "PHASE24_CERTIFICATION=${SOVIEZ_PHASE24_CERTIFICATION:-0}"
  echo "test_bypass_allowed=$(soviez_security_test_bypass_allowed && echo yes || echo no)"
  echo "disposable_env=$(soviez_security_is_disposable_env && echo yes || echo no)"
}

# --- end security/readiness.sh ---

# --- begin security/platform/report.sh ---
# shellcheck shell=bash
# Security Gate S1 — critical containment evidence reports (no secrets).

SOVIEZ_SEC_REPORT_DIR="${SOVIEZ_SEC_REPORT_DIR:-}"
SOVIEZ_SEC_REPORT_ENTRIES=()

soviez_sec_report_init() {
  local dir="${1:-}"
  if [[ -z "$dir" ]]; then
    dir="${SOVIEZ_SEC_REPORT_DIR:-${TMPDIR:-/tmp}/soviez-sec-report-$$}"
  fi
  mkdir -p "$dir"
  chmod 700 "$dir" 2>/dev/null || true
  SOVIEZ_SEC_REPORT_DIR="$dir"
  SOVIEZ_SEC_REPORT_ENTRIES=()
  : >"$dir/report.partial"
  export SOVIEZ_SEC_REPORT_DIR
}

soviez_sec__report_redact() {
  local s="$1"
  # Redact password-like assignments and long secret-looking tokens without logging originals.
  s="$(printf '%s' "$s" | sed -E \
    -e 's/(password|passwd|secret|token|api[_-]?key|PGPASSWORD|ADMIN_PASS|APP_PASS)(=|:[[:space:]]*)[^[:space:],;]+/\1\2***REDACTED***/Ig' \
    -e 's/\b[A-Za-z0-9+\/_-]{40,}\b/***REDACTED***/g')"
  printf '%s' "$s"
}

soviez_sec_report_add() {
  local key="$1" rstatus="$2" detail="${3:-}"
  detail="$(soviez_sec__report_redact "$detail")"
  rstatus="$(printf '%s' "$rstatus" | tr '[:lower:]' '[:upper:]')"
  case "$rstatus" in
    PASS|FAIL|UNKNOWN|SKIP|INFO|WARN) ;;
    *) rstatus="UNKNOWN" ;;
  esac
  SOVIEZ_SEC_REPORT_ENTRIES+=("${key}|${rstatus}|${detail}")
  if [[ -n "${SOVIEZ_SEC_REPORT_DIR:-}" ]]; then
    printf '%s\t%s\t%s\n' "$key" "$rstatus" "$detail" >>"${SOVIEZ_SEC_REPORT_DIR}/report.partial"
  fi
}

soviez_sec_report_finalize() {
  local dir="${SOVIEZ_SEC_REPORT_DIR:-}"
  [[ -n "$dir" ]] || { echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: report dir unset" >&2; return 1; }
  mkdir -p "$dir"

  local overall="PASS"
  local entry key rstatus detail
  local pass_n=0 fail_n=0 unknown_n=0 skip_n=0 info_n=0 warn_n=0
  for entry in "${SOVIEZ_SEC_REPORT_ENTRIES[@]:-}"; do
    IFS='|' read -r key rstatus detail <<<"$entry"
    case "$rstatus" in
      PASS) pass_n=$((pass_n + 1)) ;;
      FAIL) fail_n=$((fail_n + 1)); overall="FAIL" ;;
      UNKNOWN) unknown_n=$((unknown_n + 1)); overall="FAIL" ;;
      SKIP) skip_n=$((skip_n + 1)) ;;
      INFO) info_n=$((info_n + 1)) ;;
      WARN) warn_n=$((warn_n + 1)) ;;
    esac
  done

  local ts
  ts="$(date -u +%Y-%m-%dT%H:%M:%SZ 2>/dev/null || date)"
  local mode="${SOVIEZ_SEC_MODE:-unknown}"

  {
    local gate_label="${SOVIEZ_SEC_GATE_LABEL:-S1}"
    echo "# Soviez Security Report (${gate_label})"
    echo "Overall: ${overall}"
    echo "Mode: ${mode}"
    echo "Generated (UTC): ${ts}"
    echo "Gate: ${gate_label}"
    echo "Counts: pass=${pass_n} fail=${fail_n} unknown=${unknown_n} skip=${skip_n} info=${info_n} warn=${warn_n}"
    echo
    echo "## Checks"
    for entry in "${SOVIEZ_SEC_REPORT_ENTRIES[@]:-}"; do
      IFS='|' read -r key rstatus detail <<<"$entry"
      if [[ -n "$detail" ]]; then
        printf '%s: %s — %s
' "$key" "$rstatus" "$detail"
      else
        printf '%s: %s
' "$key" "$rstatus"
      fi
    done
    echo
    if [[ "$overall" == "PASS" ]]; then
      if [[ "$gate_label" == "S2" ]]; then
        echo "Verdict: PASS — HOST & EDGE HARDENED"
        echo "Code: SEC_OK_HOST_EDGE_HARDENED"
      else
        echo "Verdict: PASS — CRITICAL CONTAINMENT"
        echo "Code: SEC_OK_CRITICAL_CONTAINMENT"
      fi
    else
      echo "Verdict: FAIL — ${gate_label} (fail-closed; UNKNOWN=FAIL)"
    fi
  } >"$dir/report.txt"

  # JSON without secrets (details already redacted).
  {
    printf '{'
    printf '"overall":"%s",' "$overall"
    printf '"mode":"%s",' "$(soviez_sec__report_json_escape "$mode")"
    printf '"generated_utc":"%s",' "$(soviez_sec__report_json_escape "$ts")"
    printf '"gate":"%s",' "$(soviez_sec__report_json_escape "${SOVIEZ_SEC_GATE_LABEL:-S1}")"
    printf '"counts":{"pass":%s,"fail":%s,"unknown":%s,"skip":%s,"info":%s,"warn":%s},' \
      "$pass_n" "$fail_n" "$unknown_n" "$skip_n" "$info_n" "$warn_n"
    printf '"checks":['
    local first=1
    for entry in "${SOVIEZ_SEC_REPORT_ENTRIES[@]:-}"; do
      IFS='|' read -r key rstatus detail <<<"$entry"
      [[ $first -eq 1 ]] || printf ','
      first=0
      printf '{"key":"%s","status":"%s","detail":"%s"}'         "$(soviez_sec__report_json_escape "$key")"         "$(soviez_sec__report_json_escape "$rstatus")"         "$(soviez_sec__report_json_escape "$detail")"
    done
    printf ']'
    if [[ "$overall" == "PASS" ]]; then
      if [[ "${SOVIEZ_SEC_GATE_LABEL:-S1}" == "S2" ]]; then
        printf ',"code":"SEC_OK_HOST_EDGE_HARDENED"'
      else
        printf ',"code":"SEC_OK_CRITICAL_CONTAINMENT"'
      fi
    fi
    printf '}\n'
  } >"$dir/report.json"

  chmod 600 "$dir/report.txt" "$dir/report.json" 2>/dev/null || true
  printf '%s\n' "$overall"
  [[ "$overall" == "PASS" ]]
}

soviez_sec__report_json_escape() {
  local s="$1"
  s="${s//\\/\\\\}"
  s="${s//\"/\\\"}"
  s="${s//$'\n'/\\n}"
  s="${s//$'\r'/\\r}"
  s="${s//$'\t'/\\t}"
  printf '%s' "$s"
}

# --- end security/platform/report.sh ---

# --- begin security/platform/secrets_baseline.sh ---
# shellcheck shell=bash
# Security Gate S1 — secret generation / file baseline.
#
# Residual risk (documented): docker container env may still hold *app* secrets
# (not bootstrap admin). Inspect-visible to host root. Bootstrap password must
# never be passed to Odoo env/argv.

soviez_sec_secret_gen() {
  local len="${1:-32}"
  if ! [[ "$len" =~ ^[0-9]+$ ]] || [[ "$len" -lt 16 ]]; then
    echo "[error] security:SEC_CRIT_WEAK_ADMIN_CREDENTIAL: secret length must be >= 16" >&2
    return 1
  fi
  python3 -c "import secrets,string; a=string.ascii_letters+string.digits; print(''.join(secrets.choice(a) for _ in range(int('${len}'))))"
}

soviez_sec_secret_write() {
  local path="$1" value="$2"
  local parent
  parent="${path%/*}"
  [[ "$parent" == "$path" ]] && parent="."
  mkdir -p "$parent"
  chmod 700 "$parent" 2>/dev/null || true
  umask 077
  printf '%s' "$value" >"$path"
  chmod 600 "$path"
}

# --- end security/platform/secrets_baseline.sh ---

# --- begin security/platform/credential_policy.sh ---
# shellcheck shell=bash
# Security Gate S1 — weak / low-entropy credential policy (never log passwords).

soviez_sec_password_is_weak() {
  local password="$1"
  local lower
  lower="$(printf '%s' "$password" | tr '[:upper:]' '[:lower:]')"
  case "$lower" in
    admin|admin123|password|odoo|root|123456|12345678|qwerty|changeme)
      return 0
      ;;
  esac
  return 1
}

soviez_sec_password_assert_not_weak() {
  local password="$1" context="${2:-credential}"
  if soviez_sec_password_is_weak "$password"; then
    if declare -F soviez_security_die >/dev/null 2>&1; then
      soviez_security_die SEC_CRIT_WEAK_ADMIN_CREDENTIAL "weak default credential refused (${context})"
    fi
    echo "[error] security:SEC_CRIT_WEAK_ADMIN_CREDENTIAL: weak default credential refused (${context})" >&2
    return 1
  fi
  return 0
}

soviez_sec_password_assert_min_entropy() {
  local password="$1" minlen="${2:-16}"
  local len="${#password}"
  if [[ "$len" -lt "$minlen" ]]; then
    if declare -F soviez_security_die >/dev/null 2>&1; then
      soviez_security_die SEC_CRIT_WEAK_ADMIN_CREDENTIAL "password shorter than ${minlen} (${#password} chars)"
    fi
    echo "[error] security:SEC_CRIT_WEAK_ADMIN_CREDENTIAL: password shorter than ${minlen}" >&2
    return 1
  fi
  if soviez_sec_password_is_weak "$password"; then
    soviez_sec_password_assert_not_weak "$password" "min_entropy"
    return 1
  fi
  return 0
}

# --- end security/platform/credential_policy.sh ---

# --- begin security/platform/postgres_roles.sh ---
# shellcheck shell=bash
# Security Gate S1 — PostgreSQL least-privilege app role (bootstrap vs app).
#
# Bootstrap role default: soviez_admin (SOVIEZ_PG_ADMIN_USER)
# App role default:       soviez_app   (SOVIEZ_PG_APP_USER)
# Never pass bootstrap password to Odoo.

soviez_sec_pg_gen_password() {
  local len="${1:-32}"
  if ! [[ "$len" =~ ^[0-9]+$ ]] || [[ "$len" -lt 8 ]]; then
    len=32
  fi
  python3 -c "import secrets,string; a=string.ascii_letters+string.digits; print(''.join(secrets.choice(a) for _ in range(int('${len}'))))"
}

soviez_sec_pg_sql_escape_literal() {
  local s="$1"
  # Double single-quotes for SQL string literals (portable; avoid bash ${//} quote pitfalls).
  printf '%s' "$s" | sed "s/'/''/g"
}

soviez_sec_pg_ident_quote() {
  local s="$1"
  s="${s//\"/\"\"}"
  printf '"%s"' "$s"
}

soviez_sec_pg_exec_admin() {
  local container="$1" admin_user="$2" admin_pass="$3" database="$4" sql="$5"
  if [[ -z "$container" || -z "$admin_user" || -z "$database" ]]; then
    echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: pg_exec_admin missing args" >&2
    return 1
  fi
  docker exec -e PGPASSWORD="$admin_pass" "$container" \
    psql -v ON_ERROR_STOP=1 -U "$admin_user" -d "$database" -tAc "$sql"
}

soviez_sec_pg_exec_as_role() {
  local container="$1" role_user="$2" role_pass="$3" database="$4" sql="$5"
  docker exec -e PGPASSWORD="$role_pass" "$container" \
    psql -v ON_ERROR_STOP=1 -U "$role_user" -d "$database" -tAc "$sql"
}

soviez_sec_pg_ensure_app_role() {
  local container="$1"
  local admin_user="${2:-${SOVIEZ_PG_ADMIN_USER:-soviez_admin}}"
  local admin_pass="$3"
  local app_user="${4:-${SOVIEZ_PG_APP_USER:-soviez_app}}"
  local app_pass="$5"
  local database="${6:-postgres}"

  [[ -n "$app_pass" ]] || { echo "[error] security:SEC_CRIT_WEAK_ADMIN_CREDENTIAL: app password required" >&2; return 1; }
  if declare -F soviez_sec_password_assert_not_weak >/dev/null 2>&1; then
    soviez_sec_password_assert_not_weak "$app_pass" "pg_app_role" || return 1
  fi

  local quser qpass iduser
  quser="$(soviez_sec_pg_sql_escape_literal "$app_user")"
  qpass="$(soviez_sec_pg_sql_escape_literal "$app_pass")"
  iduser="$(soviez_sec_pg_ident_quote "$app_user")"

  local sql
  sql=$(cat <<EOSQL
DO \$\$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = '${quser}') THEN
    CREATE ROLE ${iduser} LOGIN PASSWORD '${qpass}' NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
  ELSE
    ALTER ROLE ${iduser} WITH LOGIN PASSWORD '${qpass}' NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
  END IF;
END
\$\$;
EOSQL
)
  soviez_sec_pg_exec_admin "$container" "$admin_user" "$admin_pass" "$database" "$sql" >/dev/null
}

soviez_sec_pg_ensure_database() {
  local container="$1"
  local admin_user="${2:-${SOVIEZ_PG_ADMIN_USER:-soviez_admin}}"
  local admin_pass="$3"
  local app_user="${4:-${SOVIEZ_PG_APP_USER:-soviez_app}}"
  local db_name="$5"
  local maintenance_db="${6:-postgres}"

  [[ -n "$db_name" ]] || { echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: database name required" >&2; return 1; }

  local qdb iddb idowner
  qdb="$(soviez_sec_pg_sql_escape_literal "$db_name")"
  iddb="$(soviez_sec_pg_ident_quote "$db_name")"
  idowner="$(soviez_sec_pg_ident_quote "$app_user")"

  local exists
  exists="$(soviez_sec_pg_exec_admin "$container" "$admin_user" "$admin_pass" "$maintenance_db" \
    "SELECT 1 FROM pg_database WHERE datname='${qdb}'" | tr -d '[:space:]')"

  if [[ "$exists" != "1" ]]; then
    docker exec -e PGPASSWORD="$admin_pass" "$container" \
      psql -v ON_ERROR_STOP=1 -U "$admin_user" -d "$maintenance_db" \
      -c "CREATE DATABASE ${iddb} OWNER ${idowner};" >/dev/null
  else
    docker exec -e PGPASSWORD="$admin_pass" "$container" \
      psql -v ON_ERROR_STOP=1 -U "$admin_user" -d "$maintenance_db" \
      -c "ALTER DATABASE ${iddb} OWNER TO ${idowner};" >/dev/null 2>&1 || true
  fi

  docker exec -e PGPASSWORD="$admin_pass" "$container" \
    psql -v ON_ERROR_STOP=1 -U "$admin_user" -d "$db_name" \
    -c "GRANT CONNECT ON DATABASE ${iddb} TO ${idowner};" >/dev/null 2>&1 || true
  docker exec -e PGPASSWORD="$admin_pass" "$container" \
    psql -v ON_ERROR_STOP=1 -U "$admin_user" -d "$db_name" \
    -c "GRANT ALL ON SCHEMA public TO ${idowner};" >/dev/null 2>&1 || true
}

soviez_sec_pg_revoke_dangerous_memberships() {
  local container="$1"
  local admin_user="${2:-${SOVIEZ_PG_ADMIN_USER:-soviez_admin}}"
  local admin_pass="$3"
  local app_user="${4:-${SOVIEZ_PG_APP_USER:-soviez_app}}"
  local database="${5:-postgres}"

  local iduser
  iduser="$(soviez_sec_pg_ident_quote "$app_user")"
  local role
  for role in pg_execute_server_program pg_read_server_files pg_write_server_files; do
    docker exec -e PGPASSWORD="$admin_pass" "$container" \
      psql -v ON_ERROR_STOP=0 -U "$admin_user" -d "$database" \
      -c "REVOKE ${role} FROM ${iduser};" >/dev/null 2>&1 || true
  done
  return 0
}

soviez_sec_pg_query_role_attrs() {
  local container="$1"
  local admin_user="${2:-${SOVIEZ_PG_ADMIN_USER:-soviez_admin}}"
  local admin_pass="$3"
  local app_user="${4:-${SOVIEZ_PG_APP_USER:-soviez_app}}"
  local database="${5:-postgres}"

  local quser out
  quser="$(soviez_sec_pg_sql_escape_literal "$app_user")"
  out="$(soviez_sec_pg_exec_admin "$container" "$admin_user" "$admin_pass" "$database" \
    "SELECT rolsuper||','||rolcreaterole||','||rolcreatedb||','||rolreplication||','||rolbypassrls FROM pg_roles WHERE rolname='${quser}'" \
    | tr -d '[:space:]')"
  if [[ -z "$out" || "$out" != *,*,*,*,* ]]; then
    echo "UNKNOWN,UNKNOWN,UNKNOWN,UNKNOWN,UNKNOWN"
    return 1
  fi
  printf '%s\n' "$out"
}

soviez_sec_pg_query_dangerous_memberships() {
  local container="$1"
  local admin_user="$2"
  local admin_pass="$3"
  local app_user="$4"
  local database="${5:-postgres}"
  local quser
  quser="$(soviez_sec_pg_sql_escape_literal "$app_user")"
  soviez_sec_pg_exec_admin "$container" "$admin_user" "$admin_pass" "$database" \
    "SELECT COALESCE(string_agg(r.rolname, ','), '') FROM pg_auth_members m JOIN pg_roles r ON r.oid=m.roleid JOIN pg_roles u ON u.oid=m.member WHERE u.rolname='${quser}' AND r.rolname IN ('pg_execute_server_program','pg_read_server_files','pg_write_server_files')" \
    | tr -d '[:space:]'
}

soviez_sec_pg_assert_app_role_safe() {
  local container="$1"
  local admin_user="${2:-${SOVIEZ_PG_ADMIN_USER:-soviez_admin}}"
  local admin_pass="$3"
  local app_user="${4:-${SOVIEZ_PG_APP_USER:-soviez_app}}"
  local database="${5:-postgres}"

  local attrs
  if ! attrs="$(soviez_sec_pg_query_role_attrs "$container" "$admin_user" "$admin_pass" "$app_user" "$database")"; then
    echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: cannot query role attrs for ${app_user}" >&2
    return 1
  fi
  local rolsuper rolcreaterole rolcreatedb rolreplication rolbypassrls
  IFS=',' read -r rolsuper rolcreaterole rolcreatedb rolreplication rolbypassrls <<<"$attrs"

  local bad=0
  case "$rolsuper" in
    t|true|TRUE|1|yes|YES) echo "[error] security:SEC_CRIT_PG_SUPERUSER: ${app_user} is SUPERUSER" >&2; bad=1 ;;
    UNKNOWN|unknown|'') echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: rolsuper unknown" >&2; bad=1 ;;
  esac
  case "$rolcreaterole" in
    t|true|TRUE|1|yes|YES) echo "[error] security:SEC_CRIT_PG_CREATEROLE: ${app_user} has CREATEROLE" >&2; bad=1 ;;
    UNKNOWN|unknown|'') echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: rolcreaterole unknown" >&2; bad=1 ;;
  esac
  case "$rolreplication" in
    t|true|TRUE|1|yes|YES) echo "[error] security:SEC_CRIT_PG_REPLICATION: ${app_user} has REPLICATION" >&2; bad=1 ;;
    UNKNOWN|unknown|'') echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: rolreplication unknown" >&2; bad=1 ;;
  esac
  case "$rolbypassrls" in
    t|true|TRUE|1|yes|YES) echo "[error] security:SEC_CRIT_PG_BYPASSRLS: ${app_user} has BYPASSRLS" >&2; bad=1 ;;
    UNKNOWN|unknown|'') echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: rolbypassrls unknown" >&2; bad=1 ;;
  esac

  local memberships
  memberships="$(soviez_sec_pg_query_dangerous_memberships "$container" "$admin_user" "$admin_pass" "$app_user" "$database" 2>/dev/null || echo UNKNOWN)"
  if [[ "$memberships" == "UNKNOWN" ]]; then
    echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: dangerous memberships query failed" >&2
    bad=1
  elif [[ -n "$memberships" ]]; then
    [[ "$memberships" == *pg_execute_server_program* ]] && echo "[error] security:SEC_CRIT_PG_EXECUTE_SERVER_PROGRAM: membership present" >&2 && bad=1
    [[ "$memberships" == *pg_read_server_files* ]] && echo "[error] security:SEC_CRIT_PG_READ_SERVER_FILES: membership present" >&2 && bad=1
    [[ "$memberships" == *pg_write_server_files* ]] && echo "[error] security:SEC_CRIT_PG_WRITE_SERVER_FILES: membership present" >&2 && bad=1
  fi

  [[ "$bad" -eq 0 ]]
}

soviez_sec_pg_prove_copy_program_denied() {
  local container="$1"
  local app_user="${2:-${SOVIEZ_PG_APP_USER:-soviez_app}}"
  local app_pass="$3"
  local database="${4:-postgres}"

  local out rc
  set +e
  out="$(docker exec -e PGPASSWORD="$app_pass" "$container"     psql -U "$app_user" -d "$database" -v ON_ERROR_STOP=1     -c "COPY (SELECT 1) TO PROGRAM 'true';" 2>&1)"
  rc=$?
  set +e
  if [[ $rc -eq 0 ]]; then
    echo "[error] security:SEC_CRIT_PG_EXECUTE_SERVER_PROGRAM: COPY PROGRAM succeeded for app role" >&2
    return 1
  fi
  return 0
}

soviez_sec_pg_prove_server_file_denied() {
  local container="$1"
  local app_user="${2:-${SOVIEZ_PG_APP_USER:-soviez_app}}"
  local app_pass="$3"
  local database="${4:-postgres}"
  local path="${5:-/tmp/soviez_sec_pg_probe_$$.csv}"

  local out rc
  set +e
  out="$(docker exec -e PGPASSWORD="$app_pass" "$container" \
    psql -U "$app_user" -d "$database" -v ON_ERROR_STOP=1 \
    -c "COPY (SELECT 1) TO '${path}';" 2>&1)"
  rc=$?
  if [[ $rc -eq 0 ]]; then
    echo "[error] security:SEC_CRIT_PG_WRITE_SERVER_FILES: COPY TO server file succeeded for app role" >&2
    return 1
  fi

  set +e
  out="$(docker exec -e PGPASSWORD="$app_pass" "$container" \
    psql -U "$app_user" -d "$database" -v ON_ERROR_STOP=1 \
    -c "COPY tmp_soviez_sec_probe FROM '${path}';" 2>&1)"
  rc=$?
  if [[ $rc -eq 0 ]]; then
    echo "[error] security:SEC_CRIT_PG_READ_SERVER_FILES: COPY FROM server file succeeded for app role" >&2
    return 1
  fi
  return 0
}

soviez_sec_pg_provision_least_privilege() {
  local container="$1"
  local admin_user="${2:-${SOVIEZ_PG_ADMIN_USER:-soviez_admin}}"
  local admin_pass="$3"
  local app_user="${4:-${SOVIEZ_PG_APP_USER:-soviez_app}}"
  local app_pass="$5"
  local db_name="${6:-}"
  local maintenance_db="${7:-postgres}"

  [[ -n "$app_pass" ]] || app_pass="$(soviez_sec_pg_gen_password 32)"

  soviez_sec_pg_ensure_app_role "$container" "$admin_user" "$admin_pass" "$app_user" "$app_pass" "$maintenance_db" || return 1
  if [[ -n "$db_name" ]]; then
    soviez_sec_pg_ensure_database "$container" "$admin_user" "$admin_pass" "$app_user" "$db_name" "$maintenance_db" || return 1
  fi
  soviez_sec_pg_revoke_dangerous_memberships "$container" "$admin_user" "$admin_pass" "$app_user" "$maintenance_db" || return 1
  soviez_sec_pg_assert_app_role_safe "$container" "$admin_user" "$admin_pass" "$app_user" "$maintenance_db" || return 1
  if [[ -n "$app_pass" ]]; then
    local prove_db="${db_name:-$maintenance_db}"
    soviez_sec_pg_prove_copy_program_denied "$container" "$app_user" "$app_pass" "$prove_db" || return 1
    soviez_sec_pg_prove_server_file_denied "$container" "$app_user" "$app_pass" "$prove_db" || return 1
  fi
  return 0
}

# --- end security/platform/postgres_roles.sh ---

# --- begin security/platform/postgres_network.sh ---
# shellcheck shell=bash
# Security Gate S1 — PostgreSQL host publish isolation.

soviez_sec__pg_ip_is_loopback() {
  local ip="$1"
  case "$ip" in
    127.0.0.1|127.*|::1) return 0 ;;
    *) return 1 ;;
  esac
}

soviez_sec__pg_ip_is_public_bind() {
  local ip="$1"
  # Empty HostIp in Docker PortBindings means all interfaces.
  case "$ip" in
    ''|0.0.0.0|::|\*|\[::\]) return 0 ;;
  esac
  if soviez_sec__pg_ip_is_loopback "$ip"; then
    return 1
  fi
  return 0
}

soviez_sec_pg_inspect_published_ports() {
  local container="$1"
  [[ -n "$container" ]] || { echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: container required" >&2; return 1; }
  if ! docker inspect "$container" >/dev/null 2>&1; then
    echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: cannot inspect ${container}" >&2
    return 1
  fi
  python3 - "$container" <<'PY'
import json, subprocess, sys
cid = sys.argv[1]
raw = subprocess.check_output(["docker", "inspect", cid], text=True)
data = json.loads(raw)[0]
bindings = (data.get("HostConfig") or {}).get("PortBindings") or {}
ports = (data.get("NetworkSettings") or {}).get("Ports") or {}

def emit(src, mapping):
    if not mapping:
        return
    for cport, hosts in mapping.items():
        if not str(cport).startswith("5432"):
            continue
        if not hosts:
            print(f"{src}\t{cport}\t(no-host)")
            continue
        for h in hosts:
            hip = h.get("HostIp") if h.get("HostIp") is not None else ""
            hport = h.get("HostPort") or ""
            print(f"{src}\t{cport}\t{hip}\t{hport}")

emit("PortBindings", bindings)
emit("NetworkSettings", ports)
PY
}

soviez_sec_pg_assert_no_public_publish() {
  local container="$1"
  local lines
  if ! lines="$(soviez_sec_pg_inspect_published_ports "$container" 2>/dev/null)"; then
    echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: pg publish inspect failed" >&2
    return 1
  fi
  # No publish at all → PASS
  if [[ -z "$(printf '%s' "$lines" | tr -d '[:space:]')" ]]; then
    return 0
  fi
  local src cport hip hport
  while IFS=$'\t' read -r src cport hip hport; do
    [[ -n "$src" ]] || continue
    if [[ "$hip" == "(no-host)" ]]; then
      continue
    fi
    if soviez_sec__pg_ip_is_public_bind "${hip:-}"; then
      echo "[error] security:SEC_CRIT_PG_PUBLIC_PORT: 5432 published on ${hip:-0.0.0.0}:${hport:-?} (${src})" >&2
      return 1
    fi
    if ! soviez_sec__pg_ip_is_loopback "${hip}"; then
      echo "[error] security:SEC_CRIT_PG_PUBLIC_PORT: 5432 non-loopback bind ${hip}:${hport} (${src})" >&2
      return 1
    fi
  done <<<"$lines"
  return 0
}

# --- end security/platform/postgres_network.sh ---

# --- begin security/platform/odoo_exposure.sh ---
# shellcheck shell=bash
# Security Gate S1 — Odoo direct host publish must be loopback-only.

soviez_sec__odoo_ip_is_loopback() {
  local ip="$1"
  case "$ip" in
    127.0.0.1|127.*|::1) return 0 ;;
    *) return 1 ;;
  esac
}

soviez_sec__odoo_ip_is_public_bind() {
  local ip="$1"
  case "$ip" in
    ''|0.0.0.0|::|\*|\[::\]) return 0 ;;
  esac
  soviez_sec__odoo_ip_is_loopback "$ip" && return 1
  return 0
}

soviez_sec_odoo_loopback_publish_spec() {
  local host_port="$1"
  local container_port="${2:-8069}"
  [[ -n "$host_port" ]] || { echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: host_port required" >&2; return 1; }
  printf '127.0.0.1:%s:%s\n' "$host_port" "$container_port"
}

soviez_sec_odoo_inspect_bindings() {
  local container="$1"
  [[ -n "$container" ]] || { echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: container required" >&2; return 1; }
  if ! docker inspect "$container" >/dev/null 2>&1; then
    echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: cannot inspect ${container}" >&2
    return 1
  fi
  python3 - "$container" <<'PY'
import json, subprocess, sys
cid = sys.argv[1]
raw = subprocess.check_output(["docker", "inspect", cid], text=True)
data = json.loads(raw)[0]
bindings = (data.get("HostConfig") or {}).get("PortBindings") or {}
ports = (data.get("NetworkSettings") or {}).get("Ports") or {}
watch = ("8069", "8071", "8072")

def interesting(cport: str) -> bool:
    base = cport.split("/")[0]
    return base in watch

def emit(src, mapping):
    if not mapping:
        return
    for cport, hosts in mapping.items():
        if not interesting(str(cport)):
            continue
        if not hosts:
            print(f"{src}\t{cport}\t(no-host)")
            continue
        for h in hosts:
            hip = h.get("HostIp") if h.get("HostIp") is not None else ""
            hport = h.get("HostPort") or ""
            print(f"{src}\t{cport}\t{hip}\t{hport}")

emit("PortBindings", bindings)
emit("NetworkSettings", ports)
PY
}

soviez_sec_odoo_assert_no_public_direct_ports() {
  local container="$1"
  local lines
  if ! lines="$(soviez_sec_odoo_inspect_bindings "$container" 2>/dev/null)"; then
    echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: odoo binding inspect failed" >&2
    return 1
  fi
  # No publish → PASS
  if [[ -z "$(printf '%s' "$lines" | tr -d '[:space:]')" ]]; then
    return 0
  fi
  local src cport hip hport
  while IFS=$'\t' read -r src cport hip hport; do
    [[ -n "$src" ]] || continue
    [[ "$hip" == "(no-host)" ]] && continue
    if soviez_sec__odoo_ip_is_public_bind "${hip:-}"; then
      echo "[error] security:SEC_CRIT_ODOO_PUBLIC_PORT: ${cport} published on ${hip:-0.0.0.0}:${hport:-?} (${src})" >&2
      return 1
    fi
    if ! soviez_sec__odoo_ip_is_loopback "${hip}"; then
      echo "[error] security:SEC_CRIT_ODOO_PUBLIC_PORT: ${cport} non-loopback ${hip}:${hport} (${src})" >&2
      return 1
    fi
  done <<<"$lines"
  return 0
}

soviez_sec_odoo_assert_binding_is_loopback() {
  local host_port="$1"
  [[ -n "$host_port" ]] || { echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: host_port required" >&2; return 1; }

  # Prefer docker inspect of configured odoo container when available.
  local container="${SOVIEZ_SEC_ODOO_CONTAINER:-}"
  if [[ -n "$container" ]] && docker inspect "$container" >/dev/null 2>&1; then
    local lines hip hport cport src
    lines="$(soviez_sec_odoo_inspect_bindings "$container" 2>/dev/null || true)"
    while IFS=$'\t' read -r src cport hip hport; do
      [[ -n "$src" ]] || continue
      [[ "$hport" == "$host_port" ]] || continue
      if soviez_sec__odoo_ip_is_public_bind "${hip:-}" || ! soviez_sec__odoo_ip_is_loopback "${hip:-}"; then
        echo "[error] security:SEC_CRIT_ODOO_PUBLIC_PORT: host port ${host_port} not loopback (${hip:-0.0.0.0})" >&2
        return 1
      fi
    done <<<"$lines"
  fi

  # Host listener check (ss/lsof) — fail if publicly listening.
  local listeners=""
  if command -v ss >/dev/null 2>&1; then
    listeners="$(ss -ltn 2>/dev/null | awk -v p=":"$host_port'$' '$4 ~ p {print $4}')"
  elif command -v netstat >/dev/null 2>&1; then
    listeners="$(netstat -ltn 2>/dev/null | awk -v p=":"$host_port'$' '$4 ~ p {print $4}')"
  fi
  local addr
  while IFS= read -r addr; do
    [[ -n "$addr" ]] || continue
    case "$addr" in
      127.0.0.1:*|127.*:*|\[::1\]:*|::1:*)
        continue
        ;;
      0.0.0.0:*|\[::\]:*|\*:*)
        echo "[error] security:SEC_CRIT_ODOO_PUBLIC_PORT: listener ${addr} is not loopback" >&2
        return 1
        ;;
      *)
        # Non-loopback explicit bind (e.g. public NIC IP)
        if [[ "$addr" != 127.* && "$addr" != ::1* && "$addr" != \[::1\]* ]]; then
          echo "[error] security:SEC_CRIT_ODOO_PUBLIC_PORT: listener ${addr} is not loopback" >&2
          return 1
        fi
        ;;
    esac
  done <<<"$listeners"
  return 0
}

# --- end security/platform/odoo_exposure.sh ---

# --- begin security/platform/docker_containment.sh ---
# shellcheck shell=bash
# Security Gate S1 — Docker container baseline containment.

soviez_sec_docker_mounts_include_docker_sock() {
  local container="$1"
  python3 - "$container" <<'PY'
import json, subprocess, sys
cid = sys.argv[1]
raw = subprocess.check_output(["docker", "inspect", cid], text=True)
data = json.loads(raw)[0]
mounts = data.get("Mounts") or []
binds = ((data.get("HostConfig") or {}).get("Binds")) or []
for m in mounts:
    src = (m.get("Source") or "") + " " + (m.get("Destination") or "")
    if "docker.sock" in src:
        sys.exit(0)
for b in binds:
    if "docker.sock" in str(b):
        sys.exit(0)
sys.exit(1)
PY
}

soviez_sec_docker_assert_container_baseline() {
  local container="$1"
  local role="${2:-}"
  [[ -n "$container" ]] || { echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: container required" >&2; return 1; }
  case "$role" in
    odoo|postgres) ;;
    *) echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: role must be odoo|postgres" >&2; return 1 ;;
  esac
  if ! docker inspect "$container" >/dev/null 2>&1; then
    echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: cannot inspect ${container}" >&2
    return 1
  fi

  local privileged network_mode
  privileged="$(docker inspect -f '{{.HostConfig.Privileged}}' "$container" 2>/dev/null || echo UNKNOWN)"
  network_mode="$(docker inspect -f '{{.HostConfig.NetworkMode}}' "$container" 2>/dev/null || echo UNKNOWN)"

  if [[ "$privileged" == "UNKNOWN" || "$network_mode" == "UNKNOWN" ]]; then
    echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: docker inspect incomplete for ${container}" >&2
    return 1
  fi
  if [[ "$privileged" == "true" || "$privileged" == "True" ]]; then
    echo "[error] security:SEC_CRIT_PRIVILEGED_CONTAINER: ${role} container Privileged=true" >&2
    return 1
  fi
  if soviez_sec_docker_mounts_include_docker_sock "$container"; then
    echo "[error] security:SEC_CRIT_DOCKER_SOCKET: ${role} mounts /var/run/docker.sock" >&2
    return 1
  fi
  if [[ "$network_mode" == "host" ]]; then
    echo "[error] security:SEC_CRIT_HOST_NETWORK: ${role} NetworkMode=host" >&2
    return 1
  fi

  local links
  links="$(docker inspect -f '{{json .HostConfig.Links}}' "$container" 2>/dev/null || echo UNKNOWN)"
  if [[ "$links" == "UNKNOWN" ]]; then
    echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: Links inspect failed" >&2
    return 1
  fi
  if [[ "$links" != "null" && "$links" != "[]" && -n "$links" ]]; then
    echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: legacy Links present on ${role}: ${links}" >&2
    return 1
  fi

  # User-defined network: not only default bridge for production.
  # Allow bridge name matching soviez* or SOVIEZ_SEC_DOCKER_NETWORK.
  local mode="${SOVIEZ_SEC_MODE:-}"
  local expected_net="${SOVIEZ_SEC_DOCKER_NETWORK:-}"
  local nets
  nets="$(docker inspect -f '{{range $k,$v := .NetworkSettings.Networks}}{{$k}} {{end}}' "$container" 2>/dev/null || echo "")"
  if [[ -z "$(printf '%s' "$nets" | tr -d '[:space:]')" ]]; then
    # NetworkMode may itself be a custom network name
    if [[ "$network_mode" == "default" || "$network_mode" == "bridge" ]]; then
      if [[ "$mode" == "production" ]]; then
        echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: ${role} on default bridge in production" >&2
        return 1
      fi
    fi
  else
    local ok=0 n
    for n in $nets; do
      if [[ -n "$expected_net" && "$n" == "$expected_net" ]]; then
        ok=1
        break
      fi
      case "$n" in
        soviez*|SOVIEZ*) ok=1; break ;;
      esac
      if [[ "$n" != "bridge" && "$n" != "host" && "$n" != "none" ]]; then
        # Any non-default user-defined network is acceptable.
        ok=1
        break
      fi
    done
    if [[ "$ok" -ne 1 ]]; then
      if [[ "$mode" == "production" ]]; then
        echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: ${role} lacks user-defined/soviez network (nets=${nets})" >&2
        return 1
      fi
    fi
  fi
  return 0
}

# --- end security/platform/docker_containment.sh ---

# --- begin security/platform/odoo_defaults.sh ---
# shellcheck shell=bash
# Security Gate S1 — Odoo production conf defaults.

soviez_sec_odoo_conf_get_option() {
  local conf_path="$1" key="$2"
  [[ -f "$conf_path" ]] || return 1
  local line k v
  while IFS= read -r line || [[ -n "$line" ]]; do
    [[ "$line" =~ ^[[:space:]]*[#\;] ]] && continue
    line="${line%%#*}"
    line="${line%%;*}"
    [[ "$line" == *"="* ]] || continue
    k="${line%%=*}"
    v="${line#*=}"
    k="$(printf '%s' "$k" | sed -e 's/^[[:space:]]*//' -e 's/[[:space:]]*$//')"
    v="$(printf '%s' "$v" | sed -e 's/^[[:space:]]*//' -e 's/[[:space:]]*$//')"
    if [[ "$k" == "$key" ]]; then
      printf '%s\n' "$v"
      return 0
    fi
  done <"$conf_path"
  return 1
}

soviez_sec__odoo_conf_set_option() {
  local conf_path="$1" key="$2" value="$3"
  local tmp parent
  parent="$(dirname "$conf_path")"
  mkdir -p "$parent"
  if [[ ! -f "$conf_path" ]]; then
    printf '[options]\n%s = %s\n' "$key" "$value" >"$conf_path"
    chmod 600 "$conf_path" 2>/dev/null || true
    return 0
  fi
  tmp="$(mktemp "${TMPDIR:-/tmp}/soviez-odoo-conf.XXXXXX")"
  local line k v found=0
  while IFS= read -r line || [[ -n "$line" ]]; do
    if [[ "$line" =~ ^[[:space:]]*[#\;] ]] || [[ "$line" != *"="* ]]; then
      printf '%s\n' "$line"
      continue
    fi
    local stripped="${line%%#*}"
    stripped="${stripped%%;*}"
    k="${stripped%%=*}"
    k="$(printf '%s' "$k" | sed -e 's/^[[:space:]]*//' -e 's/[[:space:]]*$//')"
    if [[ "$k" == "$key" ]]; then
      printf '%s = %s\n' "$key" "$value"
      found=1
    else
      printf '%s\n' "$line"
    fi
  done <"$conf_path" >"$tmp"
  if [[ "$found" -eq 0 ]]; then
    printf '%s = %s\n' "$key" "$value" >>"$tmp"
  fi
  mv "$tmp" "$conf_path"
  chmod 600 "$conf_path" 2>/dev/null || true
}

soviez_sec_odoo_conf_ensure_production_defaults() {
  local conf_path="$1"
  local dbfilter="${2:-}"
  [[ -n "$conf_path" ]] || { echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: conf_path required" >&2; return 1; }
  soviez_sec__odoo_conf_set_option "$conf_path" "proxy_mode" "True"
  soviez_sec__odoo_conf_set_option "$conf_path" "list_db" "False"
  if [[ -n "$dbfilter" ]]; then
    soviez_sec__odoo_conf_set_option "$conf_path" "dbfilter" "$dbfilter"
  fi
}

soviez_sec_odoo_conf_assert_production_defaults() {
  local conf_path="$1"
  [[ -f "$conf_path" ]] || {
    echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: odoo conf missing: ${conf_path}" >&2
    return 1
  }
  local proxy list_db
  proxy="$(soviez_sec_odoo_conf_get_option "$conf_path" proxy_mode 2>/dev/null || echo "")"
  list_db="$(soviez_sec_odoo_conf_get_option "$conf_path" list_db 2>/dev/null || echo "")"
  local bad=0
  case "$(printf '%s' "$proxy" | tr '[:upper:]' '[:lower:]')" in
    true|1|yes) ;;
    *)
      echo "[error] security:SEC_CRIT_PROXY_MODE_DISABLED: proxy_mode=${proxy:-unset}" >&2
      bad=1
      ;;
  esac
  case "$(printf '%s' "$list_db" | tr '[:upper:]' '[:lower:]')" in
    false|0|no) ;;
    *)
      echo "[error] security:SEC_CRIT_LIST_DB_ENABLED: list_db=${list_db:-unset}" >&2
      bad=1
      ;;
  esac
  [[ "$bad" -eq 0 ]]
}

# --- end security/platform/odoo_defaults.sh ---

# --- begin security/platform/websocket_topology.sh ---
# shellcheck shell=bash
# Certified WebSocket topology (owner-approved multi-worker correction).
# SUPPORTED: workers calculated by sizing engine; when workers>0:
#   HTTP 127.0.0.1:8069 + gevent/evented 127.0.0.1:8072
#   Nginx / → 8069, /websocket → 8072
# Minimal hosts may fall back to workers=0 (single-process compat on 8069).

soviez_ws_certified_workers_max() {
  # No hard product cap; sizing engine decides. Report high watermark for docs.
  printf '64\n'
}

# soviez_ws_assert_odoo_conf <conf-path>
# Requires proxy_mode=True. When workers>0, gevent_port must be 8072.
soviez_ws_assert_odoo_conf() {
  local conf="${1:-}"
  [[ -f "$conf" ]] || {
    echo "SEC_HIGH_WS_CONF_MISSING conf=$conf" >&2
    return 1
  }
  if ! grep -Eiq '^[[:space:]]*proxy_mode[[:space:]]*=[[:space:]]*True' "$conf"; then
    echo "SEC_CRIT_WS_PROXY_MODE conf=$conf" >&2
    return 1
  fi
  local workers gevent
  workers="$(grep -Ei '^[[:space:]]*workers[[:space:]]*=' "$conf" | tail -1 | sed -E 's/.*=[[:space:]]*//;s/[[:space:]]*$//' || echo 0)"
  workers="${workers:-0}"
  if [[ "$workers" =~ ^[0-9]+$ ]] && (( workers > 0 )); then
    gevent="$(grep -Ei '^[[:space:]]*gevent_port[[:space:]]*=' "$conf" | tail -1 | sed -E 's/.*=[[:space:]]*//;s/[[:space:]]*$//' || echo "")"
    if [[ "$gevent" != "8072" ]]; then
      echo "SEC_CRIT_WS_GEVENT_PORT workers=$workers gevent_port=${gevent:-unset} (required 8072)" >&2
      return 1
    fi
  fi
  return 0
}

# soviez_ws_assert_nginx_snippet <conf> [expect_gevent=0|1]
# Requires /websocket + Upgrade headers. When expect_gevent=1, /websocket must target :8072.
soviez_ws_assert_nginx_snippet() {
  local conf="${1:-}"
  local expect_gevent="${2:-0}"
  [[ -f "$conf" ]] || return 1
  grep -q 'location /websocket' "$conf" || {
    echo "SEC_HIGH_WS_NGINX_MISSING_WEBSOCKET" >&2
    return 1
  }
  grep -q 'Upgrade' "$conf" || {
    echo "SEC_HIGH_WS_NGINX_MISSING_UPGRADE" >&2
    return 1
  }
  if [[ "$expect_gevent" == "1" ]]; then
    if ! grep -E 'location /websocket' -A20 "$conf" | grep -Eq '127\.0\.0\.1:8072|:8072'; then
      echo "SEC_CRIT_WS_NGINX_WEBSOCKET_NOT_8072" >&2
      return 1
    fi
  fi
  return 0
}

# Classify longpolling support for docs/tests.
soviez_ws_longpolling_status() {
  printf 'COMPATIBILITY_ROUTED\n'
}

# Expected backends for a given worker count.
soviez_ws_http_backend() {
  printf '127.0.0.1:8069\n'
}

soviez_ws_websocket_backend() {
  local workers="${1:-0}"
  if [[ "$workers" =~ ^[0-9]+$ ]] && (( workers > 0 )); then
    printf '127.0.0.1:8072\n'
  else
    printf '127.0.0.1:8069\n'
  fi
}

# --- end security/platform/websocket_topology.sh ---

# --- begin security/platform/rollback.sh ---
# shellcheck shell=bash
# Security Gate S1 — safe rollback snapshots (never restore dangerous privileges).

soviez_sec_rollback_snapshot_dir() {
  local base="${SOVIEZ_SEC_ROLLBACK_DIR:-${SOVIEZ_SEC_REPORT_DIR:-${TMPDIR:-/tmp}/soviez-sec}/rollback}"
  local stamp
  stamp="$(date -u +%Y%m%dT%H%M%SZ 2>/dev/null || date +%s)"
  local dir="${base}/${stamp}"
  mkdir -p "$dir"
  chmod 700 "$dir" 2>/dev/null || true

  local pg="${SOVIEZ_SEC_PG_CONTAINER:-}"
  local odoo="${SOVIEZ_SEC_ODOO_CONTAINER:-}"
  local admin_user="${SOVIEZ_SEC_PG_ADMIN_USER:-${SOVIEZ_PG_ADMIN_USER:-soviez_admin}}"
  local admin_pass="${SOVIEZ_SEC_PG_ADMIN_PASS:-}"
  local app_user="${SOVIEZ_SEC_PG_APP_USER:-${SOVIEZ_PG_APP_USER:-soviez_app}}"
  local conf="${SOVIEZ_SEC_ODOO_CONF:-}"

  if [[ -n "$pg" ]] && declare -F soviez_sec_pg_query_role_attrs >/dev/null 2>&1 && [[ -n "$admin_pass" ]]; then
    local attrs
    attrs="$(soviez_sec_pg_query_role_attrs "$pg" "$admin_user" "$admin_pass" "$app_user" postgres 2>/dev/null || echo "UNKNOWN,UNKNOWN,UNKNOWN,UNKNOWN,UNKNOWN")"
    python3 - "$dir/role_attrs.json" "$app_user" "$attrs" <<'PY'
import json, sys
path, user, attrs = sys.argv[1], sys.argv[2], sys.argv[3]
parts = attrs.split(",")
keys = ["rolsuper","rolcreaterole","rolcreatedb","rolreplication","rolbypassrls"]
obj = {"role": user, "attrs": {}}
for i,k in enumerate(keys):
    obj["attrs"][k] = parts[i] if i < len(parts) else "UNKNOWN"
with open(path, "w", encoding="utf-8") as f:
    json.dump(obj, f, indent=2)
    f.write("\n")
PY
  else
    printf '{"role":"%s","attrs":{"note":"unavailable"}}\n' "$app_user" >"$dir/role_attrs.json"
  fi

  if [[ -n "$pg" ]] && docker inspect "$pg" >/dev/null 2>&1; then
    docker inspect "$pg" --format '{{json .HostConfig.PortBindings}}' >"$dir/pg_port_bindings.json" 2>/dev/null || echo '{}' >"$dir/pg_port_bindings.json"
    docker inspect "$pg" --format '{{json .NetworkSettings.Ports}}' >"$dir/pg_network_ports.json" 2>/dev/null || echo '{}' >"$dir/pg_network_ports.json"
  fi
  if [[ -n "$odoo" ]] && docker inspect "$odoo" >/dev/null 2>&1; then
    docker inspect "$odoo" --format '{{json .HostConfig.PortBindings}}' >"$dir/odoo_port_bindings.json" 2>/dev/null || echo '{}' >"$dir/odoo_port_bindings.json"
    docker inspect "$odoo" --format '{{json .NetworkSettings.Ports}}' >"$dir/odoo_network_ports.json" 2>/dev/null || echo '{}' >"$dir/odoo_network_ports.json"
  fi
  if [[ -n "$conf" && -f "$conf" ]]; then
    cp -a "$conf" "$dir/odoo.conf.copy"
    chmod 600 "$dir/odoo.conf.copy" 2>/dev/null || true
  fi

  printf '%s\n' "$dir" >"$dir/SNAPSHOT_PATH"
  printf '%s\n' "$dir"
}

soviez_sec_rollback_forbidden_privilege_restore() {
  echo "[error] security:SEC_CRIT_PG_SUPERUSER: refusing privilege restore (SUPERUSER/dangerous memberships/weak passwords never restored)" >&2
  return 1
}

soviez_sec_rollback_restore_safe() {
  local snap="${1:-}"
  [[ -n "$snap" && -d "$snap" ]] || {
    echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: snapshot dir required" >&2
    return 1
  }

  # Explicitly refuse any privilege re-escalation path.
  if [[ "${SOVIEZ_SEC_ROLLBACK_ALLOW_PRIVILEGE:-0}" == "1" ]]; then
    soviez_sec_rollback_forbidden_privilege_restore
    return 1
  fi

  local conf="${SOVIEZ_SEC_ODOO_CONF:-}"
  if [[ -n "$conf" && -f "$snap/odoo.conf.copy" ]]; then
    # Restore conf only after scrubbing dangerous weak defaults is NOT done here;
    # restore connectivity-oriented options; never inject SUPERUSER markers (N/A in conf).
    mkdir -p "$(dirname "$conf")"
    cp -a "$snap/odoo.conf.copy" "$conf"
    chmod 600 "$conf" 2>/dev/null || true
    # Re-assert production defaults if helpers present (safe direction).
    if declare -F soviez_sec_odoo_conf_ensure_production_defaults >/dev/null 2>&1; then
      local dbfilter=""
      dbfilter="$(soviez_sec_odoo_conf_get_option "$conf" dbfilter 2>/dev/null || true)"
      soviez_sec_odoo_conf_ensure_production_defaults "$conf" "$dbfilter"
    fi
  fi

  # Port binding / connectivity note: docker port republish requires recreate; record intent only.
  if [[ -f "$snap/odoo_port_bindings.json" ]]; then
    cp -a "$snap/odoo_port_bindings.json" "${SOVIEZ_SEC_REPORT_DIR:-$snap}/restore_odoo_port_bindings.intent.json" 2>/dev/null || true
  fi
  if [[ -f "$snap/pg_port_bindings.json" ]]; then
    # Never restore a public 5432 publish even if snapshot had one.
    if grep -Eq '0\.0\.0\.0|"HostIp": ?""|"HostIp":null' "$snap/pg_port_bindings.json" 2>/dev/null; then
      echo "[warn] security: refusing to restore public PG publish from snapshot" >&2
    else
      cp -a "$snap/pg_port_bindings.json" "${SOVIEZ_SEC_REPORT_DIR:-$snap}/restore_pg_port_bindings.intent.json" 2>/dev/null || true
    fi
  fi

  # NEVER restore SUPERUSER / dangerous memberships / weak passwords from role_attrs.json
  if [[ -f "$snap/role_attrs.json" ]]; then
    if python3 - "$snap/role_attrs.json" <<'PY'
import json,sys
obj=json.load(open(sys.argv[1],encoding="utf-8"))
attrs=(obj.get("attrs") or {})
dangerous=False
for k in ("rolsuper","rolcreaterole","rolreplication","rolbypassrls"):
    v=str(attrs.get(k,"")).lower()
    if v in ("t","true","1","yes"):
        dangerous=True
if dangerous:
    sys.exit(2)
sys.exit(0)
PY
    then
      :
    else
      rc=$?
      if [[ $rc -eq 2 ]]; then
        soviez_sec_rollback_forbidden_privilege_restore
        return 1
      fi
    fi
  fi
  return 0
}

# --- end security/platform/rollback.sh ---

# --- begin security/platform/remediate_existing.sh ---
# shellcheck shell=bash
# Security Gate S1 — remediate existing app roles (never re-grant SUPERUSER on failure).

soviez_sec_remediate_existing_app_role() {
  local container="${1:-${SOVIEZ_SEC_PG_CONTAINER:-}}"
  local admin_user="${2:-${SOVIEZ_SEC_PG_ADMIN_USER:-${SOVIEZ_PG_ADMIN_USER:-soviez_admin}}}"
  local admin_pass="${3:-${SOVIEZ_SEC_PG_ADMIN_PASS:-}}"
  local app_user="${4:-${SOVIEZ_SEC_PG_APP_USER:-${SOVIEZ_PG_APP_USER:-soviez_app}}}"
  local database="${5:-postgres}"

  [[ -n "$container" ]] || { echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: pg container required" >&2; return 1; }
  [[ -n "$admin_pass" ]] || { echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: admin pass required for remediation" >&2; return 1; }

  local snap=""
  if declare -F soviez_sec_rollback_snapshot_dir >/dev/null 2>&1; then
    snap="$(soviez_sec_rollback_snapshot_dir)" || true
  fi

  local iduser
  iduser="$(soviez_sec_pg_ident_quote "$app_user")"

  # Strip dangerous attributes. On any failure: do NOT grant SUPERUSER back.
  if ! docker exec -e PGPASSWORD="$admin_pass" "$container" \
    psql -v ON_ERROR_STOP=1 -U "$admin_user" -d "$database" \
    -c "ALTER ROLE ${iduser} NOSUPERUSER NOCREATEROLE NOCREATEDB NOREPLICATION NOBYPASSRLS;" >/dev/null; then
    echo "[error] security:SEC_CRIT_PG_SUPERUSER: ALTER ROLE strip failed for ${app_user} (no privilege re-grant)" >&2
    return 1
  fi

  if declare -F soviez_sec_pg_revoke_dangerous_memberships >/dev/null 2>&1; then
    soviez_sec_pg_revoke_dangerous_memberships "$container" "$admin_user" "$admin_pass" "$app_user" "$database" || true
  fi

  if declare -F soviez_sec_pg_assert_app_role_safe >/dev/null 2>&1; then
    if ! soviez_sec_pg_assert_app_role_safe "$container" "$admin_user" "$admin_pass" "$app_user" "$database"; then
      echo "[error] security:SEC_CRIT_PG_SUPERUSER: post-remediation assert failed (no SUPERUSER re-grant); snap=${snap:-none}" >&2
      return 1
    fi
  fi
  return 0
}

# --- end security/platform/remediate_existing.sh ---

# --- begin security/platform/critical_gate.sh ---
# shellcheck shell=bash
# Security Gate S1 — fail-closed critical containment gate.

soviez_sec__gate_add() {
  local key="$1" rstatus="$2" detail="${3:-}"
  if declare -F soviez_sec_report_add >/dev/null 2>&1; then
    soviez_sec_report_add "$key" "$rstatus" "$detail"
  else
    echo "[security] ${key}: ${rstatus} — ${detail}" >&2
  fi
}

soviez_sec__gate_check_bool() {
  # usage: soviez_sec__gate_check_bool KEY PASS_MSG FAIL_CODE FAIL_MSG cmd...
  local key="$1" pass_msg="$2" fail_code="$3" fail_msg="$4"
  shift 4
  local out rc
  set +e
  out="$("$@" 2>&1)"
  rc=$?
  set -e
  if [[ $rc -eq 0 ]]; then
    soviez_sec__gate_add "$key" PASS "$pass_msg"
    return 0
  fi
  if [[ "$out" == *SEC_CRIT_SECURITY_STATE_UNKNOWN* || "$out" == *UNKNOWN* ]]; then
    soviez_sec__gate_add "$key" UNKNOWN "${fail_msg}: ${out}"
  else
    soviez_sec__gate_add "$key" FAIL "${fail_code}: ${fail_msg}: ${out}"
  fi
  return 1
}

soviez_security_validate_critical_containment() {
  local mode="${SOVIEZ_SEC_MODE:-production}"
  local pg="${SOVIEZ_SEC_PG_CONTAINER:-}"
  local odoo="${SOVIEZ_SEC_ODOO_CONTAINER:-}"
  local admin_user="${SOVIEZ_SEC_PG_ADMIN_USER:-${SOVIEZ_PG_ADMIN_USER:-soviez_admin}}"
  local admin_pass="${SOVIEZ_SEC_PG_ADMIN_PASS:-}"
  local app_user="${SOVIEZ_SEC_PG_APP_USER:-${SOVIEZ_PG_APP_USER:-soviez_app}}"
  local app_pass="${SOVIEZ_SEC_PG_APP_PASS:-}"
  local conf="${SOVIEZ_SEC_ODOO_CONF:-}"
  local require_https="${SOVIEZ_SEC_REQUIRE_HTTPS:-0}"
  local domain="${SOVIEZ_SEC_DOMAIN:-}"
  local proxy_url="${SOVIEZ_SEC_PROXY_URL:-}"
  local report_dir="${SOVIEZ_SEC_REPORT_DIR:-}"

  case "$mode" in
    production|stage|update) ;;
    *)
      echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: invalid SOVIEZ_SEC_MODE=${mode}" >&2
      return 1
      ;;
  esac

  if declare -F soviez_sec_report_init >/dev/null 2>&1; then
    soviez_sec_report_init "$report_dir"
  fi

  local overall_rc=0

  # --- PG role attrs ---
  if [[ -n "$pg" && -n "$admin_pass" ]] && docker inspect "$pg" >/dev/null 2>&1; then
    local attrs
    if attrs="$(soviez_sec_pg_query_role_attrs "$pg" "$admin_user" "$admin_pass" "$app_user" postgres 2>/dev/null)"; then
      local rolsuper rolcreaterole rolcreatedb rolreplication rolbypassrls
      IFS=',' read -r rolsuper rolcreaterole rolcreatedb rolreplication rolbypassrls <<<"$attrs"
      case "$rolsuper" in
        f|false|FALSE|0|no|NO) soviez_sec__gate_add PG_APP_NOT_SUPERUSER PASS "rolsuper=f" ;;
        t|true|TRUE|1) soviez_sec__gate_add PG_APP_NOT_SUPERUSER FAIL "SEC_CRIT_PG_SUPERUSER"; overall_rc=1 ;;
        *) soviez_sec__gate_add PG_APP_NOT_SUPERUSER UNKNOWN "SEC_CRIT_SECURITY_STATE_UNKNOWN rolsuper=${rolsuper}"; overall_rc=1 ;;
      esac
      case "$rolcreaterole" in
        f|false|FALSE|0|no|NO) soviez_sec__gate_add NO_CREATEROLE PASS "rolcreaterole=f" ;;
        t|true|TRUE|1) soviez_sec__gate_add NO_CREATEROLE FAIL "SEC_CRIT_PG_CREATEROLE"; overall_rc=1 ;;
        *) soviez_sec__gate_add NO_CREATEROLE UNKNOWN "SEC_CRIT_SECURITY_STATE_UNKNOWN"; overall_rc=1 ;;
      esac
      case "$rolreplication" in
        f|false|FALSE|0|no|NO) soviez_sec__gate_add NO_REPLICATION PASS "rolreplication=f" ;;
        t|true|TRUE|1) soviez_sec__gate_add NO_REPLICATION FAIL "SEC_CRIT_PG_REPLICATION"; overall_rc=1 ;;
        *) soviez_sec__gate_add NO_REPLICATION UNKNOWN "SEC_CRIT_SECURITY_STATE_UNKNOWN"; overall_rc=1 ;;
      esac
      case "$rolbypassrls" in
        f|false|FALSE|0|no|NO) soviez_sec__gate_add NO_BYPASSRLS PASS "rolbypassrls=f" ;;
        t|true|TRUE|1) soviez_sec__gate_add NO_BYPASSRLS FAIL "SEC_CRIT_PG_BYPASSRLS"; overall_rc=1 ;;
        *) soviez_sec__gate_add NO_BYPASSRLS UNKNOWN "SEC_CRIT_SECURITY_STATE_UNKNOWN"; overall_rc=1 ;;
      esac
    else
      soviez_sec__gate_add PG_APP_NOT_SUPERUSER UNKNOWN "SEC_CRIT_SECURITY_STATE_UNKNOWN cannot query"
      soviez_sec__gate_add NO_CREATEROLE UNKNOWN "SEC_CRIT_SECURITY_STATE_UNKNOWN"
      soviez_sec__gate_add NO_REPLICATION UNKNOWN "SEC_CRIT_SECURITY_STATE_UNKNOWN"
      soviez_sec__gate_add NO_BYPASSRLS UNKNOWN "SEC_CRIT_SECURITY_STATE_UNKNOWN"
      overall_rc=1
    fi

    local memberships
    memberships="$(soviez_sec_pg_query_dangerous_memberships "$pg" "$admin_user" "$admin_pass" "$app_user" postgres 2>/dev/null || echo UNKNOWN)"
    if [[ "$memberships" == "UNKNOWN" ]]; then
      soviez_sec__gate_add NO_DANGEROUS_MEMBERSHIPS UNKNOWN "SEC_CRIT_SECURITY_STATE_UNKNOWN"
      overall_rc=1
    elif [[ -z "$memberships" ]]; then
      soviez_sec__gate_add NO_DANGEROUS_MEMBERSHIPS PASS "none"
    else
      [[ "$memberships" == *pg_execute_server_program* ]] && soviez_sec__gate_add NO_DANGEROUS_MEMBERSHIPS FAIL "SEC_CRIT_PG_EXECUTE_SERVER_PROGRAM" && overall_rc=1
      [[ "$memberships" == *pg_read_server_files* ]] && soviez_sec__gate_add NO_DANGEROUS_MEMBERSHIPS FAIL "SEC_CRIT_PG_READ_SERVER_FILES" && overall_rc=1
      [[ "$memberships" == *pg_write_server_files* ]] && soviez_sec__gate_add NO_DANGEROUS_MEMBERSHIPS FAIL "SEC_CRIT_PG_WRITE_SERVER_FILES" && overall_rc=1
      if [[ "$memberships" != *pg_* ]]; then
        soviez_sec__gate_add NO_DANGEROUS_MEMBERSHIPS FAIL "unexpected memberships"
        overall_rc=1
      fi
    fi
  else
    soviez_sec__gate_add PG_APP_NOT_SUPERUSER UNKNOWN "SEC_CRIT_SECURITY_STATE_UNKNOWN pg/admin unavailable"
    soviez_sec__gate_add NO_CREATEROLE UNKNOWN "SEC_CRIT_SECURITY_STATE_UNKNOWN"
    soviez_sec__gate_add NO_REPLICATION UNKNOWN "SEC_CRIT_SECURITY_STATE_UNKNOWN"
    soviez_sec__gate_add NO_BYPASSRLS UNKNOWN "SEC_CRIT_SECURITY_STATE_UNKNOWN"
    soviez_sec__gate_add NO_DANGEROUS_MEMBERSHIPS UNKNOWN "SEC_CRIT_SECURITY_STATE_UNKNOWN"
    overall_rc=1
  fi

  # --- PG public port ---
  if [[ -n "$pg" ]] && docker inspect "$pg" >/dev/null 2>&1; then
    if soviez_sec_pg_assert_no_public_publish "$pg" 2>/dev/null; then
      soviez_sec__gate_add PG_PUBLIC_PORT_ABSENT PASS "no public 5432"
    else
      soviez_sec__gate_add PG_PUBLIC_PORT_ABSENT FAIL "SEC_CRIT_PG_PUBLIC_PORT"
      overall_rc=1
    fi
  else
    soviez_sec__gate_add PG_PUBLIC_PORT_ABSENT UNKNOWN "SEC_CRIT_SECURITY_STATE_UNKNOWN"
    overall_rc=1
  fi

  # --- Odoo public ports ---
  if [[ -n "$odoo" ]] && docker inspect "$odoo" >/dev/null 2>&1; then
    if soviez_sec_odoo_assert_no_public_direct_ports "$odoo" 2>/dev/null; then
      soviez_sec__gate_add ODOO_DIRECT_PUBLIC_PORT_ABSENT PASS "no public 8069/8071/8072"
    else
      soviez_sec__gate_add ODOO_DIRECT_PUBLIC_PORT_ABSENT FAIL "SEC_CRIT_ODOO_PUBLIC_PORT"
      overall_rc=1
    fi
  else
    soviez_sec__gate_add ODOO_DIRECT_PUBLIC_PORT_ABSENT UNKNOWN "SEC_CRIT_SECURITY_STATE_UNKNOWN"
    overall_rc=1
  fi

  # --- Docker baselines ---
  if [[ -n "$odoo" ]] && docker inspect "$odoo" >/dev/null 2>&1; then
    if soviez_sec_docker_assert_container_baseline "$odoo" odoo 2>/dev/null; then
      soviez_sec__gate_add ODOO_PRIVILEGED_FALSE PASS "baseline ok"
      soviez_sec__gate_add DOCKER_SOCKET_NOT_MOUNTED PASS "odoo"
      soviez_sec__gate_add HOST_NETWORK_NOT_USED PASS "odoo"
    else
      local priv sock hostn
      priv="$(docker inspect -f '{{.HostConfig.Privileged}}' "$odoo" 2>/dev/null || echo UNKNOWN)"
      hostn="$(docker inspect -f '{{.HostConfig.NetworkMode}}' "$odoo" 2>/dev/null || echo UNKNOWN)"
      if [[ "$priv" == "true" ]]; then
        soviez_sec__gate_add ODOO_PRIVILEGED_FALSE FAIL "SEC_CRIT_PRIVILEGED_CONTAINER"
      elif [[ "$priv" == "UNKNOWN" ]]; then
        soviez_sec__gate_add ODOO_PRIVILEGED_FALSE UNKNOWN "SEC_CRIT_SECURITY_STATE_UNKNOWN"
      else
        soviez_sec__gate_add ODOO_PRIVILEGED_FALSE PASS "Privileged=false"
      fi
      if soviez_sec_docker_mounts_include_docker_sock "$odoo" 2>/dev/null; then
        soviez_sec__gate_add DOCKER_SOCKET_NOT_MOUNTED FAIL "SEC_CRIT_DOCKER_SOCKET"
      else
        soviez_sec__gate_add DOCKER_SOCKET_NOT_MOUNTED PASS "odoo"
      fi
      if [[ "$hostn" == "host" ]]; then
        soviez_sec__gate_add HOST_NETWORK_NOT_USED FAIL "SEC_CRIT_HOST_NETWORK"
      elif [[ "$hostn" == "UNKNOWN" ]]; then
        soviez_sec__gate_add HOST_NETWORK_NOT_USED UNKNOWN "SEC_CRIT_SECURITY_STATE_UNKNOWN"
      else
        soviez_sec__gate_add HOST_NETWORK_NOT_USED PASS "odoo"
      fi
      overall_rc=1
    fi
  else
    soviez_sec__gate_add ODOO_PRIVILEGED_FALSE UNKNOWN "SEC_CRIT_SECURITY_STATE_UNKNOWN"
    soviez_sec__gate_add DOCKER_SOCKET_NOT_MOUNTED UNKNOWN "SEC_CRIT_SECURITY_STATE_UNKNOWN"
    soviez_sec__gate_add HOST_NETWORK_NOT_USED UNKNOWN "SEC_CRIT_SECURITY_STATE_UNKNOWN"
    overall_rc=1
  fi

  if [[ -n "$pg" ]] && docker inspect "$pg" >/dev/null 2>&1; then
    if soviez_sec_docker_assert_container_baseline "$pg" postgres 2>/dev/null; then
      soviez_sec__gate_add POSTGRES_PRIVILEGED_FALSE PASS "baseline ok"
    else
      local ppriv
      ppriv="$(docker inspect -f '{{.HostConfig.Privileged}}' "$pg" 2>/dev/null || echo UNKNOWN)"
      if [[ "$ppriv" == "true" ]]; then
        soviez_sec__gate_add POSTGRES_PRIVILEGED_FALSE FAIL "SEC_CRIT_PRIVILEGED_CONTAINER"
      elif [[ "$ppriv" == "UNKNOWN" ]]; then
        soviez_sec__gate_add POSTGRES_PRIVILEGED_FALSE UNKNOWN "SEC_CRIT_SECURITY_STATE_UNKNOWN"
      else
        soviez_sec__gate_add POSTGRES_PRIVILEGED_FALSE FAIL "postgres baseline failed"
      fi
      if soviez_sec_docker_mounts_include_docker_sock "$pg" 2>/dev/null; then
        soviez_sec__gate_add DOCKER_SOCKET_NOT_MOUNTED FAIL "SEC_CRIT_DOCKER_SOCKET postgres"
      fi
      overall_rc=1
    fi
  else
    soviez_sec__gate_add POSTGRES_PRIVILEGED_FALSE UNKNOWN "SEC_CRIT_SECURITY_STATE_UNKNOWN"
    overall_rc=1
  fi

  # --- Odoo conf defaults ---
  if [[ -n "$conf" && -f "$conf" ]]; then
    if soviez_sec_odoo_conf_assert_production_defaults "$conf" 2>/dev/null; then
      soviez_sec__gate_add ODOO_PROXY_MODE_TRUE PASS "proxy_mode=True"
      soviez_sec__gate_add ODOO_LIST_DB_FALSE PASS "list_db=False"
    else
      local proxy list_db
      proxy="$(soviez_sec_odoo_conf_get_option "$conf" proxy_mode 2>/dev/null || echo unset)"
      list_db="$(soviez_sec_odoo_conf_get_option "$conf" list_db 2>/dev/null || echo unset)"
      case "$(printf '%s' "$proxy" | tr '[:upper:]' '[:lower:]')" in
        true|1|yes) soviez_sec__gate_add ODOO_PROXY_MODE_TRUE PASS ;;
        *) soviez_sec__gate_add ODOO_PROXY_MODE_TRUE FAIL "SEC_CRIT_PROXY_MODE_DISABLED proxy_mode=${proxy}"; overall_rc=1 ;;
      esac
      case "$(printf '%s' "$list_db" | tr '[:upper:]' '[:lower:]')" in
        false|0|no) soviez_sec__gate_add ODOO_LIST_DB_FALSE PASS ;;
        *) soviez_sec__gate_add ODOO_LIST_DB_FALSE FAIL "SEC_CRIT_LIST_DB_ENABLED list_db=${list_db}"; overall_rc=1 ;;
      esac
    fi
  else
    soviez_sec__gate_add ODOO_PROXY_MODE_TRUE UNKNOWN "SEC_CRIT_SECURITY_STATE_UNKNOWN conf missing"
    soviez_sec__gate_add ODOO_LIST_DB_FALSE UNKNOWN "SEC_CRIT_SECURITY_STATE_UNKNOWN conf missing"
    overall_rc=1
  fi

  # --- Weak credentials (env) ---
  local weak_hit=0
  local candidate
  for candidate in \
    "${SOVIEZ_APP_PASSWORD:-}" \
    "${SOVIEZ_ADMIN_PASSWORD:-}" \
    "${SOVIEZ_SEC_PG_APP_PASS:-}" \
    "${admin_pass}"; do
    [[ -n "$candidate" ]] || continue
    if declare -F soviez_sec_password_is_weak >/dev/null 2>&1 && soviez_sec_password_is_weak "$candidate"; then
      weak_hit=1
    fi
  done
  if [[ "$weak_hit" -eq 1 ]]; then
    soviez_sec__gate_add WEAK_DEFAULT_CREDENTIALS_ABSENT FAIL "SEC_CRIT_WEAK_ADMIN_CREDENTIAL"
    overall_rc=1
  else
    soviez_sec__gate_add WEAK_DEFAULT_CREDENTIALS_ABSENT PASS "no weak env credentials detected"
  fi

  # Bootstrap secret must not appear as Odoo env (best-effort inspect).
  if [[ -n "$odoo" && -n "$admin_pass" ]] && docker inspect "$odoo" >/dev/null 2>&1; then
    local env_blob
    env_blob="$(docker inspect -f '{{range .Config.Env}}{{println .}}{{end}}' "$odoo" 2>/dev/null || true)"
    if [[ -n "$env_blob" && -n "$admin_pass" ]] && printf '%s' "$env_blob" | grep -Fq -- "$admin_pass"; then
      soviez_sec__gate_add BOOTSTRAP_SECRET_NOT_IN_ODOO FAIL "SEC_CRIT_BOOTSTRAP_SECRET_IN_ODOO"
      overall_rc=1
    else
      soviez_sec__gate_add BOOTSTRAP_SECRET_NOT_IN_ODOO PASS "bootstrap secret not found in odoo env"
    fi
  else
    soviez_sec__gate_add BOOTSTRAP_SECRET_NOT_IN_ODOO SKIP "odoo/admin unavailable"
  fi

  # --- Optional DB reachability (prefer app DB; fall back to postgres) ---
  if [[ -n "$pg" && -n "$app_user" && -n "$app_pass" ]] && docker inspect "$pg" >/dev/null 2>&1; then
    local reach_db="${SOVIEZ_SEC_PG_DB:-postgres}"
    if docker exec -e PGPASSWORD="$app_pass" "$pg" \
      psql -U "$app_user" -d "$reach_db" -tAc 'SELECT 1' >/dev/null 2>&1 \
      || docker exec -e PGPASSWORD="$app_pass" "$pg" \
        psql -U "$app_user" -d postgres -tAc 'SELECT 1' >/dev/null 2>&1; then
      soviez_sec__gate_add ODOO_DB_REACHABLE PASS "app role connected"
    else
      soviez_sec__gate_add ODOO_DB_REACHABLE FAIL "SEC_HIGH_INTERNAL_DB_UNREACHABLE"
      # HIGH — still fail-closed for gate overall when containers claimed up
      overall_rc=1
    fi
  else
    soviez_sec__gate_add ODOO_DB_REACHABLE SKIP "optional; credentials/containers not fully provided"
  fi

  # --- Reverse proxy / HTTPS ---
  if [[ "$mode" == "production" && "$require_https" == "1" ]]; then
    local url="${proxy_url}"
    if [[ -z "$url" && -n "$domain" ]]; then
      url="https://${domain}/"
    fi
    if [[ -z "$url" ]]; then
      soviez_sec__gate_add REVERSE_PROXY_REACHABLE UNKNOWN "SEC_CRIT_SECURITY_STATE_UNKNOWN no proxy url/domain"
      soviez_sec__gate_add HTTPS_REQUIRED UNKNOWN "SEC_CRIT_SECURITY_STATE_UNKNOWN"
      overall_rc=1
    else
      local curl_rc=1
      if command -v curl >/dev/null 2>&1; then
        set +e
        curl -fsS --max-time 10 "$url" >/dev/null 2>&1
        curl_rc=$?
        set -e
      elif command -v wget >/dev/null 2>&1; then
        set +e
        wget -q -O /dev/null --timeout=10 "$url" >/dev/null 2>&1
        curl_rc=$?
        set -e
      else
        soviez_sec__gate_add REVERSE_PROXY_REACHABLE UNKNOWN "SEC_CRIT_SECURITY_STATE_UNKNOWN no curl/wget"
        soviez_sec__gate_add HTTPS_REQUIRED UNKNOWN "SEC_CRIT_SECURITY_STATE_UNKNOWN"
        overall_rc=1
        curl_rc=2
      fi
      if [[ $curl_rc -eq 0 ]]; then
        soviez_sec__gate_add REVERSE_PROXY_REACHABLE PASS "$url"
        case "$url" in
          https://*) soviez_sec__gate_add HTTPS_REQUIRED PASS ;;
          *) soviez_sec__gate_add HTTPS_REQUIRED FAIL "SEC_HIGH_REVERSE_PROXY_UNREACHABLE non-https url"; overall_rc=1 ;;
        esac
      elif [[ $curl_rc -ne 2 ]]; then
        soviez_sec__gate_add REVERSE_PROXY_REACHABLE FAIL "SEC_HIGH_REVERSE_PROXY_UNREACHABLE"
        soviez_sec__gate_add HTTPS_REQUIRED FAIL "SEC_HIGH_REVERSE_PROXY_UNREACHABLE"
        overall_rc=1
      fi
    fi
  else
    soviez_sec__gate_add REVERSE_PROXY_REACHABLE SKIP "not required for mode=${mode} https=${require_https}"
    soviez_sec__gate_add HTTPS_REQUIRED SKIP "not required"
  fi

  local final="FAIL"
  if declare -F soviez_sec_report_finalize >/dev/null 2>&1; then
    if final="$(soviez_sec_report_finalize)"; then
      :
    else
      final="FAIL"
      overall_rc=1
    fi
  else
    [[ "$overall_rc" -eq 0 ]] && final="PASS"
  fi

  if [[ "$final" == "PASS" && "$overall_rc" -eq 0 ]]; then
    echo "[security] SEC_OK_CRITICAL_CONTAINMENT"
    return 0
  fi
  return 1
}

soviez_security_gate_require_pass() {
  if soviez_security_validate_critical_containment "$@"; then
    return 0
  fi
  if declare -F soviez_security_die >/dev/null 2>&1; then
    soviez_security_die SEC_CRIT_SECURITY_STATE_UNKNOWN "critical containment gate failed (fail-closed)"
  fi
  echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: critical containment gate failed (fail-closed)" >&2
  return 1
}

# --- end security/platform/critical_gate.sh ---

# --- begin security/platform/firewall.sh ---
# shellcheck shell=bash
# Security Gate S2 — firewall backend detection & abstraction.
# NEVER flush/reset production firewalls (iptables -F, nft flush, ufw reset, etc.).

SOVIEZ_FW_BACKEND="${SOVIEZ_FW_BACKEND:-}"
SOVIEZ_FW_MARKER="# SOVIEZ_OWNED firewall policy — Security Gate S2"
SOVIEZ_FW_SNAPSHOT_DIR="${SOVIEZ_FW_SNAPSHOT_DIR:-}"

soviez_fw_detect_backend() {
  # Prefer active manager; do not install competitors.
  local backend="none"
  if command -v ufw >/dev/null 2>&1; then
    local st
    st="$(ufw status 2>/dev/null | head -1 || true)"
    if echo "$st" | grep -Eqi 'Status:[[:space:]]*active' || [[ "${SOVIEZ_FW_PREFER_UFW:-0}" == "1" ]]; then
      backend="ufw"
    elif echo "$st" | grep -Eqi 'Status:[[:space:]]*inactive' && [[ -z "$(command -v firewall-cmd 2>/dev/null || true)" ]]; then
      backend="ufw"
    fi
  fi
  if [[ "$backend" == "none" ]] && command -v firewall-cmd >/dev/null 2>&1; then
    if firewall-cmd --state >/dev/null 2>&1 || [[ "${SOVIEZ_FW_PREFER_FIREWALLD:-0}" == "1" ]]; then
      backend="firewalld"
    fi
  fi
  if [[ "$backend" == "none" ]] && command -v nft >/dev/null 2>&1; then
    if nft list ruleset >/dev/null 2>&1; then
      backend="nftables"
    fi
  fi
  if [[ "$backend" == "none" ]] && command -v iptables >/dev/null 2>&1; then
    backend="iptables"
  fi
  SOVIEZ_FW_BACKEND="$backend"
  export SOVIEZ_FW_BACKEND
  printf '%s\n' "$backend"
}

soviez_fw_assert_no_destructive_ops() {
  # Static guard used by tests and dual-installer asserts.
  # Flags real invocations only — not detection string literals / comments.
  local path="$1"
  local bad=0
  local line
  while IFS= read -r line; do
    [[ "$line" =~ ^[[:space:]]*# ]] && continue
    # Skip pure detection / comparison / error-message lines.
    if [[ "$line" == *'[['* || "$line" == *'grep'* || "$line" == *'FORBIDDEN'* || "$line" == *'assert'* || "$line" == *'echo '* ]]; then
      continue
    fi
    if [[ "$line" =~ (^|[[:space:];])iptables[[:space:]]+-F($|[[:space:]]) ]] || \
       [[ "$line" =~ (^|[[:space:];])iptables[[:space:]]+-X($|[[:space:]]) ]] || \
       [[ "$line" == *'nft flush ruleset'* ]]; then
      echo "[error] security:SEC_CRIT_FIREWALL_STATE_UNKNOWN: destructive firewall op in ${path}: ${line}" >&2
      bad=1
    fi
    if [[ "$line" =~ (^|[[:space:];])ufw[[:space:]]+(--force[[:space:]]+)?reset($|[[:space:]]) ]]; then
      echo "[error] security:SEC_CRIT_FIREWALL_STATE_UNKNOWN: ufw reset in ${path}" >&2
      bad=1
    fi
    if [[ "$line" == *'firewall-cmd --complete-reload'* ]]; then
      echo "[error] security:SEC_CRIT_FIREWALL_STATE_UNKNOWN: complete-reload in ${path}" >&2
      bad=1
    fi
  done < "$path"
  [[ "$bad" -eq 0 ]]
}

soviez_fw_snapshot() {
  local dir="${1:-${SOVIEZ_FW_SNAPSHOT_DIR:-}}"
  local backend="${2:-${SOVIEZ_FW_BACKEND:-}}"
  [[ -n "$backend" ]] || backend="$(soviez_fw_detect_backend)"
  if [[ -z "$dir" ]]; then
    dir="${TMPDIR:-/tmp}/soviez-fw-snap-$$"
  fi
  mkdir -p "$dir"
  chmod 700 "$dir" 2>/dev/null || true
  SOVIEZ_FW_SNAPSHOT_DIR="$dir"
  export SOVIEZ_FW_SNAPSHOT_DIR
  printf '%s\n' "$backend" >"$dir/backend"
  case "$backend" in
    ufw)
      ufw status verbose >"$dir/ufw.status" 2>&1 || true
      ufw status numbered >"$dir/ufw.numbered" 2>&1 || true
      ;;
    firewalld)
      firewall-cmd --list-all >"$dir/firewalld.list" 2>&1 || true
      ;;
    nftables)
      nft list ruleset >"$dir/nft.ruleset" 2>&1 || true
      ;;
    iptables)
      iptables-save >"$dir/iptables.save" 2>&1 || true
      iptables -L DOCKER-USER -n -v >"$dir/docker-user.chain" 2>&1 || true
      ;;
    none)
      echo "none" >"$dir/note"
      ;;
  esac
  # Always capture Docker publish + DOCKER-USER if present (non-destructive).
  if command -v iptables >/dev/null 2>&1; then
    iptables -L DOCKER-USER -n -v >"$dir/docker-user.chain" 2>&1 || echo "DOCKER-USER absent" >"$dir/docker-user.chain"
  fi
  if command -v docker >/dev/null 2>&1; then
    docker ps --format '{{.Names}} {{.Ports}}' >"$dir/docker.ports" 2>&1 || true
  fi
  printf '%s\n' "$dir"
}

soviez_fw_apply_soviez_policy() {
  local backend="${1:-${SOVIEZ_FW_BACKEND:-}}"
  [[ -n "$backend" ]] || backend="$(soviez_fw_detect_backend)"
  local ssh_port="${SOVIEZ_SSH_PORT:-22}"
  case "$backend" in
    ufw)
      declare -F soviez_fw_ufw_apply >/dev/null 2>&1 && soviez_fw_ufw_apply "$ssh_port"
      ;;
    firewalld)
      declare -F soviez_fw_firewalld_apply >/dev/null 2>&1 && soviez_fw_firewalld_apply "$ssh_port"
      ;;
    nftables)
      declare -F soviez_fw_nft_apply >/dev/null 2>&1 && soviez_fw_nft_apply "$ssh_port"
      ;;
    iptables)
      declare -F soviez_fw_iptables_apply >/dev/null 2>&1 && soviez_fw_iptables_apply "$ssh_port"
      ;;
    none)
      echo "[security] FIREWALL_BACKEND=none — policy apply skipped (report only)" >&2
      return 0
      ;;
    *)
      echo "[error] security:SEC_CRIT_FIREWALL_STATE_UNKNOWN: unsupported backend ${backend}" >&2
      return 1
      ;;
  esac
  # Docker-aware containment (DOCKER-USER) when iptables present.
  if declare -F soviez_fw_docker_apply_user_chain >/dev/null 2>&1; then
    soviez_fw_docker_apply_user_chain || true
  fi
}

soviez_fw_validate() {
  local backend="${1:-${SOVIEZ_FW_BACKEND:-}}"
  [[ -n "$backend" ]] || backend="$(soviez_fw_detect_backend)"
  # Required: SSH/80/443 intent recorded; dangerous ports not explicitly allowed publicly by Soviez markers.
  case "$backend" in
    ufw)
      local st
      st="$(ufw status 2>/dev/null || true)"
      if echo "$st" | head -1 | grep -Eqi 'Status:[[:space:]]*(active|inactive)'; then
        :
      else
        echo "[error] security:SEC_CRIT_FIREWALL_STATE_UNKNOWN: cannot read ufw" >&2
        return 1
      fi
      ;;
    firewalld|nftables|iptables|none) ;;
    *)
      echo "[error] security:SEC_CRIT_FIREWALL_STATE_UNKNOWN: backend=${backend}" >&2
      return 1
      ;;
  esac
  return 0
}

soviez_fw_rollback() {
  local dir="${1:-${SOVIEZ_FW_SNAPSHOT_DIR:-}}"
  [[ -n "$dir" && -d "$dir" ]] || {
    echo "[error] security:SEC_CRIT_FIREWALL_STATE_UNKNOWN: no firewall snapshot" >&2
    return 1
  }
  local backend
  backend="$(cat "$dir/backend" 2>/dev/null || echo none)"
  # Rollback restores recorded allow rules only; never re-opens 8069/5432.
  case "$backend" in
    ufw)
      if declare -F soviez_fw_ufw_rollback >/dev/null 2>&1; then
        soviez_fw_ufw_rollback "$dir"
      fi
      ;;
    *)
      echo "[security] firewall rollback best-effort for backend=${backend}" >&2
      ;;
  esac
}

soviez_fw_forbidden_public_ports() {
  # Space-separated list of ports that must not be publicly allowed by Soviez policy.
  printf '%s\n' "8069 8071 8072 5432 10000 2375 2376"
}

# --- end security/platform/firewall.sh ---

# --- begin security/platform/firewall_ufw.sh ---
# shellcheck shell=bash
# Security Gate S2 — UFW backend (idempotent; never ufw reset).

soviez_fw_ufw_ensure_rule() {
  local rule="$1"
  # Idempotent: skip if already present in ufw status.
  if ufw status 2>/dev/null | grep -Fqi -- "$rule"; then
    return 0
  fi
  # shellcheck disable=SC2086
  ufw allow $rule >/dev/null 2>&1 || ufw allow "$rule" >/dev/null 2>&1 || true
}

soviez_fw_ufw_apply() {
  local ssh_port="${1:-22}"
  if ! command -v ufw >/dev/null 2>&1; then
    echo "[error] security:SEC_CRIT_FIREWALL_STATE_UNKNOWN: ufw missing" >&2
    return 1
  fi
  # Open required ports BEFORE enable — preserve SSH.
  soviez_fw_ufw_ensure_rule "${ssh_port}/tcp"
  if [[ "$ssh_port" == "22" ]]; then
    soviez_fw_ufw_ensure_rule "OpenSSH"
  fi
  soviez_fw_ufw_ensure_rule "80/tcp"
  soviez_fw_ufw_ensure_rule "443/tcp"
  # Default deny inbound when enabling (ufw default); do not flush.
  ufw default deny incoming >/dev/null 2>&1 || true
  ufw default allow outgoing >/dev/null 2>&1 || true
  # Enable without reset — must succeed on Production Linux hosts.
  # Note: do not grep bare "active" (matches "inactive").
  if ! ufw status 2>/dev/null | head -1 | grep -Eqi 'Status:[[:space:]]*active'; then
    if ! ufw --force enable >/dev/null 2>&1; then
      echo "[error] security:SEC_CRIT_FIREWALL_STATE_UNKNOWN: ufw enable failed" >&2
      return 1
    fi
  fi
  return 0
}

soviez_fw_ufw_rollback() {
  local dir="$1"
  # Soft rollback: re-ensure SSH/80/443 from snapshot intent; never open app/db ports.
  local ssh_port="${SOVIEZ_SSH_PORT:-22}"
  soviez_fw_ufw_ensure_rule "${ssh_port}/tcp"
  soviez_fw_ufw_ensure_rule "80/tcp"
  soviez_fw_ufw_ensure_rule "443/tcp"
  [[ -f "$dir/ufw.status" ]] || true
}

# --- end security/platform/firewall_ufw.sh ---

# --- begin security/platform/firewall_firewalld.sh ---
# shellcheck shell=bash
# Security Gate S2 — firewalld backend (idempotent; never --complete-reload).

soviez_fw_firewalld_apply() {
  local ssh_port="${1:-22}"
  if ! command -v firewall-cmd >/dev/null 2>&1; then
    echo "[error] security:SEC_CRIT_FIREWALL_STATE_UNKNOWN: firewall-cmd missing" >&2
    return 1
  fi
  firewall-cmd --permanent --add-service=http >/dev/null 2>&1 || \
    firewall-cmd --permanent --add-port=80/tcp >/dev/null 2>&1 || true
  firewall-cmd --permanent --add-service=https >/dev/null 2>&1 || \
    firewall-cmd --permanent --add-port=443/tcp >/dev/null 2>&1 || true
  if [[ "$ssh_port" == "22" ]]; then
    firewall-cmd --permanent --add-service=ssh >/dev/null 2>&1 || true
  else
    firewall-cmd --permanent --add-port="${ssh_port}/tcp" >/dev/null 2>&1 || true
  fi
  # Reload (not complete-reload) to apply permanent rules.
  firewall-cmd --reload >/dev/null 2>&1 || true
  return 0
}

# --- end security/platform/firewall_firewalld.sh ---

# --- begin security/platform/firewall_nftables.sh ---
# shellcheck shell=bash
# Security Gate S2 — nftables backend (additive table only; never nft flush ruleset).

soviez_fw_nft_apply() {
  local ssh_port="${1:-22}"
  if ! command -v nft >/dev/null 2>&1; then
    echo "[error] security:SEC_CRIT_FIREWALL_STATE_UNKNOWN: nft missing" >&2
    return 1
  fi
  # Additive Soviez-owned table/chain — do not flush global ruleset.
  nft list table inet soviez_s2 >/dev/null 2>&1 || \
    nft add table inet soviez_s2 2>/dev/null || true
  nft list chain inet soviez_s2 input >/dev/null 2>&1 || \
    nft add chain inet soviez_s2 input '{ type filter hook input priority 0; policy accept; }' 2>/dev/null || true
  # Allow established + SSH/80/443 (idempotent add may fail if exists — ignore).
  nft add rule inet soviez_s2 input ct state established,related accept 2>/dev/null || true
  nft add rule inet soviez_s2 input tcp dport "${ssh_port}" accept 2>/dev/null || true
  nft add rule inet soviez_s2 input tcp dport 80 accept 2>/dev/null || true
  nft add rule inet soviez_s2 input tcp dport 443 accept 2>/dev/null || true
  return 0
}

# --- end security/platform/firewall_nftables.sh ---

# --- begin security/platform/docker_firewall.sh ---
# shellcheck shell=bash
# Security Gate S2 — iptables additive helpers + DOCKER-USER (never iptables -F).

soviez_fw_iptables_apply() {
  local ssh_port="${1:-22}"
  if ! command -v iptables >/dev/null 2>&1; then
    return 0
  fi
  # Ensure INPUT accepts SSH/80/443 if chain is reachable (best-effort, non-flush).
  iptables -C INPUT -p tcp --dport "$ssh_port" -j ACCEPT 2>/dev/null || \
    iptables -I INPUT -p tcp --dport "$ssh_port" -j ACCEPT 2>/dev/null || true
  iptables -C INPUT -p tcp --dport 80 -j ACCEPT 2>/dev/null || \
    iptables -I INPUT -p tcp --dport 80 -j ACCEPT 2>/dev/null || true
  iptables -C INPUT -p tcp --dport 443 -j ACCEPT 2>/dev/null || \
    iptables -I INPUT -p tcp --dport 443 -j ACCEPT 2>/dev/null || true
}

soviez_fw_docker_apply_user_chain() {
  # DOCKER-USER: drop unexpected published app/db ports from external interfaces.
  # Preserve Docker's own chains; never iptables -F DOCKER*.
  if ! command -v iptables >/dev/null 2>&1; then
    return 0
  fi
  iptables -L DOCKER-USER -n >/dev/null 2>&1 || \
    iptables -N DOCKER-USER 2>/dev/null || true
  # Return early for established.
  iptables -C DOCKER-USER -m conntrack --ctstate RELATED,ESTABLISHED -j RETURN 2>/dev/null || \
    iptables -I DOCKER-USER -m conntrack --ctstate RELATED,ESTABLISHED -j RETURN 2>/dev/null || true
  # Allow loopback / docker bridge source free (conservative).
  iptables -C DOCKER-USER -i lo -j RETURN 2>/dev/null || \
    iptables -I DOCKER-USER -i lo -j RETURN 2>/dev/null || true
  local p
  for p in 8069 8071 8072 5432; do
    # Drop NEW connections to published container ports from non-loopback.
    iptables -C DOCKER-USER -p tcp --dport "$p" -j DROP 2>/dev/null || \
      iptables -A DOCKER-USER -p tcp --dport "$p" -m comment --comment "SOVIEZ_S2_BLOCK_${p}" -j DROP 2>/dev/null || true
  done
  iptables -C DOCKER-USER -j RETURN 2>/dev/null || \
    iptables -A DOCKER-USER -j RETURN 2>/dev/null || true
  return 0
}

soviez_fw_docker_forwarding_healthy() {
  # Soft check: docker can create a network / DOCKER chains exist OR docker uses nft.
  if ! command -v docker >/dev/null 2>&1; then
    echo "docker absent"
    return 1
  fi
  docker info >/dev/null 2>&1 || return 1
  return 0
}

# --- end security/platform/docker_firewall.sh ---

# --- begin security/platform/nginx_edge.sh ---
# shellcheck shell=bash
# Security Gate S2 — Nginx production hardening (owned snippets; do not overwrite Virtualmin).

SOVIEZ_NGINX_S2_MARKER="# SOVIEZ_OWNED nginx security — Security Gate S2"

soviez_nginx_s2_render_hardened() {
  # Args: domain upstream cert key out_path [mode=https|http_only]
  local domain="$1" upstream="$2" cert="${3:-}" key="${4:-}" out="${5:-}" mode="${6:-https}"
  local client_max="${SOVIEZ_NGINX_CLIENT_MAX_BODY:-100M}"
  local edge_mode="${SOVIEZ_EDGE_MODE:-direct}"
  local real_ip_block=""
  local headers_block=""
  local rate_block=""
  local ws_map=""
  local ws_upstream="${SOVIEZ_NGINX_WS_UPSTREAM:-}"
  if [[ -z "$ws_upstream" ]]; then
    if [[ "$upstream" =~ ^(.+):8069$ ]]; then
      ws_upstream="${BASH_REMATCH[1]}:8072"
    else
      ws_upstream="$upstream"
    fi
  fi

  # Upstream must be localhost/private — reject obvious public IPs in upstream string for Production.
  if [[ "$upstream" =~ ^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+: ]]; then
    if [[ ! "$upstream" =~ ^127\. ]] && [[ ! "$upstream" =~ ^10\. ]] && \
       [[ ! "$upstream" =~ ^192\.168\. ]] && [[ ! "$upstream" =~ ^172\.(1[6-9]|2[0-9]|3[0-1])\. ]]; then
      echo "[error] security:SEC_CRIT_NGINX_INVALID: upstream not private/loopback: ${upstream}" >&2
      return 1
    fi
  fi

  headers_block=$(cat <<'HDR'
    # Safe baseline headers (CSP report-only — strict CSP deferred; breaks Odoo assets)
    add_header X-Content-Type-Options "nosniff" always;
    add_header Referrer-Policy "strict-origin-when-cross-origin" always;
    add_header X-Frame-Options "SAMEORIGIN" always;
    add_header Permissions-Policy "geolocation=(), microphone=(), camera=()" always;
    add_header Content-Security-Policy-Report-Only "default-src 'self' 'unsafe-inline' 'unsafe-eval' data: blob:;" always;
HDR
)
  if [[ "$mode" == "https" ]]; then
    headers_block+=$'\n'"    add_header Strict-Transport-Security \"max-age=31536000; includeSubDomains\" always;"
  fi

  rate_block=$(cat <<'RATE'
    # Targeted limits only — do not globally throttle /web/dataset JSON-RPC
    location = /web/login {
        limit_req zone=soviez_login burst=20 nodelay;
        proxy_pass http://UPSTREAM_PLACEHOLDER;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header X-Forwarded-Host $host;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection $connection_upgrade;
    }
RATE
)
  rate_block="${rate_block//UPSTREAM_PLACEHOLDER/${upstream}}"

  if [[ "$edge_mode" == "cloudflare" || "$edge_mode" == "cloudflare_aop" ]]; then
    if declare -F soviez_edge_cloudflare_real_ip_directives >/dev/null 2>&1; then
      real_ip_block="$(soviez_edge_cloudflare_real_ip_directives)"
    fi
  else
    # Direct mode: do not trust arbitrary X-Forwarded-For from internet.
    real_ip_block="# EDGE_MODE=direct — ignore spoofed XFF; use connection remote_addr"
  fi

  local tls_block=""
  if [[ "$mode" == "https" && -n "$cert" && -n "$key" ]]; then
    tls_block=$(cat <<TLS
    ssl_certificate ${cert};
    ssl_certificate_key ${key};
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_prefer_server_ciphers off;
    ssl_ciphers HIGH:!aNULL:!MD5:!RC4;
TLS
)
  fi

  {
    echo "${SOVIEZ_NGINX_S2_MARKER}"
    echo "# env domain=${domain} edge=${edge_mode} upstream=${upstream}"
    echo "map \$http_upgrade \$connection_upgrade { default upgrade; '' close; }"
    echo "limit_req_zone \$binary_remote_addr zone=soviez_login:10m rate=5r/s;"
    echo
    cat <<EOF
server {
    listen 80;
    server_name ${domain};
    server_tokens off;
    ${real_ip_block}
EOF
    if [[ "$mode" == "https" ]]; then
      cat <<EOF
    location ^~ /.well-known/acme-challenge/ {
        default_type "text/plain";
        root /var/www/html;
    }
    location / {
        return 301 https://\$host\$request_uri;
    }
}
server {
    listen 443 ssl http2;
    server_name ${domain};
    server_tokens off;
    ${tls_block}
    ${real_ip_block}
    client_max_body_size ${client_max};
    proxy_read_timeout 720s;
    proxy_connect_timeout 720s;
    proxy_send_timeout 720s;
    ${headers_block}

${rate_block}

    location /websocket {
        proxy_pass http://${ws_upstream};
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_set_header X-Forwarded-Host \$host;
        proxy_http_version 1.1;
        proxy_set_header Upgrade \$http_upgrade;
        proxy_set_header Connection \$connection_upgrade;
        proxy_read_timeout 720s;
    }

    location /longpolling {
        proxy_pass http://${ws_upstream};
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_read_timeout 720s;
    }

    location / {
        proxy_pass http://${upstream};
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_set_header X-Forwarded-Host \$host;
        proxy_http_version 1.1;
        proxy_set_header Upgrade \$http_upgrade;
        proxy_set_header Connection \$connection_upgrade;
        proxy_read_timeout 720s;
        proxy_buffering off;
    }
}
EOF
    else
      cat <<EOF
    client_max_body_size ${client_max};
    location / {
        proxy_pass http://${upstream};
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
    }
}
EOF
    fi
  } >"$out"
  printf '%s\n' "$out"
}

soviez_nginx_s2_validate_syntax() {
  local conf="$1"
  [[ -f "$conf" ]] || return 1
  grep -q 'SOVIEZ_OWNED nginx security' "$conf" || grep -q 'SOVIEZ_OWNED' "$conf" || true
  grep -q 'server_tokens off' "$conf" || {
    echo "[error] security:SEC_CRIT_NGINX_INVALID: server_tokens not disabled" >&2
    return 1
  }
  if grep -Eq 'proxy_pass[[:space:]]+http://0\.0\.0\.0' "$conf"; then
    echo "[error] security:SEC_CRIT_NGINX_INVALID: upstream 0.0.0.0" >&2
    return 1
  fi
  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    grep -q 'SOVIEZ_FORCE_NGINX_T_FAIL' "$conf" && return 1
    return 0
  fi
  if command -v nginx >/dev/null 2>&1; then
    # Full nginx -t needs a complete main conf; structural checks above are primary for snippets.
    return 0
  fi
  return 0
}

soviez_nginx_s2_detect_ownership() {
  local path="$1"
  if [[ ! -f "$path" ]]; then
    printf '%s\n' "missing"
    return 0
  fi
  if grep -q 'SOVIEZ_OWNED' "$path" 2>/dev/null; then
    printf '%s\n' "soviez"
    return 0
  fi
  if grep -Eiq 'Virtualmin|VIRTUALMIN|webmin' "$path" 2>/dev/null || \
     [[ "$path" == *'/etc/nginx/sites-enabled/'* && -d /etc/webmin ]]; then
    printf '%s\n' "virtualmin"
    return 0
  fi
  printf '%s\n' "unknown"
}

# --- end security/platform/nginx_edge.sh ---

# --- begin security/platform/cloudflare.sh ---
# shellcheck shell=bash
# Security Gate S2 — Cloudflare IP source-of-truth + real_ip directives.

SOVIEZ_CF_CACHE_DIR="${SOVIEZ_CF_CACHE_DIR:-}"
SOVIEZ_CF_LKG_REL="share/security/cloudflare/ips-v4.lkg.json"

soviez_cf_cache_dir() {
  if [[ -n "${SOVIEZ_CF_CACHE_DIR:-}" ]]; then
    printf '%s\n' "$SOVIEZ_CF_CACHE_DIR"
    return 0
  fi
  local root="${SOVIEZ_SH_ROOT:-${SOVIEZ_ROOT:-.}}"
  local d="${root}/var/security/cloudflare"
  mkdir -p "$d" 2>/dev/null || d="${TMPDIR:-/tmp}/soviez-cf-cache"
  mkdir -p "$d"
  printf '%s\n' "$d"
}

soviez_cf_lkg_path() {
  local root="${SOVIEZ_SH_ROOT:-${SOVIEZ_ROOT:-.}}"
  local bundled="${root}/${SOVIEZ_CF_LKG_REL}"
  if [[ -f "$bundled" ]]; then
    printf '%s\n' "$bundled"
    return 0
  fi
  # Assembled dist may not embed share/; fall back to cache.
  local cache
  cache="$(soviez_cf_cache_dir)/ips-v4.lkg.json"
  printf '%s\n' "$cache"
}

soviez_cf_active_cache_path() {
  printf '%s/ips-v4.active.json\n' "$(soviez_cf_cache_dir)"
}

soviez_cf_load_ranges() {
  # Prints CIDR lines. Prefer active cache → LKG. Never return empty if LKG exists.
  local active lkg
  active="$(soviez_cf_active_cache_path)"
  lkg="$(soviez_cf_lkg_path)"
  local src=""
  if [[ -f "$active" ]]; then
    src="$active"
  elif [[ -f "$lkg" ]]; then
    src="$lkg"
  else
    echo "[error] security:SEC_WARN_EDGE_CACHE_STALE: no Cloudflare IP cache" >&2
    return 1
  fi
  python3 - "$src" <<'PY' 2>/dev/null || true
import json,sys
p=sys.argv[1]
d=json.load(open(p))
for r in d.get("ranges") or []:
    print(r)
PY
}

soviez_cf_cache_meta() {
  local active lkg src
  active="$(soviez_cf_active_cache_path)"
  lkg="$(soviez_cf_lkg_path)"
  if [[ -f "$active" ]]; then src="$active"; else src="$lkg"; fi
  [[ -f "$src" ]] || { echo "{}"; return 1; }
  python3 - "$src" <<'PY'
import json,sys
d=json.load(open(sys.argv[1]))
print(json.dumps({
  "source": d.get("source"),
  "fetched_utc": d.get("fetched_utc"),
  "digest_sha256": d.get("digest_sha256"),
  "range_count": len(d.get("ranges") or []),
  "fallback": d.get("fallback","last_known_good"),
  "path": sys.argv[1],
}, indent=2))
PY
}

soviez_cf_refresh_ranges() {
  # Explicit operator-initiated only. No hidden periodic network refresh.
  # Usage: soviez_cf_refresh_ranges [--force]
  if [[ "${SOVIEZ_CF_ALLOW_NETWORK_REFRESH:-0}" != "1" ]]; then
    echo "[security] SEC_WARN_EDGE_CACHE_STALE: refresh requires SOVIEZ_CF_ALLOW_NETWORK_REFRESH=1 (operator-initiated)" >&2
    return 1
  fi
  local url="https://www.cloudflare.com/ips-v4"
  local tmp
  tmp="$(mktemp)"
  if ! curl -fsSL --max-time 15 "$url" -o "$tmp" 2>/dev/null; then
    echo "[security] SEC_WARN_EDGE_CACHE_STALE: fetch failed — preserving last-known-good" >&2
    rm -f "$tmp"
    return 1
  fi
  local count
  count="$(grep -cE '^[0-9]' "$tmp" || echo 0)"
  if [[ "$count" -lt 5 ]]; then
    echo "[security] SEC_WARN_EDGE_CACHE_STALE: fetched list too small — preserving LKG" >&2
    rm -f "$tmp"
    return 1
  fi
  local digest ts out
  digest="$(openssl dgst -sha256 "$tmp" | awk '{print $NF}')"
  ts="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
  out="$(soviez_cf_active_cache_path)"
  python3 - "$tmp" "$out" "$url" "$digest" "$ts" <<'PY'
import json,sys
ranges=[ln.strip() for ln in open(sys.argv[1]) if ln.strip() and not ln.startswith("#")]
obj={"source":sys.argv[3],"fetched_utc":sys.argv[5],"digest_sha256":sys.argv[4],"ranges":ranges,"fallback":"last_known_good"}
json.dump(obj, open(sys.argv[2],"w"), indent=2)
print(sys.argv[2])
PY
  rm -f "$tmp"
  chmod 600 "$out" 2>/dev/null || true
}

soviez_edge_cloudflare_real_ip_directives() {
  local r
  echo "# Cloudflare real_ip — trusted ranges only"
  echo "real_ip_header CF-Connecting-IP;"
  echo "real_ip_recursive on;"
  while IFS= read -r r; do
    [[ -n "$r" ]] || continue
    echo "set_real_ip_from ${r};"
  done < <(soviez_cf_load_ranges)
}

soviez_edge_trust_client_ip() {
  # Returns 0 if remote_addr is trusted proxy for current EDGE_MODE.
  local remote="$1"
  local mode="${SOVIEZ_EDGE_MODE:-direct}"
  case "$mode" in
    direct)
      # Direct: never treat arbitrary XFF as client; remote_addr is source of truth.
      return 0
      ;;
    cloudflare|cloudflare_aop)
      local r
      while IFS= read -r r; do
        [[ -n "$r" ]] || continue
        if python3 - "$remote" "$r" <<'PY'
import ipaddress,sys
ip=ipaddress.ip_address(sys.argv[1])
net=ipaddress.ip_network(sys.argv[2], strict=False)
sys.exit(0 if ip in net else 1)
PY
        then
          return 0
        fi
      done < <(soviez_cf_load_ranges)
      return 1
      ;;
    *)
      return 1
      ;;
  esac
}

soviez_edge_reject_spoofed_xff_policy() {
  # Document/check: in direct mode, generated nginx must not set_real_ip_from 0.0.0.0/0.
  local conf="${1:-}"
  if [[ -n "$conf" && -f "$conf" ]]; then
    if grep -E 'set_real_ip_from[[:space:]]+0\.0\.0\.0/0' "$conf" >/dev/null 2>&1; then
      echo "[error] security:SEC_CRIT_NGINX_INVALID: trusts entire internet as real_ip" >&2
      return 1
    fi
  fi
  return 0
}

# --- end security/platform/cloudflare.sh ---

# --- begin security/platform/edge.sh ---
# shellcheck shell=bash
# Security Gate S2 — edge modes (direct | cloudflare | cloudflare_aop).

SOVIEZ_EDGE_MODE="${SOVIEZ_EDGE_MODE:-direct}"

soviez_edge_validate_mode() {
  case "${SOVIEZ_EDGE_MODE:-direct}" in
    direct|cloudflare) return 0 ;;
    cloudflare_aop)
      # AOP/mTLS only if explicitly enabled and certs present — else unsupported.
      if [[ "${SOVIEZ_EDGE_AOP_ENABLED:-0}" == "1" && -n "${SOVIEZ_EDGE_AOP_CLIENT_CA:-}" && -f "${SOVIEZ_EDGE_AOP_CLIENT_CA}" ]]; then
        return 0
      fi
      echo "[security] EDGE_MODE=cloudflare_aop unsupported without SOVIEZ_EDGE_AOP_ENABLED=1 and client CA — experimental/unsupported" >&2
      return 1
      ;;
    *)
      echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: invalid EDGE_MODE=${SOVIEZ_EDGE_MODE}" >&2
      return 1
      ;;
  esac
}

soviez_edge_apply_origin_protection() {
  # When Cloudflare-restricted origin mode is enabled, limit 80/443 to CF ranges.
  # SSH remains independent. ACME HTTP-01 must remain possible (/.well-known or DNS-01).
  local mode="${SOVIEZ_EDGE_MODE:-direct}"
  if [[ "${SOVIEZ_EDGE_ORIGIN_RESTRICT:-0}" != "1" ]]; then
    return 0
  fi
  if [[ "$mode" != "cloudflare" && "$mode" != "cloudflare_aop" ]]; then
    return 0
  fi
  if ! command -v ufw >/dev/null 2>&1; then
    echo "[security] origin restrict requested but ufw absent — Needs Action" >&2
    return 0
  fi
  local r
  while IFS= read -r r; do
    [[ -n "$r" ]] || continue
    ufw allow from "$r" to any port 80 proto tcp >/dev/null 2>&1 || true
    ufw allow from "$r" to any port 443 proto tcp >/dev/null 2>&1 || true
  done < <(soviez_cf_load_ranges 2>/dev/null || true)
  # Do not delete world-open 80/443 automatically (ACME / lockout risk) — report Needs Action.
  echo "[security] origin CF allow rules ensured; review world-open 80/443 manually for ACME safety" >&2
}

soviez_edge_aop_status() {
  if [[ "${SOVIEZ_EDGE_MODE:-}" != "cloudflare_aop" ]]; then
    printf '%s\n' "N/A"
    return 0
  fi
  if [[ "${SOVIEZ_EDGE_AOP_ENABLED:-0}" == "1" && -n "${SOVIEZ_EDGE_AOP_CLIENT_CA:-}" && -f "${SOVIEZ_EDGE_AOP_CLIENT_CA}" ]]; then
    printf '%s\n' "EXPERIMENTAL"
    return 0
  fi
  printf '%s\n' "UNSUPPORTED"
}

# --- end security/platform/edge.sh ---

# --- begin security/platform/ssh.sh ---
# shellcheck shell=bash
# Security Gate S2 — SSH staged hardening (never brick management access).
# NEVER mutate the developer's workstation sshd from tests — use disposable guests.

SOVIEZ_SSH_POLICY="${SOVIEZ_SSH_POLICY:-staged}"

soviez_ssh_detect_state() {
  local conf="${1:-/etc/ssh/sshd_config}"
  local password_auth="unknown" root_login="unknown" port="22"
  if [[ -f "$conf" ]]; then
    password_auth="$(awk 'BEGIN{v="yes"} /^[[:space:]]*PasswordAuthentication[[:space:]]/{v=$2} END{print tolower(v)}' "$conf" 2>/dev/null || echo unknown)"
    root_login="$(awk 'BEGIN{v="yes"} /^[[:space:]]*PermitRootLogin[[:space:]]/{v=$2} END{print tolower(v)}' "$conf" 2>/dev/null || echo unknown)"
    port="$(awk 'BEGIN{v="22"} /^[[:space:]]*Port[[:space:]]/{v=$2} END{print v}' "$conf" 2>/dev/null || echo 22)"
  fi
  printf 'password_auth=%s root_login=%s port=%s\n' "$password_auth" "$root_login" "$port"
}

soviez_ssh_find_admin_users() {
  # Non-root users with sudo/admin group and a home authorized_keys presence hint.
  local u
  if [[ -f /etc/passwd ]]; then
    while IFS=: read -r u _ uid _ _ home shell; do
      [[ "$uid" -ge 1000 ]] 2>/dev/null || continue
      [[ "$u" == "nobody" ]] && continue
      if [[ -f "${home}/.ssh/authorized_keys" ]] && [[ -s "${home}/.ssh/authorized_keys" ]]; then
        if id -nG "$u" 2>/dev/null | grep -Eq '(sudo|admin|wheel)'; then
          printf '%s\n' "$u"
        fi
      fi
    done < /etc/passwd
  fi
}

soviez_ssh_has_alternate_access() {
  local users
  users="$(soviez_ssh_find_admin_users | head -1 || true)"
  [[ -n "$users" ]]
}

soviez_ssh_sshd_config_test() {
  local conf="${1:-}"
  if command -v sshd >/dev/null 2>&1; then
    mkdir -p /run/sshd 2>/dev/null || true
    if [[ -n "$conf" ]]; then
      sshd -t -f "$conf" >/dev/null 2>&1
    else
      sshd -t >/dev/null 2>&1
    fi
  else
    # Structural: no empty PasswordAuthentication line
    [[ -f "$conf" ]] || return 0
    ! grep -Eq '^[[:space:]]*PasswordAuthentication[[:space:]]*$' "$conf"
  fi
}

soviez_ssh_prepare_dropin() {
  # Write Soviez-owned drop-in fragment (does not apply until verified).
  local out="$1"
  local password_auth="${2:-yes}"
  local permit_root="${3:-prohibit-password}"
  mkdir -p "$(dirname "$out")"
  cat >"$out" <<EOF
# SOVIEZ_OWNED sshd drop-in — Security Gate S2
# Applied only after alternate access verification.
PasswordAuthentication ${password_auth}
PermitRootLogin ${permit_root}
PubkeyAuthentication yes
EOF
  chmod 644 "$out"
}

soviez_ssh_staged_harden() {
  # Safe staged flow. Returns 0 on apply or intentional defer.
  local policy="${SOVIEZ_SSH_POLICY:-staged}"
  local conf="${SOVIEZ_SSH_CONFIG:-/etc/ssh/sshd_config}"
  local dropin="${SOVIEZ_SSH_DROPIN:-/etc/ssh/sshd_config.d/50-soviez-s2.conf}"
  local snap_dir="${SOVIEZ_SSH_SNAPSHOT_DIR:-${TMPDIR:-/tmp}/soviez-ssh-snap-$$}"

  case "$policy" in
    deferred)
      echo "[security] SEC_WARN_SSH_HARDENING_DEFERRED: policy=deferred" >&2
      return 0
      ;;
    staged|keys_required) ;;
    *)
      echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: invalid SSH_POLICY=${policy}" >&2
      return 1
      ;;
  esac

  mkdir -p "$snap_dir"
  chmod 700 "$snap_dir" 2>/dev/null || true
  if [[ -f "$conf" ]]; then
    cp -a "$conf" "$snap_dir/sshd_config.bak" 2>/dev/null || true
  fi
  [[ -f "$dropin" ]] && cp -a "$dropin" "$snap_dir/dropin.bak" 2>/dev/null || true

  if ! soviez_ssh_has_alternate_access; then
    echo "[security] SEC_WARN_SSH_HARDENING_DEFERRED: no verified non-root sudo+key admin" >&2
    if [[ "$policy" == "keys_required" && "${SOVIEZ_SSH_FORCE_UNSAFE:-0}" != "1" ]]; then
      echo "[security] SEC_HIGH_SSH_PASSWORD_AUTH_ENABLED: cannot prove alternate login — deferring" >&2
    fi
    return 0
  fi

  # Prepare hardened drop-in.
  local staged="${dropin}.staged"
  soviez_ssh_prepare_dropin "$staged" "no" "no"

  if [[ "${SOVIEZ_SSH_APPLY:-0}" != "1" ]]; then
    echo "[security] SSH harden prepared at ${staged} (set SOVIEZ_SSH_APPLY=1 to install)" >&2
    return 0
  fi

  if ! soviez_ssh_sshd_config_test "$conf"; then
    echo "[error] security:SEC_HIGH_SSH_PASSWORD_AUTH_ENABLED: sshd -t failed pre-apply" >&2
    rm -f "$staged"
    return 1
  fi
  # Merge test: concatenate main+dropin into temp if sshd supports Include.
  local merged
  merged="$(mktemp)"
  cat "$conf" >"$merged" 2>/dev/null || true
  echo "Include ${staged}" >>"$merged"
  if ! soviez_ssh_sshd_config_test "$merged"; then
    if ! grep -q 'PasswordAuthentication no' "$staged"; then
      rm -f "$staged" "$merged"
      return 1
    fi
  fi
  rm -f "$merged"

  mv -f "$staged" "$dropin"
  if command -v systemctl >/dev/null 2>&1; then
    systemctl reload sshd >/dev/null 2>&1 || systemctl reload ssh >/dev/null 2>&1 || true
  fi
  return 0
}

soviez_ssh_rollback() {
  local snap_dir="${1:-${SOVIEZ_SSH_SNAPSHOT_DIR:-}}"
  local dropin="${SOVIEZ_SSH_DROPIN:-/etc/ssh/sshd_config.d/50-soviez-s2.conf}"
  [[ -n "$snap_dir" && -d "$snap_dir" ]] || return 1
  if [[ -f "$snap_dir/dropin.bak" ]]; then
    cp -a "$snap_dir/dropin.bak" "$dropin"
  else
    rm -f "$dropin"
  fi
  if [[ -f "$snap_dir/sshd_config.bak" && -n "${SOVIEZ_SSH_CONFIG:-}" ]]; then
    cp -a "$snap_dir/sshd_config.bak" "$SOVIEZ_SSH_CONFIG"
  fi
  command -v systemctl >/dev/null 2>&1 && {
    systemctl reload sshd >/dev/null 2>&1 || systemctl reload ssh >/dev/null 2>&1 || true
  }
  return 0
}

# --- end security/platform/ssh.sh ---

# --- begin security/platform/brute_force.sh ---
# shellcheck shell=bash
# Security Gate S2 — brute-force protection (Fail2Ban preferred; CrowdSec optional OD).

soviez_bf_detect() {
  local have_f2b=0 have_crowd=0
  command -v fail2ban-client >/dev/null 2>&1 && have_f2b=1
  command -v cscli >/dev/null 2>&1 && have_crowd=1
  if [[ "$have_f2b" -eq 1 ]]; then
    printf '%s\n' "fail2ban"
  elif [[ "$have_crowd" -eq 1 ]]; then
    printf '%s\n' "crowdsec"
  else
    printf '%s\n' "none"
  fi
}

soviez_bf_fail2ban_jail_path() {
  printf '%s\n' "${SOVIEZ_FAIL2BAN_JAIL:-/etc/fail2ban/jail.d/soviez-s2.local}"
}

soviez_bf_ensure_fail2ban_ssh() {
  # Idempotent Soviez-owned jail.local fragment — SSH only by default.
  # Do NOT add fragile Odoo JSON-RPC ban jails.
  local path
  path="$(soviez_bf_fail2ban_jail_path)"
  if [[ "${SOVIEZ_BF_INSTALL:-0}" == "1" ]] && ! command -v fail2ban-client >/dev/null 2>&1; then
    if command -v apt-get >/dev/null 2>&1; then
      if declare -F soviez_s5_apt_wait_for_lock >/dev/null 2>&1; then
        soviez_s5_apt_wait_for_lock >/dev/null 2>&1 || {
          echo "[error] security:PKG_LOCK_TIMEOUT: cannot install fail2ban while apt locked" >&2
          return 1
        }
      fi
      apt-get install -y fail2ban >/dev/null 2>&1 || true
    fi
  fi
  mkdir -p "$(dirname "$path")"
  if [[ -f "$path" ]] && grep -q 'SOVIEZ_OWNED' "$path" 2>/dev/null; then
    return 0
  fi
  cat >"$path" <<'EOF'
# SOVIEZ_OWNED fail2ban — Security Gate S2
[DEFAULT]
bantime  = 1h
findtime = 10m
maxretry = 5

[sshd]
enabled = true
port    = ssh
filter  = sshd
maxretry = 5

# nginx-http-auth only — NOT Odoo /web/dataset RPC (false-positive risk)
[nginx-http-auth]
enabled = true
port    = http,https
filter  = nginx-http-auth
logpath = /var/log/nginx/error.log
maxretry = 5
EOF
  chmod 644 "$path"
  if ! command -v fail2ban-client >/dev/null 2>&1; then
    echo "[security] Fail2Ban not present — jail file written; service enable deferred" >&2
    return 0
  fi
  if command -v systemctl >/dev/null 2>&1; then
    systemctl enable --now fail2ban >/dev/null 2>&1 || true
    systemctl reload fail2ban >/dev/null 2>&1 || systemctl restart fail2ban >/dev/null 2>&1 || true
  fi
}

soviez_bf_decision_record() {
  # OD-SEC-04: keep Fail2Ban; CrowdSec optional — do not replace working Fail2Ban.
  local d
  d="$(soviez_bf_detect)"
  case "$d" in
    fail2ban) printf '%s\n' "KEEP_FAIL2BAN" ;;
    crowdsec) printf '%s\n' "CROWDSEC_PRESENT_OPTIONAL" ;;
    none) printf '%s\n' "NONE_NEEDS_ACTION" ;;
  esac
}

# --- end security/platform/brute_force.sh ---

# --- begin security/platform/management_surface.sh ---
# shellcheck shell=bash
# Security Gate S2 — Webmin/Virtualmin detection (detect+report; no blind removal).

soviez_mgmt_detect_webmin() {
  local present=0 port_bind="" tls="unknown" version=""
  if command -v webmin >/dev/null 2>&1 || [[ -d /etc/webmin ]] || [[ -f /etc/webmin/miniserv.conf ]]; then
    present=1
  fi
  if systemctl list-unit-files 2>/dev/null | grep -qi webmin; then
    present=1
  fi
  if [[ -f /etc/webmin/miniserv.conf ]]; then
    port_bind="$(awk -F= '/^port=/{print $2}' /etc/webmin/miniserv.conf 2>/dev/null | head -1)"
    version="$(awk -F= '/^version=/{print $2}' /etc/webmin/version 2>/dev/null | head -1 || true)"
    if grep -qi 'ssl=1' /etc/webmin/miniserv.conf 2>/dev/null; then
      tls="yes"
    else
      tls="no"
    fi
  fi
  port_bind="${port_bind:-10000}"
  # Listening check via ss if available.
  local listen="unknown"
  if command -v ss >/dev/null 2>&1; then
    if ss -lnt 2>/dev/null | grep -Eq ":${port_bind}\\b"; then
      listen="listening"
      if ss -lnt 2>/dev/null | grep -E "0\\.0\\.0\\.0:${port_bind}|\\*:${port_bind}|:::${port_bind}"; then
        listen="public"
      elif ss -lnt 2>/dev/null | grep -Eq "127\\.0\\.0\\.1:${port_bind}|\\[::1\\]:${port_bind}"; then
        listen="localhost"
      fi
    else
      listen="not_listening"
    fi
  fi
  printf 'present=%s port=%s listen=%s tls=%s version=%s\n' \
    "$present" "$port_bind" "$listen" "$tls" "${version:-unknown}"
}

soviez_mgmt_detect_virtualmin() {
  local present=0
  if command -v virtualmin >/dev/null 2>&1 || [[ -d /etc/webmin/virtual-server ]] || \
     [[ -f /usr/sbin/virtualmin ]]; then
    present=1
  fi
  printf 'present=%s\n' "$present"
}

soviez_mgmt_classify_webmin() {
  # N/A | PASS | WARNING | FAIL
  local info
  info="$(soviez_mgmt_detect_webmin)"
  local present listen tls
  present="$(printf '%s' "$info" | sed -n 's/.*present=\([0-9]*\).*/\1/p')"
  listen="$(printf '%s' "$info" | sed -n 's/.*listen=\([^ ]*\).*/\1/p')"
  tls="$(printf '%s' "$info" | sed -n 's/.*tls=\([^ ]*\).*/\1/p')"
  if [[ "$present" != "1" ]]; then
    printf '%s\n' "N/A"
    return 0
  fi
  case "$listen" in
    public)
      if [[ "$tls" == "no" ]]; then
        printf '%s\n' "FAIL"
      else
        printf '%s\n' "WARNING"
      fi
      ;;
    localhost) printf '%s\n' "PASS" ;;
    *) printf '%s\n' "WARNING" ;;
  esac
}

# --- end security/platform/management_surface.sh ---

# --- begin security/platform/host_baseline.sh ---
# shellcheck shell=bash
# Security Gate S2 — host administrative surface baseline (read-only).

soviez_host_uid0_audit() {
  # List UID 0 accounts (read-only).
  if [[ ! -f /etc/passwd ]]; then
    echo "passwd_absent"
    return 0
  fi
  awk -F: '$3==0 {print $1}' /etc/passwd
}

soviez_host_login_shell_audit() {
  # Unexpected shells for system users — report only.
  if [[ ! -f /etc/passwd ]]; then
    return 0
  fi
  awk -F: '$3<1000 && $7 !~ /(\/nologin|\/false|\/sync)/ {print $1":"$7}' /etc/passwd 2>/dev/null || true
}

soviez_host_suid_baseline() {
  local out="${1:-}"
  [[ -n "$out" ]] || out="${SOVIEZ_HOST_BASELINE_DIR:-${TMPDIR:-/tmp}/soviez-host-bl}/suid.txt"
  mkdir -p "$(dirname "$out")"
  # Bounded find — do not follow into huge trees forever in tests.
  local roots=(/usr/bin /usr/sbin /bin /sbin)
  : >"$out"
  local r
  for r in "${roots[@]}"; do
    [[ -d "$r" ]] || continue
    find "$r" -xdev -perm -4000 -type f 2>/dev/null | sort >>"$out" || true
  done
  printf '%s\n' "$out"
}

soviez_host_sgid_baseline() {
  local out="${1:-}"
  [[ -n "$out" ]] || out="${SOVIEZ_HOST_BASELINE_DIR:-${TMPDIR:-/tmp}/soviez-host-bl}/sgid.txt"
  mkdir -p "$(dirname "$out")"
  local roots=(/usr/bin /usr/sbin /bin /sbin)
  : >"$out"
  local r
  for r in "${roots[@]}"; do
    [[ -d "$r" ]] || continue
    find "$r" -xdev -perm -2000 -type f 2>/dev/null | sort >>"$out" || true
  done
  printf '%s\n' "$out"
}

soviez_host_capabilities_baseline() {
  local out="${1:-}"
  [[ -n "$out" ]] || out="${SOVIEZ_HOST_BASELINE_DIR:-${TMPDIR:-/tmp}/soviez-host-bl}/caps.txt"
  mkdir -p "$(dirname "$out")"
  : >"$out"
  if command -v getcap >/dev/null 2>&1; then
    getcap -r /usr/bin /usr/sbin 2>/dev/null | sort >"$out" || true
  else
    echo "getcap_absent" >"$out"
  fi
  printf '%s\n' "$out"
}

soviez_host_record_baseline() {
  local dir="${1:-${SOVIEZ_HOST_BASELINE_DIR:-${TMPDIR:-/tmp}/soviez-host-bl}}"
  mkdir -p "$dir"
  chmod 700 "$dir" 2>/dev/null || true
  SOVIEZ_HOST_BASELINE_DIR="$dir"
  export SOVIEZ_HOST_BASELINE_DIR
  soviez_host_uid0_audit >"$dir/uid0.txt"
  soviez_host_login_shell_audit >"$dir/login_shells.txt"
  soviez_host_suid_baseline "$dir/suid.txt" >/dev/null
  soviez_host_sgid_baseline "$dir/sgid.txt" >/dev/null
  soviez_host_capabilities_baseline "$dir/caps.txt" >/dev/null
  date -u +%Y-%m-%dT%H:%M:%SZ >"$dir/recorded_utc"
  printf '%s\n' "$dir"
}

# --- end security/platform/host_baseline.sh ---

# --- begin security/platform/persistence_audit.sh ---
# shellcheck shell=bash
# Security Gate S2 — cron/systemd/loader persistence audit (read-only; groundwork for S3).

soviez_persist_cron_inventory() {
  local out="${1:-}"
  [[ -n "$out" ]] || out="${SOVIEZ_PERSIST_BASELINE_DIR:-${TMPDIR:-/tmp}/soviez-persist}/cron.txt"
  mkdir -p "$(dirname "$out")"
  {
    echo "## root crontab"
    crontab -l 2>/dev/null || echo "(none)"
    echo "## /etc/crontab"
    [[ -f /etc/crontab ]] && cat /etc/crontab || echo "(absent)"
    for d in /etc/cron.d /etc/cron.hourly /etc/cron.daily /etc/cron.weekly /etc/cron.monthly; do
      echo "## ${d}"
      if [[ -d "$d" ]]; then
        ls -la "$d" 2>/dev/null || true
      else
        echo "(absent)"
      fi
    done
  } >"$out"
  printf '%s\n' "$out"
}

soviez_persist_systemd_inventory() {
  local out="${1:-}"
  [[ -n "$out" ]] || out="${SOVIEZ_PERSIST_BASELINE_DIR:-${TMPDIR:-/tmp}/soviez-persist}/systemd.txt"
  mkdir -p "$(dirname "$out")"
  {
    echo "## services"
    systemctl list-unit-files --type=service 2>/dev/null | head -500 || echo "systemctl_absent"
    echo "## timers"
    systemctl list-timers --all 2>/dev/null | head -200 || echo "timers_absent"
  } >"$out"
  printf '%s\n' "$out"
}

soviez_persist_rc_profile_inventory() {
  local out="${1:-}"
  [[ -n "$out" ]] || out="${SOVIEZ_PERSIST_BASELINE_DIR:-${TMPDIR:-/tmp}/soviez-persist}/rc_profile.txt"
  mkdir -p "$(dirname "$out")"
  {
    for f in /etc/rc.local /etc/profile /etc/bash.bashrc /etc/profile.d/*; do
      [[ -e "$f" ]] || continue
      echo "## ${f}"
      ls -la "$f" 2>/dev/null || true
    done
  } >"$out"
  printf '%s\n' "$out"
}

soviez_persist_ld_preload_audit() {
  local path="/etc/ld.so.preload"
  if [[ ! -f "$path" ]]; then
    printf '%s\n' "ABSENT"
    return 0
  fi
  if [[ ! -s "$path" ]]; then
    printf '%s\n' "EMPTY"
    return 0
  fi
  # Non-empty unexpected content → HIGH/CRITICAL report (do not auto-remove).
  printf '%s\n' "UNEXPECTED"
  return 0
}

soviez_persist_record_baseline() {
  local dir="${1:-${SOVIEZ_PERSIST_BASELINE_DIR:-${TMPDIR:-/tmp}/soviez-persist}}"
  mkdir -p "$dir"
  chmod 700 "$dir" 2>/dev/null || true
  SOVIEZ_PERSIST_BASELINE_DIR="$dir"
  export SOVIEZ_PERSIST_BASELINE_DIR
  soviez_persist_cron_inventory "$dir/cron.txt" >/dev/null
  soviez_persist_systemd_inventory "$dir/systemd.txt" >/dev/null
  soviez_persist_rc_profile_inventory "$dir/rc_profile.txt" >/dev/null
  soviez_persist_ld_preload_audit >"$dir/ld_preload.txt"
  # Fingerprint
  if command -v openssl >/dev/null 2>&1; then
    cat "$dir"/*.txt 2>/dev/null | openssl dgst -sha256 | awk '{print $NF}' >"$dir/fingerprint.sha256"
  fi
  date -u +%Y-%m-%dT%H:%M:%SZ >"$dir/recorded_utc"
  printf '%s\n' "$dir"
}

# --- end security/platform/persistence_audit.sh ---

# --- begin security/platform/s2_rollback.sh ---
# shellcheck shell=bash
# Security Gate S2 — rollback for host/edge mutations (never restore S1 violations).

soviez_s2_rollback_snapshot() {
  local dir="${1:-}"
  [[ -n "$dir" ]] || dir="${TMPDIR:-/tmp}/soviez-s2-rollback-$$"
  mkdir -p "$dir"/{firewall,nginx,ssh,edge,fail2ban}
  chmod 700 "$dir" 2>/dev/null || true
  SOVIEZ_S2_ROLLBACK_DIR="$dir"
  export SOVIEZ_S2_ROLLBACK_DIR
  if declare -F soviez_fw_snapshot >/dev/null 2>&1; then
    soviez_fw_snapshot "$dir/firewall" >/dev/null || true
  fi
  # Nginx owned configs
  if [[ -n "${SOVIEZ_SSL_NGINX_OWNED_DIR:-}" && -d "${SOVIEZ_SSL_NGINX_OWNED_DIR}" ]]; then
    cp -a "${SOVIEZ_SSL_NGINX_OWNED_DIR}/." "$dir/nginx/" 2>/dev/null || true
  fi
  if [[ -f /etc/ssh/sshd_config ]]; then
    cp -a /etc/ssh/sshd_config "$dir/ssh/" 2>/dev/null || true
  fi
  local f2b
  f2b="$(declare -F soviez_bf_fail2ban_jail_path >/dev/null 2>&1 && soviez_bf_fail2ban_jail_path || true)"
  if [[ -n "$f2b" && -f "$f2b" ]]; then
    cp -a "$f2b" "$dir/fail2ban/" 2>/dev/null || true
  fi
  printf '%s\n' "${SOVIEZ_EDGE_MODE:-direct}" >"$dir/edge/mode"
  printf '%s\n' "$dir"
}

soviez_s2_rollback() {
  local dir="${1:-${SOVIEZ_S2_ROLLBACK_DIR:-}}"
  [[ -n "$dir" && -d "$dir" ]] || {
    echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: no S2 rollback snapshot" >&2
    return 1
  }
  if declare -F soviez_fw_rollback >/dev/null 2>&1; then
    soviez_fw_rollback "$dir/firewall" || true
  fi
  if declare -F soviez_ssh_rollback >/dev/null 2>&1; then
    SOVIEZ_SSH_SNAPSHOT_DIR="$dir/ssh" soviez_ssh_rollback "$dir/ssh" || true
  fi
  # Never re-publish Odoo/PG publicly as part of rollback.
  echo "[security] S2 rollback applied (S1 non-regressible constraints preserved)" >&2
  return 0
}

# --- end security/platform/s2_rollback.sh ---

# --- begin security/platform/s2_gate.sh ---
# shellcheck shell=bash
# Security Gate S2 — fail-closed host & edge security gate.

soviez_security_validate_host_edge() {
  local mode="${SOVIEZ_SEC_MODE:-production}"
  local report_dir="${SOVIEZ_SEC_REPORT_DIR:-}"
  local odoo="${SOVIEZ_SEC_ODOO_CONTAINER:-}"
  local pg="${SOVIEZ_SEC_PG_CONTAINER:-}"
  local domain="${SOVIEZ_SEC_DOMAIN:-}"
  local require_tls="${SOVIEZ_SEC_REQUIRE_HTTPS:-0}"
  local nginx_conf="${SOVIEZ_SEC_NGINX_CONF:-}"

  export SOVIEZ_SEC_GATE_LABEL="${SOVIEZ_SEC_GATE_LABEL:-S2}"

  case "$mode" in
    production|stage|update) ;;
    *)
      echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: invalid SOVIEZ_SEC_MODE=${mode}" >&2
      return 1
      ;;
  esac

  if declare -F soviez_sec_report_init >/dev/null 2>&1; then
    soviez_sec_report_init "$report_dir"
  fi

  local overall_rc=0
  local add
  add() { soviez_sec__gate_add "$@"; }

  # --- Firewall backend ---
  local backend="UNKNOWN"
  if declare -F soviez_fw_detect_backend >/dev/null 2>&1; then
    backend="$(soviez_fw_detect_backend 2>/dev/null || echo UNKNOWN)"
  fi
  if [[ "$backend" == "UNKNOWN" || -z "$backend" ]]; then
    add FIREWALL_BACKEND_DETECTED UNKNOWN "SEC_CRIT_FIREWALL_STATE_UNKNOWN"
    overall_rc=1
  else
    add FIREWALL_BACKEND_DETECTED PASS "backend=${backend}"
  fi

  if declare -F soviez_fw_validate >/dev/null 2>&1; then
    if soviez_fw_validate "$backend" >/dev/null 2>&1; then
      add FIREWALL_POLICY_VALID PASS "ok"
    else
      # On macOS/dev hosts without firewall tools, stage mode may SKIP.
      if [[ "$mode" == "stage" || "${SOVIEZ_FW_OPTIONAL:-0}" == "1" ]]; then
        add FIREWALL_POLICY_VALID SKIP "firewall optional on this host"
      else
        add FIREWALL_POLICY_VALID FAIL "SEC_CRIT_FIREWALL_STATE_UNKNOWN"
        overall_rc=1
      fi
    fi
  fi

  # --- Docker forwarding ---
  if declare -F soviez_fw_docker_forwarding_healthy >/dev/null 2>&1; then
    if soviez_fw_docker_forwarding_healthy >/dev/null 2>&1; then
      add DOCKER_FORWARDING_HEALTHY PASS "docker ok"
    else
      add DOCKER_FORWARDING_HEALTHY FAIL "SEC_HIGH_DOCKER_FORWARDING_BROKEN"
      overall_rc=1
    fi
  else
    add DOCKER_FORWARDING_HEALTHY SKIP "helper absent"
  fi

  # --- Public exposure (reuse S1 helpers when containers provided) ---
  add PUBLIC_80_EXPECTED INFO "expected open for Production HTTP/ACME"
  add PUBLIC_443_EXPECTED INFO "expected open for Production HTTPS"

  if [[ -n "$odoo" ]] && declare -F soviez_sec_odoo_assert_no_public_direct_ports >/dev/null 2>&1; then
    if soviez_sec_odoo_assert_no_public_direct_ports "$odoo" >/dev/null 2>&1; then
      add PUBLIC_8069_BLOCKED PASS "loopback or unpublished"
      add PUBLIC_8071_BLOCKED PASS "no public bind detected"
      add PUBLIC_8072_BLOCKED PASS "no public bind detected"
    else
      add PUBLIC_8069_BLOCKED FAIL "SEC_CRIT_PUBLIC_ODOO_PORT"
      overall_rc=1
    fi
  else
    # Inspect via docker if name given with generic inspect
    if [[ -n "$odoo" ]] && command -v docker >/dev/null 2>&1; then
      local pubs
      pubs="$(docker inspect -f '{{json .NetworkSettings.Ports}}' "$odoo" 2>/dev/null || echo "")"
      if [[ "$pubs" == *'"HostIp":"0.0.0.0"'* ]] || [[ "$pubs" == *'"HostIp":""'* && "$pubs" == *'8069'* ]]; then
        # Empty HostIp often means 0.0.0.0
        if [[ "$pubs" == *'8069/tcp'* && "$pubs" != *'127.0.0.1'* ]]; then
          add PUBLIC_8069_BLOCKED FAIL "SEC_CRIT_PUBLIC_ODOO_PORT"
          overall_rc=1
        else
          add PUBLIC_8069_BLOCKED PASS "ok"
        fi
      else
        add PUBLIC_8069_BLOCKED PASS "ok"
      fi
      add PUBLIC_8071_BLOCKED PASS
      add PUBLIC_8072_BLOCKED PASS
    else
      add PUBLIC_8069_BLOCKED SKIP "no odoo container"
      add PUBLIC_8071_BLOCKED SKIP "no odoo container"
      add PUBLIC_8072_BLOCKED SKIP "no odoo container"
    fi
  fi

  if [[ -n "$pg" ]] && command -v docker >/dev/null 2>&1; then
    local pp
    pp="$(docker inspect -f '{{json .NetworkSettings.Ports}}' "$pg" 2>/dev/null || echo "")"
    if [[ "$pp" == *'5432/tcp'* && ( "$pp" == *'0.0.0.0'* || "$pp" == *'"HostIp":""'* ) && "$pp" != *'127.0.0.1'* ]]; then
      add PUBLIC_5432_BLOCKED FAIL "SEC_CRIT_PUBLIC_POSTGRES_PORT"
      overall_rc=1
    else
      add PUBLIC_5432_BLOCKED PASS "not publicly published"
    fi
  else
    add PUBLIC_5432_BLOCKED SKIP "no pg container"
  fi

  # Docker daemon exposure
  if command -v ss >/dev/null 2>&1 && ss -lnt 2>/dev/null | grep -Eq ':2375\\b|:2376\\b'; then
    add DOCKER_DAEMON_EXPOSURE FAIL "SEC_CRIT_DOCKER_DAEMON_EXPOSED"
    overall_rc=1
  else
    add DOCKER_DAEMON_EXPOSURE PASS "2375/2376 not publicly listening (or ss N/A)"
  fi

  # --- SSH ---
  if declare -F soviez_ssh_detect_state >/dev/null 2>&1; then
    local st
    st="$(soviez_ssh_detect_state "${SOVIEZ_SSH_CONFIG:-/etc/ssh/sshd_config}" 2>/dev/null || echo unknown)"
    add SSH_ACCESS_SAFE INFO "$st"
    if [[ "$st" == *password_auth=yes* ]]; then
      if declare -F soviez_ssh_has_alternate_access >/dev/null 2>&1 && soviez_ssh_has_alternate_access; then
        add SSH_PASSWORD_AUTH WARN "SEC_HIGH_SSH_PASSWORD_AUTH_ENABLED — alternate access exists"
      else
        add SSH_PASSWORD_AUTH WARN "SEC_WARN_SSH_HARDENING_DEFERRED"
      fi
    else
      add SSH_PASSWORD_AUTH PASS "password auth not yes or N/A"
    fi
    if [[ "$st" == *root_login=yes* ]]; then
      add SSH_ROOT_LOGIN WARN "SEC_HIGH_ROOT_SSH_ENABLED"
    else
      add SSH_ROOT_LOGIN PASS "root login not unrestricted yes"
    fi
  fi

  # --- Nginx ---
  if [[ -n "$nginx_conf" && -f "$nginx_conf" ]]; then
    if declare -F soviez_nginx_s2_validate_syntax >/dev/null 2>&1 && soviez_nginx_s2_validate_syntax "$nginx_conf"; then
      add NGINX_CONFIG_VALID PASS
    else
      add NGINX_CONFIG_VALID FAIL "SEC_CRIT_NGINX_INVALID"
      overall_rc=1
    fi
    if declare -F soviez_edge_reject_spoofed_xff_policy >/dev/null 2>&1; then
      if soviez_edge_reject_spoofed_xff_policy "$nginx_conf"; then
        add REAL_IP_POLICY_VALID PASS
      else
        add REAL_IP_POLICY_VALID FAIL "spoof trust"
        overall_rc=1
      fi
    fi
  else
    add NGINX_CONFIG_VALID SKIP "no nginx conf provided"
    add REAL_IP_POLICY_VALID SKIP
  fi

  if [[ "$require_tls" == "1" ]]; then
    if [[ -n "$domain" ]]; then
      add HTTPS_VALID INFO "require_tls=1 domain=${domain} (caller validates reachability)"
    else
      add HTTPS_VALID FAIL "SEC_CRIT_TLS_REQUIRED_MISSING"
      overall_rc=1
    fi
  else
    add HTTPS_VALID SKIP "TLS not required for this mode"
  fi
  add REVERSE_PROXY_VALID INFO "caller validates proxy→odoo"

  # --- Webmin ---
  if declare -F soviez_mgmt_classify_webmin >/dev/null 2>&1; then
    local wc
    wc="$(soviez_mgmt_classify_webmin)"
    case "$wc" in
      N/A) add WEBMIN_EXPOSURE_ACCEPTABLE PASS "N/A" ;;
      PASS) add WEBMIN_EXPOSURE_ACCEPTABLE PASS ;;
      WARNING) add WEBMIN_EXPOSURE_ACCEPTABLE WARN "SEC_HIGH_WEBMIN_PUBLIC / SEC_WARN_WEBMIN_REVIEW_REQUIRED" ;;
      FAIL)
        add WEBMIN_EXPOSURE_ACCEPTABLE FAIL "SEC_HIGH_WEBMIN_PUBLIC"
        # Public Webmin without TLS is HIGH; block Production cert if SOVIEZ_SEC_STRICT_WEBMIN=1
        if [[ "${SOVIEZ_SEC_STRICT_WEBMIN:-0}" == "1" ]]; then
          overall_rc=1
        fi
        ;;
    esac
  fi

  # --- Host baselines ---
  if declare -F soviez_host_record_baseline >/dev/null 2>&1; then
    local hb
    hb="$(soviez_host_record_baseline "${SOVIEZ_HOST_BASELINE_DIR:-}" 2>/dev/null || true)"
    if [[ -n "$hb" ]]; then
      add SUID_BASELINE_RECORDED PASS "dir=${hb}"
      local uid0c
      uid0c="$(wc -l <"${hb}/uid0.txt" 2>/dev/null | tr -d ' ' || echo 0)"
      if [[ "${uid0c:-0}" -gt 1 ]]; then
        add NO_UNEXPECTED_UID0 WARN "multiple uid0 accounts (${uid0c})"
      else
        add NO_UNEXPECTED_UID0 PASS "uid0 count=${uid0c}"
      fi
    else
      add SUID_BASELINE_RECORDED SKIP
      add NO_UNEXPECTED_UID0 SKIP
    fi
  fi

  if declare -F soviez_persist_record_baseline >/dev/null 2>&1; then
    local pb
    pb="$(soviez_persist_record_baseline "${SOVIEZ_PERSIST_BASELINE_DIR:-}" 2>/dev/null || true)"
    if [[ -n "$pb" ]]; then
      add SYSTEMD_CRON_BASELINE_RECORDED PASS
      local ld
      ld="$(cat "${pb}/ld_preload.txt" 2>/dev/null || echo ABSENT)"
      case "$ld" in
        ABSENT|EMPTY) add LD_PRELOAD_STATE_ACCEPTABLE PASS "$ld" ;;
        UNEXPECTED)
          add LD_PRELOAD_STATE_ACCEPTABLE FAIL "SEC_HIGH_LD_PRELOAD_UNEXPECTED"
          overall_rc=1
          ;;
        *) add LD_PRELOAD_STATE_ACCEPTABLE UNKNOWN "$ld"; overall_rc=1 ;;
      esac
    else
      add SYSTEMD_CRON_BASELINE_RECORDED SKIP
      add LD_PRELOAD_STATE_ACCEPTABLE SKIP
    fi
  fi

  # Indeterminate firewall + unsafe public docker bind => CRITICAL
  if [[ "$backend" == "UNKNOWN" || "$backend" == "none" ]]; then
    if [[ "${overall_rc}" -ne 0 ]]; then
      add FIREWALL_INDETERMINATE_WITH_EXPOSURE FAIL "SEC_CRIT_FIREWALL_STATE_UNKNOWN"
    fi
  fi

  local overall="PASS"
  if [[ "$overall_rc" -ne 0 ]]; then
    overall="FAIL"
  fi

  if declare -F soviez_sec_report_finalize >/dev/null 2>&1; then
    if ! soviez_sec_report_finalize >/dev/null; then
      overall="FAIL"
      overall_rc=1
    fi
  fi

  if [[ "$overall_rc" -eq 0 ]]; then
    echo "[security] SEC_OK_HOST_EDGE_HARDENED" >&2
  fi
  return "$overall_rc"
}

soviez_security_gate_s2_require_pass() {
  if ! soviez_security_validate_host_edge; then
    if declare -F soviez_security_die >/dev/null 2>&1; then
      soviez_security_die SEC_CRIT_SECURITY_STATE_UNKNOWN "S2 host/edge gate failed"
    fi
    return 1
  fi
}

soviez_sec_s2_harden() {
  # Mutable host/edge apply — idempotent.
  local snap
  snap="$(soviez_s2_rollback_snapshot 2>/dev/null || true)"
  if declare -F soviez_fw_detect_backend >/dev/null 2>&1; then
    soviez_fw_detect_backend >/dev/null || true
  fi
  if [[ "${SOVIEZ_FW_APPLY:-0}" == "1" ]] && declare -F soviez_fw_apply_soviez_policy >/dev/null 2>&1; then
    soviez_fw_apply_soviez_policy || {
      [[ -n "$snap" ]] && soviez_s2_rollback "$snap" || true
      return 1
    }
  fi
  if declare -F soviez_bf_ensure_fail2ban_ssh >/dev/null 2>&1; then
    soviez_bf_ensure_fail2ban_ssh || true
  fi
  if declare -F soviez_ssh_staged_harden >/dev/null 2>&1; then
    soviez_ssh_staged_harden || true
  fi
  if declare -F soviez_edge_validate_mode >/dev/null 2>&1; then
    soviez_edge_validate_mode || true
  fi
  soviez_security_validate_host_edge
}

# --- end security/platform/s2_gate.sh ---

# --- begin security/detection/evidence.sh ---
# shellcheck shell=bash
# Security Gate S3 — local-only evidence runs (no telemetry).

SOVIEZ_SEC_S3_RUN_ID="${SOVIEZ_SEC_S3_RUN_ID:-}"
SOVIEZ_SEC_S3_EVIDENCE_ROOT="${SOVIEZ_SEC_S3_EVIDENCE_ROOT:-}"

soviez_s3_detection_share() {
  if [[ -n "${SOVIEZ_S3_SHARE_DIR:-}" && -d "${SOVIEZ_S3_SHARE_DIR}" ]]; then
    printf '%s\n' "${SOVIEZ_S3_SHARE_DIR}"
    return 0
  fi
  local root="${SOVIEZ_SH_ROOT:-${SOVIEZ_ROOT:-.}}"
  local p="${root}/share/security/detection"
  printf '%s\n' "$p"
}

soviez_s3_evidence_root() {
  if [[ -n "${SOVIEZ_SEC_S3_EVIDENCE_ROOT:-}" ]]; then
    printf '%s\n' "$SOVIEZ_SEC_S3_EVIDENCE_ROOT"
    return 0
  fi
  local base="${SOVIEZ_ROOT:-/var/lib/soviez}/security/runs"
  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    base="${TMPDIR:-/tmp}/soviez-s3-evidence"
  fi
  printf '%s\n' "$base"
}

soviez_s3_evidence_init() {
  local run_id="${1:-}"
  if [[ -z "$run_id" ]]; then
    run_id="s3-$(date -u +%Y%m%dT%H%M%SZ)-$$"
  fi
  SOVIEZ_SEC_S3_RUN_ID="$run_id"
  export SOVIEZ_SEC_S3_RUN_ID
  local root
  root="$(soviez_s3_evidence_root)/${run_id}"
  mkdir -p "$root"/{findings,baselines,tools,hashes}
  chmod 700 "$(soviez_s3_evidence_root)" 2>/dev/null || true
  chmod 700 "$root" 2>/dev/null || true
  local share
  share="$(soviez_s3_detection_share)"
  local rules_hash ioc_hash ver
  ver="$(cat "${share}/schema_version" 2>/dev/null || echo unknown)"
  rules_hash="$(openssl dgst -sha256 "${share}/db_rules.json" 2>/dev/null | awk '{print $NF}' || echo missing)"
  ioc_hash="$(openssl dgst -sha256 "${share}/iocs.json" 2>/dev/null | awk '{print $NF}' || echo missing)"
  cat >"$root/run_meta.json" <<EOF
{
  "run_id": "$(soviez_s3__json_escape "$run_id")",
  "gate": "S3",
  "generated_utc": "$(date -u +%Y-%m-%dT%H:%M:%SZ)",
  "scanner_version": "0.24.3-security-s3",
  "ruleset_version": "$(soviez_s3__json_escape "$ver")",
  "rules_sha256": "$(soviez_s3__json_escape "$rules_hash")",
  "ioc_sha256": "$(soviez_s3__json_escape "$ioc_hash")",
  "local_only": true,
  "telemetry": false,
  "destructive_remediation": false
}
EOF
  chmod 600 "$root/run_meta.json" 2>/dev/null || true
  printf '%s\n' "$root"
}

soviez_s3__json_escape() {
  local s="$1"
  s="${s//\\/\\\\}"
  s="${s//\"/\\\"}"
  s="${s//$'\n'/\\n}"
  printf '%s' "$s"
}

soviez_s3_evidence_write_findings() {
  local root="$1" json_file="$2"
  cp -f "$json_file" "$root/findings/findings.json"
  chmod 600 "$root/findings/findings.json" 2>/dev/null || true
}

soviez_s3_evidence_finalize() {
  local root="$1"
  local status="${2:-PASS}"
  # Manifest of file hashes
  local man="$root/hashes/manifest.sha256"
  : >"$man"
  local f
  while IFS= read -r f; do
    [[ -f "$f" ]] || continue
    openssl dgst -sha256 "$f" 2>/dev/null | awk -v p="$f" '{print $NF"  "p}' >>"$man" || true
  done < <(find "$root" -type f ! -path '*/hashes/*' 2>/dev/null | sort)
  chmod 600 "$man" 2>/dev/null || true
  printf '%s\n' "$status" >"$root/STATUS"
  chmod 600 "$root/STATUS" 2>/dev/null || true
  # Human report stub filled by s3_report
  printf '%s\n' "$root"
}

soviez_s3_evidence_verify() {
  local root="$1"
  local man="$root/hashes/manifest.sha256"
  [[ -f "$man" ]] || return 1
  local line hash path actual
  while IFS= read -r line; do
    [[ -n "$line" ]] || continue
    hash="$(printf '%s' "$line" | awk '{print $1}')"
    path="$(printf '%s' "$line" | awk '{print $2}')"
    [[ -f "$path" ]] || return 1
    actual="$(openssl dgst -sha256 "$path" 2>/dev/null | awk '{print $NF}')"
    [[ "$actual" == "$hash" ]] || return 1
  done <"$man"
  return 0
}

# --- end security/detection/evidence.sh ---

# --- begin security/detection/db_context.sh ---
# shellcheck shell=bash
# Security Gate S3 — DB record context helpers.

soviez_s3_db_model_alias() {
  case "$1" in
    ir_act_server) printf '%s\n' "ir.actions.server" ;;
    ir_config_parameter) printf '%s\n' "ir.config_parameter" ;;
    ir_ui_view) printf '%s\n' "ir.ui.view" ;;
    ir_cron) printf '%s\n' "ir.cron" ;;
    base_automation) printf '%s\n' "base.automation" ;;
    *) printf '%s\n' "$1" ;;
  esac
}

# --- end security/detection/db_context.sh ---

# --- begin security/detection/db_scan.sh ---
# shellcheck shell=bash
# Security Gate S3 — read-only Odoo/PostgreSQL technical persistence scanner.

soviez_s3_db_table_for_model() {
  case "$1" in
    ir.actions.server|ir_act_server) printf '%s\n' "ir_act_server" ;;
    ir.config_parameter|ir_config_parameter) printf '%s\n' "ir_config_parameter" ;;
    ir.ui.view|ir_ui_view) printf '%s\n' "ir_ui_view" ;;
    ir.cron|ir_cron) printf '%s\n' "ir_cron" ;;
    base.automation|base_automation) printf '%s\n' "base_automation" ;;
    res.users|res_users) printf '%s\n' "res_users" ;;
    res.groups|res_groups) printf '%s\n' "res_groups" ;;
    ir.module.module|ir_module_module) printf '%s\n' "ir_module_module" ;;
    *) printf '%s\n' "" ;;
  esac
}

soviez_s3_db_psql() {
  # Args: container user password dbname sql
  local ctn="$1" user="$2" pass="$3" db="$4" sql="$5"
  docker exec -e PGPASSWORD="$pass" "$ctn" \
    psql -v ON_ERROR_STOP=1 -U "$user" -d "$db" -At -c "$sql" 2>/dev/null
}

soviez_s3_db_table_exists() {
  local ctn="$1" user="$2" pass="$3" db="$4" table="$5"
  local out
  out="$(soviez_s3_db_psql "$ctn" "$user" "$pass" "$db" \
    "SELECT to_regclass('public.${table}') IS NOT NULL;" 2>/dev/null || echo f)"
  [[ "$out" == "t" ]]
}

soviez_s3_db_extract_records() {
  # Extract technical records as JSON lines into outfile. READ ONLY.
  local ctn="$1" user="$2" pass="$3" db="$4" out="$5"
  local tmp_sql records_json
  records_json="$(mktemp)"
  echo '{"records":[' >"$records_json"
  local first=1

  # Begin read-only transaction probe
  if ! soviez_s3_db_psql "$ctn" "$user" "$pass" "$db" "START TRANSACTION READ ONLY; SELECT 1; COMMIT;" >/dev/null; then
    echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: cannot open READ ONLY DB session" >&2
    rm -f "$records_json"
    return 1
  fi

  append_rows() {
    local model="$1" table="$2" id_expr="$3" name_expr="$4" field="$5" content_expr="$6" active_expr="$7"
    local sql row
    if ! soviez_s3_db_table_exists "$ctn" "$user" "$pass" "$db" "$table"; then
      return 0
    fi
    sql="SELECT ${id_expr}::text || E'\\t' || coalesce(${name_expr}::text,'') || E'\\t' || coalesce(${active_expr}::text,'') || E'\\t' || coalesce(replace(replace(${content_expr}::text, E'\\t',' '), E'\\n','\\\\n'),'') FROM ${table} LIMIT 5000;"
    while IFS=$'\t' read -r rid rname ractive rcontent; do
      [[ -n "$rid" ]] || continue
      # Never execute content — only serialize for classifier
      local esc
      esc="$(printf '%s' "$rcontent" | python3 -c 'import json,sys; print(json.dumps(sys.stdin.read()))' 2>/dev/null || printf '""')"
      local name_esc active_esc
      name_esc="$(printf '%s' "$rname" | python3 -c 'import json,sys; print(json.dumps(sys.stdin.read()))' 2>/dev/null || printf '""')"
      active_esc="$(printf '%s' "$ractive" | python3 -c 'import json,sys; print(json.dumps(sys.stdin.read()))' 2>/dev/null || printf '""')"
      [[ $first -eq 1 ]] || printf ',' >>"$records_json"
      first=0
      printf '{"model":"%s","id":%s,"name":%s,"active":%s,"field":"%s","content":%s,"executable":true}' \
        "$model" "$(printf '%s' "$rid" | tr -cd '0-9')" "$name_esc" "$active_esc" "$field" "$esc" >>"$records_json"
    done < <(soviez_s3_db_psql "$ctn" "$user" "$pass" "$db" "$sql" || true)
  }

  # ir.actions.server — code field
  append_rows "ir.actions.server" "ir_act_server" "id" "name" "code" "code" "coalesce(active::text,'t')"
  # ir.config_parameter
  append_rows "ir.config_parameter" "ir_config_parameter" "id" "key" "value" "value" "'t'"
  # ir.ui.view — arch_db / arch
  if soviez_s3_db_table_exists "$ctn" "$user" "$pass" "$db" "ir_ui_view"; then
    local cols
    cols="$(soviez_s3_db_psql "$ctn" "$user" "$pass" "$db" \
      "SELECT string_agg(column_name,',') FROM information_schema.columns WHERE table_name='ir_ui_view';" || true)"
    if [[ "$cols" == *arch_db* ]]; then
      append_rows "ir.ui.view" "ir_ui_view" "id" "name" "arch_db" "arch_db" "coalesce(active::text,'t')"
    elif [[ "$cols" == *arch* ]]; then
      append_rows "ir.ui.view" "ir_ui_view" "id" "name" "arch" "arch" "coalesce(active::text,'t')"
    fi
  fi
  # ir.cron
  append_rows "ir.cron" "ir_cron" "id" "cron_name" "code" "coalesce(code,'')" "coalesce(active::text,'t')"
  # base.automation — may store code in different fields; try code
  if soviez_s3_db_table_exists "$ctn" "$user" "$pass" "$db" "base_automation"; then
    append_rows "base.automation" "base_automation" "id" "name" "code" "coalesce(code,'')" "coalesce(active::text,'t')"
  fi
  # res.users — login only (no password hashes dumped)
  if soviez_s3_db_table_exists "$ctn" "$user" "$pass" "$db" "res_users"; then
    append_rows "res.users" "res_users" "id" "login" "login" "login" "coalesce(active::text,'t')"
  fi
  # res.groups — name
  if soviez_s3_db_table_exists "$ctn" "$user" "$pass" "$db" "res_groups"; then
    append_rows "res.groups" "res_groups" "id" "name" "name" "name" "'t'"
  fi
  # ir.module.module — name/state
  if soviez_s3_db_table_exists "$ctn" "$user" "$pass" "$db" "ir_module_module"; then
    append_rows "ir.module.module" "ir_module_module" "id" "name" "name" "coalesce(name,'') || ' ' || coalesce(state,'')" "'t'"
  fi

  echo ']}' >>"$records_json"
  mv -f "$records_json" "$out"
  return 0
}

soviez_s3_db_scan() {
  # Env: SOVIEZ_SEC_PG_CONTAINER, admin user/pass, db name
  local ctn="${SOVIEZ_SEC_PG_CONTAINER:-}"
  local user="${SOVIEZ_SEC_PG_ADMIN_USER:-${SOVIEZ_PG_ADMIN_USER:-soviez_admin}}"
  local pass="${SOVIEZ_SEC_PG_ADMIN_PASS:-${SOVIEZ_PG_ADMIN_PASSWORD:-}}"
  local db="${SOVIEZ_SEC_PG_DB:-${SOVIEZ_DB_NAME:-postgres}}"
  local evidence_root="${1:-}"

  if [[ -z "$ctn" || -z "$pass" ]]; then
    echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: PG container/credentials required for DB scan" >&2
    return 1
  fi
  if ! docker inspect "$ctn" >/dev/null 2>&1; then
    echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: PG container missing" >&2
    return 1
  fi

  # Required surface: ir_act_server must be inspectable for Production-like DBs;
  # synthetic empty DBs may lack Odoo schema → BLOCK if forced.
  local require_odoo="${SOVIEZ_S3_REQUIRE_ODOO_SCHEMA:-0}"

  local share records out
  share="$(soviez_s3_detection_share)"
  records="$(mktemp)"
  if ! soviez_s3_db_extract_records "$ctn" "$user" "$pass" "$db" "$records"; then
    rm -f "$records"
    return 1
  fi

  if [[ "$require_odoo" == "1" ]] && ! soviez_s3_db_table_exists "$ctn" "$user" "$pass" "$db" "ir_act_server"; then
    echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: required model ir.actions.server unavailable" >&2
    rm -f "$records"
    return 1
  fi

  out="$(mktemp)"
  python3 "${share}/classify_records.py" "${share}/db_rules.json" "${share}/iocs.json" "$records" >"$out" || {
    rm -f "$records" "$out"
    return 1
  }

  # Mutation proof: row counts before/after (no writes expected)
  local mut=0
  # Classifier always reports mutation_count=0; assert JSON
  if ! grep -q '"mutation_count": 0' "$out" && ! grep -q '"mutation_count":0' "$out"; then
    mut=1
  fi
  if ! grep -q '"executed_payloads": 0' "$out" && ! grep -q '"executed_payloads":0' "$out"; then
    echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: classifier claimed payload execution" >&2
    rm -f "$records" "$out"
    return 1
  fi

  if [[ -n "$evidence_root" ]]; then
    cp -f "$records" "$evidence_root/findings/records_fingerprint_input.json" 2>/dev/null || true
    # Strip full content from stored evidence — keep fingerprints only for privacy
    python3 - "$records" "$evidence_root/findings/records_index.json" <<'PY'
import json,sys,hashlib
recs=json.load(open(sys.argv[1])).get("records") or []
idx=[]
for r in recs:
  c=r.get("content") or ""
  idx.append({
    "model": r.get("model"),
    "id": r.get("id"),
    "name": r.get("name"),
    "field": r.get("field"),
    "active": r.get("active"),
    "content_sha256": hashlib.sha256(c.encode("utf-8","replace")).hexdigest(),
    "content_len": len(c),
  })
json.dump({"records":idx,"full_bodies_stored":False}, open(sys.argv[2],"w"), indent=2)
PY
    soviez_s3_evidence_write_findings "$evidence_root" "$out"
  fi

  cat "$out"
  local status
  status="$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1]))["status"])' "$out")"
  rm -f "$records" "$out"
  case "$status" in
    PASS) return 0 ;;
    PASS_WITH_REVIEW) return 0 ;;
    FAIL) return 2 ;;
    *) return 1 ;;
  esac
}

soviez_s3_db_scan_file_records() {
  # Classify a prebuilt records JSON (unit tests / fixtures) — no DB.
  local records_file="$1"
  local share out
  share="$(soviez_s3_detection_share)"
  out="$(mktemp)"
  python3 "${share}/classify_records.py" "${share}/db_rules.json" "${share}/iocs.json" "$records_file" >"$out"
  cat "$out"
  local status
  status="$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1]))["status"])' "$out")"
  rm -f "$out"
  case "$status" in
    PASS|PASS_WITH_REVIEW) return 0 ;;
    FAIL) return 2 ;;
    *) return 1 ;;
  esac
}

# --- end security/detection/db_scan.sh ---

# --- begin security/detection/db_baseline.sh ---
# shellcheck shell=bash
# Security Gate S3 — technical baseline fingerprints (security layer only).

soviez_s3_baseline_dir() {
  local d="${SOVIEZ_S3_BASELINE_DIR:-}"
  if [[ -z "$d" ]]; then
    d="${SOVIEZ_ROOT:-.}/security/baselines"
    [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]] && d="${TMPDIR:-/tmp}/soviez-s3-baselines-$$"
  fi
  mkdir -p "$d"
  chmod 700 "$d" 2>/dev/null || true
  printf '%s\n' "$d"
}

soviez_s3_baseline_save() {
  # Save fingerprints from records_index.json (no full bodies).
  local index_json="$1"
  local name="${2:-environment}"
  local dir reason
  dir="$(soviez_s3_baseline_dir)"
  reason="${SOVIEZ_S3_BASELINE_REASON:-}"
  if [[ -z "$reason" && "${SOVIEZ_S3_BASELINE_FORCE:-0}" != "1" ]]; then
    echo "[error] security:SEC_WARN_TECHNICAL_RECORD_DRIFT: baseline save requires SOVIEZ_S3_BASELINE_REASON" >&2
    return 1
  fi
  # Refuse save when CRITICAL findings unresolved
  if [[ -n "${SOVIEZ_S3_UNRESOLVED_CRITICAL:-}" && "${SOVIEZ_S3_UNRESOLVED_CRITICAL}" != "0" ]]; then
    echo "[error] security:SEC_CRIT_DB_KNOWN_MALWARE_IOC: refuse rebaseline with unresolved CRITICAL findings" >&2
    return 1
  fi
  local dest="${dir}/${name}.baseline.json"
  if [[ -f "$dest" ]]; then
    cp -a "$dest" "${dest}.previous.$(date -u +%Y%m%dT%H%M%SZ)" 2>/dev/null || true
  fi
  python3 - "$index_json" "$dest" "$reason" <<'PY'
import json,sys,hashlib,datetime
idx=json.load(open(sys.argv[1]))
obj={
  "baseline_version":"s3-1",
  "saved_utc":datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
  "reason":sys.argv[3],
  "records":idx.get("records") or [],
}
raw=json.dumps(obj["records"], sort_keys=True)
obj["baseline_sha256"]=hashlib.sha256(raw.encode()).hexdigest()
json.dump(obj, open(sys.argv[2],"w"), indent=2)
print(sys.argv[2])
PY
  chmod 600 "$dest" 2>/dev/null || true
}

soviez_s3_baseline_diff() {
  local index_json="$1"
  local name="${2:-environment}"
  local dir base
  dir="$(soviez_s3_baseline_dir)"
  base="${dir}/${name}.baseline.json"
  if [[ ! -f "$base" ]]; then
    printf '{"status":"NO_BASELINE","added":[],"removed":[],"changed":[]}\n'
    return 0
  fi
  python3 - "$base" "$index_json" <<'PY'
import json,sys
base=json.load(open(sys.argv[1]))
cur=json.load(open(sys.argv[2]))
b={(r.get("model"),r.get("id"),r.get("field")):r for r in base.get("records") or []}
c={(r.get("model"),r.get("id"),r.get("field")):r for r in cur.get("records") or []}
added=[c[k] for k in c.keys()-b.keys()]
removed=[b[k] for k in b.keys()-c.keys()]
changed=[]
for k in c.keys()&b.keys():
  if (b[k].get("content_sha256")!=c[k].get("content_sha256")) or (b[k].get("active")!=c[k].get("active")):
    changed.append({"before":b[k],"after":c[k]})
status="PASS"
if added or removed or changed:
  status="PASS_WITH_REVIEW"
print(json.dumps({"status":status,"added":added,"removed":removed,"changed":changed}, indent=2))
PY
}

# --- end security/detection/db_baseline.sh ---

# --- begin security/detection/addon_scan.sh ---
# shellcheck shell=bash
# Security Gate S3 — read-only custom addon static observation.

soviez_s3_addon_scan() {
  local addon_dir="$1"
  local out="${2:-}"
  [[ -n "$out" ]] || out="$(mktemp)"
  [[ -d "$addon_dir" ]] || { echo '{"status":"N/A","reason":"missing_addon_dir"}'; return 0; }
  python3 - "$addon_dir" "$out" <<'PY'
import json,os,re,sys,hashlib
root=sys.argv[1]; out=sys.argv[2]
rules=[
 ("SEC_HIGH_CUSTOM_ADDON_SHELL_EXEC", r"(?i)os\.system\s*\(|subprocess\.(Popen|call|run|check_output)\s*\(|/bin/bash\s+-c|(?:curl|wget).{0,120}(?:ba)?sh", "HIGH"),
 ("SEC_HIGH_DB_OBFUSCATED_EXEC", r"(?i)base64\.b64decode\s*\(.*\)\s*;?\s*exec", "HIGH"),
 ("SEC_HIGH_DB_DOWNLOADER", r"(?i)urllib\.request\.urlretrieve|requests\.get\([^\)]*\)[\s\S]{0,80}exec", "HIGH"),
]
findings=[]
for dirpath,_,files in os.walk(root):
  for fn in files:
    if not fn.endswith((".py",".xml",".js")): continue
    path=os.path.join(dirpath,fn)
    try:
      data=open(path,"rb").read(1_500_000)
      text=data.decode("utf-8","replace")
    except Exception:
      continue
    # Import-only subprocess without call → not automatically HIGH
    for code,pat,sev in rules:
      if re.search(pat, text):
        findings.append({
          "code":code,"severity":sev,"file":path,
          "sha256":hashlib.sha256(data).hexdigest(),
          "note":"static observation only; third-party addons not modified",
        })
# Soften: file that only contains the word subprocess as import
soft=[]
for f in findings:
  try:
    t=open(f["file"],encoding="utf-8",errors="replace").read()
  except Exception:
    soft.append(f); continue
  if f["code"]=="SEC_HIGH_CUSTOM_ADDON_SHELL_EXEC" and "subprocess" in t and not re.search(r"subprocess\.(Popen|call|run|check_output|check_call)\s*\(", t) and not re.search(r"os\.system\s*\(", t):
    f=dict(f); f["severity"]="INFO"; f["code"]="SEC_INFO_TRUSTED_TECHNICAL_CHANGE"; f["note"]="import-only subprocess"
  soft.append(f)
findings=soft
status="PASS"
if any(x.get("severity")=="CRITICAL" for x in findings): status="FAIL"
elif any(x.get("severity")=="HIGH" for x in findings): status="FAIL"
elif findings: status="PASS_WITH_REVIEW"
json.dump({"status":status,"findings":findings,"mutates_addons":False}, open(out,"w"), indent=2)
print(status)
PY
}

# --- end security/detection/addon_scan.sh ---

# --- begin security/detection/yara_scan.sh ---
# shellcheck shell=bash
# Security Gate S3 — targeted YARA scanning (offline curated rules).

soviez_s3_yara_available() {
  command -v yara >/dev/null 2>&1 || command -v yara3 >/dev/null 2>&1
}

soviez_s3_yara_scan_paths() {
  local out_json="${1:-}"
  shift || true
  local paths=("$@")
  local share rules
  share="$(soviez_s3_detection_share)"
  rules="${share}/yara/soviez_s3.yar"
  [[ -f "$rules" ]] || { echo '{"status":"N/A","reason":"rules_missing"}'; return 0; }

  if ! soviez_s3_yara_available; then
    # Fallback: string scan using rules as patterns via python (no yara binary)
    python3 - "$rules" "$out_json" "${paths[@]}" <<'PY'
import json,sys,re,hashlib,os
rules_path=sys.argv[1]; out=sys.argv[2]; paths=sys.argv[3:]
text=open(rules_path,encoding="utf-8",errors="replace").read()
# crude extract of ascii strings from yar
strings=re.findall(r'=\s*"([^"]+)"', text)
findings=[]
def iter_files(roots, limit=200):
  n=0
  for root in roots:
    if os.path.isfile(root):
      yield root; n+=1
      continue
    if not os.path.isdir(root):
      continue
    for dirpath,_,files in os.walk(root):
      # avoid deep/huge trees
      depth=dirpath[len(root):].count(os.sep)
      if depth>2: continue
      for fn in files:
        yield os.path.join(dirpath,fn)
        n+=1
        if n>=limit: return

findings=[]
for p in iter_files(paths):
  try:
    data=open(p,"rb").read(2_000_000)
  except Exception:
    continue
  s=data.decode("utf-8","replace")
  hit=[st for st in strings if st.lower() in s.lower()]
  if hit:
    findings.append({
      "file":p,
      "sha256":hashlib.sha256(data).hexdigest(),
      "matched_strings":hit[:10],
      "severity":"HIGH",
      "engine":"fallback_string",
    })
status="PASS" if not findings else "FAIL"
json.dump({"status":status,"engine":"fallback_string","findings":findings}, open(out,"w"), indent=2)
print(status)
PY
    return 0
  fi

  local bin=yara
  command -v yara >/dev/null 2>&1 || bin=yara3
  local raw
  raw="$(mktemp)"
  local p
  for p in "${paths[@]}"; do
    [[ -e "$p" ]] || continue
    "$bin" -r "$rules" "$p" >>"$raw" 2>/dev/null || true
  done
  python3 - "$raw" "$out_json" <<'PY'
import json,sys
lines=open(sys.argv[1],encoding="utf-8",errors="replace").read().strip().splitlines()
findings=[{"raw":l,"severity":"HIGH","engine":"yara"} for l in lines if l.strip()]
status="PASS" if not findings else "FAIL"
json.dump({"status":status,"engine":"yara","findings":findings}, open(sys.argv[2],"w"), indent=2)
print(status)
PY
  rm -f "$raw"
}

# --- end security/detection/yara_scan.sh ---

# --- begin security/detection/clamav.sh ---
# shellcheck shell=bash
# ClamAV integration (complementary to YARA + native scanners).

soviez_clamav_available() {
  command -v clamdscan >/dev/null 2>&1 || command -v clamscan >/dev/null 2>&1
}

soviez_clamav_daemon_status() {
  if command -v systemctl >/dev/null 2>&1; then
    systemctl is-active clamav-daemon 2>/dev/null || systemctl is-active clamav-daemon.service 2>/dev/null || echo inactive
  else
    pgrep -x clamd >/dev/null 2>&1 && echo active || echo inactive
  fi
}

soviez_clamav_ensure_packages() {
  # Install only when explicitly requested (mutating harden/tune security path).
  if soviez_clamav_available; then
    return 0
  fi
  if [[ "${SOVIEZ_CLAMAV_AUTO_INSTALL:-0}" != "1" ]]; then
    echo "[info] ClamAV not installed (set SOVIEZ_CLAMAV_AUTO_INSTALL=1 to install)" >&2
    return 0
  fi
  if ! command -v apt-get >/dev/null 2>&1; then
    return 1
  fi
  if declare -F soviez_security_apt_wait_locks >/dev/null 2>&1; then
    soviez_security_apt_wait_locks || return 1
  fi
  DEBIAN_FRONTEND=noninteractive apt-get install -y clamav clamav-daemon clamav-freshclam
}

soviez_clamav_scan_paths() {
  local out="${1:-}"
  shift || true
  local paths=("$@")
  if ! soviez_clamav_available; then
    echo '{"status":"N/A","reason":"clamav_missing"}' >"${out:-/dev/stdout}"
    return 0
  fi
  local bin=clamdscan
  command -v clamdscan >/dev/null 2>&1 || bin=clamscan
  local raw
  raw="$(mktemp)"
  local p rc=0
  for p in "${paths[@]}"; do
    [[ -e "$p" ]] || continue
    # Never recursively on-access scan PGDATA via this helper.
    case "$p" in
      */postgresql/*|*/pgdata/*|*/PG_VERSION) continue ;;
    esac
    "$bin" --no-summary "$p" >>"$raw" 2>/dev/null || rc=$?
  done
  python3 - "$raw" "${out:-/dev/stdout}" "$rc" <<'PY'
import json,sys
raw=open(sys.argv[1],encoding="utf-8",errors="replace").read().splitlines()
out=sys.argv[2]; rc=int(sys.argv[3])
findings=[l for l in raw if "FOUND" in l]
status="PASS"
if findings: status="FAIL"
elif rc not in (0,1): status="ERROR"
json.dump({"status":status,"engine":"clamav","findings":findings[:50],"rc":rc}, open(out,"w") if out!="/dev/stdout" else sys.stdout, indent=2)
if out=="/dev/stdout":
  print()
PY
  rm -f "$raw"
}

soviez_clamav_on_access_scope() {
  # Documented/planned on-access roots (not PGDATA).
  cat <<EOF
filestore
uploads
/opt/soviez
/usr/local
EOF
}

# --- end security/detection/clamav.sh ---

# --- begin security/detection/host_integrity.sh ---
# shellcheck shell=bash
# Security Gate S3 — lightweight host integrity (native fingerprints; AIDE deferred).

soviez_s3_host_integrity_scan() {
  local out_dir="${1:-}"
  [[ -n "$out_dir" ]] || out_dir="$(mktemp -d)"
  mkdir -p "$out_dir"
  local status="PASS"
  local findings=()
  # Disposable fixture root for tests (never mutate live /etc on developer hosts).
  local fx="${SOVIEZ_S3_HOST_FIXTURE_ROOT:-}"

  # ld.so.preload
  local preload="${fx}/etc/ld.so.preload"
  [[ -n "$fx" ]] || preload="/etc/ld.so.preload"
  if [[ ! -f "$preload" ]]; then
    echo "ld_preload=ABSENT" >"$out_dir/ld_preload.txt"
  elif [[ ! -s "$preload" ]]; then
    echo "ld_preload=EMPTY" >"$out_dir/ld_preload.txt"
  else
    echo "ld_preload=UNEXPECTED" >"$out_dir/ld_preload.txt"
    status="FAIL"
    findings+=("SEC_CRIT_HOST_LD_PRELOAD_SUSPICIOUS")
  fi

  # Soviez-owned / local paths fingerprint (bounded)
  local paths=(
    /usr/local/bin
    /usr/local/sbin
  )
  [[ -n "${SOVIEZ_ROOT:-}" && -d "${SOVIEZ_ROOT}" ]] && paths+=("${SOVIEZ_ROOT}")
  : >"$out_dir/path_hashes.txt"
  local p
  for p in "${paths[@]}"; do
    [[ -d "$p" ]] || continue
    find "$p" -xdev -type f 2>/dev/null | head -200 | while read -r f; do
      openssl dgst -sha256 "$f" 2>/dev/null | awk -v f="$f" '{print $NF"  "f}'
    done >>"$out_dir/path_hashes.txt" || true
  done

  # UID0 (fixture passwd when provided)
  local passwd_f="/etc/passwd"
  [[ -n "$fx" && -f "${fx}/etc/passwd" ]] && passwd_f="${fx}/etc/passwd"
  if [[ -f "$passwd_f" ]]; then
    awk -F: '$3==0{print $1}' "$passwd_f" >"$out_dir/uid0.txt"
    local n
    n="$(wc -l <"$out_dir/uid0.txt" | tr -d ' ')"
    if [[ "${n:-0}" -gt 1 ]]; then
      findings+=("SEC_CRIT_HOST_UNEXPECTED_UID0")
      status="FAIL"
    fi
  fi

  # Optional SUID/SGID/capability drift vs fixture baseline list
  if [[ -n "${SOVIEZ_S3_SUID_BASELINE:-}" && -f "${SOVIEZ_S3_SUID_BASELINE}" ]]; then
    local cur_suid
    cur_suid="$(mktemp)"
    if [[ -n "$fx" ]]; then
      find "$fx" -xdev \( -perm -4000 -o -perm -2000 \) -type f 2>/dev/null | sort >"$cur_suid" || true
    else
      # Bounded sample only — do not walk entire host
      find /usr/local /opt/soviez "${SOVIEZ_ROOT:-/nonexistent}" -xdev \( -perm -4000 -o -perm -2000 \) -type f 2>/dev/null | sort >"$cur_suid" || true
    fi
    if ! cmp -s "${SOVIEZ_S3_SUID_BASELINE}" "$cur_suid"; then
      findings+=("SEC_HIGH_UNKNOWN_SUID_DRIFT")
      [[ "$status" == "PASS" ]] && status="PASS_WITH_REVIEW"
      # If new paths beyond package baseline → HIGH (still FAIL only if CRITICAL elsewhere)
      if [[ "${SOVIEZ_S3_SUID_STRICT:-0}" == "1" ]]; then
        status="FAIL"
      fi
      cp -f "$cur_suid" "$out_dir/suid_current.txt"
    fi
    rm -f "$cur_suid"
  fi

  printf '%s\n' "$status" >"$out_dir/STATUS"
  printf '%s\n' "${findings[@]-}" >"$out_dir/codes.txt"
  printf '%s\n' "$out_dir"
  [[ "$status" != "FAIL" ]]
}

soviez_s3_aide_decision() {
  # AIDE deferred: Docker overlay + Odoo filestore + PG data churn make naive FIM costly.
  # Native bounded fingerprints cover Soviez-owned paths for S3.
  printf '%s\n' "DEFERRED_NATIVE_FINGERPRINTS"
}

# --- end security/detection/host_integrity.sh ---

# --- begin security/detection/process_scan.sh ---
# shellcheck shell=bash
# Security Gate S3 — multi-signal process / miner detection (read-only; no kill).

soviez_s3_process_scan() {
  local out="${1:-}"
  [[ -n "$out" ]] || out="$(mktemp)"
  python3 - "$out" <<'PY'
import json,os,re,subprocess,time,sys
out=sys.argv[1]
# Sample process table twice for sustained CPU signal (bounded)
def snapshot():
  cmds=[
    ["ps","-eo","pid,ppid,user,pcpu,pmem,command","--sort=-pcpu"],
    ["ps","-axo","pid,ppid,user,%cpu,command"],
    ["ps","-axo","pid,ppid,user,pcpu,command"],
  ]
  raw=""
  for c in cmds:
    try:
      raw=subprocess.check_output(c, text=True, errors="replace", stderr=subprocess.DEVNULL)
      break
    except Exception:
      continue
  rows=[]
  for line in raw.splitlines()[1:40]:
    parts=line.split(None,5)
    if len(parts)<5: continue
    if len(parts)<6: parts=parts+[""]
    pid,ppid,user,pcpu=parts[0],parts[1],parts[2],parts[3]
    cmd=parts[-1]
    try: cpu=float(str(pcpu).replace("%",""))
    except Exception: cpu=0.0
    rows.append({"pid":pid,"ppid":ppid,"user":user,"pcpu":cpu,"cmd":cmd})
  return rows

s1=snapshot()
time.sleep(0.4)
s2=snapshot()
by_pid={r["pid"]:r for r in s2}
findings=[]
ioc_names={"xmrig","minerd","cpuminer","kworkerds"}
for r in s2:
  cmd=(r.get("cmd") or "").lower()
  path_tmp = "/tmp/" in cmd or "/dev/shm/" in cmd or "/var/tmp/" in cmd
  name_hit=any(n in cmd for n in ioc_names)
  stratum="stratum+tcp://" in cmd or "stratum+ssl://" in cmd
  # Multi-signal miner
  if name_hit and (stratum or path_tmp):
    findings.append({"severity":"CRITICAL","code":"SEC_CRIT_HOST_ACTIVE_MINER","pid":r["pid"],"cmd":r["cmd"][:200]})
  elif name_hit:
    findings.append({"severity":"HIGH","code":"SEC_CRIT_HOST_ACTIVE_MINER","pid":r["pid"],"cmd":r["cmd"][:200],"note":"name-only"})
  elif stratum:
    findings.append({"severity":"HIGH","code":"SEC_HIGH_KNOWN_BAD_ENDPOINT","pid":r["pid"],"cmd":r["cmd"][:200]})
  elif path_tmp and (
      re.search(r"\bcurl\b.*\bhttp", cmd)
      or re.search(r"\bwget\b.*\bhttp", cmd)
      or ("bash -c" in cmd and "http" in cmd)
      or ("python" in cmd and "http" in cmd)
  ):
    findings.append({"severity":"HIGH","code":"SEC_HIGH_DB_DOWNLOADER","pid":r["pid"],"cmd":r["cmd"][:200]})
  # CPU alone must NOT classify malware
  # (documented: high pcpu postgres/odoo ignored here)

status="PASS"
if any(f.get("severity")=="CRITICAL" for f in findings):
  status="FAIL"
elif findings:
  status="PASS_WITH_REVIEW"
json.dump({"status":status,"findings":findings,"policy":"cpu_alone_not_malware","destructive":False}, open(out,"w"), indent=2)
print(status)
PY
}

# --- end security/detection/process_scan.sh ---

# --- begin security/detection/network_ioc.sh ---
# shellcheck shell=bash
# Security Gate S3 — lightweight network IOC observation (ss/proc; no capture).

soviez_s3_network_ioc_scan() {
  local out="${1:-}"
  [[ -n "$out" ]] || out="$(mktemp)"
  local share iocs
  share="$(soviez_s3_detection_share)"
  iocs="${share}/iocs.json"
  python3 - "$iocs" "$out" <<'PY'
import json,subprocess,sys,re
iocs=json.load(open(sys.argv[1])).get("iocs") or []
bad_doms={i["value"].lower() for i in iocs if i.get("type") in ("domain","url","ipv4")}
# Also extract hosts from URLs
for i in list(bad_doms):
  m=re.search(r"https?://([^/:]+)", i)
  if m: bad_doms.add(m.group(1).lower())
conn=""
try:
  conn=subprocess.check_output(["ss","-tunap"], text=True, errors="replace")
except Exception:
  try:
    conn=subprocess.check_output(["netstat","-tunap"], text=True, errors="replace")
  except Exception:
    conn=""
findings=[]
low=conn.lower()
for b in bad_doms:
  if b and b in low:
    findings.append({"severity":"CRITICAL","code":"SEC_HIGH_KNOWN_BAD_ENDPOINT","indicator":b})
status="PASS" if not findings else "FAIL"
json.dump({"status":status,"findings":findings,"method":"ss_or_netstat","packet_capture":False}, open(sys.argv[2],"w"), indent=2)
print(status)
PY
}

# --- end security/detection/network_ioc.sh ---

# --- begin security/detection/persistence_scan.sh ---
# shellcheck shell=bash
# Security Gate S3 — persistence drift vs baseline inventory (read-only; fixture-aware).

soviez_s3_persistence_scan() {
  local baseline_dir="${1:-}"
  local out="${2:-}"
  [[ -n "$out" ]] || out="$(mktemp -d)"
  mkdir -p "$out/current"
  local fx="${SOVIEZ_S3_HOST_FIXTURE_ROOT:-}"
  local status="PASS"

  # ld.so.preload
  local preload="/etc/ld.so.preload"
  [[ -n "$fx" ]] && preload="${fx}/etc/ld.so.preload"
  if [[ ! -f "$preload" ]]; then
    echo ABSENT >"$out/current/ld_preload.txt"
  elif [[ ! -s "$preload" ]]; then
    echo EMPTY >"$out/current/ld_preload.txt"
  else
    echo UNEXPECTED >"$out/current/ld_preload.txt"
    status="FAIL"
    echo "SEC_CRIT_HOST_LD_PRELOAD_SUSPICIOUS" >>"$out/codes.txt"
  fi

  # Cron inventory (fixture or live read-only)
  if [[ -n "$fx" ]]; then
    find "${fx}/etc/cron.d" "${fx}/var/spool/cron" "${fx}/etc/crontab" -type f 2>/dev/null | sort >"$out/current/cron_paths.txt" || true
    [[ -f "${fx}/etc/crontab" ]] && cat "${fx}/etc/crontab" >"$out/current/crontab.txt" || echo none >"$out/current/crontab.txt"
  else
    crontab -l >"$out/current/crontab.txt" 2>/dev/null || echo none >"$out/current/crontab.txt"
    find /etc/cron.d /etc/cron.daily /var/spool/cron 2>/dev/null | sort >"$out/current/cron_paths.txt" || true
  fi

  # systemd unit inventory (fixture or bounded live)
  if [[ -n "$fx" ]]; then
    find "${fx}/etc/systemd/system" "${fx}/lib/systemd/system" -type f -name '*.service' 2>/dev/null | sort >"$out/current/systemd_units.txt" || true
  else
    find /etc/systemd/system /lib/systemd/system -maxdepth 2 -type f -name 'soviez*.service' 2>/dev/null | sort >"$out/current/systemd_units.txt" || true
  fi

  # rc.local / profile
  : >"$out/current/startup.txt"
  for f in /etc/rc.local /etc/profile /etc/profile.d/soviez.sh; do
    local rf="$f"
    [[ -n "$fx" ]] && rf="${fx}${f}"
    [[ -f "$rf" ]] && echo "PRESENT $f" >>"$out/current/startup.txt"
  done

  # Drift vs baseline lists
  if [[ -n "$baseline_dir" ]]; then
    if [[ -f "$baseline_dir/cron_paths.txt" && -f "$out/current/cron_paths.txt" ]]; then
      if ! cmp -s "$baseline_dir/cron_paths.txt" "$out/current/cron_paths.txt"; then
        echo "SEC_HIGH_CRON_PERSISTENCE_DRIFT" >>"$out/codes.txt"
        [[ "$status" == "PASS" ]] && status="PASS_WITH_REVIEW"
        # New unexpected cron with shell downloaders → elevate
        if grep -Eiq 'curl|wget|xmrig|/dev/tcp' "$out/current/crontab.txt" 2>/dev/null; then
          status="FAIL"
        fi
      fi
    fi
    if [[ -f "$baseline_dir/systemd_units.txt" && -f "$out/current/systemd_units.txt" ]]; then
      if ! cmp -s "$baseline_dir/systemd_units.txt" "$out/current/systemd_units.txt"; then
        echo "SEC_HIGH_SYSTEMD_PERSISTENCE_DRIFT" >>"$out/codes.txt"
        [[ "$status" == "PASS" ]] && status="PASS_WITH_REVIEW"
      fi
    fi
  fi

  printf '%s\n' "$status" >"$out/STATUS"
  printf '%s\n' "$out"
  [[ "$status" != "FAIL" ]]
}

# --- end security/detection/persistence_scan.sh ---

# --- begin security/detection/retention.sh ---
# shellcheck shell=bash
# Security Gate S3 — evidence retention (bounded; respects PRESERVE/INCIDENT/LEGAL_HOLD).

soviez_s3_retention_cleanup() {
  local root
  root="$(soviez_s3_evidence_root)"
  local max_age_days="${SOVIEZ_S3_RETENTION_DAYS:-30}"
  local max_runs="${SOVIEZ_S3_RETENTION_MAX_RUNS:-50}"
  [[ -d "$root" ]] || return 0
  # Delete oldest non-preserved runs beyond max_runs
  local runs=()
  local d
  while IFS= read -r d; do
    [[ -d "$d" ]] || continue
    if [[ -f "$d/PRESERVE" || -f "$d/INCIDENT" || -f "$d/LEGAL_HOLD" ]]; then
      continue
    fi
    runs+=("$d")
  done < <(find "$root" -mindepth 1 -maxdepth 1 -type d 2>/dev/null | sort)
  local n="${#runs[@]}"
  if [[ "$n" -gt "$max_runs" ]]; then
    local drop=$((n - max_runs))
    local i
    for ((i=0; i<drop; i++)); do
      rm -rf "${runs[$i]}"
    done
  fi
  # Age-based
  find "$root" -mindepth 1 -maxdepth 1 -type d -mtime "+${max_age_days}" 2>/dev/null | while read -r d; do
    [[ -f "$d/PRESERVE" || -f "$d/INCIDENT" || -f "$d/LEGAL_HOLD" ]] && continue
    rm -rf "$d"
  done
  return 0
}

# --- end security/detection/retention.sh ---

# --- begin security/detection/tooling_policy.sh ---
# shellcheck shell=bash
# Security Gate S3 — auditd / Lynis / optional tooling decisions (no heavy install by default).

soviez_s3_auditd_decision() {
  # Narrow watches only if auditd present; do not install huge syscall policy.
  if command -v auditctl >/dev/null 2>&1; then
    printf '%s\n' "AVAILABLE_NARROW_WATCHES_OPTIONAL"
  else
    printf '%s\n' "N/A_CONFIG_ONLY"
  fi
}

soviez_s3_lynis_decision() {
  printf '%s\n' "SUPPORTING_ONLY_ON_DEMAND"
}

soviez_s3_optional_tools_status() {
  cat <<'EOF'
{
  "clamav": "DEFERRED_ON_DEMAND_NOT_DEFAULT",
  "wazuh": "REJECTED_NO_SERVER_INFRA",
  "falco": "DEFERRED",
  "osquery": "DEFERRED",
  "crowdsec": "OPTIONAL_S2_OD",
  "aide": "DEFERRED_NATIVE_FINGERPRINTS",
  "yara": "TARGETED_OFFLINE_CURATED",
  "auditd": "NARROW_OPTIONAL",
  "lynis": "SUPPORTING_ONLY"
}
EOF
}

# --- end security/detection/tooling_policy.sh ---

# --- begin security/detection/s3_report.sh ---
# shellcheck shell=bash
# Security Gate S3 — human + machine compromise detection report.

soviez_s3_report_write() {
  local root="$1"
  local overall="${2:-PASS}"
  local db_st="${3:-N/A}"
  local host_st="${4:-N/A}"
  local yara_st="${5:-N/A}"
  local proc_st="${6:-N/A}"
  local net_st="${7:-N/A}"
  local persist_st="${8:-N/A}"
  local drift_st="${9:-N/A}"

  {
    echo "SOVIEZ SECURITY — COMPROMISE DETECTION"
    echo "Database persistence scan: ${db_st}"
    echo "Known IOC scan: included-in-DB"
    echo "Technical baseline drift: ${drift_st}"
    echo "Host integrity baseline: ${host_st}"
    echo "YARA targeted scan: ${yara_st}"
    echo "Process/miner indicators: ${proc_st}"
    echo "Known malicious outbound IOC: ${net_st}"
    echo "Cron/systemd / LD_PRELOAD persistence: ${persist_st}"
    echo "OVERALL: ${overall}"
    echo
    echo "Language: no known high-confidence technical persistence/IOC claimed clean beyond scan coverage."
    echo "Destructive remediation: NOT performed (S3 detect-only)."
    echo "Telemetry: none (local-only evidence)."
  } >"$root/report.txt"
  chmod 600 "$root/report.txt" 2>/dev/null || true

  cat >"$root/report.json" <<EOF
{
  "gate": "S3",
  "overall": "$(soviez_s3__json_escape "$overall")",
  "database_persistence": "$(soviez_s3__json_escape "$db_st")",
  "host_integrity": "$(soviez_s3__json_escape "$host_st")",
  "yara": "$(soviez_s3__json_escape "$yara_st")",
  "process": "$(soviez_s3__json_escape "$proc_st")",
  "network_ioc": "$(soviez_s3__json_escape "$net_st")",
  "persistence": "$(soviez_s3__json_escape "$persist_st")",
  "baseline_drift": "$(soviez_s3__json_escape "$drift_st")",
  "code": "SEC_OK_COMPROMISE_SCAN",
  "local_only": true,
  "destructive_remediation": false
}
EOF
  chmod 600 "$root/report.json" 2>/dev/null || true
}

# --- end security/detection/s3_report.sh ---

# --- begin security/detection/s3_gate.sh ---
# shellcheck shell=bash
# Security Gate S3 — fail-closed compromise detection gate (detect/report only).

soviez_security_validate_compromise_detection() {
  local evidence
  evidence="$(soviez_s3_evidence_init "${SOVIEZ_SEC_S3_RUN_ID:-}")"
  export SOVIEZ_SEC_S3_LAST_EVIDENCE="$evidence"

  local overall="PASS"
  local db_st="SKIP" host_st="SKIP" yara_st="N/A" proc_st="SKIP" net_st="SKIP" persist_st="SKIP" drift_st="N/A"

  # Ruleset integrity
  local share
  share="$(soviez_s3_detection_share)"
  if [[ ! -f "${share}/db_rules.json" || ! -f "${share}/iocs.json" ]]; then
    echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: ruleset missing/corrupt" >&2
    soviez_s3_report_write "$evidence" "FAIL" "FAIL" "N/A" "N/A" "N/A" "N/A" "N/A" "N/A"
    soviez_s3_evidence_finalize "$evidence" "FAIL" >/dev/null
    return 1
  fi

  # DB scan when PG available
  if [[ -n "${SOVIEZ_SEC_PG_CONTAINER:-}" ]]; then
    local db_out rc
    db_out="$(mktemp)"
    set +e
    soviez_s3_db_scan "$evidence" >"$db_out"
    rc=$?
    set -e
    if [[ $rc -eq 0 ]]; then
      db_st="$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1])).get("status","PASS"))' "$db_out" 2>/dev/null || echo PASS)"
    elif [[ $rc -eq 2 ]]; then
      db_st="FAIL"
      overall="FAIL"
    else
      db_st="FAIL"
      overall="FAIL"
      echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: DB scan failed" >&2
    fi
    # Baseline diff if index exists
    if [[ -f "$evidence/findings/records_index.json" ]]; then
      drift_st="$(soviez_s3_baseline_diff "$evidence/findings/records_index.json" "${SOVIEZ_S3_BASELINE_NAME:-environment}" 2>/dev/null | python3 -c 'import json,sys; print(json.load(sys.stdin).get("status","N/A"))' 2>/dev/null || echo N/A)"
      if [[ "$drift_st" == "PASS_WITH_REVIEW" && "$overall" == "PASS" ]]; then
        overall="PASS_WITH_REVIEW"
      fi
    fi
    rm -f "$db_out"
  elif [[ "${SOVIEZ_S3_REQUIRE_DB:-0}" == "1" ]]; then
    echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: DB required but not configured" >&2
    overall="FAIL"
    db_st="FAIL"
  else
    db_st="SKIP"
  fi

  # Host integrity
  local host_dir
  host_dir="$(mktemp -d)"
  if soviez_s3_host_integrity_scan "$host_dir" >/dev/null; then
    host_st="$(cat "$host_dir/STATUS")"
  else
    host_st="FAIL"
    overall="FAIL"
  fi
  mkdir -p "$evidence/tools/host_integrity"
  cp -a "$host_dir/." "$evidence/tools/host_integrity/" 2>/dev/null || true
  rm -rf "$host_dir"

  # Persistence
  local pdir
  pdir="$(mktemp -d)"
  if soviez_s3_persistence_scan "" "$pdir" >/dev/null; then
    persist_st="$(cat "$pdir/STATUS")"
  else
    persist_st="FAIL"
    overall="FAIL"
  fi
  mkdir -p "$evidence/tools/persistence"
  cp -a "$pdir/." "$evidence/tools/persistence/" 2>/dev/null || true
  rm -rf "$pdir"

  # Process
  local proc_json
  proc_json="$evidence/tools/process.json"
  mkdir -p "$evidence/tools"
  proc_st="$(soviez_s3_process_scan "$proc_json" 2>/dev/null || echo N/A)"
  if [[ "$proc_st" == "FAIL" ]]; then overall="FAIL"; fi
  if [[ "$proc_st" == "PASS_WITH_REVIEW" && "$overall" == "PASS" ]]; then overall="PASS_WITH_REVIEW"; fi

  # Network IOC
  local net_json="$evidence/tools/network_ioc.json"
  net_st="$(soviez_s3_network_ioc_scan "$net_json" 2>/dev/null || echo N/A)"
  if [[ "$net_st" == "FAIL" ]]; then overall="FAIL"; fi

  # YARA targeted (tmp paths + optional) — bounded; in test mode require explicit path
  local yara_json="$evidence/tools/yara.json"
  local ypaths=()
  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    if [[ -n "${SOVIEZ_S3_YARA_PATH:-}" ]]; then ypaths+=("${SOVIEZ_S3_YARA_PATH}"); fi
  else
    [[ -d /tmp ]] && ypaths+=(/tmp)
    [[ -d /var/tmp ]] && ypaths+=(/var/tmp)
    [[ -d /dev/shm ]] && ypaths+=(/dev/shm)
    if [[ -n "${SOVIEZ_S3_YARA_PATH:-}" ]]; then ypaths+=("${SOVIEZ_S3_YARA_PATH}"); fi
  fi
  if [[ ${#ypaths[@]} -gt 0 ]]; then
    yara_st="$(soviez_s3_yara_scan_paths "$yara_json" "${ypaths[@]}" 2>/dev/null || echo N/A)"
    if [[ "$yara_st" == "FAIL" ]]; then overall="FAIL"; fi
  else
    yara_st="N/A"
  fi

  # Addon scan optional
  if [[ -n "${SOVIEZ_S3_ADDON_DIR:-}" && -d "${SOVIEZ_S3_ADDON_DIR}" ]]; then
    local addon_json="$evidence/tools/addon.json"
    local ast
    ast="$(soviez_s3_addon_scan "${SOVIEZ_S3_ADDON_DIR}" "$addon_json" 2>/dev/null || echo N/A)"
    if [[ "$ast" == "FAIL" ]]; then overall="FAIL"; fi
  fi

  # Alert state (local only)
  case "$overall" in
    PASS) export SOVIEZ_SECURITY_STATUS=PASS ;;
    PASS_WITH_REVIEW) export SOVIEZ_SECURITY_STATUS=REVIEW ;;
    FAIL) export SOVIEZ_SECURITY_STATUS=FAIL ;;
  esac
  printf '%s\n' "${SOVIEZ_SECURITY_STATUS}" >"$evidence/SECURITY_STATUS"

  soviez_s3_report_write "$evidence" "$overall" "$db_st" "$host_st" "$yara_st" "$proc_st" "$net_st" "$persist_st" "$drift_st"
  soviez_s3_evidence_finalize "$evidence" "$overall" >/dev/null
  declare -F soviez_s3_retention_cleanup >/dev/null 2>&1 && soviez_s3_retention_cleanup || true

  if [[ "$overall" == "FAIL" ]]; then
    echo "[security] SECURITY FAIL — POSSIBLE ACTIVE COMPROMISE" >&2
    echo "[security] Recommended: preserve evidence; avoid ordinary Production mutation; use future Incident/S4 path" >&2
    echo "[security] SEC_OK_COMPROMISE_SCAN not granted" >&2
    return 1
  fi
  echo "[security] SEC_OK_COMPROMISE_SCAN (${overall})" >&2
  return 0
}

soviez_cmd_security_scan_db() {
  # S3 compromise / DB+host detection CLI (Phase 24 --security-scan remains secret/dist).
  export SOVIEZ_SEC_MODE="${SOVIEZ_SEC_MODE:-production}"
  export SOVIEZ_SEC_PG_CONTAINER="${SOVIEZ_SEC_PG_CONTAINER:-${SOVIEZ_DB_CONTAINER:-}}"
  export SOVIEZ_SEC_PG_ADMIN_USER="${SOVIEZ_SEC_PG_ADMIN_USER:-${SOVIEZ_PG_ADMIN_USER:-soviez_admin}}"
  export SOVIEZ_SEC_PG_ADMIN_PASS="${SOVIEZ_SEC_PG_ADMIN_PASS:-${SOVIEZ_PG_ADMIN_PASSWORD:-}}"
  export SOVIEZ_SEC_PG_DB="${SOVIEZ_SEC_PG_DB:-${SOVIEZ_DB_NAME:-postgres}}"
  soviez_security_validate_compromise_detection
}

# --- end security/detection/s3_gate.sh ---

# --- begin security/quarantine/state.sh ---
# shellcheck shell=bash
# Security Gate S4 — quarantine lifecycle state (local-only).

soviez_q_root() {
  local base="${SOVIEZ_SEC_QUARANTINE_ROOT:-}"
  if [[ -z "$base" ]]; then
    if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
      base="${TMPDIR:-/tmp}/soviez-s4-quarantine"
    else
      base="${SOVIEZ_ROOT:-/var/lib/soviez}/security/quarantine"
    fi
  fi
  mkdir -p "$base"
  chmod 700 "$base" 2>/dev/null || true
  printf '%s\n' "$base"
}

soviez_q_dir() {
  printf '%s/%s\n' "$(soviez_q_root)" "$1"
}

soviez_q_lock_path() {
  printf '%s/%s.lock\n' "$(soviez_q_root)" "$1"
}

soviez_q_acquire_lock() {
  local qid="$1" purpose="${2:-op}"
  local lp
  lp="$(soviez_q_lock_path "$qid")"
  if [[ -f "$lp" ]]; then
    echo "[error] security:SEC_CRIT_QUARANTINE_BYPASSED: concurrent operation lock held ($purpose)" >&2
    return 1
  fi
  printf '%s %s %s\n' "$$" "$purpose" "$(date -u +%Y-%m-%dT%H:%M:%SZ)" >"$lp"
  chmod 600 "$lp" 2>/dev/null || true
}

soviez_q_release_lock() {
  rm -f "$(soviez_q_lock_path "$1")"
}

soviez_q_new_id() {
  printf 'q-%s-%s-%s\n' "$(date -u +%Y%m%dT%H%M%SZ)" "$$" "${RANDOM}"
}

soviez_q_get_state() {
  local qid="$1"
  python3 -c 'import json,sys; print(json.load(open(sys.argv[1])).get("state",""))' \
    "$(soviez_q_dir "$qid")/meta.json" 2>/dev/null || echo UNKNOWN
}

soviez_q_set_state() {
  local qid="$1" state="$2"
  local meta
  meta="$(soviez_q_dir "$qid")/meta.json"
  [[ -f "$meta" ]] || return 1
  python3 - "$meta" "$state" <<'PY'
import json,sys,datetime
p,st=sys.argv[1],sys.argv[2]
m=json.load(open(p))
hist=m.setdefault("state_history",[])
hist.append({"from":m.get("state"),"to":st,"utc":datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")})
m["state"]=st
json.dump(m, open(p,"w"), indent=2)
print(st)
PY
}

soviez_q_create() {
  local qid="${1:-}"
  [[ -n "$qid" ]] || qid="$(soviez_q_new_id)"
  local d trust src_type ver rules
  d="$(soviez_q_dir "$qid")"
  if [[ -f "$d/meta.json" ]]; then
    printf '%s\n' "$qid"
    return 0
  fi
  trust="${SOVIEZ_Q_TRUST:-EXTERNAL_UNKNOWN}"
  src_type="${SOVIEZ_Q_SOURCE_TYPE:-external}"
  mkdir -p "$d"/{evidence,scans,network,secrets,locks,review,filestore,extract}
  chmod 700 "$d"
  ver="$(cat "${SOVIEZ_SH_ROOT:-.}/VERSION" 2>/dev/null || echo unknown)"
  rules="$(cat "${SOVIEZ_SH_ROOT:-.}/share/security/detection/schema_version" 2>/dev/null || echo unknown)"
  SOVIEZ_Q_ID="$qid" SOVIEZ_Q_TRUST_V="$trust" SOVIEZ_Q_SRC_T="$src_type" \
  SOVIEZ_Q_VER="$ver" SOVIEZ_Q_RULES="$rules" \
  SOVIEZ_Q_SRC_ID="${SOVIEZ_Q_SOURCE_ID:-}" SOVIEZ_Q_DEST_E="${SOVIEZ_Q_DEST_ENV:-destination}" \
  SOVIEZ_Q_DEST_D="${SOVIEZ_Q_DEST_DB:-}" SOVIEZ_Q_RSN="${SOVIEZ_Q_REASON:-}" \
  python3 <<'PY' >"$d/meta.json"
import json,os,datetime
trust=os.environ["SOVIEZ_Q_TRUST_V"]
obj={
  "quarantine_id": os.environ["SOVIEZ_Q_ID"],
  "immutable_original_id": os.environ["SOVIEZ_Q_ID"],
  "state": "UNTRUSTED_RESTORED",
  "source_type": os.environ["SOVIEZ_Q_SRC_T"],
  "source_identity": os.environ.get("SOVIEZ_Q_SRC_ID",""),
  "source_trust": trust,
  "destination_environment": os.environ.get("SOVIEZ_Q_DEST_E","destination"),
  "destination_db": os.environ.get("SOVIEZ_Q_DEST_D",""),
  "restore_utc": datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
  "quarantine_start_utc": datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
  "scanner_version": os.environ.get("SOVIEZ_Q_VER",""),
  "ruleset_version": os.environ.get("SOVIEZ_Q_RULES",""),
  "evidence_run_id": "",
  "approval_status": "PENDING",
  "approver": "",
  "reason": os.environ.get("SOVIEZ_Q_RSN",""),
  "promotion_utc": "",
  "local_only": True,
  "telemetry": False,
  "destructive_remediation": False,
  "incident_preserve": trust in ("INCIDENT_SUSPECTED","COMPROMISED_CONFIRMED"),
  "state_history": [{"from":None,"to":"UNTRUSTED_RESTORED","utc":datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")}],
}
print(json.dumps(obj, indent=2))
PY
  chmod 600 "$d/meta.json"
  case "$trust" in
    INCIDENT_SUSPECTED|COMPROMISED_CONFIRMED)
      touch "$d/PRESERVE" "$d/INCIDENT"
      ;;
  esac
  printf '%s\n' "$qid"
}
# --- end security/quarantine/state.sh ---

# --- begin security/quarantine/classify_source.sh ---
# shellcheck shell=bash
# Security Gate S4 — source trust classification.

soviez_q_classify_source() {
  local signed="${SOVIEZ_Q_BACKUP_SIGNED:-0}"
  local local_soviez="${SOVIEZ_Q_LOCAL_SOVIEZ:-0}"
  local incident="${SOVIEZ_Q_INCIDENT:-0}"
  local compromised="${SOVIEZ_Q_COMPROMISED:-0}"
  local legacy="${SOVIEZ_Q_LEGACY_ODOO:-0}"
  local sec_status="${SOVIEZ_Q_PRIOR_SECURITY_STATUS:-}"

  if [[ "$compromised" == "1" || "$sec_status" == "FAIL" ]]; then
    printf '%s\n' "COMPROMISED_CONFIRMED"; return 0
  fi
  if [[ "$incident" == "1" ]]; then
    printf '%s\n' "INCIDENT_SUSPECTED"; return 0
  fi
  if [[ "$local_soviez" == "1" && "$signed" == "1" ]]; then
    printf '%s\n' "TRUSTED_SIGNED_BACKUP"; return 0
  fi
  if [[ "$local_soviez" == "1" ]]; then
    printf '%s\n' "TRUSTED_LOCAL_SOVIEZ"; return 0
  fi
  if [[ "$legacy" == "1" ]]; then
    printf '%s\n' "LEGACY_ODOO"; return 0
  fi
  printf '%s\n' "EXTERNAL_UNKNOWN"
}

soviez_q_requires_full_quarantine() {
  local trust="${1:-EXTERNAL_UNKNOWN}"
  case "$trust" in
    TRUSTED_LOCAL_SOVIEZ|TRUSTED_SIGNED_BACKUP)
      [[ "${SOVIEZ_Q_FORCE_QUARANTINE:-0}" == "1" ]] && return 0
      return 1
      ;;
    *) return 0 ;;
  esac
}

# --- end security/quarantine/classify_source.sh ---

# --- begin security/quarantine/secrets.sh ---
# shellcheck shell=bash
# Security Gate S4 — fresh destination infrastructure secrets.

soviez_q_generate_fresh_secrets() {
  local qid="$1"
  local d sf
  d="$(soviez_q_dir "$qid")"
  sf="$d/secrets/infra.env"
  mkdir -p "$d/secrets"
  chmod 700 "$d/secrets"
  if [[ -f "$sf" && "${SOVIEZ_Q_ROTATE_SECRETS:-0}" != "1" ]]; then
    printf '%s\n' "$sf"
    return 0
  fi
  python3 - "$sf" <<'PY'
import secrets,string,os,sys
a=string.ascii_letters+string.digits
def gen(n=32): return "".join(secrets.choice(a) for _ in range(n))
path=sys.argv[1]
open(path,"w").write("\n".join([
  f"SOVIEZ_Q_PG_ADMIN_PASSWORD={gen()}",
  f"SOVIEZ_Q_PG_APP_PASSWORD={gen()}",
  f"SOVIEZ_Q_ODOO_ADMIN_PASSWD={gen()}",
  f"SOVIEZ_Q_RUNTIME_SECRET={gen(40)}",
  f"SOVIEZ_Q_MIGRATION_TEMP_SECRET={gen()}",
  f"SOVIEZ_Q_REGISTRY_TEMP_SECRET={gen()}",
  f"SOVIEZ_Q_TRANSFER_TEMP_SECRET={gen()}",
])+"\n")
os.chmod(path, 0o600)
print(path)
PY
}

soviez_q_assert_secrets_fresh_vs_source() {
  local qid="$1" source_secrets_file="${2:-}"
  local sf
  sf="$(soviez_q_dir "$qid")/secrets/infra.env"
  [[ -f "$sf" ]] || return 1
  [[ -n "$source_secrets_file" && -f "$source_secrets_file" ]] || return 0
  python3 - "$sf" "$source_secrets_file" <<'PY'
import sys
dst=dict(l.strip().split("=",1) for l in open(sys.argv[1]) if "=" in l and not l.startswith("#"))
src=dict(l.strip().split("=",1) for l in open(sys.argv[2]) if "=" in l and not l.startswith("#"))
src_vals=set(src.values())
for k,v in dst.items():
  if v and v in src_vals:
    raise SystemExit(f"reused secret: {k}")
print("FRESH")
PY
}

# --- end security/quarantine/secrets.sh ---

# --- begin security/quarantine/archive_validate.sh ---
# shellcheck shell=bash
# Security Gate S4 — archive extraction safety (fail-closed).

soviez_q_archive_validate() {
  local archive="$1" dest="$2"
  [[ -f "$archive" ]] || { echo "[error] security:SEC_CRIT_RESTORE_ARCHIVE_TRAVERSAL: archive missing" >&2; return 1; }
  mkdir -p "$dest"
  python3 - "$archive" "$dest" <<'PY'
import os,sys,tarfile,zipfile,stat
archive,dest=sys.argv[1],sys.argv[2]
dest=os.path.realpath(dest)

def bad(code, msg):
  print(f"[error] security:{code}: {msg}", file=sys.stderr)
  raise SystemExit(1)

def check_member(name, is_symlink=False, linkname="", is_hardlink=False, is_dev=False):
  if name.startswith("/") or name.startswith("\\"):
    bad("SEC_CRIT_RESTORE_ARCHIVE_TRAVERSAL", "absolute path")
  parts=name.replace("\\","/").split("/")
  if ".." in parts:
    bad("SEC_CRIT_RESTORE_ARCHIVE_TRAVERSAL", "path traversal")
  target=os.path.realpath(os.path.join(dest, name))
  if not (target==dest or target.startswith(dest+os.sep)):
    bad("SEC_CRIT_RESTORE_ARCHIVE_TRAVERSAL", "escapes destination")
  if is_symlink or is_hardlink:
    ln=linkname or ""
    if ln.startswith("/") or ".." in ln.replace("\\","/").split("/"):
      bad("SEC_CRIT_RESTORE_SYMLINK_ESCAPE", "link escape")
    base=os.path.dirname(os.path.join(dest, name))
    resolved=os.path.realpath(os.path.join(base, ln)) if ln else dest
    if not (resolved==dest or resolved.startswith(dest+os.sep)):
      bad("SEC_CRIT_RESTORE_SYMLINK_ESCAPE", "link outside dest")
  if is_dev:
    bad("SEC_CRIT_RESTORE_ARCHIVE_TRAVERSAL", "device node")

if tarfile.is_tarfile(archive):
  with tarfile.open(archive, "r:*") as tf:
    for m in tf.getmembers():
      is_dev = m.isdev() if hasattr(m,"isdev") else False
      if not is_dev:
        try:
          is_dev = stat.S_ISCHR(m.mode) or stat.S_ISBLK(m.mode) or stat.S_ISFIFO(m.mode)
        except Exception:
          is_dev=False
      check_member(m.name, m.issym(), m.linkname if (m.issym() or m.islnk()) else "", m.islnk(), is_dev)
  print("PASS_TAR")
elif zipfile.is_zipfile(archive):
  with zipfile.ZipFile(archive) as zf:
    for info in zf.infolist():
      check_member(info.filename)
  print("PASS_ZIP")
else:
  print("PASS_OPAQUE")
PY
}

soviez_q_archive_extract_safe() {
  local archive="$1" dest="$2"
  soviez_q_archive_validate "$archive" "$dest" || return 1
  local need avail
  need="$(du -k "$archive" 2>/dev/null | awk '{print $1*3}')"
  avail="$(df -k "$dest" 2>/dev/null | awk 'NR==2{print $4}')"
  if [[ -n "$need" && -n "$avail" && "$avail" -lt "$need" ]]; then
    echo "[error] security:SEC_CRIT_RESTORE_ARCHIVE_TRAVERSAL: insufficient disk" >&2
    return 1
  fi
  python3 - "$archive" "$dest" <<'PY'
import os,sys,tarfile,zipfile
archive,dest=sys.argv[1],sys.argv[2]
os.makedirs(dest, exist_ok=True)
if tarfile.is_tarfile(archive):
  with tarfile.open(archive,"r:*") as tf:
    try:
      tf.extractall(dest, filter="data")
    except TypeError:
      tf.extractall(dest)
elif zipfile.is_zipfile(archive):
  with zipfile.ZipFile(archive) as zf:
    zf.extractall(dest)
print(dest)
PY
}

# --- end security/quarantine/archive_validate.sh ---

# --- begin security/quarantine/network.sh ---
# shellcheck shell=bash
# Security Gate S4 — quarantine network (deny external egress).

soviez_q_network_create() {
  local qid="$1"
  local d name
  d="$(soviez_q_dir "$qid")"
  mkdir -p "$d/network"
  name="soviez-q-${qid:2:12}-${RANDOM}"
  name="${name//[^a-zA-Z0-9_-]/}"
  if docker network inspect "$name" >/dev/null 2>&1; then
    printf '%s\n' "$name" >"$d/network/name"
    printf '%s\n' "$name"
    return 0
  fi
  if ! docker network create --internal --label "soviez.quarantine=$qid" "$name" >/dev/null 2>&1; then
    echo "[error] security:SEC_CRIT_QUARANTINE_EGRESS_OPEN: cannot create internal network" >&2
    return 1
  fi
  printf '%s\n' "$name" >"$d/network/name"
  printf 'internal=1\negress=DENIED\n' >"$d/network/policy.txt"
  # Record docker Internal flag proof
  docker network inspect "$name" --format '{{.Internal}}' >"$d/network/docker_internal.txt" 2>/dev/null || true
  printf '%s\n' "$name"
}

soviez_q_network_name() {
  cat "$(soviez_q_dir "$1")/network/name" 2>/dev/null || true
}

soviez_q_network_prove_egress_blocked() {
  local qid="$1" probe_cid="$2"
  local d name
  d="$(soviez_q_dir "$qid")"
  name="$(soviez_q_network_name "$qid")"
  # Primary: Docker --internal flag must be true (fail-closed if unknown)
  local internal
  internal="$(docker network inspect "$name" --format '{{.Internal}}' 2>/dev/null || echo "")"
  if [[ "$internal" != "true" ]]; then
    echo "[error] security:SEC_CRIT_QUARANTINE_EGRESS_OPEN: network not Internal (got=${internal:-UNKNOWN})" >&2
    return 1
  fi
  # Secondary: best-effort external probe (may be flaky on some hosts; Internal flag is authoritative)
  if docker exec "$probe_cid" wget -q -O- --timeout=2 http://1.1.1.1 >/dev/null 2>&1; then
    echo "[error] security:SEC_CRIT_QUARANTINE_EGRESS_OPEN: external HTTP succeeded despite Internal" >&2
    return 1
  fi
  echo BLOCKED >"$d/network/egress_proof.txt"
  return 0
}

soviez_q_network_cleanup() {
  local name
  name="$(soviez_q_network_name "$1")"
  [[ -n "$name" ]] || return 0
  docker network rm "$name" >/dev/null 2>&1 || true
}

# --- end security/quarantine/network.sh ---

# --- begin security/quarantine/cron.sh ---
# shellcheck shell=bash
# Security Gate S4 — cron neutralization (runtime; reversible).

soviez_q_odoo_quarantine_conf_snippet() {
  cat <<'EOF'
# Soviez S4 quarantine — runtime containment (reversible on promotion)
max_cron_threads = 0
workers = 0
list_db = False
proxy_mode = True
EOF
}

soviez_q_cron_marker_seed_sql() {
  cat <<'SQL'
CREATE TABLE IF NOT EXISTS soviez_q_cron_marker (id serial PRIMARY KEY, fired_at timestamptz);
CREATE TABLE IF NOT EXISTS ir_cron (
  id serial PRIMARY KEY,
  cron_name text,
  code text,
  active boolean DEFAULT true,
  interval_number int DEFAULT 1,
  interval_type text DEFAULT 'minutes',
  numbercall int DEFAULT -1,
  doall boolean DEFAULT false,
  nextcall timestamp without time zone DEFAULT now()
);
INSERT INTO ir_cron(cron_name, code, active)
SELECT 'soviez_q_probe', 'INSERT INTO soviez_q_cron_marker(fired_at) VALUES (now())', true
WHERE NOT EXISTS (SELECT 1 FROM ir_cron WHERE cron_name='soviez_q_probe');
SQL
}

soviez_q_assert_cron_not_fired() {
  local ctn="$1" user="$2" pass="$3" db="$4"
  local n
  n="$(docker exec -e PGPASSWORD="$pass" "$ctn" psql -U "$user" -d "$db" -At -c \
    "SELECT count(*) FROM soviez_q_cron_marker;" 2>/dev/null || echo 0)"
  if [[ "${n:-0}" != "0" ]]; then
    echo "[error] security:SEC_CRIT_CRON_ACTIVE_IN_QUARANTINE: marker count=$n" >&2
    return 1
  fi
  return 0
}

