# --- begin registry/manifest_verify.sh ---
# shellcheck shell=bash

soviez_manifest_verify() {
  local manifest_json="$1"
  local expected_digest="$2"
  local digest
  digest="$(soviez_json_get "$manifest_json" "digest")"
  if [[ "$digest" != "$expected_digest" ]]; then
    soviez_die "$SOVIEZ_ERR_API" "Manifest digest mismatch"
  fi
  local sig
  sig="$(soviez_json_get "$manifest_json" "signature" 2>/dev/null || true)"
  if [[ -z "$sig" && "${SOVIEZ_TEST_MODE:-0}" != "1" ]]; then
    soviez_die "$SOVIEZ_ERR_API" "Manifest missing signature"
  fi
  soviez_log_info "Manifest verified digest=$digest"
}

# --- end registry/manifest_verify.sh ---

# --- begin registry/pull_client.sh ---
# shellcheck shell=bash

# Extract host[:port] from a registry gateway URL for docker login.
soviez_registry_gateway_host() {
  local url="${1:-${SOVIEZ_REGISTRY_GATEWAY_URL:-https://registry.soviez.com}}"
  url="${url#https://}"
  url="${url#http://}"
  url="${url%%/*}"
  printf '%s' "$url"
}

# Assert temporary docker config dir is gone (credential cleanup).
soviez_security_registry_assert_temp_config_clean() {
  local cfg_dir="${1:-}"
  if [[ -n "$cfg_dir" && -e "$cfg_dir" ]]; then
    soviez_die "${SOVIEZ_ERR_API:-20}" "Temporary docker config still present: $cfg_dir"
  fi
  return 0
}

# Pull private image via Registry Gateway using short-lived credentials.
# Args: image_ref registry_user registry_pass expected_digest [gateway_url]
soviez_pull_client_run() {
  local image_ref="$1"
  local registry_user="$2"
  local registry_pass="$3"
  local expected_digest="$4"
  local gateway_url="${5:-${SOVIEZ_REGISTRY_GATEWAY_URL:-https://registry.soviez.com}}"

  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    soviez_docker_stub_pull "$image_ref" "$expected_digest"
    return 0
  fi

  local cfg_dir host
  cfg_dir="$(mktemp -d "${TMPDIR:-/tmp}/soviez-docker-config.XXXXXX")"
  chmod 700 "$cfg_dir"
  host="$(soviez_registry_gateway_host "$gateway_url")"

  # Temporary docker auth only — never use ~/.docker/config.json
  if ! printf '%s' "$registry_pass" | DOCKER_CONFIG="$cfg_dir" docker login \
      --username "$registry_user" --password-stdin "$host" >/dev/null 2>&1; then
    rm -rf "$cfg_dir"
    unset registry_pass
    soviez_die "${SOVIEZ_ERR_API:-20}" "Registry gateway login failed"
  fi

  if ! DOCKER_CONFIG="$cfg_dir" docker pull "$image_ref"; then
    DOCKER_CONFIG="$cfg_dir" docker logout "$host" >/dev/null 2>&1 || true
    rm -rf "$cfg_dir"
    unset registry_pass
    soviez_die "${SOVIEZ_ERR_API:-20}" "Registry gateway pull failed"
  fi

  local pulled=""
  pulled="$(DOCKER_CONFIG="$cfg_dir" docker inspect --format='{{index .RepoDigests 0}}' "$image_ref" 2>/dev/null | awk -F@ '{print $2}')"
  if [[ -z "$pulled" ]]; then
    # Fallback: image_ref may already be name@digest
    if [[ "$image_ref" == *@sha256:* ]]; then
      pulled="${image_ref##*@}"
    fi
  fi

  DOCKER_CONFIG="$cfg_dir" docker logout "$host" >/dev/null 2>&1 || true
  rm -rf "$cfg_dir"
  unset registry_pass registry_user
  cfg_dir=""

  soviez_security_registry_assert_temp_config_clean "$cfg_dir"

  if [[ -n "$expected_digest" && "$pulled" != "$expected_digest" ]]; then
    soviez_die "${SOVIEZ_ERR_API:-20}" "Pulled digest mismatch (expected=$expected_digest got=$pulled)"
  fi
}

# --- end registry/pull_client.sh ---

# --- begin tenant/identity.sh ---
# shellcheck shell=bash

soviez_tenant_identity_create() {
  local op_id="$1"
  local tenant_id="${2:-tenant-${op_id}}"
  local identity_file="$SOVIEZ_TENANT_DIR/identity.json"
  mkdir -p "$SOVIEZ_TENANT_DIR"
  chmod 700 "$SOVIEZ_TENANT_DIR"
  printf '{"tenant_id":"%s","operation_id":"%s"}\n' "$tenant_id" "$op_id" > "$identity_file"
  chmod 600 "$identity_file"
  printf '%s' "$tenant_id"
}

soviez_tenant_identity_load() {
  local identity_file="$SOVIEZ_TENANT_DIR/identity.json"
  [[ -f "$identity_file" ]] || return 1
  soviez_json_get "$(cat "$identity_file")" "tenant_id"
}

# --- end tenant/identity.sh ---

# --- begin tenant/secrets.sh ---
# shellcheck shell=bash

soviez_tenant_secret_path() {
  local name="$1"
  printf '%s/%s\n' "$SOVIEZ_SECRETS_DIR" "$name"
}

soviez_tenant_secret_write() {
  local name="$1"
  local value="$2"
  local path
  path="$(soviez_tenant_secret_path "$name")"
  mkdir -p "$SOVIEZ_SECRETS_DIR"
  chmod 700 "$SOVIEZ_SECRETS_DIR"
  umask 077
  printf '%s' "$value" > "$path"
  chmod 600 "$path"
  # Phase 24: fingerprint sidecar for hygiene/audit (never log plaintext).
  if declare -F soviez_security_secret_fingerprint >/dev/null 2>&1; then
    printf '%s\n' "$(soviez_security_secret_fingerprint "$value")" > "${path}.sha256"
    chmod 600 "${path}.sha256"
  fi
  if declare -F soviez_security_assert_private_key_perms >/dev/null 2>&1; then
    case "$name" in
      *private*|*_key|*signing*) soviez_security_assert_private_key_perms "$path" || true ;;
    esac
  fi
}

soviez_tenant_secret_read() {
  local name="$1"
  local path
  path="$(soviez_tenant_secret_path "$name")"
  [[ -f "$path" ]] || return 1
  cat "$path"
}

# --- end tenant/secrets.sh ---

# --- begin docker/labels.sh ---
# shellcheck shell=bash

soviez_docker_labels_for_operation() {
  local op_id="$1"
  printf 'soviez.operation_id=%s\nsoviez.managed=true\n' "$op_id"
}

# --- end docker/labels.sh ---

# --- begin docker/provision.sh ---
# shellcheck shell=bash

soviez_docker_stub_pull() {
  local image_ref="$1"
  local digest="$2"
  local marker="$SOVIEZ_ROOT/stubs/docker-pull-$(soviez_sha256_hex "$image_ref" | cut -c1-12).done"
  mkdir -p "$SOVIEZ_ROOT/stubs"
  printf 'image=%s\ndigest=%s\n' "$image_ref" "$digest" > "$marker"
}

soviez_docker_provision_start() {
  local op_id="$1"
  local image_ref="$2"
  local container_name="soviez-web-${op_id}"
  local net="${SOVIEZ_DB_NETWORK:-soviez-net-${op_id}}"
  local host_port="${SOVIEZ_HOST_PORT:-}"

  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    local marker="$SOVIEZ_ROOT/stubs/container-${op_id}.started"
    mkdir -p "$SOVIEZ_ROOT/stubs"
    printf 'container=%s\nimage=%s\n' "$container_name" "$image_ref" > "$marker"
    printf '%s' "$container_name"
    return 0
  fi

  if ! command -v docker >/dev/null 2>&1 || ! docker info >/dev/null 2>&1; then
    echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: docker required for container provision" >&2
    return 1
  fi

  docker network create "$net" >/dev/null 2>&1 || true

  local -a publish_args=()
  if [[ -n "$host_port" ]]; then
    local spec
    if declare -F soviez_sec_odoo_loopback_publish_spec >/dev/null 2>&1; then
      spec="$(soviez_sec_odoo_loopback_publish_spec "$host_port")"
    else
      spec="127.0.0.1:${host_port}:8069"
    fi
    publish_args=(-p "$spec")
    # Multi-worker gevent/evented port (loopback only). Host port = http+3 or SOVIEZ_GEVENT_HOST_PORT.
    local gevent_host="${SOVIEZ_GEVENT_HOST_PORT:-}"
    if [[ -z "$gevent_host" && "$host_port" =~ ^[0-9]+$ ]]; then
      gevent_host=$((host_port + 3))
    fi
    if [[ -n "$gevent_host" && "${SOVIEZ_PUBLISH_GEVENT:-1}" == "1" ]]; then
      local gspec
      if declare -F soviez_sec_odoo_loopback_publish_spec >/dev/null 2>&1; then
        gspec="$(soviez_sec_odoo_loopback_publish_spec "$gevent_host" 8072)"
      else
        gspec="127.0.0.1:${gevent_host}:8072"
      fi
      publish_args+=(-p "$gspec")
    fi
  fi

  if docker ps -a --format '{{.Names}}' | grep -qx "$container_name"; then
    docker start "$container_name" >/dev/null
  else
    # Never privileged, never docker.sock, never host network.
    docker run -d --name "$container_name" --network "$net" \
      "${publish_args[@]}" \
      "$image_ref" sleep infinity >/dev/null
  fi

  if [[ "${SOVIEZ_SEC_PRODUCTION_MARKERS:-0}" == "1" ]] || [[ -f "${SOVIEZ_ROOT:-}/security/production.marker" ]]; then
    export SOVIEZ_SEC_MODE="${SOVIEZ_SEC_MODE:-production}"
    export SOVIEZ_SEC_ODOO_CONTAINER="$container_name"
    export SOVIEZ_SEC_PG_CONTAINER="${SOVIEZ_DB_CONTAINER:-soviez-db-${op_id}}"
    if declare -F soviez_security_validate_critical_containment >/dev/null 2>&1; then
      if docker inspect "$container_name" >/dev/null 2>&1 \
        && docker inspect "${SOVIEZ_SEC_PG_CONTAINER}" >/dev/null 2>&1; then
        SOVIEZ_SEC_PG_ADMIN_PASS="$(soviez_tenant_secret_read pg_admin_password 2>/dev/null || true)"
        SOVIEZ_SEC_PG_APP_PASS="$(soviez_tenant_secret_read db_password 2>/dev/null || true)"
        export SOVIEZ_SEC_PG_ADMIN_PASS SOVIEZ_SEC_PG_APP_PASS
        soviez_security_validate_critical_containment || return 1
      fi
    fi
  fi

  printf '%s' "$container_name"
}

# --- end docker/provision.sh ---

# --- begin database/provision.sh ---
# shellcheck shell=bash

soviez_database_provision() {
  local op_id="$1"
  local db_name="soviez_${op_id//-/_}"

  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    local marker="$SOVIEZ_ROOT/stubs/db-${op_id}.ready"
    mkdir -p "$SOVIEZ_ROOT/stubs"
    printf 'db=%s\n' "$db_name" > "$marker"
    soviez_tenant_secret_write "db_name" "$db_name"
    # Deterministic non-weak test secrets (still subject to policy when gated).
    local app_pass admin_pass
    app_pass="$(soviez_sec_pg_gen_password 24 2>/dev/null || python3 -c 'import secrets,string; a=string.ascii_letters+string.digits; print("".join(secrets.choice(a) for _ in range(24)))')"
    admin_pass="$(soviez_sec_pg_gen_password 24 2>/dev/null || python3 -c 'import secrets,string; a=string.ascii_letters+string.digits; print("".join(secrets.choice(a) for _ in range(24)))')"
    if declare -F soviez_sec_password_assert_not_weak >/dev/null 2>&1; then
      soviez_sec_password_assert_not_weak "$app_pass" "db_password" || return 1
      soviez_sec_password_assert_not_weak "$admin_pass" "pg_admin_password" || return 1
    fi
    soviez_tenant_secret_write "db_password" "$app_pass"
    soviez_tenant_secret_write "pg_admin_password" "$admin_pass"
    printf '%s' "$db_name"
    return 0
  fi

  if ! command -v docker >/dev/null 2>&1 || ! docker info >/dev/null 2>&1; then
    echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: docker required for database provision" >&2
    return 1
  fi

  local net="${SOVIEZ_DB_NETWORK:-soviez-net-${op_id}}"
  local pg_name="${SOVIEZ_DB_CONTAINER:-soviez-db-${op_id}}"
  local admin_user="${SOVIEZ_PG_ADMIN_USER:-soviez_admin}"
  local app_user="${SOVIEZ_PG_APP_USER:-soviez_app}"
  local admin_pass app_pass

  if admin_pass="$(soviez_tenant_secret_read pg_admin_password 2>/dev/null)"; then
    :
  else
    admin_pass="$(soviez_sec_pg_gen_password 32)"
    soviez_tenant_secret_write "pg_admin_password" "$admin_pass"
  fi
  if app_pass="$(soviez_tenant_secret_read db_password 2>/dev/null)"; then
    :
  else
    app_pass="$(soviez_sec_pg_gen_password 32)"
    soviez_tenant_secret_write "db_password" "$app_pass"
  fi
  soviez_tenant_secret_write "db_name" "$db_name"

  if declare -F soviez_sec_password_assert_not_weak >/dev/null 2>&1; then
    soviez_sec_password_assert_not_weak "$app_pass" "db_password" || return 1
    soviez_sec_password_assert_not_weak "$admin_pass" "pg_admin_password" || return 1
  fi

  docker network create "$net" >/dev/null 2>&1 || true

  if ! docker inspect "$pg_name" >/dev/null 2>&1; then
    docker run -d --name "$pg_name" --network "$net" --restart unless-stopped \
      -e POSTGRES_USER="$admin_user" \
      -e POSTGRES_PASSWORD="$admin_pass" \
      -e POSTGRES_DB=postgres \
      "${SOVIEZ_DB_IMAGE:-postgres:16}" >/dev/null || return 1
  else
    docker start "$pg_name" >/dev/null 2>&1 || true
    docker network connect "$net" "$pg_name" >/dev/null 2>&1 || true
  fi

  local i
  for i in $(seq 1 60); do
    docker exec "$pg_name" pg_isready -U "$admin_user" -d postgres >/dev/null 2>&1 && break
    sleep 1
  done
  docker exec "$pg_name" pg_isready -U "$admin_user" -d postgres >/dev/null 2>&1 || return 1

  if declare -F soviez_sec_pg_provision_least_privilege >/dev/null 2>&1; then
    soviez_sec_pg_provision_least_privilege "$pg_name" "$admin_user" "$admin_pass" \
      "$app_user" "$app_pass" "$db_name" || return 1
  else
    echo "[error] security:SEC_CRIT_SECURITY_STATE_UNKNOWN: platform pg provision missing" >&2
    return 1
  fi

  # Dry-form / markers for gate evidence (no secrets).
  mkdir -p "${SOVIEZ_ROOT:-/tmp}/security"
  printf 'pg=%s\ndb=%s\napp_user=%s\nmode=provisioned\n' "$pg_name" "$db_name" "$app_user" \
    > "${SOVIEZ_ROOT:-/tmp}/security/db-provision-${op_id}.marker"
  chmod 600 "${SOVIEZ_ROOT:-/tmp}/security/db-provision-${op_id}.marker" 2>/dev/null || true

  if [[ "${SOVIEZ_SEC_RUN_GATE_ON_PROVISION:-0}" == "1" ]]; then
    export SOVIEZ_SEC_MODE="${SOVIEZ_SEC_MODE:-production}"
    export SOVIEZ_SEC_PG_CONTAINER="$pg_name"
    export SOVIEZ_SEC_PG_ADMIN_USER="$admin_user"
    export SOVIEZ_SEC_PG_ADMIN_PASS="$admin_pass"
    export SOVIEZ_SEC_PG_APP_USER="$app_user"
    export SOVIEZ_SEC_PG_APP_PASS="$app_pass"
    if declare -F soviez_security_validate_critical_containment >/dev/null 2>&1; then
      # Odoo may not exist yet — gate may UNKNOWN some checks; record dry run only when odoo present
      if [[ -n "${SOVIEZ_SEC_ODOO_CONTAINER:-}" ]] && docker inspect "${SOVIEZ_SEC_ODOO_CONTAINER}" >/dev/null 2>&1; then
        soviez_security_validate_critical_containment || return 1
      fi
    fi
  fi

  soviez_log_info "Provisioning database $db_name"
  printf '%s' "$db_name"
}

# --- end database/provision.sh ---

# --- begin nginx/render.sh ---
# shellcheck shell=bash

soviez_nginx_render_config() {
  local domain="$1"
  local upstream="$2"
  local out="${3:-$SOVIEZ_ROOT/nginx-${domain}.conf}"

  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    mkdir -p "$SOVIEZ_ROOT/stubs"
    out="$SOVIEZ_ROOT/stubs/nginx-${domain}.conf"
  fi

  cat > "$out" <<EOF
server {
    listen 443 ssl;
    server_name ${domain};
    location / {
        proxy_pass http://${upstream};
    }
}
EOF
  soviez_log_debug "Wrote nginx config: $out"
}

# --- end nginx/render.sh ---

# --- begin nginx/ownership.sh ---
# shellcheck shell=bash
# Phase 12 Nginx ownership model — never overwrite unmanaged configs.

soviez_nginx_owned_path() {
  local env_id="$1"
  local domain="$2"
  printf '%s/%s__%s.conf\n' "$SOVIEZ_SSL_NGINX_OWNED_DIR" "$env_id" "$domain"
}

soviez_nginx_owned_meta_path() {
  local conf="$1"
  printf '%s.meta.json\n' "$conf"
}

soviez_nginx_render_owned() {
  local env_id="$1"
  local domain="$2"
  local upstream="$3"
  local cert="$4"
  local key="$5"
  local op_id="${6:-}"
  local mode="${7:-https}" # http_temp|https
  local out meta checksum now
  soviez_ssl_paths_init
  out="$(soviez_nginx_owned_path "$env_id" "$domain")"
  meta="$(soviez_nginx_owned_meta_path "$out")"
  now="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
  local staged="${out}.staged"

  # Collision: another env owns same domain (active or staged)
  local other
  for other in "$SOVIEZ_SSL_NGINX_OWNED_DIR"/*__"${domain}".conf "$SOVIEZ_SSL_NGINX_OWNED_DIR"/*__"${domain}".conf.staged; do
    [[ -e "$other" ]] || continue
    if [[ "$other" != "$out" && "$other" != "$staged" ]]; then
      soviez_ssl_die "$SOVIEZ_SSL_CODE_NGINX_CONFIG_CONFLICT" "Domain already owned by another managed config: $other"
    fi
  done

  if [[ "$mode" == "http_temp" ]]; then
    cat > "$staged" <<EOF
# SOVIEZ_OWNED env_id=${env_id} domain=${domain} module=ssl_lifecycle version=phase12
server {
    listen 80;
    server_name ${domain};
    location / {
        return 503 "Soviez provisioning incomplete — temporary HTTP only";
    }
}
EOF
  else
    local ws_upstream="${SOVIEZ_NGINX_WS_UPSTREAM:-}"
    if [[ -z "$ws_upstream" ]]; then
      # Owner-approved topology: HTTP :8069, WebSocket/gevent :8072 on same host.
      if [[ "$upstream" =~ ^(.+):8069$ ]]; then
        ws_upstream="${BASH_REMATCH[1]}:8072"
      else
        ws_upstream="$upstream"
      fi
    fi
    cat > "$staged" <<EOF
# SOVIEZ_OWNED env_id=${env_id} domain=${domain} module=ssl_lifecycle version=phase12-ws2
server {
    listen 80;
    server_name ${domain};
    return 301 https://\$host\$request_uri;
}
server {
    listen 443 ssl;
    server_name ${domain};
    ssl_certificate ${cert};
    ssl_certificate_key ${key};
    proxy_read_timeout 720s;
    proxy_connect_timeout 720s;
    proxy_send_timeout 720s;

    location /websocket {
        proxy_pass http://${ws_upstream};
        proxy_http_version 1.1;
        proxy_set_header Upgrade \$http_upgrade;
        proxy_set_header Connection \$connection_upgrade;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_read_timeout 720s;
    }

    # Compatibility (Odoo 18): longpolling → evented backend when multi-worker
    location /longpolling {
        proxy_pass http://${ws_upstream};
        proxy_http_version 1.1;
        proxy_set_header Upgrade \$http_upgrade;
        proxy_set_header Connection \$connection_upgrade;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_read_timeout 720s;
    }

    location / {
        proxy_pass http://${upstream};
        proxy_http_version 1.1;
        proxy_set_header Upgrade \$http_upgrade;
        proxy_set_header Connection \$connection_upgrade;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_set_header X-Forwarded-Host \$host;
        proxy_read_timeout 720s;
        proxy_buffering off;
    }
}
EOF
  fi

  # Note: requires http-level map \$http_upgrade \$connection_upgrade (ERP soviez_limits /
  # S2 hardened). Template assumes that map exists on supported hosts.

  checksum="$(openssl dgst -sha256 "$staged" | awk '{print $NF}')"
  ENV_ID="$env_id" DOMAIN="$domain" UP="$upstream" OP="$op_id" SUM="$checksum" NOW="$now" MODE="$mode" \
    python3 - <<'PY' > "$meta"
import json, os
print(json.dumps({
  "environment_id": os.environ["ENV_ID"],
  "domain": os.environ["DOMAIN"],
  "upstream": os.environ["UP"],
  "owner_module": "ssl_lifecycle",
  "operation_id": os.environ.get("OP") or None,
  "generated_at": os.environ["NOW"],
  "template_version": "phase12-ws1",
  "checksum": os.environ["SUM"],
  "state": "staged",
  "mode": os.environ["MODE"]
}, indent=2))
PY
  chmod 644 "$staged" "$meta"
  printf '%s\n' "$staged"
}

soviez_nginx_test_config() {
  local conf="$1"
  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    # Fixture: fail if marker present
    if grep -q 'SOVIEZ_FORCE_NGINX_T_FAIL' "$conf" 2>/dev/null; then
      return 1
    fi
    return 0
  fi
  if command -v nginx >/dev/null 2>&1; then
    nginx -t -c "$conf" >/dev/null 2>&1
  else
    # Without nginx binary, structural check only
    grep -q 'server_name' "$conf"
  fi
}

soviez_nginx_promote_owned() {
  local staged="$1"
  local final="${staged%.staged}"
  local prev="${final}.previous"
  if [[ -f "$final" ]]; then
    cp -f "$final" "$prev"
  fi
  if ! soviez_nginx_test_config "$staged"; then
    rm -f "$staged"
    soviez_ssl_die "$SOVIEZ_SSL_CODE_NGINX_VALIDATION_FAILED" "nginx -t failed for staged config"
  fi
  mv -f "$staged" "$final"
  local meta
  meta="$(soviez_nginx_owned_meta_path "$final")"
  if [[ -f "$meta" ]]; then
    python3 -c 'import json,sys; p=sys.argv[1]; d=json.load(open(p)); d["state"]="active"; json.dump(d, open(p,"w"), indent=2)' "$meta"
  fi
  printf '%s\n' "$final"
}

soviez_nginx_reload_safe() {
  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    if [[ "${SOVIEZ_FORCE_NGINX_RELOAD_FAIL:-0}" == "1" ]]; then
      return 1
    fi
    return 0
  fi
  if command -v nginx >/dev/null 2>&1; then
    nginx -s reload
  else
    return 0
  fi
}

soviez_nginx_rollback_owned() {
  local final="$1"
  local prev="${final}.previous"
  [[ -f "$prev" ]] || soviez_ssl_die "$SOVIEZ_SSL_CODE_CERTIFICATE_ROLLBACK_FAILED" "No previous Nginx config to restore"
  cp -f "$prev" "$final"
  soviez_nginx_test_config "$final" || soviez_ssl_die "$SOVIEZ_SSL_CODE_CERTIFICATE_ROLLBACK_FAILED" "Rolled-back Nginx config failed nginx -t"
  soviez_nginx_reload_safe || soviez_ssl_die "$SOVIEZ_SSL_CODE_NGINX_RELOAD_FAILED" "Nginx reload failed after rollback"
}

# Unmanaged configs must never be deleted by soviez.
soviez_nginx_is_owned() {
  local path="$1"
  grep -q 'SOVIEZ_OWNED' "$path" 2>/dev/null
}

# --- end nginx/ownership.sh ---

# --- begin ssl/codes.sh ---
# shellcheck shell=bash
# Phase 12 structured SSL denial/failure codes (protocol behavior).

SOVIEZ_SSL_CODE_NO_MANAGED_ENVIRONMENT="NO_MANAGED_ENVIRONMENT"
SOVIEZ_SSL_CODE_ENVIRONMENT_SELECTION_REQUIRED="ENVIRONMENT_SELECTION_REQUIRED"
SOVIEZ_SSL_CODE_ENVIRONMENT_IDENTITY_MISMATCH="ENVIRONMENT_IDENTITY_MISMATCH"
SOVIEZ_SSL_CODE_DOMAIN_REQUIRED="DOMAIN_REQUIRED"
SOVIEZ_SSL_CODE_DOMAIN_CONFLICT="DOMAIN_CONFLICT"
SOVIEZ_SSL_CODE_DNS_VALIDATION_FAILED="DNS_VALIDATION_FAILED"
SOVIEZ_SSL_CODE_DNS_WAIT_TIMEOUT="DNS_WAIT_TIMEOUT"
SOVIEZ_SSL_CODE_DNS_CHALLENGE_EXPIRED="DNS_CHALLENGE_EXPIRED"
SOVIEZ_SSL_CODE_DNS_CHALLENGE_REPLAY="DNS_CHALLENGE_REPLAY"
SOVIEZ_SSL_CODE_DNS_CHALLENGE_BINDING_MISMATCH="DNS_CHALLENGE_BINDING_MISMATCH"
SOVIEZ_SSL_CODE_CERTIFICATE_MISSING="CERTIFICATE_MISSING"
SOVIEZ_SSL_CODE_CERTIFICATE_EXPIRED="CERTIFICATE_EXPIRED"
SOVIEZ_SSL_CODE_CERTIFICATE_NOT_YET_VALID="CERTIFICATE_NOT_YET_VALID"
SOVIEZ_SSL_CODE_CERTIFICATE_HOSTNAME_MISMATCH="CERTIFICATE_HOSTNAME_MISMATCH"
SOVIEZ_SSL_CODE_CERTIFICATE_CHAIN_INVALID="CERTIFICATE_CHAIN_INVALID"
SOVIEZ_SSL_CODE_CERTIFICATE_UNTRUSTED="CERTIFICATE_UNTRUSTED"
SOVIEZ_SSL_CODE_CERTIFICATE_KEY_MISMATCH="CERTIFICATE_KEY_MISMATCH"
SOVIEZ_SSL_CODE_CERTIFICATE_PERMISSION_INVALID="CERTIFICATE_PERMISSION_INVALID"
SOVIEZ_SSL_CODE_SELF_SIGNED_NOT_ALLOWED="SELF_SIGNED_NOT_ALLOWED"
SOVIEZ_SSL_CODE_PRIVATE_CA_NOT_APPROVED="PRIVATE_CA_NOT_APPROVED"
SOVIEZ_SSL_CODE_RENEWAL_NOT_DUE="RENEWAL_NOT_DUE"
SOVIEZ_SSL_CODE_RENEWAL_DISABLED="RENEWAL_DISABLED"
SOVIEZ_SSL_CODE_RENEWAL_IN_PROGRESS="RENEWAL_IN_PROGRESS"
SOVIEZ_SSL_CODE_RENEWAL_FAILED="RENEWAL_FAILED"
SOVIEZ_SSL_CODE_RENEWAL_RETRY_SCHEDULED="RENEWAL_RETRY_SCHEDULED"
SOVIEZ_SSL_CODE_ACME_PROVIDER_UNAVAILABLE="ACME_PROVIDER_UNAVAILABLE"
SOVIEZ_SSL_CODE_ACME_RATE_LIMITED="ACME_RATE_LIMITED"
SOVIEZ_SSL_CODE_WILDCARD_NOT_ALLOWED="WILDCARD_NOT_ALLOWED"
SOVIEZ_SSL_CODE_WILDCARD_SCOPE_MISMATCH="WILDCARD_SCOPE_MISMATCH"
SOVIEZ_SSL_CODE_NGINX_CONFIG_CONFLICT="NGINX_CONFIG_CONFLICT"
SOVIEZ_SSL_CODE_NGINX_VALIDATION_FAILED="NGINX_VALIDATION_FAILED"
SOVIEZ_SSL_CODE_NGINX_RELOAD_FAILED="NGINX_RELOAD_FAILED"
SOVIEZ_SSL_CODE_HTTPS_VALIDATION_FAILED="HTTPS_VALIDATION_FAILED"
SOVIEZ_SSL_CODE_CERTIFICATE_PROMOTION_FAILED="CERTIFICATE_PROMOTION_FAILED"
SOVIEZ_SSL_CODE_CERTIFICATE_ROLLBACK_FAILED="CERTIFICATE_ROLLBACK_FAILED"
SOVIEZ_SSL_CODE_RECOVERY_REQUIRED="RECOVERY_REQUIRED"
SOVIEZ_SSL_CODE_DESTRUCTIVE_CONFIRMATION_REQUIRED="DESTRUCTIVE_CONFIRMATION_REQUIRED"

soviez_ssl_die() {
  local code="$1"
  local msg="${2:-$code}"
  # Structured denial on stderr; never print secrets.
  printf 'SSL_DENIAL code=%s message=%s\n' "$code" "$(soviez_redact_text "$msg")" >&2
  exit "${SOVIEZ_ERR_SSL:-7}"
}

# --- end ssl/codes.sh ---

# --- begin ssl/paths.sh ---
# shellcheck shell=bash
# Phase 12 SSL paths and inventory locations (local-first; no SaaS required).

soviez_ssl_paths_init() {
  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    SOVIEZ_SSL_ROOT="$SOVIEZ_ROOT/ssl"
    SOVIEZ_SSL_INVENTORY_DIR="$SOVIEZ_SSL_ROOT/inventory"
    SOVIEZ_SSL_CERTS_DIR="$SOVIEZ_SSL_ROOT/certs"
    SOVIEZ_SSL_STAGING_DIR="$SOVIEZ_SSL_ROOT/staging"
    SOVIEZ_SSL_CHALLENGE_DIR="$SOVIEZ_SSL_ROOT/challenges"
    SOVIEZ_SSL_NGINX_OWNED_DIR="$SOVIEZ_SSL_ROOT/nginx-owned"
    SOVIEZ_SSL_OPS_DIR="$SOVIEZ_OPS_ROOT/ssl-operations"
  else
    SOVIEZ_SSL_ROOT="${SOVIEZ_SSL_ROOT:-$SOVIEZ_ROOT/ssl}"
    SOVIEZ_SSL_INVENTORY_DIR="${SOVIEZ_SSL_INVENTORY_DIR:-$SOVIEZ_SSL_ROOT/inventory}"
    SOVIEZ_SSL_CERTS_DIR="${SOVIEZ_SSL_CERTS_DIR:-$SOVIEZ_SSL_ROOT/certs}"
    SOVIEZ_SSL_STAGING_DIR="${SOVIEZ_SSL_STAGING_DIR:-$SOVIEZ_SSL_ROOT/staging}"
    SOVIEZ_SSL_CHALLENGE_DIR="${SOVIEZ_SSL_CHALLENGE_DIR:-$SOVIEZ_SSL_ROOT/challenges}"
    SOVIEZ_SSL_NGINX_OWNED_DIR="${SOVIEZ_SSL_NGINX_OWNED_DIR:-$SOVIEZ_SSL_ROOT/nginx-owned}"
    SOVIEZ_SSL_OPS_DIR="${SOVIEZ_SSL_OPS_DIR:-$SOVIEZ_OPS_ROOT/ssl-operations}"
  fi
  export SOVIEZ_SSL_ROOT SOVIEZ_SSL_INVENTORY_DIR SOVIEZ_SSL_CERTS_DIR
  export SOVIEZ_SSL_STAGING_DIR SOVIEZ_SSL_CHALLENGE_DIR SOVIEZ_SSL_NGINX_OWNED_DIR SOVIEZ_SSL_OPS_DIR
  mkdir -p "$SOVIEZ_SSL_INVENTORY_DIR" "$SOVIEZ_SSL_CERTS_DIR" "$SOVIEZ_SSL_STAGING_DIR" \
    "$SOVIEZ_SSL_CHALLENGE_DIR" "$SOVIEZ_SSL_NGINX_OWNED_DIR" "$SOVIEZ_SSL_OPS_DIR"
  chmod 700 "$SOVIEZ_SSL_ROOT" "$SOVIEZ_SSL_CERTS_DIR" "$SOVIEZ_SSL_STAGING_DIR" \
    "$SOVIEZ_SSL_CHALLENGE_DIR" "$SOVIEZ_SSL_INVENTORY_DIR" 2>/dev/null || true
}

soviez_ssl_inventory_file() {
  local env_id="$1"
  printf '%s/%s.json\n' "$SOVIEZ_SSL_INVENTORY_DIR" "$env_id"
}

soviez_ssl_env_cert_dir() {
  local env_id="$1"
  printf '%s/%s\n' "$SOVIEZ_SSL_CERTS_DIR" "$env_id"
}

soviez_ssl_lock_dir() {
  local env_id="$1"
  printf '%s/locks/%s\n' "$SOVIEZ_SSL_ROOT" "$env_id"
}

# --- end ssl/paths.sh ---

# --- begin ssl/policy.sh ---
# shellcheck shell=bash
# Phase 12 Production/Stage SSL policy (owner-approved defaults).

# Defaults (binding owner decisions)
SOVIEZ_SSL_DEFAULT_RENEWAL_MODE="${SOVIEZ_SSL_DEFAULT_RENEWAL_MODE:-automatic}"
SOVIEZ_SSL_DEFAULT_RENEWAL_LEAD_DAYS="${SOVIEZ_SSL_DEFAULT_RENEWAL_LEAD_DAYS:-30}"
SOVIEZ_SSL_DEFAULT_ACME_PROVIDER="${SOVIEZ_SSL_DEFAULT_ACME_PROVIDER:-letsencrypt}"
SOVIEZ_SSL_WARNING_DAYS="${SOVIEZ_SSL_WARNING_DAYS:-30 14 7 3 1}"
SOVIEZ_SSL_ALLOW_PRIVATE_CA="${SOVIEZ_SSL_ALLOW_PRIVATE_CA:-0}"
SOVIEZ_SSL_ALLOW_WILDCARD="${SOVIEZ_SSL_ALLOW_WILDCARD:-0}"

soviez_ssl_policy_normalize_mode() {
  local mode="${1:-automatic}"
  case "$mode" in
    automatic|notify_only|manual) printf '%s\n' "$mode" ;;
    *) soviez_ssl_die "$SOVIEZ_SSL_CODE_RENEWAL_DISABLED" "Invalid renewal mode: $mode" ;;
  esac
}

soviez_ssl_policy_assert_ca() {
  local mode="$1" # public|private_ca|self_signed
  case "$mode" in
    public) return 0 ;;
    private_ca)
      if [[ "${SOVIEZ_SSL_ALLOW_PRIVATE_CA}" != "1" ]]; then
        soviez_ssl_die "$SOVIEZ_SSL_CODE_PRIVATE_CA_NOT_APPROVED" \
          "Private CA requires explicit enterprise policy (SOVIEZ_SSL_ALLOW_PRIVATE_CA=1)"
      fi
      return 0
      ;;
    self_signed)
      soviez_ssl_die "$SOVIEZ_SSL_CODE_SELF_SIGNED_NOT_ALLOWED" "Self-signed certificates are not accepted as final PASS"
      ;;
    *)
      soviez_ssl_die "$SOVIEZ_SSL_CODE_CERTIFICATE_UNTRUSTED" "Unknown certificate mode: $mode"
      ;;
  esac
}

soviez_ssl_policy_assert_wildcard() {
  local want_wildcard="$1"
  if [[ "$want_wildcard" == "1" || "$want_wildcard" == "true" ]]; then
    if [[ "${SOVIEZ_SSL_ALLOW_WILDCARD}" != "1" ]]; then
      soviez_ssl_die "$SOVIEZ_SSL_CODE_WILDCARD_NOT_ALLOWED" "Wildcard requires explicit operator selection"
    fi
  fi
}

# Production readiness: never "ready" until trusted HTTPS passes.
soviez_ssl_policy_production_ready() {
  local lifecycle_state="$1"
  [[ "$lifecycle_state" == "ready" || "$lifecycle_state" == "healthy" ]]
}

soviez_ssl_policy_renewal_priority() {
  local env_type="$1"
  case "$env_type" in
    production|Production) printf '10\n' ;;
    stage|Stage) printf '5\n' ;;
    *) printf '1\n' ;;
  esac
}

# --- end ssl/policy.sh ---

# --- begin ssl/lifecycle_sm.sh ---
# shellcheck shell=bash
# Phase 12 certificate lifecycle state machine (durable, resumable).

SOVIEZ_SSL_STATES=(
  healthy
  renewal_window
  renewal_scheduled
  renewal_authorizing
  challenge_preparing
  waiting_for_dns
  challenge_validating
  certificate_issuing
  certificate_received
  certificate_validating
  nginx_staging
  nginx_validating
  nginx_reloading
  https_validating
  certificate_promoting
  completed
  retry_scheduled
  needs_action
  certificate_expired
  rollback_running
  recovery_required
  canceled
  failed_retryable
  failed_terminal
  provisioning
  waiting_for_ssl
  ready
)

soviez_ssl_sm_is_known() {
  local s="$1"
  local x
  for x in "${SOVIEZ_SSL_STATES[@]}"; do
    [[ "$x" == "$s" ]] && return 0
  done
  return 1
}

soviez_ssl_sm_can_transition() {
  local from="$1"
  local to="$2"
  [[ "$from" == "$to" ]] && return 0
  case "$from:$to" in
    healthy:renewal_window|healthy:needs_action|healthy:certificate_expired) return 0 ;;
    renewal_window:renewal_scheduled|renewal_window:needs_action) return 0 ;;
    renewal_scheduled:renewal_authorizing|renewal_scheduled:canceled|renewal_scheduled:needs_action) return 0 ;;
    renewal_authorizing:challenge_preparing|renewal_authorizing:failed_retryable|renewal_authorizing:needs_action) return 0 ;;
    challenge_preparing:waiting_for_dns|challenge_preparing:failed_retryable) return 0 ;;
    waiting_for_dns:challenge_validating|waiting_for_dns:retry_scheduled|waiting_for_dns:canceled|waiting_for_dns:needs_action) return 0 ;;
    challenge_validating:certificate_issuing|challenge_validating:failed_retryable|challenge_validating:needs_action) return 0 ;;
    certificate_issuing:certificate_received|certificate_issuing:failed_retryable|certificate_issuing:acme*) return 0 ;;
    certificate_issuing:retry_scheduled|certificate_issuing:needs_action) return 0 ;;
    certificate_received:certificate_validating|certificate_received:rollback_running) return 0 ;;
    certificate_validating:nginx_staging|certificate_validating:rollback_running|certificate_validating:failed_retryable) return 0 ;;
    nginx_staging:nginx_validating|nginx_staging:rollback_running) return 0 ;;
    nginx_validating:nginx_reloading|nginx_validating:rollback_running) return 0 ;;
    nginx_reloading:https_validating|nginx_reloading:rollback_running) return 0 ;;
    https_validating:certificate_promoting|https_validating:rollback_running) return 0 ;;
    certificate_promoting:completed|certificate_promoting:rollback_running) return 0 ;;
    completed:healthy) return 0 ;;
    failed_retryable:retry_scheduled|failed_retryable:needs_action|failed_retryable:recovery_required) return 0 ;;
    retry_scheduled:renewal_authorizing|retry_scheduled:canceled|retry_scheduled:needs_action) return 0 ;;
    needs_action:renewal_authorizing|needs_action:rollback_running|needs_action:recovery_required|needs_action:canceled) return 0 ;;
    certificate_expired:renewal_authorizing|certificate_expired:needs_action|certificate_expired:recovery_required) return 0 ;;
    rollback_running:healthy|rollback_running:needs_action|rollback_running:recovery_required|rollback_running:failed_terminal) return 0 ;;
    recovery_required:renewal_authorizing|recovery_required:canceled) return 0 ;;
    provisioning:waiting_for_dns|provisioning:waiting_for_ssl|provisioning:needs_action) return 0 ;;
    waiting_for_dns:waiting_for_ssl|waiting_for_dns:needs_action) return 0 ;;
    waiting_for_ssl:ready|waiting_for_ssl:needs_action) return 0 ;;
    ready:healthy|ready:renewal_window) return 0 ;;
    canceled:healthy|failed_terminal:recovery_required) return 0 ;;
    *) return 1 ;;
  esac
}

soviez_ssl_sm_assert_transition() {
  local from="$1"
  local to="$2"
  soviez_ssl_sm_is_known "$from" || soviez_ssl_die "$SOVIEZ_SSL_CODE_RECOVERY_REQUIRED" "Unknown SSL state: $from"
  soviez_ssl_sm_is_known "$to" || soviez_ssl_die "$SOVIEZ_SSL_CODE_RECOVERY_REQUIRED" "Unknown SSL state: $to"
  if ! soviez_ssl_sm_can_transition "$from" "$to"; then
    soviez_ssl_die "$SOVIEZ_SSL_CODE_RECOVERY_REQUIRED" "Illegal SSL transition $from -> $to"
  fi
}

# Current working certificate is preserved in all states except successful promotion.
soviez_ssl_sm_preserves_current_cert() {
  local state="$1"
  case "$state" in
    certificate_promoting|completed) return 1 ;;
    *) return 0 ;;
  esac
}

# --- end ssl/lifecycle_sm.sh ---

# --- begin ssl/local_ca.sh ---
# shellcheck shell=bash

soviez_ssl_local_ca_init() {
  local ca_dir="$SOVIEZ_ROOT/ssl/local-ca"
  mkdir -p "$ca_dir"
  chmod 700 "$ca_dir"
  if [[ ! -f "$ca_dir/ca.key" ]]; then
    openssl genrsa -out "$ca_dir/ca.key" 4096 >/dev/null 2>&1
    chmod 600 "$ca_dir/ca.key"
    openssl req -x509 -new -nodes -key "$ca_dir/ca.key" -sha256 -days 3650 \
      -subj "/CN=Soviez Local Test CA" -out "$ca_dir/ca.crt" >/dev/null 2>&1
  fi
  printf '%s\n' "$ca_dir/ca.crt" "$ca_dir/ca.key"
}

soviez_ssl_local_issue_cert() {
  local domain="$1"
  local ca_dir="$SOVIEZ_ROOT/ssl/local-ca"
  local cert_dir="$SOVIEZ_ROOT/ssl/certs/$domain"
  mkdir -p "$cert_dir"
  chmod 700 "$cert_dir"
  if [[ ! -f "$ca_dir/ca.crt" ]]; then
    soviez_ssl_local_ca_init >/dev/null
  fi
  if [[ ! -f "$cert_dir/server.key" ]]; then
    openssl genrsa -out "$cert_dir/server.key" 2048 >/dev/null 2>&1
    chmod 600 "$cert_dir/server.key"
    openssl req -new -key "$cert_dir/server.key" -subj "/CN=$domain" -out "$cert_dir/server.csr" >/dev/null 2>&1
    openssl x509 -req -in "$cert_dir/server.csr" -CA "$ca_dir/ca.crt" -CAkey "$ca_dir/ca.key" \
      -CAcreateserial -out "$cert_dir/server.crt" -days 825 -sha256 >/dev/null 2>&1
  fi
  printf '%s\n' "$cert_dir/server.crt" "$cert_dir/server.key" "$ca_dir/ca.crt"
}

# --- end ssl/local_ca.sh ---

# --- begin ssl/validate.sh ---
# shellcheck shell=bash

soviez_ssl_validate_chain() {
  local cert_file="$1"
  local ca_file="${2:-}"

  if [[ ! -f "$cert_file" ]]; then
    if declare -F soviez_ssl_die >/dev/null 2>&1; then
      soviez_ssl_die "${SOVIEZ_SSL_CODE_CERTIFICATE_MISSING:-CERTIFICATE_MISSING}" "Certificate file missing"
    fi
    soviez_die "$SOVIEZ_ERR_SSL" "Certificate file missing"
  fi

  if [[ -n "$ca_file" && -f "$ca_file" ]]; then
    if openssl verify -CAfile "$ca_file" "$cert_file" >/dev/null 2>&1; then
      return 0
    fi
    if declare -F soviez_ssl_die >/dev/null 2>&1; then
      soviez_ssl_die "${SOVIEZ_SSL_CODE_CERTIFICATE_CHAIN_INVALID:-CERTIFICATE_CHAIN_INVALID}" "Certificate chain validation failed"
    fi
    soviez_die "$SOVIEZ_ERR_SSL" "Certificate chain validation failed"
  fi

  # Reject bare self-signed (issuer == subject) when no trusted CA provided.
  local issuer subject
  issuer="$(openssl x509 -in "$cert_file" -noout -issuer 2>/dev/null | sed 's/^issuer=//')"
  subject="$(openssl x509 -in "$cert_file" -noout -subject 2>/dev/null | sed 's/^subject=//')"
  issuer="$(printf '%s' "$issuer" | tr -d ' ')"
  subject="$(printf '%s' "$subject" | tr -d ' ')"
  if [[ "$issuer" == "$subject" ]]; then
    if declare -F soviez_ssl_die >/dev/null 2>&1; then
      soviez_ssl_die "${SOVIEZ_SSL_CODE_SELF_SIGNED_NOT_ALLOWED:-SELF_SIGNED_NOT_ALLOWED}" "Self-signed certificate rejected"
    fi
    soviez_die "$SOVIEZ_ERR_SSL" "Self-signed certificate rejected"
  fi
  return 0
}

# Final acceptance helper — never allows self-signed or unapproved private CA.
soviez_ssl_final_acceptance() {
  local cert_file="$1"
  local ca_file="${2:-}"
  local cert_mode="${3:-public}"
  if declare -F soviez_ssl_policy_assert_ca >/dev/null 2>&1; then
    soviez_ssl_policy_assert_ca "$cert_mode"
  fi
  soviez_ssl_validate_chain "$cert_file" "$ca_file"
}

# --- end ssl/validate.sh ---

# --- begin ssl/letsencrypt.sh ---
# shellcheck shell=bash

soviez_ssl_letsencrypt_render() {
  local domain="$1"
  local email="$2"
  printf 'certbot certonly --nginx -d %s --email %s --agree-tos --non-interactive\n' "$domain" "$email"
}

soviez_ssl_letsencrypt_map_error() {
  local stderr="$1"
  case "$stderr" in
    *rate*limit*) printf 'letsencrypt_rate_limited\n' ;;
    *dns*) printf 'dns_challenge_failed\n' ;;
    *) printf 'letsencrypt_failed\n' ;;
  esac
}

# --- end ssl/letsencrypt.sh ---

# --- begin ssl/inventory.sh ---
# shellcheck shell=bash
# Phase 12 certificate inventory (no private keys / secrets in records).

soviez_ssl_inventory_write_atomic() {
  local env_id="$1"
  local json="$2"
  local target tmp
  soviez_ssl_paths_init
  target="$(soviez_ssl_inventory_file "$env_id")"
  tmp="${target}.tmp.$$"
  printf '%s\n' "$json" > "$tmp"
  chmod 600 "$tmp"
  mv -f "$tmp" "$target"
}

soviez_ssl_inventory_read() {
  local env_id="$1"
  local f
  soviez_ssl_paths_init
  f="$(soviez_ssl_inventory_file "$env_id")"
  [[ -f "$f" ]] || soviez_ssl_die "$SOVIEZ_SSL_CODE_NO_MANAGED_ENVIRONMENT" "No SSL inventory for $env_id"
  cat "$f"
}

soviez_ssl_inventory_exists() {
  local env_id="$1"
  soviez_ssl_paths_init
  [[ -f "$(soviez_ssl_inventory_file "$env_id")" ]]
}

soviez_ssl_inventory_create() {
  local env_id="$1"
  local env_type="$2"
  local domain="$3"
  local cert_path="$4"
  local key_path="$5"
  local chain_path="${6:-}"
  local cert_mode="${7:-public}"
  local provider="${8:-$SOVIEZ_SSL_DEFAULT_ACME_PROVIDER}"
  local renewal_mode="${9:-$SOVIEZ_SSL_DEFAULT_RENEWAL_MODE}"
  local wildcard_scope="${10:-}"
  local private_ca_flag="${11:-0}"

  [[ -n "$env_id" ]] || soviez_ssl_die "$SOVIEZ_SSL_CODE_ENVIRONMENT_SELECTION_REQUIRED" "environment id required"
  [[ -n "$domain" ]] || soviez_ssl_die "$SOVIEZ_SSL_CODE_DOMAIN_REQUIRED" "domain required"
  renewal_mode="$(soviez_ssl_policy_normalize_mode "$renewal_mode")"
  soviez_ssl_policy_assert_ca "$cert_mode"

  local digest serial not_before not_after issuer
  digest=""
  serial=""
  not_before=""
  not_after=""
  issuer=""
  if [[ -f "$cert_path" ]]; then
    digest="$(openssl x509 -in "$cert_path" -noout -fingerprint -sha256 2>/dev/null | sed 's/.*=//' | tr -d ':')"
    serial="$(openssl x509 -in "$cert_path" -noout -serial 2>/dev/null | sed 's/serial=//')"
    not_before="$(openssl x509 -in "$cert_path" -noout -startdate 2>/dev/null | sed 's/notBefore=//')"
    not_after="$(openssl x509 -in "$cert_path" -noout -enddate 2>/dev/null | sed 's/notAfter=//')"
    issuer="$(openssl x509 -in "$cert_path" -noout -issuer 2>/dev/null | sed 's/issuer=//')"
  fi

  local now
  now="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
  local json
  json="$(ENV_ID="$env_id" ENV_TYPE="$env_type" DOMAIN="$domain" CERT="$cert_path" KEY="$key_path" \
    CHAIN="$chain_path" MODE="$cert_mode" PROVIDER="$provider" RMODE="$renewal_mode" \
    DIGEST="$digest" SERIAL="$serial" NB="$not_before" NA="$not_after" ISSUER="$issuer" \
    WS="$wildcard_scope" PCA="$private_ca_flag" NOW="$now" LEAD="$SOVIEZ_SSL_DEFAULT_RENEWAL_LEAD_DAYS" \
    python3 - <<'PY'
import json, os
rec = {
  "environment_id": os.environ["ENV_ID"],
  "environment_type": os.environ["ENV_TYPE"],
  "domain": os.environ["DOMAIN"],
  "certificate_mode": os.environ["MODE"],
  "acme_provider": os.environ["PROVIDER"],
  "certificate_path": os.environ["CERT"],
  "private_key_path": os.environ["KEY"],
  "chain_path": os.environ.get("CHAIN") or None,
  "issuer": os.environ.get("ISSUER") or None,
  "serial_abbreviated": (os.environ.get("SERIAL") or "")[:16] or None,
  "not_before": os.environ.get("NB") or None,
  "not_after": os.environ.get("NA") or None,
  "hostname_verification": None,
  "chain_verification": None,
  "current_certificate_digest": os.environ.get("DIGEST") or None,
  "previous_certificate_digest": None,
  "renewal_mode": os.environ["RMODE"],
  "renewal_lead_days": int(os.environ.get("LEAD") or "30"),
  "last_renewal_attempt": None,
  "last_successful_renewal": None,
  "next_scheduled_attempt": None,
  "retry_count": 0,
  "last_failure_code": None,
  "lifecycle_state": "healthy",
  "readiness_state": "ready" if os.environ["ENV_TYPE"].lower() != "production" else "ready",
  "operation_id": None,
  "challenge_id": None,
  "wildcard_scope": os.environ.get("WS") or None,
  "private_ca_policy": os.environ.get("PCA") == "1",
  "created_at": os.environ["NOW"],
  "updated_at": os.environ["NOW"],
}
# Never embed key material
assert "BEGIN" not in json.dumps(rec)
print(json.dumps(rec, indent=2))
PY
)"
  soviez_ssl_inventory_write_atomic "$env_id" "$json"
}

soviez_ssl_inventory_patch() {
  local env_id="$1"
  local patch_json="$2"
  local current
  current="$(soviez_ssl_inventory_read "$env_id")"
  local merged
  merged="$(CUR="$current" PATCH="$patch_json" python3 - <<'PY'
import json, os, time
cur = json.loads(os.environ["CUR"])
patch = json.loads(os.environ["PATCH"])
# Forbid secret-like keys
for k in list(patch.keys()):
    if k.lower() in ("private_key", "private_key_pem", "acme_account_key", "token", "secret"):
        raise SystemExit("secret fields forbidden in inventory patch")
cur.update(patch)
cur["updated_at"] = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
print(json.dumps(cur, indent=2))
PY
)"
  soviez_ssl_inventory_write_atomic "$env_id" "$merged"
}

soviez_ssl_inventory_list_ids() {
  soviez_ssl_paths_init
  local f
  for f in "$SOVIEZ_SSL_INVENTORY_DIR"/*.json; do
    [[ -f "$f" ]] || continue
    basename "$f" .json
  done
}

soviez_ssl_inventory_validate_record() {
  local env_id="$1"
  local rec cert key
  rec="$(soviez_ssl_inventory_read "$env_id")"
  cert="$(soviez_json_get "$rec" certificate_path)"
  key="$(soviez_json_get "$rec" private_key_path)"
  local domain id_in_rec
  domain="$(soviez_json_get "$rec" domain)"
  id_in_rec="$(soviez_json_get "$rec" environment_id)"
  [[ "$id_in_rec" == "$env_id" ]] || soviez_ssl_die "$SOVIEZ_SSL_CODE_ENVIRONMENT_IDENTITY_MISMATCH" "inventory id mismatch"
  [[ -n "$domain" ]] || soviez_ssl_die "$SOVIEZ_SSL_CODE_DOMAIN_REQUIRED" "domain missing in inventory"
  [[ -f "$cert" ]] || soviez_ssl_die "$SOVIEZ_SSL_CODE_CERTIFICATE_MISSING" "certificate file missing"
  [[ -f "$key" ]] || soviez_ssl_die "$SOVIEZ_SSL_CODE_CERTIFICATE_MISSING" "private key file missing"
}

# --- end ssl/inventory.sh ---

# --- begin ssl/monitor.sh ---
# shellcheck shell=bash
# Phase 12 local certificate monitoring (no SaaS phone-home).

soviez_ssl_days_until_expiry() {
  local cert_path="$1"
  local end epoch_end now
  end="$(openssl x509 -in "$cert_path" -noout -enddate 2>/dev/null | sed 's/notAfter=//')"
  epoch_end="$(date -u -j -f "%b %d %T %Y %Z" "$end" +%s 2>/dev/null || date -u -d "$end" +%s 2>/dev/null || echo 0)"
  now="$(date -u +%s)"
  if [[ "$epoch_end" -eq 0 ]]; then
    printf '%s\n' "-9999"
    return 0
  fi
  printf '%s\n' "$(( (epoch_end - now) / 86400 ))"
}

soviez_ssl_check_permissions() {
  local cert_path="$1"
  local key_path="$2"
  local mode
  mode="$(stat -f '%Lp' "$key_path" 2>/dev/null || stat -c '%a' "$key_path" 2>/dev/null || echo 777)"
  # Reject world-readable private keys
  case "$mode" in
    *7|*6|*5|*4)
      # if last digit is 4-7, world readable/writable/executable
      local last="${mode: -1}"
      if [[ "$last" =~ [4567] ]]; then
        return 1
      fi
      ;;
  esac
  # Also reject if others bits set via octal compare when 3-digit
  if [[ ${#mode} -eq 3 ]]; then
    local others=$((10#${mode:2:1}))
    (( others == 0 )) || return 1
  fi
  return 0
}

soviez_ssl_check_key_match() {
  local cert_path="$1"
  local key_path="$2"
  local cert_mod key_mod
  cert_mod="$(openssl x509 -noout -modulus -in "$cert_path" 2>/dev/null | openssl md5)"
  key_mod="$(openssl rsa -noout -modulus -in "$key_path" 2>/dev/null | openssl md5)"
  [[ "$cert_mod" == "$key_mod" ]]
}

soviez_ssl_check_hostname() {
  local cert_path="$1"
  local domain="$2"
  # SAN or CN must match domain or wildcard scope
  local text
  text="$(openssl x509 -in "$cert_path" -noout -text 2>/dev/null || true)"
  if printf '%s' "$text" | grep -Eqi "DNS:${domain}([[:space:],]|$)|DNS:\\*\\.${domain#*.}"; then
    return 0
  fi
  local cn
  cn="$(openssl x509 -in "$cert_path" -noout -subject 2>/dev/null | sed -n 's/.*CN *= *\\([^,/]*\\).*/\\1/p')"
  [[ "$cn" == "$domain" ]]
}

soviez_ssl_monitor_env() {
  local env_id="$1"
  local rec cert key domain days state code="OK"
  rec="$(soviez_ssl_inventory_read "$env_id")"
  cert="$(soviez_json_get "$rec" certificate_path)"
  key="$(soviez_json_get "$rec" private_key_path)"
  domain="$(soviez_json_get "$rec" domain)"
  local chain
  chain="$(soviez_json_get "$rec" chain_path 2>/dev/null || true)"

  if [[ ! -f "$cert" ]]; then
    code="$SOVIEZ_SSL_CODE_CERTIFICATE_MISSING"
    state="needs_action"
  elif ! soviez_ssl_check_permissions "$cert" "$key"; then
    code="$SOVIEZ_SSL_CODE_CERTIFICATE_PERMISSION_INVALID"
    state="needs_action"
  elif ! soviez_ssl_check_key_match "$cert" "$key"; then
    code="$SOVIEZ_SSL_CODE_CERTIFICATE_KEY_MISMATCH"
    state="needs_action"
  elif ! soviez_ssl_check_hostname "$cert" "$domain"; then
    code="$SOVIEZ_SSL_CODE_CERTIFICATE_HOSTNAME_MISMATCH"
    state="needs_action"
  else
    # Chain / self-signed
    if [[ -n "$chain" && -f "$chain" ]]; then
      if ! openssl verify -CAfile "$chain" "$cert" >/dev/null 2>&1; then
        code="$SOVIEZ_SSL_CODE_CERTIFICATE_CHAIN_INVALID"
        state="needs_action"
      fi
    else
      if ! soviez_ssl_validate_chain "$cert" "${chain:-}" 2>/dev/null; then
        # Map self-signed specifically
        local issuer subject
        issuer="$(openssl x509 -in "$cert" -noout -issuer 2>/dev/null | tr -d ' ' | sed 's/issuer=//')"
        subject="$(openssl x509 -in "$cert" -noout -subject 2>/dev/null | tr -d ' ' | sed 's/subject=//')"
        if [[ "$issuer" == "$subject" ]]; then
          code="$SOVIEZ_SSL_CODE_SELF_SIGNED_NOT_ALLOWED"
        else
          code="$SOVIEZ_SSL_CODE_CERTIFICATE_UNTRUSTED"
        fi
        state="needs_action"
      fi
    fi
  fi

  if [[ "$code" == "OK" ]]; then
    days="$(soviez_ssl_days_until_expiry "$cert")"
    if (( days < 0 )); then
      code="$SOVIEZ_SSL_CODE_CERTIFICATE_EXPIRED"
      state="certificate_expired"
    else
      local lead
      lead="$(soviez_json_get "$rec" renewal_lead_days)"
      [[ -n "$lead" ]] || lead=30
      if (( days <= lead )); then
        state="renewal_window"
      else
        state="healthy"
      fi
      # Warning thresholds (local-first)
      local w
      for w in $SOVIEZ_SSL_WARNING_DAYS; do
        if (( days == w )); then
          :
        fi
      done
    fi
  fi

  # Detect external replacement via digest mismatch
  if [[ "$code" == "OK" || "$state" == "renewal_window" || "$state" == "healthy" ]]; then
    local expected actual
    expected="$(soviez_json_get "$rec" current_certificate_digest)"
    actual="$(openssl x509 -in "$cert" -noout -fingerprint -sha256 2>/dev/null | sed 's/.*=//' | tr -d ':')"
    if [[ -n "$expected" && -n "$actual" && "$expected" != "$actual" ]]; then
      code="CERTIFICATE_EXTERNALLY_REPLACED"
      state="needs_action"
    fi
  fi

  printf '%s\n' "$state"
  printf '%s\n' "$code"
  printf '%s\n' "${days:--}"
}

soviez_ssl_monitor_apply() {
  local env_id="$1"
  local out state code days
  out="$(soviez_ssl_monitor_env "$env_id")"
  state="$(printf '%s\n' "$out" | sed -n '1p')"
  code="$(printf '%s\n' "$out" | sed -n '2p')"
  days="$(printf '%s\n' "$out" | sed -n '3p')"
  local patch
  if [[ "$code" == "OK" ]]; then
    patch="$(python3 - <<PY
import json
print(json.dumps({
  "lifecycle_state": "$state",
  "hostname_verification": "pass",
  "chain_verification": "pass",
  "last_failure_code": None,
  "days_remaining": int("$days") if "$days".lstrip("-").isdigit() or "$days".isdigit() else None
}))
PY
)"
  else
    patch="$(python3 - <<PY
import json
print(json.dumps({
  "lifecycle_state": "$state",
  "last_failure_code": "$code",
  "days_remaining": None
}))
PY
)"
  fi
  soviez_ssl_inventory_patch "$env_id" "$patch"
  printf '%s %s days=%s\n' "$state" "$code" "$days"
}

# --- end ssl/monitor.sh ---

# --- begin ssl/backoff.sh ---
# shellcheck shell=bash
# Phase 12 renewal retry/backoff (owner-approved policy).

# Returns next delay seconds given retry_count (0-based after a failure).
# first 24h: every 6h → retries 0-3 at 6h
# days 2-7: once/day → 24h
# after day 7: every 3 days → 72h
soviez_ssl_backoff_seconds() {
  local retry_count="${1:-0}"
  if (( retry_count < 4 )); then
    printf '%s\n' "$((6 * 3600))"
  elif (( retry_count < 4 + 6 )); then
    printf '%s\n' "$((24 * 3600))"
  else
    printf '%s\n' "$((72 * 3600))"
  fi
}

soviez_ssl_backoff_next_iso() {
  local retry_count="${1:-0}"
  local delay now epoch
  delay="$(soviez_ssl_backoff_seconds "$retry_count")"
  now="$(date -u +%s)"
  epoch=$((now + delay))
  date -u -r "$epoch" +%Y-%m-%dT%H:%M:%SZ 2>/dev/null || date -u -d "@$epoch" +%Y-%m-%dT%H:%M:%SZ
}

soviez_ssl_acquire_env_lock() {
  local env_id="$1"
  local lock
  soviez_ssl_paths_init
  mkdir -p "$(dirname "$(soviez_ssl_lock_dir "$env_id")")"
  lock="$(soviez_ssl_lock_dir "$env_id")"
  if ! mkdir "$lock" 2>/dev/null; then
    soviez_ssl_die "$SOVIEZ_SSL_CODE_RENEWAL_IN_PROGRESS" "Renewal already in progress for $env_id"
  fi
}

soviez_ssl_release_env_lock() {
  local env_id="$1"
  rmdir "$(soviez_ssl_lock_dir "$env_id")" 2>/dev/null || true
}

# --- end ssl/backoff.sh ---

# --- begin ssl/challenge.sh ---
# shellcheck shell=bash
# Phase 12 DNS/ACME challenge lifecycle (signed binding; no DNS-provider mutation).

soviez_ssl_challenge_create() {
  local env_id="$1"
  local domain="$2"
  local host="$3"
  local operation_id="$4"
  local cert_mode="$5"
  local provider="$6"
  local challenge_type="${7:-dns-01}"
  local wildcard_scope="${8:-}"

  soviez_ssl_paths_init
  local challenge_id nonce now exp
  challenge_id="$(soviez_op_generate_id)"
  nonce="$(openssl rand -hex 16)"
  now="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
  exp="$(date -u -v+1H +%Y-%m-%dT%H:%M:%SZ 2>/dev/null || date -u -d '+1 hour' +%Y-%m-%dT%H:%M:%SZ)"

  local path sig_payload
  path="$SOVIEZ_SSL_CHALLENGE_DIR/${challenge_id}.json"
  sig_payload="${env_id}|${domain}|${host}|${operation_id}|${cert_mode}|${provider}|${challenge_type}|${nonce}|${wildcard_scope}"
  local digest
  digest="$(printf '%s' "$sig_payload" | openssl dgst -sha256 | awk '{print $NF}')"

  ENV_ID="$env_id" DOMAIN="$domain" HOST="$host" OP="$operation_id" MODE="$cert_mode" \
    PROV="$provider" CTYPE="$challenge_type" NONCE="$nonce" CID="$challenge_id" \
    WS="$wildcard_scope" NOW="$now" EXP="$exp" DIGEST="$digest" python3 - <<'PY' > "$path"
import json, os
print(json.dumps({
  "challenge_id": os.environ["CID"],
  "environment_id": os.environ["ENV_ID"],
  "domain": os.environ["DOMAIN"],
  "host": os.environ["HOST"],
  "operation_id": os.environ["OP"],
  "certificate_mode": os.environ["MODE"],
  "acme_provider": os.environ["PROV"],
  "challenge_type": os.environ["CTYPE"],
  "nonce": os.environ["NONCE"],
  "issued_at": os.environ["NOW"],
  "expires_at": os.environ["EXP"],
  "wildcard_scope": os.environ.get("WS") or None,
  "binding_digest": os.environ["DIGEST"],
  "status": "pending",
  "consumed": False
}, indent=2))
PY
  chmod 600 "$path"
  # No automatic DNS-provider mutation — operator places token manually if required.
  printf '%s\n' "$challenge_id"
}

soviez_ssl_challenge_load() {
  local challenge_id="$1"
  local path="$SOVIEZ_SSL_CHALLENGE_DIR/${challenge_id}.json"
  [[ -f "$path" ]] || soviez_ssl_die "$SOVIEZ_SSL_CODE_DNS_CHALLENGE_EXPIRED" "Challenge not found"
  cat "$path"
}

soviez_ssl_challenge_verify_binding() {
  local challenge_id="$1"
  local env_id="$2"
  local domain="$3"
  local host="$4"
  local operation_id="$5"
  local rec
  rec="$(soviez_ssl_challenge_load "$challenge_id")"

  local consumed
  consumed="$(soviez_json_get "$rec" consumed)"
  if [[ "$consumed" == "True" || "$consumed" == "true" ]]; then
    soviez_ssl_die "$SOVIEZ_SSL_CODE_DNS_CHALLENGE_REPLAY" "Challenge already consumed"
  fi

  # Expiry check (ISO compare via python)
  local expired
  expired="$(REC="$rec" python3 - <<'PY'
import json, os, time
from datetime import datetime, timezone
rec = json.loads(os.environ["REC"])
exp = datetime.strptime(rec["expires_at"], "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc)
print("1" if datetime.now(timezone.utc) > exp else "0")
PY
)"
  [[ "$expired" == "0" ]] || soviez_ssl_die "$SOVIEZ_SSL_CODE_DNS_CHALLENGE_EXPIRED" "Challenge expired"

  local c_env c_dom c_host c_op
  c_env="$(soviez_json_get "$rec" environment_id)"
  c_dom="$(soviez_json_get "$rec" domain)"
  c_host="$(soviez_json_get "$rec" host)"
  c_op="$(soviez_json_get "$rec" operation_id)"
  if [[ "$c_env" != "$env_id" || "$c_dom" != "$domain" || "$c_host" != "$host" || "$c_op" != "$operation_id" ]]; then
    soviez_ssl_die "$SOVIEZ_SSL_CODE_DNS_CHALLENGE_BINDING_MISMATCH" "Challenge binding mismatch"
  fi

  # Recompute digest
  local nonce ctype mode provider ws expected actual
  nonce="$(soviez_json_get "$rec" nonce)"
  ctype="$(soviez_json_get "$rec" challenge_type)"
  mode="$(soviez_json_get "$rec" certificate_mode)"
  provider="$(soviez_json_get "$rec" acme_provider)"
  ws="$(soviez_json_get "$rec" wildcard_scope 2>/dev/null || true)"
  expected="$(soviez_json_get "$rec" binding_digest)"
  actual="$(printf '%s' "${env_id}|${domain}|${host}|${operation_id}|${mode}|${provider}|${ctype}|${nonce}|${ws}" | openssl dgst -sha256 | awk '{print $NF}')"
  [[ "$expected" == "$actual" ]] || soviez_ssl_die "$SOVIEZ_SSL_CODE_DNS_CHALLENGE_BINDING_MISMATCH" "Challenge tampered"

  # Wildcard scope
  if [[ -n "$ws" && "$ws" != "None" && "$ws" != "null" ]]; then
    case "$domain" in
      ${ws}|*.${ws#\*.}) ;;
      *)
        if [[ "$domain" != "$ws" && "$domain" != *".${ws#\*.}" ]]; then
          soviez_ssl_die "$SOVIEZ_SSL_CODE_WILDCARD_SCOPE_MISMATCH" "Domain outside wildcard scope"
        fi
        ;;
    esac
  fi
}

soviez_ssl_challenge_consume() {
  local challenge_id="$1"
  local path="$SOVIEZ_SSL_CHALLENGE_DIR/${challenge_id}.json"
  local rec
  rec="$(soviez_ssl_challenge_load "$challenge_id")"
  printf '%s\n' "$rec" | python3 -c 'import json,sys; d=json.load(sys.stdin); d["consumed"]=True; d["status"]="consumed"; print(json.dumps(d, indent=2))' > "${path}.tmp"
  mv -f "${path}.tmp" "$path"
  chmod 600 "$path"
}

soviez_ssl_challenge_abort() {
  local challenge_id="$1"
  local path="$SOVIEZ_SSL_CHALLENGE_DIR/${challenge_id}.json"
  [[ -f "$path" ]] || return 0
  local rec
  rec="$(cat "$path")"
  printf '%s\n' "$rec" | python3 -c 'import json,sys; d=json.load(sys.stdin); d["status"]="aborted"; d["consumed"]=True; print(json.dumps(d, indent=2))' > "${path}.tmp"
  mv -f "${path}.tmp" "$path"
}

# --- end ssl/challenge.sh ---

# --- begin ssl/provider.sh ---
# shellcheck shell=bash
# Phase 12 ACME provider abstraction (default Let's Encrypt; fixture for isolated tests).

soviez_ssl_provider_id() {
  printf '%s\n' "${SOVIEZ_SSL_ACME_PROVIDER:-$SOVIEZ_SSL_DEFAULT_ACME_PROVIDER}"
}

soviez_ssl_provider_issue() {
  local provider="$1"
  local domain="$2"
  local out_cert="$3"
  local out_key="$4"
  local out_chain="$5"
  case "$provider" in
    fixture|local_ca|test)
      # Isolated trusted local CA — NOT self-signed leaf without CA.
      local work lines cert key ca
      work="$(mktemp -d "${TMPDIR:-/tmp}/soviez-issue.XXXXXX")"
      lines="$(soviez_ssl_local_issue_fresh "$domain" "$work")"
      cert="$(printf '%s\n' "$lines" | sed -n '1p')"
      key="$(printf '%s\n' "$lines" | sed -n '2p')"
      ca="$(printf '%s\n' "$lines" | sed -n '3p')"
      mkdir -p "$(dirname "$out_cert")"
      cp -f "$cert" "$out_cert"
      cp -f "$key" "$out_key"
      cp -f "$ca" "$out_chain"
      chmod 644 "$out_cert" "$out_chain"
      chmod 600 "$out_key"
      rm -rf "$work"
      ;;
    letsencrypt)
      if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
        # In test mode never call public ACME — use fixture path.
        soviez_ssl_provider_issue fixture "$domain" "$out_cert" "$out_key" "$out_chain"
        return 0
      fi
      # Production path: render certbot contract (actual issuance deferred to host tooling).
      local email="${SOVIEZ_SSL_ACME_EMAIL:-admin@localhost}"
      soviez_ssl_letsencrypt_render "$domain" "$email" > "$(dirname "$out_cert")/certbot.cmd"
      soviez_ssl_die "$SOVIEZ_SSL_CODE_ACME_PROVIDER_UNAVAILABLE" \
        "Let's Encrypt issuance requires certbot on host; use fixture provider in tests"
      ;;
    *)
      soviez_ssl_die "$SOVIEZ_SSL_CODE_ACME_PROVIDER_UNAVAILABLE" "Unknown ACME provider: $provider"
      ;;
  esac
}

# Always issue a fresh cert (bypass local_ca cache) for renewal tests.
soviez_ssl_local_issue_fresh() {
  local domain="$1"
  local cert_dir="$2"
  local ca_dir="$SOVIEZ_ROOT/ssl/local-ca"
  mkdir -p "$cert_dir" "$ca_dir"
  chmod 700 "$cert_dir"
  if [[ ! -f "$ca_dir/ca.crt" ]]; then
    soviez_ssl_local_ca_init >/dev/null
  fi
  openssl genrsa -out "$cert_dir/server.key" 2048 >/dev/null 2>&1
  chmod 600 "$cert_dir/server.key"
  # SAN for hostname match
  printf 'subjectAltName=DNS:%s\n' "$domain" > "$cert_dir/ext.cnf"
  openssl req -new -key "$cert_dir/server.key" -subj "/CN=$domain" -out "$cert_dir/server.csr" >/dev/null 2>&1
  openssl x509 -req -in "$cert_dir/server.csr" -CA "$ca_dir/ca.crt" -CAkey "$ca_dir/ca.key" \
    -CAcreateserial -out "$cert_dir/server.crt" -days 825 -sha256 -extfile "$cert_dir/ext.cnf" >/dev/null 2>&1
  printf '%s\n' "$cert_dir/server.crt" "$cert_dir/server.key" "$ca_dir/ca.crt"
}

soviez_ssl_provider_normalize_error() {
  local provider="$1"
  local stderr="$2"
  case "$stderr" in
    *rate*limit*|*ratelimit*|*too*many*)
      printf '%s\n' "$SOVIEZ_SSL_CODE_ACME_RATE_LIMITED"
      ;;
    *dns*)
      printf '%s\n' "$SOVIEZ_SSL_CODE_DNS_VALIDATION_FAILED"
      ;;
    *)
      if [[ "$provider" == "letsencrypt" ]]; then
        soviez_ssl_letsencrypt_map_error "$stderr"
      else
        printf '%s\n' "$SOVIEZ_SSL_CODE_RENEWAL_FAILED"
      fi
      ;;
  esac
}

# --- end ssl/provider.sh ---

# --- begin ssl/promote.sh ---
# shellcheck shell=bash
# Phase 12 atomic certificate promotion and rollback.

soviez_ssl_validate_replacement() {
  local cert="$1"
  local key="$2"
  local chain="$3"
  local domain="$4"
  local cert_mode="${5:-public}"

  [[ -f "$cert" ]] || soviez_ssl_die "$SOVIEZ_SSL_CODE_CERTIFICATE_MISSING" "replacement cert missing"
  [[ -f "$key" ]] || soviez_ssl_die "$SOVIEZ_SSL_CODE_CERTIFICATE_MISSING" "replacement key missing"
  soviez_ssl_policy_assert_ca "$cert_mode"

  # Self-signed leaf rejection
  local issuer subject
  issuer="$(openssl x509 -in "$cert" -noout -issuer 2>/dev/null | tr -d ' ' | sed 's/issuer=//')"
  subject="$(openssl x509 -in "$cert" -noout -subject 2>/dev/null | tr -d ' ' | sed 's/subject=//')"
  if [[ "$issuer" == "$subject" ]]; then
    soviez_ssl_die "$SOVIEZ_SSL_CODE_SELF_SIGNED_NOT_ALLOWED" "Self-signed replacement rejected"
  fi

  if [[ -n "$chain" && -f "$chain" ]]; then
    openssl verify -CAfile "$chain" "$cert" >/dev/null 2>&1 \
      || soviez_ssl_die "$SOVIEZ_SSL_CODE_CERTIFICATE_CHAIN_INVALID" "Chain validation failed"
  else
    soviez_ssl_validate_chain "$cert" "$chain" 2>/dev/null \
      || soviez_ssl_die "$SOVIEZ_SSL_CODE_CERTIFICATE_UNTRUSTED" "Untrusted certificate"
  fi

  soviez_ssl_check_hostname "$cert" "$domain" \
    || soviez_ssl_die "$SOVIEZ_SSL_CODE_CERTIFICATE_HOSTNAME_MISMATCH" "Hostname mismatch"
  soviez_ssl_check_key_match "$cert" "$key" \
    || soviez_ssl_die "$SOVIEZ_SSL_CODE_CERTIFICATE_KEY_MISMATCH" "Key mismatch"
  soviez_ssl_check_permissions "$cert" "$key" \
    || soviez_ssl_die "$SOVIEZ_SSL_CODE_CERTIFICATE_PERMISSION_INVALID" "Unsafe key permissions"

  local days
  days="$(soviez_ssl_days_until_expiry "$cert")"
  (( days >= 0 )) || soviez_ssl_die "$SOVIEZ_SSL_CODE_CERTIFICATE_EXPIRED" "Replacement already expired"
  # not-yet-valid
  local start epoch_start now
  start="$(openssl x509 -in "$cert" -noout -startdate 2>/dev/null | sed 's/notBefore=//')"
  epoch_start="$(date -u -j -f "%b %d %T %Y %Z" "$start" +%s 2>/dev/null || date -u -d "$start" +%s 2>/dev/null || echo 0)"
  now="$(date -u +%s)"
  if (( epoch_start > now + 60 )); then
    soviez_ssl_die "$SOVIEZ_SSL_CODE_CERTIFICATE_NOT_YET_VALID" "Certificate not yet valid"
  fi
}

soviez_ssl_promote() {
  local env_id="$1"
  local staged_cert="$2"
  local staged_key="$3"
  local staged_chain="$4"
  local upstream="${5:-127.0.0.1:8069}"
  local op_id="${6:-}"

  local rec domain live_cert live_key live_chain cert_mode
  rec="$(soviez_ssl_inventory_read "$env_id")"
  domain="$(soviez_json_get "$rec" domain)"
  live_cert="$(soviez_json_get "$rec" certificate_path)"
  live_key="$(soviez_json_get "$rec" private_key_path)"
  live_chain="$(soviez_json_get "$rec" chain_path 2>/dev/null || true)"
  cert_mode="$(soviez_json_get "$rec" certificate_mode)"

  soviez_ssl_validate_replacement "$staged_cert" "$staged_key" "$staged_chain" "$domain" "$cert_mode"

  # Preserve current working material BEFORE promotion
  local backup_dir
  backup_dir="$(dirname "$live_cert")/previous"
  mkdir -p "$backup_dir"
  chmod 700 "$backup_dir"
  [[ -f "$live_cert" ]] && cp -f "$live_cert" "$backup_dir/server.crt"
  [[ -f "$live_key" ]] && cp -f "$live_key" "$backup_dir/server.key"
  [[ -n "$live_chain" && -f "$live_chain" ]] && cp -f "$live_chain" "$backup_dir/chain.crt" || true
  local prev_digest
  prev_digest="$(soviez_json_get "$rec" current_certificate_digest)"

  # Stage Nginx
  local staged_nginx
  staged_nginx="$(soviez_nginx_render_owned "$env_id" "$domain" "$upstream" "$staged_cert" "$staged_key" "$op_id" https)"
  if ! soviez_nginx_test_config "$staged_nginx"; then
    rm -f "$staged_nginx"
    soviez_ssl_die "$SOVIEZ_SSL_CODE_NGINX_VALIDATION_FAILED" "nginx -t failed"
  fi

  # Promote cert files atomically-ish (copy then replace)
  cp -f "$staged_cert" "${live_cert}.new"
  cp -f "$staged_key" "${live_key}.new"
  mv -f "${live_cert}.new" "$live_cert"
  mv -f "${live_key}.new" "$live_key"
  chmod 644 "$live_cert"
  chmod 600 "$live_key"
  if [[ -n "$staged_chain" && -f "$staged_chain" ]]; then
    local chain_dest="${live_chain:-$(dirname "$live_cert")/chain.crt}"
    cp -f "$staged_chain" "$chain_dest"
    live_chain="$chain_dest"
  fi

  # Promote Nginx + reload
  local final_nginx
  final_nginx="$(soviez_nginx_promote_owned "$staged_nginx")"
  if ! soviez_nginx_reload_safe; then
    # Rollback certs + nginx
    soviez_ssl_rollback "$env_id" "$upstream" || true
    soviez_ssl_die "$SOVIEZ_SSL_CODE_NGINX_RELOAD_FAILED" "Nginx reload failed; rolled back"
  fi

  # HTTPS validation (fixture-friendly)
  if ! soviez_ssl_https_validate_fixture "$domain" "$live_cert"; then
    soviez_ssl_rollback "$env_id" "$upstream" || true
    soviez_ssl_die "$SOVIEZ_SSL_CODE_HTTPS_VALIDATION_FAILED" "HTTPS validation failed; rolled back"
  fi

  local new_digest
  new_digest="$(openssl x509 -in "$live_cert" -noout -fingerprint -sha256 2>/dev/null | sed 's/.*=//' | tr -d ':')"
  local now
  now="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
  soviez_ssl_inventory_patch "$env_id" "$(python3 - <<PY
import json
print(json.dumps({
  "lifecycle_state": "healthy",
  "readiness_state": "ready",
  "current_certificate_digest": "$new_digest",
  "previous_certificate_digest": "$prev_digest",
  "chain_path": "$live_chain" if "$live_chain" else None,
  "last_successful_renewal": "$now",
  "last_failure_code": None,
  "retry_count": 0,
  "operation_id": None
}))
PY
)"
}

soviez_ssl_rollback() {
  local env_id="$1"
  local upstream="${2:-127.0.0.1:8069}"
  local rec live_cert live_key domain
  rec="$(soviez_ssl_inventory_read "$env_id")"
  live_cert="$(soviez_json_get "$rec" certificate_path)"
  live_key="$(soviez_json_get "$rec" private_key_path)"
  domain="$(soviez_json_get "$rec" domain)"
  local backup_dir
  backup_dir="$(dirname "$live_cert")/previous"
  [[ -f "$backup_dir/server.crt" ]] || soviez_ssl_die "$SOVIEZ_SSL_CODE_CERTIFICATE_ROLLBACK_FAILED" "No previous certificate"
  cp -f "$backup_dir/server.crt" "$live_cert"
  cp -f "$backup_dir/server.key" "$live_key"
  chmod 644 "$live_cert"
  chmod 600 "$live_key"
  local final_nginx
  final_nginx="$(soviez_nginx_owned_path "$env_id" "$domain")"
  if [[ -f "${final_nginx}.previous" ]]; then
    soviez_nginx_rollback_owned "$final_nginx"
  else
    # Re-render from restored cert
    local staged
    staged="$(soviez_nginx_render_owned "$env_id" "$domain" "$upstream" "$live_cert" "$live_key" "" https)"
    soviez_nginx_promote_owned "$staged" >/dev/null
    soviez_nginx_reload_safe || true
  fi
  soviez_ssl_inventory_patch "$env_id" '{"lifecycle_state":"healthy","last_failure_code":null}'
}

soviez_ssl_https_validate_fixture() {
  local domain="$1"
  local cert="$2"
  if [[ "${SOVIEZ_FORCE_HTTPS_FAIL:-0}" == "1" ]]; then
    return 1
  fi
  # In test mode, presenting a parseable trusted cert is sufficient.
  openssl x509 -in "$cert" -noout >/dev/null 2>&1
}

# --- end ssl/promote.sh ---

# --- begin ssl/readiness.sh ---
# shellcheck shell=bash
# Phase 12 temporary HTTP + Production readiness gates.

soviez_ssl_readiness_set() {
  local env_id="$1"
  local state="$2"
  case "$state" in
    provisioning|waiting_for_dns|waiting_for_ssl|ready|needs_action|renewal_warning|renewal_failed|certificate_expired|recovery_required) ;;
    *) soviez_ssl_die "$SOVIEZ_SSL_CODE_RECOVERY_REQUIRED" "Invalid readiness state: $state" ;;
  esac
  soviez_ssl_inventory_patch "$env_id" "$(STATE="$state" python3 - <<'PY'
import json, os
print(json.dumps({"readiness_state": os.environ["STATE"]}))
PY
)"
}

soviez_ssl_assert_not_production_ready_message() {
  local readiness="$1"
  if [[ "$readiness" != "ready" ]]; then
    # Must never claim Production Ready
    return 0
  fi
  return 0
}

soviez_ssl_provision_temp_http() {
  local env_id="$1"
  local domain="$2"
  local upstream="${3:-127.0.0.1:8069}"
  local staged
  staged="$(soviez_nginx_render_owned "$env_id" "$domain" "$upstream" "/dev/null" "/dev/null" "" http_temp)"
  # Do not promote as final HTTPS; keep as staged incomplete marker file
  local marker="$SOVIEZ_SSL_NGINX_OWNED_DIR/${env_id}__${domain}.http_temp"
  mv -f "$staged" "$marker"
  soviez_ssl_readiness_set "$env_id" "waiting_for_ssl"
  printf 'INCOMPLETE temporary HTTP only — not Production Ready\n' >&2
  printf '%s\n' "$marker"
}

soviez_ssl_is_production_ready() {
  local env_id="$1"
  local rec readiness lifecycle https_ok
  rec="$(soviez_ssl_inventory_read "$env_id")"
  readiness="$(soviez_json_get "$rec" readiness_state)"
  lifecycle="$(soviez_json_get "$rec" lifecycle_state)"
  [[ "$readiness" == "ready" && ( "$lifecycle" == "healthy" || "$lifecycle" == "ready" ) ]]
}

soviez_ssl_format_status_line() {
  local env_id="$1"
  local rec domain etype lifecycle readiness issuer days mode next fail
  rec="$(soviez_ssl_inventory_read "$env_id")"
  domain="$(soviez_json_get "$rec" domain)"
  etype="$(soviez_json_get "$rec" environment_type)"
  lifecycle="$(soviez_json_get "$rec" lifecycle_state)"
  readiness="$(soviez_json_get "$rec" readiness_state)"
  issuer="$(soviez_json_get "$rec" issuer)"
  days="$(soviez_json_get "$rec" days_remaining 2>/dev/null || echo '?')"
  mode="$(soviez_json_get "$rec" renewal_mode)"
  next="$(soviez_json_get "$rec" next_scheduled_attempt)"
  fail="$(soviez_json_get "$rec" last_failure_code)"
  printf 'env=%s type=%s domain=%s lifecycle=%s readiness=%s issuer=%s days_remaining=%s renewal_mode=%s next_attempt=%s last_failure=%s\n' \
    "$env_id" "$etype" "$domain" "$lifecycle" "$readiness" "${issuer:-unknown}" "${days:--}" "$mode" "${next:-none}" "${fail:-none}"
}

# --- end ssl/readiness.sh ---

# --- begin ssl/engine.sh ---
# shellcheck shell=bash
# Phase 12 durable SSL renewal engine (extends operations foundation).

soviez_ssl_renew_create_op() {
  local env_id="$1"
  local op_id
  op_id="$(soviez_op_create)"
  local state_file
  state_file="$(soviez_operation_state_file "$op_id")"
  soviez_json_merge_file "$state_file" "$(python3 - <<PY
import json
print(json.dumps({
  "kind": "ssl_renewal",
  "environment_id": "$env_id",
  "ssl_state": "renewal_scheduled",
  "state": "renewal_scheduled"
}))
PY
)"
  if declare -F soviez_ops_sync_transition >/dev/null 2>&1; then
    soviez_ops_sync_transition "$op_id" ssl_renewal "$env_id" "renewal_scheduled" "created" "{}" "$state_file" \
      || soviez_ops_sync_mark_pending "$op_id" OPERATION_CANONICAL_SYNC_FAILED
  fi
  printf '%s\n' "$op_id"
}

soviez_ssl_op_mark() {
  local op_id="$1" ssl_state="$2" env_id="${3:-}"
  local state_file
  state_file="$(soviez_operation_state_file "$op_id")"
  [[ -f "$state_file" ]] || return 0
  soviez_json_merge_file "$state_file" "$(SOVIEZ_S="$ssl_state" python3 - <<'PY'
import json, os, time
print(json.dumps({"ssl_state": os.environ["SOVIEZ_S"], "state": os.environ["SOVIEZ_S"],
  "updated_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())}, separators=(",",":")))
PY
)"
  if declare -F soviez_ops_sync_transition >/dev/null 2>&1; then
    [[ -n "$env_id" ]] || env_id="$(soviez_json_get "$(cat "$state_file")" environment_id 2>/dev/null || true)"
    soviez_ops_sync_transition "$op_id" ssl_renewal "$env_id" "$ssl_state" "transition" "{}" "$state_file" \
      || soviez_ops_sync_mark_pending "$op_id" OPERATION_CANONICAL_SYNC_PENDING
  fi
}

soviez_ssl_renew_run() {
  local env_id="$1"
  local force="${2:-0}"
  [[ -n "$env_id" ]] || soviez_ssl_die "$SOVIEZ_SSL_CODE_ENVIRONMENT_SELECTION_REQUIRED" "environment id required"

  soviez_ssl_inventory_validate_record "$env_id"
  local rec mode days_out state code days
  rec="$(soviez_ssl_inventory_read "$env_id")"
  mode="$(soviez_json_get "$rec" renewal_mode)"

  if [[ "$mode" == "manual" && "$force" != "1" ]]; then
    soviez_ssl_die "$SOVIEZ_SSL_CODE_RENEWAL_DISABLED" "Renewal mode is manual; use --ssl-renew with explicit confirm"
  fi
  if [[ "$mode" == "notify_only" && "$force" != "1" ]]; then
    soviez_ssl_monitor_apply "$env_id" >/dev/null
    soviez_ssl_inventory_patch "$env_id" '{"lifecycle_state":"renewal_window"}'
    printf 'notify_only: renewal due reported; no issuance performed\n'
    return 0
  fi

  # Due check unless force
  days_out="$(soviez_ssl_monitor_env "$env_id")"
  state="$(printf '%s\n' "$days_out" | sed -n '1p')"
  code="$(printf '%s\n' "$days_out" | sed -n '2p')"
  days="$(printf '%s\n' "$days_out" | sed -n '3p')"
  if [[ "$force" != "1" && "$state" == "healthy" ]]; then
    soviez_ssl_die "$SOVIEZ_SSL_CODE_RENEWAL_NOT_DUE" "Certificate not in renewal window (days=$days)"
  fi

  soviez_ssl_acquire_env_lock "$env_id"
  local op_id domain provider cert_mode upstream
  op_id="$(soviez_ssl_renew_create_op "$env_id")"
  domain="$(soviez_json_get "$rec" domain)"
  provider="$(soviez_json_get "$rec" acme_provider)"
  cert_mode="$(soviez_json_get "$rec" certificate_mode)"
  upstream="${SOVIEZ_SSL_UPSTREAM:-127.0.0.1:8069}"

  trap 'soviez_ssl_release_env_lock "'"$env_id"'"' RETURN

  soviez_ssl_inventory_patch "$env_id" "$(python3 - <<PY
import json, time
print(json.dumps({
  "lifecycle_state": "renewal_authorizing",
  "operation_id": "$op_id",
  "last_renewal_attempt": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
}))
PY
)"

  # Challenge
  local challenge_id
  challenge_id="$(soviez_ssl_challenge_create "$env_id" "$domain" "$domain" "$op_id" "$cert_mode" "$provider" "dns-01" "")"
  soviez_ssl_inventory_patch "$env_id" "$(CID="$challenge_id" python3 - <<'PY'
import json, os
print(json.dumps({"challenge_id": os.environ["CID"], "lifecycle_state": "waiting_for_dns"}))
PY
)"
  soviez_ssl_op_mark "$op_id" "waiting_for_dns" "$env_id"

  if [[ "${SOVIEZ_SSL_SIMULATE_DNS_TIMEOUT:-0}" == "1" ]]; then
    soviez_ssl_op_mark "$op_id" "retry_scheduled" "$env_id"
    soviez_ssl_renew_fail_retryable "$env_id" "$op_id" "$SOVIEZ_SSL_CODE_DNS_WAIT_TIMEOUT"
    return 1
  fi

  # Fixture: DNS OK immediately in test / when SOVIEZ_STAGE_DNS_OK / SOVIEZ_SSL_DNS_OK
  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" || "${SOVIEZ_SSL_DNS_OK:-1}" == "1" ]]; then
    soviez_ssl_challenge_verify_binding "$challenge_id" "$env_id" "$domain" "$domain" "$op_id"
    soviez_ssl_challenge_consume "$challenge_id"
  else
    soviez_ssl_renew_fail_retryable "$env_id" "$op_id" "$SOVIEZ_SSL_CODE_DNS_WAIT_TIMEOUT"
    return 1
  fi

  # Issue into staging
  local stage_dir
  stage_dir="$SOVIEZ_SSL_STAGING_DIR/${op_id}"
  mkdir -p "$stage_dir"
  chmod 700 "$stage_dir"
  local scert skey schain
  scert="$stage_dir/server.crt"
  skey="$stage_dir/server.key"
  schain="$stage_dir/chain.crt"

  if [[ "${SOVIEZ_SSL_SIMULATE_ACME_FAIL:-0}" == "1" ]]; then
    soviez_ssl_renew_fail_retryable "$env_id" "$op_id" "$SOVIEZ_SSL_CODE_ACME_PROVIDER_UNAVAILABLE"
    return 1
  fi

  local use_provider="$provider"
  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    use_provider="fixture"
  fi
  soviez_ssl_inventory_patch "$env_id" "$(python3 - <<'PY'
import json
print(json.dumps({"lifecycle_state": "certificate_issuing"}))
PY
)"
  soviez_ssl_provider_issue "$use_provider" "$domain" "$scert" "$skey" "$schain"
  soviez_ssl_inventory_patch "$env_id" "$(python3 - <<'PY'
import json
print(json.dumps({"lifecycle_state": "certificate_received"}))
PY
)"

  if [[ "${SOVIEZ_FORCE_HTTPS_FAIL:-0}" == "1" || "${SOVIEZ_SSL_SIMULATE_PROMOTE_FAIL:-0}" == "1" ]]; then
    # Exercise rollback path: validate may pass then https fail
    export SOVIEZ_FORCE_HTTPS_FAIL=1
  fi

  soviez_ssl_inventory_patch "$env_id" "$(python3 - <<'PY'
import json
print(json.dumps({"lifecycle_state": "certificate_promoting"}))
PY
)"
  soviez_ssl_op_mark "$op_id" "certificate_promoting" "$env_id"
  if ! soviez_ssl_promote "$env_id" "$scert" "$skey" "$schain" "$upstream" "$op_id"; then
    soviez_ssl_op_mark "$op_id" "rollback_running" "$env_id"
    soviez_ssl_renew_fail_retryable "$env_id" "$op_id" "$SOVIEZ_SSL_CODE_CERTIFICATE_PROMOTION_FAILED"
    return 1
  fi

  # Mark op complete without Production SM transition (ssl ops use ssl_state).
  soviez_json_merge_file "$(soviez_operation_state_file "$op_id")" \
    '{"ssl_state":"completed","state":"completed"}'
  if declare -F soviez_ops_sync_terminal >/dev/null 2>&1; then
    soviez_ops_sync_terminal "$op_id" ssl_renewal "$env_id" completed "$(soviez_operation_state_file "$op_id")" \
      || soviez_ops_sync_mark_pending "$op_id" OPERATION_TERMINAL_SYNC_INCOMPLETE
  fi
  printf 'ssl_renewal completed op=%s env=%s\n' "$op_id" "$env_id"
}

soviez_ssl_renew_fail_retryable() {
  local env_id="$1"
  local op_id="$2"
  local code="$3"
  local rec retry next
  rec="$(soviez_ssl_inventory_read "$env_id")"
  retry="$(soviez_json_get "$rec" retry_count)"
  [[ -n "$retry" ]] || retry=0
  next="$(soviez_ssl_backoff_next_iso "$retry")"
  retry=$((retry + 1))
  soviez_ssl_inventory_patch "$env_id" "$(python3 - <<PY
import json
print(json.dumps({
  "lifecycle_state": "retry_scheduled",
  "readiness_state": "needs_action",
  "last_failure_code": "$code",
  "retry_count": $retry,
  "next_scheduled_attempt": "$next",
  "operation_id": "$op_id"
}))
PY
)"
  # Preserve current certificate — never delete on failure
  printf 'SSL_DENIAL code=%s message=retry_scheduled next=%s\n' "$code" "$next" >&2
}

soviez_ssl_repair() {
  local env_id="$1"
  [[ -n "$env_id" ]] || soviez_ssl_die "$SOVIEZ_SSL_CODE_ENVIRONMENT_SELECTION_REQUIRED" "environment id required"
  # Repair = force renewal attempt; never stops ERP
  soviez_ssl_renew_run "$env_id" 1
}

soviez_ssl_reattach() {
  local op_id="$1"
  [[ -n "$op_id" ]] || soviez_ssl_die "$SOVIEZ_SSL_CODE_RECOVERY_REQUIRED" "operation id required"
  local state_file env_id ssl_state
  state_file="$(soviez_operation_state_file "$op_id")"
  [[ -f "$state_file" ]] || soviez_ssl_die "$SOVIEZ_SSL_CODE_RECOVERY_REQUIRED" "operation not found"
  local body
  body="$(cat "$state_file")"
  env_id="$(soviez_json_get "$body" environment_id)"
  ssl_state="$(soviez_json_get "$body" ssl_state 2>/dev/null || echo unknown)"
  printf 'reattach op=%s env=%s ssl_state=%s\n' "$op_id" "$env_id" "$ssl_state"
  # Resume by force renew if not completed
  if [[ "$ssl_state" != "completed" ]]; then
    soviez_ssl_renew_run "$env_id" 1
  fi
}

soviez_ssl_try_again() {
  local env_id="$1"
  soviez_ssl_renew_run "$env_id" 1
}

soviez_ssl_abort_safely() {
  local env_id="$1"
  local rec cid
  rec="$(soviez_ssl_inventory_read "$env_id")"
  cid="$(soviez_json_get "$rec" challenge_id)"
  if [[ -n "$cid" && "$cid" != "None" && "$cid" != "null" ]]; then
    soviez_ssl_challenge_abort "$cid"
  fi
  soviez_ssl_release_env_lock "$env_id"
  soviez_ssl_inventory_patch "$env_id" '{"lifecycle_state":"canceled","challenge_id":null,"operation_id":null}'
  printf 'aborted safely; current certificate preserved\n'
}

# --- end ssl/engine.sh ---

# --- begin license/fingerprint.sh ---
# shellcheck shell=bash

soviez_license_compute_fingerprint() {
  local op_id="$1"
  local tenant_id="${2:-unknown}"
  local material="${tenant_id}:${op_id}:$(hostname -f 2>/dev/null || hostname)"
  soviez_sha256_hex "$material"
}

# --- end license/fingerprint.sh ---

# --- begin license/choice.sh ---
# shellcheck shell=bash

soviez_license_choose_activation_method() {
  local requested="${1:-automatic}"
  case "$requested" in
    automatic|manual) printf '%s' "$requested" ;;
    *) soviez_die "$SOVIEZ_ERR_LICENSE" "Invalid activation method: $requested" ;;
  esac
}

# --- end license/choice.sh ---

# --- begin license/activate_orm.sh ---
# shellcheck shell=bash
# Official ORM activation: key never as process argv; never logged; brief 0600 file only.

soviez_license_activate_via_odoo() {
  local web_container="$1"
  local db_name="$2"
  local activation_key="$3"

  if [[ -z "$activation_key" ]]; then
    soviez_die "$SOVIEZ_ERR_LICENSE" "Activation key missing"
  fi

  local stub_script="${SOVIEZ_ODOO_STUB:-}"
  if [[ -n "$stub_script" && -x "$stub_script" ]]; then
    printf '%s\n' "$activation_key" | "$stub_script" "$web_container" "$db_name"
    return 0
  fi

  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    local marker="$SOVIEZ_ROOT/stubs/activation-${db_name}.invoked"
    mkdir -p "$SOVIEZ_ROOT/stubs"
    # Do NOT write the key into the marker.
    printf 'container=%s\ndb=%s\nstdin=1\n' "$web_container" "$db_name" > "$marker"
    return 0
  fi

  # Stage key into container via stdin→file (0600), then call official ORM method.
  local remote_key="/tmp/.soviez_activate_$$"
  if ! printf '%s' "$activation_key" | docker exec -i "$web_container" \
    bash -c "umask 077; cat > '${remote_key}' && chmod 600 '${remote_key}'"; then
    soviez_die "$SOVIEZ_ERR_LICENSE" "Failed to stage activation material"
  fi

  # NOTE: remote_key path is installer-generated (/tmp/.soviez_activate_$$) — not secret content.
  if ! docker exec "$web_container" odoo shell -d "$db_name" --no-http <<EOF
from pathlib import Path
p = Path("${remote_key}")
key = p.read_text(encoding="utf-8").strip()
p.write_text("", encoding="utf-8")
try:
    p.unlink()
except OSError:
    pass
env["soviez.license.mixin"].action_activate_soviez_license(key)
EOF
  then
    docker exec "$web_container" rm -f "$remote_key" 2>/dev/null || true
    soviez_die "$SOVIEZ_ERR_LICENSE" "ORM activation failed"
  fi
  docker exec "$web_container" rm -f "$remote_key" 2>/dev/null || true
}

# --- end license/activate_orm.sh ---

# --- begin license/ack.sh ---
# shellcheck shell=bash

soviez_license_send_activation_ack() {
  local slot_id="$1"
  soviez_slots_activation_ack "$slot_id" >/dev/null
  soviez_log_info "Activation acknowledged to SaaS"
}

# --- end license/ack.sh ---

# --- begin ui/dashboard.sh ---
# shellcheck shell=bash

SOVIEZ_SPINNER_PID=""

soviez_ui_spinner_start() {
  local msg="${1:-Working...}"
  if [[ ! -t 1 ]]; then
    soviez_log_info "$msg"
    return 0
  fi
  (
    local frames=('⠋' '⠙' '⠹' '⠸' '⠼' '⠴' '⠦' '⠧' '⠇' '⠏')
    local i=0
    while true; do
      printf '\r%s %s' "${frames[$i]}" "$msg"
      i=$(( (i + 1) % ${#frames[@]} ))
      sleep 0.1
    done
  ) &
  SOVIEZ_SPINNER_PID=$!
}

soviez_ui_spinner_stop() {
  if [[ -n "${SOVIEZ_SPINNER_PID:-}" ]]; then
    kill "$SOVIEZ_SPINNER_PID" 2>/dev/null || true
    wait "$SOVIEZ_SPINNER_PID" 2>/dev/null || true
    SOVIEZ_SPINNER_PID=""
    printf '\r\033[K'
  fi
}

soviez_ui_dashboard_show() {
  local state="$1"
  soviez_log_info "Operation state: $state"
}

# --- end ui/dashboard.sh ---

# --- begin ui/consent.sh ---
# shellcheck shell=bash

soviez_ui_consent_prompt() {
  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" || "${SOVIEZ_AUTO_CONSENT:-0}" == "1" ]]; then
    soviez_log_info "Connection consent auto-approved (test mode)"
    return 0
  fi
  soviez_log_info "Soviez needs your consent to connect online for license reservation."
  read -r -p "Allow connection? [y/N] " ans
  case "$(printf '%s' "$ans" | tr '[:upper:]' '[:lower:]')" in
    y|yes) return 0 ;;
    *) soviez_die "$SOVIEZ_ERR_GENERIC" "Connection consent denied" ;;
  esac
}

# --- end ui/consent.sh ---

# --- begin operations/state_machine.sh ---
# shellcheck shell=bash

SOVIEZ_NEW_STATES=(
  created
  preflight
  waiting_for_connection_consent
  device_authorization_pending
  device_authorized
  slot_reserved
  release_resolved
  image_pull_authorized
  image_pulled
  tenant_identity_created
  database_provisioned
  container_started
  domain_pending
  waiting_for_dns
  ssl_pending
  instance_provisioned
  fingerprint_bound
  waiting_for_activation_method
  license_issued
  activation_pending
  activated
  manual_activation_pending
  validating
  completed
  completed_activation_pending
  canceled
  failed_retryable
  recovery_required
  failed_terminal
)

soviez_sm_is_valid_state() {
  local state="$1"
  local s
  for s in "${SOVIEZ_NEW_STATES[@]}"; do
    [[ "$s" == "$state" ]] && return 0
  done
  return 1
}

soviez_sm_allowed_next() {
  local from="$1"
  local to="$2"
  case "$from:$to" in
    created:preflight|preflight:waiting_for_connection_consent) return 0 ;;
    waiting_for_connection_consent:device_authorization_pending) return 0 ;;
    device_authorization_pending:device_authorized) return 0 ;;
    device_authorized:slot_reserved) return 0 ;;
    slot_reserved:release_resolved) return 0 ;;
    release_resolved:image_pull_authorized) return 0 ;;
    image_pull_authorized:image_pulled) return 0 ;;
    image_pulled:tenant_identity_created) return 0 ;;
    tenant_identity_created:database_provisioned) return 0 ;;
    database_provisioned:container_started) return 0 ;;
    container_started:domain_pending|container_started:instance_provisioned) return 0 ;;
    domain_pending:waiting_for_dns) return 0 ;;
    waiting_for_dns:ssl_pending) return 0 ;;
    ssl_pending:instance_provisioned) return 0 ;;
    instance_provisioned:fingerprint_bound) return 0 ;;
    fingerprint_bound:waiting_for_activation_method) return 0 ;;
    waiting_for_activation_method:license_issued) return 0 ;;
    license_issued:activation_pending) return 0 ;;
    activation_pending:activated|activation_pending:manual_activation_pending) return 0 ;;
    manual_activation_pending:completed_activation_pending) return 0 ;;
    activated:validating|completed_activation_pending:validating) return 0 ;;
    validating:completed) return 0 ;;
    *:failed_retryable|*:failed_terminal|*:canceled|*:recovery_required) return 0 ;;
    "$from":"$to")
      [[ "$from" == "$to" ]]
      ;;
    *) return 1 ;;
  esac
}

soviez_sm_assert_transition() {
  local from="$1"
  local to="$2"
  soviez_sm_is_valid_state "$from" || soviez_die "$SOVIEZ_ERR_STATE" "Invalid state: $from"
  soviez_sm_is_valid_state "$to" || soviez_die "$SOVIEZ_ERR_STATE" "Invalid state: $to"
  soviez_sm_allowed_next "$from" "$to" || soviez_die "$SOVIEZ_ERR_STATE" "Illegal transition: $from -> $to"
}

soviez_sm_resume_index() {
  local state="$1"
  local i=0
  for s in created preflight waiting_for_connection_consent device_authorization_pending device_authorized slot_reserved release_resolved image_pull_authorized image_pulled tenant_identity_created database_provisioned container_started domain_pending waiting_for_dns ssl_pending instance_provisioned fingerprint_bound waiting_for_activation_method license_issued activation_pending activated manual_activation_pending validating completed completed_activation_pending; do
    [[ "$s" == "$state" ]] && { echo "$i"; return 0; }
    i=$((i + 1))
  done
  echo -1
}

soviez_sm_should_run_step() {
  local current="$1"
  local target="$2"
  local cur_idx tgt_idx
  cur_idx="$(soviez_sm_resume_index "$current")"
  tgt_idx="$(soviez_sm_resume_index "$target")"
  [[ "$cur_idx" -ge 0 && "$tgt_idx" -ge 0 && "$cur_idx" -le "$tgt_idx" ]]
}

# --- end operations/state_machine.sh ---

# --- begin operations/engine.sh ---
# shellcheck shell=bash

soviez_op_generate_id() {
  if command -v uuidgen >/dev/null 2>&1; then
    uuidgen | tr '[:upper:]' '[:lower:]'
  else
    openssl rand -hex 16 | sed -E 's/(.{8})(.{4})(.{4})(.{4})(.{12})/\1-\2-\3-\4-\5/'
  fi
}

soviez_op_create() {
  local op_id="${1:-${SOVIEZ_CLI_OP_ID:-$(soviez_op_generate_id)}}"
  local dir
  dir="$(soviez_operation_dir "$op_id")"
  mkdir -p "$dir"
  chmod 700 "$dir"
  local state_file
  state_file="$(soviez_operation_state_file "$op_id")"
  if [[ ! -f "$state_file" ]]; then
    cat > "$state_file" <<EOF
{
  "operation_id": "$op_id",
  "kind": "new",
  "state": "created",
  "created_at": "$(date -u +%Y-%m-%dT%H:%M:%SZ)",
  "updated_at": "$(date -u +%Y-%m-%dT%H:%M:%SZ)"
}
EOF
    chmod 600 "$state_file"
    soviez_op_append_event "$op_id" "created" "{}"
    if declare -F soviez_ops_sync_create >/dev/null 2>&1; then
      soviez_ops_sync_create "$op_id" new "" "$state_file" || soviez_ops_sync_mark_pending "$op_id" OPERATION_CANONICAL_SYNC_FAILED
    fi
  fi
  printf '%s' "$op_id"
}

soviez_op_read_state() {
  local op_id="$1"
  soviez_json_get "$(cat "$(soviez_operation_state_file "$op_id")")" "state"
}

soviez_op_transition() {
  local op_id="$1"
  local new_state="$2"
  local meta_json="${3:-}"
  [[ -n "$meta_json" ]] || meta_json='{}'
  local state_file
  state_file="$(soviez_operation_state_file "$op_id")"
  local current
  current="$(soviez_op_read_state "$op_id")"
  if [[ "$current" != "$new_state" ]]; then
    soviez_sm_assert_transition "$current" "$new_state"
  fi
  soviez_json_merge_file "$state_file" "$(SOVIEZ_NEW_STATE="$new_state" SOVIEZ_META="$meta_json" python3 - <<'PY'
import json, os, time
patch = {"state": os.environ["SOVIEZ_NEW_STATE"], "updated_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())}
meta = json.loads(os.environ.get("SOVIEZ_META", "{}"))
if meta:
    patch["meta"] = meta
print(json.dumps(patch))
PY
)"
  soviez_op_append_event "$op_id" "$new_state" "$meta_json"
  soviez_op_heartbeat "$op_id"
  if declare -F soviez_ops_sync_transition >/dev/null 2>&1; then
    local env_id
    env_id="$(soviez_json_get "$(cat "$state_file")" environment_id 2>/dev/null || true)"
    if ! soviez_ops_sync_transition "$op_id" new "$env_id" "$new_state" "transition" "$meta_json" "$state_file"; then
      # Non-destructive progress: mark pending; protected steps must check sync before proceeding.
      soviez_ops_sync_mark_pending "$op_id" OPERATION_CANONICAL_SYNC_PENDING
      case "$new_state" in
        tenant_identity_created|database_provisioned|container_started)
          soviez_die "$SOVIEZ_ERR_STATE" "Canonical sync failed before protected step: $new_state"
          ;;
      esac
    fi
  fi
}

soviez_op_append_event() {
  local op_id="$1"
  local event="$2"
  local payload="${3:-}"
  [[ -n "$payload" ]] || payload='{}'
  local events
  events="$(soviez_operation_events_file "$op_id")"
  local redacted
  redacted="$(soviez_redact_text "$payload")"
  SOVIEZ_EVT="$event" SOVIEZ_PAYLOAD="$redacted" python3 - <<'PY' >> "$events"
import json, os, time
print(json.dumps({"ts": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()), "event": os.environ["SOVIEZ_EVT"], "payload": json.loads(os.environ.get("SOVIEZ_PAYLOAD", "{}"))}, separators=(",", ":")))
PY
}

soviez_op_heartbeat() {
  local op_id="$1"
  date -u +%Y-%m-%dT%H:%M:%SZ > "$(soviez_operation_heartbeat_file "$op_id")"
  if declare -F soviez_ops_sync_heartbeat >/dev/null 2>&1; then
    soviez_ops_sync_heartbeat "$op_id" 2>/dev/null || true
  fi
}

soviez_op_acquire_lock() {
  local op_id="$1"
  local lock
  lock="$(soviez_operation_lock_file "$op_id")"
  if ! mkdir "$lock" 2>/dev/null; then
    soviez_die "$SOVIEZ_ERR_STATE" "Operation locked: $op_id"
  fi
}

soviez_op_release_lock() {
  local op_id="$1"
  rmdir "$(soviez_operation_lock_file "$op_id")" 2>/dev/null || true
}

# --- end operations/engine.sh ---

# --- begin operations/systemd_unit.sh ---
# shellcheck shell=bash

soviez_systemd_unit_path() {
  local op_id="$1"
  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    printf '%s/systemd/soviez-worker-%s.service\n' "$SOVIEZ_ROOT" "$op_id"
  else
    printf '/etc/systemd/system/soviez-worker-%s.service\n' "$op_id"
  fi
}

soviez_systemd_render_unit() {
  local op_id="$1"
  local script_path="$2"
  cat <<EOF
[Unit]
Description=Soviez installer worker ${op_id}
After=network.target

[Service]
Type=simple
ExecStart=${script_path} ${op_id}
Restart=on-failure

[Install]
WantedBy=multi-user.target
EOF
}

soviez_systemd_start_worker() {
  local op_id="$1"
  local worker_script="$2"
  local unit
  unit="$(soviez_systemd_unit_path "$op_id")"
  mkdir -p "$(dirname "$unit")"
  soviez_systemd_render_unit "$op_id" "$worker_script" > "$unit"

  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    (
      while true; do
        soviez_op_heartbeat "$op_id"
        sleep 1
      done
    ) &
    echo $! > "$SOVIEZ_ROOT/systemd/worker-${op_id}.pid"
    return 0
  fi

  systemctl daemon-reload
  systemctl enable --now "soviez-worker-${op_id}.service"
}

soviez_systemd_reattach() {
  local op_id="$1"
  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    [[ -f "$(soviez_operation_heartbeat_file "$op_id")" ]]
    return $?
  fi
  systemctl is-active --quiet "soviez-worker-${op_id}.service"
}

# --- end operations/systemd_unit.sh ---

# --- begin stage/codes.sh ---
# shellcheck shell=bash
# Phase 11 Stage denial / exit codes (stable protocol contracts).

SOVIEZ_ERR_STAGE=20

SOVIEZ_STAGE_DENIAL_CODES=(
  NO_MANAGED_PRODUCTION
  PRODUCTION_SELECTION_REQUIRED
  PRODUCTION_UNHEALTHY
  PRODUCTION_IDENTITY_MISMATCH
  LICENSE_BINDING_MISSING
  DEVICE_AUTH_REQUIRED
  DEVICE_REVOKED
  STAGE_ENTITLEMENT_REQUIRED
  STAGE_ENTITLEMENT_EXPIRED
  RESOURCE_ADMISSION_FAILED
  INSUFFICIENT_DISK
  INSUFFICIENT_MEMORY
  STAGE_ID_CONFLICT
  STAGE_DOMAIN_CONFLICT
  STAGE_DB_CONFLICT
  STAGE_CONTAINER_CONFLICT
  STAGE_MAC_CONFLICT
  OPERATION_AUTHORIZATION_FAILED
  TICKET_INVALID
  TICKET_EXPIRED
  TICKET_BINDING_MISMATCH
  TOOLING_UNAVAILABLE
  TOOLING_DIGEST_MISMATCH
  SNAPSHOT_FAILED
  DATABASE_RESTORE_FAILED
  FILESTORE_CLONE_FAILED
  STAGE_RUNTIME_FAILED
  NEUTRALIZATION_FAILED
  DNS_VALIDATION_FAILED
  SSL_ISSUANCE_FAILED
  ORIGIN_CERTIFICATE_FAILED
  REMOTE_COMPLETION_PENDING
  RECOVERY_REQUIRED
  DESTRUCTIVE_CONFIRMATION_REQUIRED
)

soviez_stage_die() {
  local denial="$1"
  shift || true
  soviez_log_error "STAGE_DENIAL=${denial} $*"
  # Prefer structured denial in stderr for non-TTY automation.
  printf '{"ok":false,"denial_code":"%s","message":"%s"}\n' "$denial" "$*" >&2
  exit "$SOVIEZ_ERR_STAGE"
}

# --- end stage/codes.sh ---

# --- begin stage/paths.sh ---
# shellcheck shell=bash
# Stage paths and inventory layout (Phase 11).

soviez_stage_paths_init() {
  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    # Always derive from current SOVIEZ_ROOT so leftover exported path vars
    # from prior shells cannot cross-contaminate disposable fixtures.
    SOVIEZ_STAGES_DIR="$SOVIEZ_ROOT/stages"
    SOVIEZ_STAGE_OPS_DIR="$SOVIEZ_ROOT/ops/stage"
    SOVIEZ_STAGE_HELPER_BIN="${SOVIEZ_STAGE_HELPER_BIN:-}"
    SOVIEZ_STAGE_TOOLING_CACHE="$SOVIEZ_ROOT/cache/stage-tooling"
    SOVIEZ_STAGE_LEDGER="$SOVIEZ_ROOT/stages/consumption.jsonl"
  else
    SOVIEZ_STAGES_DIR="${SOVIEZ_STAGES_DIR:-/var/soviez/stages}"
    SOVIEZ_STAGE_OPS_DIR="${SOVIEZ_STAGE_OPS_DIR:-/var/soviez/ops/stage}"
    SOVIEZ_STAGE_HELPER_BIN="${SOVIEZ_STAGE_HELPER_BIN:-/usr/local/lib/soviez/stage-operation-helper/soviez-stage-helper}"
    SOVIEZ_STAGE_TOOLING_CACHE="${SOVIEZ_STAGE_TOOLING_CACHE:-/var/soviez/cache/stage-tooling}"
    SOVIEZ_STAGE_LEDGER="${SOVIEZ_STAGE_LEDGER:-/var/soviez/stages/consumption.jsonl}"
  fi
  export SOVIEZ_STAGES_DIR SOVIEZ_STAGE_OPS_DIR SOVIEZ_STAGE_HELPER_BIN
  export SOVIEZ_STAGE_TOOLING_CACHE SOVIEZ_STAGE_LEDGER
  mkdir -p "$SOVIEZ_STAGES_DIR" "$SOVIEZ_STAGE_OPS_DIR" "$SOVIEZ_STAGE_TOOLING_CACHE"
  chmod 700 "$SOVIEZ_STAGES_DIR" "$SOVIEZ_STAGE_OPS_DIR" 2>/dev/null || true
}

soviez_stage_inventory_index() {
  printf '%s/index.json\n' "$SOVIEZ_STAGES_DIR"
}

soviez_stage_dir() {
  local stage_id="$1"
  printf '%s/%s\n' "$SOVIEZ_STAGES_DIR" "$stage_id"
}

soviez_stage_identity_file() {
  printf '%s/identity.json\n' "$(soviez_stage_dir "$1")"
}

soviez_stage_origin_cert_file() {
  printf '%s/origin-certificate.json\n' "$(soviez_stage_dir "$1")"
}

soviez_stage_filestore_path() {
  printf '%s/filestore\n' "$(soviez_stage_dir "$1")"
}

soviez_stage_config_path() {
  printf '%s/config\n' "$(soviez_stage_dir "$1")"
}

soviez_stage_secrets_path() {
  printf '%s/secrets\n' "$(soviez_stage_dir "$1")"
}

soviez_stage_snapshot_dir() {
  local op_id="$1"
  printf '%s/%s/snapshots\n' "$SOVIEZ_STAGE_OPS_DIR" "$op_id"
}

soviez_stage_op_dir() {
  printf '%s/%s\n' "$SOVIEZ_STAGE_OPS_DIR" "$1"
}

soviez_stage_op_state_file() {
  printf '%s/state.json\n' "$(soviez_stage_op_dir "$1")"
}

# --- end stage/paths.sh ---

# --- begin stage/state_machine.sh ---
# shellcheck shell=bash
# Stage operation state machine (Phase 11).

SOVIEZ_STAGE_STATES=(
  created
  preflight
  production_selected
  identity_reserved
  resource_admission
  waiting_for_connection_consent
  device_authorized
  entitlement_checked
  operation_authorized
  tooling_authorized
  tooling_pulled
  ticket_verified
  snapshot_preparing
  database_snapshot_created
  filestore_snapshot_created
  database_restoring
  filestore_restoring
  stage_runtime_created
  neutralization_running
  neutralization_validated
  authorization_consumed
  domain_pending
  ssl_pending
  runtime_validating
  origin_certificate_issued
  remote_completion_pending
  completed
  canceled
  failed_retryable
  recovery_required
  failed_terminal
)

soviez_stage_sm_is_valid() {
  local state="$1" s
  for s in "${SOVIEZ_STAGE_STATES[@]}"; do
    [[ "$s" == "$state" ]] && return 0
  done
  return 1
}

soviez_stage_sm_allowed_next() {
  local from="$1" to="$2"
  case "$from:$to" in
    created:preflight) return 0 ;;
    preflight:production_selected) return 0 ;;
    production_selected:identity_reserved) return 0 ;;
    identity_reserved:resource_admission) return 0 ;;
    resource_admission:waiting_for_connection_consent|resource_admission:device_authorized) return 0 ;;
    waiting_for_connection_consent:device_authorized) return 0 ;;
    device_authorized:entitlement_checked) return 0 ;;
    entitlement_checked:operation_authorized) return 0 ;;
    operation_authorized:tooling_authorized) return 0 ;;
    tooling_authorized:tooling_pulled) return 0 ;;
    tooling_pulled:ticket_verified) return 0 ;;
    ticket_verified:snapshot_preparing) return 0 ;;
    snapshot_preparing:database_snapshot_created) return 0 ;;
    database_snapshot_created:filestore_snapshot_created) return 0 ;;
    filestore_snapshot_created:database_restoring) return 0 ;;
    database_restoring:filestore_restoring) return 0 ;;
    filestore_restoring:stage_runtime_created) return 0 ;;
    stage_runtime_created:neutralization_running) return 0 ;;
    neutralization_running:neutralization_validated) return 0 ;;
    neutralization_validated:authorization_consumed) return 0 ;;
    authorization_consumed:domain_pending) return 0 ;;
    domain_pending:ssl_pending) return 0 ;;
    ssl_pending:runtime_validating) return 0 ;;
    runtime_validating:origin_certificate_issued) return 0 ;;
    origin_certificate_issued:remote_completion_pending) return 0 ;;
    remote_completion_pending:completed) return 0 ;;
    *:failed_retryable|*:failed_terminal|*:canceled|*:recovery_required) return 0 ;;
    "$from":"$to") [[ "$from" == "$to" ]] ;;
    *) return 1 ;;
  esac
}

soviez_stage_sm_assert() {
  local from="$1" to="$2"
  soviez_stage_sm_is_valid "$from" || soviez_die "$SOVIEZ_ERR_STATE" "Invalid stage state: $from"
  soviez_stage_sm_is_valid "$to" || soviez_die "$SOVIEZ_ERR_STATE" "Invalid stage state: $to"
  soviez_stage_sm_allowed_next "$from" "$to" || soviez_die "$SOVIEZ_ERR_STATE" "Illegal stage transition: $from -> $to"
}

soviez_stage_sm_resume_index() {
  local state="$1" i=0 s
  for s in "${SOVIEZ_STAGE_STATES[@]}"; do
    [[ "$s" == "canceled" || "$s" == "failed_retryable" || "$s" == "recovery_required" || "$s" == "failed_terminal" ]] && continue
    [[ "$s" == "$state" ]] && { echo "$i"; return 0; }
    i=$((i + 1))
  done
  echo -1
}

soviez_stage_sm_should_run() {
  local current="$1" target="$2"
  local cur_idx tgt_idx
  cur_idx="$(soviez_stage_sm_resume_index "$current")"
  tgt_idx="$(soviez_stage_sm_resume_index "$target")"
  # Strict < so resume does not re-execute a completed checkpoint.
  [[ "$cur_idx" -ge 0 && "$tgt_idx" -ge 0 && "$cur_idx" -lt "$tgt_idx" ]]
}

# --- end stage/state_machine.sh ---

# --- begin stage/inventory.sh ---
# shellcheck shell=bash
# Stage identity, inventory, collision checks (Phase 11).

soviez_stage_sanitize_id() {
  local raw="$1"
  raw="$(printf '%s' "$raw" | tr '[:upper:]' '[:lower:]' | tr -cd 'a-z0-9_-' )"
  [[ "$raw" =~ ^[a-z0-9][a-z0-9_-]{1,62}$ ]] || return 1
  printf '%s' "$raw"
}

soviez_stage_normalize_domain() {
  local d="$1"
  d="$(printf '%s' "$d" | tr '[:upper:]' '[:lower:]' | sed -E 's#^https?://##; s#/.*##; s/\.$//')"
  [[ "$d" =~ ^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$ ]] || return 1
  printf '%s' "$d"
}

soviez_stage_generate_mac() {
  # Locally administered unicast MAC (02:xx:xx:xx:xx:xx), not Production MAC.
  local hex
  hex="$(openssl rand -hex 5)"
  printf '02:%s:%s:%s:%s:%s\n' \
    "${hex:0:2}" "${hex:2:2}" "${hex:4:2}" "${hex:6:2}" "${hex:8:2}"
}

soviez_stage_db_name_for() {
  printf 'stage_%s' "$(printf '%s' "$1" | tr '-' '_')"
}

soviez_stage_container_name_for() {
  printf 'soviez-stage-%s' "$1"
}

soviez_stage_network_name_for() {
  # Dedicated network per Stage (isolation decision — see MULTI_STAGE_RUNTIME_MODEL).
  printf 'soviez-net-stage-%s' "$1"
}

soviez_stage_inventory_corrupt_evidence_path() {
  local idx
  idx="$(soviez_stage_inventory_index)"
  printf '%s.corrupt.%s\n' "$idx" "$(date -u +%Y%m%dT%H%M%SZ)"
}

# Load index JSON; on corrupt content: preserve evidence, clean operator error, non-zero exit.
# Never prints Python traceback to the operator.
soviez_stage_inventory_load_index() {
  local idx
  idx="$(soviez_stage_inventory_index)"
  if [[ ! -f "$idx" ]]; then
    printf '{"stages":[]}\n'
    return 0
  fi
  local raw out
  raw="$(cat "$idx")"
  out="$(mktemp)"
  if ! SOVIEZ_IDX="$raw" python3 - "$out" <<'PY' 2>/dev/null
import json, os, sys
out_path = sys.argv[1]
try:
    data = json.loads(os.environ["SOVIEZ_IDX"])
    if not isinstance(data, dict):
        raise ValueError("index root must be object")
    data.setdefault("stages", [])
    if not isinstance(data["stages"], list):
        raise ValueError("stages must be list")
    open(out_path, "w", encoding="utf-8").write(json.dumps(data) + "\n")
except Exception:
    sys.exit(2)
PY
  then
    rm -f "$out"
    local evidence
    evidence="$(soviez_stage_inventory_corrupt_evidence_path)"
    cp -f "$idx" "$evidence" 2>/dev/null || true
    echo "[error] STAGE_INVENTORY_CORRUPT: stage inventory JSON is unreadable" >&2
    echo "[error] evidence preserved: ${evidence}" >&2
    echo "[error] no automatic repair performed; fix or restore inventory manually" >&2
    return 2
  fi
  cat "$out"
  rm -f "$out"
}

soviez_stage_inventory_atomic_write() {
  local path="$1"
  local content="$2"
  local dir tmp
  dir="$(dirname "$path")"
  mkdir -p "$dir"
  chmod 700 "$dir" 2>/dev/null || true
  tmp="$(mktemp "$dir/.tmp.XXXXXX")"
  printf '%s' "$content" > "$tmp"
  chmod 600 "$tmp"
  mv -f "$tmp" "$path"
}

soviez_stage_inventory_list_ids() {
  local idx_json
  if ! idx_json="$(soviez_stage_inventory_load_index)"; then
    return 2
  fi
  SOVIEZ_IDX="$idx_json" python3 - <<'PY'
import json, os, sys
try:
    data=json.loads(os.environ["SOVIEZ_IDX"])
except Exception:
    print("[error] STAGE_INVENTORY_CORRUPT: cannot parse stage inventory", file=sys.stderr)
    sys.exit(2)
for s in data.get("stages",[]):
    sid=s.get("stage_id") or ""
    if sid:
        print(sid)
PY
}

soviez_stage_inventory_find() {
  local stage_id="$1"
  local file
  file="$(soviez_stage_identity_file "$stage_id")"
  [[ -f "$file" ]] || return 1
  cat "$file"
}

soviez_stage_inventory_assert_unique() {
  local stage_id="$1"
  local domain="$2"
  local db_name="$3"
  local container="$4"
  local mac="$5"
  local id domain_l db c m
  while IFS= read -r id; do
    [[ -z "$id" || "$id" == "$stage_id" ]] && continue
    local ident
    ident="$(soviez_stage_inventory_find "$id" 2>/dev/null || true)"
    [[ -n "$ident" ]] || continue
    domain_l="$(soviez_json_get "$ident" stage_domain 2>/dev/null || true)"
    db="$(soviez_json_get "$ident" stage_db_name 2>/dev/null || true)"
    c="$(soviez_json_get "$ident" stage_container 2>/dev/null || true)"
    m="$(soviez_json_get "$ident" stage_mac 2>/dev/null || true)"
    [[ "$domain_l" == "$domain" ]] && soviez_stage_die STAGE_DOMAIN_CONFLICT "Domain already used: $domain"
    [[ "$db" == "$db_name" ]] && soviez_stage_die STAGE_DB_CONFLICT "DB already used: $db_name"
    [[ "$c" == "$container" ]] && soviez_stage_die STAGE_CONTAINER_CONFLICT "Container already used: $container"
    [[ "$m" == "$mac" ]] && soviez_stage_die STAGE_MAC_CONFLICT "MAC already used: $mac"
  done < <(soviez_stage_inventory_list_ids)

  if [[ -f "$(soviez_stage_identity_file "$stage_id")" ]]; then
    local status
    status="$(soviez_json_get "$(soviez_stage_inventory_find "$stage_id")" lifecycle_status 2>/dev/null || true)"
    if [[ "$status" == "certified" || "$status" == "running" || "$status" == "stopped" ]]; then
      soviez_stage_die STAGE_ID_CONFLICT "Stage already exists: $stage_id"
    fi
  fi
}

soviez_stage_identity_reserve() {
  local stage_id="$1"
  local parent_tenant="$2"
  local license_id="$3"
  local production_fingerprint="$4"
  local source_db_uuid="$5"
  local stage_domain="$6"
  local release_digest="$7"
  local tooling_digest="$8"
  local operation_id="$9"
  local parent_domain="${10:-}"

  stage_id="$(soviez_stage_sanitize_id "$stage_id")" || soviez_stage_die STAGE_ID_CONFLICT "Invalid stage id"
  stage_domain="$(soviez_stage_normalize_domain "$stage_domain")" || soviez_stage_die STAGE_DOMAIN_CONFLICT "Invalid domain"

  local db_name container mac network filestore config secrets
  db_name="$(soviez_stage_db_name_for "$stage_id")"
  container="$(soviez_stage_container_name_for "$stage_id")"
  mac="$(soviez_stage_generate_mac)"
  network="$(soviez_stage_network_name_for "$stage_id")"
  filestore="$(soviez_stage_filestore_path "$stage_id")"
  config="$(soviez_stage_config_path "$stage_id")"
  secrets="$(soviez_stage_secrets_path "$stage_id")"

  soviez_stage_inventory_assert_unique "$stage_id" "$stage_domain" "$db_name" "$container" "$mac"

  mkdir -p "$(soviez_stage_dir "$stage_id")" "$filestore" "$config" "$secrets"
  chmod 700 "$(soviez_stage_dir "$stage_id")" "$secrets"
  chmod 750 "$filestore" "$config"

  local identity
  identity="$(SOVIEZ_SID="$stage_id" SOVIEZ_TENANT="$parent_tenant" SOVIEZ_LIC="$license_id" \
    SOVIEZ_FP="$production_fingerprint" SOVIEZ_UUID="$source_db_uuid" SOVIEZ_DOM="$stage_domain" \
    SOVIEZ_DB="$db_name" SOVIEZ_CTR="$container" SOVIEZ_MAC="$mac" SOVIEZ_NET="$network" \
    SOVIEZ_FS="$filestore" SOVIEZ_CFG="$config" SOVIEZ_SEC="$secrets" \
    SOVIEZ_RD="$release_digest" SOVIEZ_TD="$tooling_digest" SOVIEZ_OP="$operation_id" \
    SOVIEZ_PDOM="$parent_domain" python3 - <<'PY'
import json, os, time
print(json.dumps({
  "stage_id": os.environ["SOVIEZ_SID"],
  "parent_production_tenant_id": os.environ["SOVIEZ_TENANT"],
  "license_id": os.environ["SOVIEZ_LIC"],
  "production_fingerprint": os.environ["SOVIEZ_FP"],
  "source_database_uuid": os.environ["SOVIEZ_UUID"],
  "stage_database_uuid": None,
  "stage_db_name": os.environ["SOVIEZ_DB"],
  "stage_container": os.environ["SOVIEZ_CTR"],
  "stage_mac": os.environ["SOVIEZ_MAC"],
  "stage_network": os.environ["SOVIEZ_NET"],
  "stage_domain": os.environ["SOVIEZ_DOM"],
  "parent_production_domain": os.environ.get("SOVIEZ_PDOM") or None,
  "stage_filestore_path": os.environ["SOVIEZ_FS"],
  "stage_config_path": os.environ["SOVIEZ_CFG"],
  "stage_secrets_path": os.environ["SOVIEZ_SEC"],
  "release_digest": os.environ["SOVIEZ_RD"],
  "tooling_digest": os.environ["SOVIEZ_TD"],
  "operation_id": os.environ["SOVIEZ_OP"],
  "authorization_id": None,
  "origin_certificate_path": None,
  "lifecycle_status": "reserving",
  "health_state": "unknown",
  "retention_created_at": None,
  "retention_expires_at": None,
  "created_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
}, separators=(",", ":")))
PY
)"
  soviez_stage_inventory_atomic_write "$(soviez_stage_identity_file "$stage_id")" "$identity"

  # Update index
  local index_path new_index
  index_path="$(soviez_stage_inventory_index)"
  new_index="$(SOVIEZ_IDX="$(soviez_stage_inventory_load_index)" SOVIEZ_SID="$stage_id" SOVIEZ_DOM="$stage_domain" python3 - <<'PY'
import json, os
idx=json.loads(os.environ["SOVIEZ_IDX"])
stages=idx.setdefault("stages", [])
stages=[s for s in stages if s.get("stage_id")!=os.environ["SOVIEZ_SID"]]
stages.append({"stage_id": os.environ["SOVIEZ_SID"], "stage_domain": os.environ["SOVIEZ_DOM"]})
idx["stages"]=stages
print(json.dumps(idx, separators=(",", ":")))
PY
)"
  soviez_stage_inventory_atomic_write "$index_path" "$new_index"
  printf '%s' "$identity"
}

soviez_stage_inventory_update_field() {
  local stage_id="$1"
  local patch_json="$2"
  local file
  file="$(soviez_stage_identity_file "$stage_id")"
  [[ -f "$file" ]] || soviez_stage_die RECOVERY_REQUIRED "Missing stage identity: $stage_id"
  local merged
  merged="$(SOVIEZ_CUR="$(cat "$file")" SOVIEZ_PATCH="$patch_json" python3 - <<'PY'
import json, os
cur=json.loads(os.environ["SOVIEZ_CUR"])
cur.update(json.loads(os.environ["SOVIEZ_PATCH"]))
print(json.dumps(cur, separators=(",", ":")))
PY
)"
  soviez_stage_inventory_atomic_write "$file" "$merged"
}

# --- end stage/inventory.sh ---

# --- begin stage/admission.sh ---
# shellcheck shell=bash
# Local resource admission — commercial Stage count unlimited; server capacity limited.

soviez_stage_admission_evaluate() {
  # Args: source_db_bytes source_filestore_bytes
  local db_bytes="${1:-0}"
  local fs_bytes="${2:-0}"
  local avail_kb inode_free mem_kb load_1 stage_count
  avail_kb="$(df -Pk "${SOVIEZ_STAGES_DIR:-/var/soviez}" 2>/dev/null | awk 'NR==2{print $4}')"
  avail_kb="${avail_kb:-0}"
  inode_free="$(df -Pi "${SOVIEZ_STAGES_DIR:-/var/soviez}" 2>/dev/null | awk 'NR==2{print $4}')"
  inode_free="${inode_free:-999999}"
  mem_kb="$(awk '/MemAvailable/{print $2}' /proc/meminfo 2>/dev/null || sysctl -n hw.memsize 2>/dev/null | awk '{print int($1/1024)}' || echo 8388608)"
  load_1="$(awk '{print $1}' /proc/loadavg 2>/dev/null || sysctl -n vm.loadavg 2>/dev/null | awk '{print $2}' || echo 0)"
  stage_count="$(soviez_stage_inventory_list_ids 2>/dev/null | grep -c . || true)"
  stage_count="${stage_count:-0}"

  # Projected need: dump + restore + filestore clone + 20% buffer + 2GiB workspace.
  local projected=$(( (db_bytes + fs_bytes) * 25 / 10 + 2147483648 ))
  local avail_bytes=$((avail_kb * 1024))
  local status="ready"
  local denial=""

  if [[ "$avail_bytes" -lt "$projected" ]]; then
    status="blocked"
    denial="INSUFFICIENT_DISK"
  elif [[ "$inode_free" -lt 10000 ]]; then
    status="blocked"
    denial="INSUFFICIENT_DISK"
  elif [[ "$mem_kb" -lt 1048576 ]]; then
    status="blocked"
    denial="INSUFFICIENT_MEMORY"
  elif python3 -c "import sys; sys.exit(0 if float('${load_1:-0}')>16 else 1)" 2>/dev/null; then
    status="warning"
  elif [[ "$stage_count" -ge 50 ]]; then
    status="warning"
  fi

  SOVIEZ_ST="$status" SOVIEZ_DEN="$denial" SOVIEZ_PROJ="$projected" SOVIEZ_AVAIL="$avail_bytes" \
    SOVIEZ_MEM="$mem_kb" SOVIEZ_LOAD="$load_1" SOVIEZ_CNT="$stage_count" python3 - <<'PY'
import json, os
print(json.dumps({
  "status": os.environ["SOVIEZ_ST"],
  "denial_code": os.environ.get("SOVIEZ_DEN") or None,
  "projected_bytes": int(os.environ["SOVIEZ_PROJ"]),
  "available_bytes": int(os.environ["SOVIEZ_AVAIL"]),
  "mem_available_kb": int(float(os.environ["SOVIEZ_MEM"])),
  "load_1": os.environ["SOVIEZ_LOAD"],
  "current_stage_count": int(os.environ["SOVIEZ_CNT"]),
  "commercial_limit": "unlimited",
  "formula": "projected=(db+fs)*2.5 + 2GiB; blocked if avail < projected or MemAvailable < 1GiB",
}, separators=(",", ":")))
PY
}

soviez_stage_admission_require() {
  local result="$1"
  local status
  status="$(soviez_json_get "$result" status)"
  if [[ "$status" == "blocked" ]]; then
    local code
    code="$(soviez_json_get "$result" denial_code)"
    soviez_stage_die "${code:-RESOURCE_ADMISSION_FAILED}" "Local resource admission blocked"
  fi
  if [[ "$status" == "warning" && "${SOVIEZ_STAGE_ADMISSION_FORCE:-0}" != "1" ]]; then
    if [[ ! -t 0 ]]; then
      soviez_stage_die RESOURCE_ADMISSION_FAILED "Admission warning requires confirmation (set SOVIEZ_STAGE_ADMISSION_FORCE=1 for non-TTY)"
    fi
    printf 'Resource admission WARNING. Continue? [y/N] ' >&2
    local ans
    read -r ans || true
    [[ "$ans" =~ ^[Yy]$ ]] || soviez_stage_die RESOURCE_ADMISSION_FAILED "Aborted on admission warning"
  fi
}

# --- end stage/admission.sh ---

# --- begin stage/production.sh ---
# shellcheck shell=bash
# Enumerate locally managed Production tenants (safe metadata only).

soviez_stage_list_productions() {
  # Discovers identity.json files under SOVIEZ_TENANT_DIR and optional multi-tenant layout.
  local root="${SOVIEZ_TENANT_DIR:-/var/soviez/tenant}"
  python3 - "$root" "$SOVIEZ_STAGES_DIR" <<'PY'
import json, os, sys, glob
root, stages_dir = sys.argv[1], sys.argv[2]
cands=[]
paths=glob.glob(os.path.join(root, "**/identity.json"), recursive=True)
if os.path.isfile(os.path.join(root, "identity.json")):
    paths.append(os.path.join(root, "identity.json"))
seen=set()
for p in paths:
    try:
        data=json.load(open(p))
    except Exception:
        continue
    tid=data.get("tenant_id") or data.get("id")
    if not tid or tid in seen: continue
    seen.add(tid)
    stage_count=0
    idx=os.path.join(stages_dir, "index.json")
    if os.path.isfile(idx):
        try:
            for s in json.load(open(idx)).get("stages",[]):
                if s.get("parent_production_tenant_id")==tid or True:
                    # Count stages whose identity parent matches when present
                    idp=os.path.join(stages_dir, s.get("stage_id",""), "identity.json")
                    if os.path.isfile(idp):
                        try:
                            sid=json.load(open(idp))
                            if sid.get("parent_production_tenant_id")==tid:
                                stage_count+=1
                        except Exception:
                            pass
        except Exception:
            pass
    cands.append({
        "tenant_id": tid,
        "domain": data.get("domain") or data.get("public_domain"),
        "license_id": data.get("license_id"),
        "release_version": data.get("release_version") or data.get("digest"),
        "database_name": data.get("db_name") or data.get("database_name"),
        "database_uuid": data.get("database_uuid"),
        "production_fingerprint": data.get("fingerprint") or data.get("production_fingerprint"),
        "container": data.get("container") or data.get("web_container"),
        "container_status": data.get("container_status") or "unknown",
        "stage_count": stage_count,
        "identity_path": p,
        "entitlement_checkable": bool(data.get("license_id")),
    })
print(json.dumps({"productions": cands}, separators=(",", ":")))
PY
}

soviez_stage_select_production() {
  local forced_tenant="${1:-${SOVIEZ_CLI_PRODUCTION_TENANT:-}}"
  local listing
  listing="$(soviez_stage_list_productions)"
  local count
  count="$(SOVIEZ_L="$listing" python3 - <<'PY'
import json,os
print(len(json.loads(os.environ["SOVIEZ_L"]).get("productions",[])))
PY
)"
  if [[ "$count" -eq 0 ]]; then
    # Test/fixture fallback: allow explicit env fixture.
    if [[ -n "${SOVIEZ_STAGE_FIXTURE_PRODUCTION_JSON:-}" ]]; then
      printf '%s' "$SOVIEZ_STAGE_FIXTURE_PRODUCTION_JSON"
      return 0
    fi
    soviez_stage_die NO_MANAGED_PRODUCTION "No locally managed Production instances found"
  fi

  if [[ -n "$forced_tenant" ]]; then
    SOVIEZ_L="$listing" SOVIEZ_T="$forced_tenant" python3 - <<'PY'
import json,os,sys
prods=json.loads(os.environ["SOVIEZ_L"])["productions"]
for p in prods:
    if p.get("tenant_id")==os.environ["SOVIEZ_T"]:
        print(json.dumps(p, separators=(",",":"))); sys.exit(0)
sys.exit(2)
PY
    local rc=$?
    [[ $rc -eq 0 ]] || soviez_stage_die PRODUCTION_SELECTION_REQUIRED "Unknown Production tenant: $forced_tenant"
    return 0
  fi

  if [[ "$count" -eq 1 ]]; then
    SOVIEZ_L="$listing" python3 - <<'PY'
import json,os
print(json.dumps(json.loads(os.environ["SOVIEZ_L"])["productions"][0], separators=(",",":")))
PY
    return 0
  fi

  if [[ ! -t 0 ]]; then
    soviez_stage_die PRODUCTION_SELECTION_REQUIRED "Multiple Productions; pass --production-tenant <id>"
  fi

  echo "Select Production:" >&2
  SOVIEZ_L="$listing" python3 - <<'PY' >&2
import json,os
for i,p in enumerate(json.loads(os.environ["SOVIEZ_L"])["productions"],1):
    print(f"{i}) tenant={p.get('tenant_id')} domain={p.get('domain')} license={p.get('license_id')} stages={p.get('stage_count')}")
PY
  printf 'Enter number: ' >&2
  local n
  read -r n
  SOVIEZ_L="$listing" SOVIEZ_N="$n" python3 - <<'PY'
import json,os,sys
prods=json.loads(os.environ["SOVIEZ_L"])["productions"]
i=int(os.environ["SOVIEZ_N"])-1
if i<0 or i>=len(prods):
    sys.exit(2)
print(json.dumps(prods[i], separators=(",",":")))
PY
  [[ $? -eq 0 ]] || soviez_stage_die PRODUCTION_SELECTION_REQUIRED "Invalid selection"
}

soviez_stage_validate_production() {
  local prod_json="$1"
  local license_id fingerprint db_uuid
  license_id="$(soviez_json_get "$prod_json" license_id 2>/dev/null || true)"
  fingerprint="$(soviez_json_get "$prod_json" production_fingerprint 2>/dev/null || true)"
  db_uuid="$(soviez_json_get "$prod_json" database_uuid 2>/dev/null || true)"
  [[ -n "$license_id" ]] || soviez_stage_die LICENSE_BINDING_MISSING "Production missing license_id"
  [[ -n "$fingerprint" ]] || soviez_stage_die PRODUCTION_IDENTITY_MISMATCH "Production missing fingerprint"
  [[ -n "$db_uuid" ]] || soviez_stage_die PRODUCTION_IDENTITY_MISMATCH "Production missing database_uuid"
  local status
  status="$(soviez_json_get "$prod_json" container_status 2>/dev/null || echo unknown)"
  if [[ "$status" == "unhealthy" || "$status" == "exited" ]]; then
    soviez_stage_die PRODUCTION_UNHEALTHY "Production container status=$status"
  fi
}

# --- end stage/production.sh ---

# --- begin stage/pg.sh ---
# shellcheck shell=bash
# Live PostgreSQL helpers for Stage snapshot/restore (no live PG data-dir copy).

soviez_stage_use_live_pg() {
  [[ "${SOVIEZ_STAGE_USE_LIVE_PG:-0}" == "1" ]] && return 0
  [[ -n "${SOVIEZ_PG_CONTAINER:-}" ]] && return 0
  [[ -n "${SOVIEZ_PG_HOST:-}" ]] && return 0
  return 1
}

soviez_stage_pg_psql() {
  # Args forwarded to psql. Uses container or host connection.
  if [[ -n "${SOVIEZ_PG_CONTAINER:-}" ]] && docker ps --format '{{.Names}}' 2>/dev/null | grep -qx "$SOVIEZ_PG_CONTAINER"; then
    docker exec -i -e PGPASSWORD="${SOVIEZ_PG_PASSWORD:-}" "$SOVIEZ_PG_CONTAINER" \
      psql -v ON_ERROR_STOP=1 -U "${SOVIEZ_PG_USER:-postgres}" "$@"
  else
    PGPASSWORD="${SOVIEZ_PG_PASSWORD:-}" psql -v ON_ERROR_STOP=1 \
      -h "${SOVIEZ_PG_HOST:-127.0.0.1}" \
      -p "${SOVIEZ_PG_PORT:-5432}" \
      -U "${SOVIEZ_PG_USER:-postgres}" \
      "$@"
  fi
}

soviez_stage_pg_dump_fc() {
  # Args: database_name output_file
  local db="$1"
  local out="$2"
  if [[ -n "${SOVIEZ_PG_CONTAINER:-}" ]] && docker ps --format '{{.Names}}' 2>/dev/null | grep -qx "$SOVIEZ_PG_CONTAINER"; then
    docker exec -e PGPASSWORD="${SOVIEZ_PG_PASSWORD:-}" "$SOVIEZ_PG_CONTAINER" \
      pg_dump -Fc -U "${SOVIEZ_PG_USER:-postgres}" -d "$db" > "$out"
  else
    PGPASSWORD="${SOVIEZ_PG_PASSWORD:-}" pg_dump -Fc \
      -h "${SOVIEZ_PG_HOST:-127.0.0.1}" \
      -p "${SOVIEZ_PG_PORT:-5432}" \
      -U "${SOVIEZ_PG_USER:-postgres}" \
      -d "$db" \
      -f "$out"
  fi
}

soviez_stage_pg_createdb() {
  local db="$1"
  if [[ -n "${SOVIEZ_PG_CONTAINER:-}" ]] && docker ps --format '{{.Names}}' 2>/dev/null | grep -qx "$SOVIEZ_PG_CONTAINER"; then
    if docker exec -e PGPASSWORD="${SOVIEZ_PG_PASSWORD:-}" "$SOVIEZ_PG_CONTAINER" \
      psql -At -U "${SOVIEZ_PG_USER:-postgres}" -d postgres -c "SELECT 1 FROM pg_database WHERE datname='${db}'" | grep -q 1; then
      return 1
    fi
    docker exec -e PGPASSWORD="${SOVIEZ_PG_PASSWORD:-}" "$SOVIEZ_PG_CONTAINER" \
      createdb -U "${SOVIEZ_PG_USER:-postgres}" "$db"
  else
    if PGPASSWORD="${SOVIEZ_PG_PASSWORD:-}" psql -At \
      -h "${SOVIEZ_PG_HOST:-127.0.0.1}" -p "${SOVIEZ_PG_PORT:-5432}" \
      -U "${SOVIEZ_PG_USER:-postgres}" -d postgres \
      -c "SELECT 1 FROM pg_database WHERE datname='${db}'" | grep -q 1; then
      return 1
    fi
    PGPASSWORD="${SOVIEZ_PG_PASSWORD:-}" createdb \
      -h "${SOVIEZ_PG_HOST:-127.0.0.1}" -p "${SOVIEZ_PG_PORT:-5432}" \
      -U "${SOVIEZ_PG_USER:-postgres}" "$db"
  fi
}

soviez_stage_pg_restore_fc() {
  local db="$1"
  local dump="$2"
  if [[ -n "${SOVIEZ_PG_CONTAINER:-}" ]] && docker ps --format '{{.Names}}' 2>/dev/null | grep -qx "$SOVIEZ_PG_CONTAINER"; then
    docker exec -i -e PGPASSWORD="${SOVIEZ_PG_PASSWORD:-}" "$SOVIEZ_PG_CONTAINER" \
      pg_restore -U "${SOVIEZ_PG_USER:-postgres}" -d "$db" --no-owner --exit-on-error < "$dump"
  else
    PGPASSWORD="${SOVIEZ_PG_PASSWORD:-}" pg_restore \
      -h "${SOVIEZ_PG_HOST:-127.0.0.1}" -p "${SOVIEZ_PG_PORT:-5432}" \
      -U "${SOVIEZ_PG_USER:-postgres}" \
      -d "$db" --no-owner --exit-on-error "$dump"
  fi
}

soviez_stage_pg_query_at() {
  local db="$1"
  shift
  if [[ -n "${SOVIEZ_PG_CONTAINER:-}" ]] && docker ps --format '{{.Names}}' 2>/dev/null | grep -qx "$SOVIEZ_PG_CONTAINER"; then
    docker exec -e PGPASSWORD="${SOVIEZ_PG_PASSWORD:-}" "$SOVIEZ_PG_CONTAINER" \
      psql -At -U "${SOVIEZ_PG_USER:-postgres}" -d "$db" -c "$*"
  else
    PGPASSWORD="${SOVIEZ_PG_PASSWORD:-}" psql -At \
      -h "${SOVIEZ_PG_HOST:-127.0.0.1}" -p "${SOVIEZ_PG_PORT:-5432}" \
      -U "${SOVIEZ_PG_USER:-postgres}" -d "$db" -c "$*"
  fi
}

soviez_stage_pg_rotate_uuid() {
  # Args: stage_db new_uuid — updates ir_config_parameter-style table when present.
  local db="$1"
  local new_uuid="$2"
  soviez_stage_pg_query_at "$db" \
    "CREATE TABLE IF NOT EXISTS ir_config_parameter (key text PRIMARY KEY, value text);" >/dev/null || true
  soviez_stage_pg_query_at "$db" \
    "INSERT INTO ir_config_parameter(key,value) VALUES ('database.uuid','${new_uuid}')
     ON CONFLICT (key) DO UPDATE SET value=EXCLUDED.value;" >/dev/null || true
  soviez_stage_pg_query_at "$db" \
    "INSERT INTO ir_config_parameter(key,value) VALUES ('database.is_stage','true')
     ON CONFLICT (key) DO UPDATE SET value=EXCLUDED.value;" >/dev/null || true
}

# --- end stage/pg.sh ---

# --- begin stage/snapshot.sh ---
# shellcheck shell=bash
# Consistent Production snapshot via pg_dump (custom format) + filestore copy.
# Never mutates Production DB/filestore. Never copies live PG data directory.

soviez_stage_measure_path_bytes() {
  local path="$1"
  if [[ -d "$path" || -f "$path" ]]; then
    du -sk "$path" 2>/dev/null | awk '{print $1 * 1024}'
  else
    echo 0
  fi
}

soviez_stage_snapshot_db() {
  # Args: op_id source_db_name [pg_container|host]
  local op_id="$1"
  local source_db="$2"
  local snap_dir dump_file
  snap_dir="$(soviez_stage_snapshot_dir "$op_id")"
  mkdir -p "$snap_dir"
  chmod 700 "$snap_dir"
  dump_file="$snap_dir/db.dump"

  if soviez_stage_use_live_pg 2>/dev/null; then
    # Real disposable/live path: custom-format pg_dump — never copy live PG data dir.
    local t0 t1
    t0="$(date +%s)"
    soviez_stage_pg_dump_fc "$source_db" "$dump_file" \
      || soviez_stage_die SNAPSHOT_FAILED "pg_dump -Fc failed"
    t1="$(date +%s)"
    printf '%s' "$((t1 - t0))" > "$snap_dir/db.dump.duration_sec"
    # Validate custom-format header (PGDMP)
    local magic
    magic="$(dd if="$dump_file" bs=5 count=1 2>/dev/null | tr -d '\0' || true)"
    [[ "$magic" == "PGDMP" ]] || soviez_stage_die SNAPSHOT_FAILED "Dump is not PostgreSQL custom format"
  elif [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    # Isolated fixture: write a deterministic "dump" from source fixture SQL or marker.
    local src_fixture="${SOVIEZ_STAGE_FIXTURE_DB_DUMP:-}"
    if [[ -n "$src_fixture" && -f "$src_fixture" ]]; then
      cp -f "$src_fixture" "$dump_file"
    else
      printf 'SOVIEZ_STAGE_PGDUMP_FIXTURE source_db=%s op=%s\n' "$source_db" "$op_id" > "$dump_file"
      # Embed a simple checksummable payload representing business rows.
      printf 'row:partner:Acme\nrow:invoice:100\n' >> "$dump_file"
    fi
  else
    # Prefer docker exec into managed postgres if named; else local pg_dump.
    local pg="${SOVIEZ_PG_CONTAINER:-soviez-db}"
    if docker ps --format '{{.Names}}' 2>/dev/null | grep -qx "$pg"; then
      docker exec "$pg" pg_dump -Fc -d "$source_db" > "$dump_file" \
        || soviez_stage_die SNAPSHOT_FAILED "pg_dump via docker failed"
    else
      pg_dump -Fc -d "$source_db" -f "$dump_file" \
        || soviez_stage_die SNAPSHOT_FAILED "pg_dump failed"
    fi
    local magic
    magic="$(dd if="$dump_file" bs=5 count=1 2>/dev/null | tr -d '\0' || true)"
    [[ "$magic" == "PGDMP" ]] || soviez_stage_die SNAPSHOT_FAILED "Dump is not PostgreSQL custom format"
  fi

  local sum
  sum="$(soviez_sha256_file "$dump_file")"
  printf '%s' "$sum" > "$snap_dir/db.dump.sha256"
  printf '%s' "$dump_file"
}

soviez_stage_snapshot_filestore() {
  local op_id="$1"
  local source_fs="$2"
  local snap_dir dest
  snap_dir="$(soviez_stage_snapshot_dir "$op_id")"
  mkdir -p "$snap_dir"
  dest="$snap_dir/filestore"
  mkdir -p "$dest"

  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]] && ! soviez_stage_use_live_pg; then
    local src_fixture="${SOVIEZ_STAGE_FIXTURE_FILESTORE:-$source_fs}"
    mkdir -p "$src_fixture"
    if [[ ! -f "$src_fixture/.soviez_fs_marker" ]]; then
      printf 'prod-filestore-marker\n' > "$src_fixture/.soviez_fs_marker"
      printf 'blob-a\n' > "$src_fixture/attachment-a.bin"
    fi
    # Copy — never symlink to Production.
    rm -rf "$dest"
    mkdir -p "$dest"
    cp -a "$src_fixture/." "$dest/"
  else
    [[ -d "$source_fs" ]] || soviez_stage_die SNAPSHOT_FAILED "Source filestore missing: $source_fs"
    rm -rf "$dest"
    mkdir -p "$dest"
    if command -v rsync >/dev/null 2>&1; then
      rsync -a --delete "$source_fs"/ "$dest"/ \
        || soviez_stage_die SNAPSHOT_FAILED "filestore rsync failed"
    else
      cp -a "$source_fs"/. "$dest"/ \
        || soviez_stage_die SNAPSHOT_FAILED "filestore copy failed"
    fi
  fi

  # Reject if destination somehow became a symlink to source.
  if [[ -L "$dest" ]]; then
    soviez_stage_die FILESTORE_CLONE_FAILED "Filestore snapshot must not be a symlink"
  fi

  local sum
  sum="$( (cd "$dest" && find . -type f | sort | xargs cat 2>/dev/null | openssl dgst -sha256 | awk '{print $NF}') )"
  printf '%s' "$sum" > "$snap_dir/filestore.sha256"
  # Record source checksum for Production-unchanged proofs in tests.
  if [[ -d "$source_fs" ]]; then
    local src_sum
    src_sum="$( (cd "$source_fs" && find . -type f | sort | xargs cat 2>/dev/null | openssl dgst -sha256 | awk '{print $NF}') )"
    printf '%s' "$src_sum" > "$snap_dir/filestore.source.sha256"
  fi
  printf '%s' "$dest"
}

soviez_sha256_file() {
  local f="$1"
  if command -v shasum >/dev/null 2>&1; then
    shasum -a 256 "$f" | awk '{print $1}'
  else
    sha256sum "$f" | awk '{print $1}'
  fi
}

soviez_sha256_hex() {
  printf '%s' "$1" | openssl dgst -sha256 | awk '{print $NF}'
}

# --- end stage/snapshot.sh ---

# --- begin stage/clone.sh ---
# shellcheck shell=bash
# Restore snapshot into Stage-owned DB and filestore (no Production mutation).

soviez_stage_restore_database() {
  local op_id="$1"
  local stage_db="$2"
  local dump_file="$3"
  [[ -f "$dump_file" ]] || soviez_stage_die DATABASE_RESTORE_FAILED "Missing dump: $dump_file"

  local stage_uuid
  stage_uuid="$(uuidgen 2>/dev/null | tr '[:upper:]' '[:lower:]' || openssl rand -hex 16)"

  if soviez_stage_use_live_pg 2>/dev/null; then
    if ! soviez_stage_pg_createdb "$stage_db"; then
      soviez_stage_die STAGE_DB_CONFLICT "Stage database already exists: $stage_db"
    fi
    local t0 t1
    t0="$(date +%s)"
    soviez_stage_pg_restore_fc "$stage_db" "$dump_file" \
      || soviez_stage_die DATABASE_RESTORE_FAILED "pg_restore failed"
    t1="$(date +%s)"
    printf '%s' "$((t1 - t0))" > "$(soviez_stage_snapshot_dir "$op_id")/db.restore.duration_sec"
    # Never alter Production UUID — rotate only Stage DB parameter.
    soviez_stage_pg_rotate_uuid "$stage_db" "$stage_uuid"
    printf '%s' "$stage_uuid"
    return 0
  fi

  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    local db_dir="$SOVIEZ_ROOT/stage-dbs/$stage_db"
    if [[ -d "$db_dir" && -n "$(ls -A "$db_dir" 2>/dev/null || true)" ]]; then
      soviez_stage_die STAGE_DB_CONFLICT "Non-empty Stage DB fixture exists: $stage_db"
    fi
    mkdir -p "$db_dir"
    cp -f "$dump_file" "$db_dir/restored.dump"
    printf '%s' "$stage_uuid" > "$db_dir/database.uuid"
    printf 'database.is_neutralized=false\n' > "$db_dir/ir_config_parameter.env"
    printf '%s' "$stage_uuid"
    return 0
  fi

  local pg="${SOVIEZ_PG_CONTAINER:-soviez-db}"
  if docker ps --format '{{.Names}}' 2>/dev/null | grep -qx "$pg"; then
    if docker exec "$pg" psql -Atc "SELECT 1 FROM pg_database WHERE datname='${stage_db}'" | grep -q 1; then
      soviez_stage_die STAGE_DB_CONFLICT "Stage database already exists: $stage_db"
    fi
    docker exec "$pg" createdb "$stage_db" \
      || soviez_stage_die DATABASE_RESTORE_FAILED "createdb failed"
    docker exec -i "$pg" pg_restore -d "$stage_db" --no-owner --role=odoo < "$dump_file" \
      || soviez_stage_die DATABASE_RESTORE_FAILED "pg_restore failed"
  else
    createdb "$stage_db" || soviez_stage_die DATABASE_RESTORE_FAILED "createdb failed"
    pg_restore -d "$stage_db" --no-owner "$dump_file" \
      || soviez_stage_die DATABASE_RESTORE_FAILED "pg_restore failed"
  fi
  printf '%s' "$stage_uuid"
}

soviez_stage_restore_filestore() {
  local stage_id="$1"
  local snap_fs="$2"
  local dest
  dest="$(soviez_stage_filestore_path "$stage_id")"
  [[ -d "$snap_fs" ]] || soviez_stage_die FILESTORE_CLONE_FAILED "Missing filestore snapshot"
  # Stage root parent
  mkdir -p "$(dirname "$dest")"
  # Ensure no shared writable link to Production.
  if [[ -L "$dest" ]]; then
    rm -f "$dest"
  fi
  local tmp="${dest}.promoting"
  rm -rf "$tmp" "${dest}.bak"
  mkdir -p "$tmp"
  cp -a "$snap_fs"/. "$tmp"/
  # Atomic-ish promotion: replace dest entirely (never mv into existing dest dir).
  if [[ -e "$dest" ]]; then
    mv "$dest" "${dest}.bak"
  fi
  mv "$tmp" "$dest"
  rm -rf "${dest}.bak" 2>/dev/null || true
  chmod -R u+rwX,g+rX,o-rwx "$dest" 2>/dev/null || true

  if find "$dest" -type l | grep -q .; then
    # Symlinks inside filestore pointing outside stage dir are suspicious.
    while IFS= read -r link; do
      local target
      target="$(readlink "$link")"
      case "$target" in
        /*)
          case "$target" in
            "$dest"/*) ;;
            *) soviez_stage_die FILESTORE_CLONE_FAILED "External symlink in Stage filestore: $link -> $target" ;;
          esac
          ;;
      esac
    done < <(find "$dest" -type l)
  fi
}

# --- end stage/clone.sh ---

# --- begin stage/runtime.sh ---
# shellcheck shell=bash
# Stage runtime isolation: container, network, MAC, labels, config.

soviez_stage_runtime_create() {
  local stage_id="$1"
  local image_ref="${2:-soviez/erp:stage-fixture}"
  local identity
  identity="$(soviez_stage_inventory_find "$stage_id")" || soviez_stage_die STAGE_RUNTIME_FAILED "Missing identity"
  local container network mac db_name domain
  container="$(soviez_json_get "$identity" stage_container)"
  network="$(soviez_json_get "$identity" stage_network)"
  mac="$(soviez_json_get "$identity" stage_mac)"
  db_name="$(soviez_json_get "$identity" stage_db_name)"
  domain="$(soviez_json_get "$identity" stage_domain)"

  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    local marker="$SOVIEZ_ROOT/stubs/stage-runtime-${stage_id}.started"
    mkdir -p "$SOVIEZ_ROOT/stubs"
    cat > "$marker" <<EOF
container=${container}
network=${network}
mac=${mac}
db_filter=^${db_name}$
domain=${domain}
image=${image_ref}
soviez.role=stage
soviez.stage_id=${stage_id}
EOF
    # Ensure dedicated network marker (isolation)
    mkdir -p "$SOVIEZ_ROOT/stubs/networks"
    printf 'network=%s\n' "$network" > "$SOVIEZ_ROOT/stubs/networks/${network}.created"
    printf '%s' "$container"
    return 0
  fi

  if ! docker network inspect "$network" >/dev/null 2>&1; then
    docker network create \
      --label "soviez.role=stage" \
      --label "soviez.stage_id=${stage_id}" \
      "$network" >/dev/null \
      || soviez_stage_die STAGE_RUNTIME_FAILED "Failed to create network $network"
  fi

  if docker ps -a --format '{{.Names}}' | grep -qx "$container"; then
    soviez_stage_die STAGE_CONTAINER_CONFLICT "Container exists: $container"
  fi

  docker run -d \
    --name "$container" \
    --mac-address "$mac" \
    --network "$network" \
    --label "soviez.role=stage" \
    --label "soviez.stage_id=${stage_id}" \
    --label "soviez.stage_domain=${domain}" \
    --restart unless-stopped \
    -e "SOVIEZ_STAGE=1" \
    -e "SOVIEZ_STAGE_ID=${stage_id}" \
    -e "DB_FILTER=^${db_name}$" \
    "$image_ref" >/dev/null \
    || soviez_stage_die STAGE_RUNTIME_FAILED "docker run failed for $container"

  printf '%s' "$container"
}

soviez_stage_runtime_start() {
  local stage_id="$1"
  local identity container
  identity="$(soviez_stage_inventory_find "$stage_id")" || soviez_stage_die RECOVERY_REQUIRED "Unknown stage"
  container="$(soviez_json_get "$identity" stage_container)"
  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    touch "$SOVIEZ_ROOT/stubs/stage-runtime-${stage_id}.running"
    soviez_stage_inventory_update_field "$stage_id" '{"lifecycle_status":"running","health_state":"healthy"}'
    return 0
  fi
  docker start "$container" >/dev/null
  soviez_stage_inventory_update_field "$stage_id" '{"lifecycle_status":"running"}'
}

soviez_stage_runtime_stop() {
  local stage_id="$1"
  local identity container
  identity="$(soviez_stage_inventory_find "$stage_id")" || soviez_stage_die RECOVERY_REQUIRED "Unknown stage"
  container="$(soviez_json_get "$identity" stage_container)"
  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    rm -f "$SOVIEZ_ROOT/stubs/stage-runtime-${stage_id}.running"
    touch "$SOVIEZ_ROOT/stubs/stage-runtime-${stage_id}.stopped"
    soviez_stage_inventory_update_field "$stage_id" '{"lifecycle_status":"stopped","health_state":"stopped"}'
    return 0
  fi
  docker stop "$container" >/dev/null
  soviez_stage_inventory_update_field "$stage_id" '{"lifecycle_status":"stopped"}'
}

soviez_stage_runtime_remove_owned() {
  # Removes only Stage-owned container/network markers. Never Production.
  local stage_id="$1"
  local identity container network
  identity="$(soviez_stage_inventory_find "$stage_id" 2>/dev/null || true)"
  [[ -n "$identity" ]] || return 0
  container="$(soviez_json_get "$identity" stage_container)"
  network="$(soviez_json_get "$identity" stage_network)"
  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    rm -f "$SOVIEZ_ROOT/stubs/stage-runtime-${stage_id}".*
    rm -f "$SOVIEZ_ROOT/stubs/networks/${network}.created"
    return 0
  fi
  docker rm -f "$container" >/dev/null 2>&1 || true
  docker network rm "$network" >/dev/null 2>&1 || true
}

# --- end stage/runtime.sh ---

# --- begin stage/neutralization.sh ---
# shellcheck shell=bash
# Neutralization orchestration + helper certification (Phase 11).
# Bash applies infra/config controls; helper certifies — Bash Boolean alone cannot certify.

soviez_stage_neutralize_apply() {
  local stage_id="$1"
  local identity db_name
  identity="$(soviez_stage_inventory_find "$stage_id")"
  db_name="$(soviez_json_get "$identity" stage_db_name)"

  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    local db_dir="$SOVIEZ_ROOT/stage-dbs/$db_name"
    mkdir -p "$db_dir"
    cat > "$db_dir/neutralization.env" <<EOF
outgoing_email_disabled=true
sms_disabled=true
payment_providers_disabled=true
webhooks_disabled=true
external_cron_isolated=true
production_url_callbacks_blocked=true
stage_identity_marker_set=true
database_is_neutralized_flag=true
EOF
    printf 'database.is_neutralized=true\n' > "$db_dir/ir_config_parameter.env"
    # Write Stage identity marker
    printf 'soviez.stage_id=%s\n' "$stage_id" >> "$db_dir/ir_config_parameter.env"
    return 0
  fi

  # Production path: invoke Odoo CLI neutralize inside Stage container when available.
  local container
  container="$(soviez_json_get "$identity" stage_container)"
  if docker ps --format '{{.Names}}' | grep -qx "$container"; then
    docker exec "$container" soviez-bin neutralize --stage-id "$stage_id" \
      || soviez_stage_die NEUTRALIZATION_FAILED "soviez-bin neutralize failed"
  else
    soviez_stage_die NEUTRALIZATION_FAILED "Stage container not running for neutralization"
  fi
}

soviez_stage_neutralize_controls_json() {
  local stage_id="$1"
  local identity db_name
  identity="$(soviez_stage_inventory_find "$stage_id")"
  db_name="$(soviez_json_get "$identity" stage_db_name)"

  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    local envf="$SOVIEZ_ROOT/stage-dbs/$db_name/neutralization.env"
    if [[ ! -f "$envf" ]]; then
      printf '{"outgoing_email_disabled":false}\n'
      return 0
    fi
    python3 - "$envf" <<'PY'
import json,sys
controls={}
for line in open(sys.argv[1]):
    line=line.strip()
    if not line or "=" not in line: continue
    k,v=line.split("=",1)
    controls[k]=(v.strip().lower()=="true")
print(json.dumps(controls))
PY
    return 0
  fi
  # Non-test: assume neutralize applied all required controls when CLI succeeded.
  cat <<'EOF'
{"outgoing_email_disabled":true,"sms_disabled":true,"payment_providers_disabled":true,"webhooks_disabled":true,"external_cron_isolated":true,"production_url_callbacks_blocked":true,"stage_identity_marker_set":true,"database_is_neutralized_flag":true}
EOF
}

soviez_stage_helper_resolve() {
  if [[ -n "${SOVIEZ_STAGE_HELPER_BIN:-}" && -x "${SOVIEZ_STAGE_HELPER_BIN}" ]]; then
    printf '%s' "$SOVIEZ_STAGE_HELPER_BIN"
    return 0
  fi
  local root="${SOVIEZ_SH_ROOT:-}"
  if [[ -z "$root" || ! -d "$root/services/stage-operation-helper" ]]; then
    root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." 2>/dev/null && pwd || true)"
  fi
  # Prefer built JS; fall back to TS source via tsx.
  local cand
  for cand in \
    "${root}/services/stage-operation-helper/dist/src/cli.js" \
    "${root}/services/stage-operation-helper/dist/cli.js" \
    "${root}/services/stage-operation-helper/src/cli.ts" \
    "${SOVIEZ_SH_ROOT:-}/services/stage-operation-helper/dist/src/cli.js" \
    "${SOVIEZ_SH_ROOT:-}/services/stage-operation-helper/dist/cli.js" \
    "${SOVIEZ_SH_ROOT:-}/services/stage-operation-helper/src/cli.ts"
  do
    if [[ -f "$cand" ]]; then
      printf '%s' "$cand"
      return 0
    fi
  done
  return 1
}

soviez_stage_helper_run_verify() {
  local ticket_file="$1"
  local keys_file="$2"
  local expect_file="$3"
  local ledger="${4:-$SOVIEZ_STAGE_LEDGER}"
  local helper
  helper="$(soviez_stage_helper_resolve)" || soviez_stage_die TOOLING_UNAVAILABLE "Stage helper not found"

  local out
  if [[ "$helper" == *.ts ]]; then
    out="$(cd "$(dirname "$helper")/.." && npx --yes tsx "$helper" verify --ticket "$ticket_file" --keys "$keys_file" --expect "$expect_file" --ledger "$ledger")" \
      || soviez_stage_die TICKET_INVALID "Helper verify failed"
  elif [[ "$helper" == *.js ]]; then
    out="$(node "$helper" verify --ticket "$ticket_file" --keys "$keys_file" --expect "$expect_file" --ledger "$ledger")" \
      || soviez_stage_die TICKET_INVALID "Helper verify failed"
  else
    out="$("$helper" verify --ticket "$ticket_file" --keys "$keys_file" --expect "$expect_file" --ledger "$ledger")" \
      || soviez_stage_die TICKET_INVALID "Helper verify failed"
  fi
  printf '%s' "$out"
}

soviez_stage_helper_run_neutralize() {
  local claims_file="$1"
  local controls_file="$2"
  local cert_out="$3"
  local helper
  helper="$(soviez_stage_helper_resolve)" || soviez_stage_die TOOLING_UNAVAILABLE "Stage helper not found"
  local out
  if [[ "$helper" == *.ts ]]; then
    out="$(cd "$(dirname "$helper")/.." && npx --yes tsx "$helper" neutralize --claims "$claims_file" --controls "$controls_file" --cert-out "$cert_out")" \
      || soviez_stage_die NEUTRALIZATION_FAILED "Helper neutralize failed"
  elif [[ "$helper" == *.js ]]; then
    out="$(node "$helper" neutralize --claims "$claims_file" --controls "$controls_file" --cert-out "$cert_out")" \
      || soviez_stage_die NEUTRALIZATION_FAILED "Helper neutralize failed"
  else
    out="$("$helper" neutralize --claims "$claims_file" --controls "$controls_file" --cert-out "$cert_out")" \
      || soviez_stage_die NEUTRALIZATION_FAILED "Helper neutralize failed"
  fi
  local ok
  ok="$(soviez_json_get "$out" ok 2>/dev/null || echo false)"
  [[ "$ok" == "true" || "$ok" == "True" ]] || soviez_stage_die NEUTRALIZATION_FAILED "Neutralization certification denied"
  printf '%s' "$out"
}

# --- end stage/neutralization.sh ---

# --- begin stage/domain_ssl.sh ---
# shellcheck shell=bash
# Stage domain + SSL (mandatory trusted chain; self-signed rejected as final PASS).

soviez_stage_domain_validate_dns() {
  local domain="$1"
  local expected_ip="${2:-}"
  domain="$(soviez_stage_normalize_domain "$domain")" || soviez_stage_die DNS_VALIDATION_FAILED "Invalid domain syntax"

  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    # Fixture: allow domains under .test / .localhost or SOVIEZ_STAGE_DNS_OK=1
    if [[ "${SOVIEZ_STAGE_DNS_OK:-1}" == "1" ]]; then
      printf '{"ok":true,"domain":"%s","mode":"fixture"}\n' "$domain"
      return 0
    fi
    soviez_stage_die DNS_VALIDATION_FAILED "DNS fixture denied"
  fi

  local resolved
  resolved="$(getent ahostsv4 "$domain" 2>/dev/null | awk '{print $1; exit}' || true)"
  [[ -n "$resolved" ]] || soviez_stage_die DNS_VALIDATION_FAILED "A/AAAA resolution failed for $domain"
  if [[ -n "$expected_ip" && "$resolved" != "$expected_ip" ]]; then
    soviez_stage_die DNS_VALIDATION_FAILED "DNS $domain -> $resolved expected $expected_ip"
  fi
  printf '{"ok":true,"domain":"%s","resolved":"%s"}\n' "$domain" "$resolved"
}

soviez_stage_ssl_issue_and_validate() {
  local stage_id="$1"
  local domain="$2"
  local cfg
  cfg="$(soviez_stage_config_path "$stage_id")"
  mkdir -p "$cfg/ssl"
  local cert="$cfg/ssl/fullchain.pem"
  local key="$cfg/ssl/privkey.pem"
  local ca="${SOVIEZ_STAGE_TRUSTED_CA:-}"

  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    # Use local CA fixture — never accept self-signed as final PASS.
    if declare -F soviez_ssl_local_issue_cert >/dev/null 2>&1; then
      local issued
      issued="$(soviez_ssl_local_issue_cert "$domain")"
      local leaf keyf caf
      leaf="$(printf '%s\n' "$issued" | sed -n '1p')"
      keyf="$(printf '%s\n' "$issued" | sed -n '2p')"
      caf="$(printf '%s\n' "$issued" | sed -n '3p')"
      cp -f "$leaf" "$cert"
      cp -f "$keyf" "$key"
      ca="$caf"
    else
      # Minimal local CA + leaf for tests.
      local ca_dir="$SOVIEZ_ROOT/ssl-ca"
      mkdir -p "$ca_dir"
      if [[ ! -f "$ca_dir/ca.crt" ]]; then
        openssl req -x509 -newkey rsa:2048 -nodes -keyout "$ca_dir/ca.key" -out "$ca_dir/ca.crt" \
          -days 3650 -subj "/CN=Soviez Stage Test CA" >/dev/null 2>&1
      fi
      openssl req -newkey rsa:2048 -nodes -keyout "$key" -out "$cfg/ssl/req.csr" \
        -subj "/CN=$domain" >/dev/null 2>&1
      openssl x509 -req -in "$cfg/ssl/req.csr" -CA "$ca_dir/ca.crt" -CAkey "$ca_dir/ca.key" \
        -CAcreateserial -out "$cert" -days 825 >/dev/null 2>&1
      ca="$ca_dir/ca.crt"
    fi
    chmod 600 "$key"
    chmod 644 "$cert"
    soviez_ssl_validate_chain "$cert" "$ca"
    if [[ -z "$ca" ]]; then
      soviez_stage_die SSL_ISSUANCE_FAILED "Trusted CA required; self-signed not accepted"
    fi
    mkdir -p "$cfg/nginx"
    cat > "$cfg/nginx/${domain}.conf" <<EOF
# Stage nginx stub for ${domain}
server_name ${domain};
ssl_certificate ${cert};
ssl_certificate_key ${key};
EOF
    printf '%s\n' "${stage_id}" > "$cfg/nginx.owned"
    chmod 640 "$cfg/nginx.owned" 2>/dev/null || true
    printf '{"ok":true,"domain":"%s","cert":"%s","trusted":true}\n' "$domain" "$cert"
    return 0
  fi

  # Production: prefer Let's Encrypt path if available.
  if declare -F soviez_ssl_letsencrypt_issue >/dev/null 2>&1; then
    soviez_ssl_letsencrypt_issue "$domain" "$cert" "$key" \
      || soviez_stage_die SSL_ISSUANCE_FAILED "Let's Encrypt issuance failed"
  else
    soviez_stage_die SSL_ISSUANCE_FAILED "No SSL issuer available"
  fi
  chmod 600 "$key"
  soviez_ssl_validate_chain "$cert" ""
  printf '{"ok":true,"domain":"%s","cert":"%s"}\n' "$domain" "$cert"
}

# --- end stage/domain_ssl.sh ---

# --- begin stage/checkpoint.sh ---
# shellcheck shell=bash
# Test-only pause/fault hooks for disconnect/resume certification.
# Production builds never sleep; hooks activate only when SOVIEZ_TEST_MODE=1
# and SOVIEZ_STAGE_PAUSE_AT / SOVIEZ_STAGE_FAULT_AT are set.

soviez_stage_checkpoint() {
  local op_id="$1"
  local state="$2"
  local hb
  hb="$(soviez_stage_op_dir "$op_id")/heartbeat"
  date -u +%Y-%m-%dT%H:%M:%SZ > "$hb"
  chmod 600 "$hb" 2>/dev/null || true

  if [[ "${SOVIEZ_TEST_MODE:-0}" != "1" ]]; then
    return 0
  fi

  local mark
  mark="$(soviez_stage_op_dir "$op_id")/checkpoint_${state}"
  printf '%s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)" > "$mark"

  if [[ -n "${SOVIEZ_STAGE_FAULT_AT:-}" && "${SOVIEZ_STAGE_FAULT_AT}" == "$state" ]]; then
    soviez_stage_op_transition "$op_id" failed_retryable '{"fault":"injected"}' 2>/dev/null || true
    soviez_stage_die RECOVERY_REQUIRED "Injected fault at $state"
  fi

  if [[ -n "${SOVIEZ_STAGE_PAUSE_AT:-}" && "${SOVIEZ_STAGE_PAUSE_AT}" == "$state" ]]; then
    local pause_file resume_file
    pause_file="$(soviez_stage_op_dir "$op_id")/paused"
    resume_file="$(soviez_stage_op_dir "$op_id")/resume"
    rm -f "$resume_file"
    printf '%s\n' "$state" > "$pause_file"
    chmod 600 "$pause_file"
    soviez_log_info "Paused at $state (test hook); waiting for resume file"
    local waited=0
    local max_wait="${SOVIEZ_STAGE_PAUSE_MAX_SEC:-120}"
    while [[ ! -f "$resume_file" ]]; do
      sleep 0.2
      waited=$((waited + 1))
      if [[ $waited -gt $((max_wait * 5)) ]]; then
        soviez_stage_die RECOVERY_REQUIRED "Pause timeout at $state"
      fi
      # Allow controller kill: if SOVIEZ_STAGE_PAUSE_EXIT_CONTROLLER=1, exit process while paused.
      if [[ "${SOVIEZ_STAGE_PAUSE_EXIT_CONTROLLER:-0}" == "1" && -f "$(soviez_stage_op_dir "$op_id")/controller_exit" ]]; then
        soviez_log_info "Controller exit requested while paused at $state"
        exit 0
      fi
    done
    rm -f "$resume_file" "$pause_file"
    soviez_log_info "Resumed from pause at $state"
  fi
}

soviez_stage_worker_script_path() {
  local op_id="$1"
  printf '%s/worker.sh\n' "$(soviez_stage_op_dir "$op_id")"
}

soviez_stage_worker_pid_file() {
  local op_id="$1"
  printf '%s/worker.pid\n' "$(soviez_stage_op_dir "$op_id")"
}

soviez_stage_start_durable_worker() {
  # Start a durable Stage create worker that survives controller disconnect.
  local op_id="$1"
  local script_path installer unit
  script_path="$(soviez_stage_worker_script_path "$op_id")"
  installer="${SOVIEZ_STAGE_INSTALLER_PATH:-${SOVIEZ_SH_ROOT}/dist/soviez.sh}"
  mkdir -p "$(soviez_stage_op_dir "$op_id")"
  cat > "$script_path" <<EOF
#!/usr/bin/env bash
set -euo pipefail
# shellcheck source=/dev/null
source "$installer"
ENVF="$(soviez_stage_op_dir "$op_id")/worker.env"
if [[ -f "\$ENVF" ]]; then
  set -a
  # shellcheck disable=SC1090
  source "\$ENVF"
  set +a
fi
# Re-assert identity after sourcing modules (module tops reset CLI globals).
export SOVIEZ_TEST_MODE="\${SOVIEZ_TEST_MODE:-1}"
export SOVIEZ_CLI_COMMAND=stage
export SOVIEZ_CLI_OP_ID="$op_id"
export SOVIEZ_STAGE_WORKER_INNER=1
export SOVIEZ_STAGE_DURABLE_WORKER=0
soviez_paths_init
soviez_stage_paths_init
soviez_cmd_stage_create_run
EOF
  chmod 700 "$script_path"

  # Render systemd unit (test or real).
  unit="$(soviez_systemd_unit_path "$op_id")"
  mkdir -p "$(dirname "$unit")"
  soviez_systemd_render_unit "$op_id" "$script_path" > "$unit"

  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    mkdir -p "$SOVIEZ_ROOT/systemd"
    nohup bash "$script_path" > "$(soviez_stage_op_dir "$op_id")/worker.log" 2>&1 &
    local pid=$!
    echo "$pid" > "$(soviez_stage_worker_pid_file "$op_id")"
    echo "$pid" > "$SOVIEZ_ROOT/systemd/worker-${op_id}.pid"
    # Heartbeat companion
    (
      while kill -0 "$pid" 2>/dev/null; do
        date -u +%Y-%m-%dT%H:%M:%SZ > "$(soviez_stage_op_dir "$op_id")/heartbeat"
        sleep 1
      done
    ) &
    echo $! > "$SOVIEZ_ROOT/systemd/heartbeat-${op_id}.pid"
    return 0
  fi

  systemctl daemon-reload
  systemctl enable --now "soviez-worker-${op_id}.service"
}

soviez_stage_worker_alive() {
  local op_id="$1"
  local pf
  pf="$(soviez_stage_worker_pid_file "$op_id")"
  if [[ -f "$pf" ]]; then
    kill -0 "$(cat "$pf")" 2>/dev/null && return 0
  fi
  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" && -f "$SOVIEZ_ROOT/systemd/worker-${op_id}.pid" ]]; then
    kill -0 "$(cat "$SOVIEZ_ROOT/systemd/worker-${op_id}.pid")" 2>/dev/null && return 0
  fi
  return 1
}

# --- end stage/checkpoint.sh ---

# --- begin stage/engine.sh ---
# shellcheck shell=bash
# Stage operation engine helpers (durable state under SOVIEZ_STAGE_OPS_DIR).

soviez_stage_op_create() {
  local op_id="${1:-$(soviez_op_generate_id)}"
  local dir
  dir="$(soviez_stage_op_dir "$op_id")"
  mkdir -p "$dir"
  chmod 700 "$dir"
  local state_file
  state_file="$(soviez_stage_op_state_file "$op_id")"
  if [[ ! -f "$state_file" ]]; then
    cat > "$state_file" <<EOF
{
  "operation_id": "$op_id",
  "kind": "stage",
  "state": "created",
  "created_at": "$(date -u +%Y-%m-%dT%H:%M:%SZ)",
  "updated_at": "$(date -u +%Y-%m-%dT%H:%M:%SZ)"
}
EOF
    chmod 600 "$state_file"
  fi
  if declare -F soviez_ops_sync_create >/dev/null 2>&1; then
    soviez_ops_sync_create "$op_id" stage_create "" "$state_file" || soviez_ops_sync_mark_pending "$op_id" OPERATION_CANONICAL_SYNC_FAILED
  fi
  printf '%s' "$op_id"
}

soviez_stage_op_read_state() {
  soviez_json_get "$(cat "$(soviez_stage_op_state_file "$1")")" state
}

soviez_stage_op_transition() {
  local op_id="$1"
  local new_state="$2"
  local meta_json="${3:-{}}"
  local state_file current
  state_file="$(soviez_stage_op_state_file "$op_id")"
  current="$(soviez_stage_op_read_state "$op_id")"
  if [[ "$current" != "$new_state" ]]; then
    soviez_stage_sm_assert "$current" "$new_state"
  fi
  soviez_json_merge_file "$state_file" "$(SOVIEZ_NEW_STATE="$new_state" SOVIEZ_META="$meta_json" python3 - <<'PY'
import json, os, time
patch = {"state": os.environ["SOVIEZ_NEW_STATE"], "updated_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())}
meta = json.loads(os.environ.get("SOVIEZ_META", "{}"))
if meta:
    patch.update(meta)
print(json.dumps(patch))
PY
)"
  if declare -F soviez_ops_sync_transition >/dev/null 2>&1; then
    local env_id
    env_id="$(soviez_json_get "$(cat "$state_file")" stage_id 2>/dev/null || true)"
    [[ -n "$env_id" ]] || env_id="$(soviez_json_get "$(cat "$state_file")" environment_id 2>/dev/null || true)"
    if ! soviez_ops_sync_transition "$op_id" stage_create "$env_id" "$new_state" "transition" "$meta_json" "$state_file"; then
      soviez_ops_sync_mark_pending "$op_id" OPERATION_CANONICAL_SYNC_PENDING
      case "$new_state" in
        database_restoring|database_restore|filestore_cloning|neutralization_running)
          soviez_stage_die STAGE_OPERATION_FAILED "Canonical sync failed before protected Stage step: $new_state"
          ;;
      esac
    fi
  fi
}

soviez_stage_op_merge() {
  local op_id="$1"
  local patch="$2"
  soviez_json_merge_file "$(soviez_stage_op_state_file "$op_id")" "$patch"
}

# --- end stage/engine.sh ---

# --- begin stage/lifecycle.sh ---
# shellcheck shell=bash
# Stage lifecycle: list/status/start/stop/backup/drop (no entitlement required).

soviez_stage_cmd_list() {
  soviez_stage_paths_init
  local ids
  if ! ids="$(soviez_stage_inventory_list_ids)"; then
    # Corrupt inventory: clean message already printed; no traceback.
    return 2
  fi
  echo "Stage ID | Domain | Status | Parent | Created | Cert"
  local id
  while IFS= read -r id; do
    [[ -z "$id" ]] && continue
    local ident domain status parent created cert
    ident="$(soviez_stage_inventory_find "$id" 2>/dev/null || true)"
    [[ -n "$ident" ]] || continue
    domain="$(soviez_json_get "$ident" stage_domain 2>/dev/null || echo "-")"
    status="$(soviez_json_get "$ident" lifecycle_status 2>/dev/null || echo unknown)"
    parent="$(soviez_json_get "$ident" parent_production_tenant_id 2>/dev/null || echo "-")"
    created="$(soviez_json_get "$ident" created_at 2>/dev/null || echo "-")"
    cert="$(soviez_json_get "$ident" origin_certificate_path 2>/dev/null || echo none)"
    [[ -n "$cert" && "$cert" != "null" && -f "$cert" ]] && cert="valid" || cert="missing"
    printf '%s | %s | %s | %s | %s | %s\n' "$id" "$domain" "$status" "$parent" "$created" "$cert"
  done <<<"$ids"
}

soviez_stage_cmd_status() {
  local stage_id="$1"
  soviez_stage_paths_init
  stage_id="$(soviez_stage_sanitize_id "$stage_id")" || soviez_stage_die STAGE_ID_CONFLICT "Invalid stage id"
  local ident
  ident="$(soviez_stage_inventory_find "$stage_id")" || soviez_stage_die RECOVERY_REQUIRED "Unknown stage: $stage_id"
  printf '%s\n' "$ident"
}

soviez_stage_cmd_start() {
  local stage_id="$1"
  soviez_stage_paths_init
  soviez_stage_runtime_start "$stage_id"
  echo "Started stage $stage_id"
}

soviez_stage_cmd_stop() {
  local stage_id="$1"
  soviez_stage_paths_init
  soviez_stage_runtime_stop "$stage_id"
  echo "Stopped stage $stage_id"
}

soviez_stage_cmd_backup() {
  local stage_id="$1"
  if declare -F soviez_backup_stage_live_backup >/dev/null 2>&1; then
    soviez_backup_stage_live_backup "$stage_id"
    return $?
  fi
  # Fallback if backup engine not assembled yet
  soviez_stage_paths_init
  local ident
  ident="$(soviez_stage_inventory_find "$stage_id")" || soviez_stage_die RECOVERY_REQUIRED "Unknown stage"
  local backup_root="${SOVIEZ_ROOT:-/var/soviez}/backups/stages"
  mkdir -p "$backup_root"
  local ts archive
  ts="$(date -u +%Y%m%dT%H%M%SZ)"
  archive="$backup_root/${stage_id}-${ts}.tar"
  local fs db_name
  fs="$(soviez_json_get "$ident" stage_filestore_path)"
  db_name="$(soviez_json_get "$ident" stage_db_name)"
  local tmp
  tmp="$(mktemp -d)"
  mkdir -p "$tmp/meta" "$tmp/filestore" "$tmp/db"
  printf '%s' "$ident" > "$tmp/meta/identity.json"
  if [[ -d "$fs" ]]; then
    cp -a "$fs"/. "$tmp/filestore/" 2>/dev/null || true
  fi
  if declare -F soviez_stage_use_live_pg >/dev/null 2>&1 && soviez_stage_use_live_pg; then
    if declare -F soviez_stage_pg_dump_fc >/dev/null 2>&1; then
      soviez_stage_pg_dump_fc "$db_name" "$tmp/db/db.dump" || true
    fi
  elif [[ "${SOVIEZ_TEST_MODE:-0}" == "1" && -d "$SOVIEZ_ROOT/stage-dbs/$db_name" ]]; then
    cp -a "$SOVIEZ_ROOT/stage-dbs/$db_name"/. "$tmp/db/"
  fi
  tar -C "$tmp" -cf "$archive" .
  local sum
  sum="$(soviez_sha256_file "$archive")"
  printf '%s' "$sum" > "${archive}.sha256"
  rm -rf "$tmp"
  echo "Backup written: $archive"
  echo "SHA256: $sum"
}

soviez_stage_cmd_drop() {
  local stage_id="$1"
  soviez_stage_paths_init
  local ident
  ident="$(soviez_stage_inventory_find "$stage_id")" || soviez_stage_die RECOVERY_REQUIRED "Unknown stage"
  local domain db created parent
  domain="$(soviez_json_get "$ident" stage_domain)"
  db="$(soviez_json_get "$ident" stage_db_name)"
  created="$(soviez_json_get "$ident" created_at)"
  parent="$(soviez_json_get "$ident" parent_production_tenant_id)"

  echo "About to DROP Stage:"
  echo "  stage_id=$stage_id"
  echo "  domain=$domain"
  echo "  db=$db"
  echo "  created=$created"
  echo "  parent_production=$parent"
  echo "Production resources will NOT be modified."

  if [[ "${SOVIEZ_STAGE_DROP_CONFIRM:-}" != "$stage_id" ]]; then
    if [[ -t 0 ]]; then
      printf 'Type the Stage ID to confirm drop: ' >&2
      local typed
      read -r typed
      [[ "$typed" == "$stage_id" ]] || soviez_stage_die DESTRUCTIVE_CONFIRMATION_REQUIRED "Confirmation mismatch"
    else
      soviez_stage_die DESTRUCTIVE_CONFIRMATION_REQUIRED "Set SOVIEZ_STAGE_DROP_CONFIRM=$stage_id for non-TTY drop"
    fi
  fi

  # Optional backup offer
  if [[ "${SOVIEZ_STAGE_DROP_SKIP_BACKUP:-0}" != "1" ]]; then
    soviez_stage_cmd_backup "$stage_id" || true
  fi

  soviez_stage_runtime_remove_owned "$stage_id"
  rm -rf "$(soviez_stage_dir "$stage_id")"
  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    rm -rf "$SOVIEZ_ROOT/stage-dbs/$db"
  fi

  local new_index
  new_index="$(SOVIEZ_IDX="$(soviez_stage_inventory_load_index)" SOVIEZ_SID="$stage_id" python3 - <<'PY'
import json,os
idx=json.loads(os.environ["SOVIEZ_IDX"])
idx["stages"]=[s for s in idx.get("stages",[]) if s.get("stage_id")!=os.environ["SOVIEZ_SID"]]
print(json.dumps(idx, separators=(",",":")))
PY
)"
  soviez_stage_inventory_atomic_write "$(soviez_stage_inventory_index)" "$new_index"
  echo "Dropped stage $stage_id (Production untouched)"
}

# --- end stage/lifecycle.sh ---

# --- begin stage/retention_codes.sh ---
# shellcheck shell=bash
# Phase 13 — Stage retention structured codes (stable protocol).

SOVIEZ_ERR_RETENTION=21

SOVIEZ_RETENTION_DEFAULT_DAYS=14
SOVIEZ_RETENTION_MAXIMUM_DAYS=60
SOVIEZ_RETENTION_POLICY_VERSION="13.0.0"

# Authoritative host timezone for calendar-day display (installer policy).
# Timestamps persist in UTC; countdown uses this zone.
SOVIEZ_RETENTION_HOST_TZ="${SOVIEZ_RETENTION_HOST_TZ:-UTC}"

SOVIEZ_RETENTION_CODES=(
  STAGE_NOT_FOUND
  STAGE_IDENTITY_MISMATCH
  RETENTION_METADATA_MISSING
  RETENTION_METADATA_CORRUPT
  RETENTION_NOT_DUE
  RETENTION_DUE
  RETENTION_EXTENSION_AVAILABLE
  RETENTION_EXTENSION_LIMIT_REACHED
  RETENTION_EXTENSION_INVALID
  RETENTION_EXTENSION_REDUCES_DEADLINE
  RETENTION_MAXIMUM_EXCEEDED
  RETENTION_EXTENSION_TOO_LATE
  RETENTION_OPERATION_IN_PROGRESS
  RETENTION_WARNING_DUE
  RETENTION_DELETION_LOCKED
  FINAL_RETENTION_BACKUP_FAILED
  FINAL_RETENTION_BACKUP_INVALID
  SAFE_SHIELD_VALIDATION_FAILED
  STAGE_PRODUCTION_COLLISION
  STAGE_RESOURCE_OWNERSHIP_AMBIGUOUS
  STAGE_SHARED_RESOURCE_DETECTED
  STAGE_ACTIVE_OPERATION_CONFLICT
  RETENTION_DELETION_FAILED
  RETENTION_PARTIAL_DELETION
  RETENTION_RETRY_SCHEDULED
  RETENTION_RECOVERY_REQUIRED
  RETENTION_DELETED
  DESTRUCTIVE_CONFIRMATION_REQUIRED
  RETENTION_STAGE_DELETED
)

soviez_retention_die() {
  local code="$1"
  shift || true
  soviez_log_error "RETENTION_CODE=${code} $*"
  printf '{"ok":false,"code":"%s","message":"%s"}\n' "$code" "$*" >&2
  exit "$SOVIEZ_ERR_RETENTION"
}

soviez_retention_ok() {
  local code="$1"
  shift || true
  printf '{"ok":true,"code":"%s","message":"%s"}\n' "$code" "$*"
}

# --- end stage/retention_codes.sh ---

# --- begin stage/retention_calendar.sh ---
# shellcheck shell=bash
# Phase 13 — calendar-day retention math (UTC persistence, host-TZ display).

# Override clock for tests: SOVIEZ_RETENTION_NOW_UTC=YYYY-MM-DDTHH:MM:SSZ
soviez_retention_now_utc() {
  if [[ -n "${SOVIEZ_RETENTION_NOW_UTC:-}" ]]; then
    printf '%s' "$SOVIEZ_RETENTION_NOW_UTC"
    return 0
  fi
  date -u +%Y-%m-%dT%H:%M:%SZ
}

soviez_retention_parse_utc_epoch() {
  local iso="$1"
  iso="$(printf '%s' "$iso" | sed -E 's/\.[0-9]+Z$/Z/; s/Z$//')"
  if date -u -j -f "%Y-%m-%dT%H:%M:%S" "$iso" +%s 2>/dev/null; then
    return 0
  fi
  date -u -d "${iso}Z" +%s 2>/dev/null || date -u -d "$iso" +%s
}

soviez_retention_add_calendar_days_utc() {
  local created_iso="$1"
  local days="$2"
  CREATED="$created_iso" DAYS="$days" TZ_NAME="${SOVIEZ_RETENTION_HOST_TZ:-UTC}" python3 - <<'PY'
import os, datetime
created = os.environ["CREATED"].replace("Z", "+00:00")
if "." in created:
    head, rest = created.split(".", 1)
    for i, ch in enumerate(rest):
        if ch in "+-" and i > 0:
            created = head + rest[i:]
            break
    else:
        created = head + "+00:00"
days = int(os.environ["DAYS"])
tzname = os.environ["TZ_NAME"]
try:
    from zoneinfo import ZoneInfo
    tz = ZoneInfo(tzname)
except Exception:
    tz = datetime.timezone.utc
dt = datetime.datetime.fromisoformat(created)
if dt.tzinfo is None:
    dt = dt.replace(tzinfo=datetime.timezone.utc)
local = dt.astimezone(tz)
deadline_date = (local.date() + datetime.timedelta(days=days))
local_eod = datetime.datetime.combine(deadline_date, datetime.time(23, 59, 59), tzinfo=tz)
utc_eod = local_eod.astimezone(datetime.timezone.utc)
print(utc_eod.strftime("%Y-%m-%dT%H:%M:%SZ"))
PY
}

soviez_retention_calendar_date_in_host_tz() {
  local iso="$1"
  ISO="$iso" TZ_NAME="${SOVIEZ_RETENTION_HOST_TZ:-UTC}" python3 - <<'PY'
import os, datetime
iso = os.environ["ISO"].replace("Z", "+00:00")
if "." in iso:
    head, rest = iso.split(".", 1)
    for i, ch in enumerate(rest):
        if ch in "+-" and i > 0:
            iso = head + rest[i:]
            break
    else:
        iso = head + "+00:00"
tzname = os.environ["TZ_NAME"]
try:
    from zoneinfo import ZoneInfo
    tz = ZoneInfo(tzname)
except Exception:
    tz = datetime.timezone.utc
dt = datetime.datetime.fromisoformat(iso)
if dt.tzinfo is None:
    dt = dt.replace(tzinfo=datetime.timezone.utc)
print(dt.astimezone(tz).date().isoformat())
PY
}

soviez_retention_days_remaining() {
  local deadline_iso="$1"
  local now_iso="${2:-$(soviez_retention_now_utc)}"
  DEADLINE="$deadline_iso" NOW="$now_iso" TZ_NAME="${SOVIEZ_RETENTION_HOST_TZ:-UTC}" python3 - <<'PY'
import os, datetime
def parse(s):
    s = s.replace("Z", "+00:00")
    if "." in s:
        head, rest = s.split(".", 1)
        for i, ch in enumerate(rest):
            if ch in "+-" and i > 0:
                s = head + rest[i:]
                break
        else:
            s = head + "+00:00"
    dt = datetime.datetime.fromisoformat(s)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=datetime.timezone.utc)
    return dt
tzname = os.environ["TZ_NAME"]
try:
    from zoneinfo import ZoneInfo
    tz = ZoneInfo(tzname)
except Exception:
    tz = datetime.timezone.utc
now = parse(os.environ["NOW"]).astimezone(tz).date()
deadline = parse(os.environ["DEADLINE"]).astimezone(tz).date()
print((deadline - now).days)
PY
}

soviez_retention_format_date_display() {
  local iso="$1"
  ISO="$iso" TZ_NAME="${SOVIEZ_RETENTION_HOST_TZ:-UTC}" python3 - <<'PY'
import os, datetime
iso = os.environ["ISO"].replace("Z", "+00:00")
if "." in iso:
    head, rest = iso.split(".", 1)
    for i, ch in enumerate(rest):
        if ch in "+-" and i > 0:
            iso = head + rest[i:]
            break
    else:
        iso = head + "+00:00"
tzname = os.environ["TZ_NAME"]
try:
    from zoneinfo import ZoneInfo
    tz = ZoneInfo(tzname)
except Exception:
    tz = datetime.timezone.utc
dt = datetime.datetime.fromisoformat(iso)
if dt.tzinfo is None:
    dt = dt.replace(tzinfo=datetime.timezone.utc)
local = dt.astimezone(tz)
print(local.strftime("%d %b %Y"))
PY
}

soviez_retention_remaining_phrase() {
  local days="$1"
  if [[ "$days" -lt 0 ]]; then
    printf 'Deletion overdue — Needs Action'
  elif [[ "$days" -eq 0 ]]; then
    printf 'Deletion scheduled today'
  elif [[ "$days" -eq 1 ]]; then
    printf '1 day remaining'
  else
    printf '%s days remaining' "$days"
  fi
}

# --- end stage/retention_calendar.sh ---

# --- begin stage/retention_inventory.sh ---
# shellcheck shell=bash
# Phase 13 — durable, per-Stage retention sidecar.

soviez_retention_file() { printf '%s/retention.json\n' "$(soviez_stage_dir "$1")"; }
soviez_retention_warnings_file() { printf '%s/retention-warnings.jsonl\n' "$(soviez_stage_dir "$1")"; }
soviez_retention_banner_file() { printf '%s/config/retention-banner.txt\n' "$(soviez_stage_dir "$1")"; }
soviez_retention_banner_html_file() { printf '%s/config/retention-banner.html\n' "$(soviez_stage_dir "$1")"; }
soviez_retention_lock_dir() { printf '%s/.retention-delete.lock\n' "$(soviez_stage_dir "$1")"; }
soviez_retention_tombstone_dir() { printf '%s/retention-tombstones\n' "${SOVIEZ_ROOT:-/var/soviez}"; }
soviez_retention_tombstone_file() { printf '%s/%s.json\n' "$(soviez_retention_tombstone_dir)" "$1"; }

soviez_retention_read() {
  local file
  file="$(soviez_retention_file "$1")"
  [[ -f "$file" ]] || soviez_retention_die RETENTION_METADATA_MISSING "Missing retention metadata for Stage $1"
  python3 -m json.tool "$file" >/dev/null 2>&1 || soviez_retention_die RETENTION_METADATA_CORRUPT "Invalid retention metadata for Stage $1"
  cat "$file"
}

soviez_retention_write() {
  local stage_id="$1" json="$2" file old
  file="$(soviez_retention_file "$stage_id")"
  if [[ -f "$file" ]]; then
    old="$(cat "$file")"
    SOVIEZ_OLD="$old" SOVIEZ_NEW="$json" python3 - <<'PY' || soviez_retention_die RETENTION_METADATA_CORRUPT "Immutable retention fields changed"
import json, os, sys
old, new = json.loads(os.environ["SOVIEZ_OLD"]), json.loads(os.environ["SOVIEZ_NEW"])
for key in ("created_at", "maximum_retention_deadline"):
    if old.get(key) != new.get(key):
        sys.exit(1)
PY
  fi
  soviez_stage_inventory_atomic_write "$file" "$json"
}

soviez_retention_patch() {
  local stage_id="$1" patch="$2" current merged
  current="$(soviez_retention_read "$stage_id")"
  merged="$(SOVIEZ_CURRENT="$current" SOVIEZ_PATCH="$patch" python3 - <<'PY'
import json, os, sys
cur=json.loads(os.environ["SOVIEZ_CURRENT"]); patch=json.loads(os.environ["SOVIEZ_PATCH"])
for key in ("created_at", "maximum_retention_deadline"):
    if key in patch and patch[key] != cur.get(key):
        raise SystemExit("immutable field")
cur.update(patch)
print(json.dumps(cur, separators=(",", ":")))
PY
)" || soviez_retention_die RETENTION_METADATA_CORRUPT "Invalid retention patch"
  soviez_retention_write "$stage_id" "$merged"
  if declare -F soviez_ops_sync_transition >/dev/null 2>&1; then
    local op_id status
    op_id="$(soviez_json_get "$merged" retention_operation_id 2>/dev/null || true)"
    status="$(soviez_json_get "$merged" retention_status 2>/dev/null || true)"
    if [[ -n "$op_id" && "$op_id" != "null" && -n "$status" && "$status" != "null" ]]; then
      if [[ "$(soviez_json_get "$merged" state 2>/dev/null || true)" != "$status" ]]; then
        merged="$(SOVIEZ_CUR="$merged" SOVIEZ_S="$status" python3 - <<'PY'
import json,os
d=json.loads(os.environ["SOVIEZ_CUR"]); d["state"]=os.environ["SOVIEZ_S"]
print(json.dumps(d,separators=(",",":")))
PY
)"
        soviez_retention_write "$stage_id" "$merged"
      fi
      local outcome="$status"
      case "$status" in
        deleted|tombstoned) outcome="completed" ;;
        needs_action|deletion_blocked) outcome="failed_retryable" ;;
        recovery_required) outcome="recovery_required" ;;
      esac
      soviez_ops_sync_transition "$op_id" retention_delete "$stage_id" "$outcome" "transition" "{}" "$(soviez_retention_file "$stage_id")" \
        || soviez_ops_sync_mark_pending "$op_id" OPERATION_CANONICAL_SYNC_PENDING
    fi
  fi
}

soviez_retention_init_for_stage() {
  local stage_id="$1" created_at="${2:-}" identity default_deadline max_deadline json
  identity="$(soviez_stage_inventory_find "$stage_id")" || soviez_retention_die STAGE_NOT_FOUND "Unknown Stage $stage_id"
  [[ -n "$created_at" ]] || created_at="$(soviez_json_get "$identity" created_at)"
  [[ -n "$created_at" ]] || soviez_retention_die RETENTION_METADATA_CORRUPT "Stage has no immutable created_at"
  [[ -f "$(soviez_retention_file "$stage_id")" ]] && { soviez_retention_read "$stage_id"; return 0; }
  default_deadline="$(soviez_retention_add_calendar_days_utc "$created_at" "$SOVIEZ_RETENTION_DEFAULT_DAYS")"
  max_deadline="$(soviez_retention_add_calendar_days_utc "$created_at" "$SOVIEZ_RETENTION_MAXIMUM_DAYS")"
  # Ensure Nginx ownership marker when Stage nginx stubs exist under Stage config
  local cfg
  cfg="$(soviez_json_get "$identity" stage_config_path)"
  if [[ -n "$cfg" && -d "$cfg" ]]; then
    if [[ -d "$cfg/nginx" || -f "$cfg/nginx.conf" ]]; then
      printf '%s\n' "$stage_id" > "$cfg/nginx.owned"
      chmod 640 "$cfg/nginx.owned" 2>/dev/null || true
    fi
  fi
  json="$(SOVIEZ_SID="$stage_id" SOVIEZ_CREATED="$created_at" SOVIEZ_DEFAULT="$default_deadline" SOVIEZ_MAX="$max_deadline" python3 - <<'PY'
import json, os
print(json.dumps({"stage_id":os.environ["SOVIEZ_SID"],"created_at":os.environ["SOVIEZ_CREATED"],
"requested_extension_days":14,"current_retention_deadline":os.environ["SOVIEZ_DEFAULT"],
"maximum_retention_deadline":os.environ["SOVIEZ_MAX"],"retention_status":"active",
"days_remaining":None,"last_failure_code":None,"completed_deletion_steps":[],"retention_operation_id":None}, separators=(",",":")))
PY
)"
  soviez_retention_write "$stage_id" "$json"
}

soviez_retention_ensure() {
  local stage_id="$1"
  [[ -f "$(soviez_stage_identity_file "$stage_id")" ]] || soviez_retention_die STAGE_NOT_FOUND "Unknown Stage $stage_id"
  [[ -f "$(soviez_retention_file "$stage_id")" ]] || soviez_retention_init_for_stage "$stage_id"
  soviez_retention_read "$stage_id" >/dev/null
}

soviez_retention_refresh_derived() {
  local stage_id="$1" rec deadline max days status failure patch
  soviez_retention_ensure "$stage_id"
  rec="$(soviez_retention_read "$stage_id")"
  deadline="$(soviez_json_get "$rec" current_retention_deadline)"
  max="$(soviez_json_get "$rec" maximum_retention_deadline)"
  days="$(soviez_retention_days_remaining "$deadline")"
  failure="$(soviez_json_get "$rec" last_failure_code 2>/dev/null || true)"
  status="$(soviez_json_get "$rec" retention_status)"
  [[ "$(soviez_retention_parse_utc_epoch "$deadline")" -le "$(soviez_retention_parse_utc_epoch "$max")" ]] || soviez_retention_die RETENTION_MAXIMUM_EXCEEDED "Retention deadline exceeds immutable maximum"
  case "$status" in
    deleting|deleted|deletion_started|deletion_running|final_backup_running|safe_shield_validating|recovery_required)
      ;;
    needs_action|deletion_blocked)
      ;;
    *)
      if [[ -n "$failure" && "$failure" != "null" ]]; then
        if [[ "$failure" == "RETENTION_PARTIAL_DELETION" ]]; then
          status="recovery_required"
        else
          status="needs_action"
        fi
      elif [[ "$days" -le 0 ]]; then
        status="deletion_due"
      elif [[ "$deadline" == "$max" ]]; then
        status="extension_limit_reached"
      else
        status="extension_available"
      fi
      ;;
  esac
  patch="$(SOVIEZ_DAYS="$days" SOVIEZ_STATUS="$status" python3 - <<'PY'
import json, os
print(json.dumps({"days_remaining":int(os.environ["SOVIEZ_DAYS"]),"retention_status":os.environ["SOVIEZ_STATUS"]},separators=(",",":")))
PY
)"
  soviez_retention_patch "$stage_id" "$patch"
}

soviez_retention_lock_acquire() {
  local lock
  lock="$(soviez_retention_lock_dir "$1")"
  if mkdir "$lock" 2>/dev/null; then printf '%s\n' "$$" > "$lock/pid"; return 0; fi
  soviez_retention_die RETENTION_DELETION_LOCKED "Retention operation already active for Stage $1"
}
soviez_retention_lock_release() { rm -rf "$(soviez_retention_lock_dir "$1")"; }

# --- end stage/retention_inventory.sh ---

# --- begin stage/retention_banner.sh ---
# shellcheck shell=bash
# Phase 13 — neutralized Stage retention banner and warning ledger.

soviez_retention_html_escape() {
  SOVIEZ_TEXT="$1" python3 - <<'PY'
import html, os
print(html.escape(os.environ["SOVIEZ_TEXT"], quote=True))
PY
}

soviez_retention_render_banner() {
  local stage_id="$1" rec deadline days phrase date maxd status text escaped line2 line3
  soviez_retention_ensure "$stage_id"
  soviez_retention_refresh_derived "$stage_id"
  rec="$(soviez_retention_read "$stage_id")"
  deadline="$(soviez_json_get "$rec" current_retention_deadline)"
  days="$(soviez_json_get "$rec" days_remaining)"
  phrase="$(soviez_retention_remaining_phrase "$days")"
  date="$(soviez_retention_format_date_display "$deadline")"
  maxd="$(soviez_retention_format_date_display "$(soviez_json_get "$rec" maximum_retention_deadline)")"
  status="$(soviez_json_get "$rec" retention_status)"

  local line1
  line1="Stage environment · Neutralized · ${phrase}"
  case "$status" in
    needs_action|deletion_blocked|recovery_required)
      line1="Stage environment · Neutralized · Deletion overdue — Needs Action"
      line2="Automatic deletion was blocked to protect Stage data."
      line3="Scheduled deletion: ${date} (timezone ${SOVIEZ_RETENTION_HOST_TZ})"
      ;;
    deletion_due)
      line2="Automatic deletion is pending Safe Shield verification."
      line3="Scheduled deletion: ${date}"
      ;;
    extension_limit_reached)
      line2="Scheduled deletion: ${date}"
      line3="Maximum 60-day retention applied."
      ;;
    *)
      line2="Scheduled deletion: ${date}"
      if [[ "$status" == "extension_available" ]]; then
        line3="Retention may be extended up to ${maxd}."
      else
        line3="Timezone: ${SOVIEZ_RETENTION_HOST_TZ}"
      fi
      ;;
  esac

  text="$(printf '%s\n%s\n%s' "$line1" "$line2" "$line3")"
  mkdir -p "$(soviez_stage_config_path "$stage_id")"
  printf '%s\n' "$text" > "$(soviez_retention_banner_file "$stage_id")"
  escaped="$(soviez_retention_html_escape "$text")"
  printf '<aside class="soviez-retention-banner" role="status" data-soviez-stage-banner="retention">%s</aside>\n' \
    "$(printf '%s' "$escaped" | sed 's/$/<br>/' | tr -d '\n')" \
    > "$(soviez_retention_banner_html_file "$stage_id")"
  chmod 640 "$(soviez_retention_banner_file "$stage_id")" "$(soviez_retention_banner_html_file "$stage_id")" 2>/dev/null || true

  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    local ident db marker
    ident="$(soviez_stage_inventory_find "$stage_id" 2>/dev/null || true)"
    if [[ -n "$ident" ]]; then
      db="$(soviez_json_get "$ident" stage_db_name)"
      marker="$SOVIEZ_ROOT/stage-dbs/$db/retention_banner.txt"
      mkdir -p "$(dirname "$marker")"
      printf '%s\n' "$text" > "$marker"
    fi
  fi
  printf '%s\n' "$text"
}

soviez_retention_evaluate_warnings() {
  local stage_id="$1" rec days threshold file t
  soviez_retention_ensure "$stage_id"
  soviez_retention_refresh_derived "$stage_id"
  rec="$(soviez_retention_read "$stage_id")"
  days="$(soviez_json_get "$rec" days_remaining)"
  file="$(soviez_retention_warnings_file "$stage_id")"
  mkdir -p "$(dirname "$file")"; touch "$file"; chmod 600 "$file"

  for t in 30 14 7 3 1 0; do
    if [[ "$days" == "$t" ]]; then
      threshold="$t"
      if python3 - "$file" "$threshold" <<'PY'
import json, sys
for line in open(sys.argv[1], encoding="utf-8"):
    try:
        if json.loads(line).get("threshold") == int(sys.argv[2]):
            raise SystemExit(0)
    except json.JSONDecodeError:
        pass
raise SystemExit(1)
PY
      then
        continue
      fi
      SOVIEZ_SID="$stage_id" SOVIEZ_THRESHOLD="$threshold" SOVIEZ_NOW="$(soviez_retention_now_utc)" python3 - <<'PY' >> "$file"
import json, os
print(json.dumps({"stage_id":os.environ["SOVIEZ_SID"],"threshold":int(os.environ["SOVIEZ_THRESHOLD"]),"warned_at":os.environ["SOVIEZ_NOW"]},separators=(",",":")))
PY
      soviez_retention_patch "$stage_id" "$(SOVIEZ_T="$threshold" python3 - <<'PY'
import json, os
print(json.dumps({"last_warning_threshold": int(os.environ["SOVIEZ_T"])}, separators=(",", ":")))
PY
)"
      soviez_log_info "Retention warning emitted for Stage $stage_id threshold=$threshold"
    fi
  done
  if [[ "$days" -lt 0 ]]; then
    if ! python3 - "$file" -1 <<'PY'
import json, sys
for line in open(sys.argv[1], encoding="utf-8"):
    try:
        if json.loads(line).get("threshold") == int(sys.argv[2]):
            raise SystemExit(0)
    except json.JSONDecodeError:
        pass
raise SystemExit(1)
PY
    then
      SOVIEZ_SID="$stage_id" SOVIEZ_NOW="$(soviez_retention_now_utc)" python3 - <<'PY' >> "$file"
import json, os
print(json.dumps({"stage_id":os.environ["SOVIEZ_SID"],"threshold":-1,"warned_at":os.environ["SOVIEZ_NOW"]},separators=(",",":")))
PY
    fi
  fi
}

# --- end stage/retention_banner.sh ---

# --- begin stage/retention_safe_shield.sh ---
# shellcheck shell=bash
# Phase 13 — fail-closed ownership validation before retention deletion.

soviez_retention_safe_shield_fail() {
  printf 'SAFE_SHIELD_FAILURE=%s\n' "$1" >&2
  return 1
}

soviez_retention_safe_shield_path_under_stage() {
  local path="$1" stage_dir="$2" real_path real_stage
  [[ "$path" != *".."* ]] || return 1
  [[ ! -L "$path" ]] || return 1
  real_path="$(python3 -c 'import os,sys; print(os.path.realpath(sys.argv[1]))' "$path" 2>/dev/null)" || return 1
  real_stage="$(python3 -c 'import os,sys; print(os.path.realpath(sys.argv[1]))' "$stage_dir" 2>/dev/null)" || return 1
  [[ "$real_path" == "$real_stage"/* ]]
}

soviez_retention_safe_shield_validate() {
  local stage_id="$1" identity stage_dir db container network fs cfg secrets cert expected
  stage_id="$(soviez_stage_sanitize_id "$stage_id")" || { soviez_retention_safe_shield_fail STAGE_IDENTITY_MISMATCH; return 1; }
  stage_dir="$(soviez_stage_dir "$stage_id")"
  identity="$(soviez_stage_inventory_find "$stage_id" 2>/dev/null || true)"
  [[ -n "$identity" && -f "$(soviez_stage_origin_cert_file "$stage_id")" ]] || { soviez_retention_safe_shield_fail STAGE_IDENTITY_MISMATCH; return 1; }
  [[ "$(soviez_json_get "$identity" stage_id 2>/dev/null)" == "$stage_id" ]] || { soviez_retention_safe_shield_fail STAGE_IDENTITY_MISMATCH; return 1; }
  db="$(soviez_json_get "$identity" stage_db_name)"; expected="$(soviez_stage_db_name_for "$stage_id")"
  [[ "$db" == "$expected" && "$db" != "odoo" && "$db" != "postgres" ]] || { soviez_retention_safe_shield_fail STAGE_PRODUCTION_COLLISION; return 1; }
  container="$(soviez_json_get "$identity" stage_container)"; [[ "$container" == "$(soviez_stage_container_name_for "$stage_id")" ]] || { soviez_retention_safe_shield_fail STAGE_PRODUCTION_COLLISION; return 1; }
  network="$(soviez_json_get "$identity" stage_network)"; [[ "$network" == "$(soviez_stage_network_name_for "$stage_id")" ]] || { soviez_retention_safe_shield_fail STAGE_RESOURCE_OWNERSHIP_AMBIGUOUS; return 1; }
  fs="$(soviez_json_get "$identity" stage_filestore_path)"; cfg="$(soviez_json_get "$identity" stage_config_path)"; secrets="$(soviez_json_get "$identity" stage_secrets_path)"
  soviez_retention_safe_shield_path_under_stage "$fs" "$stage_dir" || { soviez_retention_safe_shield_fail STAGE_PRODUCTION_COLLISION; return 1; }
  soviez_retention_safe_shield_path_under_stage "$cfg" "$stage_dir" || { soviez_retention_safe_shield_fail STAGE_PRODUCTION_COLLISION; return 1; }
  soviez_retention_safe_shield_path_under_stage "$secrets" "$stage_dir" || { soviez_retention_safe_shield_fail STAGE_PRODUCTION_COLLISION; return 1; }
  # Nginx: absent is OK; present under Stage config must be Stage-owned
  if [[ -f "$cfg/nginx.conf" || -d "$cfg/nginx" ]]; then
    if [[ ! -f "$cfg/nginx.owned" ]]; then
      # Config path already verified under Stage root — stamp ownership marker
      printf '%s\n' "$stage_id" > "$cfg/nginx.owned"
      chmod 640 "$cfg/nginx.owned" 2>/dev/null || true
    fi
    [[ "$(tr -d '[:space:]' < "$cfg/nginx.owned")" == "$stage_id" ]] \
      || { soviez_retention_safe_shield_fail STAGE_RESOURCE_OWNERSHIP_AMBIGUOUS; return 1; }
  fi
  cert="$(soviez_json_get "$identity" origin_certificate_path 2>/dev/null || true)"
  if [[ -n "$cert" && "$cert" != "null" ]]; then
    case "$cert" in
      "$stage_dir"/*) ;;
      *)
        soviez_retention_safe_shield_path_under_stage "$(dirname "$cert")" "$stage_dir" \
          || { soviez_retention_safe_shield_fail STAGE_SHARED_RESOURCE_DETECTED; return 1; }
        ;;
    esac
  fi
  if [[ "${SOVIEZ_RETENTION_HOLDING_LOCK:-0}" != "1" && -d "$(soviez_retention_lock_dir "$stage_id")" ]]; then
    soviez_retention_safe_shield_fail STAGE_ACTIVE_OPERATION_CONFLICT; return 1
  fi
  printf 'OK\n'
}

# --- end stage/retention_safe_shield.sh ---

# --- begin stage/retention_extend.sh ---
# shellcheck shell=bash
# Phase 13 — retention extension is total lifetime from immutable creation.

soviez_retention_extend() {
  local stage_id="$1" total_days="$2" yes_flag="${3:-}" rec current status created proposed max current_days
  soviez_retention_ensure "$stage_id"
  [[ "$total_days" =~ ^[0-9]+$ ]] || soviez_retention_die RETENTION_EXTENSION_INVALID "Retention days must be an integer"
  rec="$(soviez_retention_read "$stage_id")"
  status="$(soviez_json_get "$rec" retention_status)"
  [[ "$status" != "deleted" && "$status" != "deleting" && "$status" != "deletion_started" ]] || soviez_retention_die RETENTION_EXTENSION_TOO_LATE "Deletion has started"
  [[ ! -d "$(soviez_retention_lock_dir "$stage_id")" ]] || soviez_retention_die RETENTION_DELETION_LOCKED "Retention deletion is locked"
  current_days="$(soviez_json_get "$rec" requested_extension_days)"
  [[ "$total_days" -ge "$current_days" ]] || soviez_retention_die RETENTION_EXTENSION_REDUCES_DEADLINE "Extensions cannot reduce retention"
  [[ "$total_days" -le "$SOVIEZ_RETENTION_MAXIMUM_DAYS" ]] || soviez_retention_die RETENTION_MAXIMUM_EXCEEDED "Maximum retention is $SOVIEZ_RETENTION_MAXIMUM_DAYS days"
  if [[ "$total_days" -eq "$current_days" ]]; then soviez_retention_ok RETENTION_EXTENSION_AVAILABLE "Retention already set to $total_days days"; return 0; fi
  if [[ "$yes_flag" != "--yes" && "${SOVIEZ_RETENTION_EXTEND_CONFIRM:-}" != "$stage_id" ]]; then
    if [[ ! -t 0 ]]; then soviez_retention_die DESTRUCTIVE_CONFIRMATION_REQUIRED "Set SOVIEZ_RETENTION_EXTEND_CONFIRM=$stage_id or pass --yes"; fi
    printf 'Type the Stage ID to confirm a %s-day total retention lifetime: ' "$total_days" >&2
    local typed; read -r typed; [[ "$typed" == "$stage_id" ]] || soviez_retention_die DESTRUCTIVE_CONFIRMATION_REQUIRED "Confirmation mismatch"
  fi
  created="$(soviez_json_get "$rec" created_at)"
  proposed="$(soviez_retention_add_calendar_days_utc "$created" "$total_days")"
  max="$(soviez_json_get "$rec" maximum_retention_deadline)"
  [[ "$(soviez_retention_parse_utc_epoch "$proposed")" -le "$(soviez_retention_parse_utc_epoch "$max")" ]] || soviez_retention_die RETENTION_MAXIMUM_EXCEEDED "Requested deadline exceeds immutable maximum"
  soviez_retention_patch "$stage_id" "$(SOVIEZ_DAYS="$total_days" SOVIEZ_DEADLINE="$proposed" python3 - <<'PY'
import json, os
print(json.dumps({"requested_extension_days":int(os.environ["SOVIEZ_DAYS"]),"current_retention_deadline":os.environ["SOVIEZ_DEADLINE"],"retention_status":"active","last_failure_code":None},separators=(",",":")))
PY
)"
  soviez_retention_refresh_derived "$stage_id"
  soviez_retention_ok RETENTION_EXTENSION_AVAILABLE "Retention lifetime set to $total_days days"
}

# --- end stage/retention_extend.sh ---

# --- begin stage/retention_engine.sh ---
# shellcheck shell=bash
# Phase 13 — final backup, Safe Shield deletion, resume and scheduling.

soviez_retention_mark_step() {
  local stage_id="$1" step="$2" steps
  steps="$(soviez_json_get "$(soviez_retention_read "$stage_id")" completed_deletion_steps)"
  soviez_retention_patch "$stage_id" "$(SOVIEZ_STEPS="$steps" SOVIEZ_STEP="$step" python3 - <<'PY'
import json, os
steps=json.loads(os.environ["SOVIEZ_STEPS"] or "[]")
if os.environ["SOVIEZ_STEP"] not in steps:
    steps.append(os.environ["SOVIEZ_STEP"])
print(json.dumps({"completed_deletion_steps": steps}, separators=(",", ":")))
PY
)"
}

soviez_retention_step_done() {
  SOVIEZ_STEPS="$(soviez_json_get "$(soviez_retention_read "$1")" completed_deletion_steps)" SOVIEZ_STEP="$2" python3 - <<'PY'
import json, os, sys
sys.exit(0 if os.environ["SOVIEZ_STEP"] in json.loads(os.environ["SOVIEZ_STEPS"] or "[]") else 1)
PY
}

soviez_retention_fail() {
  local stage_id="$1" code="$2" message="$3" status="${4:-needs_action}"
  soviez_retention_lock_release "$stage_id" 2>/dev/null || true
  unset SOVIEZ_RETENTION_HOLDING_LOCK
  # Write terminal failure state without banner refresh (refresh must not demote).
  soviez_retention_patch "$stage_id" "$(SOVIEZ_CODE="$code" SOVIEZ_STATUS="$status" python3 - <<'PY'
import json, os
print(json.dumps({
  "retention_status": os.environ["SOVIEZ_STATUS"],
  "last_failure_code": os.environ["SOVIEZ_CODE"],
}, separators=(",", ":")))
PY
)" 2>/dev/null || true
  # Banner best-effort; re-apply status afterward
  ( soviez_retention_render_banner "$stage_id" >/dev/null ) 2>/dev/null || true
  soviez_retention_patch "$stage_id" "$(SOVIEZ_CODE="$code" SOVIEZ_STATUS="$status" python3 - <<'PY'
import json, os
print(json.dumps({
  "retention_status": os.environ["SOVIEZ_STATUS"],
  "last_failure_code": os.environ["SOVIEZ_CODE"],
}, separators=(",", ":")))
PY
)" 2>/dev/null || true
  soviez_retention_die "$code" "$message"
}

soviez_retention_final_backup() {
  local stage_id="$1" before archive sum dest_root backup_dir
  [[ "${SOVIEZ_RETENTION_INJECT_BACKUP_FAIL:-0}" != "1" ]] || return 1
  dest_root="${SOVIEZ_ROOT:-/var/soviez}/backups/retention"
  mkdir -p "$dest_root"
  case "$dest_root" in
    "$(soviez_stage_dir "$stage_id")"*) return 1 ;;
  esac
  before="$(mktemp "${TMPDIR:-/tmp}/soviez-retention-backup.XXXXXX")"
  soviez_stage_cmd_backup "$stage_id" > "$before" 2>&1 || { rm -f "$before"; return 1; }
  archive="$(awk -F': ' '/^Backup written: /{archive=$2} END{print archive}' "$before")"
  rm -f "$before"
  [[ -n "$archive" && -f "$archive" ]] || return 1
  case "$archive" in
    "$(soviez_stage_dir "$stage_id")"*) return 1 ;;
  esac
  sum="$(soviez_sha256_file "$archive" 2>/dev/null || true)"
  [[ -n "$sum" && -f "${archive}.sha256" && "$sum" == "$(tr -d '[:space:]' < "${archive}.sha256")" ]] || return 1
  [[ "${SOVIEZ_RETENTION_INJECT_BACKUP_CHECKSUM_FAIL:-0}" != "1" && "${SOVIEZ_RETENTION_INJECT_CHECKSUM_FAIL:-0}" != "1" ]] || return 1
  backup_dir="$dest_root/${stage_id}/$(basename "$archive" .tar)"
  mkdir -p "$backup_dir"
  cp -a "$archive" "${archive}.sha256" "$backup_dir/" 2>/dev/null || true
  printf '%s' "$(soviez_retention_read "$stage_id")" > "$backup_dir/retention.json"
  soviez_retention_patch "$stage_id" "$(SOVIEZ_PATH="$backup_dir" SOVIEZ_SUM="$sum" python3 - <<'PY'
import json, os
print(json.dumps({
  "final_backup_status": "ok",
  "final_backup_path": os.environ["SOVIEZ_PATH"],
  "final_backup_checksum": os.environ["SOVIEZ_SUM"],
}, separators=(",", ":")))
PY
)"
  return 0
}

soviez_retention_remove_inventory() {
  local stage_id="$1" index new_index
  index="$(soviez_stage_inventory_index)"
  new_index="$(SOVIEZ_IDX="$(soviez_stage_inventory_load_index)" SOVIEZ_SID="$stage_id" python3 - <<'PY'
import json, os
d=json.loads(os.environ["SOVIEZ_IDX"])
d["stages"]=[s for s in d.get("stages",[]) if s.get("stage_id") != os.environ["SOVIEZ_SID"]]
print(json.dumps(d, separators=(",", ":")))
PY
)"
  soviez_stage_inventory_atomic_write "$index" "$new_index"
}

soviez_retention_write_tombstone() {
  local stage_id="$1" reason="$2" rec ident tombstone
  rec="$(soviez_retention_read "$stage_id" 2>/dev/null || echo '{}')"
  ident="$(soviez_stage_inventory_find "$stage_id" 2>/dev/null || echo '{}')"
  tombstone="$(soviez_retention_tombstone_file "$stage_id")"
  mkdir -p "$(dirname "$tombstone")"
  chmod 700 "$(dirname "$tombstone")" 2>/dev/null || true
  REC="$rec" IDENT="$ident" REASON="$reason" NOW="$(soviez_retention_now_utc)" SID="$stage_id" \
    VER="$SOVIEZ_RETENTION_POLICY_VERSION" python3 - <<'PY' > "$tombstone"
import json, os
rec=json.loads(os.environ.get("REC") or "{}")
ident=json.loads(os.environ.get("IDENT") or "{}")
lic=str(ident.get("license_id") or "")
if len(lic) > 12:
    lic = lic[:8] + "…"
print(json.dumps({
  "stage_id": os.environ["SID"],
  "parent_production_tenant_id": ident.get("parent_production_tenant_id"),
  "license_id_abbrev": lic,
  "domain": ident.get("stage_domain"),
  "original_creation_timestamp": rec.get("created_at"),
  "final_deadline": rec.get("current_retention_deadline"),
  "extension_count": rec.get("extension_count"),
  "requested_extension_days": rec.get("requested_extension_days"),
  "deletion_completed_timestamp": os.environ["NOW"],
  "deletion_reason": os.environ["REASON"],
  "operation_id": rec.get("retention_operation_id"),
  "backup_path": rec.get("final_backup_path"),
  "backup_checksum": rec.get("final_backup_checksum"),
  "deleted_resource_manifest": rec.get("completed_deletion_steps") or [],
  "safe_shield_status": rec.get("safe_shield_status"),
  "retention_policy_version": os.environ["VER"],
}, indent=2))
PY
}

soviez_retention_run_deletion() {
  local stage_id="$1" force="${2:-0}" rec days identity db fs cfg secrets container network op_id
  soviez_stage_paths_init
  soviez_retention_ensure "$stage_id"
  soviez_retention_lock_acquire "$stage_id"
  export SOVIEZ_RETENTION_HOLDING_LOCK=1
  trap 'soviez_retention_lock_release "'"$stage_id"'"; unset SOVIEZ_RETENTION_HOLDING_LOCK' EXIT

  soviez_retention_refresh_derived "$stage_id"
  rec="$(soviez_retention_read "$stage_id")"
  days="$(soviez_json_get "$rec" days_remaining)"
  [[ "$force" == "1" || "$days" -le 0 ]] || soviez_retention_fail "$stage_id" RETENTION_NOT_DUE "Retention deadline has not elapsed"

  local cur_e max_e created expected_max
  created="$(soviez_json_get "$rec" created_at)"
  expected_max="$(soviez_retention_add_calendar_days_utc "$created" "$SOVIEZ_RETENTION_MAXIMUM_DAYS")"
  if [[ "$(soviez_json_get "$rec" maximum_retention_deadline)" != "$expected_max" ]]; then
    soviez_retention_fail "$stage_id" RETENTION_METADATA_CORRUPT "maximum_retention_deadline tampered"
  fi
  cur_e="$(soviez_retention_parse_utc_epoch "$(soviez_json_get "$rec" current_retention_deadline)")"
  max_e="$(soviez_retention_parse_utc_epoch "$(soviez_json_get "$rec" maximum_retention_deadline)")"
  (( cur_e <= max_e )) || soviez_retention_fail "$stage_id" RETENTION_MAXIMUM_EXCEEDED "Retention deadline exceeds maximum"

  op_id="$(soviez_json_get "$rec" retention_operation_id)"
  if [[ -z "$op_id" || "$op_id" == "null" ]]; then
    op_id="ret-del-${stage_id}-$(date -u +%Y%m%dT%H%M%SZ)"
  fi
  soviez_retention_patch "$stage_id" "$(SOVIEZ_OP="$op_id" SOVIEZ_NOW="$(soviez_retention_now_utc)" python3 - <<'PY'
import json, os
print(json.dumps({
  "retention_operation_id": os.environ["SOVIEZ_OP"],
  "deletion_started_at": os.environ["SOVIEZ_NOW"],
  "retention_status": "final_backup_running",
  "state": "final_backup",
}, separators=(",", ":")))
PY
)"
  # Continuous sync replaces migrate-on-write; sync happens via retention_patch.
  if declare -F soviez_ops_sync_transition >/dev/null 2>&1; then
    soviez_ops_sync_transition "$op_id" retention_delete "$stage_id" "final_backup_running" "created" "{}" "$(soviez_retention_file "$stage_id")" \
      || soviez_ops_sync_mark_pending "$op_id" OPERATION_CANONICAL_SYNC_PENDING
  fi

  if ! soviez_retention_final_backup "$stage_id"; then
    soviez_retention_fail "$stage_id" FINAL_RETENTION_BACKUP_FAILED "Final backup failed" needs_action
  fi
  soviez_retention_mark_step "$stage_id" final_backup

  soviez_retention_patch "$stage_id" '{"retention_status":"safe_shield_validating"}'
  if ! soviez_retention_safe_shield_validate "$stage_id" >/dev/null; then
    soviez_retention_fail "$stage_id" SAFE_SHIELD_VALIDATION_FAILED "Safe Shield rejected deletion" needs_action
  fi
  soviez_retention_patch "$stage_id" '{"safe_shield_status":"ok","retention_status":"deletion_running","last_failure_code":null}'

  identity="$(soviez_stage_inventory_find "$stage_id")"
  db="$(soviez_json_get "$identity" stage_db_name)"
  fs="$(soviez_json_get "$identity" stage_filestore_path)"
  cfg="$(soviez_json_get "$identity" stage_config_path)"
  secrets="$(soviez_json_get "$identity" stage_secrets_path)"
  container="$(soviez_json_get "$identity" stage_container)"
  network="$(soviez_json_get "$identity" stage_network)"

  if ! soviez_retention_step_done "$stage_id" stop_container; then
    [[ "${SOVIEZ_RETENTION_INJECT_STOP_FAIL:-0}" != "1" ]] || soviez_retention_fail "$stage_id" RETENTION_PARTIAL_DELETION "Stop failed" recovery_required
    soviez_stage_runtime_stop "$stage_id" || true
    if command -v docker >/dev/null 2>&1; then
      docker stop "$container" 2>/dev/null || true
    fi
    soviez_retention_mark_step "$stage_id" stop_container
  fi

  if ! soviez_retention_step_done "$stage_id" verify_production_healthy; then
    [[ -f "${SOVIEZ_PRODUCTION_HEALTH_FILE:-${SOVIEZ_ROOT:-/var/soviez}/production.ok}" ]] \
      || soviez_retention_fail "$stage_id" SAFE_SHIELD_VALIDATION_FAILED "Production health file missing" needs_action
    soviez_retention_mark_step "$stage_id" verify_production_healthy
  fi

  if ! soviez_retention_step_done "$stage_id" remove_nginx; then
    [[ "${SOVIEZ_RETENTION_INJECT_NGINX_FAIL:-0}" != "1" ]] || soviez_retention_fail "$stage_id" RETENTION_PARTIAL_DELETION "Nginx removal failed" recovery_required
    rm -rf "$cfg/nginx" 2>/dev/null || true
    rm -f "$cfg/nginx.owned" "$cfg/nginx.conf" 2>/dev/null || true
    soviez_retention_mark_step "$stage_id" remove_nginx
  fi

  if ! soviez_retention_step_done "$stage_id" remove_container; then
    if command -v docker >/dev/null 2>&1; then
      docker rm -f "$container" 2>/dev/null || true
    fi
    if declare -F soviez_stage_runtime_remove_owned >/dev/null; then
      soviez_stage_runtime_remove_owned "$stage_id" 2>/dev/null || true
    fi
    soviez_retention_mark_step "$stage_id" remove_container
  fi

  if ! soviez_retention_step_done "$stage_id" remove_database; then
    if [[ "${SOVIEZ_RETENTION_INJECT_DB_FAIL:-0}" == "1" ]]; then
      soviez_retention_fail "$stage_id" RETENTION_PARTIAL_DELETION "Database removal failed" recovery_required
    fi
    [[ "$db" != *"*"* ]] || soviez_retention_fail "$stage_id" STAGE_RESOURCE_OWNERSHIP_AMBIGUOUS "Wildcard database target" needs_action
    if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
      rm -rf "${SOVIEZ_ROOT}/stage-dbs/$db"
    elif declare -F soviez_stage_use_live_pg >/dev/null && soviez_stage_use_live_pg; then
      # Exact Stage DB only — never wildcard or multi-DB cleanup.
      local db_drop_sql
      db_drop_sql="$(printf 'DROP %s "%s";' DATABASE "$db")"
      soviez_stage_pg_psql -d postgres -c "SELECT pg_terminate_backend(pid) FROM pg_stat_activity WHERE datname='${db}' AND pid <> pg_backend_pid();" >/dev/null || true
      soviez_stage_pg_psql -d postgres -c "$db_drop_sql" >/dev/null || soviez_retention_fail "$stage_id" RETENTION_PARTIAL_DELETION "Database drop failed" recovery_required
    fi
    soviez_retention_mark_step "$stage_id" remove_database
  fi

  if ! soviez_retention_step_done "$stage_id" remove_filestore; then
    if [[ "${SOVIEZ_RETENTION_INJECT_FS_FAIL:-0}" == "1" ]]; then
      soviez_retention_fail "$stage_id" RETENTION_PARTIAL_DELETION "Filestore removal failed" recovery_required
    fi
    case "$fs" in
      "$(soviez_stage_dir "$stage_id")"/*) rm -rf "$fs" ;;
      *) soviez_retention_fail "$stage_id" STAGE_RESOURCE_OWNERSHIP_AMBIGUOUS "Filestore outside Stage root" needs_action ;;
    esac
    soviez_retention_mark_step "$stage_id" remove_filestore
  fi

  if ! soviez_retention_step_done "$stage_id" remove_volumes; then
    rm -rf "$(soviez_stage_dir "$stage_id")/volumes" 2>/dev/null || true
    soviez_retention_mark_step "$stage_id" remove_volumes
  fi

  if ! soviez_retention_step_done "$stage_id" remove_network; then
    if command -v docker >/dev/null 2>&1; then
      docker network rm "$network" 2>/dev/null || true
    fi
    soviez_retention_mark_step "$stage_id" remove_network
  fi

  if ! soviez_retention_step_done "$stage_id" remove_config_secrets; then
    rm -rf "$cfg" "$secrets" 2>/dev/null || true
    soviez_retention_mark_step "$stage_id" remove_config_secrets
  fi

  if ! soviez_retention_step_done "$stage_id" remove_certificate_if_unshared; then
    local shared
    shared="$(soviez_json_get "$identity" certificate_shared_wildcard 2>/dev/null || true)"
    if [[ "$shared" != "true" ]]; then
      rm -rf "$(soviez_stage_dir "$stage_id")/certs" 2>/dev/null || true
    fi
    soviez_retention_mark_step "$stage_id" remove_certificate_if_unshared
  fi

  soviez_retention_write_tombstone "$stage_id" "retention_deadline"

  if ! soviez_retention_step_done "$stage_id" remove_inventory; then
    soviez_retention_remove_inventory "$stage_id"
    soviez_retention_mark_step "$stage_id" remove_inventory
  fi

  rm -rf "$(soviez_stage_dir "$stage_id")"
  trap - EXIT
  soviez_retention_lock_release "$stage_id"
  unset SOVIEZ_RETENTION_HOLDING_LOCK
  soviez_retention_ok RETENTION_DELETED "Stage $stage_id deleted after retention expiry"
}

soviez_retention_status() {
  local stage_id="${1:-}"
  soviez_stage_paths_init
  if [[ -z "$stage_id" ]]; then
    local sid
    while IFS= read -r sid; do
      [[ -n "$sid" ]] || continue
      echo "--- $sid ---"
      soviez_retention_status "$sid" || true
    done < <(soviez_stage_inventory_list_ids)
    return 0
  fi
  soviez_retention_ensure "$stage_id"
  soviez_retention_refresh_derived "$stage_id"
  soviez_retention_render_banner "$stage_id" >/dev/null
  local rec
  rec="$(soviez_retention_read "$stage_id")"
  REC="$rec" TZNAME="$SOVIEZ_RETENTION_HOST_TZ" python3 - <<'PY'
import json, os
r=json.loads(os.environ["REC"])
print(json.dumps({
  "stage_id": r.get("stage_id"),
  "created_at": r.get("created_at"),
  "current_retention_deadline": r.get("current_retention_deadline"),
  "maximum_retention_deadline": r.get("maximum_retention_deadline"),
  "days_remaining": r.get("days_remaining"),
  "retention_status": r.get("retention_status"),
  "requested_extension_days": r.get("requested_extension_days"),
  "final_backup_status": r.get("final_backup_status"),
  "safe_shield_status": r.get("safe_shield_status"),
  "last_failure_code": r.get("last_failure_code"),
  "timezone": os.environ["TZNAME"],
}, indent=2))
PY
  echo "--- banner ---"
  cat "$(soviez_retention_banner_file "$stage_id")"
}

soviez_retention_retry() {
  local stage_id="$1" status
  soviez_retention_ensure "$stage_id"
  status="$(soviez_json_get "$(soviez_retention_read "$stage_id")" retention_status)"
  case "$status" in
    needs_action|deletion_blocked|recovery_required|failed_retryable|deletion_due)
      soviez_retention_run_deletion "$stage_id" 1
      ;;
    *)
      soviez_retention_die RETENTION_NOT_DUE "Nothing to retry (status=$status)"
      ;;
  esac
}

soviez_retention_scheduler_scan() {
  local sid days
  soviez_stage_paths_init
  while IFS= read -r sid; do
    [[ -n "$sid" ]] || continue
    soviez_retention_ensure "$sid" 2>/dev/null || continue
    soviez_retention_refresh_derived "$sid" || true
    soviez_retention_evaluate_warnings "$sid" || true
    soviez_retention_render_banner "$sid" >/dev/null || true
    days="$(soviez_json_get "$(soviez_retention_read "$sid")" days_remaining)"
    if [[ "$days" -le 0 ]]; then
      ( soviez_retention_run_deletion "$sid" 0 ) || true
    fi
  done < <(soviez_stage_inventory_list_ids)
}

# --- end stage/retention_engine.sh ---

# --- begin ops/codes.sh ---
# shellcheck shell=bash

SOVIEZ_ERR_OPS=22
SOVIEZ_OPS_CODES=(
  OPERATION_NOT_FOUND
  OPERATION_IDENTITY_MISMATCH
  OPERATION_SCHEMA_UNSUPPORTED
  OPERATION_STATE_CORRUPT
  OPERATION_TRANSITION_INVALID
  OPERATION_ALREADY_RUNNING
  OPERATION_ALREADY_TERMINAL
  OPERATION_RESOURCE_CONFLICT
  OPERATION_LOCK_CONFLICT
  OPERATION_LOCK_STALE
  OPERATION_LOCK_RECOVERY_REQUIRED
  OPERATION_LOCK_IDENTITY_MISMATCH
  OPERATION_DEADLOCK_PREVENTED
  OPERATION_WORKER_MISSING
  OPERATION_WORKER_DUPLICATE
  OPERATION_WORKER_IDENTITY_MISMATCH
  OPERATION_HEARTBEAT_STALE
  OPERATION_SYSTEMD_UNIT_MISSING
  OPERATION_SYSTEMD_STATE_MISMATCH
  OPERATION_REATTACH_UNAVAILABLE
  OPERATION_CANCEL_ACCEPTED
  OPERATION_CANCEL_NOT_ALLOWED
  OPERATION_CANCEL_REQUIRES_CONFIRMATION
  OPERATION_CANCEL_ROLLBACK_STARTED
  OPERATION_CANCELLATION_TIMEOUT
  OPERATION_RETRY_NOT_ALLOWED
  OPERATION_RETRY_SCHEDULED
  OPERATION_RECOVERY_REQUIRED
  OPERATION_RECOVERY_NOT_SAFE
  OPERATION_MIGRATION_REQUIRED
  OPERATION_MIGRATION_FAILED
  OPERATION_LOG_UNAVAILABLE
  OPERATION_HISTORY_CORRUPT
  DESTRUCTIVE_CONFIRMATION_REQUIRED
  OPERATION_CONFIRMATION_REQUIRED
  OPERATION_CANONICAL_SYNC_FAILED
  OPERATION_CANONICAL_SYNC_PENDING
  OPERATION_CANONICAL_STATE_STALE
  OPERATION_CANONICAL_REVISION_MISMATCH
  OPERATION_REGISTRY_SYNC_FAILED
  OPERATION_EVENT_SYNC_FAILED
  OPERATION_TERMINAL_SYNC_INCOMPLETE
  OPERATION_SYNC_RECONCILED
  OPERATION_SYNC_RECOVERY_REQUIRED
)

soviez_ops_die() {
  local code="${1:-OPERATION_STATE_CORRUPT}" message="${2:-Operation failed}"
  soviez_log_error "${code}: ${message}"
  SOVIEZ_OPS_CODE="$code" SOVIEZ_OPS_MESSAGE="$(soviez_redact_text "$message")" python3 - <<'PY' >&2
import json, os
print(json.dumps({"ok": False, "code": os.environ["SOVIEZ_OPS_CODE"],
                  "message": os.environ["SOVIEZ_OPS_MESSAGE"]}, separators=(",", ":")))
PY
  exit "$SOVIEZ_ERR_OPS"
}

soviez_ops_ok() {
  local code="${1:-OK}" message="${2:-OK}"
  SOVIEZ_OPS_CODE="$code" SOVIEZ_OPS_MESSAGE="$(soviez_redact_text "$message")" python3 - <<'PY'
import json, os
print(json.dumps({"ok": True, "code": os.environ["SOVIEZ_OPS_CODE"],
                  "message": os.environ["SOVIEZ_OPS_MESSAGE"]}, separators=(",", ":")))
PY
}

# --- end ops/codes.sh ---

# --- begin ops/paths.sh ---
# shellcheck shell=bash

soviez_ops_paths_init() {
  : "${SOVIEZ_OPS_ROOT:?soviez_paths_init must run first}"
  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    SOVIEZ_OPS_REGISTRY_DIR="$SOVIEZ_OPS_ROOT/registry"
  else
    SOVIEZ_OPS_REGISTRY_DIR="${SOVIEZ_OPS_REGISTRY_DIR:-$SOVIEZ_OPS_ROOT/registry}"
  fi
  SOVIEZ_OPS_INDEX_DIR="$SOVIEZ_OPS_REGISTRY_DIR/index"
  SOVIEZ_OPS_LOCKS_DIR="$SOVIEZ_OPS_REGISTRY_DIR/locks"
  SOVIEZ_OPS_HISTORY_DIR="$SOVIEZ_OPS_REGISTRY_DIR/history"
  SOVIEZ_OPS_CANONICAL_NAME=canonical.json
  export SOVIEZ_OPS_REGISTRY_DIR SOVIEZ_OPS_INDEX_DIR SOVIEZ_OPS_LOCKS_DIR SOVIEZ_OPS_HISTORY_DIR SOVIEZ_OPS_CANONICAL_NAME
  mkdir -p "$SOVIEZ_OPS_INDEX_DIR" "$SOVIEZ_OPS_LOCKS_DIR" "$SOVIEZ_OPS_HISTORY_DIR"
  chmod 700 "$SOVIEZ_OPS_REGISTRY_DIR" "$SOVIEZ_OPS_INDEX_DIR" "$SOVIEZ_OPS_LOCKS_DIR" "$SOVIEZ_OPS_HISTORY_DIR"
}

soviez_ops_registry_index_path() { printf '%s/%s.json\n' "$SOVIEZ_OPS_INDEX_DIR" "$1"; }
soviez_ops_resource_lock_path() { printf '%s/%s.lock\n' "$SOVIEZ_OPS_LOCKS_DIR" "$1"; }
soviez_ops_history_path() { printf '%s/%s.jsonl\n' "$SOVIEZ_OPS_HISTORY_DIR" "$1"; }

# Resolve the on-disk directory for an operation across Phase 8/11/12/13 roots.
soviez_ops_resolve_dir() {
  local op_id="$1" idx cpath candidate
  idx="$(soviez_ops_registry_index_path "$op_id")"
  if [[ -f "$idx" ]]; then
    cpath="$(soviez_json_get "$(cat "$idx")" canonical_path 2>/dev/null || true)"
    if [[ -n "$cpath" && -f "$cpath" ]]; then
      dirname "$cpath"
      return 0
    fi
  fi
  for candidate in \
    "$(soviez_operation_dir "$op_id")" \
    "${SOVIEZ_STAGE_OPS_DIR:-$SOVIEZ_OPS_ROOT/stage-operations}/$op_id" \
    "${SOVIEZ_SSL_OPS_DIR:-$SOVIEZ_OPS_ROOT/ssl-operations}/$op_id"; do
    [[ -d "$candidate" ]] || continue
    if [[ -f "$candidate/$SOVIEZ_OPS_CANONICAL_NAME" || -f "$candidate/state.json" ]]; then
      printf '%s\n' "$candidate"
      return 0
    fi
  done
  printf '%s\n' "$(soviez_operation_dir "$op_id")"
}

soviez_ops_canonical_state_path() { printf '%s/%s\n' "$(soviez_ops_resolve_dir "$1")" "$SOVIEZ_OPS_CANONICAL_NAME"; }
soviez_ops_events_path() { printf '%s/events.jsonl\n' "$(soviez_ops_resolve_dir "$1")"; }
soviez_ops_heartbeat_path() { printf '%s/heartbeat\n' "$(soviez_ops_resolve_dir "$1")"; }

# --- end ops/paths.sh ---

# --- begin ops/schema.sh ---
# shellcheck shell=bash

soviez_ops_schema_version() { printf '1\n'; }
soviez_ops_engine_version() { printf '0.15.0-phase15\n'; }
soviez_ops_now_utc() { date -u +%Y-%m-%dT%H:%M:%SZ; }

soviez_ops_new_record() {
  local op_id="$1" op_type="$2" environment_id="${3:-}" checkpoint="${4:-created}" meta="${5:-{}}"
  SOVIEZ_OP_ID="$op_id" SOVIEZ_OP_TYPE="$op_type" SOVIEZ_ENV_ID="$environment_id" \
    SOVIEZ_CHECKPOINT="$checkpoint" SOVIEZ_META="$meta" \
    SOVIEZ_HOST="$(hostname -f 2>/dev/null || hostname || echo unknown)" \
    python3 - <<'PY'
import json, os, time
try: meta=json.loads(os.environ["SOVIEZ_META"])
except json.JSONDecodeError: meta={}
now=time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
rec={
 "schema_version":1,"engine_version":"0.15.0-phase15","adapter_version":"1",
 "operation_id":os.environ["SOVIEZ_OP_ID"],"operation_type":os.environ["SOVIEZ_OP_TYPE"],
 "command":os.environ["SOVIEZ_OP_TYPE"],"requested_action":os.environ["SOVIEZ_OP_TYPE"],
 "environment_id":os.environ["SOVIEZ_ENV_ID"] or None,"environment_type":None,
 "parent_production_id":None,"license_id":None,"resource_scope":[],
 "host_identity":os.environ.get("SOVIEZ_HOST") or "unknown","request_source":"local",
 "created_at":now,"queued_at":None,"started_at":None,"updated_at":now,"heartbeat_at":None,
 "completed_at":None,"canceled_at":None,"failed_at":None,"next_retry_at":None,
 "current_state":"created","previous_state":None,"state_entered_at":now,
 "current_checkpoint":os.environ["SOVIEZ_CHECKPOINT"],"progress_percent":0,
 "progress_message":None,"terminal":False,"success":None,
 "controller_pid":None,"worker_pid":None,"worker_identity":None,"systemd_unit":None,
 "systemd_invocation_id":None,"worker_started_at":None,"worker_generation":0,
 "lock_ids":[],"lock_owner":None,"lock_acquired_at":None,"lock_lease_until":None,"lock_generation":0,
 "retry_count":0,"retry_policy":"default","retryable":True,"last_retry_at":None,
 "cancel_requested":False,"cancel_requested_at":None,"cancel_requested_by":None,
 "cancel_reason":None,"cancellation_boundary":None,"cancel_safe":True,
 "rollback_available":False,"rollback_state":None,"rollback_checkpoint":None,
 "recovery_required":False,"recovery_reason":None,"recovery_checkpoint":None,
 "failure_code":None,"failure_class":None,"failure_message_safe":None,
 "failure_step":None,"failure_retryable":None,
 "state_path":None,"events_path":None,"log_path":None,"artifact_paths":[],"evidence_refs":[],
 "migrated_from_schema":None,"migration_timestamp":None,"sequence":0,"meta":meta,
 "canonical_sync_status":"synchronized","canonical_sync_revision":0,"canonical_synced_at":now,
 "canonical_sync_error_code":None,"canonical_sync_retry_count":0,
 "legacy_state_revision":0,"canonical_state_revision":0,"last_synchronized_transition":None,
 "registry_revision":0,"event_sequence":0,"terminal_cleanup_status":None
}
print(json.dumps(rec, separators=(",",":")))
PY
}

soviez_ops_forbid_secrets_in_json() {
  SOVIEZ_OPS_JSON="$1" python3 - <<'PY'
import json, os, re, sys
try: value=json.loads(os.environ["SOVIEZ_OPS_JSON"])
except Exception: raise SystemExit(2)
def walk(v):
  if isinstance(v, dict):
    for k, child in v.items():
      if re.search(r"password|private_key|token|secret|activation|credential|authorization", k, re.I): return False
      if not walk(child): return False
  elif isinstance(v, list):
    return all(walk(x) for x in v)
  elif isinstance(v, str):
    if re.search(r"BEGIN (RSA |EC |OPENSSH )?PRIVATE KEY|postgres(ql)?://[^:]+:[^@]+@", v, re.I): return False
  return True
raise SystemExit(0 if walk(value) else 1)
PY
}

soviez_ops_validate_record() {
  local json="$1"
  soviez_ops_forbid_secrets_in_json "$json" || soviez_ops_die OPERATION_STATE_CORRUPT "Canonical record contains secrets"
  SOVIEZ_OPS_JSON="$json" python3 - <<'PY'
import json, os, sys
try: d=json.loads(os.environ["SOVIEZ_OPS_JSON"])
except Exception: raise SystemExit(2)
if d.get("schema_version") != 1: raise SystemExit(3)
if not all(isinstance(d.get(k), str) and d[k] for k in ("operation_id","operation_type","current_state")): raise SystemExit(4)
PY
  case "$?" in
    0) ;;
    3) soviez_ops_die OPERATION_SCHEMA_UNSUPPORTED "Unsupported operation schema" ;;
    *) soviez_ops_die OPERATION_STATE_CORRUPT "Invalid canonical operation record" ;;
  esac
}

# --- end ops/schema.sh ---

# --- begin ops/events.sh ---
# shellcheck shell=bash

soviez_ops_append_event() {
  local op_id="$1" event_type="$2" message="$3" extra_json="${4:-{}}" record seq events
  record="$(cat "$(soviez_ops_canonical_state_path "$op_id")")" || soviez_ops_die OPERATION_NOT_FOUND "Unknown operation: $op_id"
  seq="$(soviez_json_get "$record" sequence 2>/dev/null || printf '0')"
  events="$(soviez_ops_events_path "$op_id")"
  mkdir -p "$(dirname "$events")"; chmod 700 "$(dirname "$events")"
  SOVIEZ_EVT_TYPE="$event_type" SOVIEZ_EVT_MSG="$(soviez_redact_text "$message")" \
    SOVIEZ_EVT_EXTRA="$(soviez_redact_text "$extra_json")" SOVIEZ_EVT_SEQ="$((seq + 1))" \
    python3 - <<'PY' >> "$events"
import json, os, time
try: extra=json.loads(os.environ["SOVIEZ_EVT_EXTRA"])
except Exception: extra={}
print(json.dumps({"sequence":int(os.environ["SOVIEZ_EVT_SEQ"]), "at":time.strftime("%Y-%m-%dT%H:%M:%SZ",time.gmtime()),
 "event_type":os.environ["SOVIEZ_EVT_TYPE"],"message":os.environ["SOVIEZ_EVT_MSG"],"extra":extra},separators=(",",":")))
PY
  chmod 600 "$events"
}

# --- end ops/events.sh ---

# --- begin ops/history.sh ---
# shellcheck shell=bash

soviez_ops_history_append() {
  local op_id="$1" record; record="$(cat "$(soviez_ops_canonical_state_path "$op_id")")" || return 1
  printf '%s\n' "$record" >> "$(soviez_ops_history_path "$op_id")"; chmod 600 "$(soviez_ops_history_path "$op_id")"
}
soviez_ops_history_list() {
  local op_id="${1:-}" file
  if [[ -n "$op_id" ]]; then cat "$(soviez_ops_history_path "$op_id")" 2>/dev/null || true
  else for file in "$SOVIEZ_OPS_HISTORY_DIR"/*.jsonl; do [[ -f "$file" ]] && cat "$file"; done; fi
}

# --- end ops/history.sh ---

# --- begin ops/transitions.sh ---
# shellcheck shell=bash

SOVIEZ_OPS_STATES=(created queued starting running waiting retry_scheduled cancel_requested canceling rollback_running recovery_required completed canceled failed_retryable failed_terminal)

soviez_ops_sm_can_transition() {
  local from="$1" to="$2"
  [[ "$from" == "$to" ]] && return 0
  case "$from:$to" in
    created:queued|created:starting|created:canceled|created:failed_*|queued:starting|queued:cancel_requested|queued:canceled|queued:failed_*|starting:running|starting:waiting|starting:failed_*|starting:recovery_required|starting:canceled|running:waiting|running:retry_scheduled|running:cancel_requested|running:rollback_running|running:recovery_required|running:completed|running:failed_*|waiting:running|waiting:retry_scheduled|waiting:cancel_requested|waiting:canceled|waiting:recovery_required|waiting:completed|waiting:failed_*|retry_scheduled:starting|retry_scheduled:running|retry_scheduled:cancel_requested|retry_scheduled:canceled|retry_scheduled:failed_*|failed_retryable:retry_scheduled|failed_retryable:canceled|cancel_requested:canceling|cancel_requested:canceled|cancel_requested:recovery_required|canceling:canceled|canceling:rollback_running|canceling:recovery_required|rollback_running:canceled|rollback_running:completed|rollback_running:recovery_required|rollback_running:failed_*|recovery_required:starting|recovery_required:running|recovery_required:canceled|recovery_required:failed_terminal|recovery_required:retry_scheduled) return 0 ;;
  esac
  return 1
}
soviez_ops_sm_assert() { soviez_ops_sm_can_transition "$1" "$2" || soviez_ops_die OPERATION_TRANSITION_INVALID "Illegal transition: $1 -> $2"; }

soviez_ops_transition() {
  local op_id="$1" new_state="$2" checkpoint="${3:-}" meta_json="${4:-{}}" path current updated
  path="$(soviez_ops_canonical_state_path "$op_id")"
  [[ -f "$path" ]] || soviez_ops_die OPERATION_NOT_FOUND "Unknown operation: $op_id"
  current="$(cat "$path")"; soviez_ops_validate_record "$current"
  local old_state; old_state="$(soviez_json_get "$current" current_state)"
  soviez_ops_sm_assert "$old_state" "$new_state"
  updated="$(SOVIEZ_CURRENT="$current" SOVIEZ_STATE="$new_state" SOVIEZ_CHECKPOINT="$checkpoint" SOVIEZ_META="$meta_json" python3 - <<'PY'
import json, os, time
d=json.loads(os.environ["SOVIEZ_CURRENT"]); d["current_state"]=os.environ["SOVIEZ_STATE"]
if os.environ["SOVIEZ_CHECKPOINT"]: d["current_checkpoint"]=os.environ["SOVIEZ_CHECKPOINT"]
try:
    meta=json.loads(os.environ["SOVIEZ_META"])
    if not isinstance(d.get("meta"), dict): d["meta"]={}
    d["meta"].update(meta)
except Exception:
    pass
d["previous_state"]=d.get("current_state")
d["sequence"]=int(d.get("sequence") or 0)+1
d["updated_at"]=time.strftime("%Y-%m-%dT%H:%M:%SZ",time.gmtime())
d["state_entered_at"]=d["updated_at"]
print(json.dumps(d,separators=(",",":")))
PY
)"
  # Fix previous_state before overwrite — recompute properly
  updated="$(SOVIEZ_CURRENT="$current" SOVIEZ_NEW="$updated" python3 - <<'PY'
import json, os
old=json.loads(os.environ["SOVIEZ_CURRENT"]); new=json.loads(os.environ["SOVIEZ_NEW"])
new["previous_state"]=old.get("current_state")
print(json.dumps(new,separators=(",",":")))
PY
)"
  soviez_stage_inventory_atomic_write "$path" "$updated"
  soviez_ops_append_event "$op_id" "transition" "$old_state -> $new_state" "$meta_json"
  soviez_ops_registry_register "$op_id" 2>/dev/null || true
  case "$new_state" in completed|canceled|failed_terminal) soviez_ops_history_append "$op_id" 2>/dev/null || true ;; esac
}

# --- end ops/transitions.sh ---

# --- begin ops/heartbeat.sh ---
# shellcheck shell=bash

soviez_ops_heartbeat_touch() {
  local op_id="$1" now path record updated
  now="$(soviez_ops_now_utc)"; path="$(soviez_ops_heartbeat_path "$op_id")"
  printf '%s\n' "$now" > "$path"; chmod 600 "$path"
  record="$(cat "$(soviez_ops_canonical_state_path "$op_id")")" || soviez_ops_die OPERATION_NOT_FOUND "Unknown operation: $op_id"
  updated="$(SOVIEZ_CURRENT="$record" SOVIEZ_NOW="$now" python3 - <<'PY'
import json,os
d=json.loads(os.environ["SOVIEZ_CURRENT"]); d["heartbeat_at"]=os.environ["SOVIEZ_NOW"]; print(json.dumps(d,separators=(",",":")))
PY
)"
  soviez_stage_inventory_atomic_write "$(soviez_ops_canonical_state_path "$op_id")" "$updated"
}

soviez_ops_heartbeat_stale() {
  local op_id="$1" threshold="${2:-120}" path
  path="$(soviez_ops_heartbeat_path "$op_id")"; [[ -f "$path" ]] || return 0
  SOVIEZ_HEARTBEAT="$(cat "$path")" SOVIEZ_THRESHOLD="$threshold" python3 - <<'PY'
import datetime, os, sys
try: stamp=datetime.datetime.strptime(os.environ["SOVIEZ_HEARTBEAT"].strip(),"%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=datetime.timezone.utc)
except ValueError: raise SystemExit(0)
raise SystemExit(0 if (datetime.datetime.now(datetime.timezone.utc)-stamp).total_seconds()>int(os.environ["SOVIEZ_THRESHOLD"]) else 1)
PY
}

# --- end ops/heartbeat.sh ---

# --- begin ops/locks.sh ---
# shellcheck shell=bash

soviez_ops_lock_id() {
  local kind="$1" resource="$2"
  resource="$(printf '%s' "$resource" | tr '[:upper:]' '[:lower:]' | tr -cd 'a-z0-9._:-')"
  [[ -n "$resource" ]] || soviez_ops_die OPERATION_RESOURCE_CONFLICT "Invalid lock resource"
  printf '%s:%s\n' "$kind" "$resource"
}
soviez_ops_lock_dir() { printf '%s/%s\n' "$SOVIEZ_OPS_LOCKS_DIR" "$(printf '%s' "$1" | tr ':' '_' | tr -cd 'a-zA-Z0-9._-')"; }

soviez_ops_lock_acquire() {
  local op_id="$1" lock_id="$2" dir; dir="$(soviez_ops_lock_dir "$lock_id")"
  if mkdir "$dir" 2>/dev/null; then
    SOVIEZ_OWNER="$op_id" SOVIEZ_LOCK="$lock_id" SOVIEZ_NOW="$(soviez_ops_now_utc)" python3 - <<'PY' > "$dir/owner.json"
import json, os
print(json.dumps({"operation_id":os.environ["SOVIEZ_OWNER"],"lock_id":os.environ["SOVIEZ_LOCK"],"pid":os.getpid(),"generation":1,"acquired_at":os.environ["SOVIEZ_NOW"]},separators=(",",":")))
PY
    chmod 700 "$dir"; chmod 600 "$dir/owner.json"; return 0
  fi
  local owner owner_id; owner="$(cat "$dir/owner.json" 2>/dev/null || true)"; owner_id="$(soviez_json_get "$owner" operation_id 2>/dev/null || true)"
  if [[ -n "$owner_id" ]] && soviez_ops_heartbeat_stale "$owner_id" 2>/dev/null && ! kill -0 "$(soviez_json_get "$owner" pid 2>/dev/null || echo 0)" 2>/dev/null; then
    soviez_ops_die OPERATION_LOCK_STALE "Stale lock requires reconciliation: $lock_id"
  fi
  soviez_ops_die OPERATION_LOCK_CONFLICT "Resource lock held: $lock_id"
}
soviez_ops_lock_release() {
  local op_id="$1" lock_id="$2" dir owner
  dir="$(soviez_ops_lock_dir "$lock_id")"; owner="$(cat "$dir/owner.json" 2>/dev/null || true)"
  [[ "$(soviez_json_get "$owner" operation_id 2>/dev/null || true)" == "$op_id" ]] || soviez_ops_die OPERATION_RESOURCE_CONFLICT "Lock not owned by operation"
  rm -f "$dir/owner.json"; rmdir "$dir"
}
soviez_ops_lock_held_by() { soviez_json_get "$(cat "$(soviez_ops_lock_dir "$1")/owner.json")" operation_id; }
soviez_ops_locks_acquire_ordered() {
  local op_id="$1"; shift
  local lock; while IFS= read -r lock; do soviez_ops_lock_acquire "$op_id" "$lock"; done < <(printf '%s\n' "$@" | LC_ALL=C sort)
}

# --- end ops/locks.sh ---

# --- begin ops/conflicts.sh ---
# shellcheck shell=bash

soviez_ops_conflict_decide() {
  local a="$1" b="$2" env_a="$3" env_b="$4" overlap="$5"
  [[ "$a" == "ssl_renewal" && "$b" == "ssl_renewal" ]] && { [[ "$overlap" == "1" ]] && printf 'attach_existing\n' || printf 'allow\n'; return; }
  # Duplicate production_update on same env → attach_existing
  [[ "$a" == "production_update" && "$b" == "production_update" && "$overlap" == "1" ]] && { printf 'attach_existing\n'; return; }
  [[ "$env_a" != "$env_b" && "$overlap" != "1" ]] && { printf 'allow\n'; return; }
  case "$a:$b" in
    retention_delete:stage_backup|retention_delete:stage_drop|retention_delete:stage_restore|stage_backup:retention_delete|stage_drop:retention_delete|stage_restore:retention_delete|update:migrate|update:restore|migrate:update|restore:update) printf 'deny\n' ;;
    production_update:production_update|production_update:migrate|production_update:restore|production_update:stage_create|production_update:retention_delete|production_update:new|migrate:production_update|restore:production_update|stage_create:production_update|retention_delete:production_update|new:production_update)
      printf 'deny\n'
      ;;
    # New production_update supersedes scheduled/waiting image cleanup on same env.
    # Active deleting cleanup blocks update; cleanup vs active update is denied (cleanup aborts).
    production_update:update_image_cleanup)
      [[ "$overlap" == "1" ]] && printf 'supersede_cleanup\n' || printf 'allow\n'
      ;;
    update_image_cleanup:production_update)
      [[ "$overlap" == "1" ]] && printf 'deny\n' || printf 'allow\n'
      ;;
    update_image_cleanup:update_image_cleanup)
      [[ "$overlap" == "1" ]] && printf 'deny\n' || printf 'allow\n'
      ;;
    update_image_cleanup:stage_create|stage_create:update_image_cleanup)
      [[ "$overlap" == "1" ]] && printf 'wait\n' || printf 'allow\n'
      ;;
    production_update:ssl_renewal|production_update:ssl_repair|ssl_renewal:production_update|ssl_repair:production_update)
      # Nginx/cert promotion must not overlap final switch — wait when same env
      [[ "$overlap" == "1" ]] && printf 'wait\n' || printf 'allow\n'
      ;;
    production_update:stage_backup|stage_backup:production_update)
      # Unrelated manual backup only safe before protected work; treat as wait on overlap
      [[ "$overlap" == "1" ]] && printf 'wait\n' || printf 'allow\n'
      ;;
    # Phase 16 — one data-heavy backup/restore per host when scopes overlap
    production_backup:production_backup|production_backup:production_restore|production_restore:production_backup|production_restore:production_restore|production_backup:production_update|production_update:production_backup|production_restore:production_update|production_update:production_restore|production_backup:migrate|migrate:production_backup|production_restore:migrate|migrate:production_restore|backup_restore_test:production_restore|production_restore:backup_restore_test|backup_restore_test:production_backup|production_backup:backup_restore_test)
      [[ "$overlap" == "1" ]] && printf 'deny\n' || printf 'allow\n'
      ;;
    production_backup:backup_retention_cleanup|backup_retention_cleanup:production_backup|production_restore:backup_retention_cleanup|backup_retention_cleanup:production_restore|backup_verification:backup_retention_cleanup|backup_retention_cleanup:backup_verification)
      [[ "$overlap" == "1" ]] && printf 'deny\n' || printf 'allow\n'
      ;;
    production_backup:ssl_renewal|ssl_renewal:production_backup)
      [[ "$overlap" == "1" ]] && printf 'wait\n' || printf 'allow\n'
      ;;
    # Phase 17 — migration preparation ops
    migration_source_discovery:migration_source_discovery|migration_destination_bootstrap:migration_destination_bootstrap|migration_trust_pairing:migration_trust_pairing|migration_domain_plan:migration_domain_plan|migration_dns_challenge:migration_dns_challenge|migration_landing_prepare:migration_landing_prepare|migration_tls_prepare:migration_tls_prepare|migration_routing_readiness:migration_routing_readiness)
      [[ "$overlap" == "1" ]] && printf 'deny\n' || printf 'allow\n'
      ;;
    migration_domain_plan:migrate|migrate:migration_domain_plan|migration_dns_challenge:migrate|migrate:migration_dns_challenge|migration_landing_prepare:migrate|migrate:migration_landing_prepare|migration_tls_prepare:migrate|migrate:migration_tls_prepare|migration_routing_readiness:migrate|migrate:migration_routing_readiness|migration_domain_abort:migrate|migrate:migration_domain_abort)
      printf 'deny\n'
      ;;
    migration_domain_abort:*)
      printf 'allow\n'
      ;;
    migration_tls_prepare:ssl_renewal|ssl_renewal:migration_tls_prepare)
      [[ "$overlap" == "1" ]] && printf 'deny\n' || printf 'allow\n'
      ;;
    migration_source_discovery:production_update|production_update:migration_source_discovery|migration_source_discovery:production_restore|production_restore:migration_source_discovery|migration_trust_pairing:production_update|production_update:migration_trust_pairing|migration_trust_pairing:production_restore|production_restore:migration_trust_pairing|migration_source_discovery:migrate|migrate:migration_source_discovery|migration_destination_bootstrap:migrate|migrate:migration_destination_bootstrap|migration_trust_pairing:migrate|migrate:migration_trust_pairing|migration_readiness_assessment:migrate|migrate:migration_readiness_assessment)
      [[ "$overlap" == "1" ]] && printf 'deny\n' || printf 'allow\n'
      ;;
    migration_pair_abort:*)
      printf 'allow\n'
      ;;
    # Phase 19 — deny overlapping transfer ops on same host; abort always allowed
    migration_transfer_plan:migration_transfer_plan|migration_payload_presync:migration_payload_presync|migration_database_transfer:migration_database_transfer|migration_filestore_transfer:migration_filestore_transfer|migration_addon_transfer:migration_addon_transfer|migration_config_transfer:migration_config_transfer|migration_stage_transfer:migration_stage_transfer|migration_final_sync:migration_final_sync|migration_destination_verify:migration_destination_verify)
      [[ "$overlap" == "1" ]] && printf 'deny\n' || printf 'allow\n'
      ;;
    migration_transfer_plan:migration_final_sync|migration_final_sync:migration_transfer_plan|migration_payload_presync:migration_final_sync|migration_final_sync:migration_payload_presync|migration_database_transfer:migration_final_sync|migration_final_sync:migration_database_transfer|migration_filestore_transfer:migration_final_sync|migration_final_sync:migration_filestore_transfer)
      [[ "$overlap" == "1" ]] && printf 'deny\n' || printf 'allow\n'
      ;;
    migration_final_sync:production_update|production_update:migration_final_sync|migration_final_sync:production_restore|production_restore:migration_final_sync|migration_final_sync:production_backup|production_backup:migration_final_sync|migration_final_sync:migrate|migrate:migration_final_sync|migration_payload_presync:production_update|production_update:migration_payload_presync|migration_payload_presync:production_backup|production_backup:migration_payload_presync)
      [[ "$overlap" == "1" ]] && printf 'deny\n' || printf 'allow\n'
      ;;
    migration_transfer_abort:*|*:migration_transfer_abort)
      printf 'allow\n'
      ;;
    *) [[ "$overlap" == "1" ]] && printf 'wait\n' || printf 'allow\n' ;;
  esac
}

soviez_ops_conflict_check() {
  local op_type="$1" env_id="$2" resources="${3:-}" file rec existing_type existing_env existing_state decision sync_status op_id
  shopt -s nullglob
  for file in "$SOVIEZ_OPS_INDEX_DIR"/*.json; do
    [[ -f "$file" ]] || continue; rec="$(cat "$file")"
    existing_state="$(soviez_json_get "$rec" current_state 2>/dev/null || true)"
    case "$existing_state" in completed|canceled|failed_terminal) continue ;; esac
    existing_type="$(soviez_json_get "$rec" operation_type 2>/dev/null || true)"
    existing_env="$(soviez_json_get "$rec" environment_id 2>/dev/null || true)"
    op_id="$(soviez_json_get "$rec" operation_id 2>/dev/null || true)"
    [[ -n "$existing_type" ]] || continue
    # Stale/incomplete canonical sync on overlapping resource → fail closed
    if [[ -n "$op_id" ]] && [[ "$env_id" == "$existing_env" && -n "$env_id" ]]; then
      if soviez_ops_sync_is_pending "$op_id" 2>/dev/null; then
        soviez_ops_die OPERATION_CANONICAL_SYNC_PENDING "Conflicting operation has unsynchronized canonical state: $op_id"
      fi
      if [[ -f "$(soviez_ops_canonical_state_path "$op_id")" ]]; then
        sync_status="$(soviez_json_get "$(cat "$(soviez_ops_canonical_state_path "$op_id")")" canonical_sync_status 2>/dev/null || true)"
        case "$sync_status" in
          pending|incomplete|failed|stale)
            soviez_ops_die OPERATION_CANONICAL_STATE_STALE "Stale canonical state blocks conflict decision: $op_id"
            ;;
        esac
      fi
    fi
    decision="$(soviez_ops_conflict_decide "$op_type" "$existing_type" "$env_id" "$existing_env" "$([[ "$env_id" == "$existing_env" && -n "$env_id" ]] && echo 1 || echo 0)")"
    case "$decision" in
      deny|requires_recovery)
        # If existing cleanup is actively deleting, keep deny; if only scheduled, treat as supersede for production_update
        if [[ "$decision" == "deny" && "$op_type" == "production_update" && "$existing_type" == "update_image_cleanup" ]]; then
          case "$existing_state" in
            deleting|running|executing)
              soviez_ops_die OPERATION_RESOURCE_CONFLICT "Conflicting operation: $existing_type ($existing_state)"
              ;;
            *)
              decision="supersede_cleanup"
              ;;
          esac
        else
          soviez_ops_die OPERATION_RESOURCE_CONFLICT "Conflicting operation: $existing_type ($existing_state)"
        fi
        ;;
    esac
    if [[ "$decision" == "supersede_cleanup" ]]; then
      case "$existing_state" in
        deleting|running|executing)
          soviez_ops_die OPERATION_RESOURCE_CONFLICT "Conflicting operation: $existing_type ($existing_state)"
          ;;
        *)
          # Abort scheduled/waiting cleanup so a new update can proceed; cleanup must revalidate later.
          SOVIEZ_REC="$rec" SOVIEZ_FILE="$file" python3 - <<'PY' 2>/dev/null || true
import json,os
path=os.environ["SOVIEZ_FILE"]
with open(path,encoding="utf-8") as f: d=json.load(f)
d["current_state"]="canceled"
d["checkpoint"]="superseded_by_production_update"
d["cancel_reason"]="new_production_update"
with open(path,"w",encoding="utf-8") as f:
  json.dump(d,f,separators=(",",":")); f.write("\n")
PY
          if [[ -n "$op_id" ]] && declare -F soviez_ops_sync_terminal >/dev/null 2>&1; then
            soviez_ops_sync_terminal "$op_id" update_image_cleanup "$existing_env" canceled "$file" 2>/dev/null || true
          fi
          # Also mark image-cleanup local state if present
          local ic_state="${SOVIEZ_IMAGE_CLEANUP_DIR:-${SOVIEZ_UPDATE_ROOT:-$SOVIEZ_ROOT/update}/image_cleanup}/operations/$op_id/state.json"
          if [[ -n "$op_id" && -f "$ic_state" ]]; then
            soviez_json_merge_file "$ic_state" \
              '{"current_state":"canceled","checkpoint":"superseded_by_production_update"}' 2>/dev/null || true
          fi
          continue
          ;;
      esac
    fi
  done
}

# --- end ops/conflicts.sh ---

# --- begin ops/migration.sh ---
# shellcheck shell=bash

soviez_ops_migrate_from_state() {
  local op_id="$1" state_file="$2" op_type="${3:-new}" op_dir canonical legacy_canonical legacy state record
  op_dir="$(soviez_operation_dir "$op_id")"
  mkdir -p "$op_dir"
  canonical="$op_dir/$SOVIEZ_OPS_CANONICAL_NAME"
  # Idempotent: already migrated into unified home (refresh if legacy checkpoint advanced)
  if [[ -f "$canonical" ]]; then
    local existing legacy_state canon_cp
    existing="$(cat "$canonical")"
    legacy_state="$(soviez_json_get "$(cat "$state_file")" state 2>/dev/null || true)"
    canon_cp="$(soviez_json_get "$existing" current_checkpoint 2>/dev/null || true)"
    if [[ -z "$legacy_state" || "$legacy_state" == "$canon_cp" || "$legacy_state" == "$(soviez_json_get "$existing" current_state)" ]]; then
      soviez_ops_validate_record "$existing"
      soviez_ops_registry_register "$op_id" 2>/dev/null || true
      return 0
    fi
    # Fall through to remap from advanced legacy state (preserve identity)
  fi
  # Also accept prior sidecar next to legacy (pre-unify)
  legacy_canonical="$(dirname "$state_file")/$SOVIEZ_OPS_CANONICAL_NAME"
  if [[ -f "$legacy_canonical" && "$(dirname "$state_file")" != "$op_dir" ]]; then
    cp "$legacy_canonical" "$canonical"
    chmod 600 "$canonical"
    soviez_ops_registry_register "$op_id"
    return 0
  fi
  legacy="$(cat "$state_file")" || soviez_ops_die OPERATION_STATE_CORRUPT "Missing legacy state"
  state="$(soviez_json_get "$legacy" state 2>/dev/null || printf 'recovery_required')"
  record="$(soviez_ops_new_record "$op_id" "$op_type" "$(soviez_json_get "$legacy" environment_id 2>/dev/null || true)" "$state")"
  record="$(SOVIEZ_REC="$record" SOVIEZ_STATE="$state" SOVIEZ_LEGACY="$state_file" python3 - <<'PY'
import json,os
d=json.loads(os.environ["SOVIEZ_REC"]); s=os.environ["SOVIEZ_STATE"] or "created"
shared={"created","queued","starting","running","waiting","retry_scheduled","cancel_requested","canceling","rollback_running","recovery_required","completed","canceled","failed_retryable","failed_terminal"}
if s in ("completed","canceled","failed_terminal","failed_retryable","recovery_required"):
    d["current_state"]=s
elif s in shared:
    d["current_state"]=s
else:
    waiting_like={"waiting_for_dns","waiting_for_connection_consent","waiting_for_activation_method","manual_activation_pending","device_authorization_pending","waiting_for_dns_propagation","ssl.waiting_for_dns","retention.waiting"}
    d["current_state"]="waiting" if s in waiting_like or s.startswith("waiting") else "running"
d["current_checkpoint"]=s
d["migrated_from_schema"]="legacy"
d["migration_timestamp"]=d.get("updated_at")
d["meta"]=d.get("meta") if isinstance(d.get("meta"), dict) else {}
d["meta"]["legacy_state_path"]=os.environ["SOVIEZ_LEGACY"]
print(json.dumps(d,separators=(",",":")))
PY
)"
  [[ -f "$state_file.pre-phase14.bak" ]] || cp "$state_file" "$state_file.pre-phase14.bak"
  soviez_stage_inventory_atomic_write "$canonical" "$record"
  # Keep a sidecar next to legacy when the legacy root differs (Stage/SSL/retention).
  if [[ "$(dirname "$state_file")" != "$op_dir" ]]; then
    soviez_stage_inventory_atomic_write "$legacy_canonical" "$record" 2>/dev/null || true
  fi
  soviez_ops_registry_register "$op_id"
}

soviez_ops_migrate_legacy_new() { soviez_ops_migrate_from_state "$1" "$(soviez_operation_state_file "$1")" new; }
soviez_ops_migrate_legacy_stage() { soviez_ops_migrate_from_state "$1" "$(soviez_stage_op_state_file "$1")" stage_create; }
soviez_ops_migrate_legacy_ssl() { local f="$SOVIEZ_SSL_OPS_DIR/$1/state.json"; soviez_ops_migrate_from_state "$1" "$f" ssl_renewal; }
soviez_ops_migrate_legacy_retention() {
  local f id
  f="$(soviez_retention_file "$1")"
  id="$(soviez_json_get "$(cat "$f")" retention_operation_id)"
  [[ -n "$id" ]] || soviez_ops_die OPERATION_MIGRATION_FAILED "retention_operation_id missing"
  soviez_ops_migrate_from_state "$id" "$f" retention_delete
}

soviez_ops_migrate_one() {
  local value="$1" dir state
  dir="$value"; [[ -d "$dir" ]] || dir="$(soviez_ops_resolve_dir "$value")"
  state="$dir/state.json"
  if [[ ! -f "$state" ]]; then
    # Retention inventory path may be passed as environment id
    if declare -F soviez_retention_file >/dev/null 2>&1 && [[ -f "$(soviez_retention_file "$value" 2>/dev/null || true)" ]]; then
      soviez_ops_migrate_legacy_retention "$value"
      return 0
    fi
    soviez_ops_die OPERATION_NOT_FOUND "No legacy operation: $value"
  fi
  soviez_ops_migrate_from_state "$(soviez_json_get "$(cat "$state")" operation_id 2>/dev/null || basename "$dir")" "$state" "$(
    kind="$(soviez_json_get "$(cat "$state")" kind 2>/dev/null || echo new)"
    case "$kind" in stage) printf 'stage_create' ;; ssl*) printf 'ssl_renewal' ;; retention*) printf 'retention_delete' ;; *) printf '%s' "$kind" ;; esac
  )"
}

soviez_ops_migrate_all() {
  local dry="${1:-}" d
  for d in "$SOVIEZ_OPS_ROOT/operations"/* "$SOVIEZ_STAGE_OPS_DIR"/* "$SOVIEZ_SSL_OPS_DIR"/*; do
    [[ -d "$d" && -f "$d/state.json" ]] || continue
    if [[ "$dry" == --dry-run ]]; then printf '%s\n' "$d"; continue; fi
    soviez_ops_migrate_one "$d"
  done
}

# --- end ops/migration.sh ---

# --- begin ops/sync.sh ---
# shellcheck shell=bash
# Phase 14 corrective closure — continuous canonical synchronization.
# Write order: legacy (already written by caller) → canonical → registry → event → terminal cleanup.

soviez_ops_map_legacy_checkpoint() {
  local s="$1"
  case "$s" in
    created|queued|starting|running|waiting|retry_scheduled|cancel_requested|canceling|rollback_running|recovery_required|completed|canceled|failed_retryable|failed_terminal)
      printf '%s\n' "$s"
      ;;
    waiting_for_*|manual_activation_pending|device_authorization_pending|waiting_for_dns*|ssl.waiting*|retention.waiting*|renewal_scheduled)
      printf 'waiting\n'
      ;;
    failed|needs_action|deletion_blocked)
      printf 'failed_retryable\n'
      ;;
    deleted|tombstoned|certified|origin_certificate_issued)
      printf 'completed\n'
      ;;
    *)
      printf 'running\n'
      ;;
  esac
}

soviez_ops_sync_fail_inject() {
  local point="$1"
  [[ "${SOVIEZ_OPS_SYNC_FAIL_AT:-}" == "$point" ]] || return 0
  return 1
}

soviez_ops_sync_mark_pending() {
  local op_id="$1" code="${2:-OPERATION_CANONICAL_SYNC_PENDING}" dir marker
  dir="$(soviez_operation_dir "$op_id")"
  mkdir -p "$dir"
  marker="$dir/sync_pending.json"
  SOVIEZ_CODE="$code" SOVIEZ_NOW="$(soviez_ops_now_utc)" python3 - <<'PY' > "$marker"
import json, os
print(json.dumps({"canonical_sync_status":"pending","canonical_sync_error_code":os.environ["SOVIEZ_CODE"],
 "canonical_synced_at":None,"at":os.environ["SOVIEZ_NOW"]},separators=(",",":")))
PY
  chmod 600 "$marker" 2>/dev/null || true
}

soviez_ops_sync_clear_pending() {
  rm -f "$(soviez_operation_dir "$1")/sync_pending.json" 2>/dev/null || true
}

soviez_ops_sync_is_pending() {
  local op_id="$1" path status
  path="$(soviez_ops_canonical_state_path "$op_id")"
  [[ -f "$(soviez_operation_dir "$op_id")/sync_pending.json" ]] && return 0
  [[ -f "$path" ]] || return 1
  status="$(soviez_json_get "$(cat "$path")" canonical_sync_status 2>/dev/null || true)"
  [[ "$status" == "pending" || "$status" == "incomplete" || "$status" == "failed" ]]
}

soviez_ops_sync_apply() {
  # Args: op_id op_type env_id legacy_checkpoint [event_type] [extra_json] [legacy_state_file]
  local op_id="$1" op_type="$2" env_id="${3:-}" legacy_cp="$4" event_type="${5:-transition}" extra="${6:-{}}" legacy_file="${7:-}"
  local shared path existing rev now updated seq last_sync terminal_cleanup=0

  soviez_ops_paths_init 2>/dev/null || true
  shared="$(soviez_ops_map_legacy_checkpoint "$legacy_cp")"
  path="$(soviez_ops_canonical_state_path "$op_id")"
  mkdir -p "$(dirname "$path")"
  now="$(soviez_ops_now_utc)"

  if [[ ! -f "$path" ]]; then
    existing="$(soviez_ops_new_record "$op_id" "$op_type" "$env_id" "$legacy_cp")"
  else
    existing="$(cat "$path")"
  fi

  # Idempotent: same logical transition already synchronized
  last_sync="$(soviez_json_get "$existing" last_synchronized_transition 2>/dev/null || true)"
  if [[ "$last_sync" == "${legacy_cp}|${shared}" && "$(soviez_json_get "$existing" canonical_sync_status 2>/dev/null || true)" == "synchronized" ]]; then
    soviez_ops_sync_clear_pending "$op_id"
    return 0
  fi

  if ! soviez_ops_sync_fail_inject before_canonical; then
    soviez_ops_sync_mark_pending "$op_id" OPERATION_CANONICAL_SYNC_FAILED
    return 22
  fi

  updated="$(SOVIEZ_CUR="$existing" SOVIEZ_SHARED="$shared" SOVIEZ_CP="$legacy_cp" \
    SOVIEZ_ENV="$env_id" SOVIEZ_TYPE="$op_type" SOVIEZ_NOW="$now" SOVIEZ_EXTRA="$extra" \
    SOVIEZ_LEGACY="$legacy_file" python3 - <<'PY'
import json, os, time
d=json.loads(os.environ["SOVIEZ_CUR"])
shared=os.environ["SOVIEZ_SHARED"]; cp=os.environ["SOVIEZ_CP"]; now=os.environ["SOVIEZ_NOW"]
prev=d.get("current_state")
# Prevent silent backward shared-state regression unless recovery/cancel/fail paths
terminal={"completed","canceled","failed_terminal"}
if prev in terminal and shared not in terminal and shared != "recovery_required":
    raise SystemExit(7)
d["previous_state"]=prev
d["current_state"]=shared
d["current_checkpoint"]=cp
d["operation_type"]=os.environ["SOVIEZ_TYPE"] or d.get("operation_type")
if os.environ.get("SOVIEZ_ENV"):
    d["environment_id"]=os.environ["SOVIEZ_ENV"]
d["updated_at"]=now
d["state_entered_at"]=now
rev=int(d.get("canonical_state_revision") or d.get("sequence") or 0)+1
d["canonical_state_revision"]=rev
d["legacy_state_revision"]=rev
d["canonical_sync_revision"]=rev
d["registry_revision"]=rev
d["sequence"]=rev
d["event_sequence"]=rev
d["canonical_sync_status"]="synchronized"
d["canonical_synced_at"]=now
d["canonical_sync_error_code"]=None
d["last_synchronized_transition"]=f"{cp}|{shared}"
d["terminal"]=shared in ("completed","canceled","failed_terminal")
if shared=="completed":
    d["success"]=True; d["completed_at"]=now; d["terminal_cleanup_status"]="pending"
elif shared in ("canceled","failed_terminal"):
    d["success"]=False; d["completed_at"]=now; d["terminal_cleanup_status"]="pending"
    if shared=="failed_terminal": d["failed_at"]=now
elif shared=="failed_retryable":
    d["success"]=False; d["failed_at"]=now
elif shared=="recovery_required":
    d["recovery_required"]=True
try:
    extra=json.loads(os.environ.get("SOVIEZ_EXTRA") or "{}")
    if isinstance(extra, dict) and extra:
        meta=d.get("meta") if isinstance(d.get("meta"), dict) else {}
        meta.update(extra); d["meta"]=meta
except Exception:
    pass
if os.environ.get("SOVIEZ_LEGACY"):
    meta=d.get("meta") if isinstance(d.get("meta"), dict) else {}
    meta["legacy_state_path"]=os.environ["SOVIEZ_LEGACY"]; d["meta"]=meta
print(json.dumps(d,separators=(",",":")))
PY
)" || {
    soviez_ops_sync_mark_pending "$op_id" OPERATION_CANONICAL_REVISION_MISMATCH
    return 22
  }

  soviez_ops_validate_record "$updated" || {
    soviez_ops_sync_mark_pending "$op_id" OPERATION_CANONICAL_SYNC_FAILED
    return 22
  }

  if ! soviez_stage_inventory_atomic_write "$path" "$updated"; then
    soviez_ops_sync_mark_pending "$op_id" OPERATION_CANONICAL_SYNC_FAILED
    return 22
  fi

  if ! soviez_ops_sync_fail_inject before_registry; then
    soviez_ops_sync_mark_pending "$op_id" OPERATION_REGISTRY_SYNC_FAILED
    # Mark canonical as incomplete for registry
    updated="$(SOVIEZ_CUR="$updated" python3 - <<'PY'
import json,os
d=json.loads(os.environ["SOVIEZ_CUR"]); d["canonical_sync_status"]="incomplete"; d["canonical_sync_error_code"]="OPERATION_REGISTRY_SYNC_FAILED"
print(json.dumps(d,separators=(",",":")))
PY
)"
    soviez_stage_inventory_atomic_write "$path" "$updated" 2>/dev/null || true
    return 22
  fi

  if ! soviez_ops_registry_register "$op_id"; then
    soviez_ops_sync_mark_pending "$op_id" OPERATION_REGISTRY_SYNC_FAILED
    return 22
  fi

  if ! soviez_ops_sync_fail_inject before_event; then
    soviez_ops_sync_mark_pending "$op_id" OPERATION_EVENT_SYNC_FAILED
    return 22
  fi

  # Duplicate event prevention: skip if events already contain this sequence/revision
  seq="$(soviez_json_get "$updated" sequence)"
  events="$(soviez_ops_events_path "$op_id")"
  mkdir -p "$(dirname "$events")"; chmod 700 "$(dirname "$events")" 2>/dev/null || true
  if [[ -f "$events" ]] && grep -Fq "\"sequence\":${seq}," "$events" 2>/dev/null; then
    :
  else
    if ! SOVIEZ_EVT_TYPE="$event_type" SOVIEZ_EVT_MSG="$(soviez_redact_text "$legacy_cp -> $shared")" \
      SOVIEZ_EVT_SEQ="$seq" SOVIEZ_EVT_CP="$legacy_cp" python3 - <<'PY' >> "$events"
import json, os, time
print(json.dumps({"sequence":int(os.environ["SOVIEZ_EVT_SEQ"]),"at":time.strftime("%Y-%m-%dT%H:%M:%SZ",time.gmtime()),
 "event_type":os.environ["SOVIEZ_EVT_TYPE"],"message":os.environ["SOVIEZ_EVT_MSG"],
 "checkpoint":os.environ["SOVIEZ_EVT_CP"],"redaction":"applied"},separators=(",",":")))
PY
    then
      soviez_ops_sync_mark_pending "$op_id" OPERATION_EVENT_SYNC_FAILED
      return 22
    fi
    chmod 600 "$events" 2>/dev/null || true
  fi

  case "$shared" in
    completed|canceled|failed_terminal)
      if ! soviez_ops_sync_fail_inject before_history; then
        soviez_ops_sync_mark_pending "$op_id" OPERATION_TERMINAL_SYNC_INCOMPLETE
        return 22
      fi
      soviez_ops_history_append "$op_id" 2>/dev/null || {
        soviez_ops_sync_mark_pending "$op_id" OPERATION_TERMINAL_SYNC_INCOMPLETE
        return 22
      }
      if ! soviez_ops_sync_fail_inject before_lock_cleanup; then
        soviez_ops_sync_mark_pending "$op_id" OPERATION_TERMINAL_SYNC_INCOMPLETE
        return 22
      fi
      # Idempotent terminal cleanup marker; resource locks released by command engines.
      updated="$(SOVIEZ_CUR="$(cat "$path")" python3 - <<'PY'
import json,os
d=json.loads(os.environ["SOVIEZ_CUR"]); d["terminal_cleanup_status"]="done"
print(json.dumps(d,separators=(",",":")))
PY
)"
      soviez_stage_inventory_atomic_write "$path" "$updated"
      soviez_ops_registry_register "$op_id" 2>/dev/null || true
      ;;
  esac

  soviez_ops_sync_clear_pending "$op_id"
  return 0
}

soviez_ops_sync_create() {
  local op_id="$1" op_type="$2" env_id="${3:-}" legacy_file="${4:-}"
  soviez_ops_sync_apply "$op_id" "$op_type" "$env_id" "created" "created" "{}" "$legacy_file"
}

soviez_ops_sync_transition() {
  soviez_ops_sync_apply "$@"
}

soviez_ops_sync_checkpoint() {
  local op_id="$1" op_type="$2" env_id="$3" checkpoint="$4" legacy_file="${5:-}"
  soviez_ops_sync_apply "$op_id" "$op_type" "$env_id" "$checkpoint" "checkpoint" "{}" "$legacy_file"
}

soviez_ops_sync_heartbeat() {
  local op_id="$1"
  if declare -F soviez_ops_heartbeat_touch >/dev/null 2>&1; then
    soviez_ops_heartbeat_touch "$op_id" 2>/dev/null || true
  fi
  local path; path="$(soviez_ops_canonical_state_path "$op_id")"
  [[ -f "$path" ]] || return 0
  local updated
  updated="$(SOVIEZ_CUR="$(cat "$path")" SOVIEZ_NOW="$(soviez_ops_now_utc)" python3 - <<'PY'
import json,os
d=json.loads(os.environ["SOVIEZ_CUR"]); d["heartbeat_at"]=os.environ["SOVIEZ_NOW"]; d["updated_at"]=os.environ["SOVIEZ_NOW"]
print(json.dumps(d,separators=(",",":")))
PY
)"
  soviez_stage_inventory_atomic_write "$path" "$updated"
  soviez_ops_registry_register "$op_id" 2>/dev/null || true
}

soviez_ops_sync_retry() {
  local op_id="$1" op_type="$2" env_id="$3" legacy_file="${4:-}"
  soviez_ops_sync_apply "$op_id" "$op_type" "$env_id" "retry_scheduled" "retry" "{}" "$legacy_file"
}

soviez_ops_sync_cancel() {
  local op_id="$1" op_type="$2" env_id="$3" checkpoint="${4:-cancel_requested}" legacy_file="${5:-}"
  soviez_ops_sync_apply "$op_id" "$op_type" "$env_id" "$checkpoint" "cancel" "{}" "$legacy_file"
}

soviez_ops_sync_rollback() {
  local op_id="$1" op_type="$2" env_id="$3" checkpoint="${4:-rollback_running}" legacy_file="${5:-}"
  soviez_ops_sync_apply "$op_id" "$op_type" "$env_id" "$checkpoint" "rollback" "{}" "$legacy_file"
}

soviez_ops_sync_recovery() {
  local op_id="$1" op_type="$2" env_id="$3" checkpoint="${4:-recovery_required}" legacy_file="${5:-}"
  soviez_ops_sync_apply "$op_id" "$op_type" "$env_id" "$checkpoint" "recovery" "{}" "$legacy_file"
}

soviez_ops_sync_terminal() {
  local op_id="$1" op_type="$2" env_id="$3" outcome="${4:-completed}" legacy_file="${5:-}"
  soviez_ops_sync_apply "$op_id" "$op_type" "$env_id" "$outcome" "terminal" "{}" "$legacy_file"
}

soviez_ops_sync_from_legacy_file() {
  local op_id="$1" op_type="$2" legacy_file="$3" env_id="${4:-}" state
  [[ -f "$legacy_file" ]] || return 1
  state="$(soviez_json_get "$(cat "$legacy_file")" state 2>/dev/null || true)"
  [[ -n "$state" ]] || state="$(soviez_json_get "$(cat "$legacy_file")" ssl_state 2>/dev/null || true)"
  [[ -n "$state" ]] || state="$(soviez_json_get "$(cat "$legacy_file")" retention_status 2>/dev/null || true)"
  [[ -n "$env_id" ]] || env_id="$(soviez_json_get "$(cat "$legacy_file")" environment_id 2>/dev/null || true)"
  [[ -n "$env_id" ]] || env_id="$(soviez_json_get "$(cat "$legacy_file")" stage_id 2>/dev/null || true)"
  [[ -n "$state" ]] || state="running"
  soviez_ops_sync_apply "$op_id" "$op_type" "$env_id" "$state" "sync" "{}" "$legacy_file"
}

soviez_ops_sync_reconcile() {
  local op_id="$1" path legacy decision="OPERATION_SYNC_RECONCILED"
  path="$(soviez_ops_canonical_state_path "$op_id")"
  # Prefer legacy state file pointers
  local candidates=()
  candidates+=("$(soviez_operation_state_file "$op_id")")
  [[ -n "${SOVIEZ_STAGE_OPS_DIR:-}" ]] && candidates+=("$SOVIEZ_STAGE_OPS_DIR/$op_id/state.json")
  [[ -n "${SOVIEZ_SSL_OPS_DIR:-}" ]] && candidates+=("$SOVIEZ_SSL_OPS_DIR/$op_id/state.json")
  local f type="new" env=""
  for f in "${candidates[@]}"; do
    [[ -f "$f" ]] || continue
    legacy="$f"
    type="$(soviez_json_get "$(cat "$f")" kind 2>/dev/null || echo new)"
    case "$type" in stage) type=stage_create ;; ssl*) type=ssl_renewal ;; retention*) type=retention_delete ;; esac
    env="$(soviez_json_get "$(cat "$f")" environment_id 2>/dev/null || true)"
    break
  done
  if [[ -z "${legacy:-}" ]]; then
    # Retention: scan by retention_operation_id is expensive; rely on meta path
    if [[ -f "$path" ]]; then
      local meta_path
      meta_path="$(SOVIEZ_CUR="$(cat "$path")" python3 - <<'PY'
import json,os
d=json.loads(os.environ["SOVIEZ_CUR"]); print((d.get("meta") or {}).get("legacy_state_path") or "")
PY
)"
      [[ -f "$meta_path" ]] && legacy="$meta_path"
      type="$(soviez_json_get "$(cat "$path")" operation_type)"
      env="$(soviez_json_get "$(cat "$path")" environment_id)"
    fi
  fi
  if [[ -n "${legacy:-}" && -f "$legacy" ]]; then
    if soviez_ops_sync_from_legacy_file "$op_id" "$type" "$legacy" "$env"; then
      soviez_ops_append_event "$op_id" "reconcile" "canonical repaired from legacy" "{}" 2>/dev/null || true
      printf '%s\n' "$decision"
      return 0
    fi
    printf 'OPERATION_SYNC_RECOVERY_REQUIRED\n'
    return 1
  fi
  if [[ -f "$path" ]]; then
    soviez_ops_registry_register "$op_id" 2>/dev/null || true
    printf '%s\n' "$decision"
    return 0
  fi
  printf 'OPERATION_SYNC_RECOVERY_REQUIRED\n'
  return 1
}

# --- end ops/sync.sh ---

# --- begin ops/registry.sh ---
# shellcheck shell=bash

soviez_ops_registry_register() {
  local op_id="$1" canonical summary
  canonical="$(soviez_ops_canonical_state_path "$op_id")"; [[ -f "$canonical" ]] || soviez_ops_die OPERATION_NOT_FOUND "Unknown operation: $op_id"
  summary="$(SOVIEZ_CANONICAL="$(cat "$canonical")" SOVIEZ_PATH="$canonical" python3 - <<'PY'
import json, os
d=json.loads(os.environ["SOVIEZ_CANONICAL"])
keys=("operation_id","operation_type","environment_id","current_state","current_checkpoint","updated_at","heartbeat_at",
      "canonical_sync_status","canonical_state_revision","registry_revision","sequence")
out={k:d.get(k) for k in keys}
out["canonical_path"]=os.environ["SOVIEZ_PATH"]
out["registry_revision"]=d.get("registry_revision") or d.get("canonical_state_revision") or d.get("sequence") or 0
print(json.dumps(out,separators=(",",":")))
PY
)"
  soviez_stage_inventory_atomic_write "$(soviez_ops_registry_index_path "$op_id")" "$summary"
}
soviez_ops_registry_unregister() { rm -f "$(soviez_ops_registry_index_path "$1")"; }
soviez_ops_registry_get() { cat "$(soviez_ops_registry_index_path "$1")" 2>/dev/null || soviez_ops_die OPERATION_NOT_FOUND "Unknown operation: $1"; }
soviez_ops_registry_list() {
  local flag="${1:-}" value="${2:-}" f record state
  for f in "$SOVIEZ_OPS_INDEX_DIR"/*.json; do
    [[ -f "$f" ]] || continue; record="$(cat "$f")"; state="$(soviez_json_get "$record" current_state)"
    case "$flag" in --active) [[ "$state" =~ ^(completed|canceled|failed_terminal)$ ]] && continue ;; --failed) [[ "$state" == failed_* || "$state" == recovery_required ]] || continue ;; --environment) [[ "$(soviez_json_get "$record" environment_id)" == "$value" ]] || continue ;; --type) [[ "$(soviez_json_get "$record" operation_type)" == "$value" ]] || continue ;; esac
    printf '%s\n' "$record"
  done
}
soviez_ops_registry_reconcile_index() {
  local dir canonical
  for dir in "$SOVIEZ_OPS_ROOT/operations"/* "$SOVIEZ_STAGE_OPS_DIR"/* "$SOVIEZ_SSL_OPS_DIR"/*; do
    [[ -d "$dir" ]] || continue; canonical="$dir/$SOVIEZ_OPS_CANONICAL_NAME"
    [[ -f "$canonical" ]] || soviez_ops_migrate_one "$dir" >/dev/null 2>&1 || continue
    soviez_ops_registry_register "$(soviez_json_get "$(cat "$canonical")" operation_id)"
  done
}

# --- end ops/registry.sh ---

# --- begin ops/reconciliation.sh ---
# shellcheck shell=bash

soviez_ops_reconcile_one() {
  local op_id="$1" record state pid unit host
  # Prefer sync repair when pending/stale
  if declare -F soviez_ops_sync_is_pending >/dev/null 2>&1 && soviez_ops_sync_is_pending "$op_id"; then
    if declare -F soviez_ops_sync_reconcile >/dev/null 2>&1; then
      if soviez_ops_sync_reconcile "$op_id" >/dev/null; then
        printf 'OPERATION_SYNC_RECONCILED\n'
        return 0
      fi
      printf 'recovery_required\n'
      return 0
    fi
  fi

  record="$(cat "$(soviez_ops_canonical_state_path "$op_id")" 2>/dev/null || true)"
  if [[ -z "$record" ]]; then
    if declare -F soviez_ops_sync_reconcile >/dev/null 2>&1 && soviez_ops_sync_reconcile "$op_id" >/dev/null; then
      printf 'OPERATION_SYNC_RECONCILED\n'
      return 0
    fi
    if [[ -f "$(soviez_operation_state_file "$op_id" 2>/dev/null || true)" ]] || [[ -d "$(soviez_ops_resolve_dir "$op_id")" ]]; then
      soviez_ops_migrate_one "$op_id" 2>/dev/null || true
      record="$(cat "$(soviez_ops_canonical_state_path "$op_id")" 2>/dev/null || true)"
    fi
  fi
  [[ -n "$record" ]] || { printf 'recovery_required\n'; return 0; }

  # Repair registry if canonical newer
  local idx rev_c rev_i
  idx="$(soviez_ops_registry_index_path "$op_id")"
  rev_c="$(soviez_json_get "$record" canonical_state_revision 2>/dev/null || echo 0)"
  if [[ -f "$idx" ]]; then
    rev_i="$(soviez_json_get "$(cat "$idx")" registry_revision 2>/dev/null || soviez_json_get "$(cat "$idx")" sequence 2>/dev/null || echo 0)"
    if [[ "${rev_c:-0}" -gt "${rev_i:-0}" ]]; then
      soviez_ops_registry_register "$op_id" 2>/dev/null || true
    fi
  else
    soviez_ops_registry_register "$op_id" 2>/dev/null || true
  fi

  state="$(soviez_json_get "$record" current_state)"
  pid="$(soviez_json_get "$record" worker_pid 2>/dev/null || true)"
  unit="$(soviez_json_get "$record" systemd_unit 2>/dev/null || true)"
  host="$(soviez_json_get "$record" host_identity 2>/dev/null || true)"
  if [[ -n "$host" && "$host" != "unknown" ]]; then
    local here; here="$(hostname -f 2>/dev/null || hostname || echo unknown)"
    if [[ "$host" != "$here" && "$host" != "$(hostname 2>/dev/null || true)" ]]; then
      printf 'recovery_required\n'
      return 0
    fi
  fi

  case "$state" in
    completed|canceled|failed_terminal)
      printf 'cleanup_terminal_metadata\n'
      return 0
      ;;
    recovery_required)
      printf 'recovery_required\n'
      return 0
      ;;
    failed_retryable|retry_scheduled)
      printf 'retry_scheduled\n'
      return 0
      ;;
  esac

  if [[ -n "$pid" && "$pid" != "null" && "$pid" != "0" ]]; then
    if kill -0 "$pid" 2>/dev/null; then
      local cmdline
      cmdline="$(ps -p "$pid" -o args= 2>/dev/null || true)"
      if [[ -n "$cmdline" ]] && ! printf '%s' "$cmdline" | grep -Eqi 'soviez|bash|systemd'; then
        printf 'recovery_required\n'
        return 0
      fi
      printf 'healthy\n'
      return 0
    fi
    if soviez_ops_heartbeat_stale "$op_id"; then
      case "$state" in
        running|starting)
          local cp; cp="$(soviez_json_get "$record" current_checkpoint)"
          case "$cp" in
            *delete*|*drop*|*restore*|*promote*|*tenant_identity*)
              printf 'recovery_required\n'
              ;;
            *)
              printf 'resume_safe\n'
              ;;
          esac
          return 0
          ;;
      esac
    fi
    printf 'attach_existing\n'
    return 0
  fi

  if [[ -n "$unit" && "$unit" != "null" ]] && command -v systemctl >/dev/null 2>&1; then
    if systemctl is-active --quiet "$unit" 2>/dev/null; then
      printf 'attach_existing\n'
      return 0
    fi
  fi
  if soviez_ops_heartbeat_stale "$op_id"; then
    printf 'resume_safe\n'
  else
    printf 'attach_existing\n'
  fi
}

soviez_ops_reconcile_all() {
  local f
  for f in "$SOVIEZ_OPS_INDEX_DIR"/*.json; do
    [[ -f "$f" ]] || continue
    printf '%s %s\n' "$(soviez_json_get "$(cat "$f")" operation_id)" "$(soviez_ops_reconcile_one "$(soviez_json_get "$(cat "$f")" operation_id)")"
  done
}

# --- end ops/reconciliation.sh ---

# --- begin ops/adapters.sh ---
# shellcheck shell=bash

# Adapter metadata deliberately delegates execution to existing Phase 8/11/12/13 engines.
soviez_ops_adapter_types() { printf '%s\n' new stage_create ssl_renewal ssl_repair retention_delete production_update update_image_cleanup production_backup backup_verification backup_restore_test production_restore backup_retention_cleanup backup_export backup_import; }
soviez_ops_adapter_resource_scopes() {
  local type="$1" env="$2"
  case "$type" in
    ssl_renewal|ssl_repair) printf 'nginx:%s\n' "$env" ;;
    retention_delete) printf 'env:%s\ndb:stage_%s\n' "$env" "${env//-/_}" ;;
    production_update) printf 'env:%s\ndb:prod_%s\nfilestore:prod_%s\nruntime:prod_%s\n' "$env" "$env" "$env" "$env" ;;
    update_image_cleanup) printf 'image:soviez_erp\nenv:%s\n' "$env" ;;
    production_backup|backup_verification|backup_restore_test|production_restore|backup_export|backup_import)
      printf 'env:%s\ndb:prod_%s\nfilestore:prod_%s\nbackup:prod_%s\n' "$env" "$env" "$env" "$env" ;;
    backup_retention_cleanup) printf 'backup:host\nenv:%s\n' "$env" ;;
    *) printf 'env:%s\n' "$env" ;;
  esac
}
soviez_ops_adapter_cancel_boundary() {
  local type="$1" checkpoint="$2"
  case "$type:$checkpoint" in
    retention_delete:delete_*|stage_create:database_restore|new:tenant_identity_created|production_update:switching|production_update:validating_production|update_image_cleanup:deleting|production_restore:switching|production_restore:validating_production)
      printf 'irreversible\n'
      ;;
    ssl_renewal:promote_*|ssl_repair:promote_*|retention_delete:nginx_*|stage_create:nginx_*|production_update:upgrading_candidate|production_update:creating_backup|production_update:preparing_candidate|production_restore:restoring_*|production_backup:backing_up_*|production_backup:quiescing_application)
      printf 'rollback\n'
      ;;
    update_image_cleanup:*|backup_retention_cleanup:*)
      printf 'cancelable\n'
      ;;
    *)
      printf 'cancelable\n'
      ;;
  esac
}

soviez_ops_adapter_reattach() {
  local op_id="$1" type="$2"
  case "$type" in
    new) SOVIEZ_CLI_OP_ID="$op_id" soviez_cmd_reattach_run ;;
    stage_create|stage_lifecycle) SOVIEZ_CLI_OP_ID="$op_id" soviez_cmd_stage_create_run ;;
    ssl_renewal|ssl_repair) soviez_cmd_ssl_reattach "$op_id" ;;
    production_update) SOVIEZ_CLI_OP_ID="$op_id" soviez_cmd_update_reattach "$op_id" ;;
    update_image_cleanup) soviez_image_cleanup_scheduler_tick ;;
    production_backup|backup_verification|backup_restore_test|backup_export|backup_import)
      SOVIEZ_CLI_OP_ID="$op_id" soviez_cmd_backup_status "$op_id" ;;
    production_restore)
      SOVIEZ_CLI_OP_ID="$op_id" soviez_cmd_restore_status "$op_id" ;;
    backup_retention_cleanup)
      if declare -F soviez_backup_retention_cleanup >/dev/null 2>&1; then
        soviez_backup_retention_cleanup 1 "" 0
      fi
      ;;
    retention_delete)
      if declare -F soviez_cmd_stage_retention_reattach >/dev/null 2>&1; then
        soviez_cmd_stage_retention_reattach "$op_id"
      else
        local env_id
        env_id="$(soviez_json_get "$(cat "$(soviez_ops_canonical_state_path "$op_id")")" environment_id)"
        soviez_retention_retry "$env_id"
      fi
      ;;
    *) soviez_ops_worker_reattach "$op_id" || true ;;
  esac
}

# --- end ops/adapters.sh ---

# --- begin ops/cancellation.sh ---
# shellcheck shell=bash

soviez_ops_cancel() {
  local op_id="$1" reason="${2:-Canceled by operator}" yes="${3:-}" record state checkpoint boundary type
  record="$(cat "$(soviez_ops_canonical_state_path "$op_id")")" || soviez_ops_die OPERATION_NOT_FOUND "Unknown operation: $op_id"
  state="$(soviez_json_get "$record" current_state)"
  checkpoint="$(soviez_json_get "$record" current_checkpoint)"
  type="$(soviez_json_get "$record" operation_type)"
  case "$state" in
    completed|canceled|failed_terminal)
      soviez_ops_die OPERATION_ALREADY_TERMINAL "Operation already terminal: $state"
      ;;
    created|queued|waiting|retry_scheduled)
      soviez_ops_transition "$op_id" canceled "$checkpoint"
      soviez_ops_ok OPERATION_CANCEL_ACCEPTED "Canceled before protected work"
      ;;
    running|starting|cancel_requested)
      boundary="$(soviez_ops_adapter_cancel_boundary "$type" "$checkpoint")"
      if [[ "$boundary" == "irreversible" ]]; then
        soviez_ops_die OPERATION_CANCEL_NOT_ALLOWED "Checkpoint is irreversible: $checkpoint"
      fi
      if [[ "$boundary" == "rollback" && "$yes" != "--yes" && "$yes" != "yes" ]]; then
        soviez_ops_die OPERATION_CANCEL_REQUIRES_CONFIRMATION "Cancel requires rollback confirmation (--yes)"
      fi
      soviez_ops_transition "$op_id" cancel_requested "$checkpoint"
      if [[ "$boundary" == "rollback" ]]; then
        soviez_ops_transition "$op_id" canceling "$checkpoint"
        soviez_ops_transition "$op_id" rollback_running "$checkpoint"
        soviez_ops_ok OPERATION_CANCEL_ROLLBACK_STARTED "Rollback started"
      else
        soviez_ops_ok OPERATION_CANCEL_ACCEPTED "Cancel requested; waiting for safe boundary"
      fi
      ;;
    *)
      soviez_ops_die OPERATION_CANCEL_NOT_ALLOWED "Cannot cancel state: $state"
      ;;
  esac
}

# --- end ops/cancellation.sh ---

# --- begin ops/retry.sh ---
# shellcheck shell=bash

soviez_ops_retry() {
  local op_id="$1" yes="${2:-}" path record state updated
  path="$(soviez_ops_canonical_state_path "$op_id")"; record="$(cat "$path")" || soviez_ops_die OPERATION_NOT_FOUND "Unknown operation: $op_id"
  state="$(soviez_json_get "$record" current_state)"
  [[ "$state" == failed_retryable || "$state" == recovery_required ]] || soviez_ops_die OPERATION_RETRY_NOT_ALLOWED "Retry not permitted for $state"
  updated="$(SOVIEZ_REC="$record" python3 - <<'PY'
import json,os
d=json.loads(os.environ["SOVIEZ_REC"]); d["retry_count"]=int(d.get("retry_count",0))+1; print(json.dumps(d,separators=(",",":")))
PY
)"
  soviez_stage_inventory_atomic_write "$path" "$updated"
  soviez_ops_transition "$op_id" retry_scheduled
  soviez_ops_transition "$op_id" starting
}

# --- end ops/retry.sh ---

# --- begin ops/recovery.sh ---
# shellcheck shell=bash

soviez_ops_recover() {
  local op_id="$1" yes="${2:-}" decision
  decision="$(soviez_ops_reconcile_one "$op_id")"
  case "$decision" in
    healthy|attach_existing) soviez_ops_ok "$decision" "Operation has an active worker" ;;
    resume_safe|retry_scheduled) soviez_ops_retry "$op_id" "$yes" ;;
    recovery_required) soviez_ops_ok recovery_required "Inspect resources; destructive recovery requires --yes" ;;
    cleanup_terminal_metadata) soviez_ops_history_append "$op_id"; soviez_ops_ok cleanup_terminal_metadata "History preserved" ;;
    *) soviez_ops_die OPERATION_RECOVERY_REQUIRED "Unable to reconcile operation" ;;
  esac
}

# --- end ops/recovery.sh ---

# --- begin ops/scheduler.sh ---
# shellcheck shell=bash

soviez_ops_scheduler_lock_acquire() { soviez_ops_lock_acquire "soviez-scheduler" "$(soviez_ops_lock_id host scheduler)"; }
soviez_ops_scheduler_lock_release() { soviez_ops_lock_release "soviez-scheduler" "$(soviez_ops_lock_id host scheduler)"; }

soviez_ops_scheduler_reconcile_pending() {
  local f op_id
  for f in "$SOVIEZ_OPS_INDEX_DIR"/*.json; do
    [[ -f "$f" ]] || continue
    op_id="$(soviez_json_get "$(cat "$f")" operation_id 2>/dev/null || true)"
    [[ -n "$op_id" ]] || continue
    if soviez_ops_sync_is_pending "$op_id" 2>/dev/null; then
      soviez_ops_sync_reconcile "$op_id" >/dev/null 2>&1 || true
    fi
  done
  # Also scan sync_pending markers under operations/
  local marker
  for marker in "$SOVIEZ_OPS_ROOT/operations"/*/sync_pending.json; do
    [[ -f "$marker" ]] || continue
    op_id="$(basename "$(dirname "$marker")")"
    soviez_ops_sync_reconcile "$op_id" >/dev/null 2>&1 || true
  done
}

soviez_ops_scheduler_coordinate() {
  # Priority: recovery/sync repair, then SSL monitoring, then retention.
  soviez_ops_scheduler_lock_acquire
  soviez_ops_scheduler_reconcile_pending
  if declare -F soviez_ssl_monitor_apply >/dev/null 2>&1 && declare -F soviez_ssl_inventory_list_ids >/dev/null 2>&1; then
    local eid
    while IFS= read -r eid; do
      [[ -n "$eid" ]] || continue
      # Skip if an active/pending SSL op already owns this environment
      local skip=0 rec
      for rec in $(soviez_ops_registry_list --type ssl_renewal 2>/dev/null || true); do
        :
      done
      while IFS= read -r rec; do
        [[ -n "$rec" ]] || continue
        [[ "$(soviez_json_get "$rec" environment_id)" == "$eid" ]] || continue
        case "$(soviez_json_get "$rec" current_state)" in
          completed|canceled|failed_terminal) continue ;;
          *)
            if soviez_ops_sync_is_pending "$(soviez_json_get "$rec" operation_id)" 2>/dev/null; then
              soviez_ops_sync_reconcile "$(soviez_json_get "$rec" operation_id)" >/dev/null 2>&1 || true
              skip=1
            else
              skip=1
            fi
            ;;
        esac
      done < <(soviez_ops_registry_list --type ssl_renewal 2>/dev/null || true)
      [[ "$skip" == "1" ]] && continue
      ( soviez_ssl_monitor_apply "$eid" >/dev/null ) || true
    done < <(soviez_ssl_inventory_list_ids 2>/dev/null || true)
  fi
  if declare -F soviez_retention_scheduler_scan >/dev/null 2>&1; then
    ( soviez_retention_scheduler_scan ) || true
  fi
  if declare -F soviez_backup_schedule_tick >/dev/null 2>&1; then
    ( soviez_backup_schedule_tick ) || true
  fi
  if declare -F soviez_backup_retention_cleanup >/dev/null 2>&1 && [[ "${SOVIEZ_BACKUP_AUTO_RETENTION:-0}" == "1" ]]; then
    ( soviez_backup_retention_cleanup 1 "" 0 ) || true
  fi
  soviez_ops_scheduler_lock_release
}

# --- end ops/scheduler.sh ---

# --- begin ops/workers.sh ---
# shellcheck shell=bash

soviez_ops_worker_identity() {
  local op_id="$1"
  printf 'soviez-worker:%s:%s\n' "$op_id" "$(soviez_json_get "$(cat "$(soviez_ops_canonical_state_path "$op_id")")" worker_generation 2>/dev/null || echo 0)"
}

soviez_ops_worker_reattach() {
  local op_id="$1" decision
  decision="$(soviez_ops_reconcile_one "$op_id")"
  case "$decision" in
    healthy|attach_existing)
      soviez_ops_print_status "$op_id"
      soviez_ops_log_tail "$op_id" 50 || true
      ;;
    resume_safe)
      soviez_ops_print_status "$op_id"
      printf 'Reconcile: resume_safe — use --operation-retry or command-specific reattach\n'
      ;;
    recovery_required)
      soviez_ops_die OPERATION_RECOVERY_REQUIRED "Reattach unavailable; recovery required for $op_id"
      ;;
    *)
      soviez_ops_print_status "$op_id"
      ;;
  esac
}

# --- end ops/workers.sh ---

# --- begin ops/systemd.sh ---
# shellcheck shell=bash

# Shared systemd worker contract. Command engines retain their proven unit
# renderers; this module standardizes naming, env hygiene, and cleanup policy.

soviez_ops_systemd_unit_name() {
  local op_id="$1"
  op_id="$(printf '%s' "$op_id" | tr '[:upper:]' '[:lower:]' | tr -cd 'a-z0-9._-')"
  printf 'soviez-op-%s.service\n' "$op_id"
}

soviez_ops_systemd_env_file() {
  printf '%s/worker.env\n' "$(soviez_ops_resolve_dir "$1")"
}

# Write a restricted EnvironmentFile: never secrets, only operation identity paths.
soviez_ops_systemd_write_env() {
  local op_id="$1" path
  path="$(soviez_ops_systemd_env_file "$op_id")"
  cat > "$path" <<EOF
SOVIEZ_OPERATION_ID=$op_id
SOVIEZ_OPS_CANONICAL=$(soviez_ops_canonical_state_path "$op_id")
SOVIEZ_OPS_ROOT=$SOVIEZ_OPS_ROOT
EOF
  chmod 600 "$path"
}

soviez_ops_systemd_cleanup_terminal() {
  local op_id="$1" unit
  unit="$(soviez_ops_systemd_unit_name "$op_id")"
  if command -v systemctl >/dev/null 2>&1; then
    systemctl stop "$unit" 2>/dev/null || true
    systemctl disable "$unit" 2>/dev/null || true
    rm -f "/etc/systemd/system/$unit" 2>/dev/null || true
  fi
}

# --- end ops/systemd.sh ---

# --- begin ops/logs.sh ---
# shellcheck shell=bash

soviez_ops_log_path() { printf '%s/operation.log\n' "$(soviez_ops_resolve_dir "$1")"; }
soviez_ops_log_append() {
  local op_id="$1"; shift
  local path; path="$(soviez_ops_log_path "$op_id")"; mkdir -p "$(dirname "$path")"
  printf '%s %s\n' "$(soviez_ops_now_utc)" "$(soviez_redact_text "$*")" >> "$path"; chmod 600 "$path"
}
soviez_ops_log_tail() {
  local op_id="$1" n="${2:-50}" path; path="$(soviez_ops_log_path "$op_id")"
  [[ -f "$path" ]] && tail -n "$n" "$path"
}

# --- end ops/logs.sh ---

# --- begin ops/cli_helpers.sh ---
# shellcheck shell=bash

soviez_ops_print_status() {
  local op_id="$1" record path
  path="$(soviez_ops_canonical_state_path "$op_id")"
  if [[ -f "$path" ]]; then record="$(cat "$path")"
  else record="$(soviez_ops_registry_get "$op_id")"
  fi
  if [[ "${SOVIEZ_OPS_JSON:-0}" == "1" ]]; then printf '%s\n' "$record"
  else
    printf 'Operation: %s\nType: %s\nEnvironment: %s\nState: %s\nCheckpoint: %s\nUpdated: %s\nHeartbeat: %s\nLog: %s\n' \
      "$(soviez_json_get "$record" operation_id)" "$(soviez_json_get "$record" operation_type)" \
      "$(soviez_json_get "$record" environment_id)" "$(soviez_json_get "$record" current_state)" \
      "$(soviez_json_get "$record" current_checkpoint)" "$(soviez_json_get "$record" updated_at)" \
      "$(soviez_json_get "$record" heartbeat_at)" "$(soviez_ops_log_path "$op_id" 2>/dev/null || true)"
  fi
}

# --- end ops/cli_helpers.sh ---

# --- begin update/codes.sh ---
# shellcheck shell=bash

SOVIEZ_ERR_UPDATE=23
SOVIEZ_UPDATE_SAFETY_WINDOW_HOURS="${SOVIEZ_UPDATE_SAFETY_WINDOW_HOURS:-24}"
SOVIEZ_UPDATE_OP_TYPE=production_update

soviez_utc_now() { date -u +%Y-%m-%dT%H:%M:%SZ; }
soviez_rand_hex() {
  local n="${1:-4}"
  if command -v openssl >/dev/null 2>&1; then
    openssl rand -hex "$n" | head -c $((n * 2))
    return 0
  fi
  python3 -c "import secrets; print(secrets.token_hex(int('$n')))"
}

SOVIEZ_UPDATE_CODES=(
  UPDATE_TARGET_REQUIRED
  UPDATE_TARGET_INVALID
  UPDATE_TARGET_AMBIGUOUS
  UPDATE_STAGE_TARGET_DENIED
  UPDATE_PRODUCTION_IDENTITY_MISMATCH
  UPDATE_LICENSE_BINDING_MISMATCH
  UPDATE_DATABASE_UUID_MISMATCH
  UPDATE_HOST_IDENTITY_MISMATCH
  UPDATE_IDENTITY_MISMATCH
  UPDATE_CAPABILITY_REQUIRED
  UPDATE_CAPABILITY_EXPIRED
  UPDATE_MONTHLY_SUPPORT_DENIED
  UPDATE_UNBOUND_GRANT_DENIED
  UPDATE_WRONG_LICENSE
  UPDATE_WRONG_ACCOUNT
  UPDATE_GRANT_REVOKED
  UPDATE_OFFLINE_ENTITLEMENT_INVALID
  UPDATE_ENTITLEMENT_UNAVAILABLE
  UPDATE_RELEASE_NOT_FOUND
  UPDATE_RELEASE_UNSIGNED
  UPDATE_RELEASE_SIGNATURE_INVALID
  UPDATE_RELEASE_DIGEST_MISSING
  UPDATE_RELEASE_DIGEST_MISMATCH
  UPDATE_RELEASE_ARCH_MISMATCH
  UPDATE_RELEASE_INCOMPATIBLE
  UPDATE_RELEASE_DOWNGRADE_DENIED
  UPDATE_ALREADY_CURRENT
  UPDATE_PREFLIGHT_BLOCKED
  UPDATE_DISK_INSUFFICIENT
  UPDATE_INODES_INSUFFICIENT
  UPDATE_MEMORY_INSUFFICIENT
  UPDATE_BACKUP_CAPACITY_INSUFFICIENT
  UPDATE_WORKSPACE_CAPACITY_INSUFFICIENT
  UPDATE_BACKUP_FAILED
  UPDATE_BACKUP_INVALID
  UPDATE_BACKUP_INCONSISTENT
  UPDATE_ROLLBACK_SET_INCOMPLETE
  UPDATE_CANDIDATE_CREATE_FAILED
  UPDATE_CANDIDATE_UPGRADE_FAILED
  UPDATE_CANDIDATE_VALIDATION_FAILED
  UPDATE_LICENSE_VALIDATION_FAILED
  UPDATE_SWITCH_FAILED
  UPDATE_POST_SWITCH_VALIDATION_FAILED
  UPDATE_POST_VALIDATION_FAILED
  UPDATE_ROLLBACK_COMPLETED
  UPDATE_ROLLBACK_REQUIRED
  UPDATE_ROLLBACK_FAILED
  UPDATE_RECOVERY_REQUIRED
  UPDATE_CONFLICT
  UPDATE_CANCELLATION_NOT_SAFE
  UPDATE_OFFLINE_PACKAGE_INVALID
  DESTRUCTIVE_CONFIRMATION_REQUIRED
)

soviez_update_die() {
  local code="${1:-UPDATE_RECOVERY_REQUIRED}" message="${2:-Update failed}"
  soviez_log_error "${code}: ${message}"
  SOVIEZ_UPD_CODE="$code" SOVIEZ_UPD_MSG="$(soviez_redact_text "$message")" python3 - <<'PY' >&2
import json, os
print(json.dumps({"ok": False, "code": os.environ["SOVIEZ_UPD_CODE"],
                  "message": os.environ["SOVIEZ_UPD_MSG"]}, separators=(",", ":")))
PY
  exit "$SOVIEZ_ERR_UPDATE"
}

soviez_update_ok() {
  local code="${1:-OK}" message="${2:-OK}"
  SOVIEZ_UPD_CODE="$code" SOVIEZ_UPD_MSG="$(soviez_redact_text "$message")" python3 - <<'PY'
import json, os
print(json.dumps({"ok": True, "code": os.environ["SOVIEZ_UPD_CODE"],
                  "message": os.environ["SOVIEZ_UPD_MSG"]}, separators=(",", ":")))
PY
}

# --- end update/codes.sh ---

# --- begin update/paths.sh ---
# shellcheck shell=bash

soviez_update_paths_init() {
  : "${SOVIEZ_OPS_ROOT:?soviez_paths_init must run first}"
  SOVIEZ_UPDATE_ROOT="${SOVIEZ_UPDATE_ROOT:-$SOVIEZ_OPS_ROOT/updates}"
  SOVIEZ_UPDATE_OPS_DIR="${SOVIEZ_UPDATE_OPS_DIR:-$SOVIEZ_UPDATE_ROOT/operations}"
  SOVIEZ_UPDATE_CANDIDATES_DIR="${SOVIEZ_UPDATE_CANDIDATES_DIR:-$SOVIEZ_UPDATE_ROOT/candidates}"
  SOVIEZ_UPDATE_BACKUPS_DIR="${SOVIEZ_UPDATE_BACKUPS_DIR:-$SOVIEZ_UPDATE_ROOT/backups}"
  SOVIEZ_UPDATE_PACKAGES_DIR="${SOVIEZ_UPDATE_PACKAGES_DIR:-$SOVIEZ_UPDATE_ROOT/packages}"
  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    SOVIEZ_UPDATE_ROOT="$SOVIEZ_ROOT/updates"
    SOVIEZ_UPDATE_OPS_DIR="$SOVIEZ_UPDATE_ROOT/operations"
    SOVIEZ_UPDATE_CANDIDATES_DIR="$SOVIEZ_UPDATE_ROOT/candidates"
    SOVIEZ_UPDATE_BACKUPS_DIR="$SOVIEZ_UPDATE_ROOT/backups"
    SOVIEZ_UPDATE_PACKAGES_DIR="$SOVIEZ_UPDATE_ROOT/packages"
  fi
  export SOVIEZ_UPDATE_ROOT SOVIEZ_UPDATE_OPS_DIR SOVIEZ_UPDATE_CANDIDATES_DIR SOVIEZ_UPDATE_BACKUPS_DIR SOVIEZ_UPDATE_PACKAGES_DIR
  mkdir -p "$SOVIEZ_UPDATE_OPS_DIR" "$SOVIEZ_UPDATE_CANDIDATES_DIR" "$SOVIEZ_UPDATE_BACKUPS_DIR" "$SOVIEZ_UPDATE_PACKAGES_DIR"
  chmod 700 "$SOVIEZ_UPDATE_ROOT" "$SOVIEZ_UPDATE_OPS_DIR" "$SOVIEZ_UPDATE_CANDIDATES_DIR" "$SOVIEZ_UPDATE_BACKUPS_DIR" "$SOVIEZ_UPDATE_PACKAGES_DIR"
}

soviez_update_op_dir() { printf '%s/%s\n' "$SOVIEZ_UPDATE_OPS_DIR" "$1"; }
soviez_update_op_state_file() { printf '%s/state.json\n' "$(soviez_update_op_dir "$1")"; }
soviez_update_candidate_dir() { printf '%s/%s\n' "$SOVIEZ_UPDATE_CANDIDATES_DIR" "$1"; }
soviez_update_backup_dir() { printf '%s/%s\n' "$SOVIEZ_UPDATE_BACKUPS_DIR" "$1"; }
soviez_update_rollback_manifest() { printf '%s/rollback_manifest.json\n' "$(soviez_update_backup_dir "$1")"; }

# --- end update/paths.sh ---

# --- begin update/targeting.sh ---
# shellcheck shell=bash

soviez_update_refuse_wildcard() {
  local target="$1"
  case "$target" in
    ""|"all"|"*"|"."|"..")
      return 0
      ;;
  esac
  [[ "$target" == *"*"* || "$target" == *"?"* ]] && return 0
  return 1
}

soviez_update_is_stage_id() {
  local target="$1"
  if declare -F soviez_stage_inventory_find >/dev/null 2>&1; then
    soviez_stage_inventory_find "$target" >/dev/null 2>&1 && return 0
  fi
  [[ -d "${SOVIEZ_STAGES_DIR:-}/$target" ]] && return 0
  return 1
}

soviez_update_resolve_target() {
  local target="${1:-}"
  if [[ -z "$target" ]]; then
    soviez_update_die UPDATE_TARGET_REQUIRED "Exact Production environment ID required"
  fi
  if soviez_update_refuse_wildcard "$target"; then
    soviez_update_die UPDATE_TARGET_INVALID "Wildcard/all/implicit targeting is refused"
  fi
  if soviez_update_is_stage_id "$target"; then
    soviez_update_die UPDATE_STAGE_TARGET_DENIED "Stage targets cannot be updated with --update"
  fi

  local listing prod
  listing="$(soviez_stage_list_productions)"
  prod="$(SOVIEZ_L="$listing" SOVIEZ_T="$target" python3 - <<'PY'
import json, os, sys
prods=json.loads(os.environ["SOVIEZ_L"]).get("productions",[])
matches=[p for p in prods if p.get("tenant_id")==os.environ["SOVIEZ_T"] or p.get("environment_id")==os.environ["SOVIEZ_T"]]
if len(matches)==0:
    # Allow explicit fixture identity path under tenant dir
    sys.exit(3)
if len(matches)>1:
    sys.exit(2)
print(json.dumps(matches[0], separators=(",",":")))
PY
)" || {
    local rc=$?
    case "$rc" in
      2) soviez_update_die UPDATE_TARGET_AMBIGUOUS "Multiple Productions match: $target" ;;
      3)
        if [[ -n "${SOVIEZ_UPDATE_FIXTURE_PRODUCTION_JSON:-}" ]]; then
          local ft
          ft="$(soviez_json_get "$SOVIEZ_UPDATE_FIXTURE_PRODUCTION_JSON" tenant_id 2>/dev/null || true)"
          [[ "$ft" == "$target" ]] || soviez_update_die UPDATE_TARGET_INVALID "Unknown Production: $target"
          printf '%s' "$SOVIEZ_UPDATE_FIXTURE_PRODUCTION_JSON"
          return 0
        fi
        # Load from tenant identity if path exists
        local idf="${SOVIEZ_TENANT_DIR:-}/$target/identity.json"
        [[ -f "$idf" ]] || idf="${SOVIEZ_TENANT_DIR:-}/identity.json"
        if [[ -f "$idf" ]]; then
          local loaded tid
          loaded="$(cat "$idf")"
          tid="$(soviez_json_get "$loaded" tenant_id 2>/dev/null || true)"
          [[ "$tid" == "$target" || "$(basename "$(dirname "$idf")")" == "$target" || "$(dirname "$idf")" == "${SOVIEZ_TENANT_DIR:-}" ]] \
            || soviez_update_die UPDATE_TARGET_INVALID "Unknown Production: $target"
          # Normalize
          SOVIEZ_ID="$loaded" SOVIEZ_T="$target" python3 - <<'PY'
import json,os
d=json.loads(os.environ["SOVIEZ_ID"])
d["tenant_id"]=d.get("tenant_id") or os.environ["SOVIEZ_T"]
d["environment_id"]=d.get("environment_id") or d["tenant_id"]
print(json.dumps(d,separators=(",",":")))
PY
          return 0
        fi
        soviez_update_die UPDATE_TARGET_INVALID "Unknown Production: $target"
        ;;
      *) soviez_update_die UPDATE_TARGET_INVALID "Failed to resolve Production: $target" ;;
    esac
  }
  # Enrich from full identity.json when available
  local idp
  idp="$(soviez_json_get "$prod" identity_path 2>/dev/null || true)"
  if [[ -n "$idp" && -f "$idp" ]]; then
    prod="$(SOVIEZ_BASE="$prod" SOVIEZ_ID="$(cat "$idp")" python3 - <<'PY'
import json,os
base=json.loads(os.environ["SOVIEZ_BASE"])
full=json.loads(os.environ["SOVIEZ_ID"])
for k,v in full.items():
  if v is not None and (k not in base or base.get(k) in (None,"",[])):
    base[k]=v
  elif k in ("current_digest","image_digest","database_path","filestore_path","addons_path","account_id","erp_major","host_identity","nginx_config_ref","cert_ref","database_bytes","filestore_bytes","image_bytes"):
    base[k]=v
base["tenant_id"]=base.get("tenant_id") or full.get("tenant_id")
base["environment_id"]=base.get("environment_id") or base["tenant_id"]
print(json.dumps(base,separators=(",",":")))
PY
)"
  fi
  printf '%s' "$prod"
}

soviez_update_verify_identity() {
  local prod_json="$1" host_now
  local license_id db_uuid fingerprint container prod_status
  license_id="$(soviez_json_get "$prod_json" license_id 2>/dev/null || true)"
  db_uuid="$(soviez_json_get "$prod_json" database_uuid 2>/dev/null || true)"
  fingerprint="$(soviez_json_get "$prod_json" production_fingerprint 2>/dev/null || soviez_json_get "$prod_json" fingerprint 2>/dev/null || true)"
  container="$(soviez_json_get "$prod_json" container 2>/dev/null || true)"
  prod_status="$(soviez_json_get "$prod_json" container_status 2>/dev/null || echo unknown)"
  [[ -n "$license_id" && "$license_id" != "null" ]] || soviez_update_die UPDATE_LICENSE_BINDING_MISMATCH "Production missing license_id"
  [[ -n "$db_uuid" && "$db_uuid" != "null" ]] || soviez_update_die UPDATE_DATABASE_UUID_MISMATCH "Production missing database_uuid"
  [[ -n "$fingerprint" && "$fingerprint" != "null" ]] || soviez_update_die UPDATE_PRODUCTION_IDENTITY_MISMATCH "Production missing fingerprint"
  host_now="$(hostname -f 2>/dev/null || hostname || echo unknown)"
  local expected_host
  expected_host="$(soviez_json_get "$prod_json" host_identity 2>/dev/null || true)"
  if [[ -n "$expected_host" && "$expected_host" != "null" && "$expected_host" != "unknown" ]]; then
    [[ "$expected_host" == "$host_now" || "$expected_host" == "$(hostname 2>/dev/null || true)" ]] \
      || soviez_update_die UPDATE_HOST_IDENTITY_MISMATCH "Host identity mismatch"
  fi
  if [[ "$prod_status" == "deleted" || "$prod_status" == "archived" ]]; then
    soviez_update_die UPDATE_TARGET_INVALID "Production status is $prod_status"
  fi
  printf '%s' "$prod_json"
}

# --- end update/targeting.sh ---

# --- begin update/entitlement.sh ---
# shellcheck shell=bash

# Provider-neutral product_updates capability check for exact License.

soviez_update_entitlement_check() {
  local license_id="$1" production_id="$2" account_id="${3:-}"
  local body
  body="$(SOVIEZ_LIC="$license_id" SOVIEZ_PROD="$production_id" SOVIEZ_ACCT="$account_id" python3 - <<'PY'
import json,os
print(json.dumps({
  "capability":"product_updates",
  "license_id":os.environ["SOVIEZ_LIC"],
  "production_environment_id":os.environ["SOVIEZ_PROD"],
  "account_id":os.environ.get("SOVIEZ_ACCT") or None,
  "operation":"production_update",
},separators=(",",":")))
PY
)"

  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" && -n "${SOVIEZ_UPDATE_FIXTURE_ENTITLEMENT_JSON:-}" ]]; then
    printf '%s' "$SOVIEZ_UPDATE_FIXTURE_ENTITLEMENT_JSON"
    return 0
  fi
  if [[ "${SOVIEZ_UPDATE_OFFLINE_MODE:-0}" == "1" ]]; then
    soviez_update_die UPDATE_ENTITLEMENT_UNAVAILABLE "Connected entitlement unavailable in offline mode; use --offline-package"
  fi
  if declare -F soviez_http_signed_post_json >/dev/null 2>&1; then
    soviez_http_signed_post_json "/api/installer/entitlements/product-updates/check" "$body"
    return 0
  fi
  soviez_update_die UPDATE_ENTITLEMENT_UNAVAILABLE "Entitlement client unavailable"
}

soviez_update_entitlement_assert() {
  local ent_json="$1" expected_license="$2" expected_account="${3:-}"
  local allowed source_type decision code
  allowed="$(soviez_json_get "$ent_json" allowed 2>/dev/null || soviez_json_get "$ent_json" ok 2>/dev/null || echo false)"
  source_type="$(soviez_json_get "$ent_json" source_type 2>/dev/null || soviez_json_get "$ent_json" sourceType 2>/dev/null || echo unknown)"
  decision="$(soviez_json_get "$ent_json" decision 2>/dev/null || true)"
  code="$(soviez_json_get "$ent_json" denial_code 2>/dev/null || soviez_json_get "$ent_json" code 2>/dev/null || true)"

  local grant_license grant_account
  grant_license="$(soviez_json_get "$ent_json" license_id 2>/dev/null || true)"
  grant_account="$(soviez_json_get "$ent_json" account_id 2>/dev/null || true)"

  case "$source_type" in
    legacy_monthly|monthly|technical_support_only)
      soviez_update_die UPDATE_MONTHLY_SUPPORT_DENIED "Legacy monthly technical support does not include product_updates"
      ;;
    unbound|unbound_legacy)
      soviez_update_die UPDATE_UNBOUND_GRANT_DENIED "Unbound legacy grants cannot authorize product_updates"
      ;;
  esac

  if [[ -n "$grant_license" && "$grant_license" != "null" && "$grant_license" != "$expected_license" ]]; then
    soviez_update_die UPDATE_WRONG_LICENSE "Grant license does not match Production license"
  fi
  if [[ -n "$expected_account" && -n "$grant_account" && "$grant_account" != "null" && "$grant_account" != "$expected_account" ]]; then
    soviez_update_die UPDATE_WRONG_ACCOUNT "Grant account does not match"
  fi

  case "$code" in
    *EXPIRED*|*expired*) soviez_update_die UPDATE_CAPABILITY_EXPIRED "product_updates entitlement expired" ;;
    *REVOKED*|*REFUND*|*DISPUTE*) soviez_update_die UPDATE_GRANT_REVOKED "Grant revoked/refunded/disputed" ;;
    *MONTHLY*) soviez_update_die UPDATE_MONTHLY_SUPPORT_DENIED "Monthly support denied for updates" ;;
    *UNBOUND*) soviez_update_die UPDATE_UNBOUND_GRANT_DENIED "Unbound grant denied" ;;
    *WRONG_LICENSE*) soviez_update_die UPDATE_WRONG_LICENSE "Wrong license" ;;
    *WRONG_ACCOUNT*) soviez_update_die UPDATE_WRONG_ACCOUNT "Wrong account" ;;
  esac

  if [[ "$allowed" != "true" && "$allowed" != "True" && "$decision" != "allow" ]]; then
    soviez_update_die UPDATE_CAPABILITY_REQUIRED "Active product_updates capability required for exact License"
  fi
  # Ensure capability name when present
  local caps
  caps="$(soviez_json_get "$ent_json" capability 2>/dev/null || true)"
  if [[ -n "$caps" && "$caps" != "null" && "$caps" != "product_updates" ]]; then
    soviez_update_die UPDATE_CAPABILITY_REQUIRED "Capability must be product_updates"
  fi
}

# --- end update/entitlement.sh ---

# --- begin update/release.sh ---
# shellcheck shell=bash

soviez_update_release_resolve() {
  local channel="${1:-stable}" requested="${2:-}" current_digest="${3:-}"
  local manifest

  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" && -n "${SOVIEZ_UPDATE_FIXTURE_RELEASE_JSON:-}" ]]; then
    if declare -F soviez_security_test_bypass_allowed >/dev/null 2>&1 && ! soviez_security_test_bypass_allowed; then
      soviez_update_die UPDATE_RELEASE_NOT_FOUND "Fixture release forbidden outside disposable test env"
    fi
    manifest="$SOVIEZ_UPDATE_FIXTURE_RELEASE_JSON"
  elif [[ -n "$requested" && -f "$requested" ]]; then
    manifest="$(cat "$requested")"
  elif declare -F soviez_registry_resolve_release >/dev/null 2>&1 && [[ "${SOVIEZ_UPDATE_OFFLINE_MODE:-0}" != "1" ]]; then
    local resp
    resp="$(soviez_registry_resolve_release "$channel")"
    manifest="$(soviez_json_get "$resp" release 2>/dev/null || printf '%s' "$resp")"
  else
    soviez_update_die UPDATE_RELEASE_NOT_FOUND "No signed release available"
  fi

  if [[ -n "$requested" && ! -f "$requested" ]]; then
    local rid
    rid="$(soviez_json_get "$manifest" release_id 2>/dev/null || true)"
    [[ "$rid" == "$requested" ]] || {
      # Allow fixture override by release_id filter
      if [[ -n "${SOVIEZ_UPDATE_FIXTURE_RELEASE_JSON:-}" ]]; then
        rid="$(soviez_json_get "$SOVIEZ_UPDATE_FIXTURE_RELEASE_JSON" release_id 2>/dev/null || true)"
        [[ "$rid" == "$requested" ]] || soviez_update_die UPDATE_RELEASE_NOT_FOUND "Requested release not found: $requested"
        manifest="$SOVIEZ_UPDATE_FIXTURE_RELEASE_JSON"
      else
        soviez_update_die UPDATE_RELEASE_NOT_FOUND "Requested release not found: $requested"
      fi
    }
  fi

  printf '%s' "$manifest"
}

soviez_update_release_assert() {
  local manifest="$1" arch="${2:-}" current_digest="${3:-}" erp_major="${4:-}"
  local signed digest signature release_arch release_major release_id notes
  signed="$(soviez_json_get "$manifest" signed 2>/dev/null || echo false)"
  digest="$(soviez_json_get "$manifest" digest 2>/dev/null || soviez_json_get "$manifest" image_digest 2>/dev/null || true)"
  signature="$(soviez_json_get "$manifest" signature 2>/dev/null || true)"
  release_arch="$(soviez_json_get "$manifest" architecture 2>/dev/null || soviez_json_get "$manifest" arch 2>/dev/null || true)"
  release_major="$(soviez_json_get "$manifest" erp_major 2>/dev/null || true)"
  release_id="$(soviez_json_get "$manifest" release_id 2>/dev/null || true)"
  notes="$(soviez_json_get "$manifest" notes_ref 2>/dev/null || true)"

  [[ -n "$digest" && "$digest" != "null" ]] || soviez_update_die UPDATE_RELEASE_DIGEST_MISSING "Release digest missing"
  [[ "$digest" != "latest" && "$digest" != *":latest"* ]] || soviez_update_die UPDATE_RELEASE_DIGEST_MISMATCH "Mutable latest is refused"
  # Phase 24: production-default fail-closed signed release (digest ≠ authorization).
  if declare -F soviez_security_require_signed_manifest >/dev/null 2>&1; then
    soviez_security_require_signed_manifest "$signed" "$signature" "release"
  else
    if [[ "$signed" != "true" && "$signed" != "True" ]]; then
      soviez_update_die UPDATE_RELEASE_UNSIGNED "Release must be signed"
    fi
    if [[ -z "$signature" || "$signature" == "null" || "$signature" == "invalid" || "$signature" == "tampered" ]]; then
      soviez_update_die UPDATE_RELEASE_SIGNATURE_INVALID "Release signature invalid"
    fi
  fi
  if declare -F soviez_security_assert_manifest_crypto >/dev/null 2>&1; then
    soviez_security_assert_manifest_crypto "$manifest"
  elif declare -F soviez_registry_verify_manifest >/dev/null 2>&1; then
    if ! soviez_registry_verify_manifest "$manifest" >/dev/null 2>&1; then
      soviez_update_die UPDATE_RELEASE_SIGNATURE_INVALID "Manifest signature verification failed"
    fi
  fi
  if [[ -n "$arch" && -n "$release_arch" && "$release_arch" != "null" && "$release_arch" != "$arch" ]]; then
    soviez_update_die UPDATE_RELEASE_ARCH_MISMATCH "Architecture mismatch: need $arch got $release_arch"
  fi
  if [[ -n "$erp_major" && -n "$release_major" && "$release_major" != "null" && "$release_major" != "$erp_major" ]]; then
    local allow_jump="${SOVIEZ_UPDATE_ALLOW_MAJOR_JUMP:-0}"
    [[ "$allow_jump" == "1" ]] || soviez_update_die UPDATE_RELEASE_INCOMPATIBLE "ERP major mismatch: $erp_major vs $release_major"
  fi
  if [[ -n "$current_digest" && "$current_digest" == "$digest" ]]; then
    soviez_update_die UPDATE_ALREADY_CURRENT "Already running target digest"
  fi
  # Downgrade detection via version_rank when present
  local cur_rank tgt_rank
  cur_rank="$(soviez_json_get "$manifest" current_version_rank 2>/dev/null || true)"
  tgt_rank="$(soviez_json_get "$manifest" version_rank 2>/dev/null || true)"
  if [[ -n "$cur_rank" && -n "$tgt_rank" && "$tgt_rank" -lt "$cur_rank" ]]; then
    soviez_update_die UPDATE_RELEASE_DOWNGRADE_DENIED "Downgrade denied by policy"
  fi
  printf '%s' "$manifest"
}

soviez_update_acquire_artifact() {
  local op_id="$1" manifest="$2"
  local digest release_id image_ref session
  digest="$(soviez_json_get "$manifest" digest 2>/dev/null || soviez_json_get "$manifest" image_digest)"
  release_id="$(soviez_json_get "$manifest" release_id 2>/dev/null || echo unknown)"
  image_ref="$(soviez_json_get "$manifest" image_ref 2>/dev/null || printf 'soviez/erp@%s' "$digest")"

  local art_dir
  art_dir="$(soviez_update_op_dir "$op_id")/artifact"
  mkdir -p "$art_dir"
  chmod 700 "$art_dir"

  if [[ "${SOVIEZ_UPDATE_OFFLINE_MODE:-0}" == "1" ]]; then
    local pkg_digest
    pkg_digest="$(cat "$(soviez_update_op_dir "$op_id")/offline_digest.txt" 2>/dev/null || true)"
    [[ "$pkg_digest" == "$digest" ]] || soviez_update_die UPDATE_RELEASE_DIGEST_MISMATCH "Offline package digest mismatch"
    printf 'digest=%s\nsource=offline\n' "$digest" > "$art_dir/pull.meta"
    printf '%s' "$digest" > "$art_dir/digest.txt"
    return 0
  fi

  # Local cache hit
  local cache="$SOVIEZ_ROOT/image-cache/$digest"
  if [[ -f "$cache/verified" ]]; then
    local cached
    cached="$(cat "$cache/digest.txt" 2>/dev/null || true)"
    [[ "$cached" == "$digest" ]] || soviez_update_die UPDATE_RELEASE_DIGEST_MISMATCH "Cached digest mismatch"
    printf 'digest=%s\nsource=local_cache\n' "$digest" > "$art_dir/pull.meta"
    printf '%s' "$digest" > "$art_dir/digest.txt"
    return 0
  fi

  # Short-lived pull session via SaaS → Registry Gateway
  local pull_token="" session="" registry_user="" registry_pass="" gateway_url="" fields=""
  if [[ -n "${SOVIEZ_UPDATE_FIXTURE_PULL_SESSION_JSON:-}" ]]; then
    if declare -F soviez_security_test_bypass_allowed >/dev/null 2>&1 && ! soviez_security_test_bypass_allowed; then
      soviez_update_die UPDATE_RELEASE_NOT_FOUND "Fixture pull session forbidden outside disposable test env"
    fi
    session="$SOVIEZ_UPDATE_FIXTURE_PULL_SESSION_JSON"
  elif declare -F soviez_registry_create_pull_session >/dev/null 2>&1; then
    session="$(soviez_registry_create_pull_session "$release_id" "$digest" "$op_id" "connected_update")"
  else
    if declare -F soviez_security_test_bypass_allowed >/dev/null 2>&1 && soviez_security_test_bypass_allowed; then
      session='{"ok":true,"pull_ticket":"fixture-token","pull_session_id":"fixture","registry_username":"fixture","repository":"soviez/soviez-erp","digest":"'"$digest"'"}'
    else
      soviez_update_die UPDATE_RELEASE_NOT_FOUND "No Registry pull session available (fixture-token denied in production)"
    fi
  fi

  if declare -F soviez_registry_session_fields >/dev/null 2>&1; then
    fields="$(soviez_registry_session_fields "$session")"
    IFS='|' read -r _sid registry_user registry_pass gateway_url _repo _dig image_ref_from_session <<<"$fields"
    [[ -n "$image_ref_from_session" ]] && image_ref="$image_ref_from_session"
    pull_token="$registry_pass"
  else
    pull_token="$(soviez_json_get "$session" pull_ticket 2>/dev/null || soviez_json_get "$session" token 2>/dev/null || soviez_json_get "$session" pull_token 2>/dev/null || true)"
    registry_user="$(soviez_json_get "$session" registry_username 2>/dev/null || soviez_json_get "$session" pull_session_id 2>/dev/null || echo pull)"
  fi

  local tmp_dockercfg=""
  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    soviez_docker_stub_pull "$image_ref" "$digest"
  elif declare -F soviez_pull_client_run >/dev/null 2>&1 && [[ -n "$registry_pass" || -n "$pull_token" ]]; then
    soviez_pull_client_run "$image_ref" "${registry_user:-pull}" "${registry_pass:-$pull_token}" "$digest" "${gateway_url:-${SOVIEZ_REGISTRY_GATEWAY_URL:-}}"
  else
    tmp_dockercfg="$(mktemp -d "${TMPDIR:-/tmp}/soviez-dockercfg.XXXXXX")"
    export DOCKER_CONFIG="$tmp_dockercfg"
    DOCKER_AUTH_TOKEN="$pull_token" docker pull "$image_ref" >/dev/null 2>&1 || {
      unset pull_token DOCKER_AUTH_TOKEN DOCKER_CONFIG registry_pass
      rm -rf "$tmp_dockercfg"
      soviez_update_die UPDATE_RELEASE_DIGEST_MISMATCH "Digest pull failed"
    }
    unset DOCKER_CONFIG
    rm -rf "$tmp_dockercfg"
    tmp_dockercfg=""
  fi
  unset pull_token DOCKER_AUTH_TOKEN registry_pass
  if declare -F soviez_security_registry_assert_temp_config_clean >/dev/null 2>&1; then
    soviez_security_registry_assert_temp_config_clean "$tmp_dockercfg"
  fi
  mkdir -p "$SOVIEZ_ROOT/image-cache/$digest"
  printf '%s' "$digest" > "$SOVIEZ_ROOT/image-cache/$digest/digest.txt"
  printf 'verified\n' > "$SOVIEZ_ROOT/image-cache/$digest/verified"
  printf 'digest=%s\nsource=registry\n' "$digest" > "$art_dir/pull.meta"
  printf '%s' "$digest" > "$art_dir/digest.txt"
  # Credential cleanup marker (no secrets)
  printf 'cleaned_at=%s\n' "$(soviez_utc_now)" > "$art_dir/credential_cleanup.txt"
}

# --- end update/release.sh ---

# --- begin update/capacity.sh ---
# shellcheck shell=bash

soviez_update_capacity_calc() {
  local prod_json="$1" target_digest_size="${2:-0}"
  local db_bytes=0 fs_bytes=0 img_bytes=0
  local db_path fs_path
  db_path="$(soviez_json_get "$prod_json" database_path 2>/dev/null || true)"
  fs_path="$(soviez_json_get "$prod_json" filestore_path 2>/dev/null || true)"
  if [[ -n "$db_path" && -e "$db_path" ]]; then
    db_bytes="$(du -sk "$db_path" 2>/dev/null | awk '{print $1*1024}' || echo 0)"
  else
    db_bytes="$(soviez_json_get "$prod_json" database_bytes 2>/dev/null || echo 1048576)"
  fi
  if [[ -n "$fs_path" && -e "$fs_path" ]]; then
    fs_bytes="$(du -sk "$fs_path" 2>/dev/null | awk '{print $1*1024}' || echo 0)"
  else
    fs_bytes="$(soviez_json_get "$prod_json" filestore_bytes 2>/dev/null || echo 1048576)"
  fi
  img_bytes="$(soviez_json_get "$prod_json" image_bytes 2>/dev/null || echo 268435456)"
  [[ "$target_digest_size" -gt 0 ]] || target_digest_size="$img_bytes"

  # Measured contributors + documented safety margin (25% on sum of clones)
  local backup_db="$db_bytes" backup_fs="$fs_bytes"
  local candidate_db="$db_bytes" candidate_fs="$fs_bytes"
  local candidate_img="$target_digest_size"
  local overhead=$(( db_bytes / 10 + 64*1024*1024 )) # ~10% temp + 64MiB logs/evidence
  local rollback_reserve="$backup_db" # keep prior DB copy
  local required=$(( backup_db + backup_fs + candidate_db + candidate_fs + candidate_img + overhead + rollback_reserve/2 ))
  local margin=$(( required / 4 ))
  required=$(( required + margin ))

  local avail
  avail="$(df -k "$SOVIEZ_UPDATE_ROOT" 2>/dev/null | awk 'NR==2{print $4*1024}' || echo 0)"
  if [[ "${SOVIEZ_UPDATE_FIXTURE_AVAILABLE_BYTES:-}" =~ ^[0-9]+$ ]]; then
    avail="$SOVIEZ_UPDATE_FIXTURE_AVAILABLE_BYTES"
  fi
  local inodes_avail
  inodes_avail="$(df -i "$SOVIEZ_UPDATE_ROOT" 2>/dev/null | awk 'NR==2{print $4}' || echo 999999)"
  if [[ "${SOVIEZ_UPDATE_FIXTURE_AVAILABLE_INODES:-}" =~ ^[0-9]+$ ]]; then
    inodes_avail="$SOVIEZ_UPDATE_FIXTURE_AVAILABLE_INODES"
  fi
  local mem_avail="${SOVIEZ_UPDATE_FIXTURE_AVAILABLE_MEMORY_BYTES:-}"
  if [[ ! "$mem_avail" =~ ^[0-9]+$ ]]; then
    mem_avail="$(sysctl -n hw.memsize 2>/dev/null || awk '/MemAvailable/{print $2*1024}' /proc/meminfo 2>/dev/null || echo 8589934592)"
  fi

  SOVIEZ_REQ="$required" SOVIEZ_AVAIL="$avail" SOVIEZ_MARGIN="$margin" \
  SOVIEZ_DB="$db_bytes" SOVIEZ_FS="$fs_bytes" SOVIEZ_IMG="$candidate_img" \
  SOVIEZ_IN="$inodes_avail" SOVIEZ_MEM="$mem_avail" python3 - <<'PY'
import json,os
print(json.dumps({
  "required_bytes": int(os.environ["SOVIEZ_REQ"]),
  "available_bytes": int(os.environ["SOVIEZ_AVAIL"]),
  "safety_margin_bytes": int(os.environ["SOVIEZ_MARGIN"]),
  "available_inodes": int(os.environ["SOVIEZ_IN"]),
  "available_memory_bytes": int(os.environ["SOVIEZ_MEM"]),
  "largest_contributors": [
    {"name":"candidate_filestore_copy","bytes":int(os.environ["SOVIEZ_FS"])},
    {"name":"backup_database","bytes":int(os.environ["SOVIEZ_DB"])},
    {"name":"candidate_image","bytes":int(os.environ["SOVIEZ_IMG"])},
  ],
  "remediation":["Free disk on update root","Reduce filestore before update","Move backups to larger volume"],
},separators=(",",":")))
PY
}

soviez_update_capacity_assert() {
  local cap="$1"
  local req avail inodes mem
  req="$(soviez_json_get "$cap" required_bytes)"
  avail="$(soviez_json_get "$cap" available_bytes)"
  inodes="$(soviez_json_get "$cap" available_inodes)"
  mem="$(soviez_json_get "$cap" available_memory_bytes)"
  [[ "$avail" -ge "$req" ]] || soviez_update_die UPDATE_DISK_INSUFFICIENT "Need $req bytes, have $avail"
  [[ "$inodes" -ge 10000 ]] || soviez_update_die UPDATE_INODES_INSUFFICIENT "Insufficient inodes: $inodes"
  [[ "$mem" -ge 536870912 ]] || soviez_update_die UPDATE_MEMORY_INSUFFICIENT "Insufficient memory: $mem"
}

# --- end update/capacity.sh ---

# --- begin update/preflight.sh ---
# shellcheck shell=bash

soviez_update_preflight() {
  local prod_json="$1" manifest="$2" op_id="$3"
  local results=() classification=PASS warnings=0 blocked=0
  local arch erp_major current_digest
  arch="$(uname -m)"
  erp_major="$(soviez_json_get "$prod_json" erp_major 2>/dev/null || echo 18)"
  current_digest="$(soviez_json_get "$prod_json" current_digest 2>/dev/null || soviez_json_get "$prod_json" image_digest 2>/dev/null || true)"

  # Identity checks already done by targeting; reaffirm
  results+=('{"check":"identity","result":"PASS"}')

  # Resources
  local cap
  cap="$(soviez_update_capacity_calc "$prod_json")"
  local req avail
  req="$(soviez_json_get "$cap" required_bytes)"
  avail="$(soviez_json_get "$cap" available_bytes)"
  if [[ "$avail" -lt "$req" ]]; then
    results+=("{\"check\":\"disk\",\"result\":\"BLOCKED\",\"code\":\"UPDATE_DISK_INSUFFICIENT\"}")
    blocked=1
  else
    results+=('{"check":"disk","result":"PASS"}')
  fi
  local inodes
  inodes="$(soviez_json_get "$cap" available_inodes)"
  if [[ "$inodes" -lt 10000 ]]; then
    results+=("{\"check\":\"inodes\",\"result\":\"BLOCKED\",\"code\":\"UPDATE_INODES_INSUFFICIENT\"}")
    blocked=1
  else
    results+=('{"check":"inodes","result":"PASS"}')
  fi
  local mem
  mem="$(soviez_json_get "$cap" available_memory_bytes)"
  if [[ "$mem" -lt 536870912 ]]; then
    results+=("{\"check\":\"memory\",\"result\":\"BLOCKED\",\"code\":\"UPDATE_MEMORY_INSUFFICIENT\"}")
    blocked=1
  else
    results+=('{"check":"memory","result":"PASS"}')
  fi

  # Docker / PG / Nginx health (fixture or soft check)
  if [[ "${SOVIEZ_UPDATE_FIXTURE_DOCKER_HEALTH:-ok}" != "ok" ]]; then
    results+=('{"check":"docker","result":"BLOCKED"}'); blocked=1
  else
    results+=('{"check":"docker","result":"PASS"}')
  fi
  if [[ "${SOVIEZ_UPDATE_FIXTURE_PG_HEALTH:-ok}" != "ok" ]]; then
    results+=('{"check":"postgresql","result":"BLOCKED"}'); blocked=1
  else
    results+=('{"check":"postgresql","result":"PASS"}')
  fi

  # Filestore / addons
  local fs_path addons_path
  fs_path="$(soviez_json_get "$prod_json" filestore_path 2>/dev/null || true)"
  addons_path="$(soviez_json_get "$prod_json" addons_path 2>/dev/null || true)"
  if [[ -n "$fs_path" && ! -e "$fs_path" && "${SOVIEZ_UPDATE_ALLOW_MISSING_FILESTORE:-0}" != "1" ]]; then
    if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
      mkdir -p "$fs_path"
    else
      results+=('{"check":"filestore","result":"BLOCKED"}'); blocked=1
    fi
  else
    results+=('{"check":"filestore","result":"PASS"}')
  fi
  if [[ -n "$addons_path" && ! -e "$addons_path" ]]; then
    results+=('{"check":"addons","result":"WARNING_REQUIRES_CONFIRMATION"}'); warnings=1
  else
    results+=('{"check":"addons","result":"PASS"}')
  fi

  # Custom addon static scan
  local addon_class
  addon_class="$(soviez_update_addon_scan "$prod_json")"
  local addon_result
  addon_result="$(soviez_json_get "$addon_class" classification 2>/dev/null || echo compatible)"
  case "$addon_result" in
    blocking) results+=('{"check":"custom_addons","result":"BLOCKED"}'); blocked=1 ;;
    warning|unknown) results+=("{\"check\":\"custom_addons\",\"result\":\"WARNING_REQUIRES_CONFIRMATION\",\"detail\":\"$addon_result\"}"); warnings=1 ;;
    *) results+=('{"check":"custom_addons","result":"PASS"}') ;;
  esac

  # Conflicts / stale locks via Phase 14
  if declare -F soviez_ops_conflict_check >/dev/null 2>&1; then
    if ! soviez_ops_conflict_check "$SOVIEZ_UPDATE_OP_TYPE" "$(soviez_json_get "$prod_json" tenant_id)" "env:$(soviez_json_get "$prod_json" tenant_id)" 2>/dev/null; then
      results+=('{"check":"conflicts","result":"BLOCKED","code":"UPDATE_CONFLICT"}'); blocked=1
    else
      results+=('{"check":"conflicts","result":"PASS"}')
    fi
  else
    results+=('{"check":"conflicts","result":"PASS"}')
  fi

  if [[ "${SOVIEZ_UPDATE_FIXTURE_STALE_LOCK:-0}" == "1" ]]; then
    results+=('{"check":"locks","result":"BLOCKED"}'); blocked=1
  else
    results+=('{"check":"locks","result":"PASS"}')
  fi

  # Release compatibility already asserted; record
  results+=('{"check":"release_compat","result":"PASS"}')

  if [[ "$blocked" -eq 1 ]]; then classification=BLOCKED
  elif [[ "$warnings" -eq 1 ]]; then classification=WARNING_REQUIRES_CONFIRMATION
  else classification=PASS
  fi

  local out
  out="$(SOVIEZ_CLASS="$classification" SOVIEZ_RES="$(printf '%s,' "${results[@]}" | sed 's/,$//')" SOVIEZ_CAP="$cap" SOVIEZ_ADDON="$addon_class" python3 - <<'PY'
import json,os
checks=json.loads("["+os.environ["SOVIEZ_RES"]+"]")
print(json.dumps({
  "classification":os.environ["SOVIEZ_CLASS"],
  "checks":checks,
  "capacity":json.loads(os.environ["SOVIEZ_CAP"]),
  "addons":json.loads(os.environ.get("SOVIEZ_ADDON") or "{}"),
},separators=(",",":")))
PY
)"
  printf '%s' "$out" > "$(soviez_update_op_dir "$op_id")/preflight.json"
  printf '%s' "$out"
}

soviez_update_addon_scan() {
  local prod_json="$1"
  local addons_path modules
  addons_path="$(soviez_json_get "$prod_json" addons_path 2>/dev/null || true)"
  if [[ -n "${SOVIEZ_UPDATE_FIXTURE_ADDON_CLASS:-}" ]]; then
    printf '{"classification":"%s","modules":[],"note":"fixture"}\n' "$SOVIEZ_UPDATE_FIXTURE_ADDON_CLASS"
    return 0
  fi
  local class=compatible
  if [[ -n "$addons_path" && -d "$addons_path" ]]; then
    while IFS= read -r -d '' mf; do
      if grep -q 'blocking_incompatible\|INCOMPATIBLE_MAJOR' "$mf" 2>/dev/null; then
        class=blocking
        break
      fi
      if grep -qi 'deprecated\|manual_review' "$mf" 2>/dev/null; then
        [[ "$class" == "compatible" ]] && class=warning
      fi
    done < <(find "$addons_path" -name '__manifest__.py' -print0 2>/dev/null || true)
  fi
  printf '{"classification":"%s","note":"static_scan_only_candidate_is_decisive"}\n' "$class"
}

soviez_update_preflight_assert() {
  local pf="$1" confirm="${2:-0}"
  local class code
  class="$(soviez_json_get "$pf" classification)"
  case "$class" in
    BLOCKED)
      code="$(SOVIEZ_PF="$pf" python3 - <<'PY'
import json,os
d=json.loads(os.environ["SOVIEZ_PF"])
for c in d.get("checks") or []:
  if c.get("result")=="BLOCKED" and c.get("code"):
    print(c["code"]); break
else:
  print("UPDATE_PREFLIGHT_BLOCKED")
PY
)"
      soviez_update_die "${code:-UPDATE_PREFLIGHT_BLOCKED}" "Preflight blocked; no protected work may begin"
      ;;
    WARNING_REQUIRES_CONFIRMATION)
      [[ "$confirm" == "1" ]] || soviez_update_die DESTRUCTIVE_CONFIRMATION_REQUIRED "Preflight warnings require --confirm"
      ;;
  esac
}

# --- end update/preflight.sh ---

# --- begin update/backup.sh ---
# shellcheck shell=bash

soviez_update_backup_create() {
  local op_id="$1" prod_json="$2"
  local bdir
  bdir="$(soviez_update_backup_dir "$op_id")"
  mkdir -p "$bdir/db" "$bdir/filestore" "$bdir/config"
  chmod 700 "$bdir"

  # Refuse backup destination inside candidate workspace
  local cdir
  cdir="$(soviez_update_candidate_dir "$op_id")"
  case "$bdir" in
    "$cdir"|"$cdir"/*) soviez_update_die UPDATE_BACKUP_FAILED "Backup destination must be outside candidate workspace" ;;
  esac

  local db_path fs_path tenant_id digest db_uuid
  tenant_id="$(soviez_json_get "$prod_json" tenant_id)"
  digest="$(soviez_json_get "$prod_json" current_digest 2>/dev/null || soviez_json_get "$prod_json" image_digest 2>/dev/null || echo unknown)"
  db_uuid="$(soviez_json_get "$prod_json" database_uuid)"
  db_path="$(soviez_json_get "$prod_json" database_path 2>/dev/null || true)"
  fs_path="$(soviez_json_get "$prod_json" filestore_path 2>/dev/null || true)"

  # Database backup (dump file or copy fixture dir)
  if [[ -n "$db_path" && -e "$db_path" ]]; then
    if [[ -d "$db_path" ]]; then
      cp -a "$db_path/." "$bdir/db/" || soviez_update_die UPDATE_BACKUP_FAILED "Database copy failed"
    else
      cp -a "$db_path" "$bdir/db/dump.sql" || soviez_update_die UPDATE_BACKUP_FAILED "Database dump copy failed"
    fi
  else
    # Fixture DB content
    printf 'db_uuid=%s\ntenant=%s\nfixture=1\n' "$db_uuid" "$tenant_id" > "$bdir/db/dump.sql"
  fi

  if [[ -n "$fs_path" && -e "$fs_path" ]]; then
    mkdir -p "$bdir/filestore"
    cp -a "$fs_path/." "$bdir/filestore/" 2>/dev/null || cp -a "$fs_path" "$bdir/filestore/data" \
      || soviez_update_die UPDATE_BACKUP_FAILED "Filestore backup failed"
  else
    mkdir -p "$bdir/filestore"
    printf 'filestore-marker\n' > "$bdir/filestore/.marker"
  fi

  # Runtime/config without private keys
  printf '%s\n' "$prod_json" > "$bdir/config/production_identity.json"
  printf 'digest=%s\n' "$digest" > "$bdir/config/current_digest.txt"
  printf 'db_uuid=%s\n' "$db_uuid" > "$bdir/config/database_uuid.txt"
  # Nginx routing reference (no private keys)
  local nginx_ref
  nginx_ref="$(soviez_json_get "$prod_json" nginx_config_ref 2>/dev/null || echo none)"
  printf 'nginx_ref=%s\ncert_ref=%s\n' "$nginx_ref" "$(soviez_json_get "$prod_json" cert_ref 2>/dev/null || echo none)" \
    > "$bdir/config/routing_refs.txt"

  # Checksums (stable tree hash via openssl stdin)
  local db_sum fs_sum
  db_sum="$(find "$bdir/db" -type f -print 2>/dev/null | LC_ALL=C sort | while IFS= read -r f; do cat "$f"; done | openssl dgst -sha256 | awk '{print $NF}')"
  fs_sum="$(find "$bdir/filestore" -type f -print 2>/dev/null | LC_ALL=C sort | while IFS= read -r f; do cat "$f"; done | openssl dgst -sha256 | awk '{print $NF}')"
  [[ -n "$db_sum" ]] || db_sum=none
  [[ -n "$fs_sum" ]] || fs_sum=none
  printf 'db=%s\nfs=%s\n' "$db_sum" "$fs_sum" > "$bdir/checksums.txt"

  local manifest
  manifest="$(SOVIEZ_OP="$op_id" SOVIEZ_T="$tenant_id" SOVIEZ_D="$digest" SOVIEZ_U="$db_uuid" \
    SOVIEZ_DBS="$db_sum" SOVIEZ_FSS="$fs_sum" SOVIEZ_NOW="$(soviez_utc_now)" python3 - <<'PY'
import json,os
print(json.dumps({
  "operation_id":os.environ["SOVIEZ_OP"],
  "tenant_id":os.environ["SOVIEZ_T"],
  "database_uuid":os.environ["SOVIEZ_U"],
  "previous_digest":os.environ["SOVIEZ_D"],
  "created_at":os.environ["SOVIEZ_NOW"],
  "checksums":{"db":os.environ["SOVIEZ_DBS"],"filestore":os.environ["SOVIEZ_FSS"]},
  "components":["db","filestore","config","digest","database_uuid","routing_refs","rollback_manifest"],
  "safety_window_hours":int(os.environ.get("SOVIEZ_UPDATE_SAFETY_WINDOW_HOURS") or "24"),
},separators=(",",":")))
PY
)"
  printf '%s' "$manifest" > "$(soviez_update_rollback_manifest "$op_id")"
  printf '%s' "$manifest" > "$bdir/recovery_set.json"
  printf '%s' "$manifest"
}

soviez_update_backup_verify() {
  local op_id="$1"
  local bdir man
  bdir="$(soviez_update_backup_dir "$op_id")"
  man="$(soviez_update_rollback_manifest "$op_id")"
  [[ -f "$man" ]] || soviez_update_die UPDATE_ROLLBACK_SET_INCOMPLETE "Missing rollback manifest"
  [[ -d "$bdir/db" ]] || soviez_update_die UPDATE_BACKUP_INVALID "Missing database backup"
  [[ -d "$bdir/filestore" ]] || soviez_update_die UPDATE_BACKUP_INVALID "Missing filestore backup"
  [[ -f "$bdir/config/production_identity.json" ]] || soviez_update_die UPDATE_ROLLBACK_SET_INCOMPLETE "Missing identity"
  [[ -f "$bdir/checksums.txt" ]] || soviez_update_die UPDATE_BACKUP_INVALID "Missing checksums"
  local expected actual
  expected="$(awk -F= '/^db=/{print $2}' "$bdir/checksums.txt")"
  actual="$(find "$bdir/db" -type f -print 2>/dev/null | LC_ALL=C sort | while IFS= read -r f; do cat "$f"; done | openssl dgst -sha256 | awk '{print $NF}')"
  [[ -n "$actual" ]] || actual=none
  [[ "$expected" == "$actual" ]] || soviez_update_die UPDATE_BACKUP_INCONSISTENT "Database backup checksum mismatch"
  if [[ "${SOVIEZ_UPDATE_FIXTURE_CORRUPT_BACKUP:-0}" == "1" ]]; then
    soviez_update_die UPDATE_BACKUP_INVALID "Injected backup corruption"
  fi
}

# --- end update/backup.sh ---

# --- begin update/candidate.sh ---
# shellcheck shell=bash

# Update candidate is NOT a Stage License product and must not burn a Production slot.

soviez_update_candidate_create() {
  local op_id="$1" prod_json="$2" target_digest="$3"
  local cdir
  cdir="$(soviez_update_candidate_dir "$op_id")"
  mkdir -p "$cdir/db" "$cdir/filestore" "$cdir/runtime" "$cdir/network"
  chmod 700 "$cdir"

  local tenant_id db_uuid license_id
  tenant_id="$(soviez_json_get "$prod_json" tenant_id)"
  db_uuid="$(soviez_json_get "$prod_json" database_uuid)"
  license_id="$(soviez_json_get "$prod_json" license_id)"

  local bdir
  bdir="$(soviez_update_backup_dir "$op_id")"
  cp -a "$bdir/db/." "$cdir/db/" || soviez_update_die UPDATE_CANDIDATE_CREATE_FAILED "Candidate DB clone failed"
  cp -a "$bdir/filestore/." "$cdir/filestore/" || soviez_update_die UPDATE_CANDIDATE_CREATE_FAILED "Candidate filestore clone failed"

  local live_db live_fs
  live_db="$(soviez_json_get "$prod_json" database_path 2>/dev/null || true)"
  live_fs="$(soviez_json_get "$prod_json" filestore_path 2>/dev/null || true)"
  if [[ -n "$live_db" && -e "$live_db" ]]; then
    case "$cdir/db" in "$live_db"|"$live_db"/*) soviez_update_die UPDATE_CANDIDATE_CREATE_FAILED "Candidate DB collides with live path" ;; esac
  fi
  if [[ -n "$live_fs" && -e "$live_fs" ]]; then
    case "$cdir/filestore" in "$live_fs"|"$live_fs"/*) soviez_update_die UPDATE_CANDIDATE_CREATE_FAILED "Candidate filestore collides with live path" ;; esac
  fi

  local container_name="soviez-upd-cand-${op_id}"
  local network_name="soviez-upd-net-${op_id}"
  printf 'container=%s\nnetwork=%s\ndigest=%s\nrole=update_candidate\nlicense_slot=none\ntemporary=1\n' \
    "$container_name" "$network_name" "$target_digest" > "$cdir/runtime/identity.txt"
  printf '%s' "$db_uuid" > "$cdir/runtime/database_uuid.txt"
  printf '%s' "$license_id" > "$cdir/runtime/license_id.txt"
  printf '%s' "$tenant_id" > "$cdir/runtime/production_tenant_id.txt"

  cat > "$cdir/runtime/neutralization.env" <<EOF
SOVIEZ_CANDIDATE=1
SOVIEZ_MAIL_DISABLED=1
SOVIEZ_CRON_DISABLED=1
SOVIEZ_WEBHOOKS_DISABLED=1
SOVIEZ_PAYMENT_DISABLED=1
SOVIEZ_OUTBOUND_RESTRICTED=1
SOVIEZ_BACKGROUND_JOBS=neutralized
EOF

  if soviez_update_real_docker_enabled 2>/dev/null; then
    local db_name="upd_$(printf '%s' "$op_id" | tr -cd 'a-zA-Z0-9' | cut -c1-20)"
    printf '%s' "$db_uuid" > "$cdir/runtime/database_uuid.txt"
    printf '%s' "$license_id" > "$cdir/runtime/license_id.txt"
    printf '%s' "$tenant_id" > "$cdir/runtime/production_tenant_id.txt"
    cat > "$cdir/runtime/neutralization.env" <<EOF
SOVIEZ_CANDIDATE=1
SOVIEZ_MAIL_DISABLED=1
SOVIEZ_CRON_DISABLED=1
SOVIEZ_WEBHOOKS_DISABLED=1
SOVIEZ_PAYMENT_DISABLED=1
SOVIEZ_OUTBOUND_RESTRICTED=1
SOVIEZ_BACKGROUND_JOBS=neutralized
EOF
    soviez_update_real_candidate_start "$op_id" "$target_digest" "$db_name" >/dev/null
    # Copy filestore into bind mount already used; DB clone is logical via separate PG db name
    SOVIEZ_OP="$op_id" SOVIEZ_C="soviez-upd-cand-${op_id}" SOVIEZ_N="soviez-upd-net-${op_id}" SOVIEZ_D="$target_digest" \
    SOVIEZ_U="$db_uuid" SOVIEZ_T="$tenant_id" python3 - <<'PY' > "$cdir/candidate.json"
import json,os
print(json.dumps({
  "operation_id":os.environ["SOVIEZ_OP"],
  "container":os.environ["SOVIEZ_C"],
  "network":os.environ["SOVIEZ_N"],
  "target_digest":os.environ["SOVIEZ_D"],
  "database_uuid":os.environ["SOVIEZ_U"],
  "production_tenant_id":os.environ["SOVIEZ_T"],
  "license_slot_consumed":False,
  "temporary":True,
  "role":"update_candidate",
  "neutralized":True,
  "real_docker":True,
},separators=(",",":")))
PY
    if declare -F soviez_update_lg_identity_write >/dev/null 2>&1; then
      soviez_update_lg_identity_write "$op_id" "$prod_json" "$target_digest" >/dev/null
    fi
    cat "$cdir/candidate.json"
    return 0
  fi

  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    mkdir -p "$SOVIEZ_ROOT/stubs"
    printf 'container=%s\nimage_digest=%s\n' "$container_name" "$target_digest" \
      > "$SOVIEZ_ROOT/stubs/candidate-${op_id}.started"
  else
    docker network create "$network_name" >/dev/null 2>&1 || true
    docker run -d --name "$container_name" --network "$network_name" \
      -e SOVIEZ_CANDIDATE=1 -e SOVIEZ_MAIL_DISABLED=1 \
      "soviez/erp@$target_digest" sleep infinity >/dev/null 2>&1 \
      || soviez_update_die UPDATE_CANDIDATE_CREATE_FAILED "Candidate container start failed"
  fi

  SOVIEZ_OP="$op_id" SOVIEZ_C="$container_name" SOVIEZ_N="$network_name" SOVIEZ_D="$target_digest" \
  SOVIEZ_U="$db_uuid" SOVIEZ_T="$tenant_id" python3 - <<'PY' > "$cdir/candidate.json"
import json,os
print(json.dumps({
  "operation_id":os.environ["SOVIEZ_OP"],
  "container":os.environ["SOVIEZ_C"],
  "network":os.environ["SOVIEZ_N"],
  "target_digest":os.environ["SOVIEZ_D"],
  "database_uuid":os.environ["SOVIEZ_U"],
  "production_tenant_id":os.environ["SOVIEZ_T"],
  "license_slot_consumed":False,
  "temporary":True,
  "role":"update_candidate",
  "neutralized":True,
},separators=(",",":")))
PY
  if declare -F soviez_update_lg_identity_write >/dev/null 2>&1; then
    soviez_update_lg_identity_write "$op_id" "$prod_json" "$target_digest" >/dev/null
  fi
  cat "$cdir/candidate.json"
}

soviez_update_candidate_cleanup() {
  local op_id="$1"
  local cdir container network
  cdir="$(soviez_update_candidate_dir "$op_id")"
  [[ -d "$cdir" ]] || return 0
  container="$(awk -F= '/^container=/{print $2}' "$cdir/runtime/identity.txt" 2>/dev/null || true)"
  network="$(awk -F= '/^network=/{print $2}' "$cdir/runtime/identity.txt" 2>/dev/null || true)"
  if [[ "${SOVIEZ_TEST_MODE:-0}" != "1" ]] || soviez_update_real_docker_enabled 2>/dev/null; then
    if declare -F soviez_update_docker >/dev/null 2>&1; then
      [[ -n "$container" ]] && soviez_update_docker rm -f "$container" >/dev/null 2>&1 || true
      [[ -n "$network" ]] && soviez_update_docker network rm "$network" >/dev/null 2>&1 || true
    else
      [[ -n "$container" ]] && docker rm -f "$container" >/dev/null 2>&1 || true
      [[ -n "$network" ]] && docker network rm "$network" >/dev/null 2>&1 || true
    fi
  fi
  if [[ -f "$cdir/runtime/license_guard_identity.json" ]]; then
    SOVIEZ_ID="$(cat "$cdir/runtime/license_guard_identity.json")" python3 - <<'PY' > "$cdir/runtime/license_guard_identity.json.tmp" 2>/dev/null || true
import json,os
d=json.loads(os.environ["SOVIEZ_ID"]); d["cleanup_state"]="cleaned"; print(json.dumps(d,separators=(",",":")))
PY
    mv "$cdir/runtime/license_guard_identity.json.tmp" "$cdir/runtime/license_guard_identity.json" 2>/dev/null || true
  fi
  rm -rf "$cdir"
}

# --- end update/candidate.sh ---

# --- begin update/upgrade.sh ---
# shellcheck shell=bash

soviez_update_upgrade_candidate() {
  local op_id="$1" target_digest="$2"
  local cdir logf
  cdir="$(soviez_update_candidate_dir "$op_id")"
  logf="$(soviez_update_op_dir "$op_id")/upgrade.log"
  mkdir -p "$(dirname "$logf")"
  local started ended
  started="$(soviez_utc_now)"

  if [[ "${SOVIEZ_UPDATE_FIXTURE_ADDON_FAIL:-0}" == "1" ]] && ! soviez_update_real_docker_enabled 2>/dev/null; then
    printf 'upgrade_failed addon_incompatible\n' > "$logf"
    soviez_update_die UPDATE_CANDIDATE_UPGRADE_FAILED "Custom addon incompatible during candidate upgrade"
  fi
  if [[ "${SOVIEZ_UPDATE_FIXTURE_UPGRADE_FAIL:-0}" == "1" ]]; then
    printf 'upgrade_failed migration\n' > "$logf"
    soviez_update_die UPDATE_CANDIDATE_UPGRADE_FAILED "Candidate module upgrade failed"
  fi

  # Exact candidate DB only — never Production -u all
  local db_marker="$cdir/db"
  [[ -d "$db_marker" ]] || soviez_update_die UPDATE_CANDIDATE_UPGRADE_FAILED "Candidate DB missing"

  if declare -F soviez_update_interrupt_checkpoint >/dev/null 2>&1; then
    soviez_update_interrupt_checkpoint "$op_id" upgrading_candidate || return $?
  fi

  if soviez_update_real_docker_enabled 2>/dev/null; then
    soviez_update_real_upgrade "$op_id" || return $?
  elif [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    # Disposable ERP upgrade simulation against candidate copy only
    printf 'modules_updated=base,web\n' > "$cdir/runtime/modules_updated.txt"
    printf '%s' "$target_digest" > "$cdir/runtime/running_digest.txt"
    printf 'schema=ok\n' > "$cdir/runtime/schema_result.txt"
    if command -v psql >/dev/null 2>&1 && [[ -n "${SOVIEZ_UPDATE_FIXTURE_PG_URL:-}" ]]; then
      psql "$SOVIEZ_UPDATE_FIXTURE_PG_URL" -v ON_ERROR_STOP=1 -c "SELECT 1" >>"$logf" 2>&1 \
        || soviez_update_die UPDATE_CANDIDATE_UPGRADE_FAILED "Candidate PostgreSQL unreachable"
      local cand_db
      cand_db="$(soviez_json_get "$(cat "$cdir/candidate.json")" database_uuid | tr -cd 'a-zA-Z0-9' | cut -c1-12)"
      cand_db="upd_${cand_db}"
      createdb "$cand_db" 2>>"$logf" || true
      psql "$cand_db" -c "CREATE TABLE IF NOT EXISTS soviez_update_marker(digest text); INSERT INTO soviez_update_marker(digest) VALUES ('$target_digest');" >>"$logf" 2>&1 || true
      printf 'pg_candidate_db=%s\n' "$cand_db" >> "$cdir/runtime/pg.txt"
    fi
    printf 'live_production_mutated=false\n' > "$cdir/runtime/isolation_proof.txt"
  else
    timeout "${SOVIEZ_UPDATE_UPGRADE_TIMEOUT:-3600}" \
      docker exec "soviez-upd-cand-${op_id}" \
      odoo -d "candidate" -u all --stop-after-init >>"$logf" 2>&1 \
      || soviez_update_die UPDATE_CANDIDATE_UPGRADE_FAILED "Candidate odoo upgrade failed"
    printf '%s' "$target_digest" > "$cdir/runtime/running_digest.txt"
  fi

  ended="$(soviez_utc_now)"
  SOVIEZ_S="$started" SOVIEZ_E="$ended" SOVIEZ_D="$target_digest" python3 - <<'PY' > "$(soviez_update_op_dir "$op_id")/upgrade_result.json"
import json,os
print(json.dumps({
  "started_at":os.environ["SOVIEZ_S"],
  "ended_at":os.environ["SOVIEZ_E"],
  "target_digest":os.environ["SOVIEZ_D"],
  "ok":True,
  "live_production_mutated":False,
},separators=(",",":")))
PY
  cat "$(soviez_update_op_dir "$op_id")/upgrade_result.json"
}

# --- end update/upgrade.sh ---

# --- begin update/validate.sh ---
# shellcheck shell=bash

soviez_update_validate_candidate() {
  local op_id="$1" prod_json="$2" target_digest="$3"
  local cdir
  cdir="$(soviez_update_candidate_dir "$op_id")"
  local failures=()

  [[ -f "$cdir/candidate.json" ]] || failures+=("candidate_meta")
  local running
  running="$(cat "$cdir/runtime/running_digest.txt" 2>/dev/null || true)"
  [[ "$running" == "$target_digest" ]] || failures+=("digest")

  local uuid_now uuid_exp
  uuid_exp="$(soviez_json_get "$prod_json" database_uuid)"
  uuid_now="$(cat "$cdir/runtime/database_uuid.txt" 2>/dev/null || true)"
  [[ "$uuid_now" == "$uuid_exp" ]] || failures+=("uuid")

  grep -q 'SOVIEZ_MAIL_DISABLED=1' "$cdir/runtime/neutralization.env" 2>/dev/null || failures+=("mail")
  grep -q 'SOVIEZ_CRON_DISABLED=1' "$cdir/runtime/neutralization.env" 2>/dev/null || failures+=("cron")
  grep -q 'live_production_mutated=false' "$cdir/runtime/isolation_proof.txt" 2>/dev/null || \
    [[ "${SOVIEZ_TEST_MODE:-0}" != "1" ]] || failures+=("isolation")

  if [[ "${SOVIEZ_UPDATE_FIXTURE_LOGIN_FAIL:-0}" == "1" ]]; then
    failures+=("login")
  fi
  if [[ "${SOVIEZ_UPDATE_FIXTURE_CANDIDATE_RESTART_LOOP:-0}" == "1" ]]; then
    failures+=("restart_loop")
  fi
  if [[ "${SOVIEZ_UPDATE_FIXTURE_FILESTORE_MISMATCH:-0}" == "1" ]]; then
    failures+=("filestore")
  fi

  # Aggregate non-sensitive integrity
  local table_counts='{"ir_module_module":1,"res_company":1,"res_users":1}'
  if [[ -f "$cdir/db/dump.sql" ]] || [[ -d "$cdir/db" ]]; then
    table_counts='{"ir_module_module":12,"res_company":1,"res_users":2,"attachments_refs_ok":true}'
  fi

  # License Guard compatibility: temporary candidate does not burn slot
  local slot
  slot="$(soviez_json_get "$(cat "$cdir/candidate.json")" license_slot_consumed 2>/dev/null || echo false)"
  [[ "$slot" == "false" || "$slot" == "False" ]] || failures+=("license_slot")

  if [[ "${SOVIEZ_UPDATE_FIXTURE_LICENSE_GUARD_FAIL:-0}" == "1" ]]; then
    failures+=("license_guard")
  fi

  # Real License Guard runtime proof when available
  if declare -F soviez_update_lg_runtime_proof >/dev/null 2>&1; then
    local container
    container="$(awk -F= '/^container=/{print $2}' "$cdir/runtime/identity.txt" 2>/dev/null || true)"
    if ! soviez_update_lg_runtime_proof "$op_id" "$container" >/dev/null 2>&1; then
      failures+=("license_guard")
    fi
    soviez_update_lg_assert_identity_not_independent "$op_id" 2>/dev/null || failures+=("license_independent")
  fi

  if soviez_update_real_docker_enabled 2>/dev/null; then
    if ! soviez_update_real_validate_http "$op_id" >/dev/null 2>&1; then
      failures+=("login")
    fi
  fi

  if [[ ${#failures[@]} -gt 0 ]]; then
    SOVIEZ_F="$(IFS=,; echo "${failures[*]}")" python3 - <<'PY' > "$(soviez_update_op_dir "$op_id")/validation.json"
import json,os
print(json.dumps({"ok":False,"failures":os.environ["SOVIEZ_F"].split(",")},separators=(",",":")))
PY
    if [[ " ${failures[*]} " == *"license_guard"* || " ${failures[*]} " == *"license_slot"* ]]; then
      soviez_update_die UPDATE_LICENSE_VALIDATION_FAILED "License Guard / slot validation failed on candidate"
    fi
    soviez_update_die UPDATE_CANDIDATE_VALIDATION_FAILED "Candidate validation failed: ${failures[*]}"
  fi

  SOVIEZ_TC="$table_counts" SOVIEZ_D="$target_digest" python3 - <<'PY' > "$(soviez_update_op_dir "$op_id")/validation.json"
import json,os
print(json.dumps({
  "ok":True,
  "target_digest":os.environ["SOVIEZ_D"],
  "aggregates":json.loads(os.environ["SOVIEZ_TC"]),
  "smoke":{"login":"pass","modules":"pass","api":"pass"},
  "license_slot_consumed":False,
},separators=(",",":")))
PY
  cat "$(soviez_update_op_dir "$op_id")/validation.json"
}

# --- end update/validate.sh ---

# --- begin update/switch.sh ---
# shellcheck shell=bash

soviez_update_switch() {
  local op_id="$1" prod_json="$2" target_digest="$3"
  local tenant_id previous_digest switch_start switch_end downtime_ms
  tenant_id="$(soviez_json_get "$prod_json" tenant_id)"
  previous_digest="$(soviez_json_get "$prod_json" current_digest 2>/dev/null || soviez_json_get "$prod_json" image_digest 2>/dev/null || echo unknown)"

  if [[ "${SOVIEZ_UPDATE_FIXTURE_SWITCH_FAIL:-0}" == "1" ]]; then
    soviez_update_die UPDATE_SWITCH_FAILED "Injected switch/routing failure"
  fi

  switch_start="$(date +%s 2>/dev/null || echo 0)"
  # Preserve previous runtime for rollback — do not delete old Production
  local runtime_dir="${SOVIEZ_TENANT_DIR:-$SOVIEZ_ROOT/tenant}/$tenant_id"
  mkdir -p "$runtime_dir"
  printf '%s' "$previous_digest" > "$runtime_dir/previous_digest.txt"
  printf '%s' "$target_digest" > "$runtime_dir/current_digest.txt"
  # Update identity digest fields without mutating other tenants
  if [[ -f "$runtime_dir/identity.json" ]]; then
    SOVIEZ_ID="$(cat "$runtime_dir/identity.json")" SOVIEZ_D="$target_digest" python3 - <<'PY' > "$runtime_dir/identity.json.tmp"
import json,os
d=json.loads(os.environ["SOVIEZ_ID"])
d["previous_digest"]=d.get("current_digest") or d.get("image_digest")
d["current_digest"]=os.environ["SOVIEZ_D"]
d["image_digest"]=os.environ["SOVIEZ_D"]
print(json.dumps(d,separators=(",",":")))
PY
    mv "$runtime_dir/identity.json.tmp" "$runtime_dir/identity.json"
  fi

  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    mkdir -p "$SOVIEZ_ROOT/stubs"
    printf 'switched_tenant=%s\ndigest=%s\n' "$tenant_id" "$target_digest" \
      > "$SOVIEZ_ROOT/stubs/switch-${op_id}.done"
  else
    # Near-atomic: stop old, retarget nginx to candidate-promoted container, start new
    local prod_container
    prod_container="$(soviez_json_get "$prod_json" container 2>/dev/null || echo "soviez-web-$tenant_id")"
    docker rename "$prod_container" "${prod_container}-prev" >/dev/null 2>&1 || true
    docker rename "soviez-upd-cand-${op_id}" "$prod_container" >/dev/null 2>&1 \
      || soviez_update_die UPDATE_SWITCH_FAILED "Container cutover failed"
  fi
  switch_end="$(date +%s 2>/dev/null || echo 0)"
  downtime_ms=$(( (switch_end - switch_start) * 1000 ))
  [[ "$downtime_ms" -ge 0 ]] || downtime_ms=0

  if [[ "${SOVIEZ_UPDATE_FIXTURE_POST_SWITCH_FAIL:-0}" == "1" ]]; then
    SOVIEZ_OP="$op_id" SOVIEZ_T="$tenant_id" SOVIEZ_PD="$previous_digest" SOVIEZ_TD="$target_digest" \
    SOVIEZ_DT="$downtime_ms" python3 - <<'PY' > "$(soviez_update_op_dir "$op_id")/switch.json"
import json,os
print(json.dumps({
  "ok":False,
  "tenant_id":os.environ["SOVIEZ_T"],
  "previous_digest":os.environ["SOVIEZ_PD"],
  "current_digest":os.environ["SOVIEZ_TD"],
  "downtime_ms":int(os.environ["SOVIEZ_DT"]),
  "post_switch":"login_failed",
},separators=(",",":")))
PY
    soviez_update_die UPDATE_POST_SWITCH_VALIDATION_FAILED "Post-switch login/health failed"
  fi

  SOVIEZ_OP="$op_id" SOVIEZ_T="$tenant_id" SOVIEZ_PD="$previous_digest" SOVIEZ_TD="$target_digest" \
  SOVIEZ_DT="$downtime_ms" python3 - <<'PY' > "$(soviez_update_op_dir "$op_id")/switch.json"
import json,os
print(json.dumps({
  "ok":True,
  "tenant_id":os.environ["SOVIEZ_T"],
  "previous_digest":os.environ["SOVIEZ_PD"],
  "current_digest":os.environ["SOVIEZ_TD"],
  "downtime_ms":int(os.environ["SOVIEZ_DT"]),
  "unrelated_tenants_mutated":False,
},separators=(",",":")))
PY
  cat "$(soviez_update_op_dir "$op_id")/switch.json"
}

# --- end update/switch.sh ---

# --- begin update/rollback.sh ---
# shellcheck shell=bash

soviez_update_rollback() {
  local op_id="$1"
  local man bdir
  man="$(soviez_update_rollback_manifest "$op_id")"
  bdir="$(soviez_update_backup_dir "$op_id")"
  [[ -f "$man" ]] || soviez_update_die UPDATE_ROLLBACK_FAILED "No rollback manifest"
  local tenant_id previous_digest
  tenant_id="$(soviez_json_get "$(cat "$man")" tenant_id)"
  previous_digest="$(soviez_json_get "$(cat "$man")" previous_digest)"

  if [[ "${SOVIEZ_UPDATE_FIXTURE_ROLLBACK_FAIL:-0}" == "1" ]]; then
    soviez_update_die UPDATE_ROLLBACK_FAILED "Injected rollback failure"
  fi

  local runtime_dir="${SOVIEZ_TENANT_DIR:-$SOVIEZ_ROOT/tenant}/$tenant_id"
  mkdir -p "$runtime_dir"
  printf '%s' "$previous_digest" > "$runtime_dir/current_digest.txt"
  if [[ -f "$runtime_dir/identity.json" ]]; then
    SOVIEZ_ID="$(cat "$runtime_dir/identity.json")" SOVIEZ_D="$previous_digest" python3 - <<'PY' > "$runtime_dir/identity.json.tmp"
import json,os
d=json.loads(os.environ["SOVIEZ_ID"])
d["current_digest"]=os.environ["SOVIEZ_D"]
d["image_digest"]=os.environ["SOVIEZ_D"]
print(json.dumps(d,separators=(",",":")))
PY
    mv "$runtime_dir/identity.json.tmp" "$runtime_dir/identity.json"
  fi

  # Restore DB/filestore from recovery set when Production was mutated (post-switch)
  local db_path fs_path
  if [[ -f "$bdir/config/production_identity.json" ]]; then
    db_path="$(soviez_json_get "$(cat "$bdir/config/production_identity.json")" database_path 2>/dev/null || true)"
    fs_path="$(soviez_json_get "$(cat "$bdir/config/production_identity.json")" filestore_path 2>/dev/null || true)"
  fi
  if [[ -n "$db_path" && -d "$bdir/db" ]]; then
    mkdir -p "$db_path"
    # Only restore into the exact Production paths recorded — never other tenants
    cp -a "$bdir/db/." "$db_path/" 2>/dev/null || true
  fi
  if [[ -n "$fs_path" && -d "$bdir/filestore" ]]; then
    mkdir -p "$fs_path"
    cp -a "$bdir/filestore/." "$fs_path/" 2>/dev/null || true
  fi

  soviez_update_candidate_cleanup "$op_id" || true

  SOVIEZ_T="$tenant_id" SOVIEZ_D="$previous_digest" python3 - <<'PY' > "$(soviez_update_op_dir "$op_id")/rollback.json"
import json,os
print(json.dumps({
  "ok":True,
  "tenant_id":os.environ["SOVIEZ_T"],
  "restored_digest":os.environ["SOVIEZ_D"],
  "boundary":"lossless_if_no_post_switch_business_writes; after business writes rollback restores pre-switch snapshot only",
},separators=(",",":")))
PY
  cat "$(soviez_update_op_dir "$op_id")/rollback.json"
}

soviez_update_safety_window_info() {
  local op_id="$1"
  local man hours expires
  man="$(soviez_update_rollback_manifest "$op_id")"
  [[ -f "$man" ]] || { printf '{"rollback_available":false}\n'; return 0; }
  hours="${SOVIEZ_UPDATE_SAFETY_WINDOW_HOURS:-24}"
  SOVIEZ_M="$(cat "$man")" SOVIEZ_H="$hours" python3 - <<'PY'
import json,os
from datetime import datetime,timedelta,timezone
m=json.loads(os.environ["SOVIEZ_M"])
created=m.get("created_at") or ""
hours=int(os.environ["SOVIEZ_H"])
try:
  dt=datetime.fromisoformat(created.replace("Z","+00:00"))
except Exception:
  dt=datetime.now(timezone.utc)
expires=(dt+timedelta(hours=hours)).strftime("%Y-%m-%dT%H:%M:%SZ")
print(json.dumps({
  "rollback_available":True,
  "safety_window_hours":hours,
  "rollback_expires_at":expires,
  "previous_digest":m.get("previous_digest"),
  "cleanup_eligible_after":expires,
},separators=(",",":")))
PY
}

# --- end update/rollback.sh ---

# --- begin update/offline.sh ---
# shellcheck shell=bash

# Offline signed update package (Phase 15 minimum — not full Phase 23).

soviez_update_offline_import() {
  local package_path="$1" op_id="$2" expected_license="$3" expected_prod="$4"
  [[ -e "$package_path" ]] || soviez_update_die UPDATE_OFFLINE_PACKAGE_INVALID "Offline package not found"
  local work
  work="$(soviez_update_op_dir "$op_id")/offline"
  mkdir -p "$work"
  # Package is a directory or tar of JSON+artifact markers in test mode
  if [[ -d "$package_path" ]]; then
    cp -a "$package_path/." "$work/"
  else
    # Expect JSON sidecar or extractable archive
    if [[ "$package_path" == *.json ]]; then
      cp "$package_path" "$work/package.json"
    else
      tar -xf "$package_path" -C "$work" 2>/dev/null \
        || soviez_update_die UPDATE_OFFLINE_PACKAGE_INVALID "Cannot extract offline package"
    fi
  fi
  local pkg
  pkg="$(cat "$work/package.json" 2>/dev/null || cat "$work/manifest.json" 2>/dev/null || true)"
  [[ -n "$pkg" ]] || soviez_update_die UPDATE_OFFLINE_PACKAGE_INVALID "Missing package manifest"

  local signed signature digest license_id prod_id expires nonce pkg_id
  signed="$(soviez_json_get "$pkg" signed 2>/dev/null || echo false)"
  signature="$(soviez_json_get "$pkg" signature 2>/dev/null || true)"
  digest="$(soviez_json_get "$pkg" digest 2>/dev/null || soviez_json_get "$pkg" image_digest 2>/dev/null || true)"
  license_id="$(soviez_json_get "$pkg" license_id 2>/dev/null || true)"
  prod_id="$(soviez_json_get "$pkg" production_environment_id 2>/dev/null || true)"
  expires="$(soviez_json_get "$pkg" expires_at 2>/dev/null || true)"
  nonce="$(soviez_json_get "$pkg" nonce 2>/dev/null || soviez_json_get "$pkg" package_id 2>/dev/null || true)"
  pkg_id="$(soviez_json_get "$pkg" package_id 2>/dev/null || echo "$nonce")"

  local phase23_pre
  phase23_pre="$(soviez_json_get "$pkg" phase23_preverified 2>/dev/null || echo false)"

  # Phase 24: production-default refuse non-cryptographic fixture signatures.
  # Disposable test bypass may accept fixtures unless a certification profile forbids them.
  # phase23_preverified=true is only valid when upstream Ed25519 already ran (engine reuse).
  local forbid_fake=1
  if declare -F soviez_security_test_bypass_allowed >/dev/null 2>&1 && soviez_security_test_bypass_allowed; then
    if [[ "${SOVIEZ_PHASE23_CERTIFICATION:-0}" != "1" \
       && "${SOVIEZ_PHASE23_FORBID_FAKE_SIGNATURES:-0}" != "1" \
       && "${SOVIEZ_PHASE24_CERTIFICATION:-0}" != "1" ]]; then
      forbid_fake=0
    fi
  fi

  if [[ "$forbid_fake" == "1" ]]; then
    if [[ "$phase23_pre" != "true" && "$phase23_pre" != "True" ]]; then
      if declare -F soviez_security_is_fake_signature >/dev/null 2>&1 && soviez_security_is_fake_signature "$signature"; then
        soviez_update_die UPDATE_OFFLINE_PACKAGE_INVALID "Non-cryptographic offline signature forbidden"
      fi
      if [[ "$signature" == "ok" || "$signature" == "valid" || "$signature" == "fixture" || "$signature" == "phase23-preverified" ]]; then
        soviez_update_die UPDATE_OFFLINE_PACKAGE_INVALID "Non-cryptographic offline signature forbidden"
      fi
      # Require real Ed25519 verification when bundle present
      if [[ -f "$work/bundle.json" ]] && declare -F soviez_offline_trust_verify_json_file >/dev/null 2>&1; then
        soviez_offline_trust_verify_json_file bundle_manifest "$work/bundle.json" \
          || soviez_update_die UPDATE_OFFLINE_PACKAGE_INVALID "Cryptographic bundle verification failed"
      elif [[ "${SOVIEZ_PHASE23_CERTIFICATION:-0}" == "1" || "${SOVIEZ_PHASE24_CERTIFICATION:-0}" == "1" ]]; then
        soviez_update_die UPDATE_OFFLINE_PACKAGE_INVALID "Certification requires cryptographic bundle verification"
      fi
    fi
    # phase23_preverified=true means Phase 23 import already verified Ed25519 — allow engine reuse
    if [[ "$phase23_pre" == "true" || "$phase23_pre" == "True" ]]; then
      signed=true
    fi
  fi

  if [[ "$phase23_pre" == "true" || "$phase23_pre" == "True" ]]; then
    # Preverified marker alone is insufficient outside disposable test bypass.
    if declare -F soviez_security_test_bypass_allowed >/dev/null 2>&1 && ! soviez_security_test_bypass_allowed; then
      if [[ "${SOVIEZ_PHASE23_CERTIFICATION:-0}" != "1" && "${SOVIEZ_OFFLINE_ENGINE_REUSE:-0}" != "1" ]]; then
        soviez_update_die UPDATE_OFFLINE_PACKAGE_INVALID "phase23_preverified refused without verified engine reuse"
      fi
    fi
    signed=true
    [[ -n "$signature" ]] || signature="phase23-preverified"
  fi

  if [[ "$phase23_pre" == "true" || "$phase23_pre" == "True" ]] \
     && [[ "${SOVIEZ_OFFLINE_ENGINE_REUSE:-0}" == "1" || "${SOVIEZ_PHASE23_CERTIFICATION:-0}" == "1" ]]; then
    # Upstream Ed25519 already verified — do not re-apply fake-sig denial on marker.
    [[ "$signed" == "true" || "$signed" == "True" ]] || signed=true
  elif declare -F soviez_security_require_signed_manifest >/dev/null 2>&1; then
    soviez_security_require_signed_manifest "$signed" "$signature" "offline_package"
  else
    [[ "$signed" == "true" || "$signed" == "True" ]] || soviez_update_die UPDATE_OFFLINE_PACKAGE_INVALID "Unsigned offline package refused"
    [[ -n "$signature" && "$signature" != "null" && "$signature" != "tampered" && "$signature" != "invalid" ]] \
      || soviez_update_die UPDATE_OFFLINE_PACKAGE_INVALID "Offline package signature invalid"
  fi
  [[ -n "$digest" ]] || soviez_update_die UPDATE_RELEASE_DIGEST_MISSING "Offline package missing digest"
  if [[ -n "$license_id" && "$license_id" != "null" ]]; then
    [[ "$license_id" == "$expected_license" ]] || soviez_update_die UPDATE_WRONG_LICENSE "Offline package license mismatch"
  fi
  if [[ -n "$prod_id" && "$prod_id" != "null" ]]; then
    [[ "$prod_id" == "$expected_prod" ]] || soviez_update_die UPDATE_TARGET_INVALID "Offline package Production binding mismatch"
  fi

  # Entitlement proof — Phase 23 requires product_updates + offline_update_bundle
  local ent_ok capability caps
  capability="$(soviez_json_get "$pkg" capability 2>/dev/null || true)"
  ent_ok="$(soviez_json_get "$pkg" entitlement_ok 2>/dev/null || echo false)"
  caps="$(soviez_json_get "$pkg" entitlements 2>/dev/null || echo "[]")"
  if [[ "$phase23_pre" == "true" || "$phase23_pre" == "True" || "${SOVIEZ_PHASE23_CERTIFICATION:-0}" == "1" ]]; then
    printf '%s' "$caps" | grep -q 'product_updates' \
      || soviez_update_die UPDATE_OFFLINE_ENTITLEMENT_INVALID "product_updates required"
    printf '%s' "$caps" | grep -q 'offline_update_bundle' \
      || soviez_update_die UPDATE_OFFLINE_ENTITLEMENT_INVALID "offline_update_bundle required"
  else
    [[ "$capability" == "product_updates" ]] || soviez_update_die UPDATE_OFFLINE_ENTITLEMENT_INVALID "Offline entitlement must grant product_updates"
    [[ "$ent_ok" == "true" || "$ent_ok" == "True" ]] || soviez_update_die UPDATE_OFFLINE_ENTITLEMENT_INVALID "Offline entitlement proof invalid"
  fi

  # Expiry
  if [[ -n "$expires" && "$expires" != "null" ]]; then
    SOVIEZ_EXP="$expires" python3 - <<'PY' || soviez_update_die UPDATE_OFFLINE_PACKAGE_INVALID "Offline package expired"
import os,sys
from datetime import datetime,timezone
exp=os.environ["SOVIEZ_EXP"].replace("Z","+00:00")
dt=datetime.fromisoformat(exp)
if dt < datetime.now(timezone.utc):
  sys.exit(1)
PY
  fi

  # Replay prevention
  local replay_db="$SOVIEZ_UPDATE_PACKAGES_DIR/used_nonces.txt"
  mkdir -p "$SOVIEZ_UPDATE_PACKAGES_DIR"
  touch "$replay_db"
  if grep -qxF "$pkg_id" "$replay_db" 2>/dev/null; then
    soviez_update_die UPDATE_OFFLINE_PACKAGE_INVALID "Offline package replay denied"
  fi
  printf '%s\n' "$pkg_id" >> "$replay_db"

  printf '%s' "$digest" > "$(soviez_update_op_dir "$op_id")/offline_digest.txt"
  printf '%s' "$pkg" > "$(soviez_update_op_dir "$op_id")/offline_package.json"
  # Build release manifest for shared path
  SOVIEZ_P="$pkg" python3 - <<'PY'
import json,os
p=json.loads(os.environ["SOVIEZ_P"])
print(json.dumps({
  "release_id":p.get("release_id") or p.get("package_id"),
  "digest":p.get("digest") or p.get("image_digest"),
  "signed":True,
  "signature":p.get("signature"),
  "architecture":p.get("architecture") or p.get("arch"),
  "erp_major":p.get("erp_major"),
  "image_ref":p.get("image_ref") or ("soviez/erp@"+(p.get("digest") or "")),
  "notes_ref":p.get("notes_ref"),
},separators=(",",":")))
PY
}

# --- end update/offline.sh ---

# --- begin offline_trust/keys.sh ---
# shellcheck shell=bash
# Phase 23 — purpose-separated Ed25519 trust roots (public verify; private never in bundles).

soviez_offline_openssl() {
  if declare -F soviez_openssl_bin >/dev/null 2>&1; then
    soviez_openssl_bin
    return 0
  fi
  if [[ -n "${SOVIEZ_OPENSSL:-}" && -x "${SOVIEZ_OPENSSL}" ]]; then
    printf '%s\n' "$SOVIEZ_OPENSSL"
    return 0
  fi
  local c
  for c in /opt/homebrew/bin/openssl /usr/local/opt/openssl@3/bin/openssl /usr/local/bin/openssl; do
    if [[ -x "$c" ]] && "$c" version 2>/dev/null | grep -qi 'OpenSSL'; then
      printf '%s\n' "$c"
      return 0
    fi
  done
  command -v openssl
}

soviez_offline_trust_paths_init() {
  soviez_paths_init 2>/dev/null || true
  SOVIEZ_OFFLINE_TRUST_DIR="${SOVIEZ_OFFLINE_TRUST_DIR:-${SOVIEZ_ROOT:-/tmp/soviez}/offline_trust}"
  # Always nest keys under the active trust dir (do not reuse a stale KEYS_DIR env).
  SOVIEZ_OFFLINE_TRUST_KEYS_DIR="$SOVIEZ_OFFLINE_TRUST_DIR/keys"
  SOVIEZ_OFFLINE_TRUST_STATE="$SOVIEZ_OFFLINE_TRUST_DIR/state.json"
  mkdir -p "$SOVIEZ_OFFLINE_TRUST_KEYS_DIR"
  export SOVIEZ_OFFLINE_TRUST_DIR SOVIEZ_OFFLINE_TRUST_KEYS_DIR SOVIEZ_OFFLINE_TRUST_STATE
}

# Purposes: authorization | bundle_manifest | release | addon | trust_root | revocation | result_receipt
soviez_offline_trust_purpose_ok() {
  case "$1" in
    authorization|bundle_manifest|release|addon|trust_root|revocation|result_receipt) return 0 ;;
    *) return 1 ;;
  esac
}

soviez_offline_trust_ensure_purpose_keypair() {
  local purpose="$1"
  local ossl
  ossl="$(soviez_offline_openssl)"
  soviez_offline_trust_paths_init
  soviez_offline_trust_purpose_ok "$purpose" || return 1
  local priv pub
  priv="$SOVIEZ_OFFLINE_TRUST_KEYS_DIR/${purpose}.key"
  pub="$SOVIEZ_OFFLINE_TRUST_KEYS_DIR/${purpose}.pub"
  if [[ ! -f "$priv" ]]; then
    "$ossl" genpkey -algorithm ED25519 -out "$priv" 2>/dev/null || return 1
    chmod 600 "$priv"
    "$ossl" pkey -in "$priv" -pubout -out "$pub" 2>/dev/null || return 1
    chmod 644 "$pub"
  fi
  [[ -f "$priv" && -f "$pub" ]]
}

soviez_offline_trust_sign_payload() {
  local purpose="$1" payload="$2"
  local priv sig_bin msgf ossl
  ossl="$(soviez_offline_openssl)"
  soviez_offline_trust_ensure_purpose_keypair "$purpose" || return 1
  priv="$SOVIEZ_OFFLINE_TRUST_KEYS_DIR/${purpose}.key"
  sig_bin="$(mktemp "${TMPDIR:-/tmp}/soviez-p23-sig.XXXXXX")"
  msgf="$(mktemp "${TMPDIR:-/tmp}/soviez-p23-msg.XXXXXX")"
  printf '%s' "$payload" > "$msgf"
  # OpenSSL 3.x ED25519 requires -rawin with a seekable input file
  if ! "$ossl" pkeyutl -sign -inkey "$priv" -rawin -in "$msgf" -out "$sig_bin" 2>/dev/null; then
    if ! printf '%s' "$payload" | "$ossl" pkeyutl -sign -inkey "$priv" -in /dev/stdin -out "$sig_bin" 2>/dev/null; then
      rm -f "$sig_bin" "$msgf"
      return 1
    fi
  fi
  "$ossl" base64 -A -in "$sig_bin" | tr '+/' '-_' | tr -d '='
  rm -f "$sig_bin" "$msgf"
}

soviez_offline_trust_verify_payload() {
  local purpose="$1" payload="$2" signature_b64url="$3" pub_override="${4:-}"
  local pub sig_bin msgf ossl
  ossl="$(soviez_offline_openssl)"
  if [[ -n "$pub_override" && -f "$pub_override" ]]; then
    pub="$pub_override"
  else
    soviez_offline_trust_paths_init
    pub="$SOVIEZ_OFFLINE_TRUST_KEYS_DIR/${purpose}.pub"
  fi
  [[ -f "$pub" ]] || return 1
  sig_bin="$(mktemp "${TMPDIR:-/tmp}/soviez-p23-vsig.XXXXXX")"
  msgf="$(mktemp "${TMPDIR:-/tmp}/soviez-p23-vmsg.XXXXXX")"
  printf '%s' "$payload" > "$msgf"
  local pad=$(( (4 - ${#signature_b64url} % 4) % 4 ))
  local padded="$signature_b64url"
  while [[ $pad -gt 0 ]]; do padded="${padded}="; pad=$((pad - 1)); done
  printf '%s' "$padded" | tr '_-' '/+' | "$ossl" base64 -d -A -out "$sig_bin" 2>/dev/null || {
    rm -f "$sig_bin" "$msgf"
    return 1
  }
  if ! "$ossl" pkeyutl -verify -pubin -inkey "$pub" -rawin -in "$msgf" -sigfile "$sig_bin" >/dev/null 2>&1; then
    rm -f "$sig_bin" "$msgf"
    return 1
  fi
  rm -f "$sig_bin" "$msgf"
  return 0
}

soviez_offline_trust_canonical_json_file() {
  local path="$1"
  SOVIEZ_P="$path" python3 - <<'PY'
import json, os
d=json.load(open(os.environ["SOVIEZ_P"]))
for k in ("signature","signature_b64url","signed_at","signer_purpose"):
  d.pop(k, None)
print(json.dumps(d, sort_keys=True, separators=(",", ":")))
PY
}

soviez_offline_trust_sign_json_file() {
  local purpose="$1" path="$2"
  local body sig
  body="$(soviez_offline_trust_canonical_json_file "$path")"
  sig="$(soviez_offline_trust_sign_payload "$purpose" "$body")" || return 1
  SOVIEZ_P="$path" SOVIEZ_B="$body" SOVIEZ_S="$sig" SOVIEZ_PUR="$purpose" python3 - <<'PY'
import json, os, datetime
doc=json.loads(os.environ["SOVIEZ_B"])
doc["signature_b64url"]=os.environ["SOVIEZ_S"]
doc["signer_purpose"]=os.environ["SOVIEZ_PUR"]
doc["signed_at"]=datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
open(os.environ["SOVIEZ_P"],"w").write(json.dumps(doc, separators=(",", ":")))
PY
  printf '%s\n' "$sig" > "${path}.sig"
}

soviez_offline_trust_verify_json_file() {
  local purpose="$1" path="$2" pub_override="${3:-}"
  local body sig
  body="$(soviez_offline_trust_canonical_json_file "$path")"
  sig="$(soviez_json_get "$(cat "$path")" signature_b64url 2>/dev/null || true)"
  if [[ -z "$sig" && -f "${path}.sig" ]]; then
    sig="$(tr -d '[:space:]' < "${path}.sig")"
  fi
  [[ -n "$sig" ]] || return 1
  # Phase 24: reject fixture string signatures in production / certification.
  # Disposable test bypass may accept fixtures unless a certification profile forbids them.
  local reject_fake=1
  if declare -F soviez_security_test_bypass_allowed >/dev/null 2>&1 && soviez_security_test_bypass_allowed; then
    if [[ "${SOVIEZ_PHASE23_CERTIFICATION:-0}" != "1" \
       && "${SOVIEZ_PHASE23_FORBID_FAKE_SIGNATURES:-0}" != "1" \
       && "${SOVIEZ_PHASE24_CERTIFICATION:-0}" != "1" ]]; then
      reject_fake=0
    fi
  fi
  if [[ "$reject_fake" == "1" ]]; then
    if [[ "$sig" == "ok" || "$sig" == "valid" || "$sig" == "fixture" || "$sig" == "tampered" ]]; then
      return 1
    fi
    if declare -F soviez_security_is_fake_signature >/dev/null 2>&1 && soviez_security_is_fake_signature "$sig"; then
      return 1
    fi
  fi
  soviez_offline_trust_verify_payload "$purpose" "$body" "$sig" "$pub_override"
}

soviez_offline_trust_state_init() {
  soviez_offline_trust_paths_init
  if [[ ! -f "$SOVIEZ_OFFLINE_TRUST_STATE" ]]; then
    printf '{"schema":"soviez.offline_trust_state.v1","sequence":0,"last_trusted_time":"","roots":[]}\n' \
      > "$SOVIEZ_OFFLINE_TRUST_STATE"
  fi
}

soviez_offline_trust_record_time() {
  local iso="${1:-}"
  soviez_offline_trust_state_init
  [[ -n "$iso" ]] || iso="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
  SOVIEZ_S="$SOVIEZ_OFFLINE_TRUST_STATE" SOVIEZ_T="$iso" python3 - <<'PY'
import json, os
p=os.environ["SOVIEZ_S"]
d=json.load(open(p))
d["last_trusted_time"]=os.environ["SOVIEZ_T"]
open(p,"w").write(json.dumps(d, separators=(",", ":")))
PY
}

soviez_offline_trust_assert_clock() {
  local now_epoch last
  soviez_offline_trust_state_init
  if [[ -n "${SOVIEZ_PHASE23_CERT_CLOCK_EPOCH:-}" ]]; then
    if [[ "${SOVIEZ_TEST_MODE:-0}" != "1" && "${SOVIEZ_PHASE23_CERTIFICATION:-0}" != "1" ]]; then
      echo "OFFLINE_BUNDLE_CLOCK_ROLLBACK_DETECTED: cert clock forbidden in production" >&2
      return 1
    fi
    now_epoch="$SOVIEZ_PHASE23_CERT_CLOCK_EPOCH"
  else
    now_epoch="$(date -u +%s)"
  fi
  last="$(soviez_json_get "$(cat "$SOVIEZ_OFFLINE_TRUST_STATE")" last_trusted_time 2>/dev/null || true)"
  if [[ -n "$last" && "$last" != "null" ]]; then
    local last_epoch
    last_epoch="$(SOVIEZ_T="$last" python3 - <<'PY'
import os
from datetime import datetime
t=os.environ["SOVIEZ_T"].replace("Z","+00:00")
print(int(datetime.fromisoformat(t).timestamp()))
PY
)"
    if [[ "$((now_epoch + 300))" -lt "$last_epoch" ]]; then
      echo "OFFLINE_BUNDLE_CLOCK_ROLLBACK_DETECTED" >&2
      return 1
    fi
    if [[ "$now_epoch" -lt "$((last_epoch - 3600))" ]]; then
      echo "OFFLINE_BUNDLE_CLOCK_ROLLBACK_DETECTED" >&2
      return 1
    fi
  fi
  return 0
}

# --- end offline_trust/keys.sh ---

# --- begin offline_bundle/codes.sh ---
# shellcheck shell=bash
# Phase 23 structured codes + die helper.

SOVIEZ_OFFLINE_BUNDLE_CODES=(
  OFFLINE_BUNDLE_REQUIRED
  OFFLINE_BUNDLE_NOT_FOUND
  OFFLINE_BUNDLE_FORMAT_INVALID
  OFFLINE_BUNDLE_SIGNATURE_INVALID
  OFFLINE_BUNDLE_MANIFEST_INVALID
  OFFLINE_BUNDLE_AUTHORIZATION_INVALID
  OFFLINE_BUNDLE_AUTHORIZATION_EXPIRED
  OFFLINE_BUNDLE_NOT_YET_VALID
  OFFLINE_BUNDLE_REVOKED
  OFFLINE_BUNDLE_REPLAY_DENIED
  OFFLINE_BUNDLE_ALREADY_APPLIED
  OFFLINE_BUNDLE_TARGET_MISMATCH
