        SOVIEZ_CLI_COMMAND="migration-source-archive-retry"
        SOVIEZ_CLI_OP_ID="${2:-}"
        [[ -n "$SOVIEZ_CLI_OP_ID" ]] || soviez_die "$SOVIEZ_ERR_USAGE" "--migration-source-archive-retry requires operation id"
        shift 2
        ;;
      --migration-source-archive-recover)
        SOVIEZ_CLI_COMMAND="migration-source-archive-recover"
        SOVIEZ_CLI_OP_ID="${2:-}"
        [[ -n "$SOVIEZ_CLI_OP_ID" ]] || soviez_die "$SOVIEZ_ERR_USAGE" "--migration-source-archive-recover requires operation id"
        shift 2
        ;;
      --migration-source-license-finalize)
        SOVIEZ_CLI_COMMAND="migration-source-license-finalize"
        SOVIEZ_CLI_OP_ID="${2:-}"
        [[ -n "$SOVIEZ_CLI_OP_ID" ]] || soviez_die "$SOVIEZ_ERR_USAGE" "--migration-source-license-finalize requires operation id"
        shift 2
        ;;
      --migration-source-credentials-status)
        SOVIEZ_CLI_COMMAND="migration-source-credentials-status"
        SOVIEZ_CLI_OP_ID="${2:-}"
        [[ -n "$SOVIEZ_CLI_OP_ID" ]] || soviez_die "$SOVIEZ_ERR_USAGE" "--migration-source-credentials-status requires operation id"
        shift 2
        ;;
      --migration-source-runtime-suspend)
        SOVIEZ_CLI_COMMAND="migration-source-runtime-suspend"
        SOVIEZ_CLI_OP_ID="${2:-}"
        [[ -n "$SOVIEZ_CLI_OP_ID" ]] || soviez_die "$SOVIEZ_ERR_USAGE" "--migration-source-runtime-suspend requires operation id"
        shift 2
        ;;
      --migration-source-retirement-status)
        SOVIEZ_CLI_COMMAND="migration-source-retirement-status"
        SOVIEZ_CLI_MIG_SOURCE_ID="${2:-}"
        SOVIEZ_CLI_OP_ID="${2:-}"
        [[ -n "$SOVIEZ_CLI_MIG_SOURCE_ID" ]] || soviez_die "$SOVIEZ_ERR_USAGE" "--migration-source-retirement-status requires source id"
        shift 2
        ;;
      --migration-phase23-readiness)
        SOVIEZ_CLI_COMMAND="migration-phase23-readiness"
        SOVIEZ_CLI_OP_ID="${2:-}"
        [[ -n "$SOVIEZ_CLI_OP_ID" ]] || soviez_die "$SOVIEZ_ERR_USAGE" "--migration-phase23-readiness requires operation id"
        shift 2
        ;;
      --migration-phase23-readiness-show)
        SOVIEZ_CLI_COMMAND="migration-phase23-readiness-show"
        SOVIEZ_CLI_MIG_REPORT_ID="${2:-}"
        [[ -n "$SOVIEZ_CLI_MIG_REPORT_ID" ]] || soviez_die "$SOVIEZ_ERR_USAGE" "--migration-phase23-readiness-show requires report id"
        shift 2
        ;;
      --domain-plan)
        SOVIEZ_CLI_MIG_PLAN_ID="${2:-}"
        [[ -n "$SOVIEZ_CLI_MIG_PLAN_ID" ]] || soviez_die "$SOVIEZ_ERR_USAGE" "--domain-plan requires plan id"
        shift 2
        ;;
      --domain|--fqdn)
        SOVIEZ_CLI_MIG_FQDN="${2:-}"
        [[ -n "$SOVIEZ_CLI_MIG_FQDN" ]] || soviez_die "$SOVIEZ_ERR_USAGE" "--domain/--fqdn requires value"
        shift 2
        ;;
      --migration-status|--migration-reattach|--migration-cancel|--migration-retry|--migration-recover)
        case "$1" in
          --migration-status) SOVIEZ_CLI_COMMAND="migration-status" ;;
          --migration-reattach) SOVIEZ_CLI_COMMAND="migration-reattach" ;;
          --migration-cancel) SOVIEZ_CLI_COMMAND="migration-cancel" ;;
          --migration-retry) SOVIEZ_CLI_COMMAND="migration-retry" ;;
          --migration-recover) SOVIEZ_CLI_COMMAND="migration-recover" ;;
        esac
        SOVIEZ_CLI_OP_ID="${2:-}"
        [[ -n "$SOVIEZ_CLI_OP_ID" ]] || soviez_die "$SOVIEZ_ERR_USAGE" "$1 requires operation id"
        shift 2
        ;;
      -h|--help)
        soviez_cli_usage
        exit 0
        ;;
      *)
        soviez_die "$SOVIEZ_ERR_USAGE" "Unknown argument: $1"
        ;;
    esac
  done

  [[ -n "$SOVIEZ_CLI_COMMAND" ]] || soviez_die "$SOVIEZ_ERR_USAGE" "Specify a command (see --help)"
  if [[ "$SOVIEZ_CLI_COMMAND" == "stage-retention-extend" ]]; then
    [[ -n "${SOVIEZ_CLI_RETENTION_DAYS:-}" ]] || soviez_die "$SOVIEZ_ERR_USAGE" "--stage-retention-extend requires --days <total-days>"
  fi
}

# --- end cli/parse.sh ---

# --- begin commands/security_platform.sh ---
# shellcheck shell=bash
# Security Gate S1+S2 — CLI commands.

soviez_cmd_security_check() {
  local env_file="${SOVIEZ_CLI_ENV_FILE:-${ENV_FILE:-}}"
  if [[ -n "$env_file" && -f "$env_file" ]]; then
    set -a
    # shellcheck disable=SC1090
    source "$env_file"
    set +a
  fi
  export SOVIEZ_SEC_MODE="${SOVIEZ_SEC_MODE:-production}"
  export SOVIEZ_SEC_PG_CONTAINER="${SOVIEZ_SEC_PG_CONTAINER:-${SOVIEZ_DB_CONTAINER:-${DB_CONTAINER:-}}}"
  export SOVIEZ_SEC_ODOO_CONTAINER="${SOVIEZ_SEC_ODOO_CONTAINER:-${SOVIEZ_WEB_CONTAINER:-${WEB_CONTAINER:-}}}"
  export SOVIEZ_SEC_PG_ADMIN_USER="${SOVIEZ_SEC_PG_ADMIN_USER:-${SOVIEZ_PG_ADMIN_USER:-soviez_admin}}"
  export SOVIEZ_SEC_PG_APP_USER="${SOVIEZ_SEC_PG_APP_USER:-${SOVIEZ_PG_APP_USER:-soviez_app}}"
  export SOVIEZ_SEC_PG_ADMIN_PASS="${SOVIEZ_SEC_PG_ADMIN_PASS:-${SOVIEZ_PG_ADMIN_PASSWORD:-}}"
  export SOVIEZ_SEC_PG_APP_PASS="${SOVIEZ_SEC_PG_APP_PASS:-${SOVIEZ_DB_PASSWORD:-}}"
  export SOVIEZ_SEC_ODOO_CONF="${SOVIEZ_SEC_ODOO_CONF:-}"
  export SOVIEZ_SEC_REPORT_DIR="${SOVIEZ_SEC_REPORT_DIR:-${SOVIEZ_ROOT:-.}/security/reports}"
  local rc=0
  soviez_security_validate_critical_containment || rc=1
  if declare -F soviez_security_validate_host_edge >/dev/null 2>&1; then
    # Separate report dir for S2 to avoid clobbering S1 entries mid-flight
    local s2dir="${SOVIEZ_SEC_REPORT_DIR}/s2"
    SOVIEZ_SEC_REPORT_DIR="$s2dir" soviez_security_validate_host_edge || rc=1
  fi
  return "$rc"
}

soviez_cmd_security_harden() {
  local pg="${SOVIEZ_SEC_PG_CONTAINER:-${SOVIEZ_DB_CONTAINER:-}}"
  local admin_user="${SOVIEZ_SEC_PG_ADMIN_USER:-${SOVIEZ_PG_ADMIN_USER:-soviez_admin}}"
  local admin_pass="${SOVIEZ_SEC_PG_ADMIN_PASS:-${SOVIEZ_PG_ADMIN_PASSWORD:-}}"
  local app_user="${SOVIEZ_SEC_PG_APP_USER:-${SOVIEZ_PG_APP_USER:-soviez_app}}"
  local app_pass="${SOVIEZ_SEC_PG_APP_PASS:-${SOVIEZ_DB_PASSWORD:-}}"
  if [[ -n "$pg" && -n "$admin_pass" && -n "$app_pass" ]]; then
    if declare -F soviez_sec_remediate_existing_app_role >/dev/null 2>&1; then
      soviez_sec_remediate_existing_app_role "$pg" "$admin_user" "$admin_pass" "$app_user" "$app_pass" || return 1
    elif declare -F soviez_sec_pg_provision_least_privilege >/dev/null 2>&1; then
      local dbn="${SOVIEZ_DB_NAME:-postgres}"
      soviez_sec_pg_provision_least_privilege "$pg" "$admin_user" "$admin_pass" "$app_user" "$app_pass" "$dbn" || return 1
    fi
  fi
  if declare -F soviez_sec_s2_harden >/dev/null 2>&1; then
    soviez_sec_s2_harden || true
  fi
  soviez_cmd_security_check
}

soviez_cmd_security_report() {
  local dir="${SOVIEZ_SEC_REPORT_DIR:-${SOVIEZ_ROOT:-.}/security/reports}"
  # Prefer latest S3 human report if present
  local latest
  latest="$(ls -1t "${SOVIEZ_SEC_S3_LAST_EVIDENCE:-}/report.txt" "$dir"/s3/*/report.txt "$dir"/report.txt "$dir"/*/report.txt "$dir"/critical_containment_*.txt 2>/dev/null | head -1 || true)"
  if [[ -z "$latest" || ! -f "$latest" ]]; then
    echo "No security report found under $dir" >&2
    return 1
  fi
  cat "$latest"
}

# --- end commands/security_platform.sh ---

# --- begin commands/version.sh ---
# shellcheck shell=bash

soviez_cmd_version_run() {
  local ver channel digest payload
  ver="$(soviez_version)"
  channel="$(soviez_platform_channel)"
  if [[ -f "$(soviez_platform_current_dir)/CHANNEL" ]]; then
    channel="$(tr -d '[:space:]' <"$(soviez_platform_current_dir)/CHANNEL")"
  fi
  digest="$(soviez_platform_installed_digest)"
  payload="$(soviez_platform_payload)"
  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    payload="${SOVIEZ_ROOT}/platform/current/soviez.sh"
    if [[ -f "${SOVIEZ_ROOT}/platform/current/CHANNEL" ]]; then
      channel="$(tr -d '[:space:]' <"${SOVIEZ_ROOT}/platform/current/CHANNEL")"
    fi
    if [[ -f "${SOVIEZ_ROOT}/platform/current/soviez.sh.sha256" ]]; then
      digest="$(awk 'NR==1{print $1}' "${SOVIEZ_ROOT}/platform/current/soviez.sh.sha256")"
    fi
  fi
  cat <<EOF
Soviez.sh ${ver}
Channel: ${channel}
Artifact: sha256:${digest}
Payload: ${payload}
EOF
}

# --- end commands/version.sh ---

# --- begin commands/list.sh ---
# shellcheck shell=bash
# List every Soviez-managed environment on this server (local-only).

soviez_cmd_list_run() {
  printf '%-11s %-16s %-40s %s\n' "TYPE" "ID" "DOMAIN" "STATUS"
  local found=0

  # Productions from tenant identity files
  local tenant_root
  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    tenant_root="${SOVIEZ_ROOT}/tenant"
  else
    tenant_root="${SOVIEZ_TENANT_DIR:-/var/soviez/tenant}"
  fi
  if [[ -d "$tenant_root" ]]; then
    local ident id domain status
    while IFS= read -r -d '' ident; do
      id="$(soviez_json_get "$(cat "$ident")" id 2>/dev/null || soviez_json_get "$(cat "$ident")" production_id 2>/dev/null || basename "$(dirname "$ident")")"
      domain="$(soviez_json_get "$(cat "$ident")" domain 2>/dev/null || soviez_json_get "$(cat "$ident")" production_domain 2>/dev/null || echo "-")"
      status="$(soviez_json_get "$(cat "$ident")" lifecycle_status 2>/dev/null || echo "unknown")"
      # Map common statuses for display
      case "$status" in
        running|active) status="Running" ;;
        stopped) status="Stopped" ;;
        *) status="${status:-unknown}" ;;
      esac
      printf '%-11s %-16s %-40s %s\n' "Production" "$id" "$domain" "$status"
      found=1
    done < <(find "$tenant_root" -type f -name 'identity.json' -print0 2>/dev/null)
  fi

  # Legacy env sheets (best-effort)
  local envf
  for envf in /root/.soviez_*.env "${SOVIEZ_ROOT:-}/.soviez_*.env"; do
    [[ -f "$envf" ]] || continue
    # shellcheck disable=SC1090
    domain="$(grep -E '^DOMAIN=' "$envf" 2>/dev/null | head -1 | cut -d= -f2- | tr -d '"' || true)"
    id="$(basename "$envf" | sed 's/^\.soviez_//;s/\.env$//')"
    status="Unknown"
    if command -v docker >/dev/null 2>&1; then
      if docker ps --format '{{.Names}}' 2>/dev/null | grep -q "soviez-web-${id}"; then
        status="Running"
      elif docker ps -a --format '{{.Names}}' 2>/dev/null | grep -q "soviez-web-${id}"; then
        status="Stopped"
      fi
    fi
    printf '%-11s %-16s %-40s %s\n' "Production" "$id" "${domain:--}" "$status"
    found=1
  done

  # Stages
  if declare -F soviez_stage_paths_init >/dev/null 2>&1; then
    soviez_stage_paths_init 2>/dev/null || true
  fi
  if declare -F soviez_stage_inventory_list_ids >/dev/null 2>&1; then
    local sid ident domain status
    while IFS= read -r sid; do
      [[ -z "$sid" ]] && continue
      ident="$(soviez_stage_inventory_find "$sid" 2>/dev/null || true)"
      [[ -n "$ident" ]] || continue
      domain="$(soviez_json_get "$ident" stage_domain 2>/dev/null || echo "-")"
      status="$(soviez_json_get "$ident" lifecycle_status 2>/dev/null || echo unknown)"
      case "$status" in
        running) status="Running" ;;
        stopped|certified) status="Stopped" ;;
      esac
      printf '%-11s %-16s %-40s %s\n' "Stage" "$sid" "$domain" "$status"
      found=1
    done < <(soviez_stage_inventory_list_ids 2>/dev/null || true)
  fi

  if [[ "$found" -eq 0 ]]; then
    printf '%-11s %-16s %-40s %s\n' "-" "-" "-" "No environments found"
  fi
}

# --- end commands/list.sh ---

# --- begin commands/tune.sh ---
# shellcheck shell=bash

soviez_cmd_tune_run() {
  local dry="${SOVIEZ_CLI_DRY_RUN:-0}"
  local prod_n=0 stage_n=0
  if declare -F soviez_stage_inventory_list_ids >/dev/null 2>&1; then
    stage_n="$(soviez_stage_inventory_list_ids 2>/dev/null | grep -c . || true)"
  fi
  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    prod_n="$(find "${SOVIEZ_ROOT}/tenant" -name identity.json 2>/dev/null | wc -l | tr -d ' ')"
  else
    prod_n="$(find "${SOVIEZ_TENANT_DIR:-/var/soviez/tenant}" -name identity.json 2>/dev/null | wc -l | tr -d ' ')"
  fi
  prod_n="${prod_n:-1}"
  [[ "$prod_n" -ge 1 ]] || prod_n=1

  local profile
  profile="$(soviez_sizing_calculate "$prod_n" "$stage_n" 0 0)"
  echo "=== Soviez sizing plan ==="
  printf '%s\n' "$profile"

  local state_dir
  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    state_dir="${SOVIEZ_ROOT}/tuning"
  else
    state_dir="/var/soviez/tuning"
  fi
  mkdir -p "$state_dir"

  # Idempotency: identical effective profile → no apply / no restart.
  if [[ -f "${state_dir}/profile.json" ]]; then
    if SOVIEZ_NEW_PROFILE="$profile" python3 - "$state_dir/profile.json" <<'PY'
import json, os, sys
new=json.loads(os.environ["SOVIEZ_NEW_PROFILE"])
old=json.load(open(sys.argv[1],encoding="utf-8"))
keys=("odoo","postgres","docker","topology")
same=all(old.get(k)==new.get(k) for k in keys)
sys.exit(0 if same else 1)
PY
    then
      echo "[ok] no effective changes (idempotent)"
      return 0
    fi
  fi

  if [[ "$dry" == "1" ]]; then
    echo "[dry-run] proposed changes above; no system state modified"
    echo "[dry-run] restart may be required for: odoo workers/memory, postgres shared_buffers, docker shm"
    return 0
  fi

  # Checkpoint
  if [[ -f "${state_dir}/profile.json" ]]; then
    cp -f "${state_dir}/profile.json" "${state_dir}/profile.prev.json"
  fi
  local conf="${SOVIEZ_TUNE_ODOO_CONF:-}"
  local conf_bak=""
  if [[ -n "$conf" && -f "$conf" ]]; then
    conf_bak="${state_dir}/odoo.conf.bak"
    cp -f "$conf" "$conf_bak"
  fi

  printf '%s\n' "$profile" >"${state_dir}/profile.json.new"
  mv -f "${state_dir}/profile.json.new" "${state_dir}/profile.json"
  printf '%s\n' "$profile" >"${state_dir}/postgres.recommended.json"

  if [[ -n "$conf" && -f "$conf" ]]; then
    local workers soft hard cron
    workers="$(python3 -c 'import json,sys; print(json.load(sys.stdin)["odoo"]["workers"])' <<<"$profile")"
    soft="$(python3 -c 'import json,sys; print(json.load(sys.stdin)["odoo"]["limit_memory_soft"])' <<<"$profile")"
    hard="$(python3 -c 'import json,sys; print(json.load(sys.stdin)["odoo"]["limit_memory_hard"])' <<<"$profile")"
    cron="$(python3 -c 'import json,sys; print(json.load(sys.stdin)["odoo"]["max_cron_threads"])' <<<"$profile")"
    if declare -F soviez_sec__odoo_conf_set_option >/dev/null 2>&1; then
      soviez_sec__odoo_conf_set_option "$conf" workers "$workers" || {
        soviez_cmd_tune_rollback "$state_dir" "$conf" "$conf_bak"
        return 1
      }
      soviez_sec__odoo_conf_set_option "$conf" max_cron_threads "$cron"
      soviez_sec__odoo_conf_set_option "$conf" limit_memory_soft "$soft"
      soviez_sec__odoo_conf_set_option "$conf" limit_memory_hard "$hard"
      soviez_sec__odoo_conf_set_option "$conf" proxy_mode True
      soviez_sec__odoo_conf_set_option "$conf" list_db False
      if [[ "$workers" -gt 0 ]]; then
        soviez_sec__odoo_conf_set_option "$conf" gevent_port 8072
      fi
    fi
    # Verify managed keys present
    if declare -F soviez_ws_assert_odoo_conf >/dev/null 2>&1; then
      if ! soviez_ws_assert_odoo_conf "$conf"; then
        soviez_cmd_tune_rollback "$state_dir" "$conf" "$conf_bak"
        echo "[error] tune verification failed; rolled back" >&2
        return 1
      fi
    fi
  fi

  echo "[ok] tuning profile saved to ${state_dir}/profile.json"
  echo "[ok] apply complete (restart services only if values changed and require it)"
}

soviez_cmd_tune_rollback() {
  local state_dir="$1" conf="${2:-}" conf_bak="${3:-}"
  if [[ -f "${state_dir}/profile.prev.json" ]]; then
    mv -f "${state_dir}/profile.prev.json" "${state_dir}/profile.json"
  fi
  if [[ -n "$conf" && -n "$conf_bak" && -f "$conf_bak" ]]; then
    cp -f "$conf_bak" "$conf"
  fi
  echo "[warn] tune rollback restored previous configuration" >&2
}

soviez_cmd_platform_install_run() {
  soviez_platform_install_self_payload
}

# --- end commands/tune.sh ---

# --- begin commands/new.sh ---
# shellcheck shell=bash

soviez_cmd_new_run() {
  local op_id="${SOVIEZ_CLI_OP_ID:-}"
  [[ -n "$op_id" ]] || op_id="$(soviez_op_create)"
  export SOVIEZ_ACTIVE_OP_ID="$op_id"
  soviez_op_acquire_lock "$op_id"
  trap '[[ -n "${SOVIEZ_ACTIVE_OP_ID:-}" ]] && soviez_op_release_lock "$SOVIEZ_ACTIVE_OP_ID"' EXIT

  local state
  state="$(soviez_op_read_state "$op_id")"
  soviez_ui_dashboard_show "$state"

  if soviez_sm_should_run_step "$state" preflight; then
    soviez_op_transition "$op_id" preflight
    soviez_preflight_run
  fi
  state="$(soviez_op_read_state "$op_id")"

  if soviez_sm_should_run_step "$state" waiting_for_connection_consent; then
    soviez_op_transition "$op_id" waiting_for_connection_consent
    soviez_ui_consent_prompt
  fi
  state="$(soviez_op_read_state "$op_id")"

  if soviez_sm_should_run_step "$state" device_authorization_pending; then
    soviez_op_transition "$op_id" device_authorization_pending
    local start_json cred_json
    start_json="$(soviez_device_client_start)"
    soviez_json_merge_file "$(soviez_operation_state_file "$op_id")" \
      "$(SOVIEZ_START="$start_json" python3 - <<'PY'
import json, os
print(json.dumps({"device_auth": json.loads(os.environ["SOVIEZ_START"])}))
PY
)"
    if ! soviez_device_client_load_credential >/dev/null 2>&1; then
      cred_json="$(soviez_device_client_authorize "$start_json")"
      soviez_json_merge_file "$(soviez_operation_state_file "$op_id")" \
        "$(SOVIEZ_CRED="$(soviez_json_get "$cred_json" device_id)" python3 - <<'PY'
import json, os
print(json.dumps({"device_id": os.environ["SOVIEZ_CRED"]}))
PY
)"
    fi
    soviez_op_transition "$op_id" device_authorized
  fi
  state="$(soviez_op_read_state "$op_id")"

  local slot_id release_id digest image_ref container db_name tenant_id fingerprint activation_key
  if soviez_sm_should_run_step "$state" slot_reserved; then
    local reserve_json
    reserve_json="$(soviez_slots_reserve "$op_id")"
    slot_id="$(soviez_json_get "$reserve_json" slot_id)"
    soviez_json_merge_file "$(soviez_operation_state_file "$op_id")" \
      "$(SOVIEZ_SLOT="$slot_id" python3 - <<'PY'
import json, os
print(json.dumps({"slot_id": os.environ["SOVIEZ_SLOT"]}))
PY
)"
    soviez_op_transition "$op_id" slot_reserved
  else
    slot_id="$(soviez_json_get "$(cat "$(soviez_operation_state_file "$op_id")")" slot_id)"
  fi
  state="$(soviez_op_read_state "$op_id")"

  if soviez_sm_should_run_step "$state" release_resolved; then
    local release_json
    release_json="$(soviez_registry_resolve_release "$SOVIEZ_CLI_CHANNEL")"
    release_id="$(soviez_json_get "$release_json" release_id)"
    digest="$(soviez_json_get "$release_json" digest)"
    soviez_manifest_verify "$release_json" "$digest"
    soviez_json_merge_file "$(soviez_operation_state_file "$op_id")" \
      "$(SOVIEZ_RID="$release_id" SOVIEZ_DIGEST="$digest" python3 - <<'PY'
import json, os
print(json.dumps({"release_id": os.environ["SOVIEZ_RID"], "digest": os.environ["SOVIEZ_DIGEST"]}))
PY
)"
    soviez_op_transition "$op_id" release_resolved
  else
    digest="$(soviez_json_get "$(cat "$(soviez_operation_state_file "$op_id")")" digest)"
  fi
  state="$(soviez_op_read_state "$op_id")"

  if soviez_sm_should_run_step "$state" image_pull_authorized; then
    local pull_json session_id registry_user registry_pass gateway_url repository image_ref fields
    local release_id_cur
    release_id_cur="$(soviez_json_get "$(cat "$(soviez_operation_state_file "$op_id")")" release_id)"
    pull_json="$(soviez_registry_create_pull_session "$release_id_cur" "$digest" "$op_id" "production_new")"
    fields="$(soviez_registry_session_fields "$pull_json")"
    IFS='|' read -r session_id registry_user registry_pass gateway_url repository _digest_field image_ref <<<"$fields"
    [[ -n "$session_id" && -n "$registry_pass" && -n "$image_ref" ]] || \
      soviez_die "$SOVIEZ_ERR_API" "Registry pull session response incomplete"
    if [[ -n "${SOVIEZ_REGISTRY_GATEWAY_URL:-}" ]]; then
      gateway_url="$SOVIEZ_REGISTRY_GATEWAY_URL"
    elif [[ -n "$gateway_url" ]]; then
      export SOVIEZ_REGISTRY_GATEWAY_URL="$gateway_url"
    fi
    soviez_json_merge_file "$(soviez_operation_state_file "$op_id")" \
      "$(SOVIEZ_SID="$session_id" SOVIEZ_IMG="$image_ref" SOVIEZ_REPO="${repository:-}" python3 - <<'PY'
import json, os
print(json.dumps({
  "pull_session_id": os.environ["SOVIEZ_SID"],
  "image_ref": os.environ["SOVIEZ_IMG"],
  "repository": os.environ.get("SOVIEZ_REPO", ""),
}))
PY
)"
    soviez_op_transition "$op_id" image_pull_authorized
    soviez_pull_client_run "$image_ref" "$registry_user" "$registry_pass" "$digest" "$gateway_url"
    unset registry_pass
    soviez_registry_complete_pull_session "$session_id" || true
    soviez_op_transition "$op_id" image_pulled "$(SOVIEZ_DIGEST="$digest" python3 - <<'PY'
import json, os
print(json.dumps({"digest": os.environ["SOVIEZ_DIGEST"]}))
PY
)"
  else
    image_ref="$(soviez_json_get "$(cat "$(soviez_operation_state_file "$op_id")")" image_ref)"
  fi
  state="$(soviez_op_read_state "$op_id")"

  if soviez_sm_should_run_step "$state" tenant_identity_created; then
    tenant_id="$(soviez_tenant_identity_create "$op_id")"
    soviez_json_merge_file "$(soviez_operation_state_file "$op_id")" \
      "$(SOVIEZ_TID="$tenant_id" python3 - <<'PY'
import json, os
print(json.dumps({"tenant_id": os.environ["SOVIEZ_TID"]}))
PY
)"
    soviez_op_transition "$op_id" tenant_identity_created
  else
    tenant_id="$(soviez_json_get "$(cat "$(soviez_operation_state_file "$op_id")")" tenant_id 2>/dev/null || soviez_tenant_identity_load || true)"
  fi
  state="$(soviez_op_read_state "$op_id")"

  if soviez_sm_should_run_step "$state" database_provisioned; then
    db_name="$(soviez_database_provision "$op_id")"
    soviez_json_merge_file "$(soviez_operation_state_file "$op_id")" \
      "$(SOVIEZ_DB="$db_name" python3 - <<'PY'
import json, os
print(json.dumps({"db_name": os.environ["SOVIEZ_DB"]}))
PY
)"
    soviez_op_transition "$op_id" database_provisioned
  else
    db_name="$(soviez_json_get "$(cat "$(soviez_operation_state_file "$op_id")")" db_name 2>/dev/null || soviez_tenant_secret_read db_name || true)"
  fi
  state="$(soviez_op_read_state "$op_id")"

  if soviez_sm_should_run_step "$state" container_started; then
    container="$(soviez_docker_provision_start "$op_id" "$image_ref")"
    soviez_json_merge_file "$(soviez_operation_state_file "$op_id")" \
      "$(SOVIEZ_CTR="$container" python3 - <<'PY'
import json, os
print(json.dumps({"container": os.environ["SOVIEZ_CTR"]}))
PY
)"
    soviez_op_transition "$op_id" container_started
  else
    container="$(soviez_json_get "$(cat "$(soviez_operation_state_file "$op_id")")" container 2>/dev/null || printf 'soviez-web-%s' "$op_id")"
  fi
  state="$(soviez_op_read_state "$op_id")"


  # Security Gate S1 — after containers started, before completed.
  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" && "${SOVIEZ_SEC_FORCE_GATE:-0}" != "1" ]]; then
    local _app_sec _adm_sec
    _app_sec="$(soviez_tenant_secret_read db_password 2>/dev/null || true)"
    _adm_sec="$(soviez_tenant_secret_read pg_admin_password 2>/dev/null || true)"
    if declare -F soviez_sec_password_assert_not_weak >/dev/null 2>&1; then
      [[ -n "$_app_sec" ]] && soviez_sec_password_assert_not_weak "$_app_sec" "db_password"
      [[ -n "$_adm_sec" ]] && soviez_sec_password_assert_not_weak "$_adm_sec" "pg_admin_password"
    fi
  else
    local _pg _web
    _pg="${SOVIEZ_DB_CONTAINER:-soviez-db-${op_id}}"
    _web="${container:-soviez-web-${op_id}}"
    if docker inspect "$_pg" >/dev/null 2>&1 && docker inspect "$_web" >/dev/null 2>&1; then
      export SOVIEZ_SEC_MODE="${SOVIEZ_SEC_MODE:-production}"
      export SOVIEZ_SEC_PG_CONTAINER="$_pg"
      export SOVIEZ_SEC_ODOO_CONTAINER="$_web"
      export SOVIEZ_SEC_PG_ADMIN_PASS="$(soviez_tenant_secret_read pg_admin_password 2>/dev/null || true)"
      export SOVIEZ_SEC_PG_APP_PASS="$(soviez_tenant_secret_read db_password 2>/dev/null || true)"
      export SOVIEZ_SEC_REPORT_DIR="${SOVIEZ_ROOT:-.}/security/reports"
      if declare -F soviez_security_gate_require_pass >/dev/null 2>&1; then
        soviez_security_gate_require_pass || return 1
      elif declare -F soviez_security_validate_critical_containment >/dev/null 2>&1; then
        soviez_security_validate_critical_containment || return 1
      fi
    fi
  fi

  local domain="${SOVIEZ_CLI_DOMAIN:-test.local.soviez}"
  if soviez_sm_should_run_step "$state" instance_provisioned; then
    if [[ -n "$SOVIEZ_CLI_DOMAIN" ]]; then
      soviez_op_transition "$op_id" domain_pending
      soviez_op_transition "$op_id" waiting_for_dns
      soviez_op_transition "$op_id" ssl_pending
      local ssl_lines cert key ca
      ssl_lines="$(soviez_ssl_local_issue_cert "$domain")"
      cert="$(printf '%s\n' "$ssl_lines" | sed -n '1p')"
      key="$(printf '%s\n' "$ssl_lines" | sed -n '2p')"
      ca="$(printf '%s\n' "$ssl_lines" | sed -n '3p')"
      soviez_ssl_validate_chain "$cert" "$ca"
      soviez_nginx_render_config "$domain" "$container:8069"
    fi
    soviez_slots_instance_provisioned "$slot_id" >/dev/null
    soviez_op_transition "$op_id" instance_provisioned "$(SOVIEZ_DOMAIN="$domain" python3 - <<'PY'
import json, os
print(json.dumps({"domain": os.environ["SOVIEZ_DOMAIN"]}))
PY
)"
  fi
  state="$(soviez_op_read_state "$op_id")"

  if soviez_sm_should_run_step "$state" fingerprint_bound; then
    fingerprint="$(soviez_license_compute_fingerprint "$op_id" "$tenant_id")"
    soviez_slots_bind_fingerprint "$slot_id" "$fingerprint" >/dev/null
    soviez_op_transition "$op_id" fingerprint_bound "$(SOVIEZ_FP="$fingerprint" python3 - <<'PY'
import json, os
print(json.dumps({"fingerprint": os.environ["SOVIEZ_FP"]}))
PY
)"
  fi
  state="$(soviez_op_read_state "$op_id")"

  local method
  method="$(soviez_license_choose_activation_method "$SOVIEZ_CLI_ACTIVATION_METHOD")"
  if soviez_sm_should_run_step "$state" license_issued; then
    soviez_op_transition "$op_id" waiting_for_activation_method
    soviez_slots_activation_method "$slot_id" "$method" >/dev/null
    local license_json
    license_json="$(soviez_slots_issue_license "$slot_id")"
    activation_key="$(soviez_json_get "$license_json" activation_key)"
    soviez_tenant_secret_write "activation_key" "$activation_key"
    soviez_op_transition "$op_id" license_issued
  else
    activation_key="$(soviez_tenant_secret_read activation_key 2>/dev/null || true)"
  fi
  state="$(soviez_op_read_state "$op_id")"

  state="$(soviez_op_read_state "$op_id")"
  if [[ "$method" == "automatic" ]]; then
    if soviez_sm_should_run_step "$state" activated; then
      soviez_op_transition "$op_id" activation_pending
      soviez_license_activate_via_odoo "$container" "$db_name" "$activation_key"
      soviez_op_transition "$op_id" activated
      soviez_license_send_activation_ack "$slot_id"
    fi
    state="$(soviez_op_read_state "$op_id")"
    if soviez_sm_should_run_step "$state" completed; then
      soviez_op_transition "$op_id" validating
      soviez_op_transition "$op_id" completed
    fi
  else
    if soviez_sm_should_run_step "$state" completed_activation_pending; then
      soviez_op_transition "$op_id" activation_pending
      soviez_op_transition "$op_id" manual_activation_pending
      soviez_op_transition "$op_id" completed_activation_pending
    fi
  fi

  soviez_log_info "Operation $op_id finished in state $(soviez_op_read_state "$op_id")"
  printf '%s\n' "$op_id"
}

# --- end commands/new.sh ---

# --- begin commands/reattach.sh ---
# shellcheck shell=bash

soviez_cmd_reattach_run() {
  local op_id="$SOVIEZ_CLI_OP_ID"
  local state_file
  state_file="$(soviez_operation_state_file "$op_id")"
  [[ -f "$state_file" ]] || soviez_die "$SOVIEZ_ERR_STATE" "Operation not found: $op_id"

  local state
  state="$(soviez_op_read_state "$op_id")"
  soviez_log_info "Reattaching to operation $op_id (state=$state)"

  if soviez_systemd_reattach "$op_id"; then
    soviez_log_info "Worker heartbeat present"
  fi

  case "$state" in
    completed|failed_terminal|canceled)
      soviez_log_info "Operation already terminal: $state"
      ;;
    manual_activation_pending|completed_activation_pending|activation_pending)
      SOVIEZ_CLI_OP_ID="$op_id"
      soviez_cmd_new_run
      ;;
    *)
      SOVIEZ_CLI_OP_ID="$op_id"
      soviez_cmd_new_run
      ;;
  esac
}

# --- end commands/reattach.sh ---

# --- begin commands/stage.sh ---
# shellcheck shell=bash
# Phase 11 — soviez.sh --stage connected creation pipeline.

soviez_cmd_stage_create_run() {
  soviez_stage_paths_init
  local op_id="${SOVIEZ_CLI_OP_ID:-}"
  if [[ -n "$op_id" ]]; then
    soviez_stage_op_create "$op_id" >/dev/null
  else
    op_id="$(soviez_stage_op_create)"
  fi
  export SOVIEZ_ACTIVE_STAGE_OP_ID="$op_id"
  soviez_log_info "Stage operation $op_id starting"

  # Optional durable worker: controller launches worker and exits (disconnect-safe).
  if [[ "${SOVIEZ_STAGE_DURABLE_WORKER:-0}" == "1" && "${SOVIEZ_STAGE_WORKER_INNER:-0}" != "1" ]]; then
    local envf
    envf="$(soviez_stage_op_dir "$op_id")/worker.env"
    mkdir -p "$(soviez_stage_op_dir "$op_id")/auth"
    chmod 700 "$(soviez_stage_op_dir "$op_id")/auth"
    {
      echo "export SOVIEZ_STAGE_WORKER_INNER=1"
      echo "export SOVIEZ_STAGE_DURABLE_WORKER=0"
      echo "export SOVIEZ_TEST_MODE=${SOVIEZ_TEST_MODE:-0}"
      echo "export SOVIEZ_ROOT=$(printf '%q' "${SOVIEZ_ROOT}")"
      echo "export SOVIEZ_SH_ROOT=$(printf '%q' "${SOVIEZ_SH_ROOT}")"
      echo "export SOVIEZ_HOST_PUBKEY_FINGERPRINT=$(printf '%q' "${SOVIEZ_HOST_PUBKEY_FINGERPRINT:-}")"
      echo "export SOVIEZ_CLI_STAGE_ID=$(printf '%q' "${SOVIEZ_CLI_STAGE_ID:-}")"
      echo "export SOVIEZ_CLI_STAGE_DOMAIN=$(printf '%q' "${SOVIEZ_CLI_STAGE_DOMAIN:-}")"
      echo "export SOVIEZ_CLI_OP_ID=$(printf '%q' "$op_id")"
      echo "export SOVIEZ_STAGE_FIXTURE_SKIP_DEVICE=${SOVIEZ_STAGE_FIXTURE_SKIP_DEVICE:-0}"
      echo "export SOVIEZ_STAGE_FIXTURE_SKIP_REMOTE=${SOVIEZ_STAGE_FIXTURE_SKIP_REMOTE:-0}"
      echo "export SOVIEZ_STAGE_DNS_OK=${SOVIEZ_STAGE_DNS_OK:-0}"
      echo "export SOVIEZ_STAGE_ADMISSION_FORCE=${SOVIEZ_STAGE_ADMISSION_FORCE:-0}"
      echo "export SOVIEZ_STAGE_USE_LIVE_PG=${SOVIEZ_STAGE_USE_LIVE_PG:-0}"
      echo "export SOVIEZ_STAGE_PAUSE_AT=$(printf '%q' "${SOVIEZ_STAGE_PAUSE_AT:-}")"
      echo "export SOVIEZ_STAGE_PAUSE_MAX_SEC=${SOVIEZ_STAGE_PAUSE_MAX_SEC:-120}"
      echo "export SOVIEZ_STAGE_HELPER_BIN=$(printf '%q' "${SOVIEZ_STAGE_HELPER_BIN:-}")"
      echo "export SOVIEZ_STAGE_INSTALLER_PATH=$(printf '%q' "${SOVIEZ_STAGE_INSTALLER_PATH:-}")"
      if [[ -n "${SOVIEZ_STAGE_FIXTURE_PRODUCTION_JSON:-}" ]]; then
        printf '%s' "$SOVIEZ_STAGE_FIXTURE_PRODUCTION_JSON" > "$(soviez_stage_op_dir "$op_id")/auth/production.json"
        chmod 600 "$(soviez_stage_op_dir "$op_id")/auth/production.json"
        echo "export SOVIEZ_STAGE_FIXTURE_PRODUCTION_FROM_FILE=1"
      fi
      if [[ -n "${SOVIEZ_STAGE_FIXTURE_FILESTORE:-}" ]]; then
        echo "export SOVIEZ_STAGE_FIXTURE_FILESTORE=$(printf '%q' "$SOVIEZ_STAGE_FIXTURE_FILESTORE")"
      fi
      if [[ -n "${SOVIEZ_STAGE_FIXTURE_TICKET_TOKEN:-}" ]]; then
        printf '%s' "$SOVIEZ_STAGE_FIXTURE_TICKET_TOKEN" > "$(soviez_stage_op_dir "$op_id")/auth/ticket.token.pending"
        chmod 600 "$(soviez_stage_op_dir "$op_id")/auth/ticket.token.pending"
        echo "export SOVIEZ_STAGE_FIXTURE_TICKET_FROM_FILE=1"
      fi
      if [[ -n "${SOVIEZ_STAGE_FIXTURE_PUBLIC_KEYS_JSON:-}" ]]; then
        printf '%s' "$SOVIEZ_STAGE_FIXTURE_PUBLIC_KEYS_JSON" > "$(soviez_stage_op_dir "$op_id")/auth/keys.json"
        chmod 600 "$(soviez_stage_op_dir "$op_id")/auth/keys.json"
      fi
      if [[ -n "${SOVIEZ_STAGE_FIXTURE_AUTHORIZE_JSON:-}" ]]; then
        printf '%s' "$SOVIEZ_STAGE_FIXTURE_AUTHORIZE_JSON" > "$(soviez_stage_op_dir "$op_id")/auth/authorize.json"
        chmod 600 "$(soviez_stage_op_dir "$op_id")/auth/authorize.json"
        echo "export SOVIEZ_STAGE_FIXTURE_AUTHORIZE_FROM_FILE=1"
      fi
      if [[ -n "${SOVIEZ_STAGE_FIXTURE_ENTITLEMENT_JSON:-}" ]]; then
        printf '%s' "$SOVIEZ_STAGE_FIXTURE_ENTITLEMENT_JSON" > "$(soviez_stage_op_dir "$op_id")/auth/entitlement.json"
        chmod 600 "$(soviez_stage_op_dir "$op_id")/auth/entitlement.json"
        echo "export SOVIEZ_STAGE_FIXTURE_ENTITLEMENT_FROM_FILE=1"
      fi
      if [[ -n "${SOVIEZ_PG_PASSWORD:-}" ]]; then
        printf '%s' "$SOVIEZ_PG_PASSWORD" > "$(soviez_stage_op_dir "$op_id")/auth/pg.password"
        chmod 600 "$(soviez_stage_op_dir "$op_id")/auth/pg.password"
        echo "export SOVIEZ_PG_PASSWORD_FILE=$(printf '%q' "$(soviez_stage_op_dir "$op_id")/auth/pg.password")"
      fi
      [[ -n "${SOVIEZ_PG_HOST:-}" ]] && echo "export SOVIEZ_PG_HOST=$(printf '%q' "$SOVIEZ_PG_HOST")"
      [[ -n "${SOVIEZ_PG_PORT:-}" ]] && echo "export SOVIEZ_PG_PORT=$(printf '%q' "$SOVIEZ_PG_PORT")"
      [[ -n "${SOVIEZ_PG_USER:-}" ]] && echo "export SOVIEZ_PG_USER=$(printf '%q' "$SOVIEZ_PG_USER")"
      [[ -n "${SOVIEZ_PG_CONTAINER:-}" ]] && echo "export SOVIEZ_PG_CONTAINER=$(printf '%q' "$SOVIEZ_PG_CONTAINER")"
    } > "$envf"
    chmod 600 "$envf"
    soviez_stage_start_durable_worker "$op_id"
    echo "Durable Stage worker started for $op_id"
    echo "Reattach: soviez.sh --stage-reattach $op_id"
    return 0
  fi

  # Reload ticket/entitlement from files when launched as worker.
  if [[ "${SOVIEZ_STAGE_FIXTURE_PRODUCTION_FROM_FILE:-0}" == "1" && -f "$(soviez_stage_op_dir "$op_id")/auth/production.json" ]]; then
    export SOVIEZ_STAGE_FIXTURE_PRODUCTION_JSON
    SOVIEZ_STAGE_FIXTURE_PRODUCTION_JSON="$(cat "$(soviez_stage_op_dir "$op_id")/auth/production.json")"
  fi
  if [[ "${SOVIEZ_STAGE_FIXTURE_TICKET_FROM_FILE:-0}" == "1" && -f "$(soviez_stage_op_dir "$op_id")/auth/ticket.token.pending" ]]; then
    export SOVIEZ_STAGE_FIXTURE_TICKET_TOKEN
    SOVIEZ_STAGE_FIXTURE_TICKET_TOKEN="$(cat "$(soviez_stage_op_dir "$op_id")/auth/ticket.token.pending")"
  fi
  if [[ "${SOVIEZ_STAGE_FIXTURE_AUTHORIZE_FROM_FILE:-0}" == "1" && -f "$(soviez_stage_op_dir "$op_id")/auth/authorize.json" ]]; then
    export SOVIEZ_STAGE_FIXTURE_AUTHORIZE_JSON
    SOVIEZ_STAGE_FIXTURE_AUTHORIZE_JSON="$(cat "$(soviez_stage_op_dir "$op_id")/auth/authorize.json")"
  fi
  if [[ "${SOVIEZ_STAGE_FIXTURE_ENTITLEMENT_FROM_FILE:-0}" == "1" && -f "$(soviez_stage_op_dir "$op_id")/auth/entitlement.json" ]]; then
    export SOVIEZ_STAGE_FIXTURE_ENTITLEMENT_JSON
    SOVIEZ_STAGE_FIXTURE_ENTITLEMENT_JSON="$(cat "$(soviez_stage_op_dir "$op_id")/auth/entitlement.json")"
  fi
  if [[ -n "${SOVIEZ_PG_PASSWORD_FILE:-}" && -f "${SOVIEZ_PG_PASSWORD_FILE}" ]]; then
    export SOVIEZ_PG_PASSWORD
    SOVIEZ_PG_PASSWORD="$(cat "$SOVIEZ_PG_PASSWORD_FILE")"
  fi
  if [[ -f "$(soviez_stage_op_dir "$op_id")/auth/keys.json" && -z "${SOVIEZ_STAGE_FIXTURE_PUBLIC_KEYS_JSON:-}" ]]; then
    export SOVIEZ_STAGE_FIXTURE_PUBLIC_KEYS_JSON
    SOVIEZ_STAGE_FIXTURE_PUBLIC_KEYS_JSON="$(cat "$(soviez_stage_op_dir "$op_id")/auth/keys.json")"
  fi

  local state
  state="$(soviez_stage_op_read_state "$op_id")"

  if soviez_stage_sm_should_run "$state" preflight; then
    soviez_stage_op_transition "$op_id" preflight
    soviez_preflight_run 2>/dev/null || true
    soviez_stage_checkpoint "$op_id" preflight
  fi
  state="$(soviez_stage_op_read_state "$op_id")"

  local prod_json
  if soviez_stage_sm_should_run "$state" production_selected; then
    prod_json="$(soviez_stage_select_production)"
    soviez_stage_validate_production "$prod_json"
    soviez_stage_op_merge "$op_id" "$(SOVIEZ_P="$prod_json" python3 - <<'PY'
import json,os
print(json.dumps({"production": json.loads(os.environ["SOVIEZ_P"])}))
PY
)"
    soviez_stage_op_transition "$op_id" production_selected
    soviez_stage_checkpoint "$op_id" production_selected
  else
    prod_json="$(soviez_json_get "$(cat "$(soviez_stage_op_state_file "$op_id")")" production)"
  fi
  state="$(soviez_stage_op_read_state "$op_id")"

  local stage_id stage_domain license_id fingerprint db_uuid tenant_id
  license_id="$(soviez_json_get "$prod_json" license_id)"
  fingerprint="$(soviez_json_get "$prod_json" production_fingerprint)"
  db_uuid="$(soviez_json_get "$prod_json" database_uuid)"
  tenant_id="$(soviez_json_get "$prod_json" tenant_id)"
  stage_id="${SOVIEZ_CLI_STAGE_ID:-}"
  stage_domain="${SOVIEZ_CLI_STAGE_DOMAIN:-${SOVIEZ_CLI_DOMAIN:-}}"

  if [[ -z "$stage_id" ]]; then
    if [[ -t 0 ]]; then
      printf 'Stage ID: ' >&2
      read -r stage_id
    else
      soviez_stage_die STAGE_ID_CONFLICT "Pass --stage-id"
    fi
  fi
  if [[ -z "$stage_domain" ]]; then
    if [[ -t 0 ]]; then
      printf 'Stage domain: ' >&2
      read -r stage_domain
    else
      soviez_stage_die STAGE_DOMAIN_CONFLICT "Pass --stage-domain"
    fi
  fi

  local release_digest tooling_digest
  release_digest="${SOVIEZ_CLI_RELEASE_DIGEST:-sha256:bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb}"
  tooling_digest="${SOVIEZ_CLI_TOOLING_DIGEST:-sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa}"

  if soviez_stage_sm_should_run "$state" identity_reserved; then
    local identity
    identity="$(soviez_stage_identity_reserve "$stage_id" "$tenant_id" "$license_id" \
      "$fingerprint" "$db_uuid" "$stage_domain" "$release_digest" "$tooling_digest" "$op_id" \
      "$(soviez_json_get "$prod_json" domain 2>/dev/null || true)")"
    stage_id="$(soviez_json_get "$identity" stage_id)"
    soviez_stage_op_merge "$op_id" "$(SOVIEZ_I="$identity" python3 - <<'PY'
import json,os
print(json.dumps({"stage_id": json.loads(os.environ["SOVIEZ_I"])["stage_id"], "identity": json.loads(os.environ["SOVIEZ_I"])}))
PY
)"
    soviez_stage_op_transition "$op_id" identity_reserved
    soviez_stage_checkpoint "$op_id" identity_reserved
  else
    stage_id="$(soviez_json_get "$(cat "$(soviez_stage_op_state_file "$op_id")")" stage_id)"
    if [[ -z "$stage_domain" ]]; then
      stage_domain="$(soviez_json_get "$(soviez_stage_inventory_find "$stage_id")" stage_domain 2>/dev/null || true)"
    fi
    if [[ -z "$release_digest" || "$release_digest" == sha256:bbbb* ]]; then
      release_digest="$(soviez_json_get "$(soviez_stage_inventory_find "$stage_id")" release_digest 2>/dev/null || echo "$release_digest")"
    fi
    if [[ -z "$tooling_digest" || "$tooling_digest" == sha256:aaaa* ]]; then
      tooling_digest="$(soviez_json_get "$(soviez_stage_inventory_find "$stage_id")" tooling_digest 2>/dev/null || echo "$tooling_digest")"
    fi
  fi
  state="$(soviez_stage_op_read_state "$op_id")"

  if soviez_stage_sm_should_run "$state" resource_admission; then
    local src_db_bytes=1048576 src_fs_bytes=1048576
    if [[ -n "${SOVIEZ_STAGE_FIXTURE_FILESTORE:-}" ]]; then
      src_fs_bytes="$(soviez_stage_measure_path_bytes "$SOVIEZ_STAGE_FIXTURE_FILESTORE")"
    fi
    local admission
    admission="$(soviez_stage_admission_evaluate "$src_db_bytes" "$src_fs_bytes")"
    soviez_stage_admission_require "$admission"
    soviez_stage_op_merge "$op_id" "$(SOVIEZ_A="$admission" python3 - <<'PY'
import json,os
print(json.dumps({"admission": json.loads(os.environ["SOVIEZ_A"])}))
PY
)"
    soviez_stage_op_transition "$op_id" resource_admission
    soviez_stage_checkpoint "$op_id" resource_admission
  fi
  state="$(soviez_stage_op_read_state "$op_id")"

  # Device + entitlement (silent if credential present)
  if soviez_stage_sm_should_run "$state" device_authorized; then
    if [[ "${SOVIEZ_STAGE_OFFLINE:-0}" == "1" || "${SOVIEZ_STAGE_BLOCK_SAAS:-0}" == "1" ]]; then
      :
    elif ! soviez_device_client_load_credential >/dev/null 2>&1; then
      if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" && "${SOVIEZ_STAGE_FIXTURE_SKIP_DEVICE:-0}" == "1" ]]; then
        :
      else
        soviez_stage_op_transition "$op_id" waiting_for_connection_consent
        soviez_ui_consent_prompt 2>/dev/null || true
        local start_json
        start_json="$(soviez_device_client_start)"
        soviez_device_client_authorize "$start_json" >/dev/null
      fi
    fi
    soviez_stage_op_transition "$op_id" device_authorized
    soviez_stage_checkpoint "$op_id" device_authorized
  fi
  state="$(soviez_stage_op_read_state "$op_id")"

  if soviez_stage_sm_should_run "$state" entitlement_checked; then
    local ent allowed
    if [[ "${SOVIEZ_STAGE_OFFLINE:-0}" == "1" ]]; then
      # Offline package binding verification is the entitlement gate — no SaaS check.
      allowed=true
      ent='{"allowed":true,"offline":true}'
    else
      ent="$(soviez_stage_entitlement_check "$license_id" stage_create)"
      allowed="$(soviez_json_get "$ent" allowed 2>/dev/null || echo false)"
    fi
    if [[ "$allowed" != "true" && "$allowed" != "True" ]]; then
      local dcode
      dcode="$(soviez_json_get "$ent" denial_code 2>/dev/null || echo STAGE_ENTITLEMENT_REQUIRED)"
      [[ -n "$dcode" ]] || dcode=STAGE_ENTITLEMENT_REQUIRED
      case "$dcode" in
        *EXPIRED*|*PAST_DUE*) soviez_stage_die STAGE_ENTITLEMENT_EXPIRED "Stage entitlement not active" ;;
        *) soviez_stage_die STAGE_ENTITLEMENT_REQUIRED "Stage entitlement required ($dcode)" ;;
      esac
    fi
    soviez_stage_op_transition "$op_id" entitlement_checked
    soviez_stage_checkpoint "$op_id" entitlement_checked
  fi
  state="$(soviez_stage_op_read_state "$op_id")"

  local authorization_id ticket_token ticket_claims_file
  if soviez_stage_sm_should_run "$state" operation_authorized; then
    if [[ "${SOVIEZ_STAGE_OFFLINE_TICKET_READY:-0}" == "1" ]]; then
      authorization_id="$(soviez_json_get "$(cat "$(soviez_stage_op_state_file "$op_id")")" authorization_id 2>/dev/null || echo offline-auth)"
      ticket_token="$(cat "$(soviez_stage_op_dir "$op_id")/auth/ticket.token" 2>/dev/null || true)"
      [[ -n "$ticket_token" ]] || soviez_stage_die TICKET_INVALID "Offline ticket missing after import"
      soviez_stage_op_merge "$op_id" '{"ticket_present": true, "offline": true}'
      soviez_stage_op_transition "$op_id" operation_authorized
      soviez_stage_checkpoint "$op_id" operation_authorized
    else
    local host_fp
    host_fp="${SOVIEZ_HOST_PUBKEY_FINGERPRINT:-fp_host_fixture}"
    local auth_body
    auth_body="$(python3 - <<PY
import json
print(json.dumps({
  "license_id": "$license_id",
  "operation_id": "$op_id",
  "operation_type": "stage_create",
  "production_fingerprint": "$fingerprint",
  "database_uuid": "$db_uuid",
  "stage_id": "$stage_id",
  "stage_domain": "$stage_domain",
  "host_pubkey_fingerprint": "$host_fp",
  "architecture": "linux/amd64",
  "idempotency_key": "stage-create-$op_id",
}))
PY
)"
    local auth_resp
    if [[ "${SOVIEZ_STAGE_BLOCK_SAAS:-0}" == "1" ]]; then
      soviez_stage_die OPERATION_AUTHORIZATION_FAILED "SaaS blocked on offline target"
    fi
    auth_resp="$(soviez_stage_operations_authorize "$auth_body")"
    local ok
    ok="$(soviez_json_get "$auth_resp" ok 2>/dev/null || echo false)"
    if [[ "$ok" != "true" && "$ok" != "True" ]]; then
      soviez_stage_die OPERATION_AUTHORIZATION_FAILED "$(soviez_json_get "$auth_resp" denial_code 2>/dev/null || echo denied)"
    fi
    authorization_id="$(soviez_json_get "$auth_resp" authorization_id)"
    ticket_token="$(soviez_json_get "$auth_resp" ticket.token 2>/dev/null || soviez_json_get "$auth_resp" "ticket" | python3 -c 'import json,sys; t=json.load(sys.stdin); print(t.get("token",""))' 2>/dev/null || true)"
    if [[ -z "$ticket_token" || "$ticket_token" == "null" ]]; then
      # Fixture may embed token at top level
      ticket_token="$(soviez_json_get "$auth_resp" ticket_token 2>/dev/null || true)"
    fi
    [[ -n "$ticket_token" && "$ticket_token" != "null" ]] || soviez_stage_die TICKET_INVALID "Authorize response missing ticket"

    local work
    work="$(soviez_stage_op_dir "$op_id")/auth"
    mkdir -p "$work"
    chmod 700 "$work"
    printf '%s' "$ticket_token" > "$work/ticket.token"
    chmod 600 "$work/ticket.token"
    if [[ -n "${SOVIEZ_STAGE_FIXTURE_PUBLIC_KEYS_JSON:-}" ]]; then
      printf '%s' "$SOVIEZ_STAGE_FIXTURE_PUBLIC_KEYS_JSON" > "$work/keys.json"
      chmod 600 "$work/keys.json"
    fi
    # Never persist raw device credentials in operation JSON — only safe ids.
    soviez_stage_op_merge "$op_id" "$(python3 - <<PY
import json
print(json.dumps({"authorization_id": "$authorization_id", "ticket_present": True}))
PY
)"
    soviez_stage_inventory_update_field "$stage_id" "$(python3 - <<PY
import json
print(json.dumps({"authorization_id": "$authorization_id"}))
PY
)"
    soviez_stage_op_transition "$op_id" operation_authorized
    soviez_stage_checkpoint "$op_id" operation_authorized
    fi
  else
    authorization_id="$(soviez_json_get "$(cat "$(soviez_stage_op_state_file "$op_id")")" authorization_id)"
    ticket_token="$(cat "$(soviez_stage_op_dir "$op_id")/auth/ticket.token" 2>/dev/null || true)"
  fi
  state="$(soviez_stage_op_read_state "$op_id")"

  if soviez_stage_sm_should_run "$state" tooling_authorized; then
    # Tooling resolved from authorize metadata / fixture digest pin — no public latest.
    soviez_stage_op_transition "$op_id" tooling_authorized
    mkdir -p "$SOVIEZ_STAGE_TOOLING_CACHE/$tooling_digest"
    printf 'digest=%s\n' "$tooling_digest" > "$SOVIEZ_STAGE_TOOLING_CACHE/$tooling_digest/ARTIFACT.ok"
    soviez_stage_op_transition "$op_id" tooling_pulled
    soviez_stage_checkpoint "$op_id" tooling_pulled
  fi
  state="$(soviez_stage_op_read_state "$op_id")"

  if soviez_stage_sm_should_run "$state" ticket_verified; then
    local work keys_file expect_file
    work="$(soviez_stage_op_dir "$op_id")/auth"
    keys_file="$work/keys.json"
    expect_file="$work/expect.json"
    if [[ ! -f "$keys_file" ]]; then
      printf '%s\n' "${SOVIEZ_STAGE_FIXTURE_PUBLIC_KEYS_JSON:-{}}" > "$keys_file"
    fi
    python3 - <<PY > "$expect_file"
import json
print(json.dumps({
  "license_id": "$license_id",
  "device_id": "${SOVIEZ_STAGE_FIXTURE_DEVICE_ID:-dddddddd-dddd-dddd-dddd-dddddddddddd}",
  "host_pubkey_fingerprint": "${SOVIEZ_HOST_PUBKEY_FINGERPRINT:-fp_host_fixture}",
  "production_fingerprint": "$fingerprint",
  "database_uuid": "$db_uuid",
  "stage_id": "$stage_id",
  "stage_domain": "$stage_domain",
  "operation_type": "stage_create",
  "release_digest": "$release_digest",
  "tooling_digest": "$tooling_digest",
  "architecture": "linux/amd64",
}))
PY
    if [[ "${SOVIEZ_STAGE_FIXTURE_SKIP_HELPER_VERIFY:-0}" == "1" ]]; then
      # Still require helper for neutralize; verify may be short-circuited only with explicit fixture offline offline-ledger path.
      soviez_log_info "Fixture skip helper verify (offline/unit harness only)"
    else
      # Bash Boolean cannot skip: without valid ticket+keys helper fails.
      local ledger_arg=""
      if [[ "${SOVIEZ_STAGE_USE_LEDGER:-0}" == "1" || "${SOVIEZ_STAGE_OFFLINE:-0}" == "1" ]]; then
        ledger_arg="$SOVIEZ_STAGE_LEDGER"
      fi
      if [[ -f "$work/ticket.token" && -s "$keys_file" && "$(cat "$keys_file")" != "{}" ]]; then
        if [[ -n "$ledger_arg" ]]; then
          soviez_stage_helper_run_verify "$work/ticket.token" "$keys_file" "$expect_file" "$ledger_arg" >/dev/null
        else
          soviez_stage_helper_run_verify "$work/ticket.token" "$keys_file" "$expect_file" >/dev/null
        fi
      elif [[ "${SOVIEZ_TEST_MODE:-0}" == "1" && -n "${SOVIEZ_STAGE_FIXTURE_TICKET_TOKEN:-}" ]]; then
        printf '%s' "$SOVIEZ_STAGE_FIXTURE_TICKET_TOKEN" > "$work/ticket.token"
        printf '%s' "$SOVIEZ_STAGE_FIXTURE_PUBLIC_KEYS_JSON" > "$keys_file"
        if [[ -n "$ledger_arg" ]]; then
          soviez_stage_helper_run_verify "$work/ticket.token" "$keys_file" "$expect_file" "$ledger_arg" >/dev/null
        else
          soviez_stage_helper_run_verify "$work/ticket.token" "$keys_file" "$expect_file" >/dev/null
        fi
      else
        soviez_stage_die TICKET_INVALID "Ticket verification requires helper and valid keys"
      fi
    fi
    # Enforce: a forced Bash entitlement true without ticket cannot certify later.
    soviez_stage_op_transition "$op_id" ticket_verified
    soviez_stage_checkpoint "$op_id" ticket_verified
  fi
  state="$(soviez_stage_op_read_state "$op_id")"

  local dump_file snap_fs
  if soviez_stage_sm_should_run "$state" snapshot_preparing; then
    soviez_stage_op_transition "$op_id" snapshot_preparing
    soviez_stage_checkpoint "$op_id" snapshot_preparing
    local source_db source_fs
    source_db="$(soviez_json_get "$prod_json" database_name)"
    source_fs="${SOVIEZ_STAGE_FIXTURE_FILESTORE:-$(soviez_json_get "$prod_json" filestore_path 2>/dev/null || echo "")}"
    dump_file="$(soviez_stage_snapshot_db "$op_id" "${source_db:-production}")"
    soviez_stage_op_transition "$op_id" database_snapshot_created
    soviez_stage_checkpoint "$op_id" database_snapshot_created
    snap_fs="$(soviez_stage_snapshot_filestore "$op_id" "${source_fs:-$SOVIEZ_ROOT/fixtures/prod-filestore}")"
    # Prove Production filestore unchanged when source checksum recorded.
    soviez_stage_op_transition "$op_id" filestore_snapshot_created
    soviez_stage_checkpoint "$op_id" filestore_snapshot_created
  else
    dump_file="$(soviez_stage_snapshot_dir "$op_id")/db.dump"
    snap_fs="$(soviez_stage_snapshot_dir "$op_id")/filestore"
  fi
  state="$(soviez_stage_op_read_state "$op_id")"

  if soviez_stage_sm_should_run "$state" database_restoring; then
    soviez_stage_op_transition "$op_id" database_restoring
    soviez_stage_checkpoint "$op_id" database_restoring
    local identity db_name stage_uuid
    identity="$(soviez_stage_inventory_find "$stage_id")"
    db_name="$(soviez_json_get "$identity" stage_db_name)"
    stage_uuid="$(soviez_stage_restore_database "$op_id" "$db_name" "$dump_file")"
    soviez_stage_inventory_update_field "$stage_id" "$(python3 - <<PY
import json
print(json.dumps({"stage_database_uuid": "$stage_uuid"}))
PY
)"
    soviez_stage_op_transition "$op_id" filestore_restoring
    soviez_stage_checkpoint "$op_id" filestore_restoring
    soviez_stage_restore_filestore "$stage_id" "$snap_fs"
  fi
  state="$(soviez_stage_op_read_state "$op_id")"

  if soviez_stage_sm_should_run "$state" stage_runtime_created; then
    soviez_stage_runtime_create "$stage_id" >/dev/null
    soviez_stage_op_transition "$op_id" stage_runtime_created
    soviez_stage_checkpoint "$op_id" stage_runtime_created
  fi
  state="$(soviez_stage_op_read_state "$op_id")"

  if soviez_stage_sm_should_run "$state" neutralization_running; then
    soviez_stage_op_transition "$op_id" neutralization_running
    soviez_stage_checkpoint "$op_id" neutralization_running
    soviez_stage_neutralize_apply "$stage_id"
    local controls claims_file controls_file cert_out helper_out
    controls="$(soviez_stage_neutralize_controls_json "$stage_id")"
    work="$(soviez_stage_op_dir "$op_id")/auth"
    claims_file="$work/claims.json"
    controls_file="$work/controls.json"
    cert_out="$(soviez_stage_origin_cert_file "$stage_id")"
    printf '%s' "$controls" > "$controls_file"
    # Minimal claims for helper neutralize (from expect / identity)
    python3 - <<PY > "$claims_file"
import json
print(json.dumps({
  "typ": "soviez.stage-operation.v1",
  "protocol_version": "stage-operation/v1",
  "jti": "local",
  "operation_id": "$op_id",
  "operation_type": "stage_create",
  "subject_pseudonym": "sub_local",
  "account_id": "00000000-0000-0000-0000-000000000000",
  "license_id": "$license_id",
  "device_id": "${SOVIEZ_STAGE_FIXTURE_DEVICE_ID:-dddddddd-dddd-dddd-dddd-dddddddddddd}",
  "device_pubkey_fingerprint": "fp",
  "host_pubkey_fingerprint": "${SOVIEZ_HOST_PUBKEY_FINGERPRINT:-fp_host_fixture}",
  "production_fingerprint": "$fingerprint",
  "database_uuid": "$db_uuid",
  "stage_id": "$stage_id",
  "stage_domain": "$stage_domain",
  "release_id": "release",
  "release_digest": "$release_digest",
  "tooling_artifact_id": "tooling",
  "tooling_digest": "$tooling_digest",
  "architecture": "linux/amd64",
  "entitlement_decision_ref": "ent",
  "delivery_trace_id": "del",
  "iat": 0,
  "exp": 9999999999,
  "nonce": "n",
  "signer_key_id": "sok",
}))
PY
    helper_out="$(soviez_stage_helper_run_neutralize "$claims_file" "$controls_file" "$cert_out")"
    [[ -f "$cert_out" ]] || soviez_stage_die ORIGIN_CERTIFICATE_FAILED "Origin certificate not written"
    soviez_stage_inventory_update_field "$stage_id" "$(python3 - <<PY
import json
print(json.dumps({"origin_certificate_path": "$cert_out", "lifecycle_status": "neutralized"}))
PY
)"
    soviez_stage_op_transition "$op_id" neutralization_validated
    soviez_stage_checkpoint "$op_id" neutralization_validated
  fi
  state="$(soviez_stage_op_read_state "$op_id")"

  if soviez_stage_sm_should_run "$state" authorization_consumed; then
    ticket_token="$(cat "$(soviez_stage_op_dir "$op_id")/auth/ticket.token" 2>/dev/null || true)"
    authorization_id="$(soviez_json_get "$(cat "$(soviez_stage_op_state_file "$op_id")")" authorization_id)"
    if [[ "${SOVIEZ_STAGE_OFFLINE:-0}" == "1" || "${SOVIEZ_STAGE_BLOCK_SAAS:-0}" == "1" ]]; then
      # Local ledger already consumed at verify; no SaaS consume on offline target.
      :
    elif [[ -n "$ticket_token" && -n "$authorization_id" ]]; then
      soviez_stage_operations_consume "$authorization_id" "$ticket_token" >/dev/null || true
    fi
    soviez_stage_op_transition "$op_id" authorization_consumed
    soviez_stage_checkpoint "$op_id" authorization_consumed
  fi
  state="$(soviez_stage_op_read_state "$op_id")"

  if soviez_stage_sm_should_run "$state" domain_pending; then
    soviez_stage_op_transition "$op_id" domain_pending
    soviez_stage_checkpoint "$op_id" domain_pending
    soviez_stage_domain_validate_dns "$stage_domain" >/dev/null
    soviez_stage_op_transition "$op_id" ssl_pending
    soviez_stage_checkpoint "$op_id" ssl_pending
    soviez_stage_ssl_issue_and_validate "$stage_id" "$stage_domain" >/dev/null
  fi
  state="$(soviez_stage_op_read_state "$op_id")"

  if soviez_stage_sm_should_run "$state" runtime_validating; then
    soviez_stage_op_transition "$op_id" runtime_validating
    # Validate isolation markers
    local identity container network
    identity="$(soviez_stage_inventory_find "$stage_id")"
    container="$(soviez_json_get "$identity" stage_container)"
    network="$(soviez_json_get "$identity" stage_network)"
    [[ -n "$container" && -n "$network" ]] || soviez_stage_die STAGE_RUNTIME_FAILED "Missing isolation identity"
    if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
      [[ -f "$SOVIEZ_ROOT/stubs/stage-runtime-${stage_id}.started" ]] || soviez_stage_die STAGE_RUNTIME_FAILED "Runtime stub missing"
      [[ -f "$SOVIEZ_ROOT/stubs/networks/${network}.created" ]] || soviez_stage_die STAGE_RUNTIME_FAILED "Network stub missing"
    fi
    [[ -f "$(soviez_stage_origin_cert_file "$stage_id")" ]] || soviez_stage_die ORIGIN_CERTIFICATE_FAILED "Missing origin cert"
    soviez_stage_op_transition "$op_id" origin_certificate_issued
    soviez_stage_checkpoint "$op_id" origin_certificate_issued
  fi
  state="$(soviez_stage_op_read_state "$op_id")"

  if soviez_stage_sm_should_run "$state" remote_completion_pending; then
    soviez_stage_op_transition "$op_id" remote_completion_pending
    soviez_stage_checkpoint "$op_id" remote_completion_pending
    local controls
    controls="$(soviez_stage_neutralize_controls_json "$stage_id")"
    ticket_token="$(cat "$(soviez_stage_op_dir "$op_id")/auth/ticket.token" 2>/dev/null || true)"
    authorization_id="$(soviez_json_get "$(cat "$(soviez_stage_op_state_file "$op_id")")" authorization_id)"
    if [[ "${SOVIEZ_STAGE_OFFLINE:-0}" == "1" || "${SOVIEZ_STAGE_BLOCK_SAAS:-0}" == "1" ]]; then
      soviez_log_info "Offline complete — local certification only (no SaaS)"
    elif [[ -n "$ticket_token" && -n "$authorization_id" ]]; then
      if ! soviez_stage_operations_complete "$authorization_id" "$ticket_token" "$controls" >/dev/null 2>&1; then
        soviez_log_warn "Remote completion pending — Stage remains usable locally"
        # Leave recoverably pending but still mark certified locally.
      fi
    fi
    soviez_stage_inventory_update_field "$stage_id" '{"lifecycle_status":"certified","health_state":"healthy"}'
    # Phase 13 — immutable retention clock from original created_at (14d default / 60d max)
    if declare -F soviez_retention_init_for_stage >/dev/null; then
      soviez_retention_init_for_stage "$stage_id"
      soviez_retention_render_banner "$stage_id" >/dev/null || true
    fi
    soviez_stage_runtime_start "$stage_id"
    soviez_stage_op_transition "$op_id" completed
  fi

  echo "Stage created: https://${stage_domain}"
  echo "Stage ID: $stage_id"
  echo "Reattach: soviez.sh --stage-reattach $op_id"
  echo "Lifecycle: --stage-list | --stage-status $stage_id | --stage-stop $stage_id | --stage-start $stage_id"
  echo "Retention: --stage-retention-status $stage_id | --stage-retention-extend $stage_id --days <total>"
}

# --- end commands/stage.sh ---

# --- begin commands/stage_offline.sh ---
# shellcheck shell=bash
# Offline Stage authorization request export + package import (Phase 11 / 10.5).

soviez_cmd_stage_offline_request() {
  soviez_stage_paths_init
  local prod_json
  prod_json="$(soviez_stage_select_production)"
  soviez_stage_validate_production "$prod_json"
  local stage_id="${SOVIEZ_CLI_STAGE_ID:-}"
  local stage_domain="${SOVIEZ_CLI_STAGE_DOMAIN:-${SOVIEZ_CLI_DOMAIN:-}}"
  [[ -n "$stage_id" ]] || soviez_stage_die STAGE_ID_CONFLICT "Pass --stage-id"
  [[ -n "$stage_domain" ]] || soviez_stage_die STAGE_DOMAIN_CONFLICT "Pass --stage-domain"
  stage_id="$(soviez_stage_sanitize_id "$stage_id")" || soviez_stage_die STAGE_ID_CONFLICT "Invalid stage id"
  stage_domain="$(soviez_stage_normalize_domain "$stage_domain")" || soviez_stage_die STAGE_DOMAIN_CONFLICT "Invalid domain"

  local out="${SOVIEZ_CLI_OFFLINE_OUT:-$SOVIEZ_ROOT/offline-stage-request-${stage_id}.json}"
  [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]] || out="${SOVIEZ_CLI_OFFLINE_OUT:-./offline-stage-request-${stage_id}.json}"

  local nonce
  nonce="$(openssl rand -hex 16 2>/dev/null || python3 -c 'import secrets; print(secrets.token_hex(16))')"

  python3 - <<PY > "$out"
import json, time, os
print(json.dumps({
  "typ": "soviez.stage-offline-request.v1",
  "protocol_version": "stage-operation/v1",
  "request_id": "req_${stage_id}_" + str(int(time.time())),
  "request_nonce": "$nonce",
  "request_timestamp": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
  "license_id": "$(soviez_json_get "$prod_json" license_id)",
  "host_pubkey_fingerprint": "${SOVIEZ_HOST_PUBKEY_FINGERPRINT:-}",
  "production_fingerprint": "$(soviez_json_get "$prod_json" production_fingerprint)",
  "database_uuid": "$(soviez_json_get "$prod_json" database_uuid)",
  "stage_id": "$stage_id",
  "stage_domain": "$stage_domain",
  "operation_type": "stage_create",
  "release_digest": "${SOVIEZ_CLI_RELEASE_DIGEST:-sha256:bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb}",
  "tooling_digest": "${SOVIEZ_CLI_TOOLING_DIGEST:-sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa}",
  "architecture": "${SOVIEZ_CLI_ARCHITECTURE:-linux/amd64}",
  "created_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
}, indent=2))
PY
  chmod 600 "$out"
  echo "Offline Stage request written: $out"
  echo "Transfer to a connected device, obtain the signed package + tooling, then import on this host."
}

soviez_stage_offline_verify_package_bindings() {
  # Args: package_json_file expected bindings via env / production facts
  local pkg_file="$1"
  python3 - <<'PY'
import json, os, sys, time
from datetime import datetime, timezone

pkg = json.load(open(os.environ["SOVIEZ_PKG"]))
if pkg.get("typ") != "soviez.stage-offline-auth.v1":
    print("OFFLINE_PACKAGE_INVALID: bad typ", file=sys.stderr)
    sys.exit(20)

start_before = pkg.get("start_before") or pkg.get("expires_at")
if start_before:
    try:
        exp = datetime.fromisoformat(start_before.replace("Z", "+00:00"))
        if datetime.now(timezone.utc) > exp:
            print("TICKET_EXPIRED: package start_before passed", file=sys.stderr)
            sys.exit(20)
    except Exception as e:
        print(f"OFFLINE_PACKAGE_INVALID: bad start_before ({e})", file=sys.stderr)
        sys.exit(20)

b = pkg.get("bindings") or {}
checks = [
    ("license_id", os.environ.get("SOVIEZ_EXPECT_LICENSE")),
    ("production_fingerprint", os.environ.get("SOVIEZ_EXPECT_FP")),
    ("database_uuid", os.environ.get("SOVIEZ_EXPECT_DBUUID")),
    ("stage_id", os.environ.get("SOVIEZ_EXPECT_STAGE")),
    ("stage_domain", os.environ.get("SOVIEZ_EXPECT_DOMAIN")),
    ("host_pubkey_fingerprint", os.environ.get("SOVIEZ_EXPECT_HOST")),
    ("architecture", os.environ.get("SOVIEZ_EXPECT_ARCH", "linux/amd64")),
    ("release_digest", os.environ.get("SOVIEZ_EXPECT_RELEASE")),
    ("tooling_digest", os.environ.get("SOVIEZ_EXPECT_TOOLING")),
]
for key, expect in checks:
    if expect is None or expect == "":
        continue
    got = b.get(key) or pkg.get(key)
    if got != expect:
        print(f"TICKET_BINDING_MISMATCH: {key}", file=sys.stderr)
        sys.exit(20)

tooling = pkg.get("tooling") or {}
td = tooling.get("digest") or b.get("tooling_digest")
if os.environ.get("SOVIEZ_EXPECT_TOOLING") and td != os.environ["SOVIEZ_EXPECT_TOOLING"]:
    print("TOOLING_DIGEST_MISMATCH", file=sys.stderr)
    sys.exit(20)

# Reject private key material if accidentally included
blob = json.dumps(pkg)
for bad in ("BEGIN PRIVATE KEY", "service_role", "activation_key", "DATABASE_PASSWORD"):
    if bad in blob:
        print("OFFLINE_PACKAGE_INVALID: secret-like material", file=sys.stderr)
        sys.exit(20)

print("ok")
PY
}

soviez_cmd_stage_offline_import() {
  soviez_stage_paths_init
  local pkg="${SOVIEZ_CLI_OFFLINE_PACKAGE:-}"
  [[ -n "$pkg" && -f "$pkg" ]] || soviez_stage_die OPERATION_AUTHORIZATION_FAILED "Pass --offline-import <package-path>"

  local pkg_dir
  pkg_dir="$(cd "$(dirname "$pkg")" && pwd)"
  local pkg_abs="$pkg_dir/$(basename "$pkg")"

  local prod_json
  prod_json="$(soviez_stage_select_production)"
  soviez_stage_validate_production "$prod_json"

  local stage_id stage_domain license_id fingerprint db_uuid
  stage_id="${SOVIEZ_CLI_STAGE_ID:-}"
  stage_domain="${SOVIEZ_CLI_STAGE_DOMAIN:-${SOVIEZ_CLI_DOMAIN:-}}"
  license_id="$(soviez_json_get "$prod_json" license_id)"
  fingerprint="$(soviez_json_get "$prod_json" production_fingerprint)"
  db_uuid="$(soviez_json_get "$prod_json" database_uuid)"

  # Prefer bindings from package when CLI omitted.
  if [[ -z "$stage_id" ]]; then
    stage_id="$(SOVIEZ_PKG="$pkg_abs" python3 -c 'import json,os; p=json.load(open(os.environ["SOVIEZ_PKG"])); print((p.get("bindings") or {}).get("stage_id") or p.get("stage_id") or "")')"
  fi
  if [[ -z "$stage_domain" ]]; then
    stage_domain="$(SOVIEZ_PKG="$pkg_abs" python3 -c 'import json,os; p=json.load(open(os.environ["SOVIEZ_PKG"])); print((p.get("bindings") or {}).get("stage_domain") or p.get("stage_domain") or "")')"
  fi
  [[ -n "$stage_id" ]] || soviez_stage_die STAGE_ID_CONFLICT "Stage id required for offline import"
  [[ -n "$stage_domain" ]] || soviez_stage_die STAGE_DOMAIN_CONFLICT "Stage domain required for offline import"
  stage_id="$(soviez_stage_sanitize_id "$stage_id")" || soviez_stage_die STAGE_ID_CONFLICT "Invalid stage id"
  stage_domain="$(soviez_stage_normalize_domain "$stage_domain")" || soviez_stage_die STAGE_DOMAIN_CONFLICT "Invalid domain"

  local release_digest tooling_digest
  release_digest="${SOVIEZ_CLI_RELEASE_DIGEST:-}"
  tooling_digest="${SOVIEZ_CLI_TOOLING_DIGEST:-}"
  if [[ -z "$release_digest" ]]; then
    release_digest="$(SOVIEZ_PKG="$pkg_abs" python3 -c 'import json,os; p=json.load(open(os.environ["SOVIEZ_PKG"])); print((p.get("bindings") or {}).get("release_digest") or (p.get("release") or {}).get("digest") or "")')"
  fi
  if [[ -z "$tooling_digest" ]]; then
    tooling_digest="$(SOVIEZ_PKG="$pkg_abs" python3 -c 'import json,os; p=json.load(open(os.environ["SOVIEZ_PKG"])); print((p.get("tooling") or {}).get("digest") or (p.get("bindings") or {}).get("tooling_digest") or "")')"
  fi

  export SOVIEZ_PKG="$pkg_abs"
  export SOVIEZ_EXPECT_LICENSE="$license_id"
  export SOVIEZ_EXPECT_FP="$fingerprint"
  export SOVIEZ_EXPECT_DBUUID="$db_uuid"
  export SOVIEZ_EXPECT_STAGE="$stage_id"
  export SOVIEZ_EXPECT_DOMAIN="$stage_domain"
  export SOVIEZ_EXPECT_HOST="${SOVIEZ_HOST_PUBKEY_FINGERPRINT:-}"
  export SOVIEZ_EXPECT_ARCH="${SOVIEZ_CLI_ARCHITECTURE:-linux/amd64}"
  export SOVIEZ_EXPECT_RELEASE="$release_digest"
  export SOVIEZ_EXPECT_TOOLING="$tooling_digest"
  soviez_stage_offline_verify_package_bindings "$pkg_abs" >/dev/null \
    || soviez_stage_die TICKET_BINDING_MISMATCH "Offline package binding verification failed"

  # Materialize ticket + keys into a staging auth dir bound to upcoming op.
  local op_id="${SOVIEZ_CLI_OP_ID:-}"
  if [[ -z "$op_id" ]]; then
    op_id="$(SOVIEZ_PKG="$pkg_abs" python3 -c 'import json,os; p=json.load(open(os.environ["SOVIEZ_PKG"])); print(p.get("operation_id") or (p.get("bindings") or {}).get("operation_id") or "")')"
  fi
  [[ -n "$op_id" ]] || op_id="$(soviez_op_generate_id)"
  export SOVIEZ_CLI_OP_ID="$op_id"
  soviez_stage_op_create "$op_id" >/dev/null

  local work tooling_src tooling_meta
  work="$(soviez_stage_op_dir "$op_id")/auth"
  mkdir -p "$work"
  chmod 700 "$work"

  SOVIEZ_PKG="$pkg_abs" SOVIEZ_WORK="$work" python3 - <<'PY'
import json, os
from pathlib import Path
pkg = json.load(open(os.environ["SOVIEZ_PKG"]))
work = Path(os.environ["SOVIEZ_WORK"])
token = pkg.get("ticket_token") or (pkg.get("ticket") or {}).get("token")
if not token:
    raise SystemExit("missing ticket_token")
(work / "ticket.token").write_text(token)
(work / "ticket.token").chmod(0o600)
keys = pkg.get("public_keys") or pkg.get("keys") or {}
(work / "keys.json").write_text(json.dumps(keys))
(work / "keys.json").chmod(0o600)
(work / "offline_package.json").write_text(json.dumps({
  "package_id": pkg.get("package_id"),
  "typ": pkg.get("typ"),
  "signer_key_id": pkg.get("signer_key_id"),
  "start_before": pkg.get("start_before"),
  # Never copy private material
}, indent=2))
(work / "offline_package.json").chmod(0o600)
PY

  # Digest-pinned tooling bundle (local path relative to package).
  tooling_src="$(SOVIEZ_PKG="$pkg_abs" python3 -c 'import json,os; p=json.load(open(os.environ["SOVIEZ_PKG"])); print((p.get("tooling") or {}).get("bundle_path") or "")')"
  if [[ -n "$tooling_src" ]]; then
    if [[ "$tooling_src" != /* ]]; then
      tooling_src="$pkg_dir/$tooling_src"
    fi
    [[ -e "$tooling_src" ]] || soviez_stage_die TOOLING_UNAVAILABLE "Offline tooling bundle missing: $tooling_src"
    mkdir -p "$SOVIEZ_STAGE_TOOLING_CACHE/$tooling_digest"
    if [[ -d "$tooling_src" ]]; then
      cp -a "$tooling_src"/. "$SOVIEZ_STAGE_TOOLING_CACHE/$tooling_digest/"
    else
      cp -a "$tooling_src" "$SOVIEZ_STAGE_TOOLING_CACHE/$tooling_digest/"
    fi
    # Verify digest of bundle content
    local got_sum
    got_sum="$( (cd "$SOVIEZ_STAGE_TOOLING_CACHE/$tooling_digest" && find . -type f | sort | xargs cat 2>/dev/null | openssl dgst -sha256 | awk '{print $NF}') )"
    local expect_hex="${tooling_digest#sha256:}"
    if [[ -n "$expect_hex" && "$got_sum" != "$expect_hex" && "${SOVIEZ_STAGE_OFFLINE_SKIP_TOOLING_HASH:-0}" != "1" ]]; then
      # Allow metadata digest pin when bundle carries ARTIFACT.digest file matching claim
      if [[ -f "$SOVIEZ_STAGE_TOOLING_CACHE/$tooling_digest/ARTIFACT.digest" ]]; then
        local file_d
        file_d="$(tr -d '[:space:]' < "$SOVIEZ_STAGE_TOOLING_CACHE/$tooling_digest/ARTIFACT.digest")"
        [[ "$file_d" == "$tooling_digest" || "$file_d" == "$expect_hex" ]] \
          || soviez_stage_die TOOLING_DIGEST_MISMATCH "Tooling digest mismatch"
      else
        soviez_stage_die TOOLING_DIGEST_MISMATCH "Tooling digest mismatch"
      fi
    fi
    printf 'digest=%s\noffline=1\n' "$tooling_digest" > "$SOVIEZ_STAGE_TOOLING_CACHE/$tooling_digest/ARTIFACT.ok"
  else
    mkdir -p "$SOVIEZ_STAGE_TOOLING_CACHE/$tooling_digest"
    printf 'digest=%s\noffline=1\n' "$tooling_digest" > "$SOVIEZ_STAGE_TOOLING_CACHE/$tooling_digest/ARTIFACT.ok"
    printf '%s' "$tooling_digest" > "$SOVIEZ_STAGE_TOOLING_CACHE/$tooling_digest/ARTIFACT.digest"
  fi

  local auth_id
  auth_id="$(SOVIEZ_PKG="$pkg_abs" python3 -c 'import json,os; p=json.load(open(os.environ["SOVIEZ_PKG"])); print(p.get("authorization_id") or p.get("package_id") or "offline-auth")')"
  soviez_stage_op_merge "$op_id" "$(python3 - <<PY
import json
print(json.dumps({
  "authorization_id": "$auth_id",
  "ticket_present": True,
  "offline": True,
  "offline_package_id": "$(SOVIEZ_PKG="$pkg_abs" python3 -c 'import json,os; print(json.load(open(os.environ["SOVIEZ_PKG"])).get("package_id",""))')",
}))
PY
)"

  export SOVIEZ_CLI_STAGE_ID="$stage_id"
  export SOVIEZ_CLI_STAGE_DOMAIN="$stage_domain"
  export SOVIEZ_CLI_RELEASE_DIGEST="$release_digest"
  export SOVIEZ_CLI_TOOLING_DIGEST="$tooling_digest"
  export SOVIEZ_STAGE_OFFLINE=1
  export SOVIEZ_STAGE_FIXTURE_SKIP_DEVICE=1
  export SOVIEZ_STAGE_FIXTURE_SKIP_REMOTE=1
  # Offline package is the entitlement gate — do not call SaaS.
  export SOVIEZ_STAGE_FIXTURE_ENTITLEMENT_JSON='{"allowed":true,"denial_code":null,"existing_stages_unaffected":true,"offline":true}'
  export SOVIEZ_STAGE_USE_LEDGER=1
  # Skip re-authorize; ticket already on disk.
  export SOVIEZ_STAGE_OFFLINE_TICKET_READY=1
  export SOVIEZ_STAGE_FIXTURE_PUBLIC_KEYS_JSON
  SOVIEZ_STAGE_FIXTURE_PUBLIC_KEYS_JSON="$(cat "$work/keys.json")"
  export SOVIEZ_STAGE_FIXTURE_TICKET_TOKEN
  SOVIEZ_STAGE_FIXTURE_TICKET_TOKEN="$(cat "$work/ticket.token")"

  # Pre-seed authorize state so create resumes past remote authorize when offline.
  # Still runs through identity/admission/snapshot/... via create_run.
  soviez_log_info "Offline package verified; starting isolated Stage create (no SaaS)"
  # Block outbound SaaS from target: unset API base if present.
  unset SOVIEZ_SAAS_BASE_URL SOVIEZ_API_BASE_URL || true
  export SOVIEZ_STAGE_BLOCK_SAAS=1

  soviez_cmd_stage_create_run
}

# --- end commands/stage_offline.sh ---

# --- begin commands/ssl.sh ---
# shellcheck shell=bash
# Phase 12 SSL CLI commands.

soviez_cmd_ssl_status() {
  local env_id="${1:-}"
  soviez_ssl_paths_init
  if [[ -z "$env_id" ]]; then
    local id
    local any=0
    for id in $(soviez_ssl_inventory_list_ids); do
      any=1
      soviez_ssl_monitor_apply "$id" >/dev/null || true
      soviez_ssl_format_status_line "$id"
    done
    (( any == 1 )) || printf 'No managed SSL environments\n'
    return 0
  fi
  soviez_ssl_monitor_apply "$env_id" >/dev/null || true
  soviez_ssl_format_status_line "$env_id"
}

soviez_cmd_ssl_renew() {
  local env_id="${1:-}"
  [[ -n "$env_id" ]] || soviez_ssl_die "$SOVIEZ_SSL_CODE_ENVIRONMENT_SELECTION_REQUIRED" "--ssl-renew requires environment id"
  soviez_ssl_renew_run "$env_id" 1
}

soviez_cmd_ssl_repair() {
  local env_id="${1:-}"
  [[ -n "$env_id" ]] || soviez_ssl_die "$SOVIEZ_SSL_CODE_ENVIRONMENT_SELECTION_REQUIRED" "--ssl-repair requires environment id"
  soviez_ssl_repair "$env_id"
}

soviez_cmd_ssl_reattach() {
  local op_id="${1:-}"
  [[ -n "$op_id" ]] || soviez_ssl_die "$SOVIEZ_SSL_CODE_RECOVERY_REQUIRED" "--ssl-reattach requires operation id"
  soviez_ssl_reattach "$op_id"
}

soviez_cmd_ssl_policy() {
  local env_id="${1:-}"
  local set_mode="${2:-}"
  [[ -n "$env_id" ]] || soviez_ssl_die "$SOVIEZ_SSL_CODE_ENVIRONMENT_SELECTION_REQUIRED" "--ssl-policy requires environment id"
  if [[ -n "$set_mode" ]]; then
    set_mode="$(soviez_ssl_policy_normalize_mode "$set_mode")"
    soviez_ssl_inventory_patch "$env_id" "$(MODE="$set_mode" python3 - <<'PY'
import json, os
print(json.dumps({"renewal_mode": os.environ["MODE"]}))
PY
)"
    printf 'renewal_mode set to %s (existing certificate remains valid)\n' "$set_mode"
  fi
  local rec
  rec="$(soviez_ssl_inventory_read "$env_id")"
  printf 'env=%s renewal_mode=%s lead_days=%s provider=%s cert_mode=%s private_ca=%s wildcard_scope=%s\n' \
    "$env_id" \
    "$(soviez_json_get "$rec" renewal_mode)" \
    "$(soviez_json_get "$rec" renewal_lead_days)" \
    "$(soviez_json_get "$rec" acme_provider)" \
    "$(soviez_json_get "$rec" certificate_mode)" \
    "$(soviez_json_get "$rec" private_ca_policy)" \
    "$(soviez_json_get "$rec" wildcard_scope)"
}

soviez_cmd_ssl_try_again() {
  local env_id="${1:-}"
  [[ -n "$env_id" ]] || soviez_ssl_die "$SOVIEZ_SSL_CODE_ENVIRONMENT_SELECTION_REQUIRED" "environment id required"
  soviez_ssl_try_again "$env_id"
}

soviez_cmd_ssl_abort() {
  local env_id="${1:-}"
  [[ -n "$env_id" ]] || soviez_ssl_die "$SOVIEZ_SSL_CODE_ENVIRONMENT_SELECTION_REQUIRED" "environment id required"
  soviez_ssl_abort_safely "$env_id"
}

# --- end commands/ssl.sh ---

# --- begin commands/stage_retention.sh ---
# shellcheck shell=bash
# Phase 13 — Stage retention CLI commands.

soviez_cmd_stage_retention_status() {
  soviez_retention_status "${1:-}"
}

soviez_cmd_stage_retention_extend() {
  local stage_id="$1"
  local days="$2"
  local yes_flag="${3:-}"
  soviez_retention_extend "$stage_id" "$days" "$yes_flag"
}

soviez_cmd_stage_retention_run() {
  local stage_id="$1"
  # Manual run still requires deadline due unless SOVIEZ_RETENTION_FORCE_DUE=1 (tests)
  if [[ "${SOVIEZ_RETENTION_FORCE_DUE:-0}" == "1" ]]; then
    if [[ "${SOVIEZ_RETENTION_RUN_CONFIRM:-}" != "$stage_id" ]]; then
      if [[ -t 0 ]]; then
        printf 'Type the Stage ID to confirm retention deletion: ' >&2
        local typed
        read -r typed
        [[ "$typed" == "$stage_id" ]] || soviez_retention_die DESTRUCTIVE_CONFIRMATION_REQUIRED "Confirmation mismatch"
      else
        soviez_retention_die DESTRUCTIVE_CONFIRMATION_REQUIRED "Set SOVIEZ_RETENTION_RUN_CONFIRM=$stage_id"
      fi
    fi
    soviez_retention_run_deletion "$stage_id" 1
  else
    if [[ "${SOVIEZ_RETENTION_RUN_CONFIRM:-}" != "$stage_id" && ! -t 0 ]]; then
      soviez_retention_die DESTRUCTIVE_CONFIRMATION_REQUIRED "Set SOVIEZ_RETENTION_RUN_CONFIRM=$stage_id for non-TTY manual run"
    fi
    if [[ "${SOVIEZ_RETENTION_RUN_CONFIRM:-}" != "$stage_id" && -t 0 ]]; then
      printf 'Type the Stage ID to confirm retention deletion: ' >&2
      local typed
      read -r typed
      [[ "$typed" == "$stage_id" ]] || soviez_retention_die DESTRUCTIVE_CONFIRMATION_REQUIRED "Confirmation mismatch"
    fi
    soviez_retention_run_deletion "$stage_id" 0
  fi
}

soviez_cmd_stage_retention_retry() {
  soviez_retention_retry "$1"
}

soviez_cmd_stage_retention_reattach() {
  local op_id="$1"
  [[ -n "$op_id" ]] || soviez_retention_die STAGE_NOT_FOUND "operation-id required"
  soviez_stage_paths_init
  # Find stage whose retention_operation_id matches
  local sid found=""
  while IFS= read -r sid; do
    [[ -z "$sid" ]] && continue
    [[ -f "$(soviez_retention_file "$sid")" ]] || continue
    local oid
    oid="$(soviez_json_get "$(soviez_retention_read "$sid")" retention_operation_id)"
    if [[ "$oid" == "$op_id" ]]; then
      found="$sid"
      break
    fi
  done < <(soviez_stage_inventory_list_ids)
  [[ -n "$found" ]] || soviez_retention_die STAGE_NOT_FOUND "No Stage with retention_operation_id=$op_id"
  echo "Reattaching retention operation $op_id for stage $found"
  soviez_retention_retry "$found"
}

soviez_cmd_stage_retention_scan() {
  soviez_retention_scheduler_scan
}

# --- end commands/stage_retention.sh ---

# --- begin commands/operations.sh ---
# shellcheck shell=bash

soviez_cmd_operations_list() { soviez_ops_paths_init; soviez_ops_registry_list "$@"; }
soviez_cmd_operation_status() {
  soviez_ops_paths_init
  # Status reads canonical directly — migrate-on-read is compatibility fallback only.
  if [[ ! -f "$(soviez_ops_canonical_state_path "$1")" ]]; then
    soviez_ops_registry_get "$1" >/dev/null 2>&1 || soviez_ops_migrate_one "$1" || true
  elif soviez_ops_sync_is_pending "$1" 2>/dev/null; then
    soviez_ops_sync_reconcile "$1" >/dev/null 2>&1 || true
  fi
  soviez_ops_print_status "$1"
}
soviez_cmd_operation_reattach() {
  local op_id="$1" record type
  soviez_ops_paths_init
  if [[ ! -f "$(soviez_ops_canonical_state_path "$op_id")" ]]; then
    soviez_ops_registry_get "$op_id" >/dev/null 2>&1 || soviez_ops_migrate_one "$op_id" || true
  elif soviez_ops_sync_is_pending "$op_id" 2>/dev/null; then
    soviez_ops_sync_reconcile "$op_id" >/dev/null 2>&1 || true
  fi
  soviez_ops_print_status "$op_id"
  record="$(cat "$(soviez_ops_canonical_state_path "$op_id")" 2>/dev/null || soviez_ops_registry_get "$op_id")"
  type="$(soviez_json_get "$record" operation_type)"
  soviez_ops_adapter_reattach "$op_id" "$type"
}
soviez_cmd_operation_cancel() { soviez_ops_paths_init; soviez_ops_cancel "$@"; }
soviez_cmd_operation_retry() { soviez_ops_paths_init; soviez_ops_retry "$@"; }
soviez_cmd_operation_recover() { soviez_ops_paths_init; soviez_ops_recover "$@"; }
soviez_cmd_operation_logs() { soviez_ops_paths_init; soviez_ops_log_tail "$@"; }
soviez_cmd_operation_reconcile() {
  soviez_ops_paths_init
  if [[ -n "${1:-}" ]]; then soviez_ops_reconcile_one "$1"; else soviez_ops_reconcile_all; fi
}

# --- end commands/operations.sh ---

# --- begin commands/update.sh ---
# shellcheck shell=bash

soviez_cmd_update_run() {
  local target="${SOVIEZ_CLI_UPDATE_TARGET:-}"
  local release="${SOVIEZ_CLI_UPDATE_RELEASE:-}"
  local offline="${SOVIEZ_CLI_UPDATE_OFFLINE_PACKAGE:-}"
  local confirm="${SOVIEZ_CLI_CONFIRM:-0}"
  [[ "${SOVIEZ_CLI_YES:-0}" == "1" ]] && confirm=1
  soviez_update_run "$target" "$release" "$offline" "$confirm"
}

soviez_cmd_update_status() {
  local op_id="${1:-${SOVIEZ_CLI_OP_ID:-}}"
  [[ -n "$op_id" ]] || soviez_update_die UPDATE_TARGET_REQUIRED "operation-id required"
  soviez_update_paths_init
  local sf
  sf="$(soviez_update_op_state_file "$op_id")"
  if [[ -f "$sf" ]]; then
    cat "$sf"
  elif declare -F soviez_ops_status >/dev/null 2>&1; then
    soviez_ops_status "$op_id"
  else
    soviez_update_die UPDATE_TARGET_INVALID "Unknown update operation: $op_id"
  fi
  soviez_update_safety_window_info "$op_id" 2>/dev/null || true
}

soviez_cmd_update_reattach() {
  local op_id="${1:-${SOVIEZ_CLI_OP_ID:-}}"
  [[ -n "$op_id" ]] || soviez_update_die UPDATE_TARGET_REQUIRED "operation-id required"
  soviez_update_paths_init
  local sf state checkpoint
  sf="$(soviez_update_op_state_file "$op_id")"
  [[ -f "$sf" ]] || soviez_update_die UPDATE_RECOVERY_REQUIRED "Cannot reattach: missing state"
  state="$(soviez_json_get "$(cat "$sf")" current_state)"
  checkpoint="$(soviez_json_get "$(cat "$sf")" checkpoint 2>/dev/null || true)"
  case "$state" in
    completed|canceled|failed_terminal) soviez_update_ok UPDATE_ALREADY_TERMINAL "Operation already terminal: $state"; return 0 ;;
    recovery_required) soviez_update_die UPDATE_RECOVERY_REQUIRED "Use --update-recover" ;;
  esac
  # Resume from waiting_for_switch or failed_retryable with confirm
  if [[ "$state" == "waiting_for_switch" || "$checkpoint" == "waiting_for_switch" ]]; then
    local prod digest confirm
    prod="$(cat "$(soviez_update_op_dir "$op_id")/production.json")"
    digest="$(cat "$(soviez_update_op_dir "$op_id")/target_digest.txt")"
    confirm="${SOVIEZ_CLI_CONFIRM:-1}"
    soviez_update_state_write "$op_id" switching switching "{}"
    soviez_update_switch "$op_id" "$prod" "$digest"
    soviez_update_state_write "$op_id" completed completed "{}"
    soviez_update_ok UPDATE_COMPLETED "Reattached switch completed"
    return 0
  fi
  soviez_update_ok UPDATE_REATTACHED "Reattached to $op_id state=$state"
}

soviez_cmd_update_cancel() {
  local op_id="${1:-${SOVIEZ_CLI_OP_ID:-}}"
  [[ -n "$op_id" ]] || soviez_update_die UPDATE_TARGET_REQUIRED "operation-id required"
  soviez_update_paths_init
  local sf checkpoint boundary
  sf="$(soviez_update_op_state_file "$op_id")"
  [[ -f "$sf" ]] || soviez_update_die UPDATE_TARGET_INVALID "Unknown operation"
  checkpoint="$(soviez_json_get "$(cat "$sf")" checkpoint 2>/dev/null || true)"
  boundary="$(soviez_update_cancel_boundary "$checkpoint")"
  case "$boundary" in
    irreversible) soviez_update_die UPDATE_CANCELLATION_NOT_SAFE "Cannot cancel during $checkpoint" ;;
    rollback)
      soviez_update_state_write "$op_id" rollback_running cancel_rollback "{}"
      soviez_update_rollback "$op_id" >/dev/null
      soviez_update_state_write "$op_id" canceled canceled "{}"
      ;;
    *)
      soviez_update_candidate_cleanup "$op_id" || true
      soviez_update_state_write "$op_id" canceled canceled "{}"
      ;;
  esac
  soviez_update_ok UPDATE_CANCELED "Canceled $op_id"
}

soviez_cmd_update_retry() {
  local op_id="${1:-${SOVIEZ_CLI_OP_ID:-}}"
  [[ -n "$op_id" ]] || soviez_update_die UPDATE_TARGET_REQUIRED "operation-id required"
  soviez_update_paths_init
  local sf state
  sf="$(soviez_update_op_state_file "$op_id")"
  [[ -f "$sf" ]] || soviez_update_die UPDATE_RECOVERY_REQUIRED "Missing state"
  state="$(soviez_json_get "$(cat "$sf")" current_state)"
  case "$state" in
    failed_retryable|retry_scheduled)
      local prod digest
      prod="$(cat "$(soviez_update_op_dir "$op_id")/production.json")"
      digest="$(cat "$(soviez_update_op_dir "$op_id")/target_digest.txt")"
      # Do not blindly rerun ambiguous migrations — only safe candidate upgrade retry
      soviez_update_state_write "$op_id" upgrading_candidate retry_upgrade "{}"
      soviez_update_upgrade_candidate "$op_id" "$digest"
      soviez_update_validate_candidate "$op_id" "$prod" "$digest"
      soviez_update_state_write "$op_id" waiting_for_switch waiting_for_switch "{}"
      soviez_update_ok UPDATE_RETRY_OK "Retry advanced to waiting_for_switch"
      ;;
    *) soviez_update_die UPDATE_RECOVERY_REQUIRED "State $state is not safely retryable" ;;
  esac
}

soviez_cmd_update_recover() {
  local op_id="${1:-${SOVIEZ_CLI_OP_ID:-}}"
  [[ -n "$op_id" ]] || soviez_update_die UPDATE_TARGET_REQUIRED "operation-id required"
  soviez_update_paths_init
  local sf
  sf="$(soviez_update_op_state_file "$op_id")"
  if [[ ! -f "$sf" ]]; then
    soviez_update_die UPDATE_RECOVERY_REQUIRED "Ambiguous missing state"
  fi
  if declare -F soviez_ops_sync_is_pending >/dev/null 2>&1; then
    if soviez_ops_sync_is_pending "$op_id" 2>/dev/null; then
      soviez_ops_sync_reconcile "$op_id" 2>/dev/null || true
    fi
  fi
  local state
  state="$(soviez_json_get "$(cat "$sf")" current_state)"
  case "$state" in
    switching|rollback_running)
      soviez_update_state_write "$op_id" recovery_required recovery_required "{}"
      soviez_update_die UPDATE_RECOVERY_REQUIRED "Manual recovery required for ambiguous $state"
      ;;
    *)
      soviez_update_ok UPDATE_RECOVERED "Recovered view of $op_id ($state)"
      ;;
  esac
}

soviez_cmd_update_rollback() {
  local op_id="${1:-${SOVIEZ_CLI_OP_ID:-}}"
  [[ -n "$op_id" ]] || soviez_update_die UPDATE_TARGET_REQUIRED "operation-id required"
  soviez_update_paths_init
  soviez_update_state_write "$op_id" rollback_running operator_rollback "{}"
  soviez_update_rollback "$op_id"
  soviez_update_state_write "$op_id" completed rolled_back "{}"
}

soviez_cmd_update_cleanup() {
  local op_id="${1:-${SOVIEZ_CLI_OP_ID:-}}"
  [[ -n "$op_id" ]] || soviez_update_die UPDATE_TARGET_REQUIRED "operation-id required"
  soviez_update_paths_init
  local confirm="${SOVIEZ_CLI_CONFIRM:-0}"
  [[ "$confirm" == "1" ]] || soviez_update_die DESTRUCTIVE_CONFIRMATION_REQUIRED "Cleanup requires --confirm"
  local safety expires
  safety="$(soviez_update_safety_window_info "$op_id")"
  # Always allow cleanup of candidate; refuse deleting sole rollback set without confirm already given
  soviez_update_candidate_cleanup "$op_id"
  soviez_update_ok UPDATE_CLEANUP_OK "Candidate cleaned for $op_id (rollback set retained until safety window)"
}

soviez_cmd_update_image_status() {
  local production_id="${SOVIEZ_CLI_UPDATE_TARGET:-}"
  soviez_update_paths_init
  soviez_image_cleanup_paths_init
  soviez_image_status "$production_id"
}

soviez_cmd_update_image_cleanup() {
  local production_id="${SOVIEZ_CLI_UPDATE_TARGET:-}"
  local dry="${SOVIEZ_CLI_DRY_RUN:-0}"
  local confirm="${SOVIEZ_CLI_CONFIRM:-0}"
  local retry_op="${SOVIEZ_CLI_OP_ID:-}"
  soviez_update_paths_init
  soviez_image_cleanup_paths_init
  if [[ -n "$retry_op" && "${SOVIEZ_CLI_COMMAND:-}" == "update-image-cleanup-retry" ]]; then
    export SOVIEZ_IMAGE_CLEANUP_FORCE_WINDOW_ELAPSED=1
    soviez_image_cleanup_scheduler_tick
    return 0
  fi
  soviez_image_cleanup_execute "$production_id" "$confirm" "" "$dry"
}

# --- end commands/update.sh ---

# --- begin commands/offline_bundle.sh ---
# shellcheck shell=bash

soviez_cmd_offline_bundle_inspect() {
  local path="${SOVIEZ_CLI_OFFLINE_BUNDLE_PATH:-}"
  [[ -n "$path" ]] || soviez_offline_die OFFLINE_BUNDLE_REQUIRED "bundle path required"
  [[ -f "$path" ]] || soviez_offline_die OFFLINE_BUNDLE_NOT_FOUND "$path"
  soviez_offline_bundle_inspect "$path"
}

soviez_cmd_offline_bundle_import() {
  local path="${SOVIEZ_CLI_OFFLINE_BUNDLE_PATH:-}"
  local license_id="${SOVIEZ_LICENSE_ID:-${SOVIEZ_CLI_LICENSE_ID:-}}"
  local env_id="${SOVIEZ_ENVIRONMENT_ID:-${SOVIEZ_CLI_ENVIRONMENT_ID:-}}"
  local device_fp="${SOVIEZ_DEVICE_FINGERPRINT:-${SOVIEZ_CLI_DEVICE_FINGERPRINT:-}}"
  [[ -n "$path" && -n "$license_id" && -n "$env_id" && -n "$device_fp" ]] \
    || soviez_offline_die OFFLINE_BUNDLE_REQUIRED "bundle + license + environment + device required"
  soviez_offline_bundle_import "$path" "$license_id" "$env_id" "$device_fp" "${SOVIEZ_CURRENT_ERP_DIGEST:-}"
}

soviez_cmd_offline_bundle_plan() {
  local path="${SOVIEZ_CLI_OFFLINE_BUNDLE_PATH:-}"
  [[ -n "$path" ]] || soviez_offline_die OFFLINE_BUNDLE_REQUIRED "bundle path or id required"
  export SOVIEZ_LICENSE_ID="${SOVIEZ_LICENSE_ID:-${SOVIEZ_CLI_LICENSE_ID:?}}"
  export SOVIEZ_ENVIRONMENT_ID="${SOVIEZ_ENVIRONMENT_ID:-${SOVIEZ_CLI_ENVIRONMENT_ID:?}}"
  export SOVIEZ_DEVICE_FINGERPRINT="${SOVIEZ_DEVICE_FINGERPRINT:-${SOVIEZ_CLI_DEVICE_FINGERPRINT:?}}"
  soviez_offline_update_plan "$path"
}

soviez_cmd_offline_update_apply() {
  local path="${SOVIEZ_CLI_OFFLINE_BUNDLE_PATH:-}"
  [[ -n "$path" ]] || soviez_offline_die OFFLINE_BUNDLE_REQUIRED "bundle path or id required"
  export SOVIEZ_LICENSE_ID="${SOVIEZ_LICENSE_ID:-${SOVIEZ_CLI_LICENSE_ID:?}}"
  export SOVIEZ_ENVIRONMENT_ID="${SOVIEZ_ENVIRONMENT_ID:-${SOVIEZ_CLI_ENVIRONMENT_ID:?}}"
  export SOVIEZ_DEVICE_FINGERPRINT="${SOVIEZ_DEVICE_FINGERPRINT:-${SOVIEZ_CLI_DEVICE_FINGERPRINT:?}}"
  if [[ -n "${SOVIEZ_CLI_CONFIRM_TEXT:-}" ]]; then
    export SOVIEZ_OFFLINE_APPLY_CONFIRM="$SOVIEZ_CLI_CONFIRM_TEXT"
  fi
  [[ "${SOVIEZ_CLI_YES:-0}" == "1" ]] && export SOVIEZ_OFFLINE_APPLY_YES=1
  soviez_offline_update_apply "$path"
}

soviez_cmd_offline_update_status() {
  soviez_offline_update_status "${SOVIEZ_CLI_OP_ID:?}"
}

soviez_cmd_offline_update_result_export() {
  soviez_offline_update_result_export "${SOVIEZ_CLI_OP_ID:?}" "${SOVIEZ_CLI_RESULT_OUT:-}"
}

soviez_cmd_offline_update_result_show() {
  soviez_offline_update_result_show "${SOVIEZ_CLI_OFFLINE_RECEIPT_PATH:?}"
}

soviez_cmd_offline_trust_inspect() {
  local path="${SOVIEZ_CLI_OFFLINE_TRUST_PATH:?}"
  [[ -f "$path" ]] || soviez_offline_die OFFLINE_BUNDLE_NOT_FOUND "$path"
  if [[ -f "${path}.sig" ]] || grep -q signature_b64url "$path" 2>/dev/null; then
    soviez_offline_trust_verify_json_file trust_root "$path" || \
      soviez_offline_die OFFLINE_BUNDLE_SIGNATURE_INVALID "trust package"
  fi
  cat "$path"
}

soviez_cmd_offline_trust_import() {
  local path="${SOVIEZ_CLI_OFFLINE_TRUST_PATH:?}"
  soviez_offline_trust_paths_init
  soviez_offline_trust_verify_json_file trust_root "$path" || \
    soviez_offline_die OFFLINE_BUNDLE_SIGNATURE_INVALID "trust package"
  local seq local_seq
  seq="$(soviez_json_get "$(cat "$path")" sequence 2>/dev/null || echo 0)"
  soviez_offline_trust_state_init
  local_seq="$(soviez_json_get "$(cat "$SOVIEZ_OFFLINE_TRUST_STATE")" sequence 2>/dev/null || echo 0)"
  if [[ "${seq:-0}" -lt "${local_seq:-0}" ]]; then
    soviez_offline_die OFFLINE_BUNDLE_TRUST_STATE_ROLLBACK "Trust sequence rollback denied"
  fi
  cp -p "$path" "$SOVIEZ_OFFLINE_TRUST_DIR/imported_roots.json"
  SOVIEZ_S="$SOVIEZ_OFFLINE_TRUST_STATE" SOVIEZ_SEQ="$seq" python3 - <<'PY'
import json,os
p=os.environ["SOVIEZ_S"]
d=json.load(open(p))
d["sequence"]=int(os.environ["SOVIEZ_SEQ"])
open(p,"w").write(json.dumps(d,separators=(",",":")))
PY
  soviez_offline_trust_record_time
  echo "TRUST PACKAGE — IMPORTED sequence=$seq"
}

soviez_cmd_offline_phase24_readiness() {
  soviez_offline_phase24_readiness
}

