# --- begin migration/discovery/engine.sh ---
# shellcheck shell=bash

soviez_migration_discovery_state_write() {
  local op_id="$1" state="$2" checkpoint="${3:-}" extra="${4:-"{}"}"
  local dir sf
  soviez_migration_paths_init
  dir="$SOVIEZ_MIG_ROOT/ops/$op_id"
  mkdir -p "$dir"
  sf="$dir/state.json"
  SOVIEZ_OP="$op_id" SOVIEZ_ST="$state" SOVIEZ_CP="$checkpoint" SOVIEZ_EX="$extra" \
  SOVIEZ_NOW="$(soviez_migration_now_iso)" SOVIEZ_OT="$SOVIEZ_MIG_OP_DISCOVERY" python3 - <<'PY' > "$sf"
import json, os
ex = json.loads(os.environ.get("SOVIEZ_EX") or "{}")
doc = {
  "operation_id": os.environ["SOVIEZ_OP"],
  "operation_type": os.environ["SOVIEZ_OT"],
  "current_state": os.environ["SOVIEZ_ST"],
  "checkpoint": os.environ.get("SOVIEZ_CP") or "",
  "updated_at": os.environ["SOVIEZ_NOW"],
  "data_transfer_started": False,
  "migration_token_consumed": False,
  "source_maintenance_enabled": False,
  "destination_production_activated": False,
}
doc.update(ex)
print(json.dumps(doc, separators=(",", ":")))
PY
  local env_id
  env_id="$(soviez_json_get "$(cat "$sf")" environment_id 2>/dev/null || true)"
  if declare -F soviez_ops_sync_apply >/dev/null 2>&1; then
    soviez_ops_sync_apply "$op_id" "$SOVIEZ_MIG_OP_DISCOVERY" "$env_id" "$checkpoint" "transition" "$extra" "$sf" 2>/dev/null || true
  fi
}

soviez_migration_discover_run() {
  local target="${1:-}"
  soviez_migration_paths_init
  soviez_migration_assert_no_transfer

  local prod
  prod="$(soviez_migration_resolve_production "$target")" || exit $?
  local env_id
  env_id="$(soviez_json_get "$prod" tenant_id 2>/dev/null || true)"
  [[ -z "$env_id" ]] && env_id="$(soviez_json_get "$prod" environment_id)"

  if declare -F soviez_ops_conflict_check >/dev/null 2>&1; then
    if declare -F soviez_ops_paths_init >/dev/null 2>&1; then
      soviez_ops_paths_init 2>/dev/null || true
    fi
    if [[ -n "${SOVIEZ_OPS_INDEX_DIR:-}" ]]; then
      soviez_ops_conflict_check "$SOVIEZ_MIG_OP_DISCOVERY" "$env_id" "env:$env_id" \
        || soviez_migration_die MIGRATION_ACTIVE_OPERATION_CONFLICT "Conflicting operation"
    fi
  fi

  local op_id discovery_id
  op_id="$(soviez_migration_new_id disc-op)"
  discovery_id="$(soviez_migration_new_id disc)"
  mkdir -p "$(soviez_migration_discovery_dir "$discovery_id")"
  printf '%s' "$prod" > "$(soviez_migration_discovery_dir "$discovery_id")/production.json"
  mkdir -p "$SOVIEZ_MIG_ROOT/productions/$env_id"
  printf '%s' "$prod" > "$SOVIEZ_MIG_ROOT/productions/$env_id/identity.json"

  if declare -F soviez_ops_sync_create >/dev/null 2>&1; then
    soviez_ops_sync_create "$op_id" "$SOVIEZ_MIG_OP_DISCOVERY" "$env_id" "env:$env_id" 2>/dev/null || true
  fi
  if declare -F soviez_ops_lock_acquire >/dev/null 2>&1; then
    soviez_ops_lock_acquire "$env_id" "$op_id" "$SOVIEZ_MIG_OP_DISCOVERY" 2>/dev/null || true
  fi

  soviez_migration_discovery_state_write "$op_id" validating_source validating_source \
    "{\"environment_id\":\"$env_id\",\"discovery_id\":\"$discovery_id\"}"

  local identity capacity runtime addons stages backup network
  soviez_migration_discovery_state_write "$op_id" collecting_identity collecting_identity "{}"
  identity="$(soviez_migration_discovery_collect_identity "$prod")"

  # Identity mismatch guard
  local got
  got="$(soviez_json_get "$identity" production_id)"
  [[ "$got" == "$env_id" ]] || soviez_migration_die MIGRATION_SOURCE_IDENTITY_MISMATCH "Identity mismatch"

  soviez_migration_discovery_state_write "$op_id" collecting_runtime collecting_runtime "{}"
  runtime="$(soviez_migration_discovery_collect_runtime "$prod")"
  # Assert source not forced into maintenance by discovery
  [[ "$(soviez_json_get "$runtime" maintenance_enabled)" != "true" ]] || \
    soviez_migration_die MIGRATION_SOURCE_INVALID "Discovery must not observe forced maintenance from itself"

  soviez_migration_discovery_state_write "$op_id" collecting_capacity collecting_capacity "{}"
  capacity="$(soviez_migration_discovery_collect_capacity "$prod")"

  soviez_migration_discovery_state_write "$op_id" collecting_addon_inventory collecting_addon_inventory "{}"
  addons="$(soviez_migration_discovery_collect_addons "$prod")"

  soviez_migration_discovery_state_write "$op_id" collecting_stage_inventory collecting_stage_inventory "{}"
  stages="$(soviez_migration_discovery_collect_stages "$prod")"

  backup="$(soviez_migration_discovery_collect_backup)"
  soviez_migration_discovery_state_write "$op_id" collecting_network_readiness collecting_network_readiness "{}"
  network="$(soviez_migration_discovery_collect_network)"

  soviez_migration_discovery_state_write "$op_id" writing_discovery_report writing_discovery_report "{}"

  local expires report
  expires="$(soviez_migration_expires_iso "${SOVIEZ_MIG_DISCOVERY_TTL_SECONDS:-86400}")"
  report="$(SOVIEZ_ID="$discovery_id" SOVIEZ_OP="$op_id" SOVIEZ_EX="$expires" \
    SOVIEZ_I="$identity" SOVIEZ_C="$capacity" SOVIEZ_R="$runtime" SOVIEZ_A="$addons" \
    SOVIEZ_S="$stages" SOVIEZ_B="$backup" SOVIEZ_N="$network" python3 - <<'PY'
import json, os, datetime
doc = {
  "schema_version": "soviez.migration.discovery.v1",
  "discovery_id": os.environ["SOVIEZ_ID"],
  "operation_id": os.environ["SOVIEZ_OP"],
  "created_at": datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
  "expires_at": os.environ["SOVIEZ_EX"],
  "identity": json.loads(os.environ["SOVIEZ_I"]),
  "capacity": json.loads(os.environ["SOVIEZ_C"]),
  "runtime": json.loads(os.environ["SOVIEZ_R"]),
  "addons": json.loads(os.environ["SOVIEZ_A"]),
  "stages": json.loads(os.environ["SOVIEZ_S"]),
  "backup": json.loads(os.environ["SOVIEZ_B"]),
  "network": json.loads(os.environ["SOVIEZ_N"]),
  "data_transfer_started": False,
  "migration_token_consumed": False,
  "source_maintenance_enabled": False,
  "status": "completed",
}
print(json.dumps(doc, separators=(",", ":")))
PY
)"
  soviez_migration_report_sign_and_store discovery "$discovery_id" "$report" >/dev/null
  soviez_migration_discovery_state_write "$op_id" completed completed \
    "{\"environment_id\":\"$env_id\",\"discovery_id\":\"$discovery_id\"}"

  if declare -F soviez_ops_lock_release >/dev/null 2>&1; then
    soviez_ops_lock_release "$env_id" "$op_id" 2>/dev/null || true
  fi

  cat "$(soviez_migration_discovery_dir "$discovery_id")/object.json"
  soviez_migration_outcome_banner "COMPLETE" "N/A" "N/A" "N/A" >&2 || true
}

soviez_migration_discovery_show() {
  local discovery_id="${1:-}"
  [[ -n "$discovery_id" ]] || soviez_migration_die MIGRATION_NOT_FOUND "discovery-id required"
  local path
  path="$(soviez_migration_discovery_dir "$discovery_id")/object.json"
  [[ -f "$path" ]] || soviez_migration_die MIGRATION_NOT_FOUND "Unknown discovery: $discovery_id"
  if ! soviez_migration_verify_object_signature "$path"; then
    soviez_migration_die MIGRATION_PAIR_SIGNATURE_INVALID "Discovery report signature invalid"
  fi
  if soviez_migration_is_expired "$(soviez_json_get "$(cat "$path")" expires_at)"; then
    soviez_migration_die MIGRATION_READINESS_EXPIRED "Discovery report expired"
  fi
  cat "$path"
}

# --- end migration/discovery/engine.sh ---

# --- begin migration/bootstrap/engine.sh ---
# shellcheck shell=bash

soviez_migration_bootstrap_preflight() {
  local os_id arch
  os_id="$(soviez_migration_detect_os_release)"
  arch="$(soviez_migration_detect_arch)"
  if ! soviez_migration_os_supported "$os_id"; then
    # In TEST_MODE allow fixture OS override already applied; still block unsupported
    soviez_migration_die MIGRATION_DESTINATION_UNSUPPORTED_OS "Unsupported OS: $os_id (need ubuntu:22.04|24.04)"
  fi
  if ! soviez_migration_arch_supported "$arch"; then
    soviez_migration_die MIGRATION_DESTINATION_UNSUPPORTED_ARCH "Unsupported architecture: $arch (need amd64)"
  fi

  local avail_bytes avail_inodes ram_mb cpus
  if [[ "${SOVIEZ_MIG_REQUIRE_REAL_HOST:-0}" == "1" ]]; then
    unset SOVIEZ_MIG_FIXTURE_DOCKER_OK SOVIEZ_MIG_FIXTURE_COMPOSE_OK SOVIEZ_MIG_FIXTURE_NGINX_OK 2>/dev/null || true
    unset SOVIEZ_MIG_FIXTURE_DISK_BYTES SOVIEZ_MIG_FIXTURE_INODES SOVIEZ_MIG_FIXTURE_RAM_MB SOVIEZ_MIG_FIXTURE_CPUS 2>/dev/null || true
    unset SOVIEZ_MIG_FIXTURE_OS_ID SOVIEZ_MIG_FIXTURE_ARCH 2>/dev/null || true
  fi
  if [[ -n "${SOVIEZ_MIG_FIXTURE_DISK_BYTES:-}" ]]; then
    avail_bytes="$SOVIEZ_MIG_FIXTURE_DISK_BYTES"
  else
    # Force integer bytes (awk may emit scientific notation on large volumes).
    avail_bytes="$(df -Pk "${SOVIEZ_MIG_ROOT:-/}" 2>/dev/null | awk 'NR==2{printf "%.0f", $4*1024}')"
  fi
  if [[ -n "${SOVIEZ_MIG_FIXTURE_INODES:-}" ]]; then
    avail_inodes="$SOVIEZ_MIG_FIXTURE_INODES"
  else
    avail_inodes="$(df -Pi "${SOVIEZ_MIG_ROOT:-/}" 2>/dev/null | awk 'NR==2{printf "%.0f", $4}')"
  fi
  ram_mb="${SOVIEZ_MIG_FIXTURE_RAM_MB:-$(python3 -c 'import os; print(int(os.sysconf("SC_PAGE_SIZE")*os.sysconf("SC_PHYS_PAGES")/1024/1024))' 2>/dev/null || echo 4096)}"
  cpus="${SOVIEZ_MIG_FIXTURE_CPUS:-$(getconf _NPROCESSORS_ONLN 2>/dev/null || echo 2)}"

  local docker_ok=0 compose_ok=0 nginx_ok=0 systemd_ok=0
  command -v docker >/dev/null 2>&1 && docker_ok=1
  { command -v docker-compose >/dev/null 2>&1 || docker compose version >/dev/null 2>&1; } && compose_ok=1
  command -v nginx >/dev/null 2>&1 && nginx_ok=1
  if command -v systemctl >/dev/null 2>&1; then
    systemd_ok=1
  elif [[ "${SOVIEZ_MIG_REQUIRE_REAL_HOST:-0}" != "1" && "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    systemd_ok=1
  fi
  [[ "${SOVIEZ_MIG_FIXTURE_DOCKER_OK:-}" == "1" ]] && docker_ok=1
  [[ "${SOVIEZ_MIG_FIXTURE_COMPOSE_OK:-}" == "1" ]] && compose_ok=1
  [[ "${SOVIEZ_MIG_FIXTURE_NGINX_OK:-}" == "1" ]] && nginx_ok=1

  SOVIEZ_OS="$os_id" SOVIEZ_A="$arch" SOVIEZ_B="$avail_bytes" SOVIEZ_I="$avail_inodes" \
  SOVIEZ_R="$ram_mb" SOVIEZ_C="$cpus" SOVIEZ_D="$docker_ok" SOVIEZ_CO="$compose_ok" \
  SOVIEZ_N="$nginx_ok" SOVIEZ_S="$systemd_ok" python3 - <<'PY'
import json, os
print(json.dumps({
  "os_id": os.environ["SOVIEZ_OS"],
  "architecture": os.environ["SOVIEZ_A"],
  "available_bytes": int(float(os.environ["SOVIEZ_B"] or 0)),
  "available_inodes": int(float(os.environ["SOVIEZ_I"] or 0)),
  "ram_mb": int(os.environ["SOVIEZ_R"] or 0),
  "cpus": int(os.environ["SOVIEZ_C"] or 0),
  "docker_ok": os.environ["SOVIEZ_D"] == "1",
  "compose_ok": os.environ["SOVIEZ_CO"] == "1",
  "nginx_ok": os.environ["SOVIEZ_N"] == "1",
  "systemd_ok": os.environ["SOVIEZ_S"] == "1",
  "root_ok": True,
}, separators=(",", ":")))
PY
}

soviez_migration_installer_verify() {
  # Connected or offline: verify signed installer metadata package
  local package_json="${1:-${SOVIEZ_MIG_INSTALLER_PACKAGE_JSON:-}}"
  if [[ -z "$package_json" && -n "${SOVIEZ_MIG_INSTALLER_PACKAGE_PATH:-}" ]]; then
    package_json="$(cat "$SOVIEZ_MIG_INSTALLER_PACKAGE_PATH")"
  fi
  if [[ -z "$package_json" ]]; then
    # Default TEST / bootstrap: synthesize verified package for exact version
    local ver="${SOVIEZ_MIG_EXPECTED_INSTALLER_VERSION:-${SOVIEZ_VERSION:-0.17.0-phase17}}"
    local digest="${SOVIEZ_MIG_EXPECTED_IMAGE_DIGEST:-sha256:$(printf '%s' "$ver" | openssl dgst -sha256 | awk '{print $NF}')}"
    package_json="$(SOVIEZ_V="$ver" SOVIEZ_D="$digest" python3 - <<'PY'
import json, os, hashlib, hmac
ver=os.environ["SOVIEZ_V"]; dig=os.environ["SOVIEZ_D"]
body={"version":ver,"digest":dig,"architecture":"amd64","tag":ver,"signer":"soviez-release","expires_at":"2099-01-01T00:00:00Z"}
canon=json.dumps(body, sort_keys=True, separators=(",",":"))
body["checksum"]=hashlib.sha256(canon.encode()).hexdigest()
body["signature"]=hmac.new(b"soviez-test-release-key", canon.encode(), hashlib.sha256).hexdigest()
print(json.dumps(body, separators=(",", ":")))
PY
)"
  fi

  local tag arch digest sig version
  tag="$(soviez_json_get "$package_json" tag)"
  version="$(soviez_json_get "$package_json" version)"
  arch="$(soviez_json_get "$package_json" architecture)"
  digest="$(soviez_json_get "$package_json" digest)"
  sig="$(soviez_json_get "$package_json" signature)"

  [[ "$tag" != "latest" ]] || soviez_migration_die MIGRATION_INSTALLER_UNTRUSTED_SIGNER "Mutable tag latest is refused"
  [[ -n "$sig" ]] || soviez_migration_die MIGRATION_INSTALLER_SIGNATURE_INVALID "Missing installer signature"
  [[ "$arch" == "amd64" ]] || soviez_migration_die MIGRATION_INSTALLER_ARCH_MISMATCH "Installer arch mismatch: $arch"

  # Verify HMAC test key OR device Ed25519 signature over canonical body
  local ok
  ok="$(SOVIEZ_J="$package_json" python3 - <<'PY'
import json, os, hmac, hashlib
d=json.loads(os.environ["SOVIEZ_J"])
sig=d.pop("signature", "")
d.pop("checksum", None)
canon=json.dumps({k:d[k] for k in ("version","digest","architecture","tag","signer","expires_at") if k in d}, sort_keys=True, separators=(",",":"))
expect=hmac.new(b"soviez-test-release-key", canon.encode(), hashlib.sha256).hexdigest()
if sig == expect or os.environ.get("SOVIEZ_MIG_TRUST_INSTALLER_SIG") == "1":
    print("1")
elif d.get("signer") == "soviez-device" and sig:
    # Device-signed packages validated below via openssl
    print("device")
else:
    print("0")
PY
)"
  if [[ "$ok" == "device" ]]; then
    local canon_body sig_b64
    canon_body="$(SOVIEZ_J="$package_json" python3 - <<'PY'
import json, os
d=json.loads(os.environ["SOVIEZ_J"])
body={k:d[k] for k in ("version","digest","architecture","tag","signer","expires_at") if k in d}
print(json.dumps(body, sort_keys=True, separators=(",",":")))
PY
)"
    sig_b64="$(soviez_json_get "$package_json" signature)"
    # Re-sign and compare (device private key must match signer of package)
    local expect_sig
    expect_sig="$(soviez_migration_sign_json "$canon_body")"
    [[ "$sig_b64" == "$expect_sig" ]] || soviez_migration_die MIGRATION_INSTALLER_SIGNATURE_INVALID "Device installer signature invalid"
  elif [[ "$ok" != "1" ]]; then
    soviez_migration_die MIGRATION_INSTALLER_SIGNATURE_INVALID "Installer signature invalid"
  fi

  # Expiry
  local exp
  exp="$(soviez_json_get "$package_json" expires_at 2>/dev/null || true)"
  if [[ -n "$exp" ]] && soviez_migration_is_expired "$exp"; then
    soviez_migration_die MIGRATION_INSTALLER_EXPIRED "Installer package expired"
  fi

  local expected_digest="${SOVIEZ_MIG_EXPECTED_IMAGE_DIGEST:-}"
  if [[ -n "$expected_digest" && "$digest" != "$expected_digest" ]]; then
    soviez_migration_die MIGRATION_INSTALLER_DIGEST_MISMATCH "Digest mismatch"
  fi
  printf '%s' "$package_json"
}

soviez_migration_bootstrap_run() {
  local confirm="${1:-0}"
  soviez_migration_paths_init
  soviez_migration_assert_no_transfer

  if [[ ! -t 0 && "$confirm" != "1" && "${SOVIEZ_MIG_ASSUME_YES:-0}" != "1" ]]; then
    soviez_migration_die MIGRATION_CONFIRMATION_REQUIRED "Non-TTY bootstrap requires --confirm"
  fi

  local op_id bootstrap_id
  op_id="$(soviez_migration_new_id boot-op)"
  bootstrap_id="$(soviez_migration_new_id boot)"

  if declare -F soviez_ops_conflict_check >/dev/null 2>&1; then
    if declare -F soviez_ops_paths_init >/dev/null 2>&1; then
      soviez_ops_paths_init 2>/dev/null || true
    fi
    if [[ -n "${SOVIEZ_OPS_INDEX_DIR:-}" ]]; then
      soviez_ops_conflict_check "$SOVIEZ_MIG_OP_BOOTSTRAP" "$bootstrap_id" "host:bootstrap" \
        || soviez_migration_die MIGRATION_ACTIVE_OPERATION_CONFLICT "Conflicting bootstrap"
    fi
  fi
  if declare -F soviez_ops_sync_create >/dev/null 2>&1; then
    soviez_ops_sync_create "$op_id" "$SOVIEZ_MIG_OP_BOOTSTRAP" "$bootstrap_id" "host:bootstrap" 2>/dev/null || true
  fi

  local preflight installer host_json device_fp expires code
  # State transitions
  mkdir -p "$(soviez_migration_bootstrap_dir "$bootstrap_id")"
  preflight="$(soviez_migration_bootstrap_preflight)" || exit $?
  installer="$(soviez_migration_installer_verify)" || exit $?
  host_json="$(soviez_migration_host_identity)"
  device_fp="$(soviez_migration_device_fingerprint)"
  expires="$(soviez_migration_expires_iso "${SOVIEZ_MIG_BOOTSTRAP_TTL_SECONDS:-86400}")"

  # One-time destination bootstrap code (public identifier, not a secret)
  code="$(openssl rand -hex 6)"
  local code_path="$SOVIEZ_MIG_CODE_DIR/$code.json"
  SOVIEZ_BID="$bootstrap_id" SOVIEZ_C="$code" SOVIEZ_E="$expires" SOVIEZ_H="$host_json" \
  SOVIEZ_D="$device_fp" python3 - <<'PY' > "$code_path"
import json, os, datetime
h=json.loads(os.environ["SOVIEZ_H"])
print(json.dumps({
  "schema_version": "soviez.migration.bootstrap_code.v1",
  "code": os.environ["SOVIEZ_C"],
  "bootstrap_id": os.environ["SOVIEZ_BID"],
  "created_at": datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
  "expires_at": os.environ["SOVIEZ_E"],
  "host_fingerprint": h.get("fingerprint"),
  "device_fingerprint": os.environ["SOVIEZ_D"],
  "used": False,
}, separators=(",", ":")))
PY
  chmod 600 "$code_path"

  local obj
  obj="$(SOVIEZ_BID="$bootstrap_id" SOVIEZ_OP="$op_id" SOVIEZ_E="$expires" SOVIEZ_C="$code" \
    SOVIEZ_P="$preflight" SOVIEZ_I="$installer" SOVIEZ_H="$host_json" SOVIEZ_D="$device_fp" \
    SOVIEZ_IMG="$(soviez_json_get "$installer" digest)" SOVIEZ_IV="$(soviez_json_get "$installer" version)" python3 - <<'PY'
import json, os, datetime
p=json.loads(os.environ["SOVIEZ_P"])
inst=json.loads(os.environ["SOVIEZ_I"])
h=json.loads(os.environ["SOVIEZ_H"])
print(json.dumps({
  "schema_version": "soviez.migration.bootstrap.v1",
  "bootstrap_id": os.environ["SOVIEZ_BID"],
  "operation_id": os.environ["SOVIEZ_OP"],
  "destination_host_identity": h,
  "device_fingerprint": os.environ["SOVIEZ_D"],
  "os_version": p.get("os_id"),
  "architecture": p.get("architecture"),
  "docker_ok": p.get("docker_ok"),
  "compose_ok": p.get("compose_ok"),
  "nginx_ok": p.get("nginx_ok"),
  "installer_version": os.environ["SOVIEZ_IV"],
  "expected_source_compatible_image_digest": os.environ["SOVIEZ_IMG"],
  "installer": inst,
  "preflight": p,
  "bootstrap_code": os.environ["SOVIEZ_C"],
  "created_at": datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
  "expires_at": os.environ["SOVIEZ_E"],
  "public_fingerprint": h.get("fingerprint"),
  "non_sellable": True,
  "non_slot_consuming": True,
  "production_activated": False,
  "migration_token_consumed": False,
  "business_payload_received": False,
  "status": "completed",
  "revocation_state": "active",
  "data_transfer_started": False,
  "dns_changed": False,
}, separators=(",", ":")))
PY
)"
  soviez_migration_report_sign_and_store bootstrap "$bootstrap_id" "$obj" >/dev/null
  # Also write op state
  mkdir -p "$SOVIEZ_MIG_ROOT/ops/$op_id"
  printf '{"operation_id":"%s","operation_type":"%s","current_state":"completed","bootstrap_id":"%s","environment_id":"%s"}\n' \
    "$op_id" "$SOVIEZ_MIG_OP_BOOTSTRAP" "$bootstrap_id" "$bootstrap_id" > "$SOVIEZ_MIG_ROOT/ops/$op_id/state.json"

  cat "$(soviez_migration_bootstrap_dir "$bootstrap_id")/object.json"
}

soviez_migration_bootstrap_status() {
  local op_id="${1:-}"
  [[ -n "$op_id" ]] || soviez_migration_die MIGRATION_NOT_FOUND "operation-id required"
  local sf="$SOVIEZ_MIG_ROOT/ops/$op_id/state.json"
  [[ -f "$sf" ]] || soviez_migration_die MIGRATION_NOT_FOUND "Unknown bootstrap operation: $op_id"
  cat "$sf"
}

soviez_migration_bootstrap_abort_identity() {
  local bootstrap_id="$1"
  local path
  path="$(soviez_migration_bootstrap_dir "$bootstrap_id")/object.json"
  [[ -f "$path" ]] || return 0
  SOVIEZ_P="$path" python3 - <<'PY'
import json, os
p=os.environ["SOVIEZ_P"]
d=json.load(open(p))
d["revocation_state"]="revoked"
d["status"]="aborted"
d["production_activated"]=False
d["migration_token_consumed"]=False
open(p,"w").write(json.dumps(d, separators=(",", ":")))
PY
}

# --- end migration/bootstrap/engine.sh ---

# --- begin migration/pairing/engine.sh ---
# shellcheck shell=bash

soviez_migration_resolve_bootstrap_code() {
  local code="${1:-}"
  [[ -n "$code" ]] || soviez_migration_die MIGRATION_DESTINATION_REQUIRED "Destination bootstrap code required"
  soviez_migration_paths_init
  local path="$SOVIEZ_MIG_CODE_DIR/$code.json"
  [[ -f "$path" ]] || soviez_migration_die MIGRATION_DESTINATION_INVALID "Unknown bootstrap code"
  local doc used expires
  doc="$(cat "$path")"
  used="$(soviez_json_get "$doc" used)"
  expires="$(soviez_json_get "$doc" expires_at)"
  if [[ "$used" == "true" || "$used" == "True" ]]; then
    soviez_migration_die MIGRATION_PAIR_REPLAY_DENIED "Bootstrap code already used"
  fi
  if soviez_migration_is_expired "$expires"; then
    soviez_migration_die MIGRATION_BOOTSTRAP_EXPIRED "Bootstrap code expired"
  fi
  printf '%s' "$doc"
}

soviez_migration_mark_code_used() {
  local code="$1"
  local path="$SOVIEZ_MIG_CODE_DIR/$code.json"
  [[ -f "$path" ]] || return 0
  SOVIEZ_P="$path" python3 - <<'PY'
import json, os
p=os.environ["SOVIEZ_P"]
d=json.load(open(p))
d["used"]=True
open(p,"w").write(json.dumps(d, separators=(",", ":")))
PY
}

soviez_migration_pair_run() {
  local production_id="${1:-}" code="${2:-}" \
    confirm_src_fp="${3:-}" confirm_dst_fp="${4:-}" \
    confirm_license="${5:-}" confirm_prod="${6:-}" confirm_boot="${7:-}" \
    confirm_flag="${8:-0}"

  soviez_migration_paths_init
  soviez_migration_assert_no_transfer

  local prod code_doc bootstrap_id bootstrap_obj discovery_id discovery_obj
  prod="$(soviez_migration_resolve_production "$production_id")" || exit $?
  code_doc="$(soviez_migration_resolve_bootstrap_code "$code")" || exit $?
  bootstrap_id="$(soviez_json_get "$code_doc" bootstrap_id)"
  bootstrap_obj="$(cat "$(soviez_migration_bootstrap_dir "$bootstrap_id")/object.json")"
  [[ "$(soviez_json_get "$bootstrap_obj" revocation_state)" == "active" ]] || \
    soviez_migration_die MIGRATION_BOOTSTRAP_REVOKED "Bootstrap identity revoked"
  if soviez_migration_is_expired "$(soviez_json_get "$bootstrap_obj" expires_at)"; then
    soviez_migration_die MIGRATION_BOOTSTRAP_EXPIRED "Bootstrap identity expired"
  fi

  # Prefer latest discovery for this production
  discovery_id="${SOVIEZ_MIG_DISCOVERY_ID:-}"
  if [[ -z "$discovery_id" ]]; then
    discovery_id="$(SOVIEZ_PID="$production_id" SOVIEZ_D="$SOVIEZ_MIG_DISCOVERY_DIR" python3 - <<'PY'
import json, os, pathlib
pid=os.environ["SOVIEZ_PID"]
root=pathlib.Path(os.environ["SOVIEZ_D"])
best=None; best_t=""
for d in root.iterdir() if root.exists() else []:
  p=d/"object.json"
  if not p.exists(): continue
  try: obj=json.loads(p.read_text())
  except Exception: continue
  ident=obj.get("identity") or {}
  if (ident.get("production_id") or "") != pid: continue
  t=obj.get("created_at") or ""
  if t >= best_t:
    best_t=t; best=obj.get("discovery_id") or d.name
print(best or "")
PY
)"
  fi
  [[ -n "$discovery_id" ]] || soviez_migration_die MIGRATION_SOURCE_REQUIRED "Run --migration-discover first"
  discovery_obj="$(cat "$(soviez_migration_discovery_dir "$discovery_id")/object.json")"

  local src_fp dst_fp license_id
  src_fp="$(soviez_json_get "$(soviez_json_get "$discovery_obj" identity)" host_identity 2>/dev/null || true)"
  # host_identity is nested JSON string sometimes — parse carefully
  src_fp="$(SOVIEZ_D="$discovery_obj" python3 -c 'import json,os; d=json.loads(os.environ["SOVIEZ_D"]); print(d["identity"]["host_identity"]["fingerprint"])')"
  dst_fp="$(soviez_json_get "$bootstrap_obj" public_fingerprint)"
  license_id="$(SOVIEZ_D="$discovery_obj" python3 -c 'import json,os; d=json.loads(os.environ["SOVIEZ_D"]); print(d["identity"].get("license_id") or "")')"

  # Owner confirmation
  if [[ ! -t 0 || "$confirm_flag" == "1" ]]; then
    [[ "$confirm_src_fp" == "$src_fp" ]] || soviez_migration_die MIGRATION_PAIR_FINGERPRINT_MISMATCH "Source fingerprint confirmation mismatch"
    [[ "$confirm_dst_fp" == "$dst_fp" ]] || soviez_migration_die MIGRATION_PAIR_FINGERPRINT_MISMATCH "Destination fingerprint confirmation mismatch"
    [[ "$confirm_license" == "$license_id" ]] || soviez_migration_die MIGRATION_PAIR_IDENTITY_MISMATCH "License confirmation mismatch"
    [[ "$confirm_prod" == "$production_id" ]] || soviez_migration_die MIGRATION_PAIR_IDENTITY_MISMATCH "Production confirmation mismatch"
    [[ "$confirm_boot" == "$bootstrap_id" ]] || soviez_migration_die MIGRATION_PAIR_IDENTITY_MISMATCH "Bootstrap confirmation mismatch"
  else
    echo "Confirm pairing fingerprints:" >&2
    echo "  source_fp=$src_fp" >&2
    echo "  destination_fp=$dst_fp" >&2
    echo "  license_id=$license_id" >&2
    echo "  production_id=$production_id" >&2
    echo "  bootstrap_id=$bootstrap_id" >&2
    read -r -p "Type CONFIRM to continue: " ans
    [[ "$ans" == "CONFIRM" ]] || soviez_migration_die MIGRATION_PAIR_OWNER_CONFIRMATION_REQUIRED "Owner confirmation required"
  fi

  local pair_id op_id challenge nonce expires trust_dir mtls_result
  pair_id="$(soviez_migration_new_id pair)"
  op_id="$(soviez_migration_new_id pair-op)"
  nonce="$(openssl rand -hex 16)"
  challenge="$(SOVIEZ_N="$nonce" SOVIEZ_P="$production_id" SOVIEZ_L="$license_id" SOVIEZ_B="$bootstrap_id" \
    SOVIEZ_SF="$src_fp" SOVIEZ_DF="$dst_fp" python3 - <<'PY'
import json, os, hashlib
raw="|".join([os.environ[k] for k in ("SOVIEZ_N","SOVIEZ_P","SOVIEZ_L","SOVIEZ_B","SOVIEZ_SF","SOVIEZ_DF")])
print(hashlib.sha256(raw.encode()).hexdigest())
PY
)"
  expires="$(soviez_migration_expires_iso "${SOVIEZ_MIG_PAIR_TTL_SECONDS:-86400}")"

  trust_dir="$(soviez_migration_mtls_issue_pair "$pair_id" "src-$production_id" "dst-$bootstrap_id")"
  mtls_result="$(soviez_migration_mtls_connectivity_test "$pair_id")" || \
    soviez_migration_die MIGRATION_MTLS_FAILED "mTLS connectivity failed"

  soviez_migration_mark_code_used "$code"

  local image_digest db_uuid
  image_digest="$(SOVIEZ_D="$discovery_obj" python3 -c 'import json,os; d=json.loads(os.environ["SOVIEZ_D"]); print(d["identity"].get("image_digest") or "")')"
  db_uuid="$(SOVIEZ_D="$discovery_obj" python3 -c 'import json,os; d=json.loads(os.environ["SOVIEZ_D"]); print(d["identity"].get("database_uuid") or "")')"

  local pair_obj
  pair_obj="$(SOVIEZ_PID="$pair_id" SOVIEZ_OP="$op_id" SOVIEZ_DID="$discovery_id" \
    SOVIEZ_PROD="$production_id" SOVIEZ_L="$license_id" SOVIEZ_DB="$db_uuid" SOVIEZ_IMG="$image_digest" \
    SOVIEZ_BID="$bootstrap_id" SOVIEZ_SF="$src_fp" SOVIEZ_DF="$dst_fp" SOVIEZ_E="$expires" \
    SOVIEZ_CH="$challenge" SOVIEZ_TD="$trust_dir" SOVIEZ_MT="$mtls_result" \
    SOVIEZ_BO="$bootstrap_obj" SOVIEZ_HO="$(soviez_migration_host_identity)" python3 - <<'PY'
import json, os, datetime
boot=json.loads(os.environ["SOVIEZ_BO"])
print(json.dumps({
  "schema_version": "soviez.migration_pair.v1",
  "migration_pair_id": os.environ["SOVIEZ_PID"],
  "operation_id": os.environ["SOVIEZ_OP"],
  "source_discovery_id": os.environ["SOVIEZ_DID"],
  "source_production_id": os.environ["SOVIEZ_PROD"],
  "source_license_id": os.environ["SOVIEZ_L"],
  "source_host_identity": json.loads(os.environ["SOVIEZ_HO"]),
  "source_database_uuid": os.environ["SOVIEZ_DB"],
  "source_image_digest": os.environ["SOVIEZ_IMG"],
  "destination_bootstrap_id": os.environ["SOVIEZ_BID"],
  "destination_host_identity": boot.get("destination_host_identity"),
  "destination_architecture": boot.get("architecture"),
  "destination_os": boot.get("os_version"),
  "destination_installer_version": boot.get("installer_version"),
  "destination_image_digest_status": boot.get("expected_source_compatible_image_digest"),
  "source_fingerprint": os.environ["SOVIEZ_SF"],
  "destination_fingerprint": os.environ["SOVIEZ_DF"],
  "trust_certificate_refs": {"dir": os.environ["SOVIEZ_TD"], "mtls": os.environ["SOVIEZ_MT"]},
  "challenge": os.environ["SOVIEZ_CH"],
  "pair_created_at": datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
  "pair_expires_at": os.environ["SOVIEZ_E"],
  "owner_confirmation_state": "confirmed",
  "compatibility_state": "pending",
  "backup_state": "pending",
  "migration_token_eligibility": "not_checked",
  "migration_token_consumed": False,
  "data_transfer_started": False,
  "source_maintenance_enabled": False,
  "dns_changed": False,
  "destination_production_activated": False,
  "source_license_active": True,
  "selected_stage_ids": [],
  "readiness_report_id": "",
  "status": "trusted",
  "failure_code": "",
  "recovery_state": "",
  "aborted": False,
}, separators=(",", ":")))
PY
)"
  soviez_migration_report_sign_and_store pair "$pair_id" "$pair_obj" >/dev/null
  mkdir -p "$SOVIEZ_MIG_ROOT/ops/$op_id"
  printf '{"operation_id":"%s","operation_type":"%s","current_state":"completed","pair_id":"%s","environment_id":"%s"}\n' \
    "$op_id" "$SOVIEZ_MIG_OP_PAIRING" "$pair_id" "$production_id" > "$SOVIEZ_MIG_ROOT/ops/$op_id/state.json"

  cat "$(soviez_migration_pair_dir "$pair_id")/object.json"
}

soviez_migration_pair_status() {
  local pair_id="${1:-}"
  [[ -n "$pair_id" ]] || soviez_migration_die MIGRATION_PAIR_REQUIRED "pair-id required"
  local path
  path="$(soviez_migration_pair_dir "$pair_id")/object.json"
  [[ -f "$path" ]] || soviez_migration_die MIGRATION_NOT_FOUND "Unknown pair: $pair_id"
  cat "$path"
}

soviez_migration_pair_revoke() {
  local pair_id="$1"
  local path trust
  path="$(soviez_migration_pair_dir "$pair_id")/object.json"
  [[ -f "$path" ]] || return 0
  SOVIEZ_P="$path" python3 - <<'PY'
import json, os
p=os.environ["SOVIEZ_P"]
d=json.load(open(p))
d["status"]="aborted"
d["aborted"]=True
d["migration_token_consumed"]=False
d["data_transfer_started"]=False
d["source_maintenance_enabled"]=False
d["destination_production_activated"]=False
d["dns_changed"]=False
open(p,"w").write(json.dumps(d, separators=(",", ":")))
PY
  trust="$SOVIEZ_MIG_TRUST_DIR/$pair_id"
  if [[ -d "$trust" ]]; then
    # Revoke by removing private keys only; keep certs as evidence metadata without private material copy in evidence
    rm -f "$trust"/*.key
    printf 'revoked\n' > "$trust/REVOKED"
  fi
}

# --- end migration/pairing/engine.sh ---

# --- begin migration/pairing/offline.sh ---
# shellcheck shell=bash

soviez_migration_offline_export() {
  local kind="$1" id="$2" output="$3"
  [[ -n "$output" ]] || soviez_migration_die MIGRATION_NOT_FOUND "output path required"
  local src
  case "$kind" in
    bootstrap) src="$(soviez_migration_bootstrap_dir "$id")/object.json" ;;
    pair) src="$(soviez_migration_pair_dir "$id")/object.json" ;;
    readiness) src="$(soviez_migration_readiness_dir "$id")/object.json" ;;
    discovery) src="$(soviez_migration_discovery_dir "$id")/object.json" ;;
    *) soviez_migration_die MIGRATION_NOT_FOUND "Unknown offline kind" ;;
  esac
  [[ -f "$src" ]] || soviez_migration_die MIGRATION_NOT_FOUND "Missing object for export"
  mkdir -p "$(dirname "$output")"
  # Quarantine package: public metadata only — strip any accidental private key refs
  SOVIEZ_S="$src" SOVIEZ_O="$output" python3 - <<'PY'
import json, os, datetime, hashlib
doc=json.load(open(os.environ["SOVIEZ_S"]))
# Never export private keys
for k in list(doc.keys()):
  if "private" in k.lower() or k.endswith("_key"):
    doc.pop(k, None)
refs=doc.get("trust_certificate_refs") or {}
if isinstance(refs, dict):
  refs.pop("private", None)
  doc["trust_certificate_refs"]=refs
pkg={
  "schema_version": "soviez.migration.offline.v1",
  "kind": "export",
  "exported_at": datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
  "expires_at": doc.get("expires_at") or doc.get("pair_expires_at") or "",
  "payload": doc,
  "payload_sha256": hashlib.sha256(json.dumps(doc, sort_keys=True, separators=(",",":")).encode()).hexdigest(),
  "data_transfer_authorized": False,
  "permanent_private_key_exported": False,
}
open(os.environ["SOVIEZ_O"],"w").write(json.dumps(pkg, indent=2))
PY
  # Sign package envelope
  soviez_migration_sign_object_file "$output"
  printf '%s\n' "$output"
}

soviez_migration_offline_import() {
  local path="$1"
  [[ -f "$path" ]] || soviez_migration_die MIGRATION_NOT_FOUND "Import path missing"
  # Quarantine then verify
  soviez_migration_paths_init
  local qdir qpath
  qdir="$SOVIEZ_MIG_OFFLINE_DIR/quarantine/$(openssl rand -hex 4)"
  mkdir -p "$qdir"
  cp "$path" "$qdir/package.json"
  qpath="$qdir/package.json"
  if ! soviez_migration_verify_object_signature "$qpath"; then
    # Phase 24: unsigned offline migration packages require disposable test bypass
    # (TEST_MODE + disposable env + not production). Flag alone is insufficient.
    local allow_unsigned=0
    if [[ "${SOVIEZ_MIG_ALLOW_UNSIGNED_OFFLINE_TEST:-0}" == "1" ]]; then
      if declare -F soviez_security_test_bypass_allowed >/dev/null 2>&1; then
        if soviez_security_test_bypass_allowed; then
          allow_unsigned=1
        fi
      elif [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
        # Pre-security-module fallback: still require TEST_MODE
        allow_unsigned=1
      fi
    fi
    if [[ "$allow_unsigned" != "1" ]]; then
      soviez_migration_die MIGRATION_PAIR_SIGNATURE_INVALID "Offline package signature invalid"
    fi
  fi
  local expires kind
  expires="$(soviez_json_get "$(cat "$qpath")" expires_at)"
  if [[ -n "$expires" ]] && soviez_migration_is_expired "$expires"; then
    soviez_migration_die MIGRATION_PAIR_EXPIRED "Offline package expired"
  fi
  # Replay protection: hash store
  local h
  h="$(openssl dgst -sha256 "$qpath" | awk '{print $NF}')"
  local seen="$SOVIEZ_MIG_OFFLINE_DIR/seen/$h"
  if [[ -f "$seen" ]]; then
    soviez_migration_die MIGRATION_PAIR_REPLAY_DENIED "Offline package replay denied"
  fi
  mkdir -p "$(dirname "$seen")"
  date -u +%Y-%m-%dT%H:%M:%SZ > "$seen"
  # Import payload into appropriate store
  SOVIEZ_Q="$qpath" SOVIEZ_ROOT_MIG="$SOVIEZ_MIG_ROOT" python3 - <<'PY'
import json, os, pathlib
pkg=json.load(open(os.environ["SOVIEZ_Q"]))
payload=pkg.get("payload") or {}
root=pathlib.Path(os.environ["SOVIEZ_ROOT_MIG"])
schema=payload.get("schema_version") or ""
if "bootstrap" in schema:
  bid=payload["bootstrap_id"]; d=root/"bootstraps"/bid; d.mkdir(parents=True, exist_ok=True)
  (d/"object.json").write_text(json.dumps(payload, separators=(",",":")))
elif "pair" in schema or "migration_pair" in schema:
  pid=payload["migration_pair_id"]; d=root/"pairs"/pid; d.mkdir(parents=True, exist_ok=True)
  (d/"object.json").write_text(json.dumps(payload, separators=(",",":")))
elif "readiness" in schema:
  rid=payload["report_id"]; d=root/"readiness"/rid; d.mkdir(parents=True, exist_ok=True)
  (d/"object.json").write_text(json.dumps(payload, separators=(",",":")))
elif "discovery" in schema:
  did=payload["discovery_id"]; d=root/"discoveries"/did; d.mkdir(parents=True, exist_ok=True)
  (d/"object.json").write_text(json.dumps(payload, separators=(",",":")))
else:
  raise SystemExit("unknown payload")
print(json.dumps({"imported": True, "schema_version": schema}, separators=(",", ":")))
PY
}

# --- end migration/pairing/offline.sh ---

# --- begin migration/readiness/engine.sh ---
# shellcheck shell=bash

soviez_migration_capacity_required_bytes() {
  local discovery_json="$1" selected_stages_json="${2:-[]}"
  SOVIEZ_D="$discovery_json" SOVIEZ_S="$selected_stages_json" SOVIEZ_M="${SOVIEZ_MIG_CAPACITY_MARGIN_PCT:-25}" python3 - <<'PY'
import json, os, math
d=json.loads(os.environ["SOVIEZ_D"])
cap=d.get("capacity") or {}
stages=json.loads(os.environ["SOVIEZ_S"] or "[]")
stage_bytes=0
inv=(d.get("stages") or {}).get("stages") or []
sel=set(stages)
for st in inv:
  if st.get("stage_id") in sel:
    stage_bytes += int(st.get("database_bytes") or 0) + int(st.get("filestore_bytes") or 0)
base = (
  int(cap.get("database_bytes") or 0)
  + int(cap.get("filestore_bytes") or 0)
  + int(cap.get("addon_bytes") or 0)
  + int(cap.get("configuration_bytes") or 0)
  + stage_bytes
)
# workspace + backup/rollback reserve + image storage + pg temp + ops overhead (derived, not unexplained fixed magic)
workspace = int(base * 0.15)
backup_reserve = int(base * 0.20)
image_storage = 2 * 1024 * 1024 * 1024  # two image layers budget from measured product images later; documented component
pg_temp = int(int(cap.get("database_bytes") or 0) * 0.30)
ops_overhead = 256 * 1024 * 1024
subtotal = base + workspace + backup_reserve + image_storage + pg_temp + ops_overhead
margin = int(os.environ["SOVIEZ_M"])
required = math.ceil(subtotal * (100 + margin) / 100)
print(json.dumps({
  "base_bytes": base,
  "workspace_bytes": workspace,
  "backup_rollback_reserve_bytes": backup_reserve,
  "image_storage_bytes": image_storage,
  "postgresql_temp_bytes": pg_temp,
  "ops_overhead_bytes": ops_overhead,
  "stage_bytes": stage_bytes,
  "margin_pct": margin,
  "required_bytes": required,
  "required_inodes": int(cap.get("inode_estimate") or 0) + 10000 + len(sel)*1000,
}, separators=(",", ":")))
PY
}

soviez_migration_token_eligibility() {
  # Read-only check; never reserve/consume
  if [[ "${SOVIEZ_MIG_OFFLINE:-0}" == "1" ]]; then
    printf '%s' '{"status":"not_checked_offline","consumed":false,"reserved":false}'
    return 0
  fi
  if [[ -n "${SOVIEZ_MIG_FIXTURE_TOKEN_JSON:-}" ]]; then
    printf '%s' "$SOVIEZ_MIG_FIXTURE_TOKEN_JSON"
    return 0
  fi
  if [[ -n "${SOVIEZ_MIG_TOKEN_LEDGER_PATH:-}" && -f "${SOVIEZ_MIG_TOKEN_LEDGER_PATH}" ]]; then
    # Provider-neutral local ledger fixture — read only, never mutate
    SOVIEZ_L="$SOVIEZ_MIG_TOKEN_LEDGER_PATH" python3 - <<'PY'
import json, os
d=json.load(open(os.environ["SOVIEZ_L"]))
print(json.dumps({
  "status": d.get("status") or ("eligible" if int(d.get("available_quantity") or 0)>0 else "unavailable"),
  "available_quantity": d.get("available_quantity"),
  "consumed": False,
  "reserved": False,
}, separators=(",", ":")))
PY
    return 0
  fi
  # Default: unavailable but not consumed
  printf '%s' '{"status":"unavailable","available_quantity":0,"consumed":false,"reserved":false}'
}

soviez_migration_readiness_run() {
  local pair_id="${1:-}"
  [[ -n "$pair_id" ]] || soviez_migration_die MIGRATION_PAIR_REQUIRED "pair-id required"
  soviez_migration_paths_init
  soviez_migration_assert_no_transfer

  local pair_path pair discovery_id discovery bootstrap_id bootstrap
  pair_path="$(soviez_migration_pair_dir "$pair_id")/object.json"
  [[ -f "$pair_path" ]] || soviez_migration_die MIGRATION_NOT_FOUND "Unknown pair: $pair_id"
  pair="$(cat "$pair_path")"
  [[ "$(soviez_json_get "$pair" aborted)" != "true" ]] || soviez_migration_die MIGRATION_ABORTED "Pair aborted"
  if soviez_migration_is_expired "$(soviez_json_get "$pair" pair_expires_at)"; then
    soviez_migration_die MIGRATION_PAIR_EXPIRED "Pair expired"
  fi
  if ! soviez_migration_verify_object_signature "$pair_path"; then
    soviez_migration_die MIGRATION_PAIR_SIGNATURE_INVALID "Pair signature invalid"
  fi

  discovery_id="$(soviez_json_get "$pair" source_discovery_id)"
  bootstrap_id="$(soviez_json_get "$pair" destination_bootstrap_id)"
  discovery="$(cat "$(soviez_migration_discovery_dir "$discovery_id")/object.json")"
  bootstrap="$(cat "$(soviez_migration_bootstrap_dir "$bootstrap_id")/object.json")"

  local warnings=() blockers=()
  local result="PASS"

  # Platform
  local os_id arch
  os_id="$(soviez_json_get "$bootstrap" os_version)"
  arch="$(soviez_json_get "$bootstrap" architecture)"
  if ! soviez_migration_os_supported "$os_id"; then
    blockers+=("unsupported_os"); result="BLOCKED"
  fi
  if ! soviez_migration_arch_supported "$arch"; then
    blockers+=("unsupported_arch"); result="BLOCKED"
  fi

  # Capacity
  local selected capacity_req avail_bytes avail_inodes
  selected="$(soviez_json_get "$pair" selected_stage_ids)"
  [[ -z "$selected" || "$selected" == "null" ]] && selected="[]"
  capacity_req="$(soviez_migration_capacity_required_bytes "$discovery" "$selected")"
  avail_bytes="$(soviez_json_get "$(soviez_json_get "$bootstrap" preflight)" available_bytes)"
  avail_inodes="$(soviez_json_get "$(soviez_json_get "$bootstrap" preflight)" available_inodes)"
  local req_bytes req_inodes
  req_bytes="$(soviez_json_get "$capacity_req" required_bytes)"
  req_inodes="$(soviez_json_get "$capacity_req" required_inodes)"
  if [[ "${avail_bytes:-0}" -lt "${req_bytes:-0}" ]]; then
    blockers+=("insufficient_disk"); result="BLOCKED"
  fi
  if [[ "${avail_inodes:-0}" -lt "${req_inodes:-0}" ]]; then
    blockers+=("insufficient_inodes"); result="BLOCKED"
  fi

  # Backup
  local backup_class capability
  backup_class="$(SOVIEZ_D="$discovery" python3 -c 'import json,os; print((json.loads(os.environ["SOVIEZ_D"]).get("backup") or {}).get("classification") or "missing")')"
  capability="$(SOVIEZ_D="$discovery" python3 -c 'import json,os; print(str((json.loads(os.environ["SOVIEZ_D"]).get("backup") or {}).get("capability_healthy", True)).lower())')"
  if [[ "$capability" == "false" ]]; then
    blockers+=("backup_capability"); result="BLOCKED"
  elif [[ "$backup_class" == "missing" || "$backup_class" == "unverified" ]]; then
    warnings+=("backup_missing_or_unverified")
    [[ "$result" == "PASS" ]] && result="WARNING"
  elif [[ "$backup_class" == "verified_old" ]]; then
    warnings+=("backup_older_than_24h")
    [[ "$result" == "PASS" ]] && result="WARNING"
  fi

  # Token eligibility — never consume
  local token_json token_status
  token_json="$(soviez_migration_token_eligibility)"
  token_status="$(soviez_json_get "$token_json" status)"
  if [[ "$(soviez_json_get "$token_json" consumed)" == "true" ]]; then
    blockers+=("token_consumed_unexpected"); result="BLOCKED"
  fi
  if [[ "$token_status" == "unavailable" || "$token_status" == "ineligible" ]]; then
    warnings+=("migration_token_unavailable")
    [[ "$result" == "PASS" ]] && result="WARNING"
  fi

  # Connectivity / mTLS
  local mtls
  mtls="$(soviez_migration_mtls_connectivity_test "$pair_id")" || true
  if [[ "$mtls" != ok* ]]; then
    blockers+=("mtls_failed"); result="BLOCKED"
  fi

  # Image digest present
  local img
  img="$(soviez_json_get "$pair" source_image_digest)"
  if [[ -z "$img" ]]; then
    warnings+=("image_digest_empty")
    [[ "$result" == "PASS" ]] && result="WARNING"
  fi

  local report_id expires report
  report_id="$(soviez_migration_new_id ready)"
  expires="$(soviez_migration_expires_iso "${SOVIEZ_MIG_READINESS_TTL_SECONDS:-86400}")"
  report="$(SOVIEZ_RID="$report_id" SOVIEZ_PID="$pair_id" SOVIEZ_RES="$result" SOVIEZ_E="$expires" \
    SOVIEZ_W="$(printf '%s\n' "${warnings[@]:-}" | python3 -c 'import json,sys; print(json.dumps([l.strip() for l in sys.stdin if l.strip()]))')" \
    SOVIEZ_B="$(printf '%s\n' "${blockers[@]:-}" | python3 -c 'import json,sys; print(json.dumps([l.strip() for l in sys.stdin if l.strip()]))')" \
    SOVIEZ_CAP="$capacity_req" SOVIEZ_TOK="$token_json" SOVIEZ_PAIR="$pair" SOVIEZ_DISC="$discovery" \
    SOVIEZ_BOOT="$bootstrap" SOVIEZ_MT="$mtls" python3 - <<'PY'
import json, os, datetime, hashlib
pair=json.loads(os.environ["SOVIEZ_PAIR"])
disc=json.loads(os.environ["SOVIEZ_DISC"])
boot=json.loads(os.environ["SOVIEZ_BOOT"])
warnings=json.loads(os.environ["SOVIEZ_W"])
blockers=json.loads(os.environ["SOVIEZ_B"])
cap=json.loads(os.environ["SOVIEZ_CAP"])
tok=json.loads(os.environ["SOVIEZ_TOK"])
def fp(obj):
  return hashlib.sha256(json.dumps(obj, sort_keys=True, separators=(",",":")).encode()).hexdigest()
input_fps={
  "source_image_digest": (disc.get("identity") or {}).get("image_digest") or "",
  "destination_bootstrap_id": boot.get("bootstrap_id") or "",
  "destination_host_fp": ((boot.get("destination_host_identity") or {}).get("fingerprint") or boot.get("public_fingerprint") or ""),
  "selected_stage_ids": pair.get("selected_stage_ids") or [],
  "backup_classification": (disc.get("backup") or {}).get("classification") or "",
  "pair_id": pair.get("migration_pair_id") or "",
  "discovery_id": disc.get("discovery_id") or "",
}
input_fps["aggregate"]=fp(input_fps)
print(json.dumps({
  "schema_version": "soviez.migration.readiness.v1",
  "report_id": os.environ["SOVIEZ_RID"],
  "pair_id": os.environ["SOVIEZ_PID"],
  "result": os.environ["SOVIEZ_RES"],
  "source_summary": disc.get("identity"),
  "destination_summary": {
    "bootstrap_id": boot.get("bootstrap_id"),
    "os": boot.get("os_version"),
    "arch": boot.get("architecture"),
    "installer_version": boot.get("installer_version"),
  },
  "trust_status": pair.get("status"),
  "compatibility_matrix": {"os": boot.get("os_version"), "arch": boot.get("architecture"), "result": os.environ["SOVIEZ_RES"]},
  "capacity_matrix": cap,
  "connectivity_matrix": {"mtls": os.environ["SOVIEZ_MT"], "saas_relay": False},
  "backup_state": disc.get("backup"),
  "migration_token_eligibility": tok,
  "migration_token_consumed": False,
  "migration_token_reserved": False,
  "stage_inventory": disc.get("stages"),
  "selected_stage_ids": pair.get("selected_stage_ids") or [],
  "domain_ssl_inspection": {"domain": (disc.get("runtime") or {}).get("domain"), "mutated": False},
  "warnings": warnings,
  "blockers": blockers,
  "required_owner_actions": blockers + (["purchase_migration_token"] if tok.get("status")=="unavailable" else []),
  "estimated_future_transfer_bytes": (disc.get("capacity") or {}).get("estimated_transfer_bytes"),
  "estimated_future_duration_class": "unknown",
  "expected_downtime_class": "none_in_phase17",
  "created_at": datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
  "expires_at": os.environ["SOVIEZ_E"],
  "input_fingerprints": input_fps,
  "data_transfer_started": False,
  "dns_changed": False,
  "destination_production_activated": False,
  "source_license_active": True,
}, separators=(",", ":")))
PY
)"
  soviez_migration_report_sign_and_store readiness "$report_id" "$report" >/dev/null
  # Update pair with readiness id
  SOVIEZ_P="$pair_path" SOVIEZ_R="$report_id" SOVIEZ_RES="$result" SOVIEZ_TOK="$token_json" python3 - <<'PY'
import json, os
p=os.environ["SOVIEZ_P"]
d=json.load(open(p))
d["readiness_report_id"]=os.environ["SOVIEZ_R"]
d["compatibility_state"]=os.environ["SOVIEZ_RES"]
d["migration_token_eligibility"]=json.loads(os.environ["SOVIEZ_TOK"]).get("status")
d["migration_token_consumed"]=False
open(p,"w").write(json.dumps(d, separators=(",", ":")))
PY
  # Re-sign pair after update
  soviez_migration_sign_object_file "$pair_path"

  cat "$(soviez_migration_readiness_dir "$report_id")/object.json"
  soviez_migration_outcome_banner "COMPLETE" "COMPLETE" "TRUSTED" "$result" >&2 || true
}

soviez_migration_readiness_show() {
  local report_id="${1:-}"
  [[ -n "$report_id" ]] || soviez_migration_die MIGRATION_NOT_FOUND "report-id required"
  local path
  path="$(soviez_migration_readiness_dir "$report_id")/object.json"
  [[ -f "$path" ]] || soviez_migration_die MIGRATION_NOT_FOUND "Unknown readiness report: $report_id"
  if ! soviez_migration_verify_object_signature "$path"; then
    soviez_migration_die MIGRATION_PAIR_SIGNATURE_INVALID "Readiness signature invalid"
  fi
  if soviez_migration_is_expired "$(soviez_json_get "$(cat "$path")" expires_at)"; then
    soviez_migration_die MIGRATION_READINESS_EXPIRED "Readiness report expired"
  fi
  # Invalidate when material inputs changed vs fingerprints captured at report time
  local report pair_id pair discovery_id discovery bootstrap_id bootstrap
  report="$(cat "$path")"
  pair_id="$(soviez_json_get "$report" pair_id)"
  pair="$(cat "$(soviez_migration_pair_dir "$pair_id")/object.json" 2>/dev/null || echo '{}')"
  discovery_id="$(soviez_json_get "$pair" source_discovery_id)"
  bootstrap_id="$(soviez_json_get "$pair" destination_bootstrap_id)"
  discovery="$(cat "$(soviez_migration_discovery_dir "$discovery_id")/object.json" 2>/dev/null || echo '{}')"
  bootstrap="$(cat "$(soviez_migration_bootstrap_dir "$bootstrap_id")/object.json" 2>/dev/null || echo '{}')"
  SOVIEZ_R="$report" SOVIEZ_P="$pair" SOVIEZ_D="$discovery" SOVIEZ_B="$bootstrap" python3 - <<'PY' || soviez_migration_die MIGRATION_READINESS_INPUT_CHANGED "Readiness inputs changed"
import json, os, hashlib, sys
report=json.loads(os.environ["SOVIEZ_R"])
pair=json.loads(os.environ["SOVIEZ_P"])
disc=json.loads(os.environ["SOVIEZ_D"])
boot=json.loads(os.environ["SOVIEZ_B"])
fps=report.get("input_fingerprints") or {}
cur={
  "source_image_digest": (disc.get("identity") or {}).get("image_digest") or "",
  "destination_bootstrap_id": boot.get("bootstrap_id") or "",
  "destination_host_fp": ((boot.get("destination_host_identity") or {}).get("fingerprint") or boot.get("public_fingerprint") or ""),
  "selected_stage_ids": pair.get("selected_stage_ids") or [],
  "backup_classification": (disc.get("backup") or {}).get("classification") or "",
  "pair_id": pair.get("migration_pair_id") or "",
  "discovery_id": disc.get("discovery_id") or "",
}
for k in ("source_image_digest","destination_bootstrap_id","destination_host_fp","backup_classification","pair_id","discovery_id"):
  if fps.get(k) != cur.get(k):
    sys.exit(2)
if fps.get("selected_stage_ids") != cur.get("selected_stage_ids"):
  sys.exit(2)
sys.exit(0)
PY
  cat "$path"
}

soviez_migration_stage_select() {
  local pair_id="$1" stage_id="$2" mode="${3:-select}"
  local pair_path pair discovery_id discovery
  pair_path="$(soviez_migration_pair_dir "$pair_id")/object.json"
  [[ -f "$pair_path" ]] || soviez_migration_die MIGRATION_NOT_FOUND "Unknown pair"
  pair="$(cat "$pair_path")"
  discovery_id="$(soviez_json_get "$pair" source_discovery_id)"
  discovery="$(cat "$(soviez_migration_discovery_dir "$discovery_id")/object.json")"
  SOVIEZ_D="$discovery" SOVIEZ_S="$stage_id" SOVIEZ_P="$pair_path" SOVIEZ_M="$mode" python3 - <<'PY'
import json, os, sys
disc=json.loads(os.environ["SOVIEZ_D"])
sid=os.environ["SOVIEZ_S"]
mode=os.environ["SOVIEZ_M"]
stages=(disc.get("stages") or {}).get("stages") or []
match=[s for s in stages if s.get("stage_id")==sid]
if not match:
    print("MISSING", file=sys.stderr); sys.exit(31)
st=match[0]
if mode=="select":
    if not st.get("selectable", False):
        print("NOT_SELECTABLE:"+str(st.get("selectable_reason")), file=sys.stderr); sys.exit(32)
pair=json.load(open(os.environ["SOVIEZ_P"]))
sel=list(pair.get("selected_stage_ids") or [])
if mode=="select":
    if sid not in sel: sel.append(sid)
else:
    sel=[x for x in sel if x!=sid]
pair["selected_stage_ids"]=sel
# never mutate stage inventory on disk
open(os.environ["SOVIEZ_P"],"w").write(json.dumps(pair, separators=(",", ":")))
print(json.dumps({"selected_stage_ids": sel}, separators=(",", ":")))
PY
  local rc=$?
  if [[ $rc -eq 31 ]]; then
    soviez_migration_die MIGRATION_STAGE_NOT_SELECTABLE "Unknown stage"
  elif [[ $rc -eq 32 ]]; then
    soviez_migration_die MIGRATION_STAGE_EXPIRED "Stage not selectable"
  fi
  soviez_migration_sign_object_file "$pair_path"
}

soviez_migration_abort_run() {
  local pair_id="${1:-}"
  [[ -n "$pair_id" ]] || soviez_migration_die MIGRATION_PAIR_REQUIRED "pair-id required"
  soviez_migration_paths_init
  local pair_path bootstrap_id
  pair_path="$(soviez_migration_pair_dir "$pair_id")/object.json"
  if [[ -f "$pair_path" ]]; then
    bootstrap_id="$(soviez_json_get "$(cat "$pair_path")" destination_bootstrap_id)"
    soviez_migration_pair_revoke "$pair_id"
    [[ -n "$bootstrap_id" ]] && soviez_migration_bootstrap_abort_identity "$bootstrap_id"
  fi
  # Idempotent success
  printf '{"pair_id":"%s","status":"aborted","data_transfer_started":false,"migration_token_consumed":false,"source_maintenance_enabled":false,"destination_production_activated":false,"dns_changed":false}\n' "$pair_id"
}

