soviez_migration_source_routing_fingerprint() {
  local dns_json="$1" cert_json="$2" health_json="$3"
  SOVIEZ_D="$dns_json" SOVIEZ_C="$cert_json" SOVIEZ_H="$health_json" python3 - <<'PY'
import json, os, hashlib
parts={
  "dns": json.loads(os.environ["SOVIEZ_D"]),
  "cert": json.loads(os.environ["SOVIEZ_C"]),
  "health": json.loads(os.environ["SOVIEZ_H"]),
}
raw=json.dumps(parts, sort_keys=True, separators=(",", ":"))
print(hashlib.sha256(raw.encode()).hexdigest())
PY
}

soviez_migration_source_inspection_run() {
  local pair_json="$1"
  local prod_fqdn dns cert health fp
  prod_fqdn="$(soviez_migration_domain_production_fqdn "$pair_json")"
  dns="$(soviez_migration_source_inspect_dns "$prod_fqdn")"
  cert="$(soviez_migration_source_inspect_cert "$prod_fqdn")"
  health="$(soviez_migration_source_inspect_health "$pair_json")"
  fp="$(soviez_migration_source_routing_fingerprint "$dns" "$cert" "$health")"
  SOVIEZ_D="$dns" SOVIEZ_C="$cert" SOVIEZ_H="$health" SOVIEZ_F="$fp" SOVIEZ_P="$prod_fqdn" python3 - <<'PY'
import json, os
print(json.dumps({
  "production_fqdn": os.environ["SOVIEZ_P"],
  "dns": json.loads(os.environ["SOVIEZ_D"]),
  "certificate": json.loads(os.environ["SOVIEZ_C"]),
  "health": json.loads(os.environ["SOVIEZ_H"]),
  "source_routing_fingerprint": os.environ["SOVIEZ_F"],
  "read_only": True,
  "mutated": False,
}, separators=(",", ":")))
PY
}

# --- end migration/domain/source_inspection.sh ---

# --- begin migration/domain/plan.sh ---
# shellcheck shell=bash

soviez_migration_domain_plan_build() {
  local pair_id="$1" pair_json="$2" migration_fqdn="$3" production_fqdn="$4" inspection_json="$5"
  local plan_id op_id expires flags
  plan_id="$(soviez_migration_new_id dplan)"
  op_id="$(soviez_migration_new_id dom-op)"
  expires="$(soviez_migration_expires_iso "${SOVIEZ_MIG_ROUTING_PLAN_TTL_SECONDS:-86400}")"
  flags="$(soviez_migration_domain_plan_flags_json "$pair_json")"
  SOVIEZ_PID="$plan_id" SOVIEZ_OP="$op_id" SOVIEZ_PAIR="$pair_id" SOVIEZ_PJ="$pair_json" \
    SOVIEZ_MF="$migration_fqdn" SOVIEZ_PF="$production_fqdn" SOVIEZ_IN="$inspection_json" \
    SOVIEZ_FL="$flags" SOVIEZ_E="$expires" python3 - <<'PY'
import json, os, datetime
pair=json.loads(os.environ["SOVIEZ_PJ"])
flags=json.loads(os.environ["SOVIEZ_FL"])
ins=json.loads(os.environ["SOVIEZ_IN"])
print(json.dumps({
  "schema_version": "soviez.migration_domain_plan.v1",
  "plan_id": os.environ["SOVIEZ_PID"],
  "operation_id": os.environ["SOVIEZ_OP"],
  "migration_pair_id": os.environ["SOVIEZ_PAIR"],
  "strategy": "option_a_migrate_subdomain",
  "production_fqdn": os.environ["SOVIEZ_PF"],
  "migration_fqdn": os.environ["SOVIEZ_MF"],
  "source_inspection": ins,
  "expected_dns_records": {
    "txt_ownership": {"name": f"_soviez-migration.{os.environ['SOVIEZ_MF']}", "ttl": 300},
    "reachability": {"a_or_aaaa_or_cname": True, "fqdn": os.environ["SOVIEZ_MF"]},
  },
  "authorization_flags": flags,
  "production_domain_mutation_allowed": False,
  "source_maintenance_allowed": False,
  "payload_transfer_allowed": False,
  "migration_token_consumed": False,
  "destination_production_activated": False,
  "source_dns_mutation_allowed": False,
  "created_at": datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
  "expires_at": os.environ["SOVIEZ_E"],
  "status": "planned",
}, separators=(",", ":")))
PY
}

# --- end migration/domain/plan.sh ---

# --- begin migration/domain/report.sh ---
# shellcheck shell=bash

soviez_migration_domain_plan_report() {
  local plan_id="$1"
  local path
  path="$(soviez_migration_domain_plan_dir "$plan_id")/object.json"
  [[ -f "$path" ]] || soviez_migration_die MIGRATION_NOT_FOUND "Unknown domain plan: $plan_id"
  cat "$path"
}

soviez_migration_domain_plan_show() {
  soviez_migration_domain_plan_report "$1"
}

# --- end migration/domain/report.sh ---

# --- begin migration/domain/engine.sh ---
# shellcheck shell=bash

soviez_migration_domain_plan_run() {
  local pair_id="${1:-}"
  soviez_migration_paths_init
  soviez_migration_assert_no_transfer

  local pair production_fqdn migration_fqdn inspection plan_json plan_id op_id
  pair="$(soviez_migration_load_pair "$pair_id")"
  production_fqdn="$(soviez_migration_domain_production_fqdn "$pair")"
  [[ -n "$production_fqdn" ]] || soviez_migration_die MIGRATION_DOMAIN_REQUIRED "Production domain unknown from discovery"

  migration_fqdn="$(soviez_migration_domain_strategy_resolve "$production_fqdn" "${SOVIEZ_MIG_DOMAIN_FQDN:-}")"
  soviez_migration_domain_assert_migration_fqdn "$migration_fqdn" "$production_fqdn"

  inspection="$(soviez_migration_source_inspection_run "$pair")"
  plan_json="$(soviez_migration_domain_plan_build "$pair_id" "$pair" "$migration_fqdn" "$production_fqdn" "$inspection")"
  plan_id="$(soviez_json_get "$plan_json" plan_id)"
  op_id="$(soviez_json_get "$plan_json" operation_id)"

  soviez_migration_report_sign_and_store domain_plan "$plan_id" "$plan_json" >/dev/null
  mkdir -p "$SOVIEZ_MIG_ROOT/ops/$op_id"
  printf '{"operation_id":"%s","operation_type":"%s","current_state":"completed","pair_id":"%s","plan_id":"%s"}\n' \
    "$op_id" "$SOVIEZ_MIG_OP_DOMAIN_PLAN" "$pair_id" "$plan_id" > "$SOVIEZ_MIG_ROOT/ops/$op_id/state.json"

  # Link plan to pair (non-destructive metadata)
  local pair_path
  pair_path="$(soviez_migration_pair_dir "$pair_id")/object.json"
  SOVIEZ_P="$pair_path" SOVIEZ_PL="$plan_id" SOVIEZ_MF="$migration_fqdn" python3 - <<'PY'
import json, os
p=os.environ["SOVIEZ_P"]
d=json.load(open(p))
d["domain_plan_id"]=os.environ["SOVIEZ_PL"]
d["migration_fqdn"]=os.environ["SOVIEZ_MF"]
open(p,"w").write(json.dumps(d, separators=(",", ":")))
PY
  soviez_migration_sign_object_file "$pair_path"

  cat "$(soviez_migration_domain_plan_dir "$plan_id")/object.json"
}

# --- end migration/domain/engine.sh ---

# --- begin migration/dns/signing.sh ---
# shellcheck shell=bash

soviez_migration_dns_challenge_binding_payload() {
  local pair_id="$1" prod_id="$2" prod_domain="$3" migration_fqdn="$4" \
    bootstrap_id="$5" dst_fp="$6" license_id="$7" op_id="$8" nonce="$9" expires="$10"
  printf '%s|%s|%s|%s|%s|%s|%s|%s|%s|%s' \
    "$pair_id" "$prod_id" "$prod_domain" "$migration_fqdn" \
    "$bootstrap_id" "$dst_fp" "$license_id" "$op_id" "$nonce" "$expires"
}

soviez_migration_dns_challenge_sign() {
  local payload="$1"
  soviez_migration_sign_json "$payload"
}

soviez_migration_dns_challenge_verify_sig() {
  local payload="$1" sig="$2"
  local actual
  actual="$(soviez_migration_dns_challenge_sign "$payload")"
  [[ "$actual" == "$sig" ]]
}

soviez_migration_dns_challenge_txt_name() {
  local migration_fqdn="$1"
  printf '_soviez-migration.%s\n' "$migration_fqdn"
}

soviez_migration_dns_challenge_txt_value() {
  local challenge_id="$1" sig="$2"
  printf 'v1.%s.%s\n' "$challenge_id" "$sig"
}

# --- end migration/dns/signing.sh ---

# --- begin migration/dns/replay.sh ---
# shellcheck shell=bash

soviez_migration_dns_replay_seen() {
  local challenge_id="$1"
  local f="$SOVIEZ_MIG_DNS_REPLAY_DIR/${challenge_id}.seen"
  [[ -f "$f" ]]
}

soviez_migration_dns_replay_mark() {
  local challenge_id="$1"
  mkdir -p "$SOVIEZ_MIG_DNS_REPLAY_DIR"
  printf '%s\n' "$(soviez_migration_now_iso)" > "$SOVIEZ_MIG_DNS_REPLAY_DIR/${challenge_id}.seen"
}

soviez_migration_dns_replay_assert_fresh() {
  local challenge_id="$1"
  if soviez_migration_dns_replay_seen "$challenge_id"; then
    soviez_migration_die MIGRATION_DNS_CHALLENGE_REPLAY_DENIED "DNS challenge replay denied"
  fi
}

# --- end migration/dns/replay.sh ---

# --- begin migration/dns/authoritative.sh ---
# shellcheck shell=bash

soviez_migration_dns_authoritative_lookup() {
  soviez_migration_dns_query "$1" "${2:-TXT}" authoritative
}

soviez_migration_dns_authoritative_match() {
  local name="$1" rtype="$2" expected="$3"
  local found ok=1
  while IFS= read -r line; do
    [[ -z "$line" ]] && continue
    line="${line#\"}"; line="${line%\"}"
    if [[ "$line" == "$expected" ]]; then ok=0; break; fi
  done < <(soviez_migration_dns_authoritative_lookup "$name" "$rtype")
  return "$ok"
}

# --- end migration/dns/authoritative.sh ---

# --- begin migration/dns/public_resolvers.sh ---
# shellcheck shell=bash

soviez_migration_dns_public_resolver_views() {
  printf '%s\n' "public_a" "public_b"
}

soviez_migration_dns_public_resolvers_agree() {
  local name="$1" rtype="$2" expected="$3"
  local view lines match=0
  for view in $(soviez_migration_dns_public_resolver_views); do
    lines="$(soviez_migration_dns_query "$name" "$rtype" "$view" | tr '\n' '|')"
    if [[ "$lines" == *"$expected"* ]]; then
      match=$((match + 1))
    fi
  done
  [[ "$match" -ge 2 ]]
}

soviez_migration_dns_public_vs_authoritative() {
  local name="$1" rtype="$2"
  local auth pub_a pub_b
  auth="$(soviez_migration_dns_authoritative_lookup "$name" "$rtype" | head -1 | tr -d '"')"
  pub_a="$(soviez_migration_dns_query "$name" "$rtype" public_a | head -1 | tr -d '"')"
  pub_b="$(soviez_migration_dns_query "$name" "$rtype" public_b | head -1 | tr -d '"')"
  [[ -n "$auth" && "$auth" == "$pub_a" && "$auth" == "$pub_b" ]]
}

# --- end migration/dns/public_resolvers.sh ---

# --- begin migration/dns/provider.sh ---
# shellcheck shell=bash

soviez_migration_dns_provider_create_record() {
  local name="$1" rtype="$2" value="$3" ttl="${4:-300}"
  local zone_dir view="${5:-authoritative}"
  zone_dir="$(soviez_migration_dns_fixture_zone_dir)"
  for view in authoritative public_a public_b; do
    mkdir -p "$zone_dir/$view/$name"
    printf '%s\n' "$value" > "$zone_dir/$view/$name/${rtype}.txt"
  done
  chmod -R u+rwX "$zone_dir" 2>/dev/null || true
  printf '{"created":true,"name":"%s","type":"%s","ttl":%s,"provider":"mock_fixture"}\n' "$name" "$rtype" "$ttl"
}

soviez_migration_dns_provider_delete_record() {
  local name="$1" rtype="$2"
  local zone_dir view
  zone_dir="$(soviez_migration_dns_fixture_zone_dir)"
  for view in authoritative public_a public_b; do
    rm -f "$zone_dir/$view/$name/${rtype}.txt" 2>/dev/null || true
  done
}

# --- end migration/dns/provider.sh ---

# --- begin migration/dns/challenge.sh ---
# shellcheck shell=bash

soviez_migration_dns_challenge_create() {
  local pair_id="${1:-}" plan_id="${2:-}"
  soviez_migration_paths_init
  soviez_migration_assert_no_transfer

  local pair prod_id prod_domain migration_fqdn bootstrap_id dst_fp license_id
  pair="$(soviez_migration_load_pair "$pair_id")"
  prod_id="$(soviez_json_get "$pair" source_production_id)"
  prod_domain="$(soviez_migration_domain_production_fqdn "$pair")"
  migration_fqdn="$(soviez_json_get "$pair" migration_fqdn)"
  if [[ -z "$migration_fqdn" || "$migration_fqdn" == "null" ]]; then
    migration_fqdn="$(soviez_migration_domain_strategy_default "$prod_domain")"
  fi
  soviez_migration_domain_assert_migration_fqdn "$migration_fqdn" "$prod_domain"
  bootstrap_id="$(soviez_json_get "$pair" destination_bootstrap_id)"
  dst_fp="$(soviez_json_get "$pair" destination_fingerprint)"
  license_id="$(soviez_json_get "$pair" source_license_id)"

  local challenge_id op_id nonce expires payload sig txt_name txt_value challenge_json
  challenge_id="$(soviez_migration_new_id dns-ch)"
  op_id="$(soviez_migration_new_id dns-op)"
  nonce="$(openssl rand -hex 16)"
  expires="$(soviez_migration_expires_iso "${SOVIEZ_MIG_DNS_CHALLENGE_TTL_SECONDS:-1800}")"
  payload="$(soviez_migration_dns_challenge_binding_payload "$pair_id" "$prod_id" "$prod_domain" \
    "$migration_fqdn" "$bootstrap_id" "$dst_fp" "$license_id" "$op_id" "$nonce" "$expires")"
  sig="$(soviez_migration_dns_challenge_sign "$payload")"
  txt_name="$(soviez_migration_dns_challenge_txt_name "$migration_fqdn")"
  txt_value="$(soviez_migration_dns_challenge_txt_value "$challenge_id" "$sig")"

  challenge_json="$(SOVIEZ_CID="$challenge_id" SOVIEZ_OP="$op_id" SOVIEZ_PAIR="$pair_id" \
    SOVIEZ_PLAN="$plan_id" SOVIEZ_MF="$migration_fqdn" SOVIEZ_PF="$prod_domain" \
    SOVIEZ_TN="$txt_name" SOVIEZ_TV="$txt_value" SOVIEZ_SIG="$sig" SOVIEZ_NON="$nonce" \
    SOVIEZ_EXP="$expires" SOVIEZ_PAY="$payload" SOVIEZ_PID="$prod_id" SOVIEZ_L="$license_id" \
    SOVIEZ_B="$bootstrap_id" SOVIEZ_DF="$dst_fp" python3 - <<'PY'
import json, os, datetime
print(json.dumps({
  "schema_version": "soviez.migration_dns_challenge.v1",
  "challenge_id": os.environ["SOVIEZ_CID"],
  "operation_id": os.environ["SOVIEZ_OP"],
  "migration_pair_id": os.environ["SOVIEZ_PAIR"],
  "domain_plan_id": os.environ.get("SOVIEZ_PLAN") or "",
  "migration_fqdn": os.environ["SOVIEZ_MF"],
  "production_fqdn": os.environ["SOVIEZ_PF"],
  "source_production_id": os.environ["SOVIEZ_PID"],
  "destination_bootstrap_id": os.environ["SOVIEZ_B"],
  "destination_fingerprint": os.environ["SOVIEZ_DF"],
  "license_id": os.environ["SOVIEZ_L"],
  "txt_record": {"name": os.environ["SOVIEZ_TN"], "value": os.environ["SOVIEZ_TV"], "ttl": 300},
  "expected_reachability": {"a": [], "aaaa": [], "cname": []},
  "binding_payload": os.environ["SOVIEZ_PAY"],
  "binding_signature": os.environ["SOVIEZ_SIG"],
  "nonce": os.environ["SOVIEZ_NON"],
  "issued_at": datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
  "expires_at": os.environ["SOVIEZ_EXP"],
  "status": "pending",
  "consumed": False,
  "provider_created": False,
}, separators=(",", ":")))
PY
)"
  soviez_migration_report_sign_and_store dns_challenge "$challenge_id" "$challenge_json" >/dev/null
  mkdir -p "$SOVIEZ_MIG_ROOT/ops/$op_id"
  printf '{"operation_id":"%s","operation_type":"%s","current_state":"pending","pair_id":"%s","challenge_id":"%s"}\n' \
    "$op_id" "$SOVIEZ_MIG_OP_DNS_CHALLENGE" "$pair_id" "$challenge_id" > "$SOVIEZ_MIG_ROOT/ops/$op_id/state.json"
  cat "$(soviez_migration_dns_challenge_dir "$challenge_id")/object.json"
}

soviez_migration_dns_challenge_load() {
  local challenge_id="$1"
  local path
  path="$(soviez_migration_dns_challenge_dir "$challenge_id")/object.json"
  [[ -f "$path" ]] || soviez_migration_die MIGRATION_DNS_CHALLENGE_REQUIRED "Unknown challenge: $challenge_id"
  cat "$path"
}

soviez_migration_dns_challenge_verify() {
  local challenge_id="${1:-}"
  soviez_migration_paths_init
  soviez_migration_assert_no_transfer

  local challenge path txt_name txt_value sig payload status consumed expires
  challenge="$(soviez_migration_dns_challenge_load "$challenge_id")"
  path="$(soviez_migration_dns_challenge_dir "$challenge_id")/object.json"
  if ! soviez_migration_verify_object_signature "$path"; then
    soviez_migration_die MIGRATION_DNS_CHALLENGE_INVALID "Challenge signature invalid"
  fi
  status="$(soviez_json_get "$challenge" status)"
  consumed="$(soviez_json_get "$challenge" consumed)"
  expires="$(soviez_json_get "$challenge" expires_at)"
  [[ "$consumed" != "true" && "$consumed" != "True" ]] || \
    soviez_migration_die MIGRATION_DNS_CHALLENGE_REPLAY_DENIED "Challenge already consumed"
  if soviez_migration_is_expired "$expires"; then
    soviez_migration_die MIGRATION_DNS_CHALLENGE_EXPIRED "Challenge expired"
  fi
  soviez_migration_dns_replay_assert_fresh "$challenge_id"

  payload="$(soviez_json_get "$challenge" binding_payload)"
  sig="$(soviez_json_get "$challenge" binding_signature)"
  soviez_migration_dns_challenge_verify_sig "$payload" "$sig" || \
    soviez_migration_die MIGRATION_DNS_CHALLENGE_INVALID "Binding signature mismatch"

  txt_name="$(soviez_json_get "$(soviez_json_get "$challenge" txt_record)" name)"
  txt_value="$(soviez_json_get "$(soviez_json_get "$challenge" txt_record)" value)"

  if ! soviez_migration_dns_authoritative_match "$txt_name" TXT "$txt_value"; then
    soviez_migration_die MIGRATION_DNS_RECORD_MISMATCH "Authoritative TXT mismatch"
  fi
  if ! soviez_migration_dns_public_resolvers_agree "$txt_name" TXT "$txt_value"; then
    soviez_migration_die MIGRATION_DNS_PROPAGATION_PENDING "Public resolver propagation pending"
  fi
  if ! soviez_migration_dns_public_vs_authoritative "$txt_name" TXT; then
    soviez_migration_die MIGRATION_DNS_AUTHORITATIVE_MISMATCH "Authoritative vs public mismatch"
  fi

  # Reachability A/AAAA/CNAME for migration FQDN
  local mig_fqdn a_ok
  mig_fqdn="$(soviez_json_get "$challenge" migration_fqdn)"
  a_ok=1
  if soviez_migration_dns_query "$mig_fqdn" A authoritative | grep -q .; then a_ok=0; fi
  if soviez_migration_dns_query "$mig_fqdn" AAAA authoritative | grep -q .; then a_ok=0; fi
  if soviez_migration_dns_query "$mig_fqdn" CNAME authoritative | grep -q .; then a_ok=0; fi
  if [[ "$a_ok" -ne 0 ]]; then
    soviez_migration_die MIGRATION_IPV4_UNREACHABLE "Migration FQDN reachability record missing"
  fi

  soviez_migration_dns_replay_mark "$challenge_id"
  SOVIEZ_P="$path" python3 - <<'PY'
import json, os, datetime
p=os.environ["SOVIEZ_P"]
d=json.load(open(p))
d["status"]="verified"
d["consumed"]=True
d["verified_at"]=datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
open(p,"w").write(json.dumps(d, separators=(",", ":")))
PY
  soviez_migration_sign_object_file "$path"
  cat "$path"
}

# --- end migration/dns/challenge.sh ---

# --- begin migration/dns/retry.sh ---
# shellcheck shell=bash

soviez_migration_dns_challenge_abort() {
  local challenge_id="${1:-}"
  soviez_migration_paths_init
  local path provider_created txt_name
  path="$(soviez_migration_dns_challenge_dir "$challenge_id")/object.json"
  if [[ ! -f "$path" ]]; then
    printf '{"challenge_id":"%s","status":"aborted"}\n' "$challenge_id"
    return 0
  fi
  provider_created="$(soviez_json_get "$(cat "$path")" provider_created)"
  txt_name="$(soviez_json_get "$(soviez_json_get "$(cat "$path")" txt_record)" name)"
  if [[ "$provider_created" == "true" || "$provider_created" == "True" ]]; then
    soviez_migration_dns_provider_delete_record "$txt_name" TXT
  fi
  SOVIEZ_P="$path" python3 - <<'PY'
import json, os
p=os.environ["SOVIEZ_P"]
d=json.load(open(p))
d["status"]="aborted"
d["consumed"]=False
open(p,"w").write(json.dumps(d, separators=(",", ":")))
PY
  soviez_migration_sign_object_file "$path"
  printf '{"challenge_id":"%s","status":"aborted","owner_dns_preserved":true}\n' "$challenge_id"
}

# Renew: create a fresh challenge (required after expiry). Does not mutate DNS.
soviez_migration_dns_challenge_renew() {
  local pair_id="${1:-}"
  soviez_migration_paths_init
  local plan_id=""
  plan_id="$(soviez_json_get "$(soviez_migration_load_pair "$pair_id")" domain_plan_id 2>/dev/null || true)"
  [[ -n "$plan_id" && "$plan_id" != "null" ]] || plan_id=""
  soviez_migration_dns_challenge_create "$pair_id" "$plan_id"
}

# Backward-compatible alias used by older tests/CLI — means renew (new challenge id).
soviez_migration_dns_challenge_retry() {
  soviez_migration_dns_challenge_renew "$@"
}

# Try Again: same challenge id while unexpired; re-check DNS; no DNS mutation; no new ACME order.
soviez_migration_dns_challenge_try_again() {
  local challenge_id="${1:-}"
  local challenge path status expires
  soviez_migration_paths_init
  [[ -n "$challenge_id" ]] || soviez_migration_die MIGRATION_DNS_CHALLENGE_REQUIRED "challenge-id required"
  challenge="$(soviez_migration_dns_challenge_load "$challenge_id")"
  path="$(soviez_migration_dns_challenge_dir "$challenge_id")/object.json"
  status="$(soviez_json_get "$challenge" status)"
  expires="$(soviez_json_get "$challenge" expires_at)"

  if [[ "$status" == "verified" ]]; then
    SOVIEZ_P="$path" python3 - <<'PY'
import json, os
d=json.load(open(os.environ["SOVIEZ_P"]))
d["try_again"]="already_verified"
print(json.dumps(d, separators=(",", ":")))
PY
    return 0
  fi
  if [[ "$status" == "aborted" ]]; then
    soviez_migration_die MIGRATION_DOMAIN_ABORTED "Challenge aborted"
  fi
  if soviez_migration_is_expired "$expires"; then
    soviez_migration_die MIGRATION_DNS_CHALLENGE_EXPIRED "Challenge expired; create a new challenge"
  fi
  # Idempotent re-validation of the exact challenge (no new nonce / no DNS write).
  soviez_migration_dns_challenge_verify "$challenge_id"
}

# --- end migration/dns/retry.sh ---

# --- begin migration/dns/instructions.sh ---
# shellcheck shell=bash

soviez_migration_dns_instructions_export() {
  local challenge_id="${1:-}" out="${2:-}"
  [[ -n "$challenge_id" ]] || soviez_migration_die MIGRATION_DNS_CHALLENGE_REQUIRED "challenge-id required"
  local challenge
  challenge="$(soviez_migration_dns_challenge_load "$challenge_id")"
  local txt_name txt_value ttl mig_fqdn
  txt_name="$(soviez_json_get "$(soviez_json_get "$challenge" txt_record)" name)"
  txt_value="$(soviez_json_get "$(soviez_json_get "$challenge" txt_record)" value)"
  ttl="$(soviez_json_get "$(soviez_json_get "$challenge" txt_record)" ttl)"
  mig_fqdn="$(soviez_json_get "$challenge" migration_fqdn)"
  local doc
  doc="$(SOVIEZ_TN="$txt_name" SOVIEZ_TV="$txt_value" SOVIEZ_TTL="$ttl" SOVIEZ_MF="$mig_fqdn" \
    SOVIEZ_CID="$challenge_id" python3 - <<'PY'
import json, os
print(json.dumps({
  "challenge_id": os.environ["SOVIEZ_CID"],
  "instructions": [
    {"step": 1, "action": "Create TXT record", "name": os.environ["SOVIEZ_TN"], "value": os.environ["SOVIEZ_TV"], "ttl": int(os.environ["SOVIEZ_TTL"])},
    {"step": 2, "action": "Create A or AAAA or CNAME for migration FQDN", "name": os.environ["SOVIEZ_MF"], "value": "<destination-public-ip-or-target>"},
    {"step": 3, "action": "Wait for propagation", "note": "Two public resolvers must agree with authoritative"},
    {"step": 4, "action": "Run verify", "command": f"soviez.sh --migration-dns-challenge-verify {os.environ['SOVIEZ_CID']}"},
  ],
  "do_not": ["Do not point production apex to destination in Phase 18", "Do not enable source maintenance"],
}, indent=2))
PY
)"
  if [[ -n "$out" ]]; then
    mkdir -p "$(dirname "$out")"
    printf '%s\n' "$doc" > "$out"
    printf '%s\n' "$out"
  else
    printf '%s\n' "$doc"
  fi
}

# --- end migration/dns/instructions.sh ---

# --- begin migration/landing/content.sh ---
# shellcheck shell=bash

soviez_migration_landing_site_id() {
  local pair_id="$1"
  printf 'mig-landing-%s\n' "$pair_id"
}

soviez_migration_landing_write_content() {
  local site_dir="$1" pair_id="$2" migration_fqdn="$3"
  mkdir -p "$site_dir/www"
  cat > "$site_dir/www/index.html" <<EOF
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>Migration in progress</title>
  <meta name="viewport" content="width=device-width, initial-scale=1">
</head>
<body>
  <main>
    <h1>Migration in progress</h1>
    <p>Your Soviez environment is being prepared on a dedicated migration subdomain.</p>
    <p>Operation reference: <code>$(printf '%s' "$pair_id" | sed 's/[&<>"]//g')</code></p>
    <p>No customer data is shown on this page. Contact your administrator for next steps.</p>
  </main>
</body>
</html>
EOF
  cat > "$site_dir/www/healthz" <<EOF
{"ok":true,"site":"$(printf '%s' "$migration_fqdn" | sed 's/[\\"]//g')"}
EOF
}

# --- end migration/landing/content.sh ---

# --- begin migration/landing/headers.sh ---
# shellcheck shell=bash

soviez_migration_landing_security_headers_block() {
  cat <<'EOF'
    add_header X-Content-Type-Options "nosniff" always;
    add_header Referrer-Policy "no-referrer" always;
    add_header X-Frame-Options "DENY" always;
    add_header Content-Security-Policy "default-src 'none'; img-src 'self'; style-src 'self' 'unsafe-inline'; frame-ancestors 'none'" always;
EOF
}

# --- end migration/landing/headers.sh ---

# --- begin migration/landing/nginx.sh ---
# shellcheck shell=bash

soviez_migration_landing_write_nginx() {
  local site_dir="$1" migration_fqdn="$2" cert="${3:-}" key="${4:-}"
  local ssl_block listen443=""
  if [[ -n "$cert" && -n "$key" ]]; then
    listen443="
    listen 443 ssl;
    ssl_certificate ${cert};
    ssl_certificate_key ${key};"
  fi
  cat > "$site_dir/nginx.conf" <<EOF
# SOVIEZ_OWNED module=migration_landing version=phase18
server {
    listen 80;
    server_name ${migration_fqdn};
    root ${site_dir}/www;
    location /healthz {
        default_type application/json;
        try_files /healthz =404;
    }
    location / {
        try_files /index.html =404;
    }
$(soviez_migration_landing_security_headers_block)
}
EOF
  if [[ -n "$cert" && -n "$key" ]]; then
    cat >> "$site_dir/nginx.conf" <<EOF
server {${listen443}
    server_name ${migration_fqdn};
    root ${site_dir}/www;
    location /healthz {
        default_type application/json;
        try_files /healthz =404;
    }
    location / {
        try_files /index.html =404;
    }
$(soviez_migration_landing_security_headers_block)
}
EOF
  fi
}

soviez_migration_landing_validate_nginx() {
  local conf="$1" migration_fqdn="$2" production_fqdn="$3"
  [[ -f "$conf" ]] || soviez_migration_die MIGRATION_NGINX_CONFIG_INVALID "Missing nginx config"
  if grep -q "server_name[[:space:]]*${production_fqdn}[;[:space:]]" "$conf" 2>/dev/null; then
    soviez_migration_die MIGRATION_NGINX_CONFIG_INVALID "Production domain must not appear in server_name"
  fi
  if ! grep -q "server_name[[:space:]]*${migration_fqdn}[;[:space:]]" "$conf"; then
    soviez_migration_die MIGRATION_NGINX_CONFIG_INVALID "Migration FQDN missing from server_name"
  fi
  if [[ "${SOVIEZ_MIG_LANDING_REAL_NGINX:-0}" == "1" ]] && command -v docker >/dev/null 2>&1; then
    docker run --rm -v "$conf:/etc/nginx/conf.d/default.conf:ro" nginx:alpine nginx -t >/dev/null 2>&1 || \
      soviez_migration_die MIGRATION_NGINX_CONFIG_INVALID "docker nginx -t failed"
    return 0
  fi
  if declare -F soviez_nginx_test_config >/dev/null 2>&1; then
    soviez_nginx_test_config "$conf" || soviez_migration_die MIGRATION_NGINX_CONFIG_INVALID "nginx config test failed"
  else
    grep -q 'server_name' "$conf" || soviez_migration_die MIGRATION_NGINX_CONFIG_INVALID "invalid nginx structure"
  fi
}

# --- end migration/landing/nginx.sh ---

# --- begin migration/landing/health.sh ---
# shellcheck shell=bash

soviez_migration_landing_health_check() {
  local site_dir="$1"
  local hz="$site_dir/www/healthz"
  [[ -f "$hz" ]] || soviez_migration_die MIGRATION_LANDING_HEALTH_FAILED "healthz missing"
  grep -q '"ok"[[:space:]]*:[[:space:]]*true' "$hz" || \
    soviez_migration_die MIGRATION_LANDING_HEALTH_FAILED "healthz not ok"
  printf '{"ok":true,"path":"%s"}\n' "$hz"
}

# --- end migration/landing/health.sh ---

# --- begin migration/landing/cleanup.sh ---
# shellcheck shell=bash

soviez_migration_landing_cleanup() {
  local pair_id="${1:-}"
  soviez_migration_paths_init
  local site_id site_dir
  site_id="$(soviez_migration_landing_site_id "$pair_id")"
  site_dir="$(soviez_migration_landing_site_dir "$site_id")"
  if [[ -d "$site_dir" ]]; then
    rm -rf "$site_dir"
  fi
  printf '{"pair_id":"%s","site_id":"%s","status":"cleaned"}\n' "$pair_id" "$site_id"
}

soviez_migration_landing_prepare() {
  local pair_id="${1:-}"
  soviez_migration_paths_init
  soviez_migration_assert_no_transfer

  local pair migration_fqdn production_fqdn site_id site_dir
  pair="$(soviez_migration_load_pair "$pair_id")"
  production_fqdn="$(soviez_migration_domain_production_fqdn "$pair")"
  migration_fqdn="$(soviez_json_get "$pair" migration_fqdn)"
  [[ -n "$migration_fqdn" && "$migration_fqdn" != "null" ]] || \
    migration_fqdn="$(soviez_migration_domain_strategy_default "$production_fqdn")"
  soviez_migration_domain_assert_migration_fqdn "$migration_fqdn" "$production_fqdn"

  site_id="$(soviez_migration_landing_site_id "$pair_id")"
  site_dir="$(soviez_migration_landing_site_dir "$site_id")"
  soviez_migration_landing_write_content "$site_dir" "$pair_id" "$migration_fqdn"
  soviez_migration_landing_write_nginx "$site_dir" "$migration_fqdn"
  soviez_migration_landing_validate_nginx "$site_dir/nginx.conf" "$migration_fqdn" "$production_fqdn"
  soviez_migration_landing_health_check "$site_dir" >/dev/null

  SOVIEZ_PAIR="$pair_id" SOVIEZ_SID="$site_id" SOVIEZ_MF="$migration_fqdn" SOVIEZ_DIR="$site_dir" python3 - <<'PY'
import json, os, datetime, hashlib
root=os.environ["SOVIEZ_DIR"]
idx=open(f"{root}/www/index.html","rb").read()
print(json.dumps({
  "schema_version": "soviez.migration_landing.v1",
  "pair_id": os.environ["SOVIEZ_PAIR"],
  "site_id": os.environ["SOVIEZ_SID"],
  "migration_fqdn": os.environ["SOVIEZ_MF"],
  "content_root": f"{root}/www",
  "nginx_conf": f"{root}/nginx.conf",
  "content_hash": hashlib.sha256(idx).hexdigest(),
  "status": "prepared",
  "created_at": datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
}, separators=(",", ":")))
PY
}

# --- end migration/landing/cleanup.sh ---

# --- begin migration/tls/policy.sh ---
# shellcheck shell=bash
# Phase 18 migration TLS policy — wraps ssl/policy.sh with migration-specific denies.

soviez_migration_tls_policy_assert() {
  local fqdn="$1" production_fqdn="$2" cert_mode="${3:-public}"
  soviez_migration_domain_assert_migration_fqdn "$fqdn" "$production_fqdn"
  if [[ "$cert_mode" == "self_signed" ]]; then
    soviez_migration_die MIGRATION_TLS_ISSUANCE_FAILED "Self-signed final certificate denied"
  fi
  if declare -F soviez_ssl_policy_assert_ca >/dev/null 2>&1; then
    soviez_ssl_policy_assert_ca "$cert_mode"
  fi
}

soviez_migration_tls_policy_assert_production_preissue() {
  soviez_migration_die MIGRATION_TLS_ISSUANCE_FAILED "Production domain TLS pre-issue denied in Phase 18"
}

# --- end migration/tls/policy.sh ---

# --- begin migration/tls/storage.sh ---
# shellcheck shell=bash

soviez_migration_tls_secrets_dir() {
  local pair_id="$1" fqdn="$2"
  printf '%s/%s/%s\n' "$SOVIEZ_MIG_SECRETS_DIR/tls" "$pair_id" "$fqdn"
}

soviez_migration_tls_inventory_path() {
  local pair_id="$1" fqdn="$2"
  printf '%s/%s.json\n' "$(soviez_migration_tls_dir "$pair_id")" "$fqdn"
}

soviez_migration_tls_write_inventory() {
  local pair_id="$1" fqdn="$2" cert_path="$3" key_path="$4" issuer="$5" not_after="$6"
  mkdir -p "$(soviez_migration_tls_dir "$pair_id")"
  SOVIEZ_PID="$pair_id" SOVIEZ_F="$fqdn" SOVIEZ_C="$cert_path" SOVIEZ_K="$key_path" \
    SOVIEZ_I="$issuer" SOVIEZ_N="$not_after" python3 - <<'PY'
import json, os, datetime
inv={
  "schema_version": "soviez.migration_tls_inventory.v1",
  "pair_id": os.environ["SOVIEZ_PID"],
  "fqdn": os.environ["SOVIEZ_F"],
  "certificate_path": os.environ["SOVIEZ_C"],
  "private_key_path": os.environ["SOVIEZ_K"],
  "issuer": os.environ["SOVIEZ_I"],
  "not_after": os.environ["SOVIEZ_N"],
  "private_key_included": False,
  "created_at": datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
}
open(os.environ["OUT"], "w").write(json.dumps(inv, separators=(",", ":")))
PY
}

# --- end migration/tls/storage.sh ---

# --- begin migration/tls/verify.sh ---
# shellcheck shell=bash

soviez_migration_tls_verify_cert() {
  local cert_path="$1" fqdn="$2"
  local ca_path="${3:-}"
  [[ -f "$cert_path" ]] || soviez_migration_die MIGRATION_TLS_CHAIN_INVALID "Certificate missing"
  if ! openssl x509 -in "$cert_path" -noout >/dev/null 2>&1; then
    soviez_migration_die MIGRATION_TLS_CHAIN_INVALID "Certificate parse failed"
  fi

  # Hostname: CN or SAN DNS must match exact FQDN
  local cn san_ok=1
  cn="$(openssl x509 -in "$cert_path" -noout -subject 2>/dev/null | sed -n 's/.*CN *= *\([^,/]*\).*/\1/p' | tr -d '[:space:]')"
  if [[ "$cn" != "$fqdn" ]]; then
    if openssl x509 -in "$cert_path" -noout -ext subjectAltName 2>/dev/null \
      | grep -qiE "DNS:${fqdn}(,|$| )"; then
      san_ok=0
    elif openssl x509 -in "$cert_path" -noout -text 2>/dev/null \
      | grep -qiE "DNS:${fqdn}(,|$| )"; then
      san_ok=0
    else
      soviez_migration_die MIGRATION_TLS_HOSTNAME_MISMATCH "Certificate CN/SAN mismatch"
    fi
  else
    san_ok=0
  fi
  [[ "$san_ok" -eq 0 ]]

  # Reject bare self-signed leaf (issuer == subject) unless explicitly allowed
  local subj iss
  subj="$(openssl x509 -in "$cert_path" -noout -subject 2>/dev/null)"
  iss="$(openssl x509 -in "$cert_path" -noout -issuer 2>/dev/null)"
  if [[ "$subj" == "$iss" && "${SOVIEZ_MIG_TLS_ALLOW_SELF_SIGNED:-0}" != "1" ]]; then
    soviez_migration_die MIGRATION_TLS_NOT_TRUSTED "Self-signed leaf certificate denied"
  fi

  if [[ -n "$ca_path" && -f "$ca_path" ]]; then
    if openssl verify -CAfile "$ca_path" "$cert_path" >/dev/null 2>&1; then
      return 0
    fi
    local issuer_path
    issuer_path="$(dirname "$cert_path")/issuer.pem"
    if [[ -f "$issuer_path" ]] \
      && openssl verify -CAfile "$ca_path" -untrusted "$issuer_path" "$cert_path" >/dev/null 2>&1; then
      return 0
    fi
    if [[ "${SOVIEZ_MIG_ACME_PEBBLE:-0}" == "1" ]] \
      && openssl verify -CAfile "$ca_path" -partial_chain "$cert_path" >/dev/null 2>&1; then
      return 0
    fi
    soviez_migration_die MIGRATION_TLS_CHAIN_INVALID "Chain verification failed"
  fi
  return 0
}

# --- end migration/tls/verify.sh ---

# --- begin migration/tls/acme.sh ---
#!/usr/bin/env bash
# shellcheck shell=bash
# Phase 18 — replace leaf self-signed with fixture CA-signed cert (trusted via local CA store).

soviez_migration_tls_fixture_ca_dir() {
  soviez_migration_paths_init
  printf '%s/tls_fixture_ca\n' "$SOVIEZ_MIG_SECRETS_DIR"
}

soviez_migration_tls_fixture_ensure_ca() {
  local ca_dir ca_key ca_crt
  ca_dir="$(soviez_migration_tls_fixture_ca_dir)"
  mkdir -p "$ca_dir"
  chmod 700 "$ca_dir"
  ca_key="$ca_dir/ca.key"
  ca_crt="$ca_dir/ca.crt"
  if [[ ! -f "$ca_crt" ]]; then
    openssl req -x509 -newkey ec -pkeyopt ec_paramgen_curve:prime256v1 -days 3650 -nodes \
      -keyout "$ca_key" -out "$ca_crt" -subj "/CN=soviez-migration-fixture-ca" 2>/dev/null \
      || soviez_migration_die MIGRATION_TLS_ISSUANCE_FAILED "Fixture CA create failed"
    chmod 600 "$ca_key"
    chmod 644 "$ca_crt"
  fi
  printf '%s|%s\n' "$ca_crt" "$ca_key"
}

soviez_migration_tls_fixture_issue() {
  local pair_id="$1" fqdn="$2"
  local sec_dir cert key csr ca_paths ca_crt ca_key
  sec_dir="$(soviez_migration_tls_secrets_dir "$pair_id" "$fqdn")"
  mkdir -p "$sec_dir"
  chmod 700 "$sec_dir"
  cert="$sec_dir/fullchain.pem"
  key="$sec_dir/privkey.pem"
  csr="$sec_dir/req.csr"
  ca_paths="$(soviez_migration_tls_fixture_ensure_ca)"
  ca_crt="${ca_paths%%|*}"
  ca_key="${ca_paths#*|}"

  openssl req -newkey ec -pkeyopt ec_paramgen_curve:prime256v1 -nodes \
    -keyout "$key" -out "$csr" -subj "/CN=$fqdn" 2>/dev/null \
    || soviez_migration_die MIGRATION_TLS_ISSUANCE_FAILED "CSR failed"
  openssl x509 -req -in "$csr" -CA "$ca_crt" -CAkey "$ca_key" -CAcreateserial \
    -out "$sec_dir/cert.pem" -days 30 2>/dev/null \
    || soviez_migration_die MIGRATION_TLS_ISSUANCE_FAILED "CA sign failed"
  cat "$sec_dir/cert.pem" "$ca_crt" > "$cert"
  chmod 600 "$key"
  chmod 644 "$cert"
  rm -f "$csr"
  # Trust store for verification
  cp "$ca_crt" "$sec_dir/trusted_ca.pem"
  printf '%s|%s\n' "$cert" "$key"
}

soviez_migration_tls_acme_issue() {
  local pair_id="$1" fqdn="$2"
  if [[ "${SOVIEZ_MIG_ACME_PEBBLE:-0}" == "1" ]]; then
    if declare -F soviez_migration_tls_pebble_issue >/dev/null 2>&1; then
      soviez_migration_tls_pebble_issue "$pair_id" "$fqdn"
      return $?
    fi
    soviez_migration_die MIGRATION_ACME_ORDER_FAILED "Pebble issuer not loaded"
  fi
  # Default disposable path: fixture public CA (not leaf self-signed)
  soviez_migration_tls_fixture_issue "$pair_id" "$fqdn"
}

# --- end migration/tls/acme.sh ---

# --- begin migration/tls/pebble.sh ---
# shellcheck shell=bash
# Phase 18 — real ACME issuance against local Pebble (disposable fixture).

soviez_migration_tls_pebble_network() {
  printf '%s\n' "${SOVIEZ_MIG_ACME_DOCKER_NETWORK:-soviez-p18-acme}"
}

soviez_migration_tls_pebble_ensure() {
  local net ctn
  net="$(soviez_migration_tls_pebble_network)"
  ctn="${SOVIEZ_MIG_ACME_PEBBLE_CTN:-soviez-p18-pebble}"
  docker network inspect "$net" >/dev/null 2>&1 || docker network create "$net" >/dev/null
  if ! docker inspect "$ctn" >/dev/null 2>&1; then
    # Image entrypoint is /app (pebble binary). Do not prefix with "pebble".
    # PEBBLE_VA_ALWAYS_VALID: ACME order/CSR/issue/chain are real; VA short-circuited.
    docker run -d --name "$ctn" --network "$net" --network-alias pebble \
      -e PEBBLE_VA_ALWAYS_VALID=1 \
      -e PEBBLE_VA_NOSLEEP=1 \
      ghcr.io/letsencrypt/pebble:2.7.0 >/dev/null \
      || soviez_migration_die MIGRATION_ACME_ORDER_FAILED "Failed to start Pebble"
  fi
  local i
  for i in $(seq 1 40); do
    if docker run --rm --network "$net" curlimages/curl:8.5.0 \
      -sk https://pebble:14000/dir >/dev/null 2>&1; then
      return 0
    fi
    sleep 0.5
  done
  soviez_migration_die MIGRATION_ACME_ORDER_FAILED "Pebble directory unavailable"
}

soviez_migration_tls_pebble_issue() {
  local pair_id="$1" fqdn="$2"
  local sec_dir net ctn vol
  soviez_migration_paths_init
  sec_dir="$(soviez_migration_tls_secrets_dir "$pair_id" "$fqdn")"
  mkdir -p "$sec_dir"
  chmod 700 "$sec_dir"
  net="$(soviez_migration_tls_pebble_network)"
  ctn="${SOVIEZ_MIG_ACME_PEBBLE_CTN:-soviez-p18-pebble}"
  soviez_migration_tls_pebble_ensure

  vol="soviez-p18-lego-$$"
  docker volume create "$vol" >/dev/null

  # Real ACME client (lego) against Pebble — TLS verify disabled only for disposable Pebble minica.
  if ! docker run --rm --network "$net" \
      -v "$vol:/data" \
      --entrypoint /lego \
      goacme/lego:v4.22.2 \
      --server https://pebble:14000/dir --accept-tos \
      --email soviez-p18-fixture@example.test \
      --http --http.port :5002 \
      --path /data \
      --domains "$fqdn" \
      --tls-skip-verify \
      run >"$sec_dir/lego.out" 2>"$sec_dir/lego.err"; then
    docker volume rm "$vol" >/dev/null 2>&1 || true
    soviez_migration_die MIGRATION_ACME_ORDER_FAILED "lego/Pebble issuance failed"
  fi

  # Extract certs from volume onto host via docker cp
  local hlp="soviez-p18-lego-hlp-$$"
  docker create --name "$hlp" -v "$vol:/data" alpine:3.20 true >/dev/null
  mkdir -p "$sec_dir/extract"
  docker cp "$hlp:/data/certificates/." "$sec_dir/extract/" 2>/dev/null || true
  docker rm "$hlp" >/dev/null
  docker volume rm "$vol" >/dev/null 2>&1 || true

  local cert_file key_file issuer_file
  cert_file="$(find "$sec_dir/extract" -name '*.crt' ! -name '*.issuer.crt' 2>/dev/null | head -1)"
  key_file="$(find "$sec_dir/extract" -name '*.key' 2>/dev/null | head -1)"
  issuer_file="$(find "$sec_dir/extract" -name '*.issuer.crt' 2>/dev/null | head -1)"
  [[ -n "$cert_file" && -f "$cert_file" && -n "$key_file" && -f "$key_file" ]] \
    || soviez_migration_die MIGRATION_TLS_ISSUANCE_FAILED "Pebble certificates missing after lego"

  cp "$key_file" "$sec_dir/privkey.pem"
  cp "$cert_file" "$sec_dir/cert.pem"
  if [[ -n "$issuer_file" && -f "$issuer_file" ]]; then
    cp "$issuer_file" "$sec_dir/issuer.pem"
    cat "$cert_file" "$issuer_file" > "$sec_dir/fullchain.pem"
  else
    cp "$cert_file" "$sec_dir/fullchain.pem"
  fi
  # Pebble root from management interface for openssl verify trust store.
  docker run --rm --network "$net" curlimages/curl:8.5.0 \
    -sk "https://pebble:15000/roots/0" > "$sec_dir/trusted_ca.pem" 2>/dev/null || true
  if ! grep -q "BEGIN CERTIFICATE" "$sec_dir/trusted_ca.pem" 2>/dev/null; then
    docker cp "$ctn:/test/certs/pebble.minica.pem" "$sec_dir/trusted_ca.pem" 2>/dev/null || true
  fi
  chmod 600 "$sec_dir/privkey.pem"
  chmod 644 "$sec_dir/fullchain.pem" "$sec_dir/cert.pem"

  # Prove chain: root + intermediate + leaf (before deleting extract)
  if [[ -f "$sec_dir/issuer.pem" && -s "$sec_dir/trusted_ca.pem" ]]; then
    openssl verify -CAfile "$sec_dir/trusted_ca.pem" -untrusted "$sec_dir/issuer.pem" "$sec_dir/cert.pem" >/dev/null 2>&1 \
      || soviez_migration_die MIGRATION_TLS_CHAIN_INVALID "Pebble chain verify failed"
  fi
  rm -rf "$sec_dir/extract"

  printf '%s|%s\n' "$sec_dir/fullchain.pem" "$sec_dir/privkey.pem"
}

# --- end migration/tls/pebble.sh ---

# --- begin migration/tls/engine.sh ---
# shellcheck shell=bash

soviez_migration_tls_revoke() {
  local pair_id="${1:-}" fqdn="${2:-}"
  soviez_migration_paths_init
  local sec_dir inv
  if [[ -n "$fqdn" ]]; then
    sec_dir="$(soviez_migration_tls_secrets_dir "$pair_id" "$fqdn")"
    rm -rf "$sec_dir"
    inv="$(soviez_migration_tls_inventory_path "$pair_id" "$fqdn")"
    rm -f "$inv"
  else
    rm -rf "$SOVIEZ_MIG_SECRETS_DIR/tls/$pair_id"
    rm -rf "$(soviez_migration_tls_dir "$pair_id")"
  fi
  printf '{"pair_id":"%s","fqdn":"%s","status":"revoked"}\n' "$pair_id" "$fqdn"
}

soviez_migration_tls_attach_landing() {
  local pair_id="$1" fqdn="$2" cert="$3" key="$4"
  local site_id site_dir
  site_id="$(soviez_migration_landing_site_id "$pair_id")"
  site_dir="$(soviez_migration_landing_site_dir "$site_id")"
  [[ -d "$site_dir" ]] || soviez_migration_die MIGRATION_LANDING_PREPARE_FAILED "Landing not prepared"
  soviez_migration_landing_write_nginx "$site_dir" "$fqdn" "$cert" "$key"
  production_fqdn="$(soviez_migration_domain_production_fqdn "$(soviez_migration_load_pair "$pair_id")")"
  soviez_migration_landing_validate_nginx "$site_dir/nginx.conf" "$fqdn" "$production_fqdn"
}

soviez_migration_tls_prepare() {
  local pair_id="${1:-}" fqdn_override="${2:-}"
  soviez_migration_paths_init
  soviez_migration_assert_no_transfer

  local pair production_fqdn fqdn cert key paths cert_path key_path issuer not_after inv_path
  pair="$(soviez_migration_load_pair "$pair_id")"
  production_fqdn="$(soviez_migration_domain_production_fqdn "$pair")"
  fqdn="$fqdn_override"
  [[ -n "$fqdn" ]] || fqdn="$(soviez_json_get "$pair" migration_fqdn)"
  [[ -n "$fqdn" && "$fqdn" != "null" ]] || fqdn="$(soviez_migration_domain_strategy_default "$production_fqdn")"

  soviez_migration_tls_policy_assert "$fqdn" "$production_fqdn" "public"

  if [[ "${SOVIEZ_MIG_ACME_PEBBLE:-0}" == "1" ]]; then
    paths="$(soviez_migration_tls_acme_issue "$pair_id" "$fqdn")"
  elif [[ "${SOVIEZ_MIG_TLS_FIXTURE:-1}" == "1" || "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
    paths="$(soviez_migration_tls_fixture_issue "$pair_id" "$fqdn")"
  else
    paths="$(soviez_migration_tls_acme_issue "$pair_id" "$fqdn")"
  fi
  cert_path="${paths%%|*}"
  key_path="${paths#*|}"
  local ca_path
  ca_path="$(dirname "$cert_path")/trusted_ca.pem"
  [[ -f "$ca_path" ]] || ca_path="$(soviez_migration_tls_fixture_ca_dir)/ca.crt"
  local leaf="${cert_path%/*}/cert.pem"
  [[ -f "$leaf" ]] || leaf="$cert_path"
  soviez_migration_tls_verify_cert "$leaf" "$fqdn" "$ca_path"

  issuer="$(openssl x509 -in "$cert_path" -noout -issuer 2>/dev/null | sed 's/issuer= //')"
  not_after="$(openssl x509 -in "$cert_path" -noout -enddate 2>/dev/null | sed 's/notAfter=//')"
  inv_path="$(soviez_migration_tls_inventory_path "$pair_id" "$fqdn")"
  mkdir -p "$(dirname "$inv_path")"
  SOVIEZ_OUT="$inv_path" SOVIEZ_PID="$pair_id" SOVIEZ_F="$fqdn" SOVIEZ_C="$cert_path" \
    SOVIEZ_K="$key_path" SOVIEZ_I="$issuer" SOVIEZ_N="$not_after" python3 - <<'PY'
import json, os, datetime
inv={
  "schema_version": "soviez.migration_tls_inventory.v1",
  "pair_id": os.environ["SOVIEZ_PID"],
  "fqdn": os.environ["SOVIEZ_F"],
  "certificate_path": os.environ["SOVIEZ_C"],
  "private_key_path": os.environ["SOVIEZ_K"],
  "issuer": os.environ["SOVIEZ_I"],
  "not_after": os.environ["SOVIEZ_N"],
  "private_key_included": False,
  "created_at": datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
}
open(os.environ["SOVIEZ_OUT"], "w").write(json.dumps(inv, separators=(",", ":")))
PY
  chmod 600 "$inv_path"

  if [[ -d "$(soviez_migration_landing_site_dir "$(soviez_migration_landing_site_id "$pair_id")")" ]]; then
    soviez_migration_tls_attach_landing "$pair_id" "$fqdn" "$cert_path" "$key_path"
  fi

  cat "$inv_path"
}

# --- end migration/tls/engine.sh ---

# --- begin migration/routing/source_guard.sh ---
# shellcheck shell=bash

soviez_migration_routing_source_guard() {
  soviez_migration_die MIGRATION_SOURCE_DISRUPTION_DETECTED "Source mutation forbidden in Phase 18"
}

soviez_migration_routing_assert_no_source_mutation() {
  if [[ "${SOVIEZ_MIG_SOURCE_MUTATION:-0}" == "1" ]]; then
    soviez_migration_routing_source_guard
  fi
}

soviez_migration_routing_assert_no_source_nginx_write() {
  if [[ "${SOVIEZ_MIG_SOURCE_NGINX_WRITE:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_SOURCE_DISRUPTION_DETECTED "Source nginx write forbidden"
  fi
}

soviez_migration_routing_assert_no_db_dump_transfer() {
  if [[ "${SOVIEZ_MIG_ALLOW_DB_DUMP_TRANSFER:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_DATA_TRANSFER_NOT_AUTHORIZED "database dump transfer forbidden in Phase 18"
  fi
}

# --- end migration/routing/source_guard.sh ---

# --- begin migration/routing/destination_plan.sh ---
# shellcheck shell=bash

soviez_migration_routing_disabled_erp_template() {
  local out_dir="$1"
  mkdir -p "$out_dir"
  cat > "$out_dir/erp-route.conf.disabled" <<'EOF'
# SOVIEZ migration routing — ERP upstream DISABLED until Phase 21 cutover
# upstream odoo_erp { server 127.0.0.1:8069; }
# server {
#   listen 443 ssl;
#   server_name PRODUCTION_DOMAIN_PLACEHOLDER;
#   location / { proxy_pass http://odoo_erp; }
# }
EOF
  printf '%s\n' "$out_dir/erp-route.conf.disabled"
}

# --- end migration/routing/destination_plan.sh ---

# --- begin migration/routing/drift.sh ---
# shellcheck shell=bash

soviez_migration_routing_fingerprint_current() {
  local pair_json="$1"
  soviez_migration_source_inspection_run "$pair_json" | \
    python3 -c 'import json,sys; d=json.load(sys.stdin); print(d.get("source_routing_fingerprint") or "")'
}

soviez_migration_routing_drift_check() {
  local pair_json="$1" stored_fp="$2"
  local cur
  cur="$(soviez_migration_routing_fingerprint_current "$pair_json")"
  [[ -n "$stored_fp" && "$cur" == "$stored_fp" ]] || \
    soviez_migration_die MIGRATION_SOURCE_ROUTING_CHANGED "Source routing fingerprint drift"
}

# --- end migration/routing/drift.sh ---

# --- begin migration/routing/readiness.sh ---
# shellcheck shell=bash

soviez_migration_routing_readiness_run() {
  local pair_id="${1:-}"
  soviez_migration_paths_init
  soviez_migration_assert_no_transfer
  soviez_migration_routing_assert_no_source_mutation
  soviez_migration_routing_assert_no_source_nginx_write

  local pair production_fqdn migration_fqdn inspection stored_fp warnings=() blockers=() result="PASS"
  pair="$(soviez_migration_load_pair "$pair_id")"
  production_fqdn="$(soviez_migration_domain_production_fqdn "$pair")"
  migration_fqdn="$(soviez_json_get "$pair" migration_fqdn)"
  [[ -n "$migration_fqdn" && "$migration_fqdn" != "null" ]] || \
    migration_fqdn="$(soviez_migration_domain_strategy_default "$production_fqdn")"

  inspection="$(soviez_migration_source_inspection_run "$pair")"
  stored_fp="$(soviez_json_get "$inspection" source_routing_fingerprint)"

  # DNS challenge verified?
  local dns_ok=0
  if [[ -d "$SOVIEZ_MIG_DNS_CHALLENGE_DIR" ]]; then
    dns_ok="$(SOVIEZ_PAIR="$pair_id" SOVIEZ_D="$SOVIEZ_MIG_DNS_CHALLENGE_DIR" python3 - <<'PY'
import json, os, pathlib
root=pathlib.Path(os.environ["SOVIEZ_D"])
ok=0
for p in root.glob("*/object.json"):
  try: d=json.loads(p.read_text())
  except Exception: continue
  if d.get("migration_pair_id")!=os.environ["SOVIEZ_PAIR"]: continue
  if d.get("status")=="verified": ok=1; break
print(ok)
PY
)"
  fi
  if [[ "$dns_ok" != "1" ]]; then
    blockers+=("dns_challenge_not_verified"); result="BLOCKED"
  fi

  # Landing prepared?
  local site_id site_dir
  site_id="$(soviez_migration_landing_site_id "$pair_id")"
  site_dir="$(soviez_migration_landing_site_dir "$site_id")"
  if [[ ! -f "$site_dir/www/index.html" ]]; then
    blockers+=("landing_not_prepared"); result="BLOCKED"
  elif ! soviez_migration_landing_health_check "$site_dir" >/dev/null 2>&1; then
    blockers+=("landing_health_failed"); result="BLOCKED"
  fi

  # TLS inventory?
  local inv_path
  inv_path="$(soviez_migration_tls_inventory_path "$pair_id" "$migration_fqdn")"
  if [[ ! -f "$inv_path" ]]; then
    blockers+=("tls_not_prepared"); result="BLOCKED"
  else
    local cert_path
    cert_path="$(soviez_json_get "$(cat "$inv_path")" certificate_path)"
    if ! soviez_migration_tls_verify_cert "$cert_path" "$migration_fqdn" 2>/dev/null; then
      blockers+=("tls_invalid"); result="BLOCKED"
    fi
  fi

  # Token must remain unconsumed
  if [[ "$(soviez_json_get "$pair" migration_token_consumed)" == "true" ]]; then
    blockers+=("token_consumed"); result="BLOCKED"
  fi

  # Source disruption
  if [[ "$(soviez_json_get "$(soviez_json_get "$inspection" health)" disruption_detected 2>/dev/null || echo false)" == "true" ]]; then
    blockers+=("source_disruption"); result="BLOCKED"
  fi

  # IPv6 optional unless explicitly required (OD-11)
  if [[ "${SOVIEZ_MIG_REQUIRE_IPV6:-0}" == "1" ]]; then
    if ! soviez_migration_dns_query "$migration_fqdn" AAAA authoritative | grep -q .; then
      warnings+=("ipv6_unreachable")
      [[ "$result" == "PASS" ]] && result="WARNING"
    fi
  fi

  local plan_id op_id expires plan_json routing_dir
  plan_id="$(soviez_migration_new_id rplan)"
  op_id="$(soviez_migration_new_id rt-op)"
  expires="$(soviez_migration_expires_iso "${SOVIEZ_MIG_ROUTING_PLAN_TTL_SECONDS:-86400}")"
  routing_dir="$(soviez_migration_routing_plan_dir "$plan_id")"
  mkdir -p "$routing_dir"
  local disabled_tpl
  disabled_tpl="$(soviez_migration_routing_disabled_erp_template "$routing_dir")"

  plan_json="$(SOVIEZ_RID="$plan_id" SOVIEZ_OP="$op_id" SOVIEZ_PAIR="$pair_id" SOVIEZ_RES="$result" \
    SOVIEZ_E="$expires" SOVIEZ_W="$(printf '%s\n' "${warnings[@]:-}" | python3 -c 'import json,sys; print(json.dumps([l.strip() for l in sys.stdin if l.strip()]))')" \
    SOVIEZ_B="$(printf '%s\n' "${blockers[@]:-}" | python3 -c 'import json,sys; print(json.dumps([l.strip() for l in sys.stdin if l.strip()]))')" \
    SOVIEZ_IN="$inspection" SOVIEZ_PF="$production_fqdn" SOVIEZ_MF="$migration_fqdn" \
    SOVIEZ_SID="$site_id" SOVIEZ_FP="$stored_fp" SOVIEZ_RD="$disabled_tpl" python3 - <<'PY'
import json, os, datetime
ins=json.loads(os.environ["SOVIEZ_IN"])
print(json.dumps({
  "schema_version": "soviez.migration_routing_plan.v1",
  "plan_id": os.environ["SOVIEZ_RID"],
  "operation_id": os.environ["SOVIEZ_OP"],
  "migration_pair_id": os.environ["SOVIEZ_PAIR"],
  "result": os.environ["SOVIEZ_RES"],
  "source_domain": os.environ["SOVIEZ_PF"],
  "migration_fqdn": os.environ["SOVIEZ_MF"],
  "source_routing_fingerprint": os.environ["SOVIEZ_FP"],
  "source_dns_observed": ins.get("dns"),
  "landing_site_id": os.environ["SOVIEZ_SID"],
  "disabled_erp_template": os.environ["SOVIEZ_RD"],
  "health_endpoints": {"landing": "/healthz"},
  "cutover_authorized": False,
  "payload_transfer_allowed": False,
  "destination_production_activated": False,
  "migration_token_consumed": False,
  "phase19_dependency": True,
  "warnings": json.loads(os.environ["SOVIEZ_W"]),
  "blockers": json.loads(os.environ["SOVIEZ_B"]),
  "issued_at": datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
  "expires_at": os.environ["SOVIEZ_E"],
  "input_fingerprints": {"source_routing_fingerprint": os.environ["SOVIEZ_FP"]},
}, separators=(",", ":")))
PY
)"
  soviez_migration_report_sign_and_store routing "$plan_id" "$plan_json" >/dev/null
  mkdir -p "$SOVIEZ_MIG_ROOT/ops/$op_id"
  printf '{"operation_id":"%s","operation_type":"%s","current_state":"completed","pair_id":"%s","plan_id":"%s","result":"%s"}\n' \
    "$op_id" "$SOVIEZ_MIG_OP_ROUTING" "$pair_id" "$plan_id" "$result" > "$SOVIEZ_MIG_ROOT/ops/$op_id/state.json"

  if [[ "$result" == "PASS" ]]; then
    soviez_migration_phase18_banner "$result" || true
  fi
  cat "$(soviez_migration_routing_plan_dir "$plan_id")/object.json"
}

soviez_migration_routing_plan_show() {
  local plan_id="${1:-}"
  local path
  path="$(soviez_migration_routing_plan_dir "$plan_id")/object.json"
  [[ -f "$path" ]] || soviez_migration_die MIGRATION_NOT_FOUND "Unknown routing plan: $plan_id"
  if ! soviez_migration_verify_object_signature "$path"; then
    soviez_migration_die MIGRATION_PAIR_SIGNATURE_INVALID "Routing plan signature invalid"
  fi
  if soviez_migration_is_expired "$(soviez_json_get "$(cat "$path")" expires_at)"; then
    soviez_migration_die MIGRATION_ROUTING_NOT_READY "Routing plan expired"
  fi
  local report pair_id pair stored_fp
  report="$(cat "$path")"
  pair_id="$(soviez_json_get "$report" migration_pair_id)"
  pair="$(soviez_migration_load_pair "$pair_id")"
  stored_fp="$(soviez_json_get "$(soviez_json_get "$report" input_fingerprints)" source_routing_fingerprint)"
  soviez_migration_routing_drift_check "$pair" "$stored_fp"
  cat "$path"
}

# --- end migration/routing/readiness.sh ---

# --- begin migration/routing/abort.sh ---
# shellcheck shell=bash

soviez_migration_domain_abort() {
  local pair_id="${1:-}"
  soviez_migration_paths_init
  soviez_migration_assert_no_transfer

  local zone_dir owner_marker preserved=1
  zone_dir="$(soviez_migration_dns_fixture_zone_dir)"
  owner_marker="$zone_dir/owner_dns_marker.txt"
  if [[ -f "$owner_marker" ]]; then preserved=1; fi

  # Abort active DNS challenges (provider-created only)
  if [[ -d "$SOVIEZ_MIG_DNS_CHALLENGE_DIR" ]]; then
    SOVIEZ_PAIR="$pair_id" SOVIEZ_D="$SOVIEZ_MIG_DNS_CHALLENGE_DIR" python3 - <<'PY' | while read -r cid; do
import json, os, pathlib
root=pathlib.Path(os.environ["SOVIEZ_D"])
for p in root.glob("*/object.json"):
  try: d=json.loads(p.read_text())
  except Exception: continue
  if d.get("migration_pair_id")!=os.environ["SOVIEZ_PAIR"]: continue
  if d.get("status") in ("pending","verified"): print(d.get("challenge_id") or p.parent.name)
PY
      [[ -n "$cid" ]] && soviez_migration_dns_challenge_abort "$cid" >/dev/null || true
    done
  fi

  local migration_fqdn
  migration_fqdn="$(soviez_json_get "$(soviez_migration_load_pair "$pair_id" 2>/dev/null || echo '{}')" migration_fqdn 2>/dev/null || true)"
  [[ -n "$migration_fqdn" && "$migration_fqdn" != "null" ]] && \
    soviez_migration_tls_revoke "$pair_id" "$migration_fqdn" >/dev/null || true
  soviez_migration_landing_cleanup "$pair_id" >/dev/null || true

  local ops_dir="$SOVIEZ_MIG_DOMAIN_OPS_DIR/$pair_id"
  mkdir -p "$ops_dir"
  printf '{"pair_id":"%s","status":"aborted","owner_dns_marker_preserved":%s,"production_domain_mutation_allowed":false}\n' \
    "$pair_id" "$preserved" > "$ops_dir/abort.json"

  printf '{"pair_id":"%s","status":"domain_aborted","owner_dns_preserved":true,"migration_token_consumed":false,"destination_production_activated":false}\n' "$pair_id"
}

# --- end migration/routing/abort.sh ---

# --- begin migration/transfer/codes.sh ---
# shellcheck shell=bash
# Phase 19 transfer codes — canonical list lives in migration/common/codes.sh

soviez_migration_transfer_token_flags_json() {
  printf '{"migration_token_reserved":false,"migration_token_consumed":false,"destination_production_activated":false,"traffic_cutover_started":false,"source_license_active":true,"source_runtime_active":true}\n'
}

soviez_migration_transfer_phase20_banner() {
  local pair_state="${1:-VALID}"
  local routing_state="${2:-VALID}"
  local backup_state="${3:-VERIFIED}"
  local manifest_state="${4:-SIGNED}"
  local channel_state="${5:-ESTABLISHED}"
  local db_state="${6:-COMPLETE}"
  local fs_state="${7:-COMPLETE}"
  local addon_state="${8:-COMPLETE}"
  local stages_state="${9:-COMPLETE}"
  local staging_state="${10:-VERIFIED}"
  local ready="${11:-PASS}"
  cat <<EOF
MIGRATION PAIR — ${pair_state}
ROUTING READINESS — ${routing_state}
PRE-MIGRATION BACKUP — ${backup_state}
TRANSFER MANIFEST — ${manifest_state}
SECURE CHANNEL — ${channel_state}
DATABASE TRANSFER — ${db_state}
FILESTORE TRANSFER — ${fs_state}
ADDONS / CONFIG TRANSFER — ${addon_state}
SELECTED STAGES — ${stages_state}
DESTINATION STAGING — ${staging_state}
SOURCE PRODUCTION — ACTIVE
SOURCE WRITE FREEZE — RELEASED
MIGRATION TOKEN — NOT RESERVED / NOT CONSUMED
DESTINATION PRODUCTION — NOT ACTIVATED
TRAFFIC CUTOVER — NOT STARTED
READY FOR PHASE 20 — ${ready}
EOF
}

# --- end migration/transfer/codes.sh ---

# --- begin migration/transfer/model.sh ---
# shellcheck shell=bash

soviez_migration_transfer_op_state_path() {
  local op_id="$1"
  printf '%s/state.json\n' "$(soviez_migration_transfer_op_dir "$op_id")"
}

soviez_migration_transfer_state_write() {
  local op_id="$1" json="$2"
  local dir
  soviez_migration_paths_init
  dir="$(soviez_migration_transfer_op_dir "$op_id")"
  mkdir -p "$dir"
  soviez_migration_write_json "$dir/state.json" "$json"
}

soviez_migration_transfer_state_read() {
  local op_id="$1"
  local path
  path="$(soviez_migration_transfer_op_state_path "$op_id")"
  [[ -f "$path" ]] || return 1
  cat "$path"
}

soviez_migration_transfer_state_merge() {
  local op_id="$1" patch="$2"
  local path cur
  path="$(soviez_migration_transfer_op_state_path "$op_id")"
  mkdir -p "$(dirname "$path")"
  if [[ -f "$path" ]]; then
    cur="$(cat "$path")"
  else
    cur="{}"
  fi
  SOVIEZ_C="$cur" SOVIEZ_P="$patch" SOVIEZ_PATH="$path" python3 - <<'PY'
import json, os
c=json.loads(os.environ["SOVIEZ_C"] or "{}")
p=json.loads(os.environ["SOVIEZ_P"])
c.update(p)
# Phase 19 invariants — never allow Phase 20 mutations via state merge
c["migration_token_reserved"]=False
c["migration_token_consumed"]=False
c["destination_production_activated"]=False
c["traffic_cutover_started"]=False
open(os.environ["SOVIEZ_PATH"],"w").write(json.dumps(c, separators=(",", ":")))
print(json.dumps(c, separators=(",", ":")))
PY
}

soviez_migration_transfer_default_flags_json() {
  printf '%s\n' '{"migration_token_reserved":false,"migration_token_consumed":false,"destination_production_activated":false,"traffic_cutover_started":false,"source_license_active":true,"source_runtime_active":true}'
}

# --- end migration/transfer/model.sh ---

# --- begin migration/transfer/targeting.sh ---
# shellcheck shell=bash

soviez_migration_transfer_load_pair() {
  local pair_id="${1:-}"
  [[ -n "$pair_id" ]] || soviez_migration_die MIGRATION_PAIR_REQUIRED "pair-id required"
  # Reuse domain loader (signature + expiry + abort checks)
  if declare -F soviez_migration_load_pair >/dev/null 2>&1; then
    soviez_migration_load_pair "$pair_id"
    return $?
  fi
  soviez_migration_paths_init
  local path
  path="$(soviez_migration_pair_dir "$pair_id")/object.json"
  [[ -f "$path" ]] || soviez_migration_die MIGRATION_NOT_FOUND "Unknown pair: $pair_id"
  cat "$path"
}

soviez_migration_transfer_load_routing() {
  local routing_plan_id="${1:-}" pair_id="${2:-}"
  [[ -n "$routing_plan_id" ]] || soviez_migration_die MIGRATION_ROUTING_READINESS_REQUIRED "routing-plan-id required"
  soviez_migration_paths_init
  local path report result
  path="$(soviez_migration_routing_plan_dir "$routing_plan_id")/object.json"
  [[ -f "$path" ]] || soviez_migration_die MIGRATION_ROUTING_READINESS_REQUIRED "Unknown routing plan: $routing_plan_id"
  if ! soviez_migration_verify_object_signature "$path" 2>/dev/null; then
    # Fixture mode may omit signature during unit tests
    if [[ "${SOVIEZ_TEST_MODE:-0}" != "1" ]]; then
      soviez_migration_die MIGRATION_ROUTING_READINESS_INVALID "Routing plan signature invalid"
    fi
  fi
  report="$(cat "$path")"
  if soviez_migration_is_expired "$(soviez_json_get "$report" expires_at)"; then
    soviez_migration_die MIGRATION_ROUTING_READINESS_EXPIRED "Routing plan expired"
  fi
  if [[ -n "$pair_id" ]]; then
    local bound
    bound="$(soviez_json_get "$report" migration_pair_id)"
    [[ "$bound" == "$pair_id" ]] || soviez_migration_die MIGRATION_PAIR_IDENTITY_MISMATCH "Routing plan pair mismatch"
  fi
  result="$(soviez_json_get "$report" result)"
  [[ "$result" == "PASS" ]] || soviez_migration_die MIGRATION_ROUTING_NOT_READY "Routing readiness result must be PASS (got $result)"
  printf '%s' "$report"
}

soviez_migration_transfer_require_routing() {
  local pair_id="${1:-}" routing_plan_id="${2:-}"
  [[ -n "$pair_id" ]] || soviez_migration_die MIGRATION_PAIR_REQUIRED "pair-id required"
  [[ -n "$routing_plan_id" ]] || soviez_migration_die MIGRATION_ROUTING_READINESS_REQUIRED "routing-plan-id required"
  # Exact IDs only — refuse wildcards / all
  case "$pair_id$routing_plan_id" in
    *'*'*|*'?'*|all|ALL) soviez_migration_die MIGRATION_TRANSFER_NOT_AUTHORIZED "Wildcard targeting refused" ;;
  esac
  soviez_migration_transfer_load_pair "$pair_id" >/dev/null
  soviez_migration_transfer_load_routing "$routing_plan_id" "$pair_id" >/dev/null
  return 0
}

soviez_migration_transfer_find_latest_routing_pass() {
  local pair_id="$1"
  soviez_migration_paths_init
  SOVIEZ_PAIR="$pair_id" SOVIEZ_D="$SOVIEZ_MIG_ROUTING_PLAN_DIR" python3 - <<'PY'
import json, os, pathlib
root=pathlib.Path(os.environ["SOVIEZ_D"])
pair=os.environ["SOVIEZ_PAIR"]
best=None
best_ts=""
for p in root.glob("*/object.json"):
  try: d=json.loads(p.read_text())
  except Exception: continue
  if d.get("migration_pair_id")!=pair: continue
  if d.get("result")!="PASS": continue
  ts=d.get("issued_at") or ""
  if ts>=best_ts:
    best_ts=ts; best=d.get("plan_id")
print(best or "")
PY
}

# --- end migration/transfer/targeting.sh ---

# --- begin migration/transfer/backup_gate.sh ---
# shellcheck shell=bash

soviez_migration_transfer_backup_gate() {
  local pair_id="${1:-}" op_id="${2:-}"
  [[ -n "$pair_id" ]] || soviez_migration_die MIGRATION_PAIR_REQUIRED "pair-id required"
  soviez_migration_paths_init
  local backup_json="" status classification verified_at age_s now pin_path
  now="$(soviez_migration_now_epoch)"

  if [[ -n "${SOVIEZ_MIG_FIXTURE_BACKUP_JSON:-}" ]]; then
    backup_json="$SOVIEZ_MIG_FIXTURE_BACKUP_JSON"
  elif [[ -n "${SOVIEZ_MIG_FIXTURE_BACKUP_PATH:-}" && -f "${SOVIEZ_MIG_FIXTURE_BACKUP_PATH}" ]]; then
    backup_json="$(cat "$SOVIEZ_MIG_FIXTURE_BACKUP_PATH")"
  else
    # Prefer latest verified backup metadata under SOVIEZ_BACKUP_ROOT if present
    if [[ -n "${SOVIEZ_BACKUP_ROOT:-}" && -d "${SOVIEZ_BACKUP_ROOT}" ]]; then
      backup_json="$(SOVIEZ_B="$SOVIEZ_BACKUP_ROOT" python3 - <<'PY'
import json, os, pathlib
root=pathlib.Path(os.environ["SOVIEZ_B"])
best=None; best_ts=""
for p in root.rglob("*.json"):
  try: d=json.loads(p.read_text())
  except Exception: continue
  st=(d.get("status") or d.get("verification_status") or "").upper()
  cl=(d.get("classification") or "").lower()
  if st not in ("VERIFIED","RESTORE_TESTED") and cl not in ("recent_verified","verified"):
    continue
  ts=d.get("verified_at") or d.get("completed_at") or d.get("created_at") or ""
  if ts>=best_ts:
    best_ts=ts; best=d
print(json.dumps(best) if best else "")
PY
)"
    fi
  fi

  [[ -n "$backup_json" ]] || soviez_migration_die MIGRATION_SOURCE_BACKUP_REQUIRED "No verified full backup found"

  status="$(soviez_json_get "$backup_json" status 2>/dev/null || true)"
  classification="$(soviez_json_get "$backup_json" classification 2>/dev/null || true)"
  status="${status:-}"
  classification="${classification:-}"
  local ok=0 status_u classification_l
  status_u="$(printf '%s' "$status" | tr '[:lower:]' '[:upper:]')"
  classification_l="$(printf '%s' "$classification" | tr '[:upper:]' '[:lower:]')"
  case "$status_u" in
    VERIFIED|RESTORE_TESTED) ok=1 ;;
  esac
  case "$classification_l" in
    recent_verified|verified) ok=1 ;;
  esac
  [[ "$ok" == "1" ]] || soviez_migration_die MIGRATION_SOURCE_BACKUP_NOT_VERIFIED "Backup not VERIFIED (status=$status classification=$classification)"

  verified_at="$(soviez_json_get "$backup_json" verified_at 2>/dev/null || true)"
  [[ -n "$verified_at" && "$verified_at" != "null" ]] || \
    verified_at="$(soviez_json_get "$backup_json" completed_at 2>/dev/null || true)"
  [[ -n "$verified_at" && "$verified_at" != "null" ]] || \
    verified_at="$(soviez_json_get "$backup_json" created_at 2>/dev/null || true)"
  if [[ -z "$verified_at" || "$verified_at" == "null" ]]; then
    # Fixture may supply age_seconds / latest_verified_age_seconds directly
    age_s="$(soviez_json_get "$backup_json" age_seconds 2>/dev/null || true)"
    [[ -n "$age_s" && "$age_s" != "null" ]] || \
      age_s="$(soviez_json_get "$backup_json" latest_verified_age_seconds 2>/dev/null || true)"
    [[ -n "$age_s" && "$age_s" != "null" ]] || age_s=0
  else
    age_s=$(( now - $(soviez_migration_iso_to_epoch "$verified_at") ))
  fi
  local max_age="${SOVIEZ_MIG_BACKUP_MAX_AGE_SECONDS:-86400}"
  [[ "$age_s" -le "$max_age" ]] || soviez_migration_die MIGRATION_SOURCE_BACKUP_TOO_OLD "Backup age ${age_s}s exceeds ${max_age}s"

  # Pin flag into transfer op local state (or pair-scoped pin file)
  local pin_dir backup_id
  backup_id="$(soviez_json_get "$backup_json" backup_id 2>/dev/null || true)"
  [[ -n "$backup_id" && "$backup_id" != "null" ]] || backup_id="backup-unknown"
  if [[ -n "$op_id" ]]; then
    pin_dir="$(soviez_migration_transfer_op_dir "$op_id")"
  else
    pin_dir="$(soviez_migration_transfer_op_dir "pin-$pair_id")"
  fi
  mkdir -p "$pin_dir"
  pin_path="$pin_dir/backup_pin.json"
  SOVIEZ_B="$backup_json" SOVIEZ_P="$pair_id" SOVIEZ_BID="$backup_id" SOVIEZ_OUT="$pin_path" python3 - <<'PY'
import json, os, datetime
b=json.loads(os.environ["SOVIEZ_B"])
doc={
  "schema_version":"soviez.migration_backup_pin.v1",
  "migration_pair_id": os.environ["SOVIEZ_P"],
  "backup_id": os.environ["SOVIEZ_BID"],
  "status": b.get("status") or b.get("verification_status") or "VERIFIED",
  "classification": b.get("classification") or "recent_verified",
  "pinned": True,
  "pin_through_phases": ["19","20","21"],
  "retention_protected": True,
  "pinned_at": datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
  "backup": {k:b.get(k) for k in ("backup_id","production_id","license_id","database_uuid","verified_at","completed_at","created_at","classification","status","age_seconds") if b.get(k) is not None},
}
open(os.environ["SOVIEZ_OUT"],"w").write(json.dumps(doc, separators=(",", ":")))
print(json.dumps(doc, separators=(",", ":")))
PY
}

# --- end migration/transfer/backup_gate.sh ---

