inv=json.loads(os.environ["SOVIEZ_I"])
secrets=list(inv.get("secrets_detected") or [])
doc={
  "schema_version":"soviez.migration_secret_inventory.v1",
  "secrets":[{"key":k,"transfer_authorized":False,"remediation":"re-enter_at_destination"} for k in secrets],
  "automatic_secret_transfer": False,
  "created_at": datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
}
open(os.environ["SOVIEZ_O"],"w").write(json.dumps(doc, separators=(",", ":")))
print(json.dumps(doc, separators=(",", ":")))
PY
}

# --- end migration/config/secret_inventory.sh ---

# --- begin migration/config/transfer.sh ---
# shellcheck shell=bash

soviez_migration_config_transfer() {
  local pair_id="$1" op_id="$2" manifest_id="$3"
  local inv sanitized out_dir
  out_dir="$(soviez_migration_transfer_op_dir "$op_id")/config"
  mkdir -p "$out_dir"
  inv="$(soviez_migration_config_inventory "$pair_id")"
  sanitized="$(soviez_migration_config_sanitize "$inv")"
  printf '%s' "$sanitized" > "$out_dir/sanitized.json"
  soviez_migration_config_secret_inventory "$inv" "$out_dir/secret_inventory.json" >/dev/null
  # Never auto-transfer secrets
  if [[ "$(soviez_json_get "$(cat "$out_dir/secret_inventory.json")" automatic_secret_transfer)" == "true" ]]; then
    soviez_migration_die MIGRATION_SECRET_TRANSFER_NOT_AUTHORIZED "Secret transfer not authorized"
  fi
  printf '{"status":"config_transferred","sanitized":true,"secrets_excluded":true}\n'
}

# --- end migration/config/transfer.sh ---

# --- begin migration/config/verify.sh ---
# shellcheck shell=bash

soviez_migration_config_verify() {
  local op_id="$1"
  local path
  path="$(soviez_migration_transfer_op_dir "$op_id")/config/sanitized.json"
  [[ -f "$path" ]] || soviez_migration_die MIGRATION_CONFIG_TRANSFER_FAILED "Sanitized config missing"
  # Ensure no obvious secrets remain
  if grep -Eiq 'password|api_key|private_key|smtp\.password' "$path"; then
    soviez_migration_die MIGRATION_SECRET_TRANSFER_NOT_AUTHORIZED "Secret-like keys found in sanitized config"
  fi
  printf '{"status":"verified"}\n'
}

