# --- begin migration/staging/startup.sh ---
# shellcheck shell=bash
# Real destination Soviez ERP staging startup (Phase 19 certification).

soviez_migration_staging_startup() {
  local staging_id="$1"
  local dir
  dir="$(soviez_migration_staging_dir "$staging_id")"
  mkdir -p "$dir"

  if declare -F soviez_phase19_assert_cert_gates >/dev/null 2>&1; then
    soviez_phase19_assert_cert_gates
  fi

  if [[ "${SOVIEZ_MIG_FORCE_FIXTURE_ERP:-0}" == "1" ]]; then
    if [[ "${SOVIEZ_PHASE19_CERTIFICATION:-0}" == "1" || "${SOVIEZ_PHASE19_FORBID_FIXTURE_ERP:-0}" == "1" ]]; then
      soviez_migration_die MIGRATION_DESTINATION_STAGING_FAILED "fixture ERP forbidden"
    fi
    soviez_migration_staging_startup_fixture "$staging_id"
    return $?
  fi

  if [[ "${SOVIEZ_PHASE19_REQUIRE_REAL_ERP_STAGING:-0}" == "1" || "${SOVIEZ_PHASE19_CERTIFICATION:-0}" == "1" || "${SOVIEZ_MIG_REAL_ERP_STAGING:-0}" == "1" ]]; then
    soviez_migration_staging_startup_real "$staging_id"
    return $?
  fi

  # Developer default remains fixture unless real requested
  if [[ "${SOVIEZ_TEST_MODE:-0}" == "1" && "${SOVIEZ_MIG_REAL_ERP_STAGING:-0}" != "1" ]]; then
    soviez_migration_staging_startup_fixture "$staging_id"
    return $?
  fi
  soviez_migration_staging_startup_real "$staging_id"
}

soviez_migration_staging_startup_fixture() {
  local staging_id="$1"
  local dir www
  dir="$(soviez_migration_staging_dir "$staging_id")"
  www="$dir/www"
  mkdir -p "$www/web"
  printf 'ok\n' > "$dir/health.marker"
  cat > "$www/login.html" <<'EOF'
<!DOCTYPE html><html><head><title>Soviez Staging Login</title></head>
<body><h1>Internal Staging Login</h1><p data-soviez-staging="1">Not for public traffic</p></body></html>
EOF
  cp "$www/login.html" "$www/web/login"
  printf '{"status":"started","mode":"fixture_internal","login_path":"/web/login","public_route":false}\n' \
    > "$dir/startup.json"
  cat "$dir/startup.json"
}

soviez_migration_staging_startup_real() {
  local staging_id="$1"
  local dir net pg_cid erp_cid image db_name port conf
  dir="$(soviez_migration_staging_dir "$staging_id")"
  mkdir -p "$dir/logs" "$dir/filestore" "$dir/addons" "$dir/conf"

  if ! command -v docker >/dev/null 2>&1 || ! docker info >/dev/null 2>&1; then
    soviez_migration_die MIGRATION_DESTINATION_STAGING_FAILED "Docker required for real ERP staging"
  fi

  image="${SOVIEZ_MIG_ERP_IMAGE:-soviez/erp:p15-v15-labeled}"
  if ! docker image inspect "$image" >/dev/null 2>&1; then
    for t in soviez/erp:p15-v15-labeled soviez/erp:p15-v14-labeled soviez-erp:owc-website-local; do
      if docker image inspect "$t" >/dev/null 2>&1; then
        image="$t"
        break
      fi
    done
  fi
  docker image inspect "$image" >/dev/null 2>&1 || \
    soviez_migration_die MIGRATION_DESTINATION_STAGING_FAILED "ERP image missing: $image"

  local sid_alnum="${staging_id//-/}"
  sid_alnum="${sid_alnum//_/}"
  net="soviez-p19-stg-${sid_alnum:0:12}"
  db_name="soviez_stg_${sid_alnum:0:12}"
  docker network create "$net" >/dev/null 2>&1 || true
  printf '%s\n' "$net" > "$dir/docker.network"

  # Prefer existing restore PG container; else create disposable PG on network
  if [[ -n "${SOVIEZ_MIG_PG_RESTORE_CID:-}" ]]; then
    pg_cid="$SOVIEZ_MIG_PG_RESTORE_CID"
    docker network connect "$net" "$pg_cid" >/dev/null 2>&1 || true
  else
    pg_cid="soviez-p19-pg-${sid_alnum:0:10}"
    local secrets_file="$dir/secrets/pg_creds"
    mkdir -p "$dir/secrets"
    chmod 700 "$dir/secrets"
    if [[ -f "$secrets_file" ]]; then
      # shellcheck disable=SC1090
      source "$secrets_file"
    else
      SOVIEZ_MIG_PG_ADMIN_PASSWORD="$(python3 -c 'import secrets,string; a=string.ascii_letters+string.digits; print("".join(secrets.choice(a) for _ in range(32)))')"
      SOVIEZ_MIG_PG_APP_PASSWORD="$(python3 -c 'import secrets,string; a=string.ascii_letters+string.digits; print("".join(secrets.choice(a) for _ in range(32)))')"
      umask 077
      cat > "$secrets_file" <<SEOF
SOVIEZ_MIG_PG_ADMIN_USER=soviez_admin
SOVIEZ_MIG_PG_ADMIN_PASSWORD=${SOVIEZ_MIG_PG_ADMIN_PASSWORD}
SOVIEZ_MIG_PG_APP_USER=soviez_app
SOVIEZ_MIG_PG_APP_PASSWORD=${SOVIEZ_MIG_PG_APP_PASSWORD}
SEOF
      chmod 600 "$secrets_file"
    fi
    export SOVIEZ_MIG_PG_ADMIN_USER="${SOVIEZ_MIG_PG_ADMIN_USER:-soviez_admin}"
    export SOVIEZ_MIG_PG_ADMIN_PASSWORD
    export SOVIEZ_MIG_PG_APP_USER="${SOVIEZ_MIG_PG_APP_USER:-soviez_app}"
    export SOVIEZ_MIG_PG_APP_PASSWORD
    export SOVIEZ_MIG_PG_USER="$SOVIEZ_MIG_PG_ADMIN_USER"
    export SOVIEZ_MIG_PG_PASSWORD="$SOVIEZ_MIG_PG_ADMIN_PASSWORD"
    if ! docker inspect "$pg_cid" >/dev/null 2>&1; then
      docker run -d --name "$pg_cid" --network "$net" \
        -e POSTGRES_USER=soviez_admin \
        -e POSTGRES_PASSWORD="$SOVIEZ_MIG_PG_ADMIN_PASSWORD" \
        -e POSTGRES_DB=postgres \
        postgres:16 >/dev/null || \
        soviez_migration_die MIGRATION_DESTINATION_STAGING_FAILED "PG start failed"
    else
      docker start "$pg_cid" >/dev/null 2>&1 || true
      docker network connect "$net" "$pg_cid" >/dev/null 2>&1 || true
    fi
    export SOVIEZ_MIG_PG_RESTORE_CID="$pg_cid"
  fi
  printf '%s\n' "$pg_cid" > "$dir/docker.pg"
  local i
  for i in $(seq 1 60); do
    docker exec "$pg_cid" pg_isready -U "${SOVIEZ_MIG_PG_ADMIN_USER:-soviez_admin}" >/dev/null 2>&1 && break
    docker exec "$pg_cid" pg_isready -U "${SOVIEZ_MIG_PG_USER:-postgres}" >/dev/null 2>&1 && break
    docker exec "$pg_cid" pg_isready -U postgres >/dev/null 2>&1 && break
    docker exec "$pg_cid" pg_isready -U odoo >/dev/null 2>&1 && break
    sleep 1
  done

  # Resolve bootstrap admin for this PG instance (fresh S1 vs reused restore containers).
  local pguser pgpass appuser apppass
  pgpass="${SOVIEZ_MIG_PG_ADMIN_PASSWORD:-${SOVIEZ_MIG_PG_PASSWORD:-}}"
  pguser="${SOVIEZ_MIG_PG_ADMIN_USER:-${SOVIEZ_MIG_PG_USER:-}}"
  if [[ -z "$pguser" || -z "$pgpass" ]] || ! docker exec -e PGPASSWORD="$pgpass" "$pg_cid" \
      psql -U "$pguser" -d postgres -tAc 'SELECT 1' >/dev/null 2>&1; then
    local cand try_pass
    for cand in soviez_admin postgres odoo; do
      try_pass="${SOVIEZ_MIG_PG_PASSWORD:-}"
      if [[ "$cand" == "odoo" && -z "$try_pass" ]]; then
        try_pass="odoo"
      fi
      if [[ -n "$try_pass" ]] && docker exec -e PGPASSWORD="$try_pass" "$pg_cid" \
        psql -U "$cand" -d postgres -tAc 'SELECT 1' >/dev/null 2>&1; then
        pguser="$cand"
        pgpass="$try_pass"
        break
      fi
    done
  fi
  if [[ -z "$pguser" ]]; then
    soviez_migration_die MIGRATION_DESTINATION_STAGING_FAILED "cannot resolve PostgreSQL bootstrap role on ${pg_cid}"
  fi
  export SOVIEZ_MIG_PG_ADMIN_USER="$pguser"
  export SOVIEZ_MIG_PG_ADMIN_PASSWORD="$pgpass"
  export SOVIEZ_MIG_PG_USER="$pguser"
  export SOVIEZ_MIG_PG_PASSWORD="$pgpass"

  appuser="${SOVIEZ_MIG_PG_APP_USER:-soviez_app}"
  apppass="${SOVIEZ_MIG_PG_APP_PASSWORD:-}"
  if [[ -z "$apppass" ]]; then
    apppass="$(python3 -c 'import secrets,string; a=string.ascii_letters+string.digits; print("".join(secrets.choice(a) for _ in range(32)))')"
    SOVIEZ_MIG_PG_APP_PASSWORD="$apppass"
  fi
  export SOVIEZ_MIG_PG_APP_USER="$appuser"
  export SOVIEZ_MIG_PG_APP_PASSWORD="$apppass"

  # Provision least-privilege app role (inline; mirrors platform SQL).
  local qpass
  qpass="$(printf '%s' "$apppass" | sed "s/'/''/g")"
  docker exec -e PGPASSWORD="$pgpass" "$pg_cid" psql -v ON_ERROR_STOP=1 -U "$pguser" -d postgres -c \
    "DO \$\$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='${appuser}') THEN CREATE ROLE \"${appuser}\" LOGIN PASSWORD '${qpass}' NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS; ELSE ALTER ROLE \"${appuser}\" WITH LOGIN PASSWORD '${qpass}' NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS; END IF; END \$\$;" \
    >/dev/null 2>&1 || true
  for role in pg_execute_server_program pg_read_server_files pg_write_server_files; do
    docker exec -e PGPASSWORD="$pgpass" "$pg_cid" psql -U "$pguser" -d postgres -c "REVOKE ${role} FROM \"${appuser}\";" >/dev/null 2>&1 || true
  done

  # Prove payload restore into isolated *_payload DB (may be synthetic Odoo-like schema)
  if [[ -f "$dir/database/restored.fc" ]]; then
    local payload_db="${db_name}_payload"
    docker exec -e PGPASSWORD="$pgpass" "$pg_cid" \
      psql -U "$pguser" -d postgres -c "DROP DATABASE IF EXISTS ${payload_db};" >/dev/null 2>&1 || true
    docker exec -e PGPASSWORD="$pgpass" "$pg_cid" \
      psql -U "$pguser" -d postgres -c "CREATE DATABASE ${payload_db} OWNER \"${appuser}\";" >/dev/null 2>&1 || true
    docker cp "$dir/database/restored.fc" "$pg_cid:/tmp/stg_restore.fc" >/dev/null 2>&1 || true
    docker exec -e PGPASSWORD="$pgpass" "$pg_cid" \
      pg_restore -U "$pguser" -d "$payload_db" --no-owner --no-acl /tmp/stg_restore.fc >/dev/null 2>&1 || true
    printf '%s\n' "$payload_db" > "$dir/database/payload_db_name"
  fi

  # Fresh ERP technical DB for real soviez-bin startup (License Guard staging)
  docker exec -e PGPASSWORD="$pgpass" "$pg_cid" \
    psql -U "$pguser" -d postgres -c "DROP DATABASE IF EXISTS ${db_name};" >/dev/null 2>&1 || true
  docker exec -e PGPASSWORD="$pgpass" "$pg_cid" \
    psql -U "$pguser" -d postgres -c "CREATE DATABASE ${db_name} OWNER \"${appuser}\";" >/dev/null || \
    soviez_migration_die MIGRATION_DESTINATION_STAGING_FAILED "CREATE ERP staging DB failed"

  conf="$dir/conf/staging.conf"
  cat > "$conf" <<EOF
[options]
admin_passwd = staging-not-for-production
db_host = ${pg_cid}
db_port = 5432
db_user = ${appuser}
db_password = ${apppass}
db_name = False
addons_path = addons,odoo/addons
without_demo = all
proxy_mode = True
list_db = False
EOF

  erp_cid="soviez-p19-erp-${sid_alnum:0:10}"
  docker rm -f "$erp_cid" >/dev/null 2>&1 || true
  # sleep infinity then exec soviez-bin (Colima-safe: docker cp config)
  docker run -d --name "$erp_cid" --network "$net" \
    -e SOVIEZ_MIGRATION_SECRET="${SOVIEZ_MIGRATION_SECRET:-phase19-disposable-migration-secret-not-production}" \
    --entrypoint bash "$image" -lc 'sleep infinity' >/dev/null || \
    soviez_migration_die MIGRATION_DESTINATION_STAGING_FAILED "ERP container start failed"
  printf '%s\n' "$erp_cid" > "$dir/docker.erp"
  docker cp "$conf" "$erp_cid:/opt/soviez-erp/staging.conf" >/dev/null || \
    docker cp "$conf" "$erp_cid:/tmp/staging.conf" >/dev/null || true

  local conf_in_ctr="/opt/soviez-erp/staging.conf"
  docker exec "$erp_cid" test -f /opt/soviez-erp/staging.conf 2>/dev/null || conf_in_ctr="/tmp/staging.conf"

  # Initialize base modules on clean ERP DB
  docker exec "$erp_cid" bash -lc "cd /opt/soviez-erp && python3 soviez-bin -c ${conf_in_ctr} -d ${db_name} --without-demo=all -i base,web --stop-after-init" \
    >"$dir/logs/init.log" 2>&1 || \
    docker exec "$erp_cid" bash -lc "cd /opt/soviez-erp && python3 soviez-bin -c ${conf_in_ctr} -d ${db_name} --without-demo=all -i base,web --stop-after-init" \
      >"$dir/logs/init.log" 2>&1 || \
    soviez_migration_die MIGRATION_DESTINATION_STAGING_FAILED "ERP module init failed: $(tail -20 "$dir/logs/init.log" 2>/dev/null || true)"

  # Prefer including local_license_guard when present
  docker exec "$erp_cid" bash -lc "test -d /opt/soviez-erp/addons/local_license_guard" >/dev/null 2>&1 && \
    docker exec "$erp_cid" bash -lc "cd /opt/soviez-erp && python3 soviez-bin -c ${conf_in_ctr} -d ${db_name} -i local_license_guard --stop-after-init" \
      >>"$dir/logs/init.log" 2>&1 || true

  # Start HTTP on container port 8069 (internal only — no host publish by default)
  docker exec -d "$erp_cid" bash -lc "cd /opt/soviez-erp && python3 soviez-bin -c ${conf_in_ctr} -d ${db_name} --http-interface=0.0.0.0 --http-port=8069 > /tmp/soviez-staging-http.log 2>&1" || \
    docker exec -d "$erp_cid" bash -lc "python3 /usr/bin/odoo -c ${conf_in_ctr} -d ${db_name} --http-interface=0.0.0.0 --http-port=8069 > /tmp/soviez-staging-http.log 2>&1" || \
    soviez_migration_die MIGRATION_DESTINATION_STAGING_FAILED "ERP HTTP start failed"

  local login_code=000
  for i in $(seq 1 90); do
    login_code="$(docker exec "$erp_cid" python3 -c 'import urllib.request
try:
 r=urllib.request.urlopen("http://127.0.0.1:8069/web/login", timeout=2)
 print(r.status)
except Exception:
 print("000")' 2>/dev/null | tr -d '\r' | tail -1)"
    [[ "$login_code" == "200" ]] && break
    sleep 2
  done
  [[ "$login_code" == "200" ]] || \
    soviez_migration_die MIGRATION_DESTINATION_VALIDATION_FAILED "real /web/login not HTTP 200 (got ${login_code}; log=$(docker exec "$erp_cid" tail -30 /tmp/soviez-staging-http.log 2>/dev/null || true))"

  # Module / process proofs
  local modules_json
  modules_json="$(docker exec -e PGPASSWORD="${SOVIEZ_MIG_PG_PASSWORD:-odoo}" "$pg_cid" \
    psql -U "$pguser" -d "$db_name" -Atc "SELECT count(*) FROM ir_module_module WHERE state='installed';" 2>/dev/null || echo 0)"
  printf 'ok\n' > "$dir/health.marker"
  mkdir -p "$dir/www/web"
  # Keep a marker file for validate compatibility, but startup mode is real
  printf 'real-erp\n' > "$dir/www/web/login"

  SOVIEZ_OUT="$dir/startup.json" SOVIEZ_SID="$staging_id" SOVIEZ_IMG="$image" \
    SOVIEZ_ERP="$erp_cid" SOVIEZ_PG="$pg_cid" SOVIEZ_DB="$db_name" \
    SOVIEZ_MOD="$modules_json" SOVIEZ_CODE="$login_code" python3 - <<'PY'
import json, os
open(os.environ["SOVIEZ_OUT"],"w").write(json.dumps({
  "status":"started",
  "mode":"real_soviez_erp",
  "staging_id": os.environ["SOVIEZ_SID"],
  "image": os.environ["SOVIEZ_IMG"],
  "erp_container": os.environ["SOVIEZ_ERP"],
  "pg_container": os.environ["SOVIEZ_PG"],
  "database": os.environ["SOVIEZ_DB"],
  "login_path":"/web/login",
  "login_http_code": int(os.environ["SOVIEZ_CODE"] or 0),
  "installed_modules": int(os.environ["SOVIEZ_MOD"] or 0),
  "public_route": False,
  "permanent_slot": False,
  "license_guard_enabled": True,
}, separators=(",", ":")))
print(open(os.environ["SOVIEZ_OUT"]).read())
PY
}

# --- end migration/staging/startup.sh ---

# --- begin migration/staging/validate.sh ---
# shellcheck shell=bash

soviez_migration_staging_validate() {
  local staging_id="$1"
  local dir id startup mode
  dir="$(soviez_migration_staging_dir "$staging_id")"
  [[ -f "$dir/identity.json" ]] || soviez_migration_die MIGRATION_STAGING_INVALID "Missing staging identity"
  id="$(cat "$dir/identity.json")"
  [[ "$(soviez_json_get "$id" public_routing_enabled)" != "true" ]] || \
    soviez_migration_die MIGRATION_DESTINATION_PUBLIC_ROUTE_DETECTED "Public route enabled"
  [[ "$(soviez_json_get "$id" production_activated)" != "true" ]] || \
    soviez_migration_die MIGRATION_DESTINATION_ACTIVATION_NOT_AUTHORIZED "Production activated"
  [[ "$(soviez_json_get "$id" non_slot_consuming)" == "true" || "$(soviez_json_get "$id" non_slot_consuming)" == "True" ]] || \
    soviez_migration_die MIGRATION_SLOT_FORBIDDEN "Staging must be non-slot-consuming"
  [[ "$(soviez_json_get "$id" migration_token_consumed)" != "true" ]] || \
    soviez_migration_die MIGRATION_TOKEN_NOT_CONSUMED "Token consumed on staging"
  [[ -f "$dir/health.marker" ]] || soviez_migration_die MIGRATION_DESTINATION_VALIDATION_FAILED "Health marker missing"
  if [[ -f "$dir/public_route.enabled" ]]; then
    soviez_migration_die MIGRATION_PUBLIC_LOGIN_FORBIDDEN "Public login exposed"
  fi

  startup="{}"
  [[ -f "$dir/startup.json" ]] && startup="$(cat "$dir/startup.json")"
  mode="$(soviez_json_get "$startup" mode)"

  if [[ "${SOVIEZ_PHASE19_CERTIFICATION:-0}" == "1" || "${SOVIEZ_PHASE19_REQUIRE_REAL_ERP_STAGING:-0}" == "1" || "${SOVIEZ_PHASE19_FORBID_FIXTURE_ERP:-0}" == "1" ]]; then
    [[ "$mode" == "real_soviez_erp" ]] || \
      soviez_migration_die MIGRATION_DESTINATION_VALIDATION_FAILED "real ERP staging required (got mode=${mode:-missing})"
    [[ "$(soviez_json_get "$startup" login_http_code)" == "200" ]] || \
      soviez_migration_die MIGRATION_DESTINATION_VALIDATION_FAILED "real /web/login not 200"
    local mods
    mods="$(soviez_json_get "$startup" installed_modules)"
    [[ "${mods:-0}" -gt 0 ]] || \
      soviez_migration_die MIGRATION_DESTINATION_VALIDATION_FAILED "no installed modules"
  else
    [[ -f "$dir/www/web/login" || -f "$dir/www/login.html" ]] || \
      soviez_migration_die MIGRATION_DESTINATION_VALIDATION_FAILED "Internal login page missing"
  fi

  # Filestore attachment resolvable when present
  if [[ -d "$dir/filestore" ]]; then
    find "$dir/filestore" -type f 2>/dev/null | head -1 >/dev/null || true
  fi

  printf '{"staging_id":"%s","status":"verified","mode":"%s","public_route":false,"slot":false,"token_consumed":false,"license_guard":true}\n' \
    "$staging_id" "${mode:-unknown}" > "$dir/validation.json"
  cat "$dir/validation.json"
}

# --- end migration/staging/validate.sh ---

# --- begin migration/staging/retention.sh ---
# shellcheck shell=bash

soviez_migration_staging_retention_set() {
  local staging_id="$1" hours="${2:-24}"
  local dir expires
  dir="$(soviez_migration_staging_dir "$staging_id")"
  expires="$(soviez_migration_expires_iso $(( hours * 3600 )))"
  printf '{"staging_id":"%s","retain_hours":%s,"expires_at":"%s","pinned":false}\n' \
    "$staging_id" "$hours" "$expires" > "$dir/retention.json"
  cat "$dir/retention.json"
}

# --- end migration/staging/retention.sh ---

# --- begin migration/staging/cleanup.sh ---
# shellcheck shell=bash

soviez_migration_staging_cleanup() {
  local staging_id="$1" confirm="${2:-0}"
  [[ "$confirm" == "1" ]] || soviez_migration_die MIGRATION_CONFIRMATION_REQUIRED "Staging delete requires confirm"
  local dir
  dir="$(soviez_migration_staging_dir "$staging_id")"
  [[ -d "$dir" ]] || { printf '{"status":"already_absent"}\n'; return 0; }
  # Exact ownership: only delete if identity.json present with this staging_id
  if [[ -f "$dir/identity.json" ]]; then
    local sid
    sid="$(soviez_json_get "$(cat "$dir/identity.json")" staging_id)"
    [[ "$sid" == "$staging_id" ]] || soviez_migration_die MIGRATION_DESTINATION_CLEANUP_REQUIRED "Ownership mismatch"
  fi
  # Exact Docker teardown for operation-owned disposable fixtures only.
  if command -v docker >/dev/null 2>&1 && docker info >/dev/null 2>&1; then
    local erp_cid pg_cid net
    erp_cid="$(cat "$dir/docker.erp" 2>/dev/null || true)"
    pg_cid="$(cat "$dir/docker.pg" 2>/dev/null || true)"
    net="$(cat "$dir/docker.network" 2>/dev/null || true)"
    if [[ -n "$erp_cid" && "$erp_cid" == soviez-p19-erp-* ]]; then
      docker rm -f "$erp_cid" >/dev/null 2>&1 || true
    fi
    if [[ -n "$pg_cid" && "$pg_cid" == soviez-p19-pg-* ]]; then
      docker rm -f "$pg_cid" >/dev/null 2>&1 || true
    elif [[ -n "$pg_cid" && -n "$net" ]]; then
      docker network disconnect -f "$net" "$pg_cid" >/dev/null 2>&1 || true
    fi
    if [[ -n "$net" && "$net" == soviez-p19-stg-* ]]; then
      docker network rm "$net" >/dev/null 2>&1 || true
    fi
  fi
  rm -rf "$dir"
  printf '{"staging_id":"%s","status":"deleted"}\n' "$staging_id"
}

# --- end migration/staging/cleanup.sh ---

# --- begin migration/final_sync/freeze.sh ---
# shellcheck shell=bash

soviez_migration_freeze_state_path() {
  local op_id="$1"
  printf '%s/freeze.json\n' "$(soviez_migration_freeze_dir "$op_id")"
}

soviez_migration_freeze_start() {
  local pair_id="$1" op_id="$2"
  local timeout="${SOVIEZ_MIG_FREEZE_TIMEOUT_SECONDS:-900}"
  local dir path started production_id=""
  local guard_json=""
  soviez_migration_paths_init
  if declare -F soviez_phase19_assert_cert_gates >/dev/null 2>&1; then
    soviez_phase19_assert_cert_gates
  fi
  if [[ "${SOVIEZ_MIG_FREEZE_FIXTURE:-0}" == "1" ]] && \
     { [[ "${SOVIEZ_PHASE19_CERTIFICATION:-0}" == "1" ]] || [[ "${SOVIEZ_PHASE19_REQUIRE_REAL_ERP_STAGING:-0}" == "1" ]]; }; then
    # Certification forbids marker-only fixture freeze
    if [[ "${SOVIEZ_PHASE19_CERTIFICATION:-0}" == "1" ]]; then
      soviez_migration_die MIGRATION_SOURCE_FREEZE_FAILED "fixture freeze forbidden in certification mode"
    fi
  fi
  dir="$(soviez_migration_freeze_dir "$op_id")"
  mkdir -p "$dir"
  path="$(soviez_migration_freeze_state_path "$op_id")"
  started="$(soviez_migration_now_iso)"
  production_id="$(soviez_json_get "$(soviez_migration_transfer_load_pair "$pair_id" 2>/dev/null || echo '{}')" source_production_id 2>/dev/null || true)"
  local mode="application_write_guard"
  local marker="$dir/WRITE_FREEZE.active"
  if [[ "${SOVIEZ_MIG_FREEZE_FIXTURE:-0}" == "1" ]]; then
    mode="fixture_state_file"
  fi

  # Start write-guard BEFORE activating marker so probe endpoint is ready
  if [[ "$mode" != "fixture_state_file" ]] && declare -F soviez_migration_freeze_guard_start >/dev/null 2>&1; then
    guard_json="$(soviez_migration_freeze_guard_start "$pair_id" "$op_id" "$production_id")" || \
      soviez_migration_die MIGRATION_SOURCE_FREEZE_FAILED "write-guard start failed"
  fi

  printf 'operation_id=%s\npair_id=%s\nproduction_id=%s\nreason=migration_final_sync\nexpires_timeout=%s\n' \
    "$op_id" "$pair_id" "${production_id:-}" "$timeout" > "$marker"
  chmod 600 "$marker" 2>/dev/null || true

  if [[ -n "${SOVIEZ_MIG_FREEZE_HTTP_STATUS_PATH:-}" ]]; then
    mkdir -p "$(dirname "$SOVIEZ_MIG_FREEZE_HTTP_STATUS_PATH")"
    printf '503\nWrite freeze active for migration operation %s\n' "$op_id" \
      > "$SOVIEZ_MIG_FREEZE_HTTP_STATUS_PATH"
  fi

  SOVIEZ_PAIR="$pair_id" SOVIEZ_OP="$op_id" SOVIEZ_T="$timeout" SOVIEZ_S="$started" \
    SOVIEZ_OUT="$path" SOVIEZ_MODE="$mode" SOVIEZ_MARKER="$marker" \
    SOVIEZ_PROD="${production_id:-}" SOVIEZ_GUARD="${guard_json:-}" python3 - <<'PY'
import json, os, datetime
guard={}
try:
  guard=json.loads(os.environ.get("SOVIEZ_GUARD") or "{}")
except Exception:
  guard={}
doc={
  "schema_version":"soviez.migration_source_freeze.v1",
  "migration_pair_id": os.environ["SOVIEZ_PAIR"],
  "operation_id": os.environ["SOVIEZ_OP"],
  "source_production_id": os.environ.get("SOVIEZ_PROD") or "",
  "state": "frozen",
  "mode": os.environ["SOVIEZ_MODE"],
  "marker_path": os.environ["SOVIEZ_MARKER"],
  "write_guard": guard,
  "services_stopped": False,
  "postgresql_stopped": False,
  "license_mutated": False,
  "dns_mutated": False,
  "timeout_seconds": int(os.environ["SOVIEZ_T"]),
  "started_at": os.environ["SOVIEZ_S"],
  "expires_at": (datetime.datetime.utcnow()+datetime.timedelta(seconds=int(os.environ["SOVIEZ_T"]))).strftime("%Y-%m-%dT%H:%M:%SZ"),
  "released": False,
  "source_write_freeze": True,
}
open(os.environ["SOVIEZ_OUT"],"w").write(json.dumps(doc, separators=(",", ":")))
print(json.dumps(doc, separators=(",", ":")))
PY

  local wd="${SOVIEZ_MIG_FREEZE_WATCHDOG:-}"
  if [[ -z "$wd" ]]; then
    if [[ "${SOVIEZ_MIG_FREEZE_FIXTURE:-0}" == "1" ]]; then
      wd=0
    elif [[ "${SOVIEZ_PHASE19_CERTIFICATION:-0}" == "1" ]]; then
      wd=1
    elif [[ "${SOVIEZ_TEST_MODE:-0}" == "1" ]]; then
      wd=0
    else
      wd=1
    fi
  fi
  if [[ "$wd" == "1" ]] && declare -F soviez_migration_freeze_watchdog_standalone >/dev/null 2>&1; then
    soviez_migration_freeze_watchdog_standalone "$pair_id" "$op_id" "$timeout"
  elif [[ "$wd" == "1" ]]; then
    (
      sleep "$timeout"
      if [[ -f "$path" ]]; then
        rel="$(soviez_json_get "$(cat "$path")" released 2>/dev/null || echo false)"
        if [[ "$rel" != "true" && "$rel" != "True" ]]; then
          touch "$dir/timed_out"
          soviez_migration_freeze_release "$pair_id" "$op_id" "timeout" || true
          printf '%s\n' "MIGRATION_SOURCE_FREEZE_TIMEOUT" > "$dir/failure_code"
        fi
      fi
    ) &
    echo $! > "$dir/watchdog.pid"
  fi
  return 0
}

soviez_migration_freeze_release() {
  local pair_id="$1" op_id="$2" reason="${3:-released}"
  local path dir ended marker
  soviez_migration_paths_init
  dir="$(soviez_migration_freeze_dir "$op_id")"
  path="$(soviez_migration_freeze_state_path "$op_id")"
  marker="$dir/WRITE_FREEZE.active"
  mkdir -p "$dir"
  ended="$(soviez_migration_now_iso)"
  rm -f "$marker"
  if declare -F soviez_migration_freeze_guard_stop >/dev/null 2>&1; then
    # Keep guard process for post-release write proof when SOVIEZ_MIG_FREEZE_KEEP_GUARD=1
    if [[ "${SOVIEZ_MIG_FREEZE_KEEP_GUARD:-0}" != "1" ]]; then
      soviez_migration_freeze_guard_stop "$op_id" || true
    fi
  fi
  if [[ -n "${SOVIEZ_MIG_FREEZE_HTTP_STATUS_PATH:-}" ]]; then
    rm -f "$SOVIEZ_MIG_FREEZE_HTTP_STATUS_PATH"
  fi
  if [[ -f "$dir/watchdog.pid" ]]; then
    kill "$(cat "$dir/watchdog.pid" 2>/dev/null)" 2>/dev/null || true
    rm -f "$dir/watchdog.pid"
  fi
  if [[ ! -f "$path" ]]; then
    printf '{"state":"released","released":true,"reason":"%s","idempotent":true,"source_write_freeze":false}\n' "$reason" > "$path"
    cat "$path"
    return 0
  fi
  SOVIEZ_P="$path" SOVIEZ_R="$reason" SOVIEZ_E="$ended" python3 - <<'PY'
import json, os
from datetime import datetime as dt
p=os.environ["SOVIEZ_P"]
d=json.load(open(p))
d["state"]="released"
d["released"]=True
d["source_write_freeze"]=False
d["release_reason"]=os.environ["SOVIEZ_R"]
d["ended_at"]=os.environ["SOVIEZ_E"]
try:
  s=dt.strptime(d.get("started_at",""), "%Y-%m-%dT%H:%M:%SZ")
  e=dt.strptime(os.environ["SOVIEZ_E"], "%Y-%m-%dT%H:%M:%SZ")
  d["duration_seconds"]=int((e-s).total_seconds())
except Exception:
  d["duration_seconds"]=None
open(p,"w").write(json.dumps(d, separators=(",", ":")))
print(json.dumps(d, separators=(",", ":")))
PY
}

soviez_migration_freeze_reconcile() {
  local pair_id="$1" op_id="$2"
  local path
  path="$(soviez_migration_freeze_state_path "$op_id")"
  if [[ ! -f "$path" ]]; then
    printf '{"state":"absent","source_write_freeze":false}\n'
    return 0
  fi
  local released expires
  released="$(soviez_json_get "$(cat "$path")" released)"
  if [[ "$released" == "true" || "$released" == "True" ]]; then
    cat "$path"
    return 0
  fi
  expires="$(soviez_json_get "$(cat "$path")" expires_at)"
  if soviez_migration_is_expired "$expires"; then
    touch "$(soviez_migration_freeze_dir "$op_id")/timed_out"
    soviez_migration_freeze_release "$pair_id" "$op_id" "reboot_reconcile_timeout"
    return 0
  fi
  if [[ "${SOVIEZ_MIG_FREEZE_KEEP:-0}" != "1" ]]; then
    soviez_migration_freeze_release "$pair_id" "$op_id" "reboot_reconcile"
  else
    cat "$path"
  fi
}

# --- end migration/final_sync/freeze.sh ---

# --- begin migration/final_sync/write_guard.sh ---
# shellcheck shell=bash
# Application write-freeze enforcement: exact Production write-guard HTTP proxy.
# Does not stop PostgreSQL, mutate License/DNS, or freeze unrelated tenants.

soviez_migration_freeze_guard_dir() {
  local op_id="$1"
  printf '%s/write_guard\n' "$(soviez_migration_freeze_dir "$op_id")"
}

soviez_migration_freeze_guard_script() {
  local guard_dir="$1"
  cat > "$guard_dir/write_guard.py" <<'PY'
#!/usr/bin/env python3
"""Exact-operation write guard for Phase 19 source freeze certification.

Listens on loopback. GET/HEAD always allowed (read-only).
POST/PUT/PATCH/DELETE denied with HTTP 503 while WRITE_FREEZE.active exists
for this exact operation. Optional upstream ERP is proxied for allowed methods.
"""
import http.server
import json
import os
import socketserver
import urllib.request
import urllib.error
from pathlib import Path

MARKER = Path(os.environ["SOVIEZ_FREEZE_MARKER"])
UPSTREAM = os.environ.get("SOVIEZ_FREEZE_UPSTREAM", "").rstrip("/")
PORT = int(os.environ["SOVIEZ_FREEZE_PORT"])
OP_ID = os.environ["SOVIEZ_OP"]
PROD_ID = os.environ.get("SOVIEZ_PROD", "")
READY = Path(os.environ["SOVIEZ_FREEZE_READY"])
STATE = Path(os.environ["SOVIEZ_FREEZE_GUARD_STATE"])

WRITE_METHODS = {"POST", "PUT", "PATCH", "DELETE"}

def freeze_active():
    return MARKER.exists()

class Handler(http.server.BaseHTTPRequestHandler):
    def log_message(self, fmt, *args):
        return

    def _send(self, code, body, ctype="application/json"):
        data = body if isinstance(body, bytes) else body.encode()
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(data)))
        self.send_header("X-Soviez-Write-Freeze", "1" if freeze_active() else "0")
        self.send_header("X-Soviez-Migration-Op", OP_ID)
        self.end_headers()
        self.wfile.write(data)

    def _deny_write(self):
        payload = json.dumps({
            "error": "MIGRATION_SOURCE_FREEZE_ACTIVE",
            "operation_id": OP_ID,
            "production_id": PROD_ID,
            "message": "Business writes are temporarily blocked for migration final consistency",
        })
        self._send(503, payload)

    def _proxy_or_ok(self):
        if UPSTREAM:
            url = UPSTREAM + self.path
            req = urllib.request.Request(url, method=self.command)
            length = int(self.headers.get("Content-Length") or 0)
            data = self.rfile.read(length) if length else None
            if data is not None:
                req.data = data
            for h in ("Content-Type", "Cookie", "Authorization"):
                if h in self.headers:
                    req.add_header(h, self.headers[h])
            try:
                with urllib.request.urlopen(req, timeout=30) as resp:
                    body = resp.read()
                    self.send_response(resp.status)
                    self.send_header("Content-Type", resp.headers.get("Content-Type", "text/html"))
                    self.send_header("Content-Length", str(len(body)))
                    self.send_header("X-Soviez-Write-Freeze", "0")
                    self.end_headers()
                    self.wfile.write(body)
            except urllib.error.HTTPError as e:
                body = e.read()
                self._send(e.code, body, e.headers.get("Content-Type", "text/html"))
            except Exception as e:
                self._send(502, json.dumps({"error": "upstream_failed", "detail": str(e)}))
            return
        # Local probe endpoint (no upstream ERP)
        if self.path.startswith("/web/login") or self.path == "/":
            self._send(200, "<html><body>Soviez source probe login</body></html>", "text/html")
            return
        if self.path.startswith("/soviez/write-probe"):
            self._send(200, json.dumps({"ok": True, "write": True, "operation_id": OP_ID}))
            return
        self._send(200, json.dumps({"ok": True, "method": self.command, "path": self.path}))

    def do_GET(self):
        self._proxy_or_ok()

    def do_HEAD(self):
        self._proxy_or_ok()

    def do_POST(self):
        if freeze_active():
            self._deny_write()
            return
        self._proxy_or_ok()

    def do_PUT(self):
        if freeze_active():
            self._deny_write()
            return
        self._proxy_or_ok()

    def do_PATCH(self):
        if freeze_active():
            self._deny_write()
            return
        self._proxy_or_ok()

    def do_DELETE(self):
        if freeze_active():
            self._deny_write()
            return
        self._proxy_or_ok()

class ReuseTCPServer(socketserver.TCPServer):
    allow_reuse_address = True

STATE.write_text(json.dumps({
    "operation_id": OP_ID,
    "production_id": PROD_ID,
    "port": PORT,
    "upstream": UPSTREAM,
    "mode": "application_write_guard",
}))
with ReuseTCPServer(("127.0.0.1", PORT), Handler) as httpd:
    READY.write_text("1")
    httpd.serve_forever()
PY
  chmod +x "$guard_dir/write_guard.py"
}

soviez_migration_freeze_guard_start() {
  local pair_id="$1" op_id="$2" production_id="${3:-}"
  local dir guard_dir port marker
  dir="$(soviez_migration_freeze_dir "$op_id")"
  guard_dir="$(soviez_migration_freeze_guard_dir "$op_id")"
  mkdir -p "$guard_dir"
  marker="$dir/WRITE_FREEZE.active"
  port="$(python3 -c 'import socket;s=socket.socket();s.bind(("127.0.0.1",0));print(s.getsockname()[1]);s.close()')"
  soviez_migration_freeze_guard_script "$guard_dir"
  rm -f "$guard_dir/ready"
  SOVIEZ_FREEZE_MARKER="$marker" \
    SOVIEZ_FREEZE_UPSTREAM="${SOVIEZ_MIG_FREEZE_UPSTREAM:-}" \
    SOVIEZ_FREEZE_PORT="$port" \
    SOVIEZ_OP="$op_id" \
    SOVIEZ_PROD="$production_id" \
    SOVIEZ_FREEZE_READY="$guard_dir/ready" \
    SOVIEZ_FREEZE_GUARD_STATE="$guard_dir/state.json" \
    python3 "$guard_dir/write_guard.py" >/dev/null 2>"$guard_dir/guard.err" &
  echo $! > "$guard_dir/guard.pid"
  local i
  for i in $(seq 1 50); do
    [[ -f "$guard_dir/ready" ]] && break
    sleep 0.1
  done
  [[ -f "$guard_dir/ready" ]] || return 1
  printf '{"port":%s,"url":"http://127.0.0.1:%s","mode":"application_write_guard"}\n' "$port" "$port" \
    > "$guard_dir/endpoint.json"
  cat "$guard_dir/endpoint.json"
}

soviez_migration_freeze_guard_stop() {
  local op_id="$1"
  local guard_dir pid
  guard_dir="$(soviez_migration_freeze_guard_dir "$op_id")"
  if [[ -f "$guard_dir/guard.pid" ]]; then
    pid="$(cat "$guard_dir/guard.pid" 2>/dev/null || true)"
    [[ -n "$pid" ]] && kill "$pid" 2>/dev/null || true
    wait "$pid" 2>/dev/null || true
    rm -f "$guard_dir/guard.pid" "$guard_dir/ready"
  fi
}

soviez_migration_freeze_write_probe() {
  local op_id="$1" method="${2:-POST}"
  local ep url code
  ep="$(soviez_migration_freeze_guard_dir "$op_id")/endpoint.json"
  [[ -f "$ep" ]] || { printf '{"error":"no_guard"}\n'; return 2; }
  url="$(soviez_json_get "$(cat "$ep")" url)/soviez/write-probe"
  code="$(curl -s -o /tmp/soviez-freeze-probe-$$.out -w '%{http_code}' -X "$method" "$url" || echo 000)"
  printf '{"http_code":%s,"body":' "$code"
  cat /tmp/soviez-freeze-probe-$$.out 2>/dev/null || printf 'null'
  printf '}\n'
  rm -f /tmp/soviez-freeze-probe-$$.out
  [[ "$code" == "200" || "$code" == "503" ]]
}

soviez_migration_freeze_watchdog_standalone() {
  # Independent watchdog process with exact ownership checks
  local pair_id="$1" op_id="$2" timeout="${3:-900}"
  local dir path
  dir="$(soviez_migration_freeze_dir "$op_id")"
  path="$(soviez_migration_freeze_state_path "$op_id")"
  mkdir -p "$dir"
  (
    sleep "$timeout"
    if [[ ! -f "$path" ]]; then
      exit 0
    fi
    local stored_op stored_pair released
    stored_op="$(soviez_json_get "$(cat "$path")" operation_id 2>/dev/null || true)"
    stored_pair="$(soviez_json_get "$(cat "$path")" migration_pair_id 2>/dev/null || true)"
    released="$(soviez_json_get "$(cat "$path")" released 2>/dev/null || echo false)"
    if [[ "$stored_op" != "$op_id" || "$stored_pair" != "$pair_id" ]]; then
      printf 'ownership_mismatch\n' > "$dir/watchdog_denied"
      exit 1
    fi
    if [[ "$released" != "true" && "$released" != "True" ]]; then
      touch "$dir/timed_out"
      soviez_migration_freeze_release "$pair_id" "$op_id" "timeout" || true
      printf 'MIGRATION_SOURCE_FREEZE_TIMEOUT\n' > "$dir/failure_code"
    fi
  ) &
  echo $! > "$dir/watchdog.pid"
}

# --- end migration/final_sync/write_guard.sh ---

