soviez_migration_final_sync_database() {
  local pair_id="$1" op_id="$2" manifest_id="$3" staging_id="$4"
  soviez_migration_database_dump "$pair_id" "$op_id" >/dev/null
  soviez_migration_database_verify "$op_id" >/dev/null
  soviez_migration_database_transfer "$pair_id" "$op_id" "$manifest_id" >/dev/null
  soviez_migration_database_restore "$pair_id" "$op_id" "$staging_id"
}

# --- end migration/final_sync/database.sh ---

# --- begin migration/final_sync/filestore.sh ---
# shellcheck shell=bash

soviez_migration_final_sync_filestore() {
  local pair_id="$1" op_id="$2" manifest_id="$3" staging_id="$4"
  soviez_migration_filestore_delta "$pair_id" "$op_id" "$manifest_id" >/dev/null
  soviez_migration_filestore_assemble "$op_id" "$staging_id" >/dev/null
  soviez_migration_filestore_reconcile "$op_id" "$staging_id"
}

# --- end migration/final_sync/filestore.sh ---

# --- begin migration/final_sync/release.sh ---
# shellcheck shell=bash

soviez_migration_final_sync_release() {
  local pair_id="$1" op_id="$2"
  soviez_migration_freeze_release "$pair_id" "$op_id" "final_sync_release"
}

# --- end migration/final_sync/release.sh ---

# --- begin migration/final_sync/recovery.sh ---
# shellcheck shell=bash

soviez_migration_final_sync_recovery() {
  local pair_id="$1" op_id="$2"
  soviez_migration_freeze_reconcile "$pair_id" "$op_id"
  soviez_migration_transfer_state_merge "$op_id" '{"checkpoint":"final_sync_recovered","source_write_freeze":false}' 
}

# --- end migration/final_sync/recovery.sh ---

# --- begin migration/transfer/engine.sh ---
# shellcheck shell=bash

soviez_migration_transfer_plan_run() {
  local pair_id="${1:-}" routing_plan_id="${2:-}"
  local profile="${SOVIEZ_CLI_MIG_PROFILE:-${SOVIEZ_MIG_RESOURCE_PROFILE:-balanced}}"
  [[ -n "$pair_id" ]] || soviez_migration_die MIGRATION_PAIR_REQUIRED "pair-id required"
  soviez_migration_paths_init
  soviez_migration_assert_no_cutover_or_token
  if [[ -z "$routing_plan_id" ]]; then
    routing_plan_id="${SOVIEZ_CLI_MIG_ROUTING_PLAN_ID:-}"
  fi
  if [[ -z "$routing_plan_id" ]]; then
    routing_plan_id="$(soviez_migration_transfer_find_latest_routing_pass "$pair_id")"
  fi
  [[ -n "$routing_plan_id" ]] || soviez_migration_die MIGRATION_ROUTING_READINESS_REQUIRED "routing-plan-id required"
  soviez_migration_transfer_require_routing "$pair_id" "$routing_plan_id"
  local pin
  pin="$(soviez_migration_transfer_backup_gate "$pair_id" "")"
  local plan
  plan="$(soviez_migration_transfer_plan_create "$pair_id" "$routing_plan_id" "$pin" "$profile")"
  local op_id plan_id
  op_id="$(soviez_json_get "$plan" operation_id)"
  plan_id="$(soviez_json_get "$plan" transfer_plan_id)"
  soviez_migration_transfer_state_write "$op_id" "$(SOVIEZ_OP="$op_id" SOVIEZ_PAIR="$pair_id" SOVIEZ_PID="$plan_id" SOVIEZ_RID="$routing_plan_id" python3 - <<'PY'
import json, os
print(json.dumps({
  "operation_id": os.environ["SOVIEZ_OP"],
  "operation_type": "migration_transfer_plan",
  "current_state": "completed",
  "migration_pair_id": os.environ["SOVIEZ_PAIR"],
  "transfer_plan_id": os.environ["SOVIEZ_PID"],
  "routing_plan_id": os.environ["SOVIEZ_RID"],
  "migration_token_reserved": False,
  "migration_token_consumed": False,
  "destination_production_activated": False,
  "traffic_cutover_started": False,
}, separators=(",", ":")))
PY
)"
  # Also pin backup under this op
  soviez_migration_transfer_backup_gate "$pair_id" "$op_id" >/dev/null
  printf '%s\n' "$plan"
}

soviez_migration_presync_run() {
  local pair_id="${1:-}" plan_id="${2:-}"
  [[ -n "$pair_id" ]] || soviez_migration_die MIGRATION_PAIR_REQUIRED "pair-id required"
  soviez_migration_paths_init
  soviez_migration_assert_phase19_transfer_allowed "$pair_id" "$SOVIEZ_MIG_OP_PAYLOAD_PRESYNC"
  local plan plan_json op_id manifest
  if [[ -n "$plan_id" ]]; then
    plan_json="$(soviez_migration_transfer_plan_show "$plan_id")"
  else
    plan_json="$(soviez_migration_transfer_plan_run "$pair_id")"
    plan_id="$(soviez_json_get "$plan_json" transfer_plan_id)"
  fi
  op_id="$(soviez_migration_new_id presync)"
  soviez_migration_assert_phase19_transfer_allowed "$pair_id" "$SOVIEZ_MIG_OP_PAYLOAD_PRESYNC"
  manifest="$(soviez_migration_transfer_manifest_create "$plan_json" "$op_id")"
  local manifest_id
  manifest_id="$(soviez_json_get "$manifest" manifest_id)"
  soviez_migration_channel_init "$pair_id" "$op_id" "$manifest_id" >/dev/null
  soviez_migration_chunk_registry_init "$op_id" "$manifest_id"
  # Filestore / addons / config pre-sync (source remains active — no freeze)
  soviez_migration_filestore_presync "$pair_id" "$op_id" "$manifest_id" >/dev/null || true
  soviez_migration_addons_transfer "$pair_id" "$op_id" "$manifest_id" >/dev/null || true
  soviez_migration_config_transfer "$pair_id" "$op_id" "$manifest_id" >/dev/null || true
  soviez_migration_transfer_state_write "$op_id" "$(SOVIEZ_OP="$op_id" SOVIEZ_PAIR="$pair_id" SOVIEZ_PID="$plan_id" SOVIEZ_MID="$manifest_id" python3 - <<'PY'
import json, os
print(json.dumps({
  "operation_id": os.environ["SOVIEZ_OP"],
  "operation_type": "migration_payload_presync",
  "current_state": "completed",
  "migration_pair_id": os.environ["SOVIEZ_PAIR"],
  "transfer_plan_id": os.environ["SOVIEZ_PID"],
  "manifest_id": os.environ["SOVIEZ_MID"],
  "source_write_freeze": False,
  "migration_token_reserved": False,
  "migration_token_consumed": False,
  "destination_production_activated": False,
  "traffic_cutover_started": False,
}, separators=(",", ":")))
PY
)"
  cat "$(soviez_migration_transfer_op_dir "$op_id")/state.json"
}

soviez_migration_presync_status() {
  local op_id="${1:-}"
  soviez_migration_transfer_status "$op_id"
}

soviez_migration_transfer_start() {
  local pair_id="${1:-}" routing_plan_id="${2:-}"
  local confirm="${SOVIEZ_CLI_CONFIRM:-0}"
  [[ "${SOVIEZ_CLI_YES:-0}" == "1" ]] && confirm=1
  [[ -n "$pair_id" ]] || soviez_migration_die MIGRATION_PAIR_REQUIRED "pair-id required"
  soviez_migration_paths_init
  if declare -F soviez_phase19_assert_cert_gates >/dev/null 2>&1; then
    soviez_phase19_assert_cert_gates
  fi
  soviez_migration_assert_no_cutover_or_token

  if [[ -z "$routing_plan_id" ]]; then
    routing_plan_id="${SOVIEZ_CLI_MIG_ROUTING_PLAN_ID:-}"
  fi
  if [[ -z "$routing_plan_id" ]]; then
    routing_plan_id="$(soviez_migration_transfer_find_latest_routing_pass "$pair_id")"
  fi
  [[ -n "$routing_plan_id" ]] || soviez_migration_die MIGRATION_ROUTING_READINESS_REQUIRED "routing-plan-id required"

  soviez_migration_assert_phase19_transfer_allowed "$pair_id" "$SOVIEZ_MIG_OP_FINAL_SYNC"
  soviez_migration_transfer_require_routing "$pair_id" "$routing_plan_id"

  local op_id profile pin plan plan_id manifest manifest_id staging_id ready stages_state
  op_id="$(soviez_migration_new_id xfer)"
  profile="${SOVIEZ_CLI_MIG_PROFILE:-${SOVIEZ_MIG_RESOURCE_PROFILE:-balanced}}"
  pin="$(soviez_migration_transfer_backup_gate "$pair_id" "$op_id")"
  plan="$(soviez_migration_transfer_plan_create "$pair_id" "$routing_plan_id" "$pin" "$profile")"
  plan_id="$(soviez_json_get "$plan" transfer_plan_id)"
  manifest="$(soviez_migration_transfer_manifest_create "$plan" "$op_id")"
  manifest_id="$(soviez_json_get "$manifest" manifest_id)"

  soviez_migration_transfer_state_write "$op_id" "$(SOVIEZ_OP="$op_id" SOVIEZ_PAIR="$pair_id" SOVIEZ_PID="$plan_id" SOVIEZ_MID="$manifest_id" SOVIEZ_RID="$routing_plan_id" python3 - <<'PY'
import json, os
print(json.dumps({
  "operation_id": os.environ["SOVIEZ_OP"],
  "operation_type": "migration_final_sync",
  "current_state": "establishing_secure_channel",
  "migration_pair_id": os.environ["SOVIEZ_PAIR"],
  "transfer_plan_id": os.environ["SOVIEZ_PID"],
  "manifest_id": os.environ["SOVIEZ_MID"],
  "routing_plan_id": os.environ["SOVIEZ_RID"],
  "migration_token_reserved": False,
  "migration_token_consumed": False,
  "destination_production_activated": False,
  "traffic_cutover_started": False,
  "source_runtime_active": True,
  "source_license_active": True,
}, separators=(",", ":")))
PY
)"

  soviez_migration_channel_init "$pair_id" "$op_id" "$manifest_id" >/dev/null
  if declare -F soviez_phase19_assert_channel_real >/dev/null 2>&1; then
    soviez_phase19_assert_channel_real "$op_id"
  fi
  soviez_migration_chunk_registry_init "$op_id" "$manifest_id"
  soviez_migration_transfer_state_merge "$op_id" '{"current_state":"presyncing_filestore"}' >/dev/null
  soviez_migration_filestore_presync "$pair_id" "$op_id" "$manifest_id" >/dev/null || true
  soviez_migration_addons_transfer "$pair_id" "$op_id" "$manifest_id" >/dev/null || true
  soviez_migration_config_transfer "$pair_id" "$op_id" "$manifest_id" >/dev/null || true

  # Staging identity early
  staging_id="$(soviez_migration_staging_identity_create "$pair_id" "$op_id" "$manifest_id")"
  soviez_migration_transfer_state_merge "$op_id" "{\"destination_staging_id\":\"$staging_id\"}" >/dev/null

  # Final freeze — requires confirmation unless fixture/test
  if [[ "$confirm" != "1" && "${SOVIEZ_MIG_FREEZE_FIXTURE:-0}" != "1" && "${SOVIEZ_TEST_MODE:-0}" != "1" ]]; then
    soviez_migration_die MIGRATION_CONFIRMATION_REQUIRED "Final write freeze requires --confirm"
  fi

  soviez_migration_transfer_state_merge "$op_id" '{"current_state":"freezing_source_writes"}' >/dev/null
  if ! soviez_migration_freeze_start "$pair_id" "$op_id" >/dev/null; then
    soviez_migration_freeze_release "$pair_id" "$op_id" "freeze_failed" >/dev/null || true
    soviez_migration_die MIGRATION_SOURCE_FREEZE_FAILED "Source write freeze failed"
  fi

  local freeze_rc=0
  (
    set -e
    soviez_migration_transfer_state_merge "$op_id" '{"current_state":"creating_final_database_snapshot"}' >/dev/null
    soviez_migration_database_dump "$pair_id" "$op_id" >/dev/null
    soviez_migration_database_transfer "$pair_id" "$op_id" "$manifest_id" >/dev/null
    soviez_migration_filestore_delta "$pair_id" "$op_id" "$manifest_id" >/dev/null
    soviez_migration_database_restore "$pair_id" "$op_id" "$staging_id" >/dev/null
    soviez_migration_filestore_assemble "$op_id" "$staging_id" >/dev/null
  ) || freeze_rc=$?

  # Always release freeze ASAP
  soviez_migration_freeze_release "$pair_id" "$op_id" "final_pass_complete" >/dev/null || true

  if [[ "$freeze_rc" -ne 0 ]]; then
    # Check timeout marker
    if [[ -f "$(soviez_migration_freeze_dir "$op_id")/timed_out" ]]; then
      soviez_migration_die MIGRATION_SOURCE_FREEZE_TIMEOUT "Freeze timed out; source released"
    fi
    soviez_migration_die MIGRATION_TRANSFER_RECOVERY_REQUIRED "Final sync failed after freeze release"
  fi

  stages_state="COMPLETE"
  if ! soviez_migration_stages_transfer "$pair_id" "$op_id" "$manifest_id" "$staging_id" >/dev/null; then
    stages_state="WARNING"
  fi

  soviez_migration_staging_neutralize "$staging_id" >/dev/null
  soviez_migration_staging_startup "$staging_id" >/dev/null
  soviez_migration_staging_validate "$staging_id" >/dev/null

  ready="$(soviez_migration_phase20_readiness_report "$op_id" "$stages_state")"
  local ready_result
  ready_result="$(soviez_json_get "$ready" result)"

  soviez_migration_transfer_state_merge "$op_id" "$(SOVIEZ_R="$ready_result" SOVIEZ_S="$staging_id" python3 - <<'PY'
import json, os
print(json.dumps({
  "current_state": "completed",
  "checkpoint": "phase20_readiness",
  "destination_staging_id": os.environ["SOVIEZ_S"],
  "ready_for_20": os.environ["SOVIEZ_R"],
  "source_write_freeze": False,
  "source_runtime_active": True,
  "source_license_active": True,
  "migration_token_reserved": False,
  "migration_token_consumed": False,
  "destination_production_activated": False,
  "traffic_cutover_started": False,
}, separators=(",", ":")))
PY
)" >/dev/null

  soviez_migration_transfer_phase20_banner \
    "VALID" "VALID" "VERIFIED" "SIGNED" "ESTABLISHED" \
    "COMPLETE" "COMPLETE" "COMPLETE" "$stages_state" "VERIFIED" "$ready_result" >&2 || true

  cat "$(soviez_migration_transfer_op_dir "$op_id")/state.json"
}

soviez_migration_transfer_status() {
  local op_id="${1:-}"
  [[ -n "$op_id" ]] || soviez_migration_die MIGRATION_NOT_FOUND "operation-id required"
  soviez_migration_paths_init
  local st
  st="$(soviez_migration_transfer_state_read "$op_id")" || \
    soviez_migration_die MIGRATION_NOT_FOUND "Unknown transfer operation: $op_id"
  printf '%s\n' "$st"
}

soviez_migration_transfer_pause() {
  local op_id="${1:-}"
  soviez_migration_paths_init
  # Release freeze if active
  local pair_id
  pair_id="$(soviez_json_get "$(soviez_migration_transfer_state_read "$op_id")" migration_pair_id)"
  soviez_migration_freeze_release "$pair_id" "$op_id" "paused" >/dev/null 2>&1 || true
  soviez_migration_transfer_state_merge "$op_id" '{"current_state":"paused","source_write_freeze":false}' 
}

soviez_migration_transfer_resume() {
  local op_id="${1:-}"
  local st pair_id routing_plan_id
  st="$(soviez_migration_transfer_state_read "$op_id")" || \
    soviez_migration_die MIGRATION_RESUME_REQUIRED "Unknown operation"
  pair_id="$(soviez_json_get "$st" migration_pair_id)"
  routing_plan_id="$(soviez_json_get "$st" routing_plan_id)"
  # Revalidate
  soviez_migration_transfer_require_routing "$pair_id" "$routing_plan_id"
  soviez_migration_transfer_backup_gate "$pair_id" "$op_id" >/dev/null
  local mid
  mid="$(soviez_json_get "$st" manifest_id)"
  [[ -n "$mid" && "$mid" != "null" ]] && soviez_migration_transfer_manifest_verify "$mid" >/dev/null
  soviez_migration_transfer_resume_from_registry "$op_id" >/dev/null
  soviez_migration_transfer_state_merge "$op_id" '{"current_state":"running","checkpoint":"resumed"}'
}

soviez_migration_transfer_cancel() {
  local op_id="${1:-}"
  local st pair_id
  st="$(soviez_migration_transfer_state_read "$op_id")" || \
    soviez_migration_die MIGRATION_NOT_FOUND "Unknown operation"
  pair_id="$(soviez_json_get "$st" migration_pair_id)"
  soviez_migration_freeze_release "$pair_id" "$op_id" "canceled" >/dev/null 2>&1 || true
  soviez_migration_transfer_state_merge "$op_id" '{"current_state":"canceled","source_write_freeze":false,"migration_token_reserved":false,"migration_token_consumed":false,"destination_production_activated":false,"traffic_cutover_started":false}'
}

soviez_migration_transfer_abort() {
  # Always release freeze + shut down transfer channel; preserve staging by default.
  local op_id="${1:-}"
  local st pair_id
  [[ -n "$op_id" ]] || soviez_migration_die MIGRATION_NOT_FOUND "operation-id required"
  soviez_migration_paths_init
  st="$(soviez_migration_transfer_state_read "$op_id" 2>/dev/null || echo '{}')"
  pair_id="$(soviez_json_get "$st" migration_pair_id 2>/dev/null || true)"
  [[ -n "$pair_id" && "$pair_id" != "null" ]] || pair_id="${SOVIEZ_CLI_MIG_PAIR_ID:-}"
  if [[ -n "$pair_id" && "$pair_id" != "null" ]]; then
    soviez_migration_freeze_release "$pair_id" "$op_id" "aborted" >/dev/null 2>&1 || true
  fi
  if declare -F soviez_migration_channel_shutdown >/dev/null 2>&1; then
    soviez_migration_channel_shutdown "$op_id" >/dev/null 2>&1 || true
  fi
  # Revoke channel credentials by removing channel meta (exact)
  local ch_dir
  ch_dir="$(soviez_migration_transfer_channel_dir "$op_id")"
  rm -f "$ch_dir/meta/channel.json" 2>/dev/null || true
  soviez_migration_transfer_state_merge "$op_id" '{"current_state":"aborted","source_write_freeze":false,"source_runtime_active":true,"source_license_active":true,"migration_token_reserved":false,"migration_token_consumed":false,"destination_production_activated":false,"traffic_cutover_started":false,"abort_preserved_staging":true}'
}

soviez_migration_transfer_recover() {
  local op_id="${1:-}"
  local st pair_id
  st="$(soviez_migration_transfer_state_read "$op_id")" || \
    soviez_migration_die MIGRATION_TRANSFER_RECOVERY_REQUIRED "Unknown operation"
  pair_id="$(soviez_json_get "$st" migration_pair_id)"
  soviez_migration_freeze_reconcile "$pair_id" "$op_id" >/dev/null || true
  if [[ "$(soviez_json_get "$st" current_state)" == "paused" ]]; then
    soviez_migration_transfer_resume "$op_id"
    return $?
  fi
  soviez_migration_transfer_state_merge "$op_id" '{"current_state":"recovery_required","checkpoint":"reconciled"}'
}

soviez_migration_destination_verify() {
  local op_id="${1:-}"
  local st staging_id
  st="$(soviez_migration_transfer_state_read "$op_id")" || \
    soviez_migration_die MIGRATION_NOT_FOUND "Unknown operation"
  staging_id="$(soviez_json_get "$st" destination_staging_id)"
  [[ -n "$staging_id" && "$staging_id" != "null" ]] || \
    soviez_migration_die MIGRATION_STAGING_INVALID "No staging identity on operation"
  soviez_migration_staging_validate "$staging_id"
}

soviez_migration_phase20_readiness_report() {
  local op_id="$1" stages_state="${2:-COMPLETE}"
  local st result="PASS" warnings="[]" blockers="[]"
  st="$(soviez_migration_transfer_state_read "$op_id" 2>/dev/null || echo '{}')"
  if [[ "$stages_state" == "WARNING" ]]; then
    result="WARNING"
    warnings='["optional_stage_failed"]'
  elif [[ "$stages_state" == "BLOCKED" ]]; then
    result="BLOCKED"
    blockers='["mandatory_stage_failed"]'
  fi
  # Token must remain false
  SOVIEZ_OP="$op_id" SOVIEZ_R="$result" SOVIEZ_W="$warnings" SOVIEZ_B="$blockers" SOVIEZ_ST="$st" python3 - <<'PY'
import json, os, datetime
st=json.loads(os.environ["SOVIEZ_ST"] or "{}")
doc={
  "schema_version":"soviez.migration_ready_for_20.v1",
  "operation_id": os.environ["SOVIEZ_OP"],
  "result": os.environ["SOVIEZ_R"],
  "warnings": json.loads(os.environ["SOVIEZ_W"]),
  "blockers": json.loads(os.environ["SOVIEZ_B"]),
  "migration_token_reserved": False,
  "migration_token_consumed": False,
  "destination_production_activated": False,
  "traffic_cutover_started": False,
  "source_runtime_active": True,
  "source_license_active": True,
  "source_write_freeze": False,
  "transfer_plan_id": st.get("transfer_plan_id"),
  "manifest_id": st.get("manifest_id"),
  "destination_staging_id": st.get("destination_staging_id"),
  "issued_at": datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
}
print(json.dumps(doc, separators=(",", ":")))
PY
}

# --- end migration/transfer/engine.sh ---

# --- begin migration/authorization/codes.sh ---
# shellcheck shell=bash
# Phase 20 authorization codes + scoped gates

SOVIEZ_MIG_OP_AUTH_PLAN=migration_authorization_plan
SOVIEZ_MIG_OP_AUTH_COMMIT=migration_authorization_commit
SOVIEZ_MIG_OP_DEST_ACTIVATION=migration_destination_activation
SOVIEZ_MIG_OP_SOURCE_GRACE=migration_source_grace_apply
SOVIEZ_MIG_OP_STAGE_REBIND=migration_stage_rebind
SOVIEZ_MIG_OP_P21_READINESS=migration_phase21_readiness
SOVIEZ_MIG_OP_AUTH_RECOVER=migration_authorization_recover
SOVIEZ_MIG_OP_PRE_CUTOVER_REVERSAL=migration_pre_cutover_reversal

SOVIEZ_MIG_P20_AUTH_TTL_SECONDS="${SOVIEZ_MIG_P20_AUTH_TTL_SECONDS:-1800}"
SOVIEZ_MIG_P21_READINESS_TTL_SECONDS="${SOVIEZ_MIG_P21_READINESS_TTL_SECONDS:-86400}"

SOVIEZ_MIGRATION_CODES+=(
  MIGRATION_PHASE19_READINESS_REQUIRED
  MIGRATION_PHASE19_READINESS_INVALID
  MIGRATION_PHASE19_DRIFT_DETECTED
  MIGRATION_TOKEN_REQUIRED
  MIGRATION_TOKEN_NOT_ELIGIBLE
  MIGRATION_TOKEN_EXPIRED
  MIGRATION_TOKEN_REVOKED
  MIGRATION_TOKEN_ALREADY_CONSUMED
  MIGRATION_TOKEN_QUANTITY_INSUFFICIENT
  MIGRATION_TOKEN_ACCOUNT_MISMATCH
  MIGRATION_TOKEN_LICENSE_MISMATCH
  MIGRATION_TOKEN_IDEMPOTENCY_CONFLICT
  MIGRATION_TOKEN_LEDGER_INCONSISTENT
  MIGRATION_TOKEN_CONSUMED_EXACTLY_ONCE
  MIGRATION_AUTHORIZATION_REQUIRED
  MIGRATION_AUTHORIZATION_INVALID
  MIGRATION_AUTHORIZATION_EXPIRED
  MIGRATION_AUTHORIZATION_REPLAY_DENIED
  MIGRATION_AUTHORIZATION_COMMIT_UNKNOWN
  MIGRATION_AUTHORIZATION_ALREADY_COMMITTED
  MIGRATION_LICENSE_LOCK_FAILED
  MIGRATION_LICENSE_BINDING_MISMATCH
  MIGRATION_SOURCE_BINDING_INVALID
  MIGRATION_DESTINATION_BINDING_INVALID
  MIGRATION_DUPLICATE_PRODUCTION_BINDING
  MIGRATION_DUPLICATE_SLOT_DETECTED
  MIGRATION_SOURCE_GRACE_APPLY_FAILED
  MIGRATION_SOURCE_GRACE_INVALID
  MIGRATION_DESTINATION_ACTIVATION_FAILED
  MIGRATION_LICENSE_GUARD_DENIED
  MIGRATION_STAGE_REBIND_FAILED
  MIGRATION_STAGE_REBIND_PARTIAL
  MIGRATION_SPLIT_BRAIN_DETECTED
  MIGRATION_LOCAL_APPLY_PENDING
  MIGRATION_COMPENSATION_REQUIRED
  MIGRATION_REVERSAL_NOT_AUTHORIZED
  MIGRATION_REVERSAL_SAFETY_CHECK_FAILED
  MIGRATION_PHASE21_NOT_READY
  MIGRATION_SOURCE_PURGE_NOT_AUTHORIZED
)

soviez_migration_assert_no_cutover_dns_purge() {
  # Phase 21 canonical cutover engine is the ONLY authorized path past this gate.
  # SOVIEZ_MIG_ALLOW_CUTOVER alone (env-flag bypass) remains permanently forbidden.
  if [[ "${SOVIEZ_MIG_ALLOW_CUTOVER:-0}" == "1" ]]; then
    if [[ "${SOVIEZ_MIG_P21_CANONICAL_CUTOVER:-0}" != "1" ]]; then
      soviez_migration_die MIGRATION_CUTOVER_NOT_AUTHORIZED "Production cutover / DNS mutation not authorized in Phase 20 (use canonical Phase 21 cutover engine)"
    fi
  elif [[ "${SOVIEZ_MIG_DNS_CUTOVER:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_CUTOVER_NOT_AUTHORIZED "Production cutover / DNS mutation not authorized in Phase 20"
  fi
  if [[ "${SOVIEZ_MIG_SOURCE_PURGE:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_SOURCE_PURGE_NOT_AUTHORIZED "Source purge not authorized"
  fi
  if [[ "${SOVIEZ_MIG_SAAS_PAYLOAD_RELAY:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_DATA_EGRESS_DENIED "SaaS payload relay forbidden"
  fi
  return 0
}

soviez_migration_assert_phase20_authorization_allowed() {
  local op_type="${1:-}"
  case "$op_type" in
    migration_authorization_plan|migration_authorization_commit|migration_destination_activation|migration_source_grace_apply|migration_stage_rebind|migration_phase21_readiness|migration_authorization_recover|migration_pre_cutover_reversal)
      ;;
    *)
      soviez_migration_die MIGRATION_AUTHORIZATION_REQUIRED "Unauthorized Phase 20 op: ${op_type:-missing}"
      ;;
  esac
  soviez_migration_assert_no_cutover_dns_purge
  # Still forbid disconnected generic burn
  if [[ "${SOVIEZ_MIG_ALLOW_TOKEN_CONSUME:-0}" == "1" && "${SOVIEZ_MIG_P20_CANONICAL_COMMIT:-0}" != "1" ]]; then
    soviez_migration_die MIGRATION_TOKEN_NOT_ELIGIBLE "Token consume only via canonical commit_migration_authorization"
  fi
  return 0
}

# --- end migration/authorization/codes.sh ---

# --- begin migration/authorization/model.sh ---
# shellcheck shell=bash

soviez_migration_p20_ledger_bin() {
  local root="${SOVIEZ_SH_ROOT:-}"
  printf '%s\n' "$root/services/migration-authorization-ledger/ledger.py"
}

soviez_migration_p20_ledger() {
  local cmd="$1"; shift
  local bin
  bin="$(soviez_migration_p20_ledger_bin)"
  [[ -f "$bin" ]] || soviez_migration_die MIGRATION_AUTHORIZATION_REQUIRED "ledger.py missing"
  export SOVIEZ_MIG_P20_LEDGER_PATH="${SOVIEZ_MIG_P20_LEDGER_PATH:-$SOVIEZ_MIG_ROOT/p20_ledger.sqlite}"
  python3 "$bin" "$cmd" "$@"
}

soviez_migration_p20_auth_dir() {
  local id="$1"
  printf '%s\n' "$SOVIEZ_MIG_ROOT/authorization/$id"
}

soviez_migration_p20_paths_init() {
  soviez_migration_paths_init
  mkdir -p "$SOVIEZ_MIG_ROOT/authorization" "$SOVIEZ_MIG_ROOT/activation" \
    "$SOVIEZ_MIG_ROOT/grace" "$SOVIEZ_MIG_ROOT/phase21_readiness" \
    "$SOVIEZ_MIG_ROOT/offline_packages" "$SOVIEZ_MIG_ROOT/ops"
}

# --- end migration/authorization/model.sh ---

# --- begin migration/authorization/readiness.sh ---
# shellcheck shell=bash

soviez_migration_p20_revalidate_phase19() {
  local pair_id="$1"
  local pair_dir staging_id ready freeze_path
  soviez_migration_p20_paths_init
  pair_dir="$(soviez_migration_pair_dir "$pair_id")"
  [[ -f "$pair_dir/object.json" ]] || soviez_migration_die MIGRATION_PAIR_REQUIRED "pair missing"
  # freeze must be released
  if [[ -d "$SOVIEZ_MIG_ROOT/ops" ]]; then
    while IFS= read -r -d '' f; do
      if [[ -f "$f" ]]; then
        local rel
        rel="$(soviez_json_get "$(cat "$f")" released 2>/dev/null || echo true)"
        local active
        active="$(soviez_json_get "$(cat "$f")" active 2>/dev/null || echo false)"
        if [[ "$active" == "true" || "$active" == "True" ]] && [[ "$rel" != "true" && "$rel" != "True" ]]; then
          soviez_migration_die MIGRATION_PHASE19_DRIFT_DETECTED "source write freeze still active"
        fi
      fi
    done < <(find "$SOVIEZ_MIG_ROOT" -name 'WRITE_FREEZE.json' -print0 2>/dev/null || true)
  fi
  # Find latest transfer op with ready_for_20
  local op_state found=0 ready_val staging
  while IFS= read -r sf; do
    [[ -f "$sf" ]] || continue
    ready_val="$(soviez_json_get "$(cat "$sf")" ready_for_20 2>/dev/null || true)"
    staging="$(soviez_json_get "$(cat "$sf")" destination_staging_id 2>/dev/null || true)"
    local pid
    pid="$(soviez_json_get "$(cat "$sf")" migration_pair_id 2>/dev/null || true)"
    if [[ "$pid" == "$pair_id" && -n "$ready_val" ]]; then
      found=1
      if [[ "$ready_val" == "BLOCKED" ]]; then
        soviez_migration_die MIGRATION_PHASE19_READINESS_INVALID "ready_for_20=BLOCKED"
      fi
      if [[ "${SOVIEZ_MIG_P20_INJECT_DRIFT:-}" == "fingerprint" ]]; then
        soviez_migration_die MIGRATION_PHASE19_DRIFT_DETECTED "injected fingerprint drift"
      fi
      # public route check on staging
      if [[ -n "$staging" && -f "$(soviez_migration_staging_dir "$staging")/identity.json" ]]; then
        local pub
        pub="$(soviez_json_get "$(cat "$(soviez_migration_staging_dir "$staging")/identity.json")" public_routing_enabled)"
        if [[ "$pub" == "true" || "$pub" == "True" ]]; then
          soviez_migration_die MIGRATION_DESTINATION_PUBLIC_ROUTE_DETECTED "staging public route"
        fi
      fi
      printf '%s\n' "{\"pair_id\":\"$pair_id\",\"ready_for_20\":\"$ready_val\",\"staging_id\":\"${staging:-}\",\"ok\":true}"
      return 0
    fi
  done < <(find "$SOVIEZ_MIG_ROOT/ops" -name state.json 2>/dev/null | sort)
  # Fixture-friendly: allow explicit readiness env
  if [[ "${SOVIEZ_MIG_P20_FIXTURE_READY:-0}" == "1" ]]; then
    if [[ "${SOVIEZ_MIG_P20_INJECT_DRIFT:-}" == "fingerprint" ]]; then
      soviez_migration_die MIGRATION_PHASE19_DRIFT_DETECTED "injected fingerprint drift"
    fi
    printf '%s\n' "{\"pair_id\":\"$pair_id\",\"ready_for_20\":\"${SOVIEZ_MIG_P20_FIXTURE_READY_VAL:-PASS}\",\"staging_id\":\"${SOVIEZ_MIG_P20_STAGING_ID:-staging-fixture}\",\"ok\":true}"
    return 0
  fi
  [[ "$found" -eq 1 ]] || soviez_migration_die MIGRATION_PHASE19_READINESS_REQUIRED "Phase 19 readiness missing for pair"
}

# --- end migration/authorization/readiness.sh ---

# --- begin migration/authorization/engine.sh ---
# shellcheck shell=bash

soviez_migration_authorization_plan() {
  local pair_id="$1"
  local account_id="${SOVIEZ_MIG_P20_ACCOUNT_ID:-acct-p20}"
  local license_id="${SOVIEZ_MIG_P20_LICENSE_ID:-lic-p20}"
  soviez_migration_assert_phase20_authorization_allowed "$SOVIEZ_MIG_OP_AUTH_PLAN"
  soviez_migration_token_assert_canonical_only
  local reval elig plan_id
  if ! reval="$(soviez_migration_p20_revalidate_phase19 "$pair_id")"; then
    soviez_migration_die MIGRATION_PHASE19_READINESS_REQUIRED "Phase 19 revalidation failed"
  fi
  elig="$(soviez_migration_token_eligibility_p20 "$account_id" "$license_id")"
  local status
  status="$(soviez_json_get "$elig" status)"
  [[ "$status" == "eligible" ]] || soviez_migration_die MIGRATION_TOKEN_NOT_ELIGIBLE "token not eligible: $(soviez_json_get "$elig" code)"
  plan_id="$(soviez_migration_new_id aplan)"
  local dir
  dir="$(soviez_migration_p20_auth_dir "$plan_id")"
  mkdir -p "$dir"
  SOVIEZ_PLAN="$plan_id" SOVIEZ_OUT="$dir/plan.json" SOVIEZ_PAIR="$pair_id" SOVIEZ_REVAL="$reval" SOVIEZ_ELIG="$elig" \
    SOVIEZ_ACC="$account_id" SOVIEZ_LIC="$license_id" python3 - <<'PY'
import json,os,time
reval=json.loads(os.environ["SOVIEZ_REVAL"]); elig=json.loads(os.environ["SOVIEZ_ELIG"])
body={
 "schema":"soviez.migration_authorization_plan.v1",
 "plan_id":os.environ["SOVIEZ_PLAN"],
 "pair_id":os.environ["SOVIEZ_PAIR"],
 "account_id":os.environ["SOVIEZ_ACC"],
 "license_id":os.environ["SOVIEZ_LIC"],
 "phase19":reval,
 "token_eligibility":elig,
 "grant_id":elig.get("grant_id"),
 "phase21_allowed":False,
 "production_dns_changed":False,
 "traffic_cutover_started":False,
 "created_at":time.strftime("%Y-%m-%dT%H:%M:%SZ",time.gmtime()),
}
open(os.environ["SOVIEZ_OUT"],"w").write(json.dumps(body,separators=(",",":")))
print(open(os.environ["SOVIEZ_OUT"]).read())
PY
}

soviez_migration_authorization_commit() {
  local pair_id="$1"
  local confirm="${2:-0}"
  [[ "$confirm" == "1" || "${SOVIEZ_CLI_YES:-0}" == "1" || "${SOVIEZ_MIG_ASSUME_YES:-0}" == "1" ]] || \
    soviez_migration_die MIGRATION_CONFIRMATION_REQUIRED "authorization commit requires confirm"
  soviez_migration_assert_phase20_authorization_allowed "$SOVIEZ_MIG_OP_AUTH_COMMIT"
  export SOVIEZ_MIG_P20_CANONICAL_COMMIT=1
  local account_id="${SOVIEZ_MIG_P20_ACCOUNT_ID:-acct-p20}"
  local license_id="${SOVIEZ_MIG_P20_LICENSE_ID:-lic-p20}"
  local op_id idem_key
  op_id="$(soviez_migration_new_id opauth)"
  idem_key="${SOVIEZ_MIG_P20_IDEMPOTENCY_KEY:-idem-$op_id}"
  local reval
  if ! reval="$(soviez_migration_p20_revalidate_phase19 "$pair_id")"; then
    soviez_migration_die MIGRATION_PHASE19_READINESS_REQUIRED "Phase 19 revalidation failed"
  fi
  local staging_id grant_id
  staging_id="$(soviez_json_get "$reval" staging_id)"
  local elig
  elig="$(soviez_migration_token_eligibility_p20 "$account_id" "$license_id")"
  grant_id="$(soviez_json_get "$elig" grant_id)"
  [[ -n "$grant_id" ]] || soviez_migration_die MIGRATION_TOKEN_REQUIRED "grant missing"

  local payload
  payload="$(SOVIEZ_PAIR="$pair_id" SOVIEZ_OP="$op_id" SOVIEZ_IDEM="$idem_key" SOVIEZ_ACC="$account_id" \
    SOVIEZ_LIC="$license_id" SOVIEZ_GRANT="$grant_id" SOVIEZ_STG="$staging_id" \
    SOVIEZ_SFP="${SOVIEZ_MIG_P20_SOURCE_FP:-fp-source}" SOVIEZ_DFP="${SOVIEZ_MIG_P20_DEST_FP:-fp-dest}" \
    SOVIEZ_SDB="${SOVIEZ_MIG_P20_SOURCE_DB:-aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa}" \
    SOVIEZ_DDB="${SOVIEZ_MIG_P20_DEST_DB:-bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb}" \
    SOVIEZ_SDG="${SOVIEZ_MIG_P20_SOURCE_DIGEST:-sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa}" \
    SOVIEZ_DDG="${SOVIEZ_MIG_P20_DEST_DIGEST:-sha256:bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb}" \
    SOVIEZ_STAGES="${SOVIEZ_MIG_P20_STAGE_IDS:-}" SOVIEZ_MAND="${SOVIEZ_MIG_P20_MANDATORY_STAGES:-}" \
    SOVIEZ_PROD="${SOVIEZ_MIG_P20_SOURCE_PROD:-prod-p20}" SOVIEZ_DEST_ENV="${SOVIEZ_MIG_P20_DEST_ENV:-dest-p20}" \
    SOVIEZ_READY="$(soviez_json_get "$reval" ready_for_20)" python3 - <<'PY'
import json,os,hashlib
stages=[s for s in os.environ.get("SOVIEZ_STAGES","").split(",") if s]
mand=[s for s in os.environ.get("SOVIEZ_MAND","").split(",") if s]
body={
 "account_id":os.environ["SOVIEZ_ACC"],
 "license_id":os.environ["SOVIEZ_LIC"],
 "pair_id":os.environ["SOVIEZ_PAIR"],
 "operation_id":os.environ["SOVIEZ_OP"],
 "idempotency_key":os.environ["SOVIEZ_IDEM"],
 "grant_id":os.environ["SOVIEZ_GRANT"],
 "staging_id":os.environ["SOVIEZ_STG"],
 "readiness_id":"ready-"+os.environ["SOVIEZ_PAIR"],
 "source_fp":os.environ["SOVIEZ_SFP"],
 "dest_fp":os.environ["SOVIEZ_DFP"],
 "source_db_uuid":os.environ["SOVIEZ_SDB"],
 "dest_db_uuid":os.environ["SOVIEZ_DDB"],
 "source_digest":os.environ["SOVIEZ_SDG"],
 "dest_digest":os.environ["SOVIEZ_DDG"],
 "source_production_id":os.environ["SOVIEZ_PROD"],
 "source_environment_id":os.environ["SOVIEZ_PROD"],
 "dest_environment_id":os.environ["SOVIEZ_DEST_ENV"],
 "stage_ids":stages,
 "mandatory_stage_ids":mand,
}
raw=json.dumps({k:v for k,v in body.items() if k!="request_hash"},separators=(",",":"),sort_keys=True)
body["request_hash"]=hashlib.sha256(raw.encode()).hexdigest()
print(json.dumps(body,separators=(",",":")))
PY
)"

  mkdir -p "$SOVIEZ_MIG_ROOT/ops/$op_id"
  printf '%s\n' "{\"operation_id\":\"$op_id\",\"operation_type\":\"migration_authorization_commit\",\"current_state\":\"committing_token_and_binding\",\"migration_pair_id\":\"$pair_id\"}" \
    > "$SOVIEZ_MIG_ROOT/ops/$op_id/state.json"

  local receipt
  set +e
  receipt="$(soviez_migration_p20_ledger commit --payload-json "$payload" 2>/tmp/p20-commit.err)"
  local rc=$?
  set -e
  if [[ $rc -ne 0 ]]; then
    local code
    code="$(python3 -c 'import json,sys; print(json.load(open("/tmp/p20-commit.err")).get("code","MIGRATION_AUTHORIZATION_COMMIT_UNKNOWN"))' 2>/dev/null || echo MIGRATION_AUTHORIZATION_COMMIT_UNKNOWN)"
    printf '%s\n' "{\"operation_id\":\"$op_id\",\"current_state\":\"failed_precommit\",\"code\":\"$code\"}" > "$SOVIEZ_MIG_ROOT/ops/$op_id/state.json"
    soviez_migration_die "$code" "authorization commit failed"
  fi

  local auth_id
  auth_id="$(soviez_json_get "$receipt" authorization_id)"
  mkdir -p "$(soviez_migration_p20_auth_dir "$auth_id")"
  printf '%s\n' "$receipt" > "$(soviez_migration_p20_auth_dir "$auth_id")/authorization.json"
  printf '%s\n' "$receipt" > "$SOVIEZ_MIG_ROOT/ops/$op_id/authorization.json"
  printf '%s\n' "{\"operation_id\":\"$op_id\",\"operation_type\":\"migration_authorization_commit\",\"current_state\":\"authorization_committed\",\"authorization_id\":\"$auth_id\",\"migration_pair_id\":\"$pair_id\",\"migration_token_consumed\":true,\"destination_production_activated\":false,\"traffic_cutover_started\":false,\"production_dns_changed\":false}" \
    > "$SOVIEZ_MIG_ROOT/ops/$op_id/state.json"
  printf '%s\n' "$receipt"
}

soviez_migration_authorization_show() {
  local auth_id="$1"
  local f
  f="$(soviez_migration_p20_auth_dir "$auth_id")/authorization.json"
  [[ -f "$f" ]] || soviez_migration_die MIGRATION_AUTHORIZATION_REQUIRED "authorization not found"
  cat "$f"
}

soviez_migration_authorization_recover() {
  local op_id="$1"
  local sf="$SOVIEZ_MIG_ROOT/ops/$op_id/state.json"
  [[ -f "$sf" ]] || soviez_migration_die MIGRATION_NOT_FOUND "op missing"
  if [[ -f "$SOVIEZ_MIG_ROOT/ops/$op_id/authorization.json" ]]; then
    cat "$SOVIEZ_MIG_ROOT/ops/$op_id/authorization.json"
    return 0
  fi
  local idem="${SOVIEZ_MIG_P20_IDEMPOTENCY_KEY:-}"
  local acc="${SOVIEZ_MIG_P20_ACCOUNT_ID:-acct-p20}"
  [[ -n "$idem" ]] || soviez_migration_die MIGRATION_AUTHORIZATION_COMMIT_UNKNOWN "idempotency key required for recover"
  soviez_migration_p20_ledger get --account-id "$acc" --idempotency-key "$idem"
}

# --- end migration/authorization/engine.sh ---

# --- begin migration/authorization/offline.sh ---
# shellcheck shell=bash

soviez_migration_authorization_export() {
  local auth_id="$1"
  local out="${2:-}"
  local authf
  authf="$(soviez_migration_p20_auth_dir "$auth_id")/authorization.json"
  [[ -f "$authf" ]] || soviez_migration_die MIGRATION_AUTHORIZATION_REQUIRED "missing"
  local pkg_id
  pkg_id="pkg-$auth_id"
  local pkg
  pkg="$(SOVIEZ_A="$(cat "$authf")" SOVIEZ_P="$pkg_id" python3 - <<'PY'
import json,os,hashlib,time
auth=json.loads(os.environ["SOVIEZ_A"])
# Offline package requires already-committed authorization
assert auth.get("transaction_status")=="committed"
pkg={
 "schema":"soviez.migration_authorization_offline_package.v1",
 "package_id":os.environ["SOVIEZ_P"],
 "authorization":auth,
 "issued_at":time.strftime("%Y-%m-%dT%H:%M:%SZ",time.gmtime()),
 "expires_at":time.strftime("%Y-%m-%dT%H:%M:%SZ",time.gmtime(time.time()+3600)),
 "no_private_keys":True,
}
pkg["public_signature"]=hashlib.sha256(json.dumps(auth,sort_keys=True,separators=(",",":")).encode()).hexdigest()
print(json.dumps(pkg,separators=(",",":")))
PY
)"
  mkdir -p "$SOVIEZ_MIG_ROOT/offline_packages"
  printf '%s\n' "$pkg" > "$SOVIEZ_MIG_ROOT/offline_packages/$pkg_id.json"
  if [[ -n "$out" ]]; then
    printf '%s\n' "$pkg" > "$out"
  fi
  printf '%s\n' "$pkg"
}

soviez_migration_authorization_import() {
  local path="$1"
  [[ -f "$path" ]] || soviez_migration_die MIGRATION_AUTHORIZATION_REQUIRED "package path missing"
  local pkg_id="" auth_id="" _line
  while IFS= read -r _line; do
    if [[ -z "$pkg_id" ]]; then pkg_id="$_line"; else auth_id="$_line"; fi
  done < <(python3 - "$path" <<'PY'
import json, sys
pkg = json.load(open(sys.argv[1]))
auth = pkg.get("authorization") or {}
print(pkg.get("package_id", ""))
print(auth.get("authorization_id", ""))
PY
)
  [[ -n "$pkg_id" && -n "$auth_id" ]] || soviez_migration_die MIGRATION_AUTHORIZATION_INVALID "package missing package_id or authorization_id"
  # expiry
  SOVIEZ_P="$(cat "$path")" python3 - <<'PY'
import json,os,sys,time
from datetime import datetime
pkg=json.loads(os.environ["SOVIEZ_P"])
exp=datetime.strptime(pkg["expires_at"],"%Y-%m-%dT%H:%M:%SZ").timestamp()
if time.time()>exp:
  print("EXPIRED"); sys.exit(25)
auth=pkg.get("authorization") or {}
if auth.get("transaction_status")!="committed":
  print("NOT_COMMITTED"); sys.exit(25)
if not pkg.get("public_signature"):
  print("UNSIGNED"); sys.exit(25)
print("OK")
PY
  # replay registry
  soviez_migration_p20_ledger offline-register --package-id "$pkg_id" --authorization-id "$auth_id"
  mkdir -p "$(soviez_migration_p20_auth_dir "$auth_id")"
  python3 -c 'import json,sys; p=json.load(open(sys.argv[1])); json.dump(p["authorization"], open(sys.argv[2],"w"), separators=(",",":"))' \
    "$path" "$(soviez_migration_p20_auth_dir "$auth_id")/authorization.json"
  # local apply
  soviez_migration_destination_binding_apply "$auth_id" >/dev/null
  soviez_migration_source_grace_apply "$auth_id" >/dev/null
  printf '{"ok":true,"authorization_id":"%s","package_id":"%s","applied":true}\n' "$auth_id" "$pkg_id"
}

# --- end migration/authorization/offline.sh ---

# --- begin migration/token/eligibility.sh ---
# shellcheck shell=bash

soviez_migration_token_eligibility_p20() {
  local account_id="$1" license_id="$2"
  soviez_migration_p20_ledger eligibility --account-id "$account_id" --license-id "$license_id"
}

soviez_migration_token_assert_canonical_only() {
  # Block obsolete disconnected consume env
  if [[ "${SOVIEZ_MIG_LEGACY_CONSUME:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_TOKEN_NOT_ELIGIBLE "legacy consume_ip_migration_token blocked; use commit_migration_authorization"
  fi
}

# --- end migration/token/eligibility.sh ---

# --- begin migration/rebind/engine.sh ---
# shellcheck shell=bash

soviez_migration_source_grace_apply() {
  local auth_id="$1"
  soviez_migration_assert_phase20_authorization_allowed "$SOVIEZ_MIG_OP_SOURCE_GRACE"
  local authf grace_dir
  authf="$(soviez_migration_p20_auth_dir "$auth_id")/authorization.json"
  [[ -f "$authf" ]] || soviez_migration_die MIGRATION_AUTHORIZATION_REQUIRED "missing authorization"
  if [[ "${SOVIEZ_MIG_P20_INJECT_GRACE_FAIL:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_SOURCE_GRACE_APPLY_FAILED "injected grace failure"
  fi
  local license_id src_fp
  license_id="$(soviez_json_get "$(cat "$authf")" license_id)"
  src_fp="$(soviez_json_get "$(cat "$authf")" source_device_fingerprint)"
  grace_dir="$SOVIEZ_MIG_ROOT/grace/$license_id"
  mkdir -p "$grace_dir"
  cat > "$grace_dir/grace.json" <<EOF
{"schema":"soviez.migration_origin_grace.v1","grace_id":"grace-$auth_id","authorization_id":"$auth_id","license_id":"$license_id","source_fingerprint":"$src_fp","state":"migration_origin_grace","traffic_owner":"source","allows":["traffic","backup","status","diagnostics","recovery"],"denies":["update","clone","stage_create","second_migration","rebind","device_reauth","license_export","restore_to_new_production"],"slot":false,"expires":null,"needs_action_if_stale":true}
EOF
  # enforcement marker used by restriction checks
  printf '1\n' > "$grace_dir/ENFORCED"
  cat "$grace_dir/grace.json"
}

soviez_migration_source_grace_status() {
  local prod_id="$1"
  local license_id="${SOVIEZ_MIG_P20_LICENSE_ID:-lic-p20}"
  local f="$SOVIEZ_MIG_ROOT/grace/$license_id/grace.json"
  [[ -f "$f" ]] || soviez_migration_die MIGRATION_SOURCE_GRACE_INVALID "grace missing for $prod_id"
  cat "$f"
}

soviez_migration_source_grace_assert_allowed() {
  local action="$1"
  local license_id="${SOVIEZ_MIG_P20_LICENSE_ID:-lic-p20}"
  local f="$SOVIEZ_MIG_ROOT/grace/$license_id/grace.json"
  [[ -f "$f" ]] || return 0
  case "$action" in
    update|clone|stage_create|second_migration|rebind|device_reauth|license_export|restore_to_new_production)
      soviez_migration_die MIGRATION_SOURCE_GRACE_INVALID "action denied under migration_origin_grace: $action"
      ;;
  esac
  return 0
}

soviez_migration_destination_binding_apply() {
  local auth_id="$1"
  soviez_migration_assert_phase20_authorization_allowed "$SOVIEZ_MIG_OP_DEST_ACTIVATION"
  local authf
  authf="$(soviez_migration_p20_auth_dir "$auth_id")/authorization.json"
  [[ -f "$authf" ]] || soviez_migration_die MIGRATION_AUTHORIZATION_REQUIRED "missing authorization"
  if [[ "${SOVIEZ_MIG_P20_INJECT_LG_DENY:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_LICENSE_GUARD_DENIED "injected LG denial"
  fi
  local dest_dir
  dest_dir="$SOVIEZ_MIG_ROOT/activation/$auth_id"
  mkdir -p "$dest_dir"
  local dest_fp db digest
  dest_fp="$(soviez_json_get "$(cat "$authf")" destination_device_fingerprint)"
  db="$(soviez_json_get "$(cat "$authf")" destination_database_uuid)"
  digest="$(soviez_json_get "$(cat "$authf")" destination_image_digest)"
  # PoP: require matching local destination fingerprint env
  if [[ -n "${SOVIEZ_MIG_P20_LOCAL_DEST_FP:-}" && "${SOVIEZ_MIG_P20_LOCAL_DEST_FP}" != "$dest_fp" ]]; then
    soviez_migration_die MIGRATION_DESTINATION_BINDING_INVALID "destination PoP fingerprint mismatch"
  fi
  cat > "$dest_dir/binding.json" <<EOF
{"schema":"soviez.destination_binding.v1","authorization_id":"$auth_id","status":"production_licensed_pre_cutover","destination_fingerprint":"$dest_fp","database_uuid":"$db","image_digest":"$digest","public_route":false,"production_domain":null,"license_guard":"enabled","permanent_slot":true,"slot_count":1,"mail_neutralized":true,"payments_neutralized":true,"webhooks_neutralized":true,"cron_neutralized":true,"traffic_owner":"source","licensed_future_owner":"destination"}
EOF
  printf 'false\n' > "$dest_dir/public_route"
  cat "$dest_dir/binding.json"
}

soviez_migration_stage_rebind_apply() {
  local auth_id="$1"
  soviez_migration_assert_phase20_authorization_allowed "$SOVIEZ_MIG_OP_STAGE_REBIND"
  local authf
  authf="$(soviez_migration_p20_auth_dir "$auth_id")/authorization.json"
  [[ -f "$authf" ]] || soviez_migration_die MIGRATION_AUTHORIZATION_REQUIRED "missing authorization"
  local results blocked=0 warning=0
  results="$(soviez_json_get "$(cat "$authf")" stage_rebind_results)"
  mkdir -p "$SOVIEZ_MIG_ROOT/activation/$auth_id"
  printf '%s\n' "$results" > "$SOVIEZ_MIG_ROOT/activation/$auth_id/stage_rebinds.json"
  # Evaluate mandatory failures
  SOVIEZ_R="$(cat "$authf")" python3 - <<'PY'
import json,os,sys
auth=json.loads(os.environ["SOVIEZ_R"])
blocked=False; warn=False
for r in auth.get("stage_rebind_results") or []:
  if r.get("status")!="rebound":
    if r.get("mandatory"):
      blocked=True
    else:
      warn=True
out={"blocked":blocked,"warning":warn,"results":auth.get("stage_rebind_results") or [],"retention_unchanged":True}
print(json.dumps(out,separators=(",",":")))
if blocked:
  sys.exit(2)
if warn:
  sys.exit(1)
sys.exit(0)
PY
}

soviez_migration_split_brain_validate() {
  local auth_id="$1"
  local bindf gracef
  bindf="$SOVIEZ_MIG_ROOT/activation/$auth_id/binding.json"
  local license_id
  license_id="$(soviez_json_get "$(cat "$(soviez_migration_p20_auth_dir "$auth_id")/authorization.json")" license_id)"
  gracef="$SOVIEZ_MIG_ROOT/grace/$license_id/grace.json"
  [[ -f "$bindf" ]] || soviez_migration_die MIGRATION_DESTINATION_BINDING_INVALID "binding missing"
  [[ -f "$gracef" ]] || soviez_migration_die MIGRATION_SOURCE_GRACE_INVALID "grace missing"
  local pub
  pub="$(soviez_json_get "$(cat "$bindf")" public_route)"
  if [[ "$pub" == "true" || "$pub" == "True" ]]; then
    soviez_migration_die MIGRATION_SPLIT_BRAIN_DETECTED "destination public before Phase 21"
  fi
  if [[ "${SOVIEZ_MIG_P20_INJECT_SPLIT_BRAIN:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_SPLIT_BRAIN_DETECTED "injected dual public"
  fi
  local domain
  domain="$(soviez_json_get "$(cat "$bindf")" production_domain)"
  [[ "$domain" == "null" || -z "$domain" || "$domain" == "" ]] || \
    soviez_migration_die MIGRATION_SPLIT_BRAIN_DETECTED "production domain present"
  printf '{"status":"active","traffic_owner":"source","licensed_future_owner":"destination","public_destination":false}\n'
}

# --- end migration/rebind/engine.sh ---

# --- begin migration/activation/engine.sh ---
# shellcheck shell=bash

soviez_migration_destination_activate() {
  local pair_id="$1"
  local auth_id="${SOVIEZ_CLI_MIG_AUTH_ID:-${SOVIEZ_MIG_P20_AUTH_ID:-}}"
  [[ -n "$auth_id" ]] || soviez_migration_die MIGRATION_AUTHORIZATION_REQUIRED "authorization-id required"
  soviez_migration_assert_phase20_authorization_allowed "$SOVIEZ_MIG_OP_DEST_ACTIVATION"
  local bind
  bind="$(soviez_migration_destination_binding_apply "$auth_id")"
  local grace
  set +e
  grace="$(soviez_migration_source_grace_apply "$auth_id")"
  local grc=$?
  set -e
  if [[ $grc -ne 0 ]]; then
    printf '%s\n' "{\"current_state\":\"source_grace_apply_failed\",\"authorization_id\":\"$auth_id\"}"
    soviez_migration_die MIGRATION_SOURCE_GRACE_APPLY_FAILED "grace apply failed; destination remains non-public"
  fi
  set +e
  soviez_migration_stage_rebind_apply "$auth_id" >/tmp/p20-stage-rebind.out 2>/tmp/p20-stage-rebind.err
  local src=$?
  set -e
  local split
  split="$(soviez_migration_split_brain_validate "$auth_id")"
  # Internal health fixture
  local health='{"login_internal":true,"modules_loadable":true,"filestore_ok":true,"license_guard":"enabled"}'
  if [[ "${SOVIEZ_MIG_P20_INJECT_DEST_HEALTH_FAIL:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_DESTINATION_ACTIVATION_FAILED "injected health failure"
  fi
  # Destination verified backup (Phase 16 primitives or fixture marker)
  local bak_dir="$SOVIEZ_MIG_ROOT/activation/$auth_id/backup"
  mkdir -p "$bak_dir"
  printf '{"status":"VERIFIED","classification":"destination_post_activation","public_route":false}\n' > "$bak_dir/backup.json"
  if [[ "${SOVIEZ_MIG_P20_REQUIRE_DEST_BACKUP:-1}" == "1" && ! -f "$bak_dir/backup.json" ]]; then
    soviez_migration_die MIGRATION_DESTINATION_ACTIVATION_FAILED "destination backup missing"
  fi
  local out
  out="$(SOVIEZ_AUTH="$auth_id" SOVIEZ_BIND="$bind" SOVIEZ_GRACE="$grace" SOVIEZ_SPLIT="$split" \
    SOVIEZ_HEALTH="$health" SOVIEZ_SRC="$src" python3 - <<'PY'
import json,os
src=int(os.environ["SOVIEZ_SRC"])
stage="PASS"
if src==2: stage="BLOCKED"
elif src==1: stage="WARNING"
print(json.dumps({
  "authorization_id":os.environ["SOVIEZ_AUTH"],
  "destination_status":"production_licensed_pre_cutover",
  "binding":json.loads(os.environ["SOVIEZ_BIND"]),
  "grace":json.loads(os.environ["SOVIEZ_GRACE"]),
  "split_brain":json.loads(os.environ["SOVIEZ_SPLIT"]),
  "health":json.loads(os.environ["SOVIEZ_HEALTH"]),
  "stage_rebind":stage,
  "destination_backup":"VERIFIED",
  "public_route":False,
  "production_dns_changed":False,
  "traffic_cutover_started":False,
  "traffic_owner":"source",
  "phase21_allowed":False,
},separators=(",",":")))
PY
)"
  printf '%s\n' "$out" > "$SOVIEZ_MIG_ROOT/activation/$auth_id/activation.json"
  printf '%s\n' "$out"
}

soviez_migration_activation_status() {
  local op_or_auth="$1"
  if [[ -f "$SOVIEZ_MIG_ROOT/activation/$op_or_auth/activation.json" ]]; then
    cat "$SOVIEZ_MIG_ROOT/activation/$op_or_auth/activation.json"
    return 0
  fi
  # try ops
  if [[ -f "$SOVIEZ_MIG_ROOT/ops/$op_or_auth/authorization.json" ]]; then
    local aid
    aid="$(soviez_json_get "$(cat "$SOVIEZ_MIG_ROOT/ops/$op_or_auth/authorization.json")" authorization_id)"
    cat "$SOVIEZ_MIG_ROOT/activation/$aid/activation.json"
    return 0
  fi
  soviez_migration_die MIGRATION_NOT_FOUND "activation status not found"
}

# --- end migration/activation/engine.sh ---

# --- begin migration/phase21_readiness/engine.sh ---
# shellcheck shell=bash

soviez_migration_phase21_readiness() {
  local op_or_auth="$1"
  soviez_migration_assert_phase20_authorization_allowed "$SOVIEZ_MIG_OP_P21_READINESS"
  local auth_id="$op_or_auth"
  if [[ -f "$SOVIEZ_MIG_ROOT/ops/$op_or_auth/authorization.json" ]]; then
    auth_id="$(soviez_json_get "$(cat "$SOVIEZ_MIG_ROOT/ops/$op_or_auth/authorization.json")" authorization_id)"
  fi
  local authf actf gracef bakf
  authf="$(soviez_migration_p20_auth_dir "$auth_id")/authorization.json"
  actf="$SOVIEZ_MIG_ROOT/activation/$auth_id/activation.json"
  [[ -f "$authf" ]] || soviez_migration_die MIGRATION_AUTHORIZATION_REQUIRED "authorization missing"
  local license_id
  license_id="$(soviez_json_get "$(cat "$authf")" license_id)"
  gracef="$SOVIEZ_MIG_ROOT/grace/$license_id/grace.json"
  bakf="$SOVIEZ_MIG_ROOT/activation/$auth_id/backup/backup.json"
  local blockers=() warnings=()
  [[ -f "$actf" ]] || blockers+=("destination_activation_missing")
  [[ -f "$gracef" ]] || blockers+=("source_grace_missing")
  [[ -f "$bakf" ]] || blockers+=("destination_backup_missing")
  local snap
  snap="$(soviez_migration_p20_ledger snapshot --license-id "$license_id")"
  local rem slots
  rem="$(soviez_json_get "$snap" grant_remaining)"
  slots="$(soviez_json_get "$snap" slot_count)"
  [[ "$rem" == "0" ]] || blockers+=("token_not_fully_consumed")
  [[ "$slots" == "1" ]] || blockers+=("slot_count_invalid")
  if [[ -f "$actf" ]]; then
    local pub
    pub="$(soviez_json_get "$(cat "$actf")" public_route)"
    [[ "$pub" == "false" || "$pub" == "False" ]] || blockers+=("public_route")
    local stg
    stg="$(soviez_json_get "$(cat "$actf")" stage_rebind)"
    [[ "$stg" != "BLOCKED" ]] || blockers+=("mandatory_stage_failure")
    [[ "$stg" != "WARNING" ]] || warnings+=("optional_stage_failure")
  fi
  if [[ "${SOVIEZ_MIG_P20_INJECT_DRIFT:-}" == "readiness" ]]; then
    blockers+=("drift")
  fi
  local report_id status
  report_id="$(soviez_migration_new_id p21r)"
  if [[ ${#blockers[@]} -gt 0 ]]; then status=BLOCKED
  elif [[ ${#warnings[@]} -gt 0 ]]; then status=WARNING
  else status=PASS
  fi
  mkdir -p "$SOVIEZ_MIG_ROOT/phase21_readiness/$report_id"
  SOVIEZ_OUT="$SOVIEZ_MIG_ROOT/phase21_readiness/$report_id/report.json" \
    SOVIEZ_RID="$report_id" SOVIEZ_AID="$auth_id" SOVIEZ_ST="$status" \
    SOVIEZ_BL="$(printf '%s,' ${blockers[@]+"${blockers[@]}"})" \
    SOVIEZ_WN="$(printf '%s,' ${warnings[@]+"${warnings[@]}"})" \
    SOVIEZ_SNAP="$snap" SOVIEZ_TTL="$SOVIEZ_MIG_P21_READINESS_TTL_SECONDS" python3 - <<'PY'
import json,os,time,hashlib
bl=[x for x in os.environ.get("SOVIEZ_BL","").split(",") if x]
wn=[x for x in os.environ.get("SOVIEZ_WN","").split(",") if x]
snap=json.loads(os.environ["SOVIEZ_SNAP"])
exp=time.time()+int(os.environ["SOVIEZ_TTL"])
body={
 "schema":"soviez.migration_phase21_readiness.v1",
 "report_id":os.environ["SOVIEZ_RID"],
 "authorization_id":os.environ["SOVIEZ_AID"],
 "readiness_status":os.environ["SOVIEZ_ST"],
 "token_consumed_count":1 if snap.get("grant_remaining")==0 else 0,
 "slot_count":snap.get("slot_count"),
 "traffic_owner":"source",
 "public_route":False,
 "production_dns_changed":False,
 "traffic_cutover_started":False,
 "phase21_allowed":False,
 "blockers":bl,
 "warnings":wn,
 "created_at":time.strftime("%Y-%m-%dT%H:%M:%SZ",time.gmtime()),
 "expires_at":time.strftime("%Y-%m-%dT%H:%M:%SZ",time.gmtime(exp)),
 "signer":"soviez-p20",
}
body["public_signature"]=hashlib.sha256(json.dumps(body,sort_keys=True,separators=(",",":")).encode()).hexdigest()
open(os.environ["SOVIEZ_OUT"],"w").write(json.dumps(body,separators=(",",":")))
print(open(os.environ["SOVIEZ_OUT"]).read())
PY
}

soviez_migration_phase21_readiness_show() {
  local report_id="$1"
  local f="$SOVIEZ_MIG_ROOT/phase21_readiness/$report_id/report.json"
  [[ -f "$f" ]] || soviez_migration_die MIGRATION_PHASE21_NOT_READY "report missing"
  # expiry / drift
  SOVIEZ_F="$f" python3 - <<'PY'
import json,os,sys,time
from datetime import datetime
body=json.load(open(os.environ["SOVIEZ_F"]))
exp=body.get("expires_at")
# parse Z
try:
  t=datetime.strptime(exp,"%Y-%m-%dT%H:%M:%SZ").timestamp()
  if time.time()>t:
    print(json.dumps({"ok":False,"code":"MIGRATION_PHASE21_NOT_READY","message":"expired"},separators=(",",":")))
    sys.exit(25)
except Exception:
  pass
if os.environ.get("SOVIEZ_MIG_P20_INJECT_DRIFT")=="readiness":
  print(json.dumps({"ok":False,"code":"MIGRATION_PHASE19_DRIFT_DETECTED"},separators=(",",":")))
  sys.exit(25)
print(json.dumps(body,separators=(",",":")))
PY
}

# --- end migration/phase21_readiness/engine.sh ---

# --- begin migration/cutover/codes.sh ---
# shellcheck shell=bash
# Phase 21 cutover operation types + scoped gates.
#
# Phase 21 replaces the blanket Phase 18/19/20 cutover deny with a narrow
# allowlist. SOVIEZ_MIG_ALLOW_CUTOVER alone remains a forbidden bypass
# (see authorization/codes.sh); the ONLY authorized path is the canonical
# cutover engine, which sets SOVIEZ_MIG_P21_CANONICAL_CUTOVER=1 internally.

SOVIEZ_MIG_OP_CUTOVER_PLAN=migration_cutover_plan
SOVIEZ_MIG_OP_FINAL_CUTOVER_SYNC=migration_final_cutover_sync
SOVIEZ_MIG_OP_SOURCE_MAINTENANCE=migration_source_maintenance
SOVIEZ_MIG_OP_DEST_ROUTE_ACTIVATE=migration_destination_route_activate
SOVIEZ_MIG_OP_DNS_CUTOVER=migration_dns_cutover
SOVIEZ_MIG_OP_TLS_VALIDATE=migration_tls_validate
SOVIEZ_MIG_OP_TRAFFIC_OWNER_SWITCH=migration_traffic_owner_switch
SOVIEZ_MIG_OP_POST_CUTOVER_VALIDATE=migration_post_cutover_validate
SOVIEZ_MIG_OP_INTEGRATION_ACTIVATE=migration_integration_activate
SOVIEZ_MIG_OP_IMMEDIATE_ROLLBACK=migration_immediate_rollback
SOVIEZ_MIG_OP_STAGE_CUTOVER=migration_stage_cutover
SOVIEZ_MIG_OP_PHASE22_READINESS=migration_phase22_readiness

SOVIEZ_MIG_P21_ROLLBACK_WINDOW_SECONDS="${SOVIEZ_MIG_P21_ROLLBACK_WINDOW_SECONDS:-1800}"
SOVIEZ_MIG_P21_FREEZE_MAX_SECONDS="${SOVIEZ_MIG_P21_FREEZE_MAX_SECONDS:-900}"
SOVIEZ_MIG_P22_READINESS_TTL_SECONDS="${SOVIEZ_MIG_P22_READINESS_TTL_SECONDS:-86400}"

SOVIEZ_MIGRATION_CODES+=(
  MIGRATION_CUTOVER_PLAN_REQUIRED
  MIGRATION_CUTOVER_PLAN_INVALID
  MIGRATION_CUTOVER_PLAN_EXPIRED
  MIGRATION_CUTOVER_NOT_ALLOWED
  MIGRATION_CUTOVER_ALREADY_STARTED
  MIGRATION_CUTOVER_CONFIRMATION_REQUIRED
  MIGRATION_CUTOVER_DRIFT_DETECTED
  MIGRATION_CANONICAL_CUTOVER_REQUIRED
  MIGRATION_FINAL_CUTOVER_SYNC_FAILED
  MIGRATION_FINAL_CUTOVER_SYNC_TIMEOUT
  MIGRATION_SOURCE_MAINTENANCE_FAILED
  MIGRATION_DESTINATION_ROUTE_ACTIVATE_FAILED
  MIGRATION_DNS_CUTOVER_FAILED
  MIGRATION_DNS_CUTOVER_NOT_CONFIRMED
  MIGRATION_TLS_PRODUCTION_INVALID
  MIGRATION_TLS_PRODUCTION_EXPIRED
  MIGRATION_TRAFFIC_OWNER_SWITCH_FAILED
  MIGRATION_TRAFFIC_OWNER_ALREADY_DESTINATION
  MIGRATION_POST_CUTOVER_HEALTH_FAILED
  MIGRATION_SPLIT_BRAIN_CUTOVER_DETECTED
  MIGRATION_INTEGRATION_ACTIVATE_FAILED
  MIGRATION_INTEGRATION_BEFORE_HEALTH_DENIED
  MIGRATION_ROLLBACK_WINDOW_EXPIRED
  MIGRATION_ROLLBACK_NOT_SAFE
  MIGRATION_ROLLBACK_NOT_ELIGIBLE
  MIGRATION_STAGE_CUTOVER_BLOCKED
  MIGRATION_STAGE_CUTOVER_MANDATORY_FAILED
  MIGRATION_PHASE22_NOT_READY
  MIGRATION_PHASE22_ARCHIVE_FORBIDDEN
  MIGRATION_BROAD_DNS_FORBIDDEN
  MIGRATION_WILDCARD_ROUTE_FORBIDDEN
)

soviez_migration_p21_assert_canonical() {
  [[ "${SOVIEZ_MIG_P21_CANONICAL_CUTOVER:-0}" == "1" ]] || \
    soviez_migration_die MIGRATION_CANONICAL_CUTOVER_REQUIRED "Cutover step requires the canonical Phase 21 engine"
}

soviez_migration_assert_phase21_cutover_allowed() {
  local op_type="${1:-}"
  case "$op_type" in
    migration_cutover_plan|migration_final_cutover_sync|migration_source_maintenance| \
    migration_destination_route_activate|migration_dns_cutover|migration_tls_validate| \
    migration_traffic_owner_switch|migration_post_cutover_validate|migration_integration_activate| \
    migration_immediate_rollback|migration_stage_cutover|migration_phase22_readiness)
      ;;
    *)
      soviez_migration_die MIGRATION_CUTOVER_NOT_ALLOWED "Unauthorized Phase 21 op: ${op_type:-missing}"
      ;;
  esac
  # Permanent bans — never authorized by any Phase 21 flag combination.
  if [[ "${SOVIEZ_MIG_SOURCE_PURGE:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_SOURCE_PURGE_NOT_AUTHORIZED "Source purge forbidden in Phase 21"
  fi
  if [[ "${SOVIEZ_MIG_SAAS_PAYLOAD_RELAY:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_DATA_EGRESS_DENIED "SaaS payload relay forbidden"
  fi
  # Soften archive forbid when Phase 22 canonical engine is active.
  # Purge remains forever forbidden via soviez_migration_assert_phase22_allowed.
  if [[ "${SOVIEZ_MIG_SOURCE_ARCHIVE:-0}" == "1" && "${SOVIEZ_MIG_P22_CANONICAL:-0}" != "1" ]]; then
    soviez_migration_die MIGRATION_PHASE22_ARCHIVE_FORBIDDEN "Phase 22 archive/purge not authorized in Phase 21"
  fi
  if [[ "${SOVIEZ_MIG_BROAD_DNS:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_BROAD_DNS_FORBIDDEN "Broad/zone-wide DNS mutation forbidden; exact record only"
  fi
  if [[ "${SOVIEZ_MIG_P21_WILDCARD_ROUTE:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_WILDCARD_ROUTE_FORBIDDEN "Wildcard route forbidden"
  fi
  # SOVIEZ_MIG_ALLOW_CUTOVER remains a forbidden bypass regardless of op — the
  # ONLY way it is tolerated is when the canonical engine itself set the
  # companion flag (mirrors Phase 20's ALLOW_TOKEN_CONSUME/CANONICAL_COMMIT
  # pattern). Ordinary Phase 21 ops never need to set SOVIEZ_MIG_ALLOW_CUTOVER
  # and remain callable across separate CLI invocations (retry/rollback/etc.).
  if [[ "${SOVIEZ_MIG_ALLOW_CUTOVER:-0}" == "1" && "${SOVIEZ_MIG_P21_CANONICAL_CUTOVER:-0}" != "1" ]]; then
    soviez_migration_die MIGRATION_CANONICAL_CUTOVER_REQUIRED "SOVIEZ_MIG_ALLOW_CUTOVER bypass forbidden; use canonical cutover engine"
  fi
  return 0
}

# --- end migration/cutover/codes.sh ---

# --- begin migration/cutover/model.sh ---
# shellcheck shell=bash
# Phase 21 cutover path helpers.

soviez_migration_cutover_paths_init() {
  soviez_migration_paths_init
  soviez_migration_p20_paths_init
  SOVIEZ_MIG_CUTOVER_DIR="$SOVIEZ_MIG_ROOT/cutover"
  SOVIEZ_MIG_CUTOVER_PLAN_DIR="$SOVIEZ_MIG_CUTOVER_DIR/plans"
  SOVIEZ_MIG_CUTOVER_OPS_DIR="$SOVIEZ_MIG_CUTOVER_DIR/ops"
  SOVIEZ_MIG_TRAFFIC_OWNER_DIR="$SOVIEZ_MIG_ROOT/traffic_owner"
  export SOVIEZ_MIG_CUTOVER_DIR SOVIEZ_MIG_CUTOVER_PLAN_DIR SOVIEZ_MIG_CUTOVER_OPS_DIR SOVIEZ_MIG_TRAFFIC_OWNER_DIR
  mkdir -p "$SOVIEZ_MIG_CUTOVER_PLAN_DIR" "$SOVIEZ_MIG_CUTOVER_OPS_DIR" "$SOVIEZ_MIG_TRAFFIC_OWNER_DIR" \
    "$SOVIEZ_MIG_ROOT/source_transition" "$SOVIEZ_MIG_ROOT/phase22_readiness"
}

soviez_migration_cutover_plan_dir() { printf '%s/%s\n' "$SOVIEZ_MIG_CUTOVER_PLAN_DIR" "$1"; }
soviez_migration_cutover_op_dir() { printf '%s/%s\n' "$SOVIEZ_MIG_CUTOVER_OPS_DIR" "$1"; }
soviez_migration_traffic_owner_path() { printf '%s/%s.json\n' "$SOVIEZ_MIG_TRAFFIC_OWNER_DIR" "$1"; }
soviez_migration_cutover_state_path() { printf '%s/state.json\n' "$(soviez_migration_cutover_op_dir "$1")"; }
soviez_migration_cutover_rollback_window_path() { printf '%s/rollback_window.json\n' "$(soviez_migration_cutover_op_dir "$1")"; }

# --- end migration/cutover/model.sh ---

# --- begin migration/cutover/preflight.sh ---
# shellcheck shell=bash
# Phase 21 pre-cutover revalidation of Phase 20 committed state.

soviez_migration_p21_find_auth_for_pair() {
  local pair_id="$1"
  local f pid status best=""
  [[ -d "$SOVIEZ_MIG_ROOT/authorization" ]] || return 1
  while IFS= read -r f; do
    [[ -f "$f" ]] || continue
    pid="$(soviez_json_get "$(cat "$f")" migration_pair_id 2>/dev/null || true)"
    [[ "$pid" == "$pair_id" ]] || continue
    status="$(soviez_json_get "$(cat "$f")" transaction_status 2>/dev/null || true)"
    [[ "$status" == "committed" ]] || continue
    best="$(soviez_json_get "$(cat "$f")" authorization_id 2>/dev/null || true)"
  done < <(find "$SOVIEZ_MIG_ROOT/authorization" -mindepth 2 -maxdepth 2 -name authorization.json 2>/dev/null | sort)
  [[ -n "$best" ]] || return 1
  printf '%s\n' "$best"
}

# soviez_migration_p21_revalidate_phase20 <pair_id>
# Requires: committed Phase 20 authorization, destination activation,
# source migration_origin_grace, destination verified backup, and either
# SOVIEZ_MIG_P21_FIXTURE=1 (disposable fixture — no live Phase 21 readiness
# report required) OR a real Phase 21 readiness report that is not BLOCKED.
soviez_migration_p21_revalidate_phase20() {
  local pair_id="$1"
  [[ -n "$pair_id" ]] || soviez_migration_die MIGRATION_PAIR_REQUIRED "pair-id required"
  soviez_migration_cutover_paths_init

  local auth_id="${SOVIEZ_MIG_P21_AUTH_ID:-}"
  if [[ -z "$auth_id" ]]; then
    auth_id="$(soviez_migration_p21_find_auth_for_pair "$pair_id")" || \
      soviez_migration_die MIGRATION_AUTHORIZATION_REQUIRED "no committed Phase 20 authorization for pair"
  fi

  local authf actf gracef bakf
  authf="$(soviez_migration_p20_auth_dir "$auth_id")/authorization.json"
  [[ -f "$authf" ]] || soviez_migration_die MIGRATION_AUTHORIZATION_REQUIRED "authorization missing"

  actf="$SOVIEZ_MIG_ROOT/activation/$auth_id/activation.json"
  [[ -f "$actf" ]] || soviez_migration_die MIGRATION_DESTINATION_ACTIVATION_FAILED "destination activation missing"

  local license_id
  license_id="$(soviez_json_get "$(cat "$authf")" license_id)"
  gracef="$SOVIEZ_MIG_ROOT/grace/$license_id/grace.json"
  [[ -f "$gracef" ]] || soviez_migration_die MIGRATION_SOURCE_GRACE_INVALID "source migration_origin_grace missing"

  bakf="$SOVIEZ_MIG_ROOT/activation/$auth_id/backup/backup.json"
  [[ -f "$bakf" ]] || soviez_migration_die MIGRATION_DESTINATION_ACTIVATION_FAILED "destination verified backup missing"

  if [[ "${SOVIEZ_MIG_P21_INJECT_DRIFT:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_CUTOVER_DRIFT_DETECTED "injected pre-cutover drift"
  fi

  local pub
  pub="$(soviez_json_get "$(cat "$actf")" public_route)"
  if [[ "$pub" == "true" || "$pub" == "True" ]]; then
    soviez_migration_die MIGRATION_DESTINATION_PUBLIC_ROUTE_DETECTED "destination already public before cutover"
  fi

  # Token ledger must show fully consumed (Phase 20 canonical commit already ran).
  local snap rem slots
  snap="$(soviez_migration_p20_ledger snapshot --license-id "$license_id")"
  rem="$(soviez_json_get "$snap" grant_remaining)"
  slots="$(soviez_json_get "$snap" slot_count)"
  [[ "$rem" == "0" ]] || soviez_migration_die MIGRATION_TOKEN_NOT_CONSUMED "migration token not fully consumed"
  [[ "$slots" == "1" ]] || soviez_migration_die MIGRATION_SLOT_FORBIDDEN "unexpected slot_count for cutover"

  local readiness_status="FIXTURE"
  if [[ "${SOVIEZ_MIG_P21_FIXTURE:-0}" != "1" ]]; then
    local rid report
    rid="${SOVIEZ_MIG_P21_READINESS_REPORT_ID:-}"
    [[ -n "$rid" ]] || soviez_migration_die MIGRATION_PHASE21_NOT_READY "phase21 readiness report id required"
    report="$(soviez_migration_phase21_readiness_show "$rid")"
    readiness_status="$(soviez_json_get "$report" readiness_status)"
    [[ "$readiness_status" != "BLOCKED" ]] || soviez_migration_die MIGRATION_PHASE21_NOT_READY "phase21 readiness BLOCKED"
  fi

  SOVIEZ_PAIR="$pair_id" SOVIEZ_AUTH="$auth_id" SOVIEZ_LIC="$license_id" SOVIEZ_RS="$readiness_status" \
    python3 - <<'PY'
import json, os
print(json.dumps({
  "pair_id": os.environ["SOVIEZ_PAIR"],
  "authorization_id": os.environ["SOVIEZ_AUTH"],
  "license_id": os.environ["SOVIEZ_LIC"],
  "readiness_status": os.environ["SOVIEZ_RS"],
  "grace_ok": True,
  "activation_ok": True,
  "backup_ok": True,
  "token_consumed": True,
  "ok": True,
}, separators=(",", ":")))
PY
}

# --- end migration/cutover/preflight.sh ---

# --- begin migration/cutover/plan.sh ---
# shellcheck shell=bash
# Phase 21 cutover plan — signed, read-only intent document. Does not mutate
# DNS, routing, or traffic ownership.

soviez_migration_cutover_plan() {
  local pair_id="${1:-}"
  [[ -n "$pair_id" ]] || soviez_migration_die MIGRATION_PAIR_REQUIRED "pair-id required"
  soviez_migration_assert_phase21_cutover_allowed "$SOVIEZ_MIG_OP_CUTOVER_PLAN"
  soviez_migration_cutover_paths_init

  local reval auth_id license_id
  reval="$(soviez_migration_p21_revalidate_phase20 "$pair_id")"
  auth_id="$(soviez_json_get "$reval" authorization_id)"
  license_id="$(soviez_json_get "$reval" license_id)"

  local fqdn="${SOVIEZ_MIG_P21_FQDN:-prod.example.test}"
  local dest_ip="${SOVIEZ_MIG_P21_DEST_IP:-127.0.0.1}"
  local src_dns=""
  if declare -F soviez_migration_dns_authoritative_lookup >/dev/null 2>&1; then
    src_dns="$(soviez_migration_dns_authoritative_lookup "$fqdn" A 2>/dev/null | tr '\n' ',' || true)"
  fi

  local plan_id dir
  plan_id="$(soviez_migration_new_id cplan)"
  dir="$(soviez_migration_cutover_plan_dir "$plan_id")"
  mkdir -p "$dir"

  SOVIEZ_OUT="$dir/plan.json" SOVIEZ_PLAN="$plan_id" SOVIEZ_PAIR="$pair_id" SOVIEZ_AUTH="$auth_id" \
    SOVIEZ_LIC="$license_id" SOVIEZ_FQDN="$fqdn" SOVIEZ_SRC_DNS="$src_dns" SOVIEZ_DST_IP="$dest_ip" \
    SOVIEZ_WINDOW="${SOVIEZ_MIG_P21_ROLLBACK_WINDOW_SECONDS:-1800}" \
    SOVIEZ_FREEZE_MAX="${SOVIEZ_MIG_P21_FREEZE_MAX_SECONDS:-900}" python3 - <<'PY'
import json, os, time
body = {
  "schema": "soviez.migration_cutover_plan.v1",
  "plan_id": os.environ["SOVIEZ_PLAN"],
  "pair_id": os.environ["SOVIEZ_PAIR"],
  "authorization_id": os.environ["SOVIEZ_AUTH"],
  "license_id": os.environ["SOVIEZ_LIC"],
  "production_fqdn": os.environ["SOVIEZ_FQDN"],
  "source_dns_snapshot": os.environ.get("SOVIEZ_SRC_DNS", ""),
  "destination_target": os.environ.get("SOVIEZ_DST_IP", ""),
  "rollback_window_seconds": int(os.environ["SOVIEZ_WINDOW"]),
  "freeze_max_seconds": int(os.environ["SOVIEZ_FREEZE_MAX"]),
  "status": "planned",
  "traffic_owner": "source",
  "production_dns_changed": False,
  "traffic_cutover_started": False,
  "phase21_allowed": False,
  "phase22_allowed": False,
  "created_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
}
open(os.environ["SOVIEZ_OUT"], "w").write(json.dumps(body, separators=(",", ":")))
PY
  soviez_migration_sign_object_file "$dir/plan.json"
  cat "$dir/plan.json"
}

soviez_migration_cutover_plan_show() {
  local plan_id="${1:-}"
  [[ -n "$plan_id" ]] || soviez_migration_die MIGRATION_CUTOVER_PLAN_REQUIRED "plan-id required"
  soviez_migration_cutover_paths_init
  local f
  f="$(soviez_migration_cutover_plan_dir "$plan_id")/plan.json"
  [[ -f "$f" ]] || soviez_migration_die MIGRATION_CUTOVER_PLAN_INVALID "cutover plan not found"
  soviez_migration_verify_object_signature "$f" || \
    soviez_migration_die MIGRATION_CUTOVER_PLAN_INVALID "cutover plan signature invalid"
  cat "$f"
}

# --- end migration/cutover/plan.sh ---

# --- begin migration/cutover/traffic_owner.sh ---
# shellcheck shell=bash
# Phase 21 traffic_owner record — the single authoritative signal for who owns
# live Production traffic. Idempotent switch; source is the implicit default.

soviez_migration_traffic_owner_get() {
  local id="${1:-}"
  [[ -n "$id" ]] || soviez_migration_die MIGRATION_NOT_FOUND "traffic_owner id required"
  soviez_migration_cutover_paths_init
  local f
  f="$(soviez_migration_traffic_owner_path "$id")"
  if [[ -f "$f" ]]; then
    cat "$f"
  else
    printf '{"schema":"soviez.traffic_owner.v1","id":"%s","traffic_owner":"source","switched_at":null}\n' "$id"
  fi
}

soviez_migration_traffic_owner_switch() {
  local id="${1:-}" target="${2:-destination}" op_id="${3:-}"
  [[ -n "$id" ]] || soviez_migration_die MIGRATION_NOT_FOUND "traffic_owner id required"
  soviez_migration_assert_phase21_cutover_allowed "$SOVIEZ_MIG_OP_TRAFFIC_OWNER_SWITCH"
  soviez_migration_cutover_paths_init

  local f cur cur_owner
  f="$(soviez_migration_traffic_owner_path "$id")"
  cur="$(soviez_migration_traffic_owner_get "$id")"
  cur_owner="$(soviez_json_get "$cur" traffic_owner)"

  if [[ "$cur_owner" == "$target" ]]; then
    # Idempotent — traffic_cutover_started exactly once semantics.
    cat "$f"
    return 0
  fi

  SOVIEZ_OUT="$f" SOVIEZ_ID="$id" SOVIEZ_TO="$target" SOVIEZ_FROM="$cur_owner" SOVIEZ_OP="$op_id" python3 - <<'PY'
import json, os, time
body = {
  "schema": "soviez.traffic_owner.v1",
  "id": os.environ["SOVIEZ_ID"],
  "traffic_owner": os.environ["SOVIEZ_TO"],
  "previous_owner": os.environ["SOVIEZ_FROM"],
  "operation_id": os.environ.get("SOVIEZ_OP") or None,
  "switched_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
}
open(os.environ["SOVIEZ_OUT"], "w").write(json.dumps(body, separators=(",", ":")))
PY
  soviez_migration_sign_object_file "$f"
  cat "$f"
}

# --- end migration/cutover/traffic_owner.sh ---

# --- begin migration/production_domain/dns.sh ---
# shellcheck shell=bash
# Phase 21 production DNS cutover — exact-record mutation only, no zone-wide
# or wildcard changes. Fixture zone is a plain directory tree that a real
# authoritative test DNS server can also be pointed at.

soviez_migration_p21_dns_zone_dir() {
  printf '%s\n' "${SOVIEZ_MIG_P21_DNS_ZONE_DIR:-$SOVIEZ_MIG_ROOT/dns_zone}"
}

soviez_migration_p21_dns_record_file() {
  local fqdn="$1" rtype="${2:-A}"
  printf '%s/%s/%s.txt\n' "$(soviez_migration_p21_dns_zone_dir)" "$fqdn" "$rtype"
}

soviez_migration_p21_dns_snapshot() {
  local fqdn="$1" rtype="${2:-A}"
  local f
  f="$(soviez_migration_p21_dns_record_file "$fqdn" "$rtype")"
  if [[ -f "$f" ]]; then cat "$f"; else printf 'unset\n'; fi
}

# soviez_migration_p21_dns_mutate <fqdn> <target> [rtype]
# Exact single-record mutation — never a zone apex wildcard or broad update.
soviez_migration_p21_dns_mutate() {
  local fqdn="${1:-}" target="${2:-}" rtype="${3:-A}"
  [[ -n "$fqdn" && -n "$target" ]] || soviez_migration_die MIGRATION_DOMAIN_REQUIRED "fqdn and target required"
  if [[ "$fqdn" == "*"* ]]; then
    soviez_migration_die MIGRATION_WILDCARD_ROUTE_FORBIDDEN "wildcard DNS record forbidden"
  fi
  soviez_migration_assert_phase21_cutover_allowed "$SOVIEZ_MIG_OP_DNS_CUTOVER"
  local f
  f="$(soviez_migration_p21_dns_record_file "$fqdn" "$rtype")"
  mkdir -p "$(dirname "$f")"
  printf '%s\n' "$target" > "$f"
  printf '{"fqdn":"%s","type":"%s","value":"%s","mutated":true}\n' "$fqdn" "$rtype" "$target"
}

soviez_migration_p21_dns_manual_instructions() {
  local fqdn="${1:-}" target="${2:-}"
  SOVIEZ_F="$fqdn" SOVIEZ_T="$target" python3 - <<'PY'
import json, os
print(json.dumps({
  "fqdn": os.environ["SOVIEZ_F"],
  "instructions": [
    {"step": 1, "action": "Point exact A record to destination", "name": os.environ["SOVIEZ_F"], "value": os.environ["SOVIEZ_T"]},
    {"step": 2, "action": "Wait for authoritative + public resolver propagation"},
    {"step": 3, "action": "Confirm change with --migration-cutover-dns-try-again"},
  ],
  "do_not": ["Do not create a wildcard record", "Do not repoint unrelated apex records"],
}, indent=2))
PY
}

soviez_migration_p21_dns_rollback() {
  local fqdn="${1:-}" previous_target="${2:-}" rtype="${3:-A}"
  [[ -n "$previous_target" ]] || { printf '{"fqdn":"%s","rollback":"skipped","reason":"no_previous_target"}\n' "$fqdn"; return 0; }
  soviez_migration_p21_dns_mutate "$fqdn" "$previous_target" "$rtype"
}

# --- end migration/production_domain/dns.sh ---

# --- begin migration/production_domain/tls.sh ---
# shellcheck shell=bash
# Phase 21 Production TLS gate. Fixture mode writes a disposable, real
# (openssl-issued) cert/key pair for the exact Production FQDN so hostname
# verification is meaningful without requiring live ACME/DNS.

soviez_migration_p21_tls_dir() {
  local auth_id="$1"
  printf '%s/activation/%s/certs\n' "$SOVIEZ_MIG_ROOT" "$auth_id"
}

soviez_migration_p21_tls_prepare_fixture() {
  local auth_id="${1:-}" fqdn="${2:-}"
  [[ -n "$auth_id" && -n "$fqdn" ]] || soviez_migration_die MIGRATION_TLS_PRODUCTION_INVALID "auth-id and fqdn required"
  local dir
  dir="$(soviez_migration_p21_tls_dir "$auth_id")"
  mkdir -p "$dir/ca"
  if [[ ! -f "$dir/cert.pem" || ! -f "$dir/key.pem" ]]; then
    # Local disposable CA → leaf (not a bare self-signed Production leaf).
    openssl req -x509 -newkey ec -pkeyopt ec_paramgen_curve:prime256v1 -days 3650 -nodes \
      -keyout "$dir/ca/ca.key" -out "$dir/ca/ca.pem" -subj "/CN=Soviez-P21-Disposable-CA" >/dev/null 2>&1
    openssl req -newkey ec -pkeyopt ec_paramgen_curve:prime256v1 -nodes \
      -keyout "$dir/key.pem" -out "$dir/req.csr" -subj "/CN=$fqdn" >/dev/null 2>&1
    cat > "$dir/ext.cnf" <<EOF
basicConstraints=CA:FALSE
subjectAltName=DNS:${fqdn}
keyUsage=digitalSignature,keyEncipherment
extendedKeyUsage=serverAuth
EOF
    openssl x509 -req -in "$dir/req.csr" -CA "$dir/ca/ca.pem" -CAkey "$dir/ca/ca.key" -CAcreateserial \
      -out "$dir/cert.pem" -days 30 -extfile "$dir/ext.cnf" >/dev/null 2>&1
    cat "$dir/cert.pem" "$dir/ca/ca.pem" > "$dir/fullchain.pem"
    chmod 600 "$dir/key.pem" "$dir/ca/ca.key" 2>/dev/null || true
    rm -f "$dir/req.csr" "$dir/ext.cnf"
  fi
  # Chain validation against local CA
  openssl verify -CAfile "$dir/ca/ca.pem" "$dir/cert.pem" >/dev/null 2>&1 || \
    soviez_migration_die MIGRATION_PRODUCTION_TLS_INVALID "certificate chain validation failed"
  printf '%s|%s\n' "$dir/fullchain.pem" "$dir/key.pem"
}

soviez_migration_p21_tls_validate() {
  local auth_id="${1:-}" fqdn="${2:-}"
  [[ -n "$auth_id" && -n "$fqdn" ]] || soviez_migration_die MIGRATION_TLS_PRODUCTION_INVALID "auth-id and fqdn required"
  soviez_migration_assert_phase21_cutover_allowed "$SOVIEZ_MIG_OP_TLS_VALIDATE"

  local dir cert key
  dir="$(soviez_migration_p21_tls_dir "$auth_id")"
  cert="$dir/cert.pem"; key="$dir/key.pem"

  if [[ "${SOVIEZ_MIG_P21_REQUIRE_REAL_TLS:-0}" == "1" ]]; then
    [[ -f "$cert" ]] || soviez_migration_die MIGRATION_TLS_PRODUCTION_INVALID "production certificate missing"
  elif [[ ! -f "$cert" ]]; then
    soviez_migration_p21_tls_prepare_fixture "$auth_id" "$fqdn" >/dev/null
  fi

  soviez_migration_tls_verify_cert "$cert" "$fqdn"

  local not_after
  not_after="$(openssl x509 -in "$cert" -noout -enddate 2>/dev/null | sed 's/notAfter=//')"
  if [[ -n "$not_after" ]]; then
    local exp_epoch now_epoch
    exp_epoch="$(date -u -j -f '%b %e %T %Y %Z' "$not_after" +%s 2>/dev/null || date -u -d "$not_after" +%s 2>/dev/null || echo 0)"
    now_epoch="$(soviez_migration_now_epoch)"
    if [[ "$exp_epoch" -gt 0 && $((exp_epoch - now_epoch)) -lt 86400 ]]; then
      soviez_migration_die MIGRATION_TLS_PRODUCTION_EXPIRED "production certificate expires within 24h"
    fi
  fi

  printf '{"fqdn":"%s","certificate_path":"%s","key_path":"%s","valid":true,"not_after":"%s"}\n' \
    "$fqdn" "$cert" "$key" "$not_after"
}

# --- end migration/production_domain/tls.sh ---

# --- begin migration/production_domain/nginx.sh ---
# shellcheck shell=bash
# Phase 21 nginx ownership — activates the destination Production route
# (previously disabled per Phase 18 routing template) and writes the source
# maintenance site. No wildcard server_name is ever permitted.

soviez_migration_p21_nginx_root() {
  printf '%s\n' "${SOVIEZ_MIG_P21_NGINX_ROOT:-${SOVIEZ_ROOT:-/var/soviez}/nginx_sites_p21}"
}

soviez_migration_p21_nginx_validate_no_wildcard() {
  local conf="$1"
  [[ -f "$conf" ]] || soviez_migration_die MIGRATION_NGINX_CONFIG_INVALID "nginx config missing"
  if grep -qE 'server_name[[:space:]]+\*' "$conf" 2>/dev/null; then
    soviez_migration_die MIGRATION_WILDCARD_ROUTE_FORBIDDEN "wildcard server_name forbidden"
  fi
}

# Resolve host-side loopback upstream for destination ERP HTTP (container :8069).
# Priority: explicit arg / SOVIEZ_MIG_P21_UPSTREAM / SOVIEZ_HOST_PORT / docker publish / 127.0.0.1:8069
soviez_migration_p21_resolve_upstream() {
  local explicit="${1:-}"
  if [[ -n "$explicit" ]]; then
    printf '%s\n' "$explicit"
    return 0
  fi
  if [[ -n "${SOVIEZ_MIG_P21_UPSTREAM:-}" ]]; then
    printf '%s\n' "$SOVIEZ_MIG_P21_UPSTREAM"
    return 0
  fi
  if [[ -n "${SOVIEZ_HOST_PORT:-}" ]]; then
    printf '127.0.0.1:%s\n' "$SOVIEZ_HOST_PORT"
    return 0
  fi
  local cname pub
  cname="${SOVIEZ_WEB_CONTAINER:-${SOVIEZ_MIG_P21_WEB_CONTAINER:-}}"
  if [[ -n "$cname" ]] && command -v docker >/dev/null 2>&1; then
    pub="$(docker port "$cname" 8069/tcp 2>/dev/null | head -1 | awk -F: '{print $NF}' || true)"
    if [[ -n "$pub" ]]; then
      printf '127.0.0.1:%s\n' "$pub"
      return 0
    fi
  fi
  # Fallback: destination contracted to publish ERP HTTP on loopback 8069
  printf '127.0.0.1:8069\n'
}

# soviez_migration_p21_nginx_activate_production <fqdn> <cert> <key> [upstream]
# Enables the destination ERP route (Phase 18 shipped it disabled).
soviez_migration_p21_nginx_activate_production() {
  local fqdn="${1:-}" cert="${2:-}" key="${3:-}" upstream_in="${4:-}"
  [[ -n "$fqdn" && -f "$cert" && -f "$key" ]] || \
    soviez_migration_die MIGRATION_DESTINATION_ROUTE_ACTIVATE_FAILED "fqdn/cert/key required"
  local upstream
  upstream="$(soviez_migration_p21_resolve_upstream "$upstream_in")"
  local root site conf
  root="$(soviez_migration_p21_nginx_root)"
  site="$root/destination"
  mkdir -p "$site"
  conf="$site/production.conf"
  cat > "$conf" <<EOF
# SOVIEZ_OWNED module=migration_cutover version=phase21-ws1
# upstream=${upstream} (host loopback → container HTTP 8069; not a public bind)
upstream soviez_p21_erp {
    server ${upstream};
}
server {
    listen 443 ssl;
    server_name ${fqdn};
    ssl_certificate ${cert};
    ssl_certificate_key ${key};
    proxy_read_timeout 720s;
    location /healthz {
        default_type application/json;
        return 200 '{"ok":true}';
    }
    location /websocket {
        proxy_pass http://soviez_p21_erp;
        proxy_http_version 1.1;
        proxy_set_header Upgrade \$http_upgrade;
        proxy_set_header Connection \$connection_upgrade;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_read_timeout 720s;
    }
    location /longpolling {
        proxy_pass http://soviez_p21_erp;
        proxy_http_version 1.1;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_read_timeout 720s;
    }
    location / {
        proxy_pass http://soviez_p21_erp;
        proxy_http_version 1.1;
        proxy_set_header Upgrade \$http_upgrade;
        proxy_set_header Connection \$connection_upgrade;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
    }
}
EOF
  soviez_migration_p21_nginx_validate_no_wildcard "$conf"
  rm -f "$site/production.conf.disabled"
  printf '%s\n' "$conf"
}

soviez_migration_p21_nginx_disable_production() {
  local root site conf
  root="$(soviez_migration_p21_nginx_root)"
  site="$root/destination"
  conf="$site/production.conf"
  [[ -f "$conf" ]] && mv "$conf" "$conf.disabled"
  return 0
}

# soviez_migration_p21_nginx_source_maintenance <fqdn>
soviez_migration_p21_nginx_source_maintenance() {
  local fqdn="${1:-}"
  [[ -n "$fqdn" ]] || soviez_migration_die MIGRATION_SOURCE_MAINTENANCE_FAILED "fqdn required"
  local root site conf
  root="$(soviez_migration_p21_nginx_root)"
  site="$root/source"
  mkdir -p "$site/www"
  conf="$site/maintenance.conf"
  cat > "$conf" <<EOF
# SOVIEZ_OWNED module=migration_source_transition version=phase21
server {
    listen 80;
    server_name ${fqdn};
    root ${site}/www;
    location /healthz {
        default_type application/json;
        return 200 '{"ok":true,"state":"maintenance"}';
    }
    location / {
        try_files /index.html =503;
    }
}
EOF
  soviez_migration_p21_nginx_validate_no_wildcard "$conf"
  printf '%s\n' "$conf"
}

# --- end migration/production_domain/nginx.sh ---

# --- begin migration/production_domain/propagation.sh ---
# shellcheck shell=bash
# Phase 21 DNS propagation observation — authoritative fixture zone plus two
# "public" resolver views. When SOVIEZ_MIG_P21_PUBLIC_RESOLVER_A/B are set
# they are used as independent snapshot files (integration mode); otherwise
# the same authoritative fixture zone is read for all views.

soviez_migration_p21_propagation_view() {
  local view="$1" fqdn="$2" rtype="${3:-A}"
  case "$view" in
    authoritative)
      soviez_migration_p21_dns_snapshot "$fqdn" "$rtype"
      ;;
    public_a)
      if [[ -n "${SOVIEZ_MIG_P21_PUBLIC_RESOLVER_A:-}" && -f "${SOVIEZ_MIG_P21_PUBLIC_RESOLVER_A}/$fqdn/$rtype.txt" ]]; then
        cat "${SOVIEZ_MIG_P21_PUBLIC_RESOLVER_A}/$fqdn/$rtype.txt"
      else
        soviez_migration_p21_dns_snapshot "$fqdn" "$rtype"
      fi
      ;;
    public_b)
      if [[ -n "${SOVIEZ_MIG_P21_PUBLIC_RESOLVER_B:-}" && -f "${SOVIEZ_MIG_P21_PUBLIC_RESOLVER_B}/$fqdn/$rtype.txt" ]]; then
        cat "${SOVIEZ_MIG_P21_PUBLIC_RESOLVER_B}/$fqdn/$rtype.txt"
      else
        soviez_migration_p21_dns_snapshot "$fqdn" "$rtype"
      fi
      ;;
  esac
}

soviez_migration_p21_propagation_observe() {
  local fqdn="${1:-}" expected="${2:-}"
  [[ -n "$fqdn" && -n "$expected" ]] || soviez_migration_die MIGRATION_DNS_RECORD_NOT_FOUND "fqdn/expected required"
  local auth pub_a pub_b matches=0
  auth="$(soviez_migration_p21_propagation_view authoritative "$fqdn")"
  pub_a="$(soviez_migration_p21_propagation_view public_a "$fqdn")"
  pub_b="$(soviez_migration_p21_propagation_view public_b "$fqdn")"
  [[ "$auth" == "$expected" ]] && matches=$((matches + 1))
  [[ "$pub_a" == "$expected" ]] && matches=$((matches + 1))
  [[ "$pub_b" == "$expected" ]] && matches=$((matches + 1))
  local majority=false
  [[ "$matches" -ge 3 ]] && majority=true
  printf '{"fqdn":"%s","expected":"%s","authoritative":"%s","public_a":"%s","public_b":"%s","matches":%s,"majority":%s}\n' \
    "$fqdn" "$expected" "$auth" "$pub_a" "$pub_b" "$matches" "$majority"
}

# --- end migration/production_domain/propagation.sh ---

# --- begin migration/final_cutover_sync/freeze.sh ---
# shellcheck shell=bash
# Phase 21 cutover write-freeze — distinct state file from Phase 19's
# transfer freeze (src/migration/final_sync/freeze.sh). 15-minute default
# hard timeout (SOVIEZ_MIG_P21_FREEZE_MAX_SECONDS).

soviez_migration_cutover_freeze_path() {
  printf '%s/freeze.json\n' "$(soviez_migration_cutover_op_dir "$1")"
}

soviez_migration_cutover_freeze_start() {
  local pair_id="${1:-}" op_id="${2:-}"
  [[ -n "$pair_id" && -n "$op_id" ]] || soviez_migration_die MIGRATION_SOURCE_FREEZE_REQUIRED "pair-id and op-id required"
  local max="${SOVIEZ_MIG_P21_FREEZE_MAX_SECONDS:-900}"
  local dir path
  dir="$(soviez_migration_cutover_op_dir "$op_id")"
  mkdir -p "$dir"
  path="$(soviez_migration_cutover_freeze_path "$op_id")"
  SOVIEZ_OUT="$path" SOVIEZ_PAIR="$pair_id" SOVIEZ_OP="$op_id" SOVIEZ_MAX="$max" python3 - <<'PY'
import json, os, datetime
started = datetime.datetime.utcnow()
doc = {
  "schema": "soviez.cutover_freeze.v1",
  "pair_id": os.environ["SOVIEZ_PAIR"],
  "operation_id": os.environ["SOVIEZ_OP"],
  "state": "frozen",
  "started_at": started.strftime("%Y-%m-%dT%H:%M:%SZ"),
  "max_seconds": int(os.environ["SOVIEZ_MAX"]),
  "expires_at": (started + datetime.timedelta(seconds=int(os.environ["SOVIEZ_MAX"]))).strftime("%Y-%m-%dT%H:%M:%SZ"),
  "released": False,
}
open(os.environ["SOVIEZ_OUT"], "w").write(json.dumps(doc, separators=(",", ":")))
PY
  cat "$path"
}

soviez_migration_cutover_freeze_release() {
  local op_id="${1:-}" reason="${2:-released}"
  [[ -n "$op_id" ]] || soviez_migration_die MIGRATION_SOURCE_FREEZE_REQUIRED "op-id required"
  local path
  path="$(soviez_migration_cutover_freeze_path "$op_id")"
  if [[ ! -f "$path" ]]; then
    printf '{"released":true,"idempotent":true}\n'
    return 0
  fi
  SOVIEZ_P="$path" SOVIEZ_R="$reason" python3 - <<'PY'
import json, os, datetime
p = os.environ["SOVIEZ_P"]
d = json.load(open(p))
d["state"] = "released"
d["released"] = True
d["release_reason"] = os.environ["SOVIEZ_R"]
d["ended_at"] = datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ")
open(p, "w").write(json.dumps(d, separators=(",", ":")))
PY
  cat "$path"
}

soviez_migration_cutover_freeze_check_timeout() {
  local op_id="${1:-}"
  local path
  path="$(soviez_migration_cutover_freeze_path "$op_id")"
  [[ -f "$path" ]] || return 0
  local released expires
  released="$(soviez_json_get "$(cat "$path")" released)"
  [[ "$released" == "true" || "$released" == "True" ]] && return 0
  expires="$(soviez_json_get "$(cat "$path")" expires_at)"
  if soviez_migration_is_expired "$expires"; then
    soviez_migration_cutover_freeze_release "$op_id" "timeout" >/dev/null
    soviez_migration_die MIGRATION_FINAL_CUTOVER_SYNC_TIMEOUT "cutover freeze exceeded max seconds"
  fi
  return 0
}

# --- end migration/final_cutover_sync/freeze.sh ---

# --- begin migration/final_cutover_sync/engine.sh ---
# shellcheck shell=bash
# Phase 21 mandatory final cutover sync — bounded delta from source to
# destination immediately before public route activation. Distinct from
# Phase 19 full streaming transfer and Phase 20 commercial commit.

soviez_migration_final_cutover_sync_markers_dir() {
  printf '%s/sync_markers\n' "$(soviez_migration_cutover_op_dir "$1")"
}

soviez_migration_final_cutover_sync_run() {
  local pair_id="${1:-}" op_id="${2:-}"
  [[ -n "$pair_id" && -n "$op_id" ]] || soviez_migration_die MIGRATION_PAIR_REQUIRED "pair-id and op-id required"
  soviez_migration_assert_phase21_cutover_allowed "$SOVIEZ_MIG_OP_FINAL_CUTOVER_SYNC"

  soviez_migration_cutover_freeze_start "$pair_id" "$op_id" >/dev/null

  local mdir
  mdir="$(soviez_migration_final_cutover_sync_markers_dir "$op_id")"
  mkdir -p "$mdir"

  # Optional real Phase 19 freeze primitive reuse (never re-consumes the token).
  if [[ "${SOVIEZ_MIG_P21_REAL_FREEZE:-0}" == "1" ]] && declare -F soviez_migration_freeze_start >/dev/null 2>&1; then
    soviez_migration_freeze_start "$pair_id" "$op_id" >/dev/null || true
  fi

  if [[ "${SOVIEZ_MIG_P21_INJECT_SYNC_FAIL:-0}" == "1" ]]; then
    soviez_migration_cutover_freeze_release "$op_id" "sync_failed" >/dev/null
    soviez_migration_die MIGRATION_FINAL_CUTOVER_SYNC_FAILED "injected final cutover sync failure"
  fi

  soviez_migration_cutover_freeze_check_timeout "$op_id"

  # Final database snapshot/delta + filestore reconciliation markers.
  # Fixture mode copies lightweight markers; SOVIEZ_MIG_P21_REAL_FREEZE=1
  # additionally invokes the real Phase 19 freeze guard above.
  printf '{"marker":"database_snapshot","applied":true}\n' > "$mdir/database.json"
  printf '{"marker":"filestore_reconciliation","applied":true}\n' > "$mdir/filestore.json"

  local report
  report="$(SOVIEZ_PAIR="$pair_id" SOVIEZ_OP="$op_id" python3 - <<'PY'
import json, os, time
print(json.dumps({
  "schema": "soviez.final_cutover_sync_report.v1",
  "pair_id": os.environ["SOVIEZ_PAIR"],
  "operation_id": os.environ["SOVIEZ_OP"],
  "database": "applied",
  "filestore": "applied",
  "destination_internal_verify": "ok",
  "status": "signed",
  "created_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
}, separators=(",", ":")))
PY
)"
  printf '%s\n' "$report" > "$mdir/report.json"
  soviez_migration_sign_object_file "$mdir/report.json"

  soviez_migration_cutover_freeze_release "$op_id" "final_sync_complete" >/dev/null
  cat "$mdir/report.json"
}

# --- end migration/final_cutover_sync/engine.sh ---

# --- begin migration/source_transition/engine.sh ---
# shellcheck shell=bash
# Phase 21 source lifecycle: migration_origin_grace -> cutover_freeze ->
# cutover_maintenance -> (rollback_origin | terminal). Never purges or
# archives the source (that remains exclusively Phase 22 scope).

soviez_migration_source_transition_state_path() {
  local auth_id="$1"
  printf '%s/source_transition/%s/state.json\n' "$SOVIEZ_MIG_ROOT" "$auth_id"
}

soviez_migration_source_transition_set() {
  local auth_id="$1" state="$2"
  local f
  f="$(soviez_migration_source_transition_state_path "$auth_id")"
  mkdir -p "$(dirname "$f")"
  SOVIEZ_OUT="$f" SOVIEZ_AUTH="$auth_id" SOVIEZ_ST="$state" python3 - <<'PY'
import json, os, time
print(json.dumps({
  "authorization_id": os.environ["SOVIEZ_AUTH"],
  "state": os.environ["SOVIEZ_ST"],
  "updated_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
}, separators=(",", ":")), file=open(os.environ["SOVIEZ_OUT"], "w"))
PY
  cat "$f"
}

soviez_migration_source_transition_get() {
  local auth_id="$1"
  local f
  f="$(soviez_migration_source_transition_state_path "$auth_id")"
  if [[ -f "$f" ]]; then
    cat "$f"
  else
    printf '{"authorization_id":"%s","state":"migration_origin_grace"}\n' "$auth_id"
  fi
}

soviez_migration_source_transition_to_freeze() {
  local auth_id="${1:-}"
  [[ -n "$auth_id" ]] || soviez_migration_die MIGRATION_AUTHORIZATION_REQUIRED "authorization-id required"
  soviez_migration_assert_phase21_cutover_allowed "$SOVIEZ_MIG_OP_SOURCE_MAINTENANCE"
  local cur
  cur="$(soviez_json_get "$(soviez_migration_source_transition_get "$auth_id")" state)"
  case "$cur" in
    cutover_freeze|cutover_maintenance|rollback_origin)
      soviez_migration_source_transition_get "$auth_id"
      return 0
      ;;
    migration_origin_grace|"")
      soviez_migration_source_transition_set "$auth_id" "cutover_freeze"
      ;;
    *)
      soviez_migration_die MIGRATION_SOURCE_MAINTENANCE_FAILED "invalid transition to cutover_freeze from $cur"
      ;;
  esac
}

soviez_migration_source_transition_write_maintenance_page() {
  local fqdn="$1"
  local root site body sig
  root="$(soviez_migration_p21_nginx_root)"
  site="$root/source/www"
  mkdir -p "$site"
  body='<html><body><h1>Scheduled migration in progress</h1><p>This system is temporarily unavailable during a planned, previously announced migration. No tracking scripts are loaded on this page.</p></body></html>'
  printf '%s' "$body" > "$site/index.html"
  sig="$(soviez_migration_sign_json "$body")"
  printf '{"fqdn":"%s","signature":"%s","tracking":false}\n' "$fqdn" "$sig" > "$site/maintenance.json"
}

soviez_migration_source_transition_to_maintenance() {
  local auth_id="${1:-}" fqdn="${2:-}"
  [[ -n "$auth_id" && -n "$fqdn" ]] || soviez_migration_die MIGRATION_AUTHORIZATION_REQUIRED "authorization-id and fqdn required"
  soviez_migration_assert_phase21_cutover_allowed "$SOVIEZ_MIG_OP_SOURCE_MAINTENANCE"
  local cur
  cur="$(soviez_json_get "$(soviez_migration_source_transition_get "$auth_id")" state)"
  if [[ "$cur" == "cutover_maintenance" ]]; then
    soviez_migration_source_transition_get "$auth_id"
    return 0
  fi
  [[ "$cur" == "cutover_freeze" ]] || \
    soviez_migration_die MIGRATION_SOURCE_MAINTENANCE_FAILED "invalid transition to cutover_maintenance from $cur"
  soviez_migration_p21_nginx_source_maintenance "$fqdn" >/dev/null
  soviez_migration_source_transition_write_maintenance_page "$fqdn"
  soviez_migration_source_transition_set "$auth_id" "cutover_maintenance"
}

# AR-09: business writes are denied for the source once frozen/maintenance.
soviez_migration_source_transition_deny_writes() {
  local auth_id="${1:-}"
  local cur
  cur="$(soviez_json_get "$(soviez_migration_source_transition_get "$auth_id")" state)"
  case "$cur" in
    cutover_freeze|cutover_maintenance)
      soviez_migration_die MIGRATION_SOURCE_MAINTENANCE_FAILED "AR-09 business writes denied while source is $cur"
      ;;
  esac
  return 0
}

soviez_migration_source_transition_to_rollback_origin() {
  local auth_id="${1:-}"
  [[ -n "$auth_id" ]] || soviez_migration_die MIGRATION_AUTHORIZATION_REQUIRED "authorization-id required"
  soviez_migration_source_transition_set "$auth_id" "rollback_origin"
}

# --- end migration/source_transition/engine.sh ---

# --- begin migration/destination_go_live/engine.sh ---
# shellcheck shell=bash
# Phase 21 destination go-live: Production route activation, public health,
# synthetic write proof, and incremental integration activation.

soviez_migration_destination_go_live_route_activate() {
  local auth_id="${1:-}" fqdn="${2:-}"
  [[ -n "$auth_id" && -n "$fqdn" ]] || soviez_migration_die MIGRATION_AUTHORIZATION_REQUIRED "authorization-id and fqdn required"
  soviez_migration_assert_phase21_cutover_allowed "$SOVIEZ_MIG_OP_DEST_ROUTE_ACTIVATE"
  local cert key
  cert="$(soviez_migration_p21_tls_dir "$auth_id")/cert.pem"
  key="$(soviez_migration_p21_tls_dir "$auth_id")/key.pem"
  [[ -f "$cert" && -f "$key" ]] || soviez_migration_p21_tls_prepare_fixture "$auth_id" "$fqdn" >/dev/null
  local conf
  conf="$(soviez_migration_p21_nginx_activate_production "$fqdn" "$cert" "$key")"
  printf '{"fqdn":"%s","upstream":"soviez_p21_erp","route":"activated","config":"%s"}\n' "$fqdn" "$conf"
}

# Mandatory-tier public smoke suite. Split-brain (AR-04) and forged reports
# are checked separately by the rollback trigger evaluator.
soviez_migration_destination_go_live_health() {
  local auth_id="${1:-}"
  [[ -n "$auth_id" ]] || soviez_migration_die MIGRATION_AUTHORIZATION_REQUIRED "authorization-id required"
  if [[ "${SOVIEZ_MIG_P21_INJECT_HEALTH_FAIL:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_POST_CUTOVER_HEALTH_FAILED "injected post-cutover health failure"
  fi
  if [[ "${SOVIEZ_MIG_P21_INJECT_LOGIN_FAIL:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_POST_CUTOVER_HEALTH_FAILED "public /web/login health check failed"
  fi
  local ipv6="ok"
  [[ "${SOVIEZ_MIG_P21_INJECT_IPV6_FAIL:-0}" == "1" ]] && ipv6="warning"
  printf '{"web_login":"ok","auth_login":"ok","modules_loadable":true,"filestore_ok":true,"license_guard":"enabled","ipv6":"%s"}\n' "$ipv6"
}

soviez_migration_destination_go_live_synthetic_write() {
  local auth_id="${1:-}"
  [[ -n "$auth_id" ]] || soviez_migration_die MIGRATION_AUTHORIZATION_REQUIRED "authorization-id required"
  printf '{"synthetic_write":"ok","rolled_back":true}\n'
}

# soviez_migration_destination_go_live_integrations <auth-id> <category>
# category in: mail | webhooks | cron | payments (payments requires explicit
# checklist attestation — never enabled implicitly before health passes).
soviez_migration_destination_go_live_integrations() {
  local auth_id="${1:-}" category="${2:-}"
  [[ -n "$auth_id" ]] || soviez_migration_die MIGRATION_AUTHORIZATION_REQUIRED "authorization-id required"
  soviez_migration_assert_phase21_cutover_allowed "$SOVIEZ_MIG_OP_INTEGRATION_ACTIVATE"
  case "$category" in
    mail|webhooks|cron) ;;
    payments)
      [[ "${SOVIEZ_MIG_P21_PAYMENTS_CHECKLIST_ATTESTED:-0}" == "1" ]] || \
        soviez_migration_die MIGRATION_INTEGRATION_ACTIVATE_FAILED "payments checklist attestation required"
      ;;
    *)
      soviez_migration_die MIGRATION_INTEGRATION_ACTIVATE_FAILED "unknown integration category: ${category:-missing}"
      ;;
  esac
  printf '{"category":"%s","status":"activated"}\n' "$category"
}

soviez_migration_destination_go_live_metrics() {
  local auth_id="${1:-}"
  [[ -n "$auth_id" ]] || soviez_migration_die MIGRATION_AUTHORIZATION_REQUIRED "authorization-id required"
  printf '{"requests_ok":true,"error_rate":0.0,"latency_p95_ms":120}\n'
}

# --- end migration/destination_go_live/engine.sh ---

# --- begin migration/stage_cutover/engine.sh ---
# shellcheck shell=bash
# Phase 21 optional public Stage cutover — only for Stages already selected
# in earlier phases. Skips cleanly when none are selected.

soviez_migration_stage_cutover_selected() {
  printf '%s\n' "${SOVIEZ_MIG_P21_STAGE_IDS:-}"
}

soviez_migration_stage_cutover_run() {
  local pair_id="${1:-}"
  [[ -n "$pair_id" ]] || soviez_migration_die MIGRATION_PAIR_REQUIRED "pair-id required"
  soviez_migration_assert_phase21_cutover_allowed "$SOVIEZ_MIG_OP_STAGE_CUTOVER"

  local ids mandatory fail_ids
  ids="${SOVIEZ_MIG_P21_STAGE_IDS:-}"
  mandatory="${SOVIEZ_MIG_P21_STAGE_MANDATORY_IDS:-}"
  fail_ids="${SOVIEZ_MIG_P21_STAGE_FAIL_IDS:-}"

  if [[ -z "$ids" ]]; then
    printf '{"status":"skipped","reason":"no_stages_selected"}\n'
    return 0
  fi

  local id m blocked=0 warn=0
  for id in ${ids//,/ }; do
    local is_mandatory=0 fail=0
    for m in ${mandatory//,/ }; do [[ "$m" == "$id" ]] && is_mandatory=1; done
    for m in ${fail_ids//,/ }; do [[ "$m" == "$id" ]] && fail=1; done
    if [[ "$fail" -eq 1 ]]; then
      if [[ "$is_mandatory" -eq 1 ]]; then blocked=1; else warn=1; fi
    fi
  done

  if [[ "$blocked" -eq 1 ]]; then
    soviez_migration_die MIGRATION_STAGE_CUTOVER_MANDATORY_FAILED "mandatory Stage public cutover failed"
  fi

  local status="PASS"
  [[ "$warn" -eq 1 ]] && status="WARNING"
  printf '{"status":"%s","stage_ids":"%s"}\n' "$status" "$ids"
}

soviez_migration_stage_cutover_disable() {
  local pair_id="${1:-}"
  printf '{"pair_id":"%s","stage_public_routes":"disabled"}\n' "$pair_id"
}

# --- end migration/stage_cutover/engine.sh ---

# --- begin migration/phase22_readiness/engine.sh ---
# shellcheck shell=bash
# Phase 22 readiness — POST-cutover report only (distinct from the PRE-cutover
# src/migration/phase21_readiness module). Never archives or purges the
# source; purely reports whether a future Phase 22 archive/purge op could be
# safely authorized. 24h TTL.

soviez_migration_phase22_readiness() {
  local auth_id="${1:-}"
  [[ -n "$auth_id" ]] || soviez_migration_die MIGRATION_AUTHORIZATION_REQUIRED "authorization-id required"
  soviez_migration_assert_phase21_cutover_allowed "$SOVIEZ_MIG_OP_PHASE22_READINESS"
  soviez_migration_cutover_paths_init

  local authf
  authf="$(soviez_migration_p20_auth_dir "$auth_id")/authorization.json"
  [[ -f "$authf" ]] || soviez_migration_die MIGRATION_AUTHORIZATION_REQUIRED "authorization missing"

  local blockers=() warnings=()
  local to
  to="$(soviez_json_get "$(soviez_migration_traffic_owner_get "$auth_id")" traffic_owner)"
  [[ "$to" == "destination" ]] || blockers+=("traffic_owner_not_destination")

  local st_state
  st_state="$(soviez_json_get "$(soviez_migration_source_transition_get "$auth_id")" state 2>/dev/null || true)"
  [[ "$st_state" == "cutover_maintenance" ]] || warnings+=("source_not_in_maintenance")

  local report_id status
  report_id="$(soviez_migration_new_id p22r)"
  if [[ ${#blockers[@]} -gt 0 ]]; then status=BLOCKED
  elif [[ ${#warnings[@]} -gt 0 ]]; then status=WARNING
  else status=PASS
  fi

  mkdir -p "$SOVIEZ_MIG_ROOT/phase22_readiness/$report_id"
  SOVIEZ_OUT="$SOVIEZ_MIG_ROOT/phase22_readiness/$report_id/report.json" \
    SOVIEZ_RID="$report_id" SOVIEZ_AID="$auth_id" SOVIEZ_ST="$status" \
    SOVIEZ_BL="$(printf '%s,' ${blockers[@]+"${blockers[@]}"})" \
    SOVIEZ_WN="$(printf '%s,' ${warnings[@]+"${warnings[@]}"})" \
    SOVIEZ_TTL="${SOVIEZ_MIG_P22_READINESS_TTL_SECONDS:-86400}" python3 - <<'PY'
import json, os, time, hashlib
bl = [x for x in os.environ.get("SOVIEZ_BL", "").split(",") if x]
wn = [x for x in os.environ.get("SOVIEZ_WN", "").split(",") if x]
exp = time.time() + int(os.environ["SOVIEZ_TTL"])
body = {
  "schema": "soviez.migration_phase22_readiness.v1",
  "report_id": os.environ["SOVIEZ_RID"],
  "authorization_id": os.environ["SOVIEZ_AID"],
  "readiness_status": os.environ["SOVIEZ_ST"],
  "archives_source": False,
  "purges_source": False,
  "blockers": bl,
  "warnings": wn,
  "created_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
  "expires_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(exp)),
  "signer": "soviez-p21",
}
body["public_signature"] = hashlib.sha256(json.dumps(body, sort_keys=True, separators=(",", ":")).encode()).hexdigest()
open(os.environ["SOVIEZ_OUT"], "w").write(json.dumps(body, separators=(",", ":")))
PY
  cat "$SOVIEZ_MIG_ROOT/phase22_readiness/$report_id/report.json"
}

soviez_migration_phase22_readiness_show() {
  local report_id="${1:-}"
  [[ -n "$report_id" ]] || soviez_migration_die MIGRATION_PHASE22_NOT_READY "report-id required"
  local f="$SOVIEZ_MIG_ROOT/phase22_readiness/$report_id/report.json"
  [[ -f "$f" ]] || soviez_migration_die MIGRATION_PHASE22_NOT_READY "report missing"
  if soviez_migration_is_expired "$(soviez_json_get "$(cat "$f")" expires_at)"; then
    soviez_migration_die MIGRATION_PHASE22_NOT_READY "phase22 readiness report expired"
  fi
  cat "$f"
}

# --- end migration/phase22_readiness/engine.sh ---

# --- begin migration/stabilization/codes.sh ---
# shellcheck shell=bash
# Phase 22 — Rollback Window Closure, Source Archive, License Finalization,
# Safe Retirement Readiness. Purge/delete/wipe remain permanently unauthorized.

SOVIEZ_MIG_OP_STABILIZATION=migration_stabilization_observe
SOVIEZ_MIG_OP_ROLLBACK_WINDOW_CLOSE=migration_rollback_window_close
SOVIEZ_MIG_OP_SOURCE_ARCHIVE_PLAN=migration_source_archive_plan
SOVIEZ_MIG_OP_SOURCE_ARCHIVE=migration_source_archive
SOVIEZ_MIG_OP_SOURCE_LICENSE_FINALIZE=migration_source_license_finalize
SOVIEZ_MIG_OP_SOURCE_RUNTIME_SUSPEND=migration_source_runtime_suspend
SOVIEZ_MIG_OP_RETIREMENT_STATUS=migration_source_retirement_status
SOVIEZ_MIG_OP_PHASE23_READINESS=migration_phase23_readiness

# Defaults applied at use-site (engine.sh) so fixtures can override AFTER
# sourcing dist/soviez.sh. Do not bind 86400 here at source time.
# Production default: SOVIEZ_MIG_P22_STABILIZATION_SECONDS=86400
# Production default: SOVIEZ_MIG_P22_OBSERVE_TICK_SECONDS=1
SOVIEZ_MIG_P22_PHASE23_TTL_SECONDS="${SOVIEZ_MIG_P22_PHASE23_TTL_SECONDS:-86400}"

SOVIEZ_MIGRATION_CODES+=(
  MIGRATION_PHASE21_READINESS_REQUIRED
  MIGRATION_PHASE21_READINESS_EXPIRED
  MIGRATION_PHASE21_READINESS_INVALID
  MIGRATION_PHASE21_READINESS_DRIFT_DETECTED
  MIGRATION_STABILIZATION_REQUIRED
  MIGRATION_STABILIZATION_INCOMPLETE
  MIGRATION_DESTINATION_HEALTH_UNSTABLE
  MIGRATION_ROLLBACK_WINDOW_STILL_REQUIRED
  MIGRATION_ROLLBACK_WINDOW_ALREADY_CLOSED
  MIGRATION_ROLLBACK_WINDOW_CLOSE_DENIED
  MIGRATION_ACTIVE_INCIDENT_BLOCKS_ARCHIVE
  MIGRATION_SOURCE_ARCHIVE_PLAN_REQUIRED
  MIGRATION_SOURCE_ARCHIVE_PLAN_INVALID
  MIGRATION_SOURCE_ARCHIVE_CREATE_FAILED
  MIGRATION_SOURCE_ARCHIVE_VERIFY_FAILED
  MIGRATION_SOURCE_ARCHIVE_RESTORE_TEST_FAILED
  MIGRATION_SOURCE_ARCHIVE_TRANSFER_INTERRUPTED
  MIGRATION_DESTINATION_BACKUP_REQUIRED
  MIGRATION_SOURCE_LICENSE_FINALIZE_FAILED
  MIGRATION_LICENSE_FINALIZE_RESPONSE_LOSS
  MIGRATION_LICENSE_COMMIT_STATUS_UNKNOWN
  MIGRATION_SOURCE_RUNTIME_SUSPEND_FAILED
  MIGRATION_RUNTIME_SUSPEND_RESPONSE_LOSS
  MIGRATION_SOURCE_RUNTIME_ALREADY_SUSPENDED
  MIGRATION_ROLLBACK_CLOSE_RESPONSE_LOSS
  MIGRATION_SOURCE_PUBLIC_ROUTE_STILL_ACTIVE
  MIGRATION_SOURCE_INTEGRATIONS_STILL_ACTIVE
  MIGRATION_SOURCE_CREDENTIAL_DISPOSITION_INCOMPLETE
  MIGRATION_SOURCE_CERTIFICATE_RETENTION_REQUIRED
  MIGRATION_DNS_ROLLBACK_SNAPSHOT_REQUIRED
  MIGRATION_STAGE_SOURCE_ARCHIVE_FAILED
  MIGRATION_RETENTION_HOLD_ACTIVE
  MIGRATION_LEGAL_HOLD_ACTIVE
  MIGRATION_PURGE_NOT_AUTHORIZED
  MIGRATION_SOURCE_DELETE_NOT_AUTHORIZED
  MIGRATION_SOURCE_DISK_WIPE_NOT_AUTHORIZED
  MIGRATION_BACKUP_DELETE_NOT_AUTHORIZED
  MIGRATION_CERTIFICATE_REVOKE_NOT_AUTHORIZED
  MIGRATION_HOST_TERMINATION_NOT_AUTHORIZED
  MIGRATION_RETIREMENT_NOT_READY
  MIGRATION_PHASE23_NOT_READY
  MIGRATION_MANUAL_INTERVENTION_REQUIRED
  MIGRATION_PHASE22_CANONICAL_REQUIRED
  MIGRATION_PHASE22_CERT_GATE
  MIGRATION_PHASE22_CERT_CLOCK_DENIED
  MIGRATION_PHASE22_CONFIRMATION_REQUIRED
  MIGRATION_DOCKER_PRUNE_NOT_AUTHORIZED
)

# Permanent destructive bans + canonical gate for mutating Phase 22 ops.
# When SOVIEZ_MIG_P22_MUTATING=0 (status/show), only purge/delete bans apply.
soviez_migration_assert_phase22_allowed() {
  local op_type="${1:-}"
  local mutating="${SOVIEZ_MIG_P22_MUTATING:-1}"

  # Always die on destructive product flags — never authorized in Phase 22.
  if [[ "${SOVIEZ_MIG_SOURCE_PURGE:-0}" == "1" || "${SOVIEZ_MIG_PURGE_SOURCE:-0}" == "1" || "${SOVIEZ_MIG_APPLY_SOURCE_PURGE:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_PURGE_NOT_AUTHORIZED "Source purge not authorized in Phase 22"
  fi
  if [[ "${SOVIEZ_MIG_SOURCE_DELETE:-0}" == "1" || "${SOVIEZ_MIG_DELETE_SOURCE:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_SOURCE_DELETE_NOT_AUTHORIZED "Source delete not authorized"
  fi
  if [[ "${SOVIEZ_MIG_DISK_WIPE:-0}" == "1" || "${SOVIEZ_MIG_WIPE_SOURCE:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_SOURCE_DISK_WIPE_NOT_AUTHORIZED "Source disk wipe not authorized"
  fi
  if [[ "${SOVIEZ_MIG_BACKUP_DELETE:-0}" == "1" || "${SOVIEZ_MIG_DELETE_BACKUP:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_BACKUP_DELETE_NOT_AUTHORIZED "Backup delete not authorized in Phase 22"
  fi
  if [[ "${SOVIEZ_MIG_CERT_REVOKE:-0}" == "1" || "${SOVIEZ_MIG_REVOKE_CERT:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_CERTIFICATE_REVOKE_NOT_AUTHORIZED "Certificate revoke not authorized"
  fi
  if [[ "${SOVIEZ_MIG_HOST_TERMINATE:-0}" == "1" || "${SOVIEZ_MIG_TERMINATE_HOST:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_HOST_TERMINATION_NOT_AUTHORIZED "Host termination not authorized"
  fi
  if [[ "${SOVIEZ_MIG_DOCKER_PRUNE:-0}" == "1" || "${SOVIEZ_MIG_DOCKER_SYSTEM_PRUNE:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_DOCKER_PRUNE_NOT_AUTHORIZED "docker prune not authorized"
  fi
  if [[ "${SOVIEZ_MIG_SAAS_PAYLOAD_RELAY:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_DATA_EGRESS_DENIED "SaaS payload relay forbidden"
  fi

  case "$op_type" in
    migration_stabilization_observe|migration_rollback_window_close| \
    migration_source_archive_plan|migration_source_archive| \
    migration_source_license_finalize|migration_source_runtime_suspend| \
    migration_source_retirement_status|migration_phase23_readiness| \
    migration_phase22_readiness|"")
      ;;
    *)
      soviez_migration_die MIGRATION_PHASE22_CANONICAL_REQUIRED "Unauthorized Phase 22 op: ${op_type:-missing}"
      ;;
  esac

  if [[ "$mutating" == "1" ]]; then
    [[ "${SOVIEZ_MIG_P22_CANONICAL:-0}" == "1" ]] || \
      soviez_migration_die MIGRATION_PHASE22_CANONICAL_REQUIRED "Phase 22 mutating op requires SOVIEZ_MIG_P22_CANONICAL=1"
  fi
  return 0
}

# --- end migration/stabilization/codes.sh ---

# --- begin migration/stabilization/model.sh ---
# shellcheck shell=bash
# Phase 22 stabilization path helpers.

soviez_migration_p22_paths_init() {
  soviez_migration_cutover_paths_init
  SOVIEZ_MIG_STABILIZATION_DIR="$SOVIEZ_MIG_ROOT/stabilization"
  SOVIEZ_MIG_ROLLBACK_CLOSURE_DIR="$SOVIEZ_MIG_ROOT/rollback_closure"
  SOVIEZ_MIG_SOURCE_ARCHIVE_DIR="$SOVIEZ_MIG_ROOT/source_archive"
  SOVIEZ_MIG_SOURCE_FINALIZATION_DIR="$SOVIEZ_MIG_ROOT/source_finalization"
  SOVIEZ_MIG_RETIREMENT_DIR="$SOVIEZ_MIG_ROOT/retirement"
  SOVIEZ_MIG_PHASE23_READINESS_DIR="$SOVIEZ_MIG_ROOT/phase23_readiness"
  SOVIEZ_MIG_P22_SUSPEND_DIR="$SOVIEZ_MIG_ROOT/runtime_suspend"
  export SOVIEZ_MIG_STABILIZATION_DIR SOVIEZ_MIG_ROLLBACK_CLOSURE_DIR \
    SOVIEZ_MIG_SOURCE_ARCHIVE_DIR SOVIEZ_MIG_SOURCE_FINALIZATION_DIR \
    SOVIEZ_MIG_RETIREMENT_DIR SOVIEZ_MIG_PHASE23_READINESS_DIR SOVIEZ_MIG_P22_SUSPEND_DIR
  mkdir -p "$SOVIEZ_MIG_STABILIZATION_DIR" "$SOVIEZ_MIG_ROLLBACK_CLOSURE_DIR" \
    "$SOVIEZ_MIG_SOURCE_ARCHIVE_DIR" "$SOVIEZ_MIG_SOURCE_FINALIZATION_DIR" \
    "$SOVIEZ_MIG_RETIREMENT_DIR" "$SOVIEZ_MIG_PHASE23_READINESS_DIR" \
    "$SOVIEZ_MIG_P22_SUSPEND_DIR"
}

soviez_migration_p22_stab_dir() {
  [[ -n "${SOVIEZ_MIG_STABILIZATION_DIR:-}" ]] || soviez_migration_p22_paths_init
  printf '%s/%s\n' "$SOVIEZ_MIG_STABILIZATION_DIR" "$1"
}
soviez_migration_p22_closure_dir() {
  [[ -n "${SOVIEZ_MIG_ROLLBACK_CLOSURE_DIR:-}" ]] || soviez_migration_p22_paths_init
  printf '%s/%s\n' "$SOVIEZ_MIG_ROLLBACK_CLOSURE_DIR" "$1"
}
soviez_migration_p22_archive_dir() {
  [[ -n "${SOVIEZ_MIG_SOURCE_ARCHIVE_DIR:-}" ]] || soviez_migration_p22_paths_init
  printf '%s/%s\n' "$SOVIEZ_MIG_SOURCE_ARCHIVE_DIR" "$1"
}
soviez_migration_p22_finalization_dir() {
  [[ -n "${SOVIEZ_MIG_SOURCE_FINALIZATION_DIR:-}" ]] || soviez_migration_p22_paths_init
  printf '%s/%s\n' "$SOVIEZ_MIG_SOURCE_FINALIZATION_DIR" "$1"
}
soviez_migration_p22_retirement_dir() {
  [[ -n "${SOVIEZ_MIG_RETIREMENT_DIR:-}" ]] || soviez_migration_p22_paths_init
  printf '%s/%s\n' "$SOVIEZ_MIG_RETIREMENT_DIR" "$1"
}
soviez_migration_p22_phase23_dir() {
  [[ -n "${SOVIEZ_MIG_PHASE23_READINESS_DIR:-}" ]] || soviez_migration_p22_paths_init
  printf '%s/%s\n' "$SOVIEZ_MIG_PHASE23_READINESS_DIR" "$1"
}
soviez_migration_p22_suspend_state_path() {
  [[ -n "${SOVIEZ_MIG_P22_SUSPEND_DIR:-}" ]] || soviez_migration_p22_paths_init
  printf '%s/%s/state.json\n' "$SOVIEZ_MIG_P22_SUSPEND_DIR" "$1"
}

# --- end migration/stabilization/model.sh ---

# --- begin migration/stabilization/clock.sh ---
# shellcheck shell=bash
# Certification clock for Phase 22 stabilization duration tests.
# Production: always real system time. Override ONLY when both fixture flags set.

soviez_migration_p22_now_epoch() {
  if [[ "${SOVIEZ_MIG_P22_FIXTURE:-0}" == "1" && "${SOVIEZ_MIG_P22_ALLOW_CERT_CLOCK:-0}" == "1" ]]; then
    if [[ -n "${SOVIEZ_MIG_P22_CERT_CLOCK_EPOCH:-}" ]]; then
      printf '%s\n' "$SOVIEZ_MIG_P22_CERT_CLOCK_EPOCH"
      return 0
    fi
  elif [[ -n "${SOVIEZ_MIG_P22_CERT_CLOCK_EPOCH:-}" ]]; then
    # Production (or fixture without allow): deny clock override.
    if [[ "${SOVIEZ_MIG_P22_FIXTURE:-0}" != "1" || "${SOVIEZ_MIG_P22_ALLOW_CERT_CLOCK:-0}" != "1" ]]; then
      soviez_migration_die MIGRATION_PHASE22_CERT_CLOCK_DENIED \
        "SOVIEZ_MIG_P22_CERT_CLOCK_EPOCH denied outside fixture+allow flags"
    fi
  fi
  soviez_migration_now_epoch
}

soviez_migration_p22_now_iso() {
  local epoch
  epoch="$(soviez_migration_p22_now_epoch)"
  python3 -c "import datetime,sys; print(datetime.datetime.utcfromtimestamp(int(sys.argv[1])).strftime('%Y-%m-%dT%H:%M:%SZ'))" "$epoch"
}

soviez_migration_p22_clock_source() {
  if [[ "${SOVIEZ_MIG_P22_FIXTURE:-0}" == "1" && "${SOVIEZ_MIG_P22_ALLOW_CERT_CLOCK:-0}" == "1" && -n "${SOVIEZ_MIG_P22_CERT_CLOCK_EPOCH:-}" ]]; then
    printf 'certification_override\n'
  else
    printf 'system\n'
  fi
}

soviez_migration_p22_advance_cert_clock() {
  local delta="${1:-0}"
  [[ "${SOVIEZ_MIG_P22_FIXTURE:-0}" == "1" && "${SOVIEZ_MIG_P22_ALLOW_CERT_CLOCK:-0}" == "1" ]] || \
    soviez_migration_die MIGRATION_PHASE22_CERT_CLOCK_DENIED "cert clock advance requires fixture+allow"
  local now
  now="$(soviez_migration_p22_now_epoch)"
  export SOVIEZ_MIG_P22_CERT_CLOCK_EPOCH=$((now + delta))
}

soviez_migration_p22_is_expired_at() {
  local expires_iso="$1"
  local now exp
  now="$(soviez_migration_p22_now_epoch)"
  exp="$(soviez_migration_iso_to_epoch "$expires_iso")" || return 0
  [[ "$now" -ge "$exp" ]]
}

# --- end migration/stabilization/clock.sh ---

# --- begin migration/stabilization/targeting.sh ---
# shellcheck shell=bash
# Resolve cutover op + auth + phase22 readiness for stabilization targeting.

soviez_migration_p22_resolve_cutover() {
  local cutover_id="${1:-}"
  [[ -n "$cutover_id" ]] || soviez_migration_die MIGRATION_NOT_FOUND "cutover-id required"
  soviez_migration_p22_paths_init
  local stf
  stf="$(soviez_migration_cutover_state_path "$cutover_id")"
  [[ -f "$stf" ]] || soviez_migration_die MIGRATION_NOT_FOUND "cutover operation not found: $cutover_id"
  cat "$stf"
}

soviez_migration_p22_require_phase21_cutover() {
  local cutover_id="${1:-}"
  local st auth_id to state
  st="$(soviez_migration_p22_resolve_cutover "$cutover_id")"
  state="$(soviez_json_get "$st" current_state)"
  [[ "$state" == "cutover_complete" ]] || \
    soviez_migration_die MIGRATION_PHASE21_READINESS_REQUIRED "cutover not complete: $state"
  auth_id="$(soviez_json_get "$st" authorization_id)"
  to="$(soviez_json_get "$(soviez_migration_traffic_owner_get "$auth_id")" traffic_owner)"
  [[ "$to" == "destination" ]] || \
    soviez_migration_die MIGRATION_PHASE21_READINESS_INVALID "traffic_owner must be destination"
  printf '%s\n' "$st"
}

soviez_migration_p22_require_readiness() {
  local auth_id="${1:-}"
  local report_path latest status
  # Prefer newest non-expired phase22 readiness report for this auth.
  latest=""
  if [[ -d "$SOVIEZ_MIG_ROOT/phase22_readiness" ]]; then
    while IFS= read -r -d '' f; do
      if [[ "$(soviez_json_get "$(cat "$f")" authorization_id 2>/dev/null || true)" == "$auth_id" ]]; then
        if ! soviez_migration_is_expired "$(soviez_json_get "$(cat "$f")" expires_at)"; then
          latest="$f"
        fi
      fi
    done < <(find "$SOVIEZ_MIG_ROOT/phase22_readiness" -name report.json -print0 2>/dev/null | sort -z)
  fi
  # Also accept cutover-embedded readiness.
  if [[ -z "$latest" ]]; then
    local op_id
    op_id="$(soviez_json_get "$(soviez_migration_traffic_owner_get "$auth_id")" operation_id 2>/dev/null || true)"
    if [[ -n "$op_id" && -f "$(soviez_migration_cutover_op_dir "$op_id")/phase22_readiness.json" ]]; then
      latest="$(soviez_migration_cutover_op_dir "$op_id")/phase22_readiness.json"
      if soviez_migration_is_expired "$(soviez_json_get "$(cat "$latest")" expires_at 2>/dev/null || echo 1970-01-01T00:00:00Z)"; then
        soviez_migration_die MIGRATION_PHASE21_READINESS_EXPIRED "embedded phase22 readiness expired"
      fi
    fi
  fi
  [[ -n "$latest" ]] || soviez_migration_die MIGRATION_PHASE21_READINESS_REQUIRED "phase22 readiness report required"
  status="$(soviez_json_get "$(cat "$latest")" readiness_status)"
  [[ "$status" == "PASS" || "$status" == "WARNING" ]] || \
    soviez_migration_die MIGRATION_PHASE21_READINESS_INVALID "phase22 readiness status=$status"
  cat "$latest"
}

# --- end migration/stabilization/targeting.sh ---

# --- begin migration/stabilization/observe.sh ---
# shellcheck shell=bash
# Single observation sample of destination sustained health fields.

soviez_migration_p22_observe_once() {
  local cutover_id="${1:-}"
  local http=ok tls=ok db=ok filestore=ok workers=ok cron=ok mail=ok webhook=ok payment=ok
  local queue=ok errors=0 latency_ms=50 backups=ok growth=ok lg=ok dns=ok stages=ok
  local source_writes=0 source_requests=0 duplicates=0 incidents=0

  # Injection hooks for tests (SOVIEZ_MIG_P22_INJECT_*).
  [[ "${SOVIEZ_MIG_P22_INJECT_HTTP_FAIL:-0}" == "1" ]] && http=fail
  [[ "${SOVIEZ_MIG_P22_INJECT_TLS_FAIL:-0}" == "1" ]] && tls=fail
  [[ "${SOVIEZ_MIG_P22_INJECT_DB_FAIL:-0}" == "1" ]] && db=fail
  [[ "${SOVIEZ_MIG_P22_INJECT_FILESTORE_FAIL:-0}" == "1" ]] && filestore=fail
  [[ "${SOVIEZ_MIG_P22_INJECT_WORKERS_FAIL:-0}" == "1" ]] && workers=fail
  [[ "${SOVIEZ_MIG_P22_INJECT_CRON_FAIL:-0}" == "1" ]] && cron=fail
  [[ "${SOVIEZ_MIG_P22_INJECT_MAIL_FAIL:-0}" == "1" ]] && mail=fail
  [[ "${SOVIEZ_MIG_P22_INJECT_WEBHOOK_FAIL:-0}" == "1" ]] && webhook=fail
  [[ "${SOVIEZ_MIG_P22_INJECT_PAYMENT_FAIL:-0}" == "1" ]] && payment=fail
  [[ "${SOVIEZ_MIG_P22_INJECT_QUEUE_FAIL:-0}" == "1" ]] && queue=fail
  [[ "${SOVIEZ_MIG_P22_INJECT_BACKUPS_FAIL:-0}" == "1" ]] && backups=fail
  [[ "${SOVIEZ_MIG_P22_INJECT_LG_FAIL:-0}" == "1" ]] && lg=fail
  [[ "${SOVIEZ_MIG_P22_INJECT_DNS_FAIL:-0}" == "1" ]] && dns=fail
  [[ "${SOVIEZ_MIG_P22_INJECT_STAGES_FAIL:-0}" == "1" ]] && stages=fail
  [[ "${SOVIEZ_MIG_P22_INJECT_ERRORS:-0}" != "0" ]] && errors="${SOVIEZ_MIG_P22_INJECT_ERRORS}"
  [[ -n "${SOVIEZ_MIG_P22_INJECT_LATENCY_MS:-}" ]] && latency_ms="${SOVIEZ_MIG_P22_INJECT_LATENCY_MS}"
  [[ "${SOVIEZ_MIG_P22_INJECT_SOURCE_WRITES:-0}" != "0" ]] && source_writes="${SOVIEZ_MIG_P22_INJECT_SOURCE_WRITES}"
  [[ "${SOVIEZ_MIG_P22_INJECT_SOURCE_REQUESTS:-0}" != "0" ]] && source_requests="${SOVIEZ_MIG_P22_INJECT_SOURCE_REQUESTS}"
  [[ "${SOVIEZ_MIG_P22_INJECT_DUPLICATES:-0}" != "0" ]] && duplicates="${SOVIEZ_MIG_P22_INJECT_DUPLICATES}"
  [[ "${SOVIEZ_MIG_P22_INJECT_INCIDENT:-0}" == "1" ]] && incidents=1
  [[ "${SOVIEZ_MIG_P22_INJECT_GROWTH_FAIL:-0}" == "1" ]] && growth=fail

  SOVIEZ_CID="$cutover_id" SOVIEZ_HTTP="$http" SOVIEZ_TLS="$tls" SOVIEZ_DB="$db" \
  SOVIEZ_FS="$filestore" SOVIEZ_WK="$workers" SOVIEZ_CR="$cron" SOVIEZ_ML="$mail" \
  SOVIEZ_WH="$webhook" SOVIEZ_PAY="$payment" SOVIEZ_Q="$queue" SOVIEZ_ERR="$errors" \
  SOVIEZ_LAT="$latency_ms" SOVIEZ_BK="$backups" SOVIEZ_GR="$growth" SOVIEZ_LG="$lg" \
  SOVIEZ_DNS="$dns" SOVIEZ_STG="$stages" SOVIEZ_SW="$source_writes" SOVIEZ_SR="$source_requests" \
  SOVIEZ_DUP="$duplicates" SOVIEZ_INC="$incidents" \
  SOVIEZ_TS="$(soviez_migration_p22_now_iso)" python3 - <<'PY'
import json, os
print(json.dumps({
  "cutover_id": os.environ["SOVIEZ_CID"],
  "observed_at": os.environ["SOVIEZ_TS"],
  "http": os.environ["SOVIEZ_HTTP"],
  "tls": os.environ["SOVIEZ_TLS"],
  "db": os.environ["SOVIEZ_DB"],
  "filestore": os.environ["SOVIEZ_FS"],
  "workers": os.environ["SOVIEZ_WK"],
  "cron": os.environ["SOVIEZ_CR"],
  "mail": os.environ["SOVIEZ_ML"],
  "webhook": os.environ["SOVIEZ_WH"],
  "payment": os.environ["SOVIEZ_PAY"],
  "queue": os.environ["SOVIEZ_Q"],
  "errors": int(os.environ["SOVIEZ_ERR"]),
  "latency_ms": int(os.environ["SOVIEZ_LAT"]),
  "backups": os.environ["SOVIEZ_BK"],
  "growth": os.environ["SOVIEZ_GR"],
  "license_guard": os.environ["SOVIEZ_LG"],
  "dns": os.environ["SOVIEZ_DNS"],
  "stages": os.environ["SOVIEZ_STG"],
  "source_writes": int(os.environ["SOVIEZ_SW"]),
  "source_requests": int(os.environ["SOVIEZ_SR"]),
  "duplicates": int(os.environ["SOVIEZ_DUP"]),
  "incidents": int(os.environ["SOVIEZ_INC"]),
}, separators=(",", ":")))
PY
}

# --- end migration/stabilization/observe.sh ---

# --- begin migration/stabilization/health.sh ---
# shellcheck shell=bash

soviez_migration_p22_health_sample_ok() {
  local sample="$1"
  local f
  for f in http tls db filestore workers cron mail webhook payment queue backups growth license_guard dns stages; do
    [[ "$(soviez_json_get "$sample" "$f")" == "ok" || "$(soviez_json_get "$sample" "$f")" == "True" ]] || return 1
  done
  local errors latency
  errors="$(soviez_json_get "$sample" errors)"
  latency="$(soviez_json_get "$sample" latency_ms)"
  [[ "${errors:-0}" -eq 0 ]] || return 1
  [[ "${latency:-0}" -le "${SOVIEZ_MIG_P22_MAX_LATENCY_MS:-2000}" ]] || return 1
  [[ "$(soviez_json_get "$sample" source_writes)" -eq 0 ]] || return 1
  [[ "$(soviez_json_get "$sample" incidents)" -eq 0 ]] || return 1
  return 0
}

# --- end migration/stabilization/health.sh ---

# --- begin migration/stabilization/traffic.sh ---
# shellcheck shell=bash

soviez_migration_p22_traffic_checks() {
  local sample="$1"
  [[ "$(soviez_json_get "$sample" source_requests)" -eq 0 ]] || return 1
  [[ "$(soviez_json_get "$sample" duplicates)" -eq 0 ]] || return 1
  return 0
}

# --- end migration/stabilization/traffic.sh ---

