# --- end migration/stabilization/stages.sh ---

# --- begin migration/stabilization/incidents.sh ---
# shellcheck shell=bash

soviez_migration_p22_incidents_clear() {
  local sample="$1"
  [[ "$(soviez_json_get "$sample" incidents)" -eq 0 ]] || return 1
  return 0
}

# --- end migration/stabilization/incidents.sh ---

# --- begin migration/stabilization/validate.sh ---
# shellcheck shell=bash

soviez_migration_p22_validate_observation_window() {
  local started_epoch="$1" ended_epoch="$2" required_seconds="$3"
  local span=$((ended_epoch - started_epoch))
  [[ "$span" -ge "$required_seconds" ]] || \
    soviez_migration_die MIGRATION_STABILIZATION_INCOMPLETE \
      "observation span ${span}s < required ${required_seconds}s (single instantaneous check insufficient)"
}

# --- end migration/stabilization/validate.sh ---

# --- begin migration/stabilization/report.sh ---
# shellcheck shell=bash

soviez_migration_p22_stabilization_write_report() {
  local report_id="$1" cutover_id="$2" auth_id="$3" status="$4" samples_file="$5"
  local out_dir out_file
  out_dir="$(soviez_migration_p22_stab_dir "$report_id")"
  mkdir -p "$out_dir"
  out_file="$out_dir/report.json"
  SOVIEZ_OUT="$out_file" SOVIEZ_RID="$report_id" SOVIEZ_CID="$cutover_id" \
  SOVIEZ_AID="$auth_id" SOVIEZ_ST="$status" SOVIEZ_SAMPLES="$samples_file" \
  SOVIEZ_CS="$(soviez_migration_p22_clock_source)" \
  SOVIEZ_DUR="${SOVIEZ_MIG_P22_STABILIZATION_SECONDS}" \
  SOVIEZ_NOW="$(soviez_migration_p22_now_iso)" python3 - <<'PY'
import json, os
samples = []
try:
  with open(os.environ["SOVIEZ_SAMPLES"]) as f:
    for line in f:
      line=line.strip()
      if line:
        samples.append(json.loads(line))
except Exception:
  samples = []
body = {
  "schema": "soviez.migration_stabilization.v1",
  "report_id": os.environ["SOVIEZ_RID"],
  "cutover_id": os.environ["SOVIEZ_CID"],
  "authorization_id": os.environ["SOVIEZ_AID"],
  "stabilization_status": os.environ["SOVIEZ_ST"],
  "required_duration_seconds": int(os.environ["SOVIEZ_DUR"]),
  "clock_source": os.environ["SOVIEZ_CS"],
  "sample_count": len(samples),
  "samples": samples,
  "purges_source": False,
  "archives_source": False,
  "created_at": os.environ["SOVIEZ_NOW"],
  "signer": "soviez-p22",
}
open(os.environ["SOVIEZ_OUT"], "w").write(json.dumps(body, separators=(",", ":")))
PY
  soviez_migration_sign_object_file "$out_file"
  cat "$out_file"
}

# --- end migration/stabilization/report.sh ---

# --- begin migration/stabilization/engine.sh ---
# shellcheck shell=bash
# Phase 22 destination stabilization — sustained observation over configured duration.

soviez_migration_stabilization_status() {
  local cutover_id="${1:-}"
  soviez_migration_p22_paths_init
  SOVIEZ_MIG_P22_MUTATING=0 soviez_migration_assert_phase22_allowed "$SOVIEZ_MIG_OP_STABILIZATION"
  local st auth_id
  st="$(soviez_migration_p22_require_phase21_cutover "$cutover_id")"
  auth_id="$(soviez_json_get "$st" authorization_id)"
  soviez_migration_p22_require_readiness "$auth_id" >/dev/null

  local report_id duration started_epoch ended_epoch samples_file tick sample ok_all=1 waited
  report_id="$(soviez_migration_new_id p22s)"
  duration="${SOVIEZ_MIG_P22_STABILIZATION_SECONDS:-86400}"
  tick="${SOVIEZ_MIG_P22_OBSERVE_TICK_SECONDS:-1}"
  [[ "$tick" -gt 0 ]] || tick=1
  # Fixture safety: never spin 86400 python ticks in certification unless explicitly requested.
  if [[ "${SOVIEZ_MIG_P22_FIXTURE:-0}" == "1" && "$duration" -gt 120 && "${SOVIEZ_MIG_P22_ALLOW_LONG_STAB:-0}" != "1" ]]; then
    duration=10
  fi
  # Cap sample count: use larger effective ticks so we get ≥2 samples without O(duration) cost.
  local max_samples=12
  if [[ $((duration / tick)) -gt $max_samples ]]; then
    tick=$(( (duration + max_samples - 1) / max_samples ))
    [[ "$tick" -gt 0 ]] || tick=1
  fi
  samples_file="$(soviez_migration_p22_stab_dir "$report_id")/samples.ndjson"
  mkdir -p "$(dirname "$samples_file")"
  : > "$samples_file"

  started_epoch="$(soviez_migration_p22_now_epoch)"
  waited=0
  # Multi-tick observation loop: record a sample each tick across the full duration.
  # Cert-clock fixtures advance time per tick instead of sleeping wall-clock.
  while true; do
    sample="$(soviez_migration_p22_observe_once "$cutover_id")"
    printf '%s\n' "$sample" >> "$samples_file"
    if ! soviez_migration_p22_health_sample_ok "$sample" \
      || ! soviez_migration_p22_traffic_checks "$sample" \
      || ! soviez_migration_p22_integrations_ok "$sample" \
      || ! soviez_migration_p22_backups_ok "$sample" \
      || ! soviez_migration_p22_stages_ok "$sample" \
      || ! soviez_migration_p22_incidents_clear "$sample"; then
      ok_all=0
    fi

    if [[ "$waited" -ge "$duration" ]]; then
      break
    fi

    if [[ "${SOVIEZ_MIG_P22_FIXTURE:-0}" == "1" && "${SOVIEZ_MIG_P22_ALLOW_CERT_CLOCK:-0}" == "1" ]]; then
      soviez_migration_p22_advance_cert_clock "$tick"
    else
      sleep "$tick"
    fi
    waited=$((waited + tick))
  done

  ended_epoch="$(soviez_migration_p22_now_epoch)"
  soviez_migration_p22_validate_observation_window "$started_epoch" "$ended_epoch" "$duration"

  # Require multiple samples — a single instantaneous check is insufficient.
  local sample_count
  sample_count="$(wc -l < "$samples_file" | tr -d ' ')"
  [[ "$sample_count" -ge 2 ]] || \
    soviez_migration_die MIGRATION_STABILIZATION_INCOMPLETE \
      "observation recorded ${sample_count} sample(s); need multiple ticks over duration"

  local status=PASS
  if [[ "$ok_all" -ne 1 ]]; then
    status=FAIL
  fi
  local report
  report="$(soviez_migration_p22_stabilization_write_report "$report_id" "$cutover_id" "$auth_id" "$status" "$samples_file")"
  # Index by cutover for lookups.
  mkdir -p "$(soviez_migration_p22_stab_dir "by_cutover")"
  printf '%s\n' "$report_id" > "$(soviez_migration_p22_stab_dir "by_cutover")/${cutover_id}.id"
  if [[ "$status" != "PASS" ]]; then
    soviez_migration_die MIGRATION_DESTINATION_HEALTH_UNSTABLE "stabilization failed"
  fi
  printf '%s\n' "$report"
}

soviez_migration_stabilization_latest_report() {
  local cutover_id="${1:-}"
  soviez_migration_p22_paths_init
  local idf rid
  idf="$(soviez_migration_p22_stab_dir "by_cutover")/${cutover_id}.id"
  [[ -f "$idf" ]] || soviez_migration_die MIGRATION_STABILIZATION_REQUIRED "no stabilization report for cutover"
  rid="$(tr -d '[:space:]' < "$idf")"
  cat "$(soviez_migration_p22_stab_dir "$rid")/report.json"
}

# --- end migration/stabilization/engine.sh ---

# --- begin migration/rollback_closure/codes.sh ---
# shellcheck shell=bash
# Rollback closure codes — shared set lives in stabilization/codes.sh.
# This file exists for modular assemble ordering and any closure-local ops.

SOVIEZ_MIG_OP_ROLLBACK_WINDOW_CLOSE_PLAN=migration_rollback_window_close_plan
SOVIEZ_MIG_OP_ROLLBACK_WINDOW_CLOSE_STATUS=migration_rollback_window_close_status

# --- end migration/rollback_closure/codes.sh ---

# --- begin migration/rollback_closure/model.sh ---
# shellcheck shell=bash

soviez_migration_p22_closure_receipt_path() {
  printf '%s/receipt.json\n' "$(soviez_migration_p22_closure_dir "$1")"
}

soviez_migration_p22_closure_by_cutover_path() {
  [[ -n "${SOVIEZ_MIG_ROLLBACK_CLOSURE_DIR:-}" ]] || soviez_migration_p22_paths_init
  printf '%s/by_cutover/%s.json\n' "$SOVIEZ_MIG_ROLLBACK_CLOSURE_DIR" "$1"
}

# --- end migration/rollback_closure/model.sh ---

# --- begin migration/rollback_closure/eligibility.sh ---
# shellcheck shell=bash

soviez_migration_rollback_window_close_eligibility() {
  local cutover_id="${1:-}"
  soviez_migration_p22_paths_init
  local blockers=() warnings=()

  # Already closed?
  local byc
  byc="$(soviez_migration_p22_closure_by_cutover_path "$cutover_id")"
  if [[ -f "$byc" ]]; then
    local closed
    closed="$(soviez_json_get "$(cat "$byc")" automatic_rollback_allowed 2>/dev/null || echo true)"
    if [[ "$closed" == "False" || "$closed" == "false" ]]; then
      printf '{"eligible":false,"code":"MIGRATION_ROLLBACK_WINDOW_ALREADY_CLOSED","reason":"already_closed"}\n'
      return 1
    fi
  fi

  # Stabilization PASS required.
  local stab
  set +e
  stab="$(soviez_migration_stabilization_latest_report "$cutover_id" 2>/dev/null)"
  local src=$?
  set -e
  if [[ "$src" -ne 0 ]]; then
    blockers+=("stabilization_required")
  else
    [[ "$(soviez_json_get "$stab" stabilization_status)" == "PASS" ]] || blockers+=("stabilization_not_pass")
  fi

  # Window must be expired (immediate window 30m / P21 rollback window).
  local wf
  wf="$(soviez_migration_cutover_rollback_window_path "$cutover_id")"
  if [[ -f "$wf" ]]; then
    local exp
    exp="$(soviez_json_get "$(cat "$wf")" expires_at)"
    if ! soviez_migration_p22_is_expired_at "$exp"; then
      # Allow fixture force-expire
      if [[ "${SOVIEZ_MIG_P22_FORCE_WINDOW_EXPIRED:-0}" == "1" ]]; then
        :
      else
        blockers+=("window_still_open")
      fi
    fi
  else
    blockers+=("window_missing")
  fi

  # No active incident.
  if [[ "${SOVIEZ_MIG_P22_INJECT_INCIDENT:-0}" == "1" ]]; then
    blockers+=("active_incident")
  fi

  # No active rollback in progress.
  if [[ "${SOVIEZ_MIG_P22_ACTIVE_ROLLBACK:-0}" == "1" ]]; then
    blockers+=("active_rollback")
  fi

  # Backups valid (fixture defaults ok unless injected).
  if [[ "${SOVIEZ_MIG_P22_INJECT_BACKUPS_FAIL:-0}" == "1" ]]; then
    blockers+=("backups_invalid")
  fi

  if [[ ${#blockers[@]} -gt 0 ]]; then
    SOVIEZ_BL="$(printf '%s,' "${blockers[@]}")" python3 - <<'PY'
import json, os
bl=[x for x in os.environ.get("SOVIEZ_BL","").split(",") if x]
code="MIGRATION_ROLLBACK_WINDOW_CLOSE_DENIED"
if "window_still_open" in bl:
  code="MIGRATION_ROLLBACK_WINDOW_STILL_REQUIRED"
elif "active_incident" in bl:
  code="MIGRATION_ACTIVE_INCIDENT_BLOCKS_ARCHIVE"
elif "stabilization_required" in bl or "stabilization_not_pass" in bl:
  code="MIGRATION_STABILIZATION_REQUIRED"
print(json.dumps({"eligible":False,"code":code,"blockers":bl}, separators=(",", ":")))
PY
    return 1
  fi
  printf '{"eligible":true,"warnings":[]}\n'
  return 0
}

# --- end migration/rollback_closure/eligibility.sh ---

# --- begin migration/rollback_closure/confirmation.sh ---
# shellcheck shell=bash
# Confirmation phrase: CLOSE ROLLBACK WINDOW <cutover-id>

soviez_migration_rollback_window_confirm() {
  local cutover_id="${1:-}"
  local expected phrase
  expected="CLOSE ROLLBACK WINDOW ${cutover_id}"
  phrase="${SOVIEZ_CLI_CONFIRM_PHRASE:-}"

  if [[ -z "$phrase" ]]; then
    if [[ -t 0 && "${SOVIEZ_MIG_P22_FIXTURE:-0}" != "1" ]]; then
      printf 'Type exact confirmation phrase to close rollback window:\n' >&2
      printf '  %s\n' "$expected" >&2
      read -r phrase
    else
      soviez_migration_die MIGRATION_PHASE22_CONFIRMATION_REQUIRED \
        "non-TTY requires --confirm-phrase \"$expected\""
    fi
  fi

  [[ "$phrase" == "$expected" ]] || \
    soviez_migration_die MIGRATION_PHASE22_CONFIRMATION_REQUIRED \
      "confirmation phrase mismatch (expected CLOSE ROLLBACK WINDOW <cutover-id>)"
  return 0
}

# --- end migration/rollback_closure/confirmation.sh ---

# --- begin migration/rollback_closure/receipt.sh ---
# shellcheck shell=bash

soviez_migration_rollback_window_write_receipt() {
  local op_id="$1" cutover_id="$2" auth_id="$3"
  local out_dir receipt byc wf
  out_dir="$(soviez_migration_p22_closure_dir "$op_id")"
  mkdir -p "$out_dir" "$(dirname "$(soviez_migration_p22_closure_by_cutover_path "$cutover_id")")"
  receipt="$out_dir/receipt.json"

  # Mark DNS snapshot as manual_recovery_only if present.
  wf="$(soviez_migration_cutover_rollback_window_path "$cutover_id")"
  if [[ -f "$wf" ]]; then
    SOVIEZ_WF="$wf" python3 - <<'PY'
import json, os
p=os.environ["SOVIEZ_WF"]
d=json.load(open(p))
d["manual_recovery_only"]=True
d["automatic_rollback_allowed"]=False
d["window_closed"]=True
open(p,"w").write(json.dumps(d, separators=(",", ":")))
PY
  fi

  # Also stamp DNS zone snapshot marker if exists.
  local dns_snap
  dns_snap="$(soviez_migration_cutover_op_dir "$cutover_id")/dns_rollback_snapshot.json"
  if [[ -f "$dns_snap" ]]; then
    SOVIEZ_D="$dns_snap" python3 - <<'PY'
import json, os
p=os.environ["SOVIEZ_D"]
d=json.load(open(p))
d["manual_recovery_only"]=True
open(p,"w").write(json.dumps(d, separators=(",", ":")))
PY
  else
    printf '{"manual_recovery_only":true,"retained":true}\n' > "$dns_snap"
  fi

  SOVIEZ_OUT="$receipt" SOVIEZ_OP="$op_id" SOVIEZ_CID="$cutover_id" SOVIEZ_AID="$auth_id" \
  SOVIEZ_NOW="$(soviez_migration_p22_now_iso)" python3 - <<'PY'
import json, os
body={
  "schema":"soviez.migration_rollback_window_close.v1",
  "operation_id":os.environ["SOVIEZ_OP"],
  "operation_type":"migration_rollback_window_close",
  "cutover_id":os.environ["SOVIEZ_CID"],
  "authorization_id":os.environ["SOVIEZ_AID"],
  "status":"closed",
  "automatic_rollback_allowed":False,
  "manual_recovery_only":True,
  "data_deleted":False,
  "runtime_stopped":False,
  "closed_at":os.environ["SOVIEZ_NOW"],
  "signer":"soviez-p22",
}
open(os.environ["SOVIEZ_OUT"],"w").write(json.dumps(body, separators=(",", ":")))
PY
  soviez_migration_sign_object_file "$receipt"
  cp -f "$receipt" "$(soviez_migration_p22_closure_by_cutover_path "$cutover_id")"
  cat "$receipt"
}

# --- end migration/rollback_closure/receipt.sh ---

# --- begin migration/rollback_closure/close.sh ---
# shellcheck shell=bash

soviez_migration_rollback_window_close_commit() {
  local cutover_id="${1:-}"
  local st auth_id op_id byc
  st="$(soviez_migration_p22_require_phase21_cutover "$cutover_id")"
  auth_id="$(soviez_json_get "$st" authorization_id)"

  # Idempotent: same receipt on retry.
  byc="$(soviez_migration_p22_closure_by_cutover_path "$cutover_id")"
  if [[ -f "$byc" ]] && [[ "$(soviez_json_get "$(cat "$byc")" automatic_rollback_allowed)" == "False" || "$(soviez_json_get "$(cat "$byc")" automatic_rollback_allowed)" == "false" ]]; then
    cat "$byc"
    return 0
  fi

  op_id="$(soviez_migration_new_id p22rc)"
  soviez_migration_rollback_window_write_receipt "$op_id" "$cutover_id" "$auth_id"
}

# --- end migration/rollback_closure/close.sh ---

# --- begin migration/rollback_closure/status.sh ---
# shellcheck shell=bash

soviez_migration_rollback_window_close_status() {
  local op_id="${1:-}"
  [[ -n "$op_id" ]] || soviez_migration_die MIGRATION_NOT_FOUND "operation-id required"
  SOVIEZ_MIG_P22_MUTATING=0 soviez_migration_assert_phase22_allowed "$SOVIEZ_MIG_OP_ROLLBACK_WINDOW_CLOSE"
  soviez_migration_p22_paths_init
  local f
  f="$(soviez_migration_p22_closure_receipt_path "$op_id")"
  [[ -f "$f" ]] || soviez_migration_die MIGRATION_NOT_FOUND "closure receipt not found"
  cat "$f"
}

# --- end migration/rollback_closure/status.sh ---

# --- begin migration/rollback_closure/recover.sh ---
# shellcheck shell=bash

soviez_migration_rollback_window_close_recover() {
  local op_id="${1:-}"
  # Recovery is advisory — never re-opens automatic rollback silently.
  soviez_migration_rollback_window_close_status "$op_id"
}

# --- end migration/rollback_closure/recover.sh ---

# --- begin migration/rollback_closure/engine.sh ---
# shellcheck shell=bash

soviez_migration_rollback_window_close_plan() {
  local cutover_id="${1:-}"
  export SOVIEZ_MIG_P22_CANONICAL=1
  soviez_migration_p22_paths_init
  soviez_migration_assert_phase22_allowed "$SOVIEZ_MIG_OP_ROLLBACK_WINDOW_CLOSE"
  local elig erc
  set +e
  elig="$(soviez_migration_rollback_window_close_eligibility "$cutover_id")"
  erc=$?
  set -e
  SOVIEZ_CID="$cutover_id" SOVIEZ_ELIG="$elig" SOVIEZ_OK="$erc" \
  SOVIEZ_NOW="$(soviez_migration_p22_now_iso)" python3 - <<'PY'
import json, os
elig=json.loads(os.environ["SOVIEZ_ELIG"])
print(json.dumps({
  "schema":"soviez.migration_rollback_window_close_plan.v1",
  "cutover_id":os.environ["SOVIEZ_CID"],
  "eligible": elig.get("eligible", False),
  "eligibility": elig,
  "confirmation_phrase": f"CLOSE ROLLBACK WINDOW {os.environ['SOVIEZ_CID']}",
  "created_at": os.environ["SOVIEZ_NOW"],
}, separators=(",", ":")))
PY
}

soviez_migration_rollback_window_close() {
  local cutover_id="${1:-}"
  export SOVIEZ_MIG_P22_CANONICAL=1
  soviez_migration_p22_paths_init
  soviez_migration_assert_phase22_allowed "$SOVIEZ_MIG_OP_ROLLBACK_WINDOW_CLOSE"

  local elig erc
  set +e
  elig="$(soviez_migration_rollback_window_close_eligibility "$cutover_id")"
  erc=$?
  set -e
  if [[ "$erc" -ne 0 ]]; then
    # Already closed → return existing receipt (idempotent).
    if [[ "$(soviez_json_get "$elig" code)" == "MIGRATION_ROLLBACK_WINDOW_ALREADY_CLOSED" ]]; then
      cat "$(soviez_migration_p22_closure_by_cutover_path "$cutover_id")"
      return 0
    fi
    local code
    code="$(soviez_json_get "$elig" code)"
    soviez_migration_die "$code" "rollback window close denied: $(soviez_json_get "$elig" reason 2>/dev/null || echo blockers)"
  fi

  soviez_migration_rollback_window_confirm "$cutover_id"

  # Pre-commit response-loss injection (eligibility+confirm done; commit not yet).
  if [[ "${SOVIEZ_MIG_P22_CLOSURE_PRE_COMMIT_LOSS:-0}" == "1" ]]; then
    unset SOVIEZ_MIG_P22_CLOSURE_PRE_COMMIT_LOSS
    export SOVIEZ_MIG_P22_CLOSURE_PRE_COMMIT_LOSS=0
    soviez_migration_die MIGRATION_ROLLBACK_CLOSE_RESPONSE_LOSS \
      "injected loss after eligibility/confirm before commit"
  fi

  local receipt
  receipt="$(soviez_migration_rollback_window_close_commit "$cutover_id")"

  # Post-commit response-loss: receipt on disk; client never saw response.
  if [[ "${SOVIEZ_MIG_P22_CLOSURE_POST_COMMIT_LOSS:-0}" == "1" ]]; then
    unset SOVIEZ_MIG_P22_CLOSURE_POST_COMMIT_LOSS
    export SOVIEZ_MIG_P22_CLOSURE_POST_COMMIT_LOSS=0
    soviez_migration_die MIGRATION_ROLLBACK_CLOSE_RESPONSE_LOSS \
      "injected loss after rollback-window close commit"
  fi
  printf '%s\n' "$receipt"
}

# --- end migration/rollback_closure/engine.sh ---

# --- begin migration/source_archive/codes.sh ---
# shellcheck shell=bash
# Source archive codes — shared Phase 22 set in stabilization/codes.sh.

SOVIEZ_MIG_OP_SOURCE_ARCHIVE_STATUS=migration_source_archive_status
SOVIEZ_MIG_OP_SOURCE_ARCHIVE_RETRY=migration_source_archive_retry
SOVIEZ_MIG_OP_SOURCE_ARCHIVE_RECOVER=migration_source_archive_recover

# --- end migration/source_archive/codes.sh ---

# --- begin migration/source_archive/paths.sh ---
# shellcheck shell=bash

soviez_migration_p22_archive_op_dir() {
  [[ -n "${SOVIEZ_MIG_SOURCE_ARCHIVE_DIR:-}" ]] || soviez_migration_p22_paths_init
  printf '%s/%s\n' "$SOVIEZ_MIG_SOURCE_ARCHIVE_DIR" "$1"
}

soviez_migration_p22_archive_plan_path() {
  printf '%s/plan.json\n' "$(soviez_migration_p22_archive_op_dir "$1")"
}

soviez_migration_p22_archive_manifest_path() {
  printf '%s/manifest.json\n' "$(soviez_migration_p22_archive_op_dir "$1")"
}

soviez_migration_p22_archive_state_path() {
  printf '%s/state.json\n' "$(soviez_migration_p22_archive_op_dir "$1")"
}

# --- end migration/source_archive/paths.sh ---

# --- begin migration/source_archive/model.sh ---
# shellcheck shell=bash

soviez_migration_p22_archive_state_write() {
  local op_id="$1" state="$2"
  local source_id="${3:-}" cutover_id="${4:-}" auth_id="${5:-}" more_json="${6:-{}}"
  local f
  f="$(soviez_migration_p22_archive_state_path "$op_id")"
  mkdir -p "$(dirname "$f")"
  SOVIEZ_OUT="$f" SOVIEZ_OP="$op_id" SOVIEZ_ST="$state" \
  SOVIEZ_SID="$source_id" SOVIEZ_CID="$cutover_id" SOVIEZ_AID="$auth_id" \
  SOVIEZ_MORE="$more_json" python3 - <<'PY'
import json, os
existing={}
try:
  existing=json.load(open(os.environ["SOVIEZ_OUT"]))
except Exception:
  existing={}
existing.update({
  "operation_id": os.environ["SOVIEZ_OP"],
  "current_state": os.environ["SOVIEZ_ST"],
})
if os.environ.get("SOVIEZ_SID"):
  existing["source_id"] = os.environ["SOVIEZ_SID"]
if os.environ.get("SOVIEZ_CID"):
  existing["cutover_id"] = os.environ["SOVIEZ_CID"]
if os.environ.get("SOVIEZ_AID"):
  existing["authorization_id"] = os.environ["SOVIEZ_AID"]
more_raw = os.environ.get("SOVIEZ_MORE") or "{}"
try:
  more = json.loads(more_raw)
  if isinstance(more, dict):
    existing.update(more)
except Exception:
  pass
open(os.environ["SOVIEZ_OUT"],"w").write(json.dumps(existing, separators=(",", ":")))
PY
  cat "$f"
}

# --- end migration/source_archive/model.sh ---

# --- begin migration/source_archive/targeting.sh ---
# shellcheck shell=bash

soviez_migration_p22_archive_resolve_source() {
  local source_id="${1:-}"
  [[ -n "$source_id" ]] || soviez_migration_die MIGRATION_SOURCE_REQUIRED "source-id required"
  # source_id may be cutover op id OR production/source id mapped via env.
  local cutover_id="${SOVIEZ_MIG_P22_CUTOVER_ID:-$source_id}"
  local st
  st="$(soviez_migration_p22_require_phase21_cutover "$cutover_id")"
  # Rollback window must be closed.
  local byc
  byc="$(soviez_migration_p22_closure_by_cutover_path "$cutover_id")"
  [[ -f "$byc" ]] || soviez_migration_die MIGRATION_ROLLBACK_WINDOW_STILL_REQUIRED "rollback window not closed"
  local ara
  ara="$(soviez_json_get "$(cat "$byc")" automatic_rollback_allowed)"
  [[ "$ara" == "False" || "$ara" == "false" ]] || \
    soviez_migration_die MIGRATION_ROLLBACK_WINDOW_STILL_REQUIRED "automatic rollback still allowed"
  printf '%s\n' "$st"
}

# --- end migration/source_archive/targeting.sh ---

# --- begin migration/source_archive/inventory.sh ---
# shellcheck shell=bash

soviez_migration_p22_archive_inventory() {
  local op_id="$1" source_root="${2:-}"
  source_root="${source_root:-${SOVIEZ_MIG_P22_SOURCE_ROOT:-}}"
  [[ -n "$source_root" && -d "$source_root" ]] || \
    soviez_migration_die MIGRATION_SOURCE_ARCHIVE_CREATE_FAILED "source root required"
  local out
  out="$(soviez_migration_p22_archive_op_dir "$op_id")/inventory.json"
  mkdir -p "$(dirname "$out")"
  SOVIEZ_OUT="$out" SOVIEZ_ROOT="$source_root" python3 - <<'PY'
import json, os, hashlib
root=os.environ["SOVIEZ_ROOT"]
files=[]
for dirpath, dirnames, filenames in os.walk(root):
  # deny traversal escapes later; skip special dirs
  for fn in filenames:
    p=os.path.join(dirpath, fn)
    rel=os.path.relpath(p, root)
    if rel.startswith(".."):
      continue
    st=os.lstat(p)
    if os.path.islink(p) or not os.path.isfile(p):
      continue
    h=hashlib.sha256(open(p,"rb").read()).hexdigest()
    files.append({"path":rel.replace("\\\\","/"),"size":st.st_size,"sha256":h})
open(os.environ["SOVIEZ_OUT"],"w").write(json.dumps({
  "source_root": root,
  "file_count": len(files),
  "files": files,
}, separators=(",", ":")))
print(open(os.environ["SOVIEZ_OUT"]).read())
PY
}

# --- end migration/source_archive/inventory.sh ---

# --- begin migration/source_archive/database.sh ---
# shellcheck shell=bash

soviez_migration_p22_archive_database() {
  local op_id="$1"
  local out_dir out_file db_name require_real real_pg=0
  out_dir="$(soviez_migration_p22_archive_op_dir "$op_id")/database"
  mkdir -p "$out_dir"
  out_file="$out_dir/dump.fc"
  db_name="${SOVIEZ_MIG_P22_SOURCE_DB_NAME:-${SOVIEZ_MIG_SOURCE_DB_NAME:-soviez_src}}"
  require_real="${SOVIEZ_MIG_P22_REQUIRE_REAL_PG:-0}"

  if [[ -n "${SOVIEZ_MIG_PG_DUMP_CID:-}" ]] && command -v docker >/dev/null 2>&1; then
    docker exec -e PGPASSWORD="${SOVIEZ_MIG_PG_PASSWORD:-soviez}" "${SOVIEZ_MIG_PG_DUMP_CID}" \
      pg_dump -Fc -U "${SOVIEZ_MIG_PG_USER:-postgres}" -d "$db_name" > "$out_file" || \
      soviez_migration_die MIGRATION_SOURCE_ARCHIVE_CREATE_FAILED "pg_dump -Fc failed"
    real_pg=1
  elif [[ "$require_real" != "1" && -n "${SOVIEZ_MIG_FIXTURE_DB_DUMP:-}" && -f "${SOVIEZ_MIG_FIXTURE_DB_DUMP}" ]]; then
    # Synthetic/pinned copy allowed only when real PG is not required.
    cp -f "$SOVIEZ_MIG_FIXTURE_DB_DUMP" "$out_file"
  elif command -v pg_dump >/dev/null 2>&1 && [[ -n "${SOVIEZ_MIG_P22_PG_DSN:-}" ]]; then
    pg_dump -Fc "$SOVIEZ_MIG_P22_PG_DSN" -f "$out_file" || \
      soviez_migration_die MIGRATION_SOURCE_ARCHIVE_CREATE_FAILED "pg_dump failed"
    real_pg=1
  elif command -v pg_dump >/dev/null 2>&1 && \
       { command -v psql >/dev/null 2>&1; } && \
       psql -U "${SOVIEZ_MIG_PG_USER:-postgres}" -d "$db_name" -c 'SELECT 1' >/dev/null 2>&1; then
    pg_dump -Fc -U "${SOVIEZ_MIG_PG_USER:-postgres}" -d "$db_name" -f "$out_file" || \
      soviez_migration_die MIGRATION_SOURCE_ARCHIVE_CREATE_FAILED "pg_dump -Fc failed"
    real_pg=1
  elif [[ "${SOVIEZ_MIG_P22_FIXTURE:-0}" == "1" && "$require_real" != "1" ]]; then
    # Synthetic PGDMP only when REQUIRE_REAL_PG is unset/0 (unit paths without postgres).
    printf 'PGDMP\x01soviez-p22-fixture\n' > "$out_file"
    printf 'CREATE TABLE p22_archive_probe(id int primary key, v text);\nINSERT INTO p22_archive_probe VALUES (1, '\''ok'\'');\n' > "$out_dir/dump.sql"
  else
    if [[ "$require_real" == "1" ]]; then
      soviez_migration_die MIGRATION_SOURCE_ARCHIVE_CREATE_FAILED \
        "SOVIEZ_MIG_P22_REQUIRE_REAL_PG=1 requires real pg_dump -Fc (synthetic PGDMP forbidden)"
    fi
    soviez_migration_die MIGRATION_SOURCE_ARCHIVE_CREATE_FAILED "no postgres dump capability"
  fi

  if [[ "$require_real" == "1" && "$real_pg" -ne 1 ]]; then
    soviez_migration_die MIGRATION_SOURCE_ARCHIVE_CREATE_FAILED \
      "SOVIEZ_MIG_P22_REQUIRE_REAL_PG=1 forbids synthetic/header-only dump"
  fi

  local digest size
  digest="$(openssl dgst -sha256 "$out_file" | awk '{print $NF}')"
  size="$(wc -c < "$out_file" | tr -d ' ')"
  SOVIEZ_OUT="$out_dir/meta.json" SOVIEZ_D="$digest" SOVIEZ_S="$size" SOVIEZ_DB="$db_name" \
  SOVIEZ_REAL="$real_pg" python3 - <<'PY'
import json, os, datetime
open(os.environ["SOVIEZ_OUT"],"w").write(json.dumps({
  "database_name": os.environ["SOVIEZ_DB"],
  "path": "dump.fc",
  "sha256": os.environ["SOVIEZ_D"],
  "size_bytes": int(os.environ["SOVIEZ_S"]),
  "format": "custom",
  "real_pg_dump": os.environ["SOVIEZ_REAL"] == "1",
  "created_at": datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%SZ"),
}, separators=(",", ":")))
print(open(os.environ["SOVIEZ_OUT"]).read())
PY
}

# --- end migration/source_archive/database.sh ---

# --- begin migration/source_archive/filestore.sh ---
# shellcheck shell=bash

soviez_migration_p22_archive_filestore() {
  local op_id="$1" source_root="${2:-}"
  source_root="${source_root:-${SOVIEZ_MIG_P22_SOURCE_FILESTORE:-${SOVIEZ_MIG_P22_SOURCE_ROOT:-}}}"
  [[ -n "$source_root" && -d "$source_root" ]] || \
    soviez_migration_die MIGRATION_SOURCE_ARCHIVE_CREATE_FAILED "filestore root required"

  local out_dir tar_path manifest
  out_dir="$(soviez_migration_p22_archive_op_dir "$op_id")/filestore"
  mkdir -p "$out_dir"
  tar_path="$out_dir/filestore.tar"
  manifest="$out_dir/manifest.json"

  # Pre-scan: deny symlink escape, path traversal, device, fifo.
  SOVIEZ_ROOT="$source_root" python3 - <<'PY'
import os, sys, stat
root=os.path.realpath(os.environ["SOVIEZ_ROOT"])
for dirpath, dirnames, filenames in os.walk(root, followlinks=False):
  for name in dirnames + filenames:
    p=os.path.join(dirpath, name)
    rel=os.path.relpath(p, root)
    if ".." in rel.split(os.sep):
      print("path traversal", rel, file=sys.stderr); sys.exit(2)
    st=os.lstat(p)
    if stat.S_ISLNK(st.st_mode):
      target=os.path.realpath(p)
      if not (target==root or target.startswith(root+os.sep)):
        print("symlink escape", rel, file=sys.stderr); sys.exit(3)
    if stat.S_ISCHR(st.st_mode) or stat.S_ISBLK(st.st_mode) or stat.S_ISFIFO(st.st_mode) or stat.S_ISSOCK(st.st_mode):
      print("special file denied", rel, file=sys.stderr); sys.exit(4)
print("ok")
PY
  [[ $? -eq 0 ]] || soviez_migration_die MIGRATION_SOURCE_ARCHIVE_CREATE_FAILED "filestore safety scan failed"

  # Create tar with relative paths only.
  (
    cd "$source_root"
    tar -cf "$tar_path" .
  ) || soviez_migration_die MIGRATION_SOURCE_ARCHIVE_CREATE_FAILED "filestore tar failed"

  SOVIEZ_OUT="$manifest" SOVIEZ_ROOT="$source_root" SOVIEZ_TAR="$tar_path" python3 - <<'PY'
import json, os, hashlib, tarfile
root=os.environ["SOVIEZ_ROOT"]
entries=[]
with tarfile.open(os.environ["SOVIEZ_TAR"], "r:") as tf:
  for m in tf.getmembers():
    if not m.isfile():
      continue
    if m.name.startswith("/") or ".." in m.name.split("/"):
      raise SystemExit("unsafe tar member")
    f=tf.extractfile(m)
    data=f.read() if f else b""
    entries.append({"path": m.name.lstrip("./"), "size": len(data), "sha256": hashlib.sha256(data).hexdigest()})
tar_sha=hashlib.sha256(open(os.environ["SOVIEZ_TAR"],"rb").read()).hexdigest()
open(os.environ["SOVIEZ_OUT"],"w").write(json.dumps({
  "file_count": len(entries),
  "files": entries,
  "tar_sha256": tar_sha,
}, separators=(",", ":")))
print(open(os.environ["SOVIEZ_OUT"]).read())
PY
}

# --- end migration/source_archive/filestore.sh ---

