# shellcheck shell=bash

soviez_migration_p22_archive_certificates() {
  local op_id="$1"
  local out
  out="$(soviez_migration_p22_archive_op_dir "$op_id")/certificates.json"
  mkdir -p "$(dirname "$out")"
  # Retention metadata only — never revoke.
  printf '{"retained":true,"revoked":false,"revoke_authorized":false}\n' > "$out"
  cat "$out"
}

# --- end migration/source_archive/certificates.sh ---

# --- begin migration/source_archive/dns.sh ---
# shellcheck shell=bash

soviez_migration_p22_archive_dns() {
  local op_id="$1" cutover_id="${2:-}"
  local out snap
  out="$(soviez_migration_p22_archive_op_dir "$op_id")/dns_rollback_snapshot.json"
  mkdir -p "$(dirname "$out")"
  snap="$(soviez_migration_cutover_op_dir "$cutover_id")/dns_rollback_snapshot.json"
  if [[ -f "$snap" ]]; then
    cp -f "$snap" "$out"
  else
    printf '{"retained":true,"manual_recovery_only":true,"deleted":false}\n' > "$out"
  fi
  cat "$out"
}

# --- end migration/source_archive/dns.sh ---

# --- begin migration/source_archive/stages.sh ---
# shellcheck shell=bash

soviez_migration_p22_archive_stages() {
  local op_id="$1"
  local out status=ok
  out="$(soviez_migration_p22_archive_op_dir "$op_id")/stages.json"
  mkdir -p "$(dirname "$out")"
  # Metadata only — never delete Stage resources.
  if [[ "${SOVIEZ_MIG_P22_STAGE_MANDATORY_FAIL:-0}" == "1" ]]; then
    status=BLOCKED
  elif [[ "${SOVIEZ_MIG_P22_STAGE_OPTIONAL_FAIL:-0}" == "1" ]]; then
    status=WARNING
  fi
  SOVIEZ_OUT="$out" SOVIEZ_ST="$status" python3 - <<'PY'
import json, os
st=os.environ["SOVIEZ_ST"]
open(os.environ["SOVIEZ_OUT"],"w").write(json.dumps({
  "stages_metadata_archived": True,
  "stages_deleted": False,
  "status": st,
  "optional_fail_warning": st=="WARNING",
  "mandatory_fail_blocked": st=="BLOCKED",
}, separators=(",", ":")))
print(open(os.environ["SOVIEZ_OUT"]).read())
PY
  if [[ "$status" == "BLOCKED" ]]; then
    soviez_migration_die MIGRATION_STAGE_SOURCE_ARCHIVE_FAILED "mandatory stage archive metadata failed"
  fi
}

# --- end migration/source_archive/stages.sh ---

# --- begin migration/source_archive/infrastructure.sh ---
# shellcheck shell=bash

soviez_migration_p22_archive_infrastructure() {
  local op_id="$1"
  local out
  out="$(soviez_migration_p22_archive_op_dir "$op_id")/infrastructure.json"
  mkdir -p "$(dirname "$out")"
  printf '{"host_retained":true,"volumes_retained":true,"termination_authorized":false}\n' > "$out"
  cat "$out"
}

# --- end migration/source_archive/infrastructure.sh ---

# --- begin migration/source_archive/encryption.sh ---
# shellcheck shell=bash

soviez_migration_p22_archive_encrypt() {
  local op_id="$1"
  local op_dir plain enc
  op_dir="$(soviez_migration_p22_archive_op_dir "$op_id")"
  # Bundle database + filestore into a package then encrypt.
  plain="$op_dir/archive_bundle.tar"
  enc="$op_dir/archive_bundle.tar.enc"
  (
    cd "$op_dir"
    tar -cf "$plain" database filestore addons.json config secret_inventory.json \
      certificates.json dns_rollback_snapshot.json stages.json infrastructure.json 2>/dev/null || \
    tar -cf "$plain" database filestore 2>/dev/null || true
  )
  [[ -f "$plain" ]] || soviez_migration_die MIGRATION_SOURCE_ARCHIVE_CREATE_FAILED "bundle missing"
  export SOVIEZ_BACKUP_PASSPHRASE="${SOVIEZ_BACKUP_PASSPHRASE:-p22-fixture-passphrase}"
  soviez_backup_encrypt_file "$plain" "$enc"
  local digest
  digest="$(openssl dgst -sha256 "$enc" | awk '{print $NF}')"
  printf '{"encrypted_path":"archive_bundle.tar.enc","sha256":"%s","plaintext_retained":false}\n' "$digest" \
    > "$op_dir/encryption.json"
  # Remove plaintext bundle from archive dir (source data untouched).
  rm -f "$plain"
  cat "$op_dir/encryption.json"
}

# --- end migration/source_archive/encryption.sh ---

# --- begin migration/source_archive/store.sh ---
# shellcheck shell=bash
# Optional remote copy of encrypted archive bundle (Phase 16 destination primitives).
# Interrupt / lost-ack hooks for Phase 22 G3 certification. Never deletes source data.

soviez_migration_p22_archive_remote_enabled() {
  [[ -n "${SOVIEZ_MIG_P22_ARCHIVE_S3_PROFILE:-}" || -n "${SOVIEZ_MIG_P22_ARCHIVE_SFTP_PROFILE:-}" ]]
}

soviez_migration_p22_archive_store_receipt_path() {
  printf '%s/remote_store.json\n' "$(soviez_migration_p22_archive_op_dir "$1")"
}

soviez_migration_p22_archive_store_ack_path() {
  printf '%s/remote_store.ack\n' "$(soviez_migration_p22_archive_op_dir "$1")"
}

# Exact-path upload of archive_bundle.tar.enc via Phase 16 S3/SFTP helpers.
soviez_migration_p22_archive_store_remote() {
  local op_id="$1"
  local op_dir enc staging receipt ackf kind profile_id profile prod_id backup_id out
  op_dir="$(soviez_migration_p22_archive_op_dir "$op_id")"
  enc="$op_dir/archive_bundle.tar.enc"
  receipt="$(soviez_migration_p22_archive_store_receipt_path "$op_id")"
  ackf="$(soviez_migration_p22_archive_store_ack_path "$op_id")"

  [[ -f "$enc" ]] || soviez_migration_die MIGRATION_SOURCE_ARCHIVE_CREATE_FAILED "encrypted bundle missing for remote store"

  # Idempotent: already stored + acknowledged.
  if [[ -f "$receipt" && -f "$ackf" ]]; then
    if [[ "$(soviez_json_get "$(cat "$receipt")" status 2>/dev/null || true)" == "stored" ]]; then
      cat "$receipt"
      return 0
    fi
  fi

  # Lost-ack recovery: remote write completed, local ack missing → re-ack without re-upload if object present.
  if [[ -f "$receipt" ]] && [[ "$(soviez_json_get "$(cat "$receipt")" write_completed 2>/dev/null || true)" == "True" \
       || "$(soviez_json_get "$(cat "$receipt")" write_completed 2>/dev/null || true)" == "true" ]]; then
    if [[ ! -f "$ackf" ]]; then
      if [[ "${SOVIEZ_MIG_P22_ARCHIVE_LOST_ACK:-0}" == "1" ]]; then
        # First pass after write: pretend ack lost (injection once).
        unset SOVIEZ_MIG_P22_ARCHIVE_LOST_ACK
        export SOVIEZ_MIG_P22_ARCHIVE_LOST_ACK=0
        soviez_migration_die MIGRATION_SOURCE_ARCHIVE_TRANSFER_INTERRUPTED \
          "injected lost-ack after remote archive write"
      fi
      printf 'acked\n' > "$ackf"
      SOVIEZ_R="$receipt" python3 - <<'PY'
import json, os
p=os.environ["SOVIEZ_R"]
d=json.load(open(p))
d["status"]="stored"
d["ack"]="idempotent_retry"
d["duplicate_upload"]=False
open(p,"w").write(json.dumps(d, separators=(",", ":")))
print(open(p).read())
PY
      return 0
    fi
  fi

  if ! soviez_migration_p22_archive_remote_enabled; then
    # Local-only archive is valid outside remote cert destinations.
    printf '{"status":"local_only","operation_id":"%s","purge_authorized":false}\n' "$op_id" > "$receipt"
    cat "$receipt"
    return 0
  fi

  if [[ "${SOVIEZ_MIG_P22_ARCHIVE_UPLOAD_INTERRUPT:-0}" == "1" ]]; then
    unset SOVIEZ_MIG_P22_ARCHIVE_UPLOAD_INTERRUPT
    export SOVIEZ_MIG_P22_ARCHIVE_UPLOAD_INTERRUPT=0
    soviez_migration_die MIGRATION_SOURCE_ARCHIVE_TRANSFER_INTERRUPTED "injected interrupt mid-upload once"
  fi

  staging="$op_dir/remote_staging"
  mkdir -p "$staging"
  # Exact filename required by cert tests.
  cp -f "$enc" "$staging/archive_bundle.tar.enc"
  prod_id="p22-archive"
  backup_id="$op_id"

  if [[ -n "${SOVIEZ_MIG_P22_ARCHIVE_S3_PROFILE:-}" ]]; then
    kind=s3
    profile_id="$SOVIEZ_MIG_P22_ARCHIVE_S3_PROFILE"
    if [[ "${SOVIEZ_MIG_P22_S3_INTERRUPT:-0}" == "1" ]] || [[ -n "${SOVIEZ_BACKUP_S3_INTERRUPT:-}" ]]; then
      # before_first_part works for small objects; middle_part needs multipart (>=2 parts).
      export SOVIEZ_BACKUP_S3_INTERRUPT="${SOVIEZ_BACKUP_S3_INTERRUPT:-before_first_part}"
    fi
    profile="$(soviez_backup_destination_resolve "$profile_id")"
    set +e
    out="$(soviez_backup_s3_dest_put "$profile" "$staging" "$backup_id" "$prod_id" 2>&1)"
    local rc=$?
    set -e
    unset SOVIEZ_BACKUP_S3_INTERRUPT 2>/dev/null || true
    unset SOVIEZ_MIG_P22_S3_INTERRUPT 2>/dev/null || true
    export SOVIEZ_MIG_P22_S3_INTERRUPT=0
    if [[ $rc -ne 0 ]]; then
      if printf '%s' "$out" | grep -q BACKUP_TRANSFER_INTERRUPTED; then
        soviez_migration_die MIGRATION_SOURCE_ARCHIVE_TRANSFER_INTERRUPTED "S3 archive upload interrupted"
      fi
      soviez_migration_die MIGRATION_SOURCE_ARCHIVE_CREATE_FAILED "S3 archive upload failed: $out"
    fi
  elif [[ -n "${SOVIEZ_MIG_P22_ARCHIVE_SFTP_PROFILE:-}" ]]; then
    kind=sftp
    profile_id="$SOVIEZ_MIG_P22_ARCHIVE_SFTP_PROFILE"
    if [[ "${SOVIEZ_MIG_P22_SFTP_INTERRUPT:-0}" == "1" ]] || [[ -n "${SOVIEZ_BACKUP_SFTP_INTERRUPT:-}" ]]; then
      export SOVIEZ_BACKUP_SFTP_INTERRUPT="${SOVIEZ_BACKUP_SFTP_INTERRUPT:-mid_upload}"
    fi
    profile="$(soviez_backup_destination_resolve "$profile_id")"
    set +e
    out="$(soviez_backup_sftp_dest_put "$profile" "$staging" "$backup_id" "$prod_id" 2>&1)"
    local rc=$?
    set -e
    unset SOVIEZ_BACKUP_SFTP_INTERRUPT 2>/dev/null || true
    unset SOVIEZ_MIG_P22_SFTP_INTERRUPT 2>/dev/null || true
    export SOVIEZ_MIG_P22_SFTP_INTERRUPT=0
    if [[ $rc -ne 0 ]]; then
      if printf '%s' "$out" | grep -q BACKUP_TRANSFER_INTERRUPTED; then
        soviez_migration_die MIGRATION_SOURCE_ARCHIVE_TRANSFER_INTERRUPTED "SFTP archive upload interrupted"
      fi
      soviez_migration_die MIGRATION_SOURCE_ARCHIVE_CREATE_FAILED "SFTP archive upload failed: $out"
    fi
  else
    soviez_migration_die MIGRATION_SOURCE_ARCHIVE_CREATE_FAILED "remote store profile missing"
  fi

  # Mark write completed before local ack (lost-ack window).
  SOVIEZ_OUT="$receipt" SOVIEZ_OP="$op_id" SOVIEZ_KIND="$kind" SOVIEZ_PROF="$profile_id" \
  SOVIEZ_LOC="${out:-}" SOVIEZ_NOW="$(soviez_migration_p22_now_iso)" python3 - <<'PY'
import json, os
body={
  "schema":"soviez.migration_source_archive_remote_store.v1",
  "operation_id": os.environ["SOVIEZ_OP"],
  "kind": os.environ["SOVIEZ_KIND"],
  "profile_id": os.environ["SOVIEZ_PROF"],
  "object":"archive_bundle.tar.enc",
  "location": os.environ.get("SOVIEZ_LOC","").strip().splitlines()[-1] if os.environ.get("SOVIEZ_LOC") else "",
  "write_completed": True,
  "status": "write_completed",
  "purge_authorized": False,
  "deletion_performed": False,
  "duplicate_upload": False,
  "stored_at": os.environ["SOVIEZ_NOW"],
}
open(os.environ["SOVIEZ_OUT"],"w").write(json.dumps(body, separators=(",", ":")))
PY

  if [[ "${SOVIEZ_MIG_P22_ARCHIVE_LOST_ACK:-0}" == "1" ]]; then
    unset SOVIEZ_MIG_P22_ARCHIVE_LOST_ACK
    export SOVIEZ_MIG_P22_ARCHIVE_LOST_ACK=0
    soviez_migration_die MIGRATION_SOURCE_ARCHIVE_TRANSFER_INTERRUPTED \
      "injected lost-ack after remote archive write"
  fi

  printf 'acked\n' > "$ackf"
  SOVIEZ_R="$receipt" python3 - <<'PY'
import json, os
p=os.environ["SOVIEZ_R"]
d=json.load(open(p))
d["status"]="stored"
d["ack"]="ok"
open(p,"w").write(json.dumps(d, separators=(",", ":")))
print(open(p).read())
PY
}

# Retrieve remote copy (optional verify). Interrupt once then clear.
soviez_migration_p22_archive_retrieve_remote() {
  local op_id="$1"
  local dest="${2:-}"
  local op_dir enc receipt kind profile_id profile prod_id backup_id out
  op_dir="$(soviez_migration_p22_archive_op_dir "$op_id")"
  enc="$op_dir/archive_bundle.tar.enc"
  receipt="$(soviez_migration_p22_archive_store_receipt_path "$op_id")"
  dest="${dest:-$op_dir/remote_retrieve}"
  mkdir -p "$dest"

  if [[ "${SOVIEZ_MIG_P22_ARCHIVE_RETRIEVE_INTERRUPT:-0}" == "1" ]]; then
    unset SOVIEZ_MIG_P22_ARCHIVE_RETRIEVE_INTERRUPT
    export SOVIEZ_MIG_P22_ARCHIVE_RETRIEVE_INTERRUPT=0
    soviez_migration_die MIGRATION_SOURCE_ARCHIVE_TRANSFER_INTERRUPTED "injected interrupt mid-retrieve once"
  fi

  [[ -f "$receipt" ]] || soviez_migration_die MIGRATION_SOURCE_ARCHIVE_CREATE_FAILED "remote store receipt missing"
  kind="$(soviez_json_get "$(cat "$receipt")" kind)"
  profile_id="$(soviez_json_get "$(cat "$receipt")" profile_id)"
  prod_id="p22-archive"
  backup_id="$op_id"
  profile="$(soviez_backup_destination_resolve "$profile_id")"

  if [[ "$kind" == "s3" ]]; then
    set +e
    out="$(soviez_backup_s3_dest_get "$profile" "$dest" "$backup_id" "$prod_id" 2>&1)"
    local rc=$?
    set -e
    if [[ $rc -ne 0 ]]; then
      if printf '%s' "$out" | grep -q BACKUP_TRANSFER_INTERRUPTED; then
        soviez_migration_die MIGRATION_SOURCE_ARCHIVE_TRANSFER_INTERRUPTED "S3 retrieve interrupted"
      fi
      soviez_migration_die MIGRATION_SOURCE_ARCHIVE_CREATE_FAILED "S3 retrieve failed"
    fi
  elif [[ "$kind" == "sftp" ]]; then
    set +e
    out="$(soviez_backup_sftp_dest_get "$profile" "$dest" "$backup_id" "$prod_id" 2>&1)"
    local rc=$?
    set -e
    if [[ $rc -ne 0 ]]; then
      if printf '%s' "$out" | grep -q BACKUP_TRANSFER_INTERRUPTED; then
        soviez_migration_die MIGRATION_SOURCE_ARCHIVE_TRANSFER_INTERRUPTED "SFTP retrieve interrupted"
      fi
      soviez_migration_die MIGRATION_SOURCE_ARCHIVE_CREATE_FAILED "SFTP retrieve failed"
    fi
  else
    # local_only — copy local enc
    cp -f "$enc" "$dest/archive_bundle.tar.enc"
  fi
  printf '{"status":"retrieved","operation_id":"%s","dest":"%s"}\n' "$op_id" "$dest"
}

# --- end migration/source_archive/store.sh ---

# --- begin migration/source_archive/cert_gates.sh ---
# shellcheck shell=bash
# Phase 22 certification-mode hard gates. Fail closed on material skips.

soviez_migration_p22_cert_mode() {
  [[ "${SOVIEZ_PHASE22_CERTIFICATION:-0}" == "1" ]]
}

soviez_migration_p22_apply_cert_defaults() {
  soviez_migration_p22_cert_mode || return 0
  export SOVIEZ_PHASE22_REQUIRE_REAL_POSTGRES="${SOVIEZ_PHASE22_REQUIRE_REAL_POSTGRES:-1}"
  export SOVIEZ_PHASE22_REQUIRE_REAL_ARCHIVE_ENCRYPTION="${SOVIEZ_PHASE22_REQUIRE_REAL_ARCHIVE_ENCRYPTION:-1}"
  export SOVIEZ_PHASE22_REQUIRE_REAL_RESTORE_TEST="${SOVIEZ_PHASE22_REQUIRE_REAL_RESTORE_TEST:-1}"
  export SOVIEZ_PHASE22_REQUIRE_REAL_S3="${SOVIEZ_PHASE22_REQUIRE_REAL_S3:-1}"
  export SOVIEZ_PHASE22_REQUIRE_REAL_SFTP="${SOVIEZ_PHASE22_REQUIRE_REAL_SFTP:-1}"
  export SOVIEZ_PHASE22_REQUIRE_HOST_REBOOT="${SOVIEZ_PHASE22_REQUIRE_HOST_REBOOT:-1}"
  export SOVIEZ_PHASE22_REQUIRE_NETWORK_INTERRUPTION="${SOVIEZ_PHASE22_REQUIRE_NETWORK_INTERRUPTION:-1}"
  export SOVIEZ_PHASE22_FORBID_REBOOT_SIMULATION="${SOVIEZ_PHASE22_FORBID_REBOOT_SIMULATION:-1}"
  export SOVIEZ_PHASE22_FORBID_FIXTURE_ARCHIVE="${SOVIEZ_PHASE22_FORBID_FIXTURE_ARCHIVE:-1}"
  export SOVIEZ_PHASE22_FORBID_MATERIAL_SKIPS="${SOVIEZ_PHASE22_FORBID_MATERIAL_SKIPS:-1}"
  export SOVIEZ_MIG_P22_REQUIRE_REAL_PG="${SOVIEZ_MIG_P22_REQUIRE_REAL_PG:-1}"
  # Do NOT silently clear material skips — assert_cert_gates fails closed if they are set.
}

soviez_migration_p22_assert_cert_gates() {
  soviez_migration_p22_apply_cert_defaults
  soviez_migration_p22_cert_mode || return 0

  if [[ "${SOVIEZ_PHASE22_FORBID_FIXTURE_ARCHIVE:-1}" == "1" ]]; then
    if [[ "${SOVIEZ_MIG_P22_REQUIRE_REAL_PG:-0}" != "1" ]]; then
      soviez_migration_die MIGRATION_PHASE22_CERT_GATE \
        "certification forbids fixture archive without SOVIEZ_MIG_P22_REQUIRE_REAL_PG=1"
    fi
  fi
  if [[ "${SOVIEZ_PHASE22_REQUIRE_REAL_POSTGRES:-1}" == "1" && "${SOVIEZ_MIG_P22_REQUIRE_REAL_PG:-0}" != "1" ]]; then
    soviez_migration_die MIGRATION_PHASE22_CERT_GATE "certification requires real postgres"
  fi
  if [[ "${SOVIEZ_PHASE22_REQUIRE_REAL_RESTORE_TEST:-1}" == "1" && "${SOVIEZ_MIG_P22_REQUIRE_REAL_PG:-0}" != "1" ]]; then
    soviez_migration_die MIGRATION_PHASE22_CERT_GATE "certification requires real restore test / real PG"
  fi
  if [[ "${SOVIEZ_PHASE22_REQUIRE_REAL_ARCHIVE_ENCRYPTION:-1}" == "1" ]]; then
    if [[ "${SOVIEZ_BACKUP_DISABLE_ENCRYPTION:-0}" == "1" ]]; then
      soviez_migration_die MIGRATION_PHASE22_CERT_GATE "certification requires real archive encryption"
    fi
  fi
  if [[ "${SOVIEZ_PHASE22_FORBID_REBOOT_SIMULATION:-1}" == "1" && "${SOVIEZ_PHASE22_ALLOW_REBOOT_SIM:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_PHASE22_CERT_GATE "certification forbids reboot simulation"
  fi
  if [[ "${SOVIEZ_PHASE22_FORBID_MATERIAL_SKIPS:-1}" == "1" ]]; then
    if [[ "${SOVIEZ_PHASE22_SKIP_HOST_REBOOT:-0}" == "1" ]]; then
      soviez_migration_die MIGRATION_PHASE22_CERT_GATE "material host reboot skip forbidden"
    fi
    if [[ "${SOVIEZ_PHASE22_SKIP_NETWORK_INTERRUPTION:-0}" == "1" ]]; then
      soviez_migration_die MIGRATION_PHASE22_CERT_GATE "material network interruption skip forbidden"
    fi
    if [[ "${SOVIEZ_PHASE22_SKIP_S3:-0}" == "1" ]]; then
      soviez_migration_die MIGRATION_PHASE22_CERT_GATE "material S3 skip forbidden"
    fi
    if [[ "${SOVIEZ_PHASE22_SKIP_SFTP:-0}" == "1" ]]; then
      soviez_migration_die MIGRATION_PHASE22_CERT_GATE "material SFTP skip forbidden"
    fi
  fi
  if [[ "${SOVIEZ_PHASE22_REQUIRE_HOST_REBOOT:-0}" == "1" && "${SOVIEZ_PHASE22_SKIP_HOST_REBOOT:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_PHASE22_CERT_GATE "material host reboot skip forbidden"
  fi
  if [[ "${SOVIEZ_PHASE22_REQUIRE_NETWORK_INTERRUPTION:-0}" == "1" && "${SOVIEZ_PHASE22_SKIP_NETWORK_INTERRUPTION:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_PHASE22_CERT_GATE "material network interruption skip forbidden"
  fi
  if [[ "${SOVIEZ_PHASE22_REQUIRE_REAL_S3:-0}" == "1" && "${SOVIEZ_PHASE22_SKIP_S3:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_PHASE22_CERT_GATE "material S3 skip forbidden"
  fi
  if [[ "${SOVIEZ_PHASE22_REQUIRE_REAL_SFTP:-0}" == "1" && "${SOVIEZ_PHASE22_SKIP_SFTP:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_PHASE22_CERT_GATE "material SFTP skip forbidden"
  fi
  if [[ "${SOVIEZ_MIG_SOURCE_PURGE:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_PURGE_NOT_AUTHORIZED "purge forbidden in certification"
  fi
  return 0
}

# Test-helper alias (matches phase19 naming).
soviez_phase22_assert_cert_gates() {
  soviez_migration_p22_assert_cert_gates
}

# --- end migration/source_archive/cert_gates.sh ---

# --- begin migration/source_archive/manifest.sh ---
# shellcheck shell=bash

soviez_migration_p22_archive_write_manifest() {
  local op_id="$1" cutover_id="$2" source_id="$3"
  local op_dir manifest pinned
  op_dir="$(soviez_migration_p22_archive_op_dir "$op_id")"
  manifest="$op_dir/manifest.json"
  pinned="${SOVIEZ_MIG_P22_PINNED_BACKUP:-}"
  [[ -n "$pinned" && -e "$pinned" ]] || \
    soviez_migration_die MIGRATION_SOURCE_BACKUP_REQUIRED "independent recovery copy (pinned rollback backup) required"

  local enc_sha
  enc_sha="$(soviez_json_get "$(cat "$op_dir/encryption.json")" sha256)"

  SOVIEZ_OUT="$manifest" SOVIEZ_OP="$op_id" SOVIEZ_CID="$cutover_id" SOVIEZ_SID="$source_id" \
  SOVIEZ_ENC="$enc_sha" SOVIEZ_PIN="$pinned" SOVIEZ_NOW="$(soviez_migration_p22_now_iso)" python3 - <<'PY'
import json, os
body={
  "schema":"soviez.migration_source_archive_manifest.v1",
  "operation_id": os.environ["SOVIEZ_OP"],
  "cutover_id": os.environ["SOVIEZ_CID"],
  "source_id": os.environ["SOVIEZ_SID"],
  "encrypted_sha256": os.environ["SOVIEZ_ENC"],
  "independent_recovery_copy": os.environ["SOVIEZ_PIN"],
  "purge_authorized": False,
  "deletion_performed": False,
  "source_data_deleted": False,
  "backup_deleted": False,
  "certificate_revoked": False,
  "created_at": os.environ["SOVIEZ_NOW"],
  "signer": "soviez-p22",
}
open(os.environ["SOVIEZ_OUT"],"w").write(json.dumps(body, separators=(",", ":")))
PY
  cat "$manifest"
}

# --- end migration/source_archive/manifest.sh ---

# --- begin migration/source_archive/signing.sh ---
# shellcheck shell=bash

soviez_migration_p22_archive_sign_manifest() {
  local op_id="$1"
  local manifest
  manifest="$(soviez_migration_p22_archive_manifest_path "$op_id")"
  [[ -f "$manifest" ]] || soviez_migration_die MIGRATION_SOURCE_ARCHIVE_VERIFY_FAILED "manifest missing"
  soviez_migration_sign_object_file "$manifest"
  cat "$manifest"
}

# --- end migration/source_archive/signing.sh ---

# --- begin migration/source_archive/verify.sh ---
# shellcheck shell=bash

soviez_migration_p22_archive_verify() {
  local op_id="$1"
  local op_dir manifest enc
  op_dir="$(soviez_migration_p22_archive_op_dir "$op_id")"
  manifest="$(soviez_migration_p22_archive_manifest_path "$op_id")"
  enc="$op_dir/archive_bundle.tar.enc"
  [[ -f "$manifest" && -f "$enc" ]] || \
    soviez_migration_die MIGRATION_SOURCE_ARCHIVE_VERIFY_FAILED "archive artifacts missing"
  soviez_migration_verify_object_signature "$manifest" || \
    soviez_migration_die MIGRATION_SOURCE_ARCHIVE_VERIFY_FAILED "manifest signature invalid"
  local expected actual
  expected="$(soviez_json_get "$(cat "$manifest")" encrypted_sha256)"
  actual="$(openssl dgst -sha256 "$enc" | awk '{print $NF}')"
  [[ "$expected" == "$actual" ]] || \
    soviez_migration_die MIGRATION_SOURCE_ARCHIVE_VERIFY_FAILED "encrypted checksum mismatch"
  [[ "$(soviez_json_get "$(cat "$manifest")" purge_authorized)" == "False" || "$(soviez_json_get "$(cat "$manifest")" purge_authorized)" == "false" ]] || \
    soviez_migration_die MIGRATION_PURGE_NOT_AUTHORIZED "manifest must have purge_authorized=false"
  [[ "$(soviez_json_get "$(cat "$manifest")" deletion_performed)" == "False" || "$(soviez_json_get "$(cat "$manifest")" deletion_performed)" == "false" ]] || \
    soviez_migration_die MIGRATION_SOURCE_DELETE_NOT_AUTHORIZED "manifest must have deletion_performed=false"
  local pinned
  pinned="$(soviez_json_get "$(cat "$manifest")" independent_recovery_copy)"
  [[ -e "$pinned" ]] || soviez_migration_die MIGRATION_SOURCE_BACKUP_REQUIRED "pinned recovery copy missing"
  printf '{"verified":true,"operation_id":"%s"}\n' "$op_id"
}

# --- end migration/source_archive/verify.sh ---

# --- begin migration/source_archive/restore_test.sh ---
# shellcheck shell=bash
# Decrypt → restore into isolated DB → verify schema/counts → destroy ONLY restore target.

soviez_migration_p22_archive_restore_test() {
  local op_id="$1"
  local op_dir work enc plain restore_db require_real real_pg=0 probe_count=-1
  op_dir="$(soviez_migration_p22_archive_op_dir "$op_id")"
  work="$op_dir/restore_test"
  rm -rf "$work"
  mkdir -p "$work"
  enc="$op_dir/archive_bundle.tar.enc"
  plain="$work/archive_bundle.tar"
  export SOVIEZ_BACKUP_PASSPHRASE="${SOVIEZ_BACKUP_PASSPHRASE:-p22-fixture-passphrase}"
  soviez_backup_decrypt_file "$enc" "$plain"
  ( cd "$work" && tar -xf "$plain" ) || \
    soviez_migration_die MIGRATION_SOURCE_ARCHIVE_RESTORE_TEST_FAILED "decrypt/untar failed"

  [[ -f "$work/database/dump.fc" ]] || \
    soviez_migration_die MIGRATION_SOURCE_ARCHIVE_RESTORE_TEST_FAILED "dump missing after decrypt"
  [[ -f "$work/filestore/manifest.json" ]] || \
    soviez_migration_die MIGRATION_SOURCE_ARCHIVE_RESTORE_TEST_FAILED "filestore manifest missing"

  restore_db="soviez_p22_restore_${op_id//[^a-zA-Z0-9]/}"
  restore_db="${restore_db:0:60}"
  require_real="${SOVIEZ_MIG_P22_REQUIRE_REAL_PG:-0}"

  local ok=0
  # Synthetic header-only PASS is forbidden when real PG is required.
  if [[ "$require_real" != "1" && "${SOVIEZ_MIG_P22_FIXTURE:-0}" == "1" && -z "${SOVIEZ_MIG_PG_DUMP_CID:-}" ]]; then
    if head -c 5 "$work/database/dump.fc" | grep -q 'PGDMP'; then
      # Only accept synthetic when no docker/local restore path is available.
      if ! command -v pg_restore >/dev/null 2>&1 || \
         ! psql -U "${SOVIEZ_MIG_PG_USER:-postgres}" -d postgres -c 'SELECT 1' >/dev/null 2>&1; then
        ok=1
      fi
    fi
  fi

  if [[ "$ok" -ne 1 && -n "${SOVIEZ_MIG_PG_DUMP_CID:-}" ]] && command -v docker >/dev/null 2>&1; then
    docker exec -e PGPASSWORD="${SOVIEZ_MIG_PG_PASSWORD:-soviez}" "${SOVIEZ_MIG_PG_DUMP_CID}" \
      psql -U "${SOVIEZ_MIG_PG_USER:-postgres}" -d postgres -c "DROP DATABASE IF EXISTS ${restore_db};" >/dev/null
    docker exec -e PGPASSWORD="${SOVIEZ_MIG_PG_PASSWORD:-soviez}" "${SOVIEZ_MIG_PG_DUMP_CID}" \
      psql -U "${SOVIEZ_MIG_PG_USER:-postgres}" -d postgres -c "CREATE DATABASE ${restore_db};" >/dev/null
    if ! docker exec -i -e PGPASSWORD="${SOVIEZ_MIG_PG_PASSWORD:-soviez}" "${SOVIEZ_MIG_PG_DUMP_CID}" \
         pg_restore -U "${SOVIEZ_MIG_PG_USER:-postgres}" -d "$restore_db" --no-owner --no-acl < "$work/database/dump.fc" 2>/dev/null; then
      # pg_restore may exit non-zero on warnings; verify via probe table below.
      true
    fi
    probe_count="$(docker exec -e PGPASSWORD="${SOVIEZ_MIG_PG_PASSWORD:-soviez}" "${SOVIEZ_MIG_PG_DUMP_CID}" \
      psql -U "${SOVIEZ_MIG_PG_USER:-postgres}" -d "$restore_db" -Atc "SELECT count(*) FROM p22_archive_probe;" 2>/dev/null || echo -1)"
    if [[ "$probe_count" == "1" ]]; then
      ok=1
      real_pg=1
    fi
    # Destroy ONLY restore target (never source DB).
    docker exec -e PGPASSWORD="${SOVIEZ_MIG_PG_PASSWORD:-soviez}" "${SOVIEZ_MIG_PG_DUMP_CID}" \
      psql -U "${SOVIEZ_MIG_PG_USER:-postgres}" -d postgres -c "DROP DATABASE IF EXISTS ${restore_db};" >/dev/null
  elif [[ "$ok" -ne 1 ]] && command -v psql >/dev/null 2>&1 && command -v pg_restore >/dev/null 2>&1; then
    dropdb -U "${SOVIEZ_MIG_PG_USER:-postgres}" --if-exists "$restore_db" 2>/dev/null || true
    if createdb -U "${SOVIEZ_MIG_PG_USER:-postgres}" "$restore_db" 2>/dev/null; then
      pg_restore -U "${SOVIEZ_MIG_PG_USER:-postgres}" -d "$restore_db" --clean --if-exists "$work/database/dump.fc" 2>/dev/null || true
      if [[ -f "$work/database/dump.sql" && "$require_real" != "1" ]]; then
        psql -U "${SOVIEZ_MIG_PG_USER:-postgres}" -d "$restore_db" -f "$work/database/dump.sql" >/dev/null 2>&1 || true
      fi
      probe_count="$(psql -U "${SOVIEZ_MIG_PG_USER:-postgres}" -d "$restore_db" -Atc \
        "SELECT count(*) FROM p22_archive_probe;" 2>/dev/null || echo -1)"
      if [[ "$probe_count" == "1" ]]; then
        ok=1
        real_pg=1
      elif [[ "$require_real" != "1" ]]; then
        psql -U "${SOVIEZ_MIG_PG_USER:-postgres}" -d "$restore_db" -c "SELECT 1" >/dev/null 2>&1 && ok=1
      fi
      dropdb -U "${SOVIEZ_MIG_PG_USER:-postgres}" --if-exists "$restore_db" 2>/dev/null || true
    fi
    # Fall back to fixture header verification only when real PG is not required.
    if [[ "$ok" -ne 1 && "$require_real" != "1" && "${SOVIEZ_MIG_P22_FIXTURE:-0}" == "1" ]]; then
      head -c 5 "$work/database/dump.fc" | grep -q 'PGDMP' && ok=1
    fi
  fi

  if [[ "$ok" -ne 1 ]]; then
    if [[ "$require_real" == "1" ]]; then
      soviez_migration_die MIGRATION_SOURCE_ARCHIVE_RESTORE_TEST_FAILED \
        "REQUIRE_REAL_PG=1: real pg_restore + p22_archive_probe count=1 required (synthetic PASS forbidden)"
    fi
    soviez_migration_die MIGRATION_SOURCE_ARCHIVE_RESTORE_TEST_FAILED "restore test failed"
  fi

  if [[ "$require_real" == "1" && "$real_pg" -ne 1 ]]; then
    soviez_migration_die MIGRATION_SOURCE_ARCHIVE_RESTORE_TEST_FAILED \
      "REQUIRE_REAL_PG=1 forbids synthetic header-only restore PASS"
  fi

  # Persist result for acceptance / e2e assertions.
  SOVIEZ_OUT="$op_dir/restore_test.json" SOVIEZ_REAL="$real_pg" SOVIEZ_PROBE="$probe_count" python3 - <<'PY'
import json, os
body={
  "restore_test": "PASS",
  "restore_target_destroyed": True,
  "source_untouched": True,
  "real_pg_restore": os.environ["SOVIEZ_REAL"] == "1",
  "p22_archive_probe_count": int(os.environ.get("SOVIEZ_PROBE") or -1),
}
open(os.environ["SOVIEZ_OUT"], "w").write(json.dumps(body, separators=(",", ":")))
print(open(os.environ["SOVIEZ_OUT"]).read())
PY
  # Cleanup work dir only (never source).
  rm -rf "$work"
}

# --- end migration/source_archive/restore_test.sh ---

# --- begin migration/source_archive/full_erp_restore_test.sh ---
# shellcheck shell=bash

soviez_migration_p22_archive_full_erp_restore_test() {
  local op_id="$1"
  if [[ "${SOVIEZ_MIG_P22_SKIP_FULL_ERP_RESTORE:-0}" == "1" ]]; then
    printf '{"full_erp_restore_test":"SKIPPED","policy":"optional"}\n'
    return 0
  fi
  # Recommended: re-run DB restore test as proxy when full ERP stack unavailable.
  soviez_migration_p22_archive_restore_test "$op_id" >/dev/null
  printf '{"full_erp_restore_test":"PASS","mode":"database_proxy"}\n'
}

# --- end migration/source_archive/full_erp_restore_test.sh ---

# --- begin migration/source_archive/status.sh ---
# shellcheck shell=bash

soviez_migration_source_archive_status() {
  local op_id="${1:-}"
  [[ -n "$op_id" ]] || soviez_migration_die MIGRATION_NOT_FOUND "operation-id required"
  SOVIEZ_MIG_P22_MUTATING=0 soviez_migration_assert_phase22_allowed "$SOVIEZ_MIG_OP_SOURCE_ARCHIVE"
  soviez_migration_p22_paths_init
  local f
  f="$(soviez_migration_p22_archive_state_path "$op_id")"
  [[ -f "$f" ]] || soviez_migration_die MIGRATION_NOT_FOUND "archive operation not found"
  cat "$f"
}

# --- end migration/source_archive/status.sh ---

# --- begin migration/source_archive/report.sh ---
# shellcheck shell=bash

soviez_migration_p22_archive_report() {
  local op_id="$1"
  local f
  f="$(soviez_migration_p22_archive_op_dir "$op_id")/report.json"
  if [[ -f "$f" ]]; then cat "$f"; return 0; fi
  soviez_migration_source_archive_status "$op_id"
}

# --- end migration/source_archive/report.sh ---

# --- begin migration/source_archive/recover.sh ---
# shellcheck shell=bash

soviez_migration_source_archive_recover() {
  local op_id="${1:-}"
  export SOVIEZ_MIG_P22_CANONICAL=1
  soviez_migration_assert_phase22_allowed "$SOVIEZ_MIG_OP_SOURCE_ARCHIVE"
  local state
  state="$(soviez_json_get "$(soviez_migration_source_archive_status "$op_id")" current_state)"
  case "$state" in
    verified|complete)
      soviez_migration_source_archive_status "$op_id"
      ;;
    failed|create_failed|verify_failed)
      soviez_migration_source_archive_retry "$op_id"
      ;;
    *)
      soviez_migration_die MIGRATION_RECOVERY_REQUIRED "archive recovery required for state=$state"
      ;;
  esac
}

soviez_migration_source_archive_retry() {
  local op_id="${1:-}"
  export SOVIEZ_MIG_P22_CANONICAL=1
  soviez_migration_assert_phase22_allowed "$SOVIEZ_MIG_OP_SOURCE_ARCHIVE"
  local st source_id cutover_id
  st="$(soviez_migration_source_archive_status "$op_id")"
  source_id="$(soviez_json_get "$st" source_id)"
  cutover_id="$(soviez_json_get "$st" cutover_id)"
  export SOVIEZ_MIG_P22_CUTOVER_ID="$cutover_id"
  soviez_migration_source_archive_start "$source_id" "$op_id"
}

# --- end migration/source_archive/recover.sh ---

# --- begin migration/source_archive/engine.sh ---
# shellcheck shell=bash

soviez_migration_source_archive_plan() {
  local source_id="${1:-}"
  export SOVIEZ_MIG_P22_CANONICAL=1
  soviez_migration_p22_paths_init
  soviez_migration_assert_phase22_allowed "$SOVIEZ_MIG_OP_SOURCE_ARCHIVE_PLAN"
  local st auth_id cutover_id op_id
  cutover_id="${SOVIEZ_MIG_P22_CUTOVER_ID:-$source_id}"
  st="$(soviez_migration_p22_archive_resolve_source "$source_id")"
  auth_id="$(soviez_json_get "$st" authorization_id)"
  op_id="$(soviez_migration_new_id p22a)"
  mkdir -p "$(soviez_migration_p22_archive_op_dir "$op_id")"
  SOVIEZ_OUT="$(soviez_migration_p22_archive_plan_path "$op_id")" \
  SOVIEZ_OP="$op_id" SOVIEZ_SID="$source_id" SOVIEZ_CID="$cutover_id" SOVIEZ_AID="$auth_id" \
  SOVIEZ_ROOT="${SOVIEZ_MIG_P22_SOURCE_ROOT:-}" SOVIEZ_NOW="$(soviez_migration_p22_now_iso)" python3 - <<'PY'
import json, os
body={
  "schema":"soviez.migration_source_archive_plan.v1",
  "operation_id": os.environ["SOVIEZ_OP"],
  "source_id": os.environ["SOVIEZ_SID"],
  "cutover_id": os.environ["SOVIEZ_CID"],
  "authorization_id": os.environ["SOVIEZ_AID"],
  "source_root": os.environ.get("SOVIEZ_ROOT",""),
  "purge_authorized": False,
  "deletion_authorized": False,
  "created_at": os.environ["SOVIEZ_NOW"],
}
open(os.environ["SOVIEZ_OUT"],"w").write(json.dumps(body, separators=(",", ":")))
PY
  soviez_migration_p22_archive_state_write "$op_id" "planned" "$source_id" "$cutover_id" "$auth_id" >/dev/null
  cat "$(soviez_migration_p22_archive_plan_path "$op_id")"
}

soviez_migration_source_archive_start() {
  local source_id="${1:-}" reuse_op="${2:-}"
  export SOVIEZ_MIG_P22_CANONICAL=1
  # Soften Phase 21 archive forbid for canonical Phase 22.
  export SOVIEZ_MIG_SOURCE_ARCHIVE=1
  soviez_migration_p22_paths_init
  soviez_migration_assert_phase22_allowed "$SOVIEZ_MIG_OP_SOURCE_ARCHIVE"
  if declare -F soviez_migration_p22_assert_cert_gates >/dev/null 2>&1; then
    soviez_migration_p22_assert_cert_gates
  fi

  local st auth_id cutover_id op_id planf
  cutover_id="${SOVIEZ_MIG_P22_CUTOVER_ID:-$source_id}"
  st="$(soviez_migration_p22_archive_resolve_source "$source_id")"
  auth_id="$(soviez_json_get "$st" authorization_id)"

  if [[ -n "$reuse_op" ]]; then
    op_id="$reuse_op"
  else
    # Prefer existing plan for this source if present via env.
    op_id="${SOVIEZ_MIG_P22_ARCHIVE_OP_ID:-}"
    if [[ -z "$op_id" ]]; then
      local plan
      plan="$(soviez_migration_source_archive_plan "$source_id")"
      op_id="$(soviez_json_get "$plan" operation_id)"
    fi
  fi

  planf="$(soviez_migration_p22_archive_plan_path "$op_id")"
  [[ -f "$planf" ]] || soviez_migration_die MIGRATION_SOURCE_ARCHIVE_PLAN_REQUIRED "archive plan required"

  # Holds
  if [[ "${SOVIEZ_MIG_P22_LEGAL_HOLD:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_LEGAL_HOLD_ACTIVE "legal hold active"
  fi
  if [[ "${SOVIEZ_MIG_P22_RETENTION_HOLD:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_RETENTION_HOLD_ACTIVE "retention hold active"
  fi

  soviez_migration_p22_archive_state_write "$op_id" "creating" "$source_id" "$cutover_id" "$auth_id" >/dev/null

  local src_root
  src_root="${SOVIEZ_MIG_P22_SOURCE_ROOT:-}"
  [[ -n "$src_root" ]] || soviez_migration_die MIGRATION_SOURCE_ARCHIVE_CREATE_FAILED "SOVIEZ_MIG_P22_SOURCE_ROOT required"

  soviez_migration_p22_archive_inventory "$op_id" "$src_root" >/dev/null
  soviez_migration_p22_archive_database "$op_id" >/dev/null
  soviez_migration_p22_archive_filestore "$op_id" "${SOVIEZ_MIG_P22_SOURCE_FILESTORE:-$src_root/filestore}" >/dev/null
  soviez_migration_p22_archive_addons "$op_id" >/dev/null
  soviez_migration_p22_archive_config "$op_id" >/dev/null
  soviez_migration_p22_archive_secret_inventory "$op_id" >/dev/null
  soviez_migration_p22_archive_certificates "$op_id" >/dev/null
  soviez_migration_p22_archive_dns "$op_id" "$cutover_id" >/dev/null
  soviez_migration_p22_archive_stages "$op_id" >/dev/null
  soviez_migration_p22_archive_infrastructure "$op_id" >/dev/null
  soviez_migration_p22_archive_encrypt "$op_id" >/dev/null
  # Optional remote store (S3/SFTP) — interrupt/lost-ack recoverable; never deletes source.
  if declare -F soviez_migration_p22_archive_store_remote >/dev/null 2>&1; then
    soviez_migration_p22_archive_store_remote "$op_id" >/dev/null
  fi
  soviez_migration_p22_archive_write_manifest "$op_id" "$cutover_id" "$source_id" >/dev/null
  soviez_migration_p22_archive_sign_manifest "$op_id" >/dev/null
  soviez_migration_p22_archive_verify "$op_id" >/dev/null
  soviez_migration_p22_archive_restore_test "$op_id" >/dev/null
  soviez_migration_p22_archive_full_erp_restore_test "$op_id" >/dev/null

  local report
  report="$(soviez_migration_p22_archive_op_dir "$op_id")/report.json"
  SOVIEZ_OUT="$report" SOVIEZ_OP="$op_id" SOVIEZ_SID="$source_id" SOVIEZ_CID="$cutover_id" \
  SOVIEZ_NOW="$(soviez_migration_p22_now_iso)" python3 - <<'PY'
import json, os
body={
  "schema":"soviez.migration_source_archive.v1",
  "operation_id": os.environ["SOVIEZ_OP"],
  "source_id": os.environ["SOVIEZ_SID"],
  "cutover_id": os.environ["SOVIEZ_CID"],
  "status": "verified",
  "purge_authorized": False,
  "deletion_performed": False,
  "created_at": os.environ["SOVIEZ_NOW"],
  "signer": "soviez-p22",
}
open(os.environ["SOVIEZ_OUT"],"w").write(json.dumps(body, separators=(",", ":")))
PY
  soviez_migration_sign_object_file "$report"
  soviez_migration_p22_archive_state_write "$op_id" "verified" "$source_id" "$cutover_id" "$auth_id" '{"status":"verified"}' >/dev/null
  # Index
  mkdir -p "$SOVIEZ_MIG_SOURCE_ARCHIVE_DIR/by_source"
  printf '%s\n' "$op_id" > "$SOVIEZ_MIG_SOURCE_ARCHIVE_DIR/by_source/${source_id}.id"
  cat "$report"
}

# Full Phase 22 happy-path orchestrator for fixtures/tests.
# Requires SOVIEZ_MIG_P22_FIXTURE=1 (+ cert clock flags for short stabilization).
soviez_migration_phase22_run() {
  local cutover_id="${1:-}" source_id="${2:-}"
  [[ -n "$cutover_id" ]] || soviez_migration_die MIGRATION_NOT_FOUND "cutover-id required"
  source_id="${source_id:-$cutover_id}"
  export SOVIEZ_MIG_P22_CANONICAL=1
  export SOVIEZ_MIG_P22_CUTOVER_ID="$cutover_id"
  export SOVIEZ_CLI_CONFIRM_PHRASE="CLOSE ROLLBACK WINDOW ${cutover_id}"
  soviez_migration_p22_paths_init

  soviez_migration_stabilization_status "$cutover_id" >/dev/null
  # Ensure window appears expired for closure.
  export SOVIEZ_MIG_P22_FORCE_WINDOW_EXPIRED=1
  soviez_migration_rollback_window_close "$cutover_id" >/dev/null
  local archive
  archive="$(soviez_migration_source_archive_start "$source_id")"
  local op_id
  op_id="$(soviez_json_get "$archive" operation_id)"
  soviez_migration_source_license_finalize "$op_id" >/dev/null
  soviez_migration_source_runtime_suspend "$op_id" >/dev/null
  local retirement p23
  retirement="$(soviez_migration_source_retirement_status "$source_id")"
  p23="$(soviez_migration_phase23_readiness "$op_id")"
  SOVIEZ_AID="$op_id" SOVIEZ_CID="$cutover_id" SOVIEZ_SID="$source_id" \
  SOVIEZ_RET="$retirement" SOVIEZ_P23="$p23" python3 - <<'PY'
import json, os
print(json.dumps({
  "status": "phase22_complete",
  "cutover_id": os.environ["SOVIEZ_CID"],
  "source_id": os.environ["SOVIEZ_SID"],
  "archive_operation_id": os.environ["SOVIEZ_AID"],
  "retirement": json.loads(os.environ["SOVIEZ_RET"]),
  "phase23_readiness": json.loads(os.environ["SOVIEZ_P23"]),
  "purges_source": False,
}, separators=(",", ":")))
PY
}

# --- end migration/source_archive/engine.sh ---

# --- begin migration/source_finalization/codes.sh ---
# shellcheck shell=bash

SOVIEZ_MIG_OP_SOURCE_CREDENTIALS_STATUS=migration_source_credentials_status

# --- end migration/source_finalization/codes.sh ---

# --- begin migration/source_finalization/model.sh ---
# shellcheck shell=bash

soviez_migration_p22_finalization_state_path() {
  printf '%s/%s/state.json\n' "$SOVIEZ_MIG_SOURCE_FINALIZATION_DIR" "$1"
}

# --- end migration/source_finalization/model.sh ---

# --- begin migration/source_finalization/license.sh ---
# shellcheck shell=bash

soviez_migration_p22_license_finalize() {
  local archive_op_id="$1"
  local out_dir statef ackf idem_key
  out_dir="$(soviez_migration_p22_finalization_dir "$archive_op_id")"
  mkdir -p "$out_dir"
  statef="$out_dir/license.json"
  ackf="$out_dir/license.ack"
  idem_key="p22-license-finalize:${archive_op_id}"

  # Enforce one license, one slot, token=1 (consumed), traffic_owner=destination.
  local st cutover_id auth_id to
  st="$(soviez_migration_source_archive_status "$archive_op_id")"
  [[ "$(soviez_json_get "$st" current_state)" == "verified" ]] || \
    soviez_migration_die MIGRATION_SOURCE_LICENSE_FINALIZE_FAILED "archive must be verified"
  cutover_id="$(soviez_json_get "$st" cutover_id)"
  auth_id="$(soviez_json_get "$st" authorization_id)"
  to="$(soviez_json_get "$(soviez_migration_traffic_owner_get "$auth_id")" traffic_owner)"
  [[ "$to" == "destination" ]] || \
    soviez_migration_die MIGRATION_SOURCE_LICENSE_FINALIZE_FAILED "traffic_owner must remain destination"

  if [[ "${SOVIEZ_MIG_P22_INJECT_SECOND_LICENSE:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_SOURCE_LICENSE_FINALIZE_FAILED "second license/slot forbidden"
  fi
  if [[ "${SOVIEZ_MIG_P22_INJECT_TOKEN_RESET:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_SOURCE_LICENSE_FINALIZE_FAILED "token reset forbidden"
  fi

  # Idempotent: commit already present + ack → return same receipt (no duplicate transition).
  if [[ -f "$statef" && -f "$ackf" ]]; then
    local prev_state
    prev_state="$(soviez_json_get "$(cat "$statef")" source_license_state 2>/dev/null || true)"
    if [[ "$prev_state" == "migrated_source_archived" ]]; then
      cat "$statef"
      return 0
    fi
  fi

  # Commit-status-unknown: commit file exists, response never returned → resolve without re-commit.
  if [[ -f "$statef" ]] && [[ ! -f "$ackf" ]]; then
    if [[ "${SOVIEZ_MIG_P22_LICENSE_RESPONSE_LOSS:-0}" == "1" ]]; then
      unset SOVIEZ_MIG_P22_LICENSE_RESPONSE_LOSS
      export SOVIEZ_MIG_P22_LICENSE_RESPONSE_LOSS=0
      soviez_migration_die MIGRATION_LICENSE_COMMIT_STATUS_UNKNOWN \
        "license finalize commit present; response lost (inject once)"
    fi
    printf 'acked\n' > "$ackf"
    SOVIEZ_R="$statef" python3 - <<'PY'
import json, os
p=os.environ["SOVIEZ_R"]
d=json.load(open(p))
d["ack"]="idempotent_retry"
d["duplicate_finalization"]=False
d["commit_status"]="resolved"
open(p,"w").write(json.dumps(d, separators=(",", ":")))
print(open(p).read())
PY
    return 0
  fi

  # First commit write (before local ack — response-loss window).
  SOVIEZ_OUT="$statef" SOVIEZ_OP="$archive_op_id" SOVIEZ_AID="$auth_id" \
  SOVIEZ_IDEM="$idem_key" SOVIEZ_NOW="$(soviez_migration_p22_now_iso)" python3 - <<'PY'
import json, os
body={
  "schema":"soviez.migration_source_license_finalize.v1",
  "archive_operation_id": os.environ["SOVIEZ_OP"],
  "authorization_id": os.environ["SOVIEZ_AID"],
  "idempotency_key": os.environ["SOVIEZ_IDEM"],
  "source_license_state": "migrated_source_archived",
  "destination_sole_production": True,
  "license_count": 1,
  "slot_count": 1,
  "token_consumed": 1,
  "token_reset": False,
  "traffic_owner": "destination",
  "commit_status": "committed",
  "duplicate_finalization": False,
  "finalized_at": os.environ["SOVIEZ_NOW"],
}
open(os.environ["SOVIEZ_OUT"],"w").write(json.dumps(body, separators=(",", ":")))
PY

  if [[ "${SOVIEZ_MIG_P22_LICENSE_RESPONSE_LOSS:-0}" == "1" ]]; then
    unset SOVIEZ_MIG_P22_LICENSE_RESPONSE_LOSS
    export SOVIEZ_MIG_P22_LICENSE_RESPONSE_LOSS=0
    soviez_migration_die MIGRATION_LICENSE_FINALIZE_RESPONSE_LOSS \
      "injected response loss after license finalize commit"
  fi

  printf 'acked\n' > "$ackf"
  cat "$statef"
}

# --- end migration/source_finalization/license.sh ---

# --- begin migration/source_finalization/license_guard.sh ---
# shellcheck shell=bash

soviez_migration_p22_license_guard_archived() {
  local archive_op_id="$1"
  local out
  out="$(soviez_migration_p22_finalization_dir "$archive_op_id")/license_guard_archived.json"
  mkdir -p "$(dirname "$out")"
  printf '{"mode":"archived","deny_production_login":true,"production_login_flags_denied":true}\n' > "$out"
  cat "$out"
}

# Guard check used by accidental-start denial.
soviez_migration_p22_assert_not_archived_login() {
  local source_id="${1:-}"
  local f
  f="$SOVIEZ_MIG_SOURCE_FINALIZATION_DIR/${source_id}/license_guard_archived.json"
  # Also scan by archive op.
  if [[ -f "$f" ]] && [[ "$(soviez_json_get "$(cat "$f")" deny_production_login)" == "True" || "$(soviez_json_get "$(cat "$f")" deny_production_login)" == "true" ]]; then
    if [[ "${SOVIEZ_MIG_P22_ALLOW_ARCHIVED_LOGIN:-0}" != "1" ]]; then
      soviez_migration_die MIGRATION_SOURCE_RUNTIME_SUSPEND_FAILED "archived source denies Production login"
    fi
  fi
}

# --- end migration/source_finalization/license_guard.sh ---

# --- begin migration/source_finalization/integrations.sh ---
# shellcheck shell=bash

soviez_migration_p22_disable_integrations() {
  local archive_op_id="$1"
  local out
  out="$(soviez_migration_p22_finalization_dir "$archive_op_id")/integrations.json"
  mkdir -p "$(dirname "$out")"
  if [[ "${SOVIEZ_MIG_P22_INJECT_INTEGRATIONS_ACTIVE:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_SOURCE_INTEGRATIONS_STILL_ACTIVE "integrations still active"
  fi
  printf '{"integrations_disabled":true,"webhooks":false,"payments":false,"mail":false}\n' > "$out"
  cat "$out"
}

# --- end migration/source_finalization/integrations.sh ---

# --- begin migration/source_finalization/credentials.sh ---
# shellcheck shell=bash

soviez_migration_p22_credentials_disposition() {
  local archive_op_id="$1"
  local out
  out="$(soviez_migration_p22_finalization_dir "$archive_op_id")/credentials.json"
  mkdir -p "$(dirname "$out")"
  if [[ "${SOVIEZ_MIG_P22_CREDENTIALS_INCOMPLETE:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_SOURCE_CREDENTIAL_DISPOSITION_INCOMPLETE "credential disposition incomplete"
  fi
  # Record disposition — never silent destroy of all credentials as purge.
  printf '{"disposition_recorded":true,"destroyed":false,"rotated":false,"retained_inventory":true}\n' > "$out"
  cat "$out"
}

soviez_migration_source_credentials_status() {
  local archive_op_id="${1:-}"
  SOVIEZ_MIG_P22_MUTATING=0 soviez_migration_assert_phase22_allowed "$SOVIEZ_MIG_OP_SOURCE_LICENSE_FINALIZE"
  soviez_migration_p22_paths_init
  local f
  f="$(soviez_migration_p22_finalization_dir "$archive_op_id")/credentials.json"
  [[ -f "$f" ]] || printf '{"disposition_recorded":false}\n'
  [[ -f "$f" ]] && cat "$f"
}

# --- end migration/source_finalization/credentials.sh ---

# --- begin migration/source_finalization/routing.sh ---
# shellcheck shell=bash

soviez_migration_p22_disable_routing() {
  local archive_op_id="$1"
  local out
  out="$(soviez_migration_p22_finalization_dir "$archive_op_id")/routing.json"
  mkdir -p "$(dirname "$out")"
  if [[ "${SOVIEZ_MIG_P22_INJECT_PUBLIC_ROUTE:-0}" == "1" ]]; then
    soviez_migration_die MIGRATION_SOURCE_PUBLIC_ROUTE_STILL_ACTIVE "source public route still active"
  fi
  printf '{"public_route_disabled":true,"destination_binding_unchanged":true}\n' > "$out"
  cat "$out"
}

# --- end migration/source_finalization/routing.sh ---

# --- begin migration/source_finalization/runtime.sh ---
# shellcheck shell=bash
# Option B: stop exact ERP marker/service/container only; preserve host/volumes/backups.

soviez_migration_p22_runtime_suspend() {
  local archive_op_id="$1"
  local source_id marker statef stop_committed
  source_id="$(soviez_json_get "$(soviez_migration_source_archive_status "$archive_op_id")" source_id)"
  marker="${SOVIEZ_MIG_P22_ERP_MARKER:-soviez-erp-source}"
  statef="$(soviez_migration_p22_suspend_state_path "$source_id")"
  mkdir -p "$(dirname "$statef")"
  stop_committed="$(dirname "$statef")/stop_committed"

  if [[ -f "$statef" ]] && [[ "$(soviez_json_get "$(cat "$statef")" suspended)" == "True" || "$(soviez_json_get "$(cat "$statef")" suspended)" == "true" ]]; then
    cat "$statef"
    return 0
  fi

  # Response-loss recovery: stop already committed, ack missing → finish without re-stop.
  if [[ -f "$stop_committed" ]] && [[ ! -f "$statef" || "$(soviez_json_get "$(cat "$statef" 2>/dev/null || echo '{}')" suspended 2>/dev/null || true)" != "true" ]]; then
    if [[ "${SOVIEZ_MIG_P22_RUNTIME_RESPONSE_LOSS:-0}" == "1" ]]; then
      unset SOVIEZ_MIG_P22_RUNTIME_RESPONSE_LOSS
      export SOVIEZ_MIG_P22_RUNTIME_RESPONSE_LOSS=0
      soviez_migration_die MIGRATION_RUNTIME_SUSPEND_RESPONSE_LOSS \
        "runtime stop committed; response lost (inject once)"
    fi
    SOVIEZ_OUT="$statef" SOVIEZ_SID="$source_id" SOVIEZ_OP="$archive_op_id" SOVIEZ_MK="$marker" \
    SOVIEZ_NOW="$(soviez_migration_p22_now_iso)" python3 - <<'PY'
import json, os
body={
  "schema":"soviez.migration_source_runtime_suspend.v1",
  "source_id": os.environ["SOVIEZ_SID"],
  "archive_operation_id": os.environ["SOVIEZ_OP"],
  "suspended": True,
  "marker": os.environ["SOVIEZ_MK"],
  "host_preserved": True,
  "volumes_preserved": True,
  "backups_preserved": True,
  "postgres_stopped": False,
  "survives_reboot": True,
  "accidental_start_denied": True,
  "duplicate_suspension": False,
  "ack": "idempotent_retry",
  "suspended_at": os.environ["SOVIEZ_NOW"],
}
open(os.environ["SOVIEZ_OUT"],"w").write(json.dumps(body, separators=(",", ":")))
print(open(os.environ["SOVIEZ_OUT"]).read())
PY
    return 0
  fi

  # Stop exact container/service if present (fixture: touch stop marker).
  if [[ -n "${SOVIEZ_MIG_P22_ERP_CONTAINER:-}" ]] && command -v docker >/dev/null 2>&1; then
    docker stop "${SOVIEZ_MIG_P22_ERP_CONTAINER}" >/dev/null 2>&1 || \
      soviez_migration_die MIGRATION_SOURCE_RUNTIME_SUSPEND_FAILED "failed to stop ERP container"
  fi
  if [[ -n "${SOVIEZ_MIG_P22_ERP_SERVICE:-}" ]] && command -v systemctl >/dev/null 2>&1; then
    systemctl stop "${SOVIEZ_MIG_P22_ERP_SERVICE}" >/dev/null 2>&1 || true
  fi
  # Fixture stop file under mig root (survives reboot simulation).
  mkdir -p "$SOVIEZ_MIG_ROOT/runtime_suspend/$source_id"
  printf 'stopped\n' > "$SOVIEZ_MIG_ROOT/runtime_suspend/$source_id/erp.stop"
  printf '%s\n' "$marker" > "$SOVIEZ_MIG_ROOT/runtime_suspend/$source_id/marker"
  # Exact ERP runtime marker (Option B) — never delete host/data.
  if [[ -n "${SOVIEZ_MIG_P22_ERP_RUNTIME_MARKER:-}" ]]; then
    mkdir -p "$(dirname "$SOVIEZ_MIG_P22_ERP_RUNTIME_MARKER")"
    printf 'SUSPENDED\n' > "$SOVIEZ_MIG_P22_ERP_RUNTIME_MARKER"
  fi
  printf 'stop_committed\n' > "$stop_committed"

  if [[ "${SOVIEZ_MIG_P22_RUNTIME_RESPONSE_LOSS:-0}" == "1" ]]; then
    unset SOVIEZ_MIG_P22_RUNTIME_RESPONSE_LOSS
    export SOVIEZ_MIG_P22_RUNTIME_RESPONSE_LOSS=0
    soviez_migration_die MIGRATION_RUNTIME_SUSPEND_RESPONSE_LOSS \
      "injected response loss after ERP stop commit"
  fi

  SOVIEZ_OUT="$statef" SOVIEZ_SID="$source_id" SOVIEZ_OP="$archive_op_id" SOVIEZ_MK="$marker" \
  SOVIEZ_NOW="$(soviez_migration_p22_now_iso)" python3 - <<'PY'
import json, os
body={
  "schema":"soviez.migration_source_runtime_suspend.v1",
  "source_id": os.environ["SOVIEZ_SID"],
  "archive_operation_id": os.environ["SOVIEZ_OP"],
  "suspended": True,
  "marker": os.environ["SOVIEZ_MK"],
  "host_preserved": True,
  "volumes_preserved": True,
  "backups_preserved": True,
  "postgres_stopped": False,
  "survives_reboot": True,
  "accidental_start_denied": True,
  "duplicate_suspension": False,
  "ack": "ok",
  "suspended_at": os.environ["SOVIEZ_NOW"],
}
open(os.environ["SOVIEZ_OUT"],"w").write(json.dumps(body, separators=(",", ":")))
print(open(os.environ["SOVIEZ_OUT"]).read())
PY
}

soviez_migration_p22_assert_not_accidentally_started() {
  local source_id="$1"
  local statef
  statef="$(soviez_migration_p22_suspend_state_path "$source_id")"
  [[ -f "$statef" ]] || return 0
  if [[ "$(soviez_json_get "$(cat "$statef")" suspended)" == "True" || "$(soviez_json_get "$(cat "$statef")" suspended)" == "true" ]]; then
    if [[ "${SOVIEZ_MIG_P22_RECOVERY_START:-0}" != "1" ]]; then
      soviez_migration_die MIGRATION_SOURCE_RUNTIME_ALREADY_SUSPENDED \
        "suspended source start denied without recovery command"
    fi
  fi
}

# --- end migration/source_finalization/runtime.sh ---

# --- begin migration/source_finalization/postgres.sh ---
# shellcheck shell=bash

soviez_migration_p22_postgres_optional_stop() {
  local archive_op_id="$1"
  local out
  out="$(soviez_migration_p22_finalization_dir "$archive_op_id")/postgres.json"
  mkdir -p "$(dirname "$out")"
  if [[ "${SOVIEZ_MIG_P22_STOP_POSTGRES:-0}" != "1" ]]; then
    printf '{"postgres_stopped":false,"policy_gate":"SOVIEZ_MIG_P22_STOP_POSTGRES!=1"}\n' > "$out"
    cat "$out"
    return 0
  fi
  # Policy-gated optional stop — never drop data/volumes.
  if [[ -n "${SOVIEZ_MIG_P22_PG_CONTAINER:-}" ]] && command -v docker >/dev/null 2>&1; then
    docker stop "${SOVIEZ_MIG_P22_PG_CONTAINER}" >/dev/null 2>&1 || true
  fi
  printf '{"postgres_stopped":true,"data_preserved":true,"volumes_preserved":true}\n' > "$out"
  # Update suspend state if present.
  local source_id statef
  source_id="$(soviez_json_get "$(soviez_migration_source_archive_status "$archive_op_id")" source_id)"
  statef="$(soviez_migration_p22_suspend_state_path "$source_id")"
  if [[ -f "$statef" ]]; then
    SOVIEZ_F="$statef" python3 - <<'PY'
import json, os
d=json.load(open(os.environ["SOVIEZ_F"]))
d["postgres_stopped"]=True
open(os.environ["SOVIEZ_F"],"w").write(json.dumps(d, separators=(",", ":")))
PY
  fi
  cat "$out"
}

# --- end migration/source_finalization/postgres.sh ---

# --- begin migration/source_finalization/quarantine.sh ---
# shellcheck shell=bash

soviez_migration_p22_quarantine() {
  local archive_op_id="$1"
  local out
  out="$(soviez_migration_p22_finalization_dir "$archive_op_id")/quarantine.json"
  mkdir -p "$(dirname "$out")"
  printf '{"quarantined":true,"public_access":false}\n' > "$out"
  cat "$out"
}

# --- end migration/source_finalization/quarantine.sh ---

# --- begin migration/source_finalization/verify.sh ---
# shellcheck shell=bash

soviez_migration_p22_finalization_verify() {
  local archive_op_id="$1"
  local d
  d="$(soviez_migration_p22_finalization_dir "$archive_op_id")"
  [[ -f "$d/license.json" ]] || soviez_migration_die MIGRATION_SOURCE_LICENSE_FINALIZE_FAILED "license missing"
  [[ -f "$d/license_guard_archived.json" ]] || soviez_migration_die MIGRATION_SOURCE_LICENSE_FINALIZE_FAILED "LG missing"
  [[ -f "$d/integrations.json" ]] || soviez_migration_die MIGRATION_SOURCE_INTEGRATIONS_STILL_ACTIVE "integrations missing"
  [[ -f "$d/routing.json" ]] || soviez_migration_die MIGRATION_SOURCE_PUBLIC_ROUTE_STILL_ACTIVE "routing missing"
  [[ -f "$d/credentials.json" ]] || soviez_migration_die MIGRATION_SOURCE_CREDENTIAL_DISPOSITION_INCOMPLETE "credentials missing"
  printf '{"finalization_verified":true}\n'
}

# --- end migration/source_finalization/verify.sh ---

# --- begin migration/source_finalization/recover.sh ---
# shellcheck shell=bash

soviez_migration_p22_finalization_recover() {
  local archive_op_id="$1"
  soviez_migration_source_license_finalize "$archive_op_id"
}

# --- end migration/source_finalization/recover.sh ---

# --- begin migration/source_finalization/engine.sh ---
# shellcheck shell=bash

soviez_migration_source_license_finalize() {
  local archive_op_id="${1:-}"
  export SOVIEZ_MIG_P22_CANONICAL=1
  soviez_migration_assert_phase22_allowed "$SOVIEZ_MIG_OP_SOURCE_LICENSE_FINALIZE"
  soviez_migration_p22_paths_init
  soviez_migration_p22_license_finalize "$archive_op_id" >/dev/null
  soviez_migration_p22_license_guard_archived "$archive_op_id" >/dev/null
  soviez_migration_p22_disable_integrations "$archive_op_id" >/dev/null
  soviez_migration_p22_credentials_disposition "$archive_op_id" >/dev/null
  soviez_migration_p22_disable_routing "$archive_op_id" >/dev/null
  soviez_migration_p22_quarantine "$archive_op_id" >/dev/null
  soviez_migration_p22_finalization_verify "$archive_op_id" >/dev/null
  local out
  out="$(soviez_migration_p22_finalization_dir "$archive_op_id")/state.json"
  SOVIEZ_OUT="$out" SOVIEZ_OP="$archive_op_id" SOVIEZ_NOW="$(soviez_migration_p22_now_iso)" python3 - <<'PY'
import json, os
body={
  "archive_operation_id": os.environ["SOVIEZ_OP"],
  "current_state": "license_finalized",
  "source_license_state": "migrated_source_archived",
  "finalized_at": os.environ["SOVIEZ_NOW"],
}
open(os.environ["SOVIEZ_OUT"],"w").write(json.dumps(body, separators=(",", ":")))
print(open(os.environ["SOVIEZ_OUT"]).read())
PY
}

soviez_migration_source_runtime_suspend() {
  local archive_op_id="${1:-}"
  export SOVIEZ_MIG_P22_CANONICAL=1
  soviez_migration_assert_phase22_allowed "$SOVIEZ_MIG_OP_SOURCE_RUNTIME_SUSPEND"
  soviez_migration_p22_paths_init
  # Prerequisites
  local fin
  fin="$(soviez_migration_p22_finalization_dir "$archive_op_id")/state.json"
  [[ -f "$fin" ]] || soviez_migration_die MIGRATION_SOURCE_LICENSE_FINALIZE_FAILED "license finalize required first"
  [[ -f "$(soviez_migration_p22_finalization_dir "$archive_op_id")/routing.json" ]] || \
    soviez_migration_die MIGRATION_SOURCE_PUBLIC_ROUTE_STILL_ACTIVE "routing disable required"
  [[ -f "$(soviez_migration_p22_finalization_dir "$archive_op_id")/integrations.json" ]] || \
    soviez_migration_die MIGRATION_SOURCE_INTEGRATIONS_STILL_ACTIVE "integrations disable required"
  soviez_migration_p22_runtime_suspend "$archive_op_id"
  soviez_migration_p22_postgres_optional_stop "$archive_op_id" >/dev/null
}

# --- end migration/source_finalization/engine.sh ---

# --- begin migration/retirement/model.sh ---
# shellcheck shell=bash

soviez_migration_p22_retirement_inventory() {
  local source_id="$1"
  local out_dir out
  out_dir="$(soviez_migration_p22_retirement_dir "$source_id")"
  mkdir -p "$out_dir"
  out="$out_dir/inventory.json"
  local unknown=0
  [[ "${SOVIEZ_MIG_P22_UNKNOWN_RESOURCES:-0}" == "1" ]] && unknown=1
  SOVIEZ_OUT="$out" SOVIEZ_SID="$source_id" SOVIEZ_UNK="$unknown" python3 - <<'PY'
import json, os
unk=os.environ["SOVIEZ_UNK"]=="1"
resources=[
  {"kind":"host","id":"source-host","known":True,"retained":True},
  {"kind":"volume","id":"source-data","known":True,"retained":True},
  {"kind":"backup","id":"pinned","known":True,"retained":True},
]
if unk:
  resources.append({"kind":"unknown","id":"mystery","known":False,"retained":True})
body={
  "source_id": os.environ["SOVIEZ_SID"],
  "resources": resources,
  "unknown_count": 1 if unk else 0,
  "purge_authorized": False,
}
open(os.environ["SOVIEZ_OUT"],"w").write(json.dumps(body, separators=(",", ":")))
print(open(os.environ["SOVIEZ_OUT"]).read())
PY
}

# --- end migration/retirement/model.sh ---

# --- begin migration/retirement/inventory.sh ---
# shellcheck shell=bash

soviez_migration_p22_retirement_inventory_check() {
  local source_id="$1"
  local inv
  inv="$(soviez_migration_p22_retirement_inventory "$source_id")"
  local unk
  unk="$(soviez_json_get "$inv" unknown_count)"
  [[ "${unk:-0}" -eq 0 ]] || soviez_migration_die MIGRATION_RETIREMENT_NOT_READY "unknown resources BLOCK"
  printf '%s\n' "$inv"
}

# --- end migration/retirement/inventory.sh ---

# --- begin migration/retirement/manual.sh ---
# shellcheck shell=bash

soviez_migration_p22_retirement_manual() {
  printf '{"manual_steps":["confirm archive verified","confirm license finalized","confirm runtime suspended"],"automated_purge":false}\n'
}

# --- end migration/retirement/manual.sh ---

# --- begin migration/retirement/provider.sh ---
# shellcheck shell=bash

soviez_migration_p22_retirement_provider() {
  # Provider hooks are advisory — never terminate host.
  printf '{"provider":"none","host_termination_authorized":false}\n'
}

# --- end migration/retirement/provider.sh ---

# --- begin migration/retirement/suspend.sh ---
# shellcheck shell=bash

soviez_migration_p22_retirement_suspend_check() {
  local source_id="$1"
  local statef
  statef="$(soviez_migration_p22_suspend_state_path "$source_id")"
  [[ -f "$statef" ]] || soviez_migration_die MIGRATION_RETIREMENT_NOT_READY "runtime not suspended"
  [[ "$(soviez_json_get "$(cat "$statef")" suspended)" == "True" || "$(soviez_json_get "$(cat "$statef")" suspended)" == "true" ]] || \
    soviez_migration_die MIGRATION_RETIREMENT_NOT_READY "runtime not suspended"
  cat "$statef"
}

# --- end migration/retirement/suspend.sh ---

# --- begin migration/retirement/readiness.sh ---
# shellcheck shell=bash

soviez_migration_p22_retirement_readiness() {
  local source_id="$1"
  local blockers=()
  set +e
  soviez_migration_p22_retirement_inventory_check "$source_id" >/dev/null 2>&1 || blockers+=("unknown_resources")
  soviez_migration_p22_retirement_suspend_check "$source_id" >/dev/null 2>&1 || blockers+=("not_suspended")
  set -e
  local status=PASS
  [[ ${#blockers[@]} -eq 0 ]] || status=BLOCKED
  SOVIEZ_ST="$status" SOVIEZ_BL="$(printf '%s,' ${blockers[@]+"${blockers[@]}"})" SOVIEZ_SID="$source_id" python3 - <<'PY'
import json, os
bl=[x for x in os.environ.get("SOVIEZ_BL","").split(",") if x]
print(json.dumps({
  "source_id": os.environ["SOVIEZ_SID"],
  "readiness_status": os.environ["SOVIEZ_ST"],
  "blockers": bl,
  "purge_authorized": False,
}, separators=(",", ":")))
PY
}

# --- end migration/retirement/readiness.sh ---

# --- begin migration/retirement/report.sh ---
# shellcheck shell=bash

soviez_migration_p22_retirement_report() {
  local source_id="$1"
  local out
  out="$(soviez_migration_p22_retirement_dir "$source_id")/report.json"
  mkdir -p "$(dirname "$out")"
  local ready inv
  ready="$(soviez_migration_p22_retirement_readiness "$source_id")"
  inv="$(soviez_migration_p22_retirement_inventory "$source_id")"
  SOVIEZ_OUT="$out" SOVIEZ_READY="$ready" SOVIEZ_INV="$inv" SOVIEZ_SID="$source_id" \
  SOVIEZ_NOW="$(soviez_migration_p22_now_iso)" python3 - <<'PY'
import json, os
body={
  "schema":"soviez.migration_retirement.v1",
  "source_id": os.environ["SOVIEZ_SID"],
  "readiness": json.loads(os.environ["SOVIEZ_READY"]),
  "inventory": json.loads(os.environ["SOVIEZ_INV"]),
  "manual": {"automated_purge": False},
  "provider": {"host_termination_authorized": False},
  "created_at": os.environ["SOVIEZ_NOW"],
}
open(os.environ["SOVIEZ_OUT"],"w").write(json.dumps(body, separators=(",", ":")))
print(open(os.environ["SOVIEZ_OUT"]).read())
PY
}

# --- end migration/retirement/report.sh ---

# --- begin migration/retirement/engine.sh ---
# shellcheck shell=bash

soviez_migration_source_retirement_status() {
  local source_id="${1:-}"
  SOVIEZ_MIG_P22_MUTATING=0 soviez_migration_assert_phase22_allowed "$SOVIEZ_MIG_OP_RETIREMENT_STATUS"
  soviez_migration_p22_paths_init
  soviez_migration_p22_retirement_report "$source_id"
}

# --- end migration/retirement/engine.sh ---

# --- begin migration/phase23_readiness/model.sh ---
# shellcheck shell=bash
# Phase 23 readiness — REPORT ONLY. Never implements offline bundles or purge.

soviez_migration_p23_model_defaults() {
  printf '{"ttl_seconds":%s,"implements_phase23_product":false}\n' \
    "${SOVIEZ_MIG_P22_PHASE23_TTL_SECONDS}"
}

# --- end migration/phase23_readiness/model.sh ---

# --- begin migration/phase23_readiness/validate.sh ---
# shellcheck shell=bash

soviez_migration_phase23_readiness_validate() {
  local archive_op_id="$1"
  local blockers=() warnings=()
  local st cutover_id source_id auth_id

  st="$(soviez_migration_source_archive_status "$archive_op_id")"
  [[ "$(soviez_json_get "$st" current_state)" == "verified" ]] || blockers+=("archive_not_verified")
  cutover_id="$(soviez_json_get "$st" cutover_id)"
  source_id="$(soviez_json_get "$st" source_id)"
  auth_id="$(soviez_json_get "$st" authorization_id)"

  # Stabilization + window closed
  set +e
  soviez_migration_stabilization_latest_report "$cutover_id" >/dev/null 2>&1 || blockers+=("stabilization_missing")
  set -e
  local byc
  byc="$(soviez_migration_p22_closure_by_cutover_path "$cutover_id")"
  [[ -f "$byc" ]] || blockers+=("rollback_window_open")

  # License finalized
  [[ -f "$(soviez_migration_p22_finalization_dir "$archive_op_id")/state.json" ]] || blockers+=("license_not_finalized")

  # Runtime suspended
  local sus
  sus="$(soviez_migration_p22_suspend_state_path "$source_id")"
  [[ -f "$sus" ]] || blockers+=("runtime_not_suspended")

  # Inventory
  set +e
  soviez_migration_p22_retirement_inventory_check "$source_id" >/dev/null 2>&1 || blockers+=("inventory_incomplete")
  set -e

  # Optional warnings
  if [[ "${SOVIEZ_MIG_P22_STAGE_OPTIONAL_FAIL:-0}" == "1" ]]; then
    warnings+=("optional_stage_archive")
  fi
  if [[ "${SOVIEZ_MIG_P22_SKIP_FULL_ERP_RESTORE:-0}" == "1" ]]; then
    warnings+=("full_erp_restore_skipped")
  fi

  # Never allow purge flags to produce PASS
  if [[ "${SOVIEZ_MIG_SOURCE_PURGE:-0}" == "1" ]]; then
    blockers+=("purge_attempted")
  fi

  local status=PASS
  if [[ ${#blockers[@]} -gt 0 ]]; then status=BLOCKED
  elif [[ ${#warnings[@]} -gt 0 ]]; then status=WARNING
  fi
  SOVIEZ_ST="$status" SOVIEZ_BL="$(printf '%s,' ${blockers[@]+"${blockers[@]}"})" \
  SOVIEZ_WN="$(printf '%s,' ${warnings[@]+"${warnings[@]}"})" \
  SOVIEZ_OP="$archive_op_id" SOVIEZ_SID="$source_id" python3 - <<'PY'
import json, os
bl=[x for x in os.environ.get("SOVIEZ_BL","").split(",") if x]
wn=[x for x in os.environ.get("SOVIEZ_WN","").split(",") if x]
print(json.dumps({
  "archive_operation_id": os.environ["SOVIEZ_OP"],
  "source_id": os.environ["SOVIEZ_SID"],
  "readiness_status": os.environ["SOVIEZ_ST"],
  "blockers": bl,
  "warnings": wn,
  "implements_offline_bundles": False,
  "implements_purge": False,
}, separators=(",", ":")))
PY
}

# --- end migration/phase23_readiness/validate.sh ---

# --- begin migration/phase23_readiness/drift.sh ---
# shellcheck shell=bash

soviez_migration_phase23_readiness_drift() {
  local report_path="$1"
  # Invalidate when fingerprint env changes.
  local expected actual
  expected="$(soviez_json_get "$(cat "$report_path")" drift_fingerprint 2>/dev/null || true)"
  actual="${SOVIEZ_MIG_P22_DRIFT_FINGERPRINT:-stable}"
  if [[ -n "$expected" && "$expected" != "$actual" ]]; then
    soviez_migration_die MIGRATION_PHASE23_NOT_READY "phase23 readiness drift detected"
  fi
  return 0
}

# --- end migration/phase23_readiness/drift.sh ---

# --- begin migration/phase23_readiness/report.sh ---
# shellcheck shell=bash

soviez_migration_phase23_readiness_write_report() {
  local report_id="$1" validation_json="$2"
  local out_dir out
  out_dir="$(soviez_migration_p22_phase23_dir "$report_id")"
  mkdir -p "$out_dir"
  out="$out_dir/report.json"
  SOVIEZ_OUT="$out" SOVIEZ_RID="$report_id" SOVIEZ_VAL="$validation_json" \
  SOVIEZ_TTL="${SOVIEZ_MIG_P22_PHASE23_TTL_SECONDS}" \
  SOVIEZ_FP="${SOVIEZ_MIG_P22_DRIFT_FINGERPRINT:-stable}" \
  SOVIEZ_NOW="$(soviez_migration_p22_now_iso)" python3 - <<'PY'
import json, os, datetime
val=json.loads(os.environ["SOVIEZ_VAL"])
ttl=int(os.environ["SOVIEZ_TTL"])
exp=(datetime.datetime.utcnow()+datetime.timedelta(seconds=ttl)).strftime("%Y-%m-%dT%H:%M:%SZ")
body={
  "schema":"soviez.migration_phase23_readiness.v1",
  "report_id": os.environ["SOVIEZ_RID"],
  "readiness_status": val["readiness_status"],
  "archive_operation_id": val.get("archive_operation_id"),
  "source_id": val.get("source_id"),
  "blockers": val.get("blockers",[]),
  "warnings": val.get("warnings",[]),
  "implements_offline_bundles": False,
  "implements_purge": False,
  "drift_fingerprint": os.environ["SOVIEZ_FP"],
  "created_at": os.environ["SOVIEZ_NOW"],
  "expires_at": exp,
  "signer": "soviez-p22",
}
open(os.environ["SOVIEZ_OUT"],"w").write(json.dumps(body, separators=(",", ":")))
PY
  soviez_migration_sign_object_file "$out"
  cat "$out"
}

# --- end migration/phase23_readiness/report.sh ---

# --- begin migration/phase23_readiness/engine.sh ---
# shellcheck shell=bash

soviez_migration_phase23_readiness() {
  local archive_op_id="${1:-}"
  SOVIEZ_MIG_P22_MUTATING=0 soviez_migration_assert_phase22_allowed "$SOVIEZ_MIG_OP_PHASE23_READINESS"
  soviez_migration_p22_paths_init
  local val report_id
  val="$(soviez_migration_phase23_readiness_validate "$archive_op_id")"
  report_id="$(soviez_migration_new_id p23r)"
  soviez_migration_phase23_readiness_write_report "$report_id" "$val"
}

soviez_migration_phase23_readiness_show() {
  local report_id="${1:-}"
  [[ -n "$report_id" ]] || soviez_migration_die MIGRATION_PHASE23_NOT_READY "report-id required"
  SOVIEZ_MIG_P22_MUTATING=0 soviez_migration_assert_phase22_allowed "$SOVIEZ_MIG_OP_PHASE23_READINESS"
  soviez_migration_p22_paths_init
  local f
  f="$(soviez_migration_p22_phase23_dir "$report_id")/report.json"
  [[ -f "$f" ]] || soviez_migration_die MIGRATION_PHASE23_NOT_READY "report missing"
  if soviez_migration_is_expired "$(soviez_json_get "$(cat "$f")" expires_at)"; then
    soviez_migration_die MIGRATION_PHASE23_NOT_READY "phase23 readiness report expired"
  fi
  soviez_migration_phase23_readiness_drift "$f"
  cat "$f"
}

# --- end migration/phase23_readiness/engine.sh ---

# --- begin migration/rollback/engine.sh ---
# shellcheck shell=bash
# Phase 21 rollback tiers:
#   R0 — pre-commit abort (traffic_owner still source; no DNS change made yet)
#   R1 — post-commit, within window, zero meaningful writes/payment capture
#   R2 — post-commit, within window, dual-control required (T0+15m, OD-24)
#   R3 — MIGRATION_ROLLBACK_NOT_SAFE (window expired / meaningful writes /
#        payment side effect) — advisory/manual only, token never restored.

SOVIEZ_MIG_P21_DUAL_CONTROL_AFTER_SECONDS="${SOVIEZ_MIG_P21_DUAL_CONTROL_AFTER_SECONDS:-900}"

soviez_migration_rollback_eligibility() {
  local op_id="${1:-}" auth_id="${2:-}"
  [[ -n "$op_id" ]] || soviez_migration_die MIGRATION_NOT_FOUND "op-id required"
  soviez_migration_cutover_paths_init

  if [[ "${SOVIEZ_MIG_P21_MEANINGFUL_WRITES:-0}" == "1" ]]; then
    printf '{"eligible":false,"tier":"R3","code":"MIGRATION_ROLLBACK_NOT_SAFE","reason":"meaningful_writes"}\n'
    return 1
  fi
  if [[ "${SOVIEZ_MIG_P21_PAYMENT_CAPTURED:-0}" == "1" ]]; then
    printf '{"eligible":false,"tier":"R3","code":"MIGRATION_ROLLBACK_NOT_SAFE","reason":"payment_side_effect"}\n'
    return 1
  fi

  # Phase 22: if rollback window closed / automatic_rollback_allowed=false → not eligible.
  local closure_byc wf_closed
  if [[ -n "${SOVIEZ_MIG_ROOT:-}" ]]; then
    closure_byc="$SOVIEZ_MIG_ROOT/rollback_closure/by_cutover/${op_id}.json"
    if [[ -f "$closure_byc" ]]; then
      local ara
      ara="$(soviez_json_get "$(cat "$closure_byc")" automatic_rollback_allowed 2>/dev/null || echo true)"
      if [[ "$ara" == "False" || "$ara" == "false" ]]; then
        printf '{"eligible":false,"tier":"R3","code":"MIGRATION_ROLLBACK_WINDOW_ALREADY_CLOSED","reason":"already_closed"}\n'
        return 1
      fi
    fi
  fi
  wf_closed="$(soviez_migration_cutover_rollback_window_path "$op_id")"
  if [[ -f "$wf_closed" ]]; then
    local closed_flag
    closed_flag="$(soviez_json_get "$(cat "$wf_closed")" automatic_rollback_allowed 2>/dev/null || echo true)"
    if [[ "$closed_flag" == "False" || "$closed_flag" == "false" ]]; then
      printf '{"eligible":false,"tier":"R3","code":"MIGRATION_ROLLBACK_WINDOW_ALREADY_CLOSED","reason":"already_closed"}\n'
      return 1
    fi
  fi

  local wf window_expired=0
  wf="$(soviez_migration_cutover_rollback_window_path "$op_id")"
  if [[ -f "$wf" ]]; then
    local exp
    exp="$(soviez_json_get "$(cat "$wf")" expires_at)"
    soviez_migration_is_expired "$exp" && window_expired=1
  fi
  if [[ "$window_expired" -eq 1 ]]; then
    printf '{"eligible":false,"tier":"R3","code":"MIGRATION_ROLLBACK_WINDOW_EXPIRED","reason":"window_expired"}\n'
    return 1
  fi

  local to="source"
  [[ -n "$auth_id" ]] && to="$(soviez_json_get "$(soviez_migration_traffic_owner_get "$auth_id")" traffic_owner 2>/dev/null || echo source)"

  if [[ "$to" != "destination" ]]; then
    printf '{"eligible":true,"tier":"R0"}\n'
    return 0
  fi

  local elapsed=0
  if [[ -f "$wf" ]]; then
    local opened_epoch now_epoch
    opened_epoch="$(soviez_migration_iso_to_epoch "$(soviez_json_get "$(cat "$wf")" opened_at)" 2>/dev/null || echo 0)"
    now_epoch="$(soviez_migration_now_epoch)"
    elapsed=$((now_epoch - opened_epoch))
  fi
  if [[ "$elapsed" -ge "${SOVIEZ_MIG_P21_DUAL_CONTROL_AFTER_SECONDS}" ]]; then
    printf '{"eligible":true,"tier":"R2","dual_control_required":true}\n'
    return 0
  fi
  printf '{"eligible":true,"tier":"R1"}\n'
  return 0
}

# soviez_migration_rollback_run <pair-id> <op-id> <auth-id> <fqdn> [previous-dns-target] [dual-control-confirmed]
soviez_migration_rollback_run() {
  local pair_id="${1:-}" op_id="${2:-}" auth_id="${3:-}" fqdn="${4:-}" prev_target="${5:-}" dual_confirmed="${6:-0}"
  [[ -n "$op_id" && -n "$auth_id" ]] || soviez_migration_die MIGRATION_NOT_FOUND "op-id and authorization-id required"
  soviez_migration_cutover_paths_init
  soviez_migration_assert_phase21_cutover_allowed "$SOVIEZ_MIG_OP_IMMEDIATE_ROLLBACK"

  local elig erc
  set +e
  elig="$(soviez_migration_rollback_eligibility "$op_id" "$auth_id")"
  erc=$?
  set -e
  if [[ "$erc" -ne 0 ]]; then
    local code
    code="$(soviez_json_get "$elig" code)"
    soviez_migration_die "$code" "rollback not eligible: $(soviez_json_get "$elig" reason)"
  fi

  local tier
  tier="$(soviez_json_get "$elig" tier)"
  if [[ "$tier" == "R2" && "$dual_confirmed" != "1" ]]; then
    soviez_migration_die MIGRATION_ROLLBACK_NOT_ELIGIBLE "dual-control confirmation required after T0+15m (OD-24)"
  fi

  if [[ -n "$fqdn" && -n "$prev_target" ]]; then
    ( soviez_migration_p21_dns_rollback "$fqdn" "$prev_target" ) >/dev/null 2>&1 || true
  fi
  soviez_migration_p21_nginx_disable_production || true
  soviez_migration_stage_cutover_disable "$pair_id" >/dev/null || true
  soviez_migration_source_transition_to_rollback_origin "$auth_id" >/dev/null
  soviez_migration_traffic_owner_switch "$auth_id" source >/dev/null

  printf '{"status":"rolled_back","tier":"%s","traffic_owner":"source","migration_token_consumed":true,"token_restored":false}\n' "$tier"
}

# AR-04 split-brain / AR-01 health flapping automatic trigger evaluation.
# Returns 0 with a trigger payload when rollback is recommended/required.
soviez_migration_rollback_auto_check() {
  local auth_id="${1:-}"
  if [[ "${SOVIEZ_MIG_P21_SPLIT_BRAIN:-0}" == "1" ]]; then
    printf '{"trigger":"AR-04","action":"rollback_required","enforced":true}\n'
    return 0
  fi
  if [[ "${SOVIEZ_MIG_P21_HEALTH_FLAPPING:-0}" == "1" ]]; then
    if [[ "${SOVIEZ_MIG_P21_POST_WINDOW:-0}" == "1" ]]; then
      printf '{"trigger":"AR-01","action":"advisory_only"}\n'
    else
      printf '{"trigger":"AR-01","action":"suppressed_grace_period"}\n'
    fi
    return 0
  fi
  printf '{"trigger":"none"}\n'
  return 1
}

# --- end migration/rollback/engine.sh ---

# --- begin migration/cutover/engine.sh ---
# shellcheck shell=bash
# Phase 21 cutover orchestrator — parent operation state machine.
#
# Every mutating step is individually idempotent so retry/recover can safely
# re-run the whole sequence: DNS mutation overwrites the same record, TLS
# fixture issuance is skipped once cert files exist, nginx activation
# rewrites the same config, traffic_owner switch is a no-op once already at
# the target owner, and source_transition state changes short-circuit once
# already advanced.

soviez_migration_cutover_state_write() {
  local op_id="$1" state="$2" extra="${3:-}"
  [[ -n "$extra" ]] || extra="{}"
  local f
  f="$(soviez_migration_cutover_state_path "$op_id")"
  mkdir -p "$(dirname "$f")"
  SOVIEZ_OUT="$f" SOVIEZ_OP="$op_id" SOVIEZ_ST="$state" SOVIEZ_EXTRA="$extra" python3 - <<'PY'
import json, os
extra = json.loads(os.environ["SOVIEZ_EXTRA"])
existing = {}
try:
  existing = json.load(open(os.environ["SOVIEZ_OUT"]))
except Exception:
  existing = {}
doc = {
  "operation_id": os.environ["SOVIEZ_OP"],
  "operation_type": "migration_cutover",
  "current_state": os.environ["SOVIEZ_ST"],
}
existing.update(doc)
existing.update(extra)
open(os.environ["SOVIEZ_OUT"], "w").write(json.dumps(existing, separators=(",", ":")))
PY
  cat "$f"
}

soviez_migration_cutover_status() {
  local op_id="${1:-}"
  [[ -n "$op_id" ]] || soviez_migration_die MIGRATION_NOT_FOUND "operation-id required"
  soviez_migration_cutover_paths_init
  local f
  f="$(soviez_migration_cutover_state_path "$op_id")"
  [[ -f "$f" ]] || soviez_migration_die MIGRATION_NOT_FOUND "cutover operation not found"
  cat "$f"
}

soviez_migration_cutover_certification_banner() {
  cat <<'EOF'
TRAFFIC OWNER — DESTINATION
PRODUCTION DNS — CHANGED
SOURCE — MAINTENANCE (BUSINESS WRITES DENIED)
ROLLBACK WINDOW — OPEN
PHASE 22 READINESS — REPORTED
NO SOURCE PURGE
NO SOURCE ARCHIVE
NO SAAS PAYLOAD RELAY
MIGRATION TOKEN — CONSUMED EXACTLY ONCE (PHASE 20)
EOF
}

# soviez_migration_cutover_start <pair-id> [confirm]
soviez_migration_cutover_start() {
  local pair_id="${1:-}" confirm="${2:-0}"
  [[ -n "$pair_id" ]] || soviez_migration_die MIGRATION_PAIR_REQUIRED "pair-id required"
  [[ "$confirm" == "1" || "${SOVIEZ_CLI_YES:-0}" == "1" || "${SOVIEZ_MIG_ASSUME_YES:-0}" == "1" ]] || \
    soviez_migration_die MIGRATION_CUTOVER_CONFIRMATION_REQUIRED "cutover requires explicit confirm"

  # Security Gate S4 — quarantine must be PROMOTED for external migrations
  if declare -F soviez_q_migration_cutover_allowed >/dev/null 2>&1; then
    if ! soviez_q_migration_cutover_allowed; then
      soviez_migration_die MIGRATION_CUTOVER_CONFIRMATION_REQUIRED "S4 quarantine blocks cutover (token not consumed)"
    fi
  fi

  soviez_migration_cutover_paths_init

  # Exact lock: one active cutover per migration pair (portable; no flock binary).
  local lock_dir lock_file
  lock_dir="$SOVIEZ_MIG_CUTOVER_DIR/locks"
  mkdir -p "$lock_dir"
  lock_file="$lock_dir/pair-${pair_id}.lock"
  if ! SOVIEZ_LOCK="$lock_file" python3 - <<'PY'
import os, sys, time
path = os.environ["SOVIEZ_LOCK"]
# Exclusive create; stale locks older than 2h are stolen (crash recovery).
for _ in range(40):
  try:
    fd = os.open(path, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
    os.write(fd, str(os.getpid()).encode())
    os.close(fd)
    sys.exit(0)
  except FileExistsError:
    try:
      age = time.time() - os.path.getmtime(path)
      if age > 7200:
        os.unlink(path)
        continue
    except OSError:
      pass
    time.sleep(0.05)
sys.exit(1)
PY
  then
    soviez_migration_die MIGRATION_ACTIVE_OPERATION_CONFLICT "one active cutover per pair"
  fi
  # Ensure unlock on exit of this shell function path via trap scoped carefully
  trap 'rm -f "'"$lock_file"'"' RETURN

  # 1. Revalidate Phase 20 committed state (grace/activation/backup/ledger).
  local reval auth_id license_id
  reval="$(soviez_migration_p21_revalidate_phase20 "$pair_id")"
  auth_id="$(soviez_json_get "$reval" authorization_id)"
  license_id="$(soviez_json_get "$reval" license_id)"

  # Idempotent short-circuit: if traffic_owner already destination for this auth, return completed.
  if [[ -f "$(soviez_migration_traffic_owner_path "$auth_id")" ]]; then
    local cur_owner
    cur_owner="$(soviez_json_get "$(cat "$(soviez_migration_traffic_owner_path "$auth_id")")" traffic_owner 2>/dev/null || true)"
    if [[ "$cur_owner" == "destination" ]]; then
      local existing_op
      existing_op="$(soviez_json_get "$(cat "$(soviez_migration_traffic_owner_path "$auth_id")")" operation_id 2>/dev/null || true)"
      if [[ -n "$existing_op" && -f "$(soviez_migration_cutover_state_path "$existing_op")" ]]; then
        rm -f "$lock_file"
        trap - RETURN
        soviez_migration_cutover_certification_banner >&2 || true
        cat "$(soviez_migration_cutover_state_path "$existing_op")"
        return 0
      fi
    fi
  fi

  # 2. confirm already checked above.
  # 3. Canonical cutover flag — the ONLY way past the Phase 20/21 gates.
  export SOVIEZ_MIG_P21_CANONICAL_CUTOVER=1
  export SOVIEZ_MIG_P21_AUTH_ID="$auth_id"

  local fqdn="${SOVIEZ_MIG_P21_FQDN:-prod.example.test}"
  local dest_target="${SOVIEZ_MIG_P21_DEST_IP:-127.0.0.1}"
  local prev_target
  prev_target="$(soviez_migration_p21_dns_snapshot "$fqdn")"

  # 4. Create op state machine.
  local op_id
  op_id="$(soviez_migration_new_id cop)"
  soviez_migration_cutover_state_write "$op_id" "started" \
    "$(SOVIEZ_P="$pair_id" SOVIEZ_A="$auth_id" SOVIEZ_L="$license_id" SOVIEZ_F="$fqdn" SOVIEZ_PT="$prev_target" python3 -c '
import json, os
print(json.dumps({
  "pair_id": os.environ["SOVIEZ_P"],
  "authorization_id": os.environ["SOVIEZ_A"],
  "license_id": os.environ["SOVIEZ_L"],
  "fqdn": os.environ["SOVIEZ_F"],
  "previous_dns_target": os.environ["SOVIEZ_PT"],
}, separators=(",", ":")))
')" >/dev/null

  # 5. Final cutover sync (mandatory, bounded freeze).
  soviez_migration_cutover_state_write "$op_id" "final_cutover_sync" >/dev/null
  soviez_migration_final_cutover_sync_run "$pair_id" "$op_id" >/dev/null

  # 6. Source maintenance: grace -> freeze (maintenance page follows DNS confirm).
  soviez_migration_cutover_state_write "$op_id" "source_freeze" >/dev/null
  soviez_migration_source_transition_to_freeze "$auth_id" >/dev/null

  # 7. Destination route activate.
  soviez_migration_cutover_state_write "$op_id" "destination_route_activate" >/dev/null
  soviez_migration_p21_tls_prepare_fixture "$auth_id" "$fqdn" >/dev/null 2>&1 || true
  soviez_migration_destination_go_live_route_activate "$auth_id" "$fqdn" >/dev/null

  # 8. TLS validate (Production FQDN, hostname + expiry gate).
  soviez_migration_cutover_state_write "$op_id" "tls_validate" >/dev/null
  soviez_migration_p21_tls_validate "$auth_id" "$fqdn" >/dev/null

  # 9. DNS cutover — manual (attestation) or fixture provider.
  soviez_migration_cutover_state_write "$op_id" "dns_cutover" >/dev/null
  local dns_mode="${SOVIEZ_MIG_P21_DNS_MODE:-fixture}"
  if [[ "$dns_mode" == "manual" ]]; then
    soviez_migration_p21_dns_manual_instructions "$fqdn" "$dest_target" \
      > "$(soviez_migration_cutover_op_dir "$op_id")/dns_instructions.json"
    if [[ "${SOVIEZ_MIG_P21_DNS_CONFIRMED:-0}" != "1" ]]; then
      soviez_migration_die MIGRATION_DNS_CUTOVER_NOT_CONFIRMED "manual DNS change operator attestation required"
    fi
  fi
  soviez_migration_p21_dns_mutate "$fqdn" "$dest_target" >/dev/null

  # 10. Propagation observation (advisory unless required).
  soviez_migration_cutover_state_write "$op_id" "propagation_observe" >/dev/null
  soviez_migration_p21_propagation_observe "$fqdn" "$dest_target" \
    > "$(soviez_migration_cutover_op_dir "$op_id")/propagation.json"

  # Source now switches from freeze into signed maintenance now that DNS moved.
  soviez_migration_source_transition_to_maintenance "$auth_id" "$fqdn" >/dev/null

  # 11. Public health / smoke suite (mandatory tier).
  soviez_migration_cutover_state_write "$op_id" "post_cutover_validate" >/dev/null
  soviez_migration_destination_go_live_health "$auth_id" \
    > "$(soviez_migration_cutover_op_dir "$op_id")/health.json"
  soviez_migration_destination_go_live_synthetic_write "$auth_id" >/dev/null

  # 12. Commit boundary — traffic_owner flip (idempotent, exactly-once semantics).
  soviez_migration_cutover_state_write "$op_id" "traffic_owner_switch" >/dev/null
  soviez_migration_traffic_owner_switch "$auth_id" destination "$op_id" >/dev/null

  # 13. Restrict source — report the enforced state (deny_writes is the
  # standalone probe other callers use to prove writes are actually
  # rejected; calling it here would always die by design, since we are
  # deliberately in cutover_freeze/cutover_maintenance at this point).
  soviez_migration_source_transition_get "$auth_id" \
    > "$(soviez_migration_cutover_op_dir "$op_id")/source_restricted.json"

  # 14. Integrations — incremental; payments never before health/attestation.
  soviez_migration_cutover_state_write "$op_id" "integration_activate" >/dev/null
  soviez_migration_destination_go_live_integrations "$auth_id" mail >/dev/null
  soviez_migration_destination_go_live_integrations "$auth_id" webhooks >/dev/null
  soviez_migration_destination_go_live_integrations "$auth_id" cron >/dev/null
  if [[ "${SOVIEZ_MIG_P21_ACTIVATE_PAYMENTS:-0}" == "1" ]]; then
    soviez_migration_destination_go_live_integrations "$auth_id" payments >/dev/null
  fi

  # 15. Open rollback window.
  soviez_migration_cutover_state_write "$op_id" "rollback_window_open" >/dev/null
  local window="${SOVIEZ_MIG_P21_ROLLBACK_WINDOW_SECONDS:-1800}"
  SOVIEZ_OUT="$(soviez_migration_cutover_rollback_window_path "$op_id")" SOVIEZ_W="$window" python3 - <<'PY'
import json, os, datetime
opened = datetime.datetime.utcnow()
doc = {
  "opened_at": opened.strftime("%Y-%m-%dT%H:%M:%SZ"),
  "expires_at": (opened + datetime.timedelta(seconds=int(os.environ["SOVIEZ_W"]))).strftime("%Y-%m-%dT%H:%M:%SZ"),
  "window_seconds": int(os.environ["SOVIEZ_W"]),
}
open(os.environ["SOVIEZ_OUT"], "w").write(json.dumps(doc, separators=(",", ":")))
PY

  # 16. Stage cutover if Stages were selected (skips cleanly otherwise).
  soviez_migration_cutover_state_write "$op_id" "stage_cutover" >/dev/null
  soviez_migration_stage_cutover_run "$pair_id" > "$(soviez_migration_cutover_op_dir "$op_id")/stage_cutover.json"

  # 17. Phase 22 readiness report (post-cutover; never archives/purges).
  soviez_migration_cutover_state_write "$op_id" "phase22_readiness" >/dev/null
  soviez_migration_phase22_readiness "$auth_id" > "$(soviez_migration_cutover_op_dir "$op_id")/phase22_readiness.json"

  soviez_migration_cutover_state_write "$op_id" "cutover_complete" \
    '{"traffic_owner":"destination","production_dns_changed":true,"traffic_cutover_started":true,"phase22_allowed":false}' \
    >/dev/null

  soviez_migration_cutover_certification_banner >&2 || true
  soviez_migration_cutover_status "$op_id"
}

soviez_migration_cutover_show() {
  soviez_migration_cutover_plan_show "${1:-}"
}

soviez_migration_cutover_recover() {
  local op_id="${1:-}"
  [[ -n "$op_id" ]] || soviez_migration_die MIGRATION_RECOVERY_REQUIRED "operation-id required"
  soviez_migration_cutover_paths_init
  local f
  f="$(soviez_migration_cutover_state_path "$op_id")"
  [[ -f "$f" ]] || soviez_migration_die MIGRATION_RECOVERY_REQUIRED "cutover operation state missing"
  local fz
  fz="$(soviez_migration_cutover_freeze_path "$op_id")"
  if [[ -f "$fz" ]]; then
    local released
    released="$(soviez_json_get "$(cat "$fz")" released)"
    if [[ "$released" != "true" && "$released" != "True" ]]; then
      local expires
      expires="$(soviez_json_get "$(cat "$fz")" expires_at)"
      if soviez_migration_is_expired "$expires"; then
        soviez_migration_cutover_freeze_release "$op_id" "recover_timeout" >/dev/null
      fi
    fi
  fi
  cat "$f"
}

# Retry re-runs the full (idempotent) sequence for the same pair; every step
# either no-ops when already applied or continues from where it left off.
soviez_migration_cutover_retry() {
  local op_id="${1:-}"
  [[ -n "$op_id" ]] || soviez_migration_die MIGRATION_NOT_FOUND "operation-id required"
  local st pair_id
  st="$(soviez_migration_cutover_status "$op_id")"
  pair_id="$(soviez_json_get "$st" pair_id)"
  [[ -n "$pair_id" ]] || soviez_migration_die MIGRATION_NOT_FOUND "cutover operation missing pair_id"
  soviez_migration_cutover_start "$pair_id" 1
}

soviez_migration_cutover_dns_show() {
  local op_id="${1:-}"
  [[ -n "$op_id" ]] || soviez_migration_die MIGRATION_DNS_RECORD_NOT_FOUND "operation-id required"
  soviez_migration_cutover_paths_init
  local f
  f="$(soviez_migration_cutover_op_dir "$op_id")/dns_instructions.json"
  [[ -f "$f" ]] || soviez_migration_die MIGRATION_DNS_RECORD_NOT_FOUND "dns instructions not found for op"
  cat "$f"
}

soviez_migration_cutover_dns_try_again() {
  local op_id="${1:-}"
  [[ -n "$op_id" ]] || soviez_migration_die MIGRATION_DNS_RECORD_NOT_FOUND "operation-id required"
  export SOVIEZ_MIG_P21_DNS_CONFIRMED=1
  soviez_migration_cutover_retry "$op_id"
}

